    while Exists (Select 1 From Sys.indexes Where Name = @IndexName)
	begin
      Set @NumSeqIdx = @NumSeqIdx + 1
      SET @IndexName = 'IX_PDVIT_'+dbo.FN_FormataInteiro(@NumSeqIdx,3)
	end

    Set @SqlCmd = 'CREATE INDEX ['+@IndexName+'] ON [dbo].[PDVIT] ([Cod_Estabe],[Cod_Pedido],[Qtd_Pedido]) '+
	              'INCLUDE ([Flg_BlqInfPar],[C_PrcTotal],[Vlr_RepIcms],[Desconto],[Qtd_Bonificacao],[Per_Desconto],[Tip_BasRnt]) '

    EXECUTE sp_executesql @SqlCmd
  end


/*
  Versao 21.04 / Trunk
  Setembro de 2023
  Tabela: FS_F100: Armazena as informações Registro F100: Demais Documentos e Operações Geradoras de Contribuição e Créditos
*/

IF NOT EXISTS (SELECT * FROM dbo.sysobjects WHERE id = object_id(N'dbo.FS_F100') AND OBJECTPROPERTY(id, N'IsUserTable') = 1)

    CREATE TABLE dbo.FS_F100 (
		Id integer IDENTITY(1,1) PRIMARY KEY,
		Cod_Estabe integer NOT NULL,
		Tip_Regist integer NOT NULL,        			-- 0 - Entrada | 1 - Saída		
		Num_CnpjCpf varchar(14) NOT NULL,				-- CPF/CNPJ Participante
		Cod_Produt integer NULL,		    			-- Produto da Operação - (campo 02 do Registro 0200)
		Dat_Emissa datetime NOT NULL,					-- Data Emissão da Operação
		Vlr_Operac numeric(18,4) NULL default 0, 		-- Valor da Operação
		Cod_NatBasCre char(2) NULL,						-- Código da Base de Cálculo dos Créditos, conforme a tabela indicada no item 4.3.7
		Cod_OriCred integer NOT NULL,					-- 0 – Operação no Mercado Interno | 1 – Operação de Importação
		CST_Pis char(2) NULL,							-- Código da Situação Tributária Pis
		Vlr_BasPis numeric(18,4) NULL default 0,
		Alq_Pis numeric(18,4) NULL default 0,
		Vlr_Pis numeric(18,4) NULL default 0,
		CST_Cofins char(2) NULL,						-- Código da Situação Tributária Cofins		
		Vlr_BasCof numeric(18,4) NULL default 0,
		Alq_Cof numeric(18,4) NULL default 0,
		Vlr_Cof numeric(18,4) NULL default 0,
		Cod_CtaCtb varchar(100) NULL,					-- Código da conta analítica contábil debitada/creditada - Cadastro Infarma
		Cod_CntRes varchar(100) NULL,					-- Código do Centro de Resultados - Cadastro Infarma
		Descricao varchar(100) NULL,						-- Descrição do Documento/Operação
		Dat_Importa datetime NULL,						-- Data Importação da Operação
		Transacao datetime NULL,						
		Usuario varchar(15) NULL
    )

GO

