CREATE VIEW [dbo].[V_PRODU] AS

Select	Cod_Produto = p.Codigo, 
        Linha = cl.Descricao,
		p.Descricao, 
		Fabricante = p.Cod_Fabricante, 
		Controlado = Case 
		               When (p.Ctrl_Venda = 'C') or (p.Ctrl_Venda = 'E') or (p.Ctrl_Venda = 'P') Then 1 
		               Else 0 
		             End,
		p.Cod_Classif, 
        p.Cod_GrpPrc,
		x.Cod_ClaTri,
		Des_Generica = IsNull(p.Des_NomGen,'') +' '+ IsNull(p.Des_FormaFarmac,'') +' '+ IsNull(Convert(VarChar,p.Qtd_UndVen),'') +' '+ IsNull(p.Des_UndVen,''),
		Des_Comercial = IsNull(p.Des_PrdRef,''), 
		
		Flg_DescGlobal = IsNull(p.Flg_PolComercMax,0), 
		Flg_PrzGlobal = Case
                          When IsNull(p.Flg_PolComercMax,0) = 1 Then IsNull(p.Flg_PrzComercMax,0) 
                          Else 0 
                        End, 
        Cod_Barra = IsNull(p.Cod_EAN,''),
        Caixa_Fechada = IsNull(p.Qtd_Embalagem,0),
		p.Unidade_Venda,
		Preco_Venda = x.Prc_Venda,		
		x.Cod_OriMer, --p.Ctrl_Origem,
		Cod_NCM = p.Cod_ClaFis,
		p.Tip_LisPis,
		p.Sta_AbcValFat,
		p.Sta_AbcUniVen,
		p.Cod_CEST,
        Principio = (Isnull(s1.Descricao, '') + Case 
		                                          When Isnull(p.Cod_SubBas, 0) > 0 and Isnull(p.Cod_SubBas2, 0) > 0 Then '+' + Isnull(s2.Descricao, '') 
												  Else Isnull(s2.Descricao, '') 
												end +
                                                Case 
												  When (Isnull(p.Cod_SubBas, 0) > 0 or Isnull(p.Cod_SubBas2, 0) > 0) and Isnull(p.Cod_SubBas3, 0) > 0 Then '+' + Isnull(s3.Descricao, '') 
												  Else Isnull(s3.Descricao, '') 
												End),
        Dun14 = Isnull(p.Cod_EanEmbCmp, ''),
		p.Tipo,
		Prc_Fabric12, 
        Prc_MaxCon12, 
		Prc_Fabric17, 
		Prc_MaxCon17, 
		Prc_Fabric175, 
		Prc_MaxCon175, 
		Prc_Fabric18, 
		Prc_MaxCon18,
		Prc_Fabric19, 
		Prc_MaxCon19,
		Prc_Fabric195, 
		Prc_MaxCon195,
		Prc_Fabric20,
		Prc_MaxCon20,
		Prc_Fabric205,
		Prc_MaxCon205,
		Prc_Fabric21,
		Prc_MaxCon21,
		Prc_Fabric22,
		Prc_MaxCon22,
		Ctrl_Preco,
        SubLinha = cl2.Descricao,  -- Integração Repifarma DMD-8229/8330
		Descricao_Item_1 = p.Descricao,  -- Integração Repifarma DMD-8229/8330
		Descricao_Item_2 = p.Descri  -- Integração Repifarma DMD-8229/8330
  From  PRODU p
        Inner Join PRXES x On x.Cod_Estabe = (Select Min(Cod_Estabe) as CodEstabe From ESTAB) 
                              And x.Cod_Produt = p.Codigo
        Left Join SBBAS s1 on p.Cod_Subbas = s1.codigo
        Left Join SBBAS s2 on p.Cod_Subbas2 = s2.codigo
        Left Join SBBAS s3 on p.Cod_Subbas3 = s3.codigo
		Left Join CLASS cl ON cl.Codigo = SUBSTRING(p.Cod_Classif, 1, 2)
		Left Join CLASS cl2 ON cl.Codigo = SUBSTRING(p.Cod_Classif, 1, 4)
 Where  p.Flag_ImprClassif1 <> 'N' 

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW dbo.V_CLIEN

AS

Select distinct
       c.Pessoa,
       Cod_Cliente = c.Codigo,
       Fantasia = Case 
                    When c.Fantasia is not Null Then c.Fantasia 
                    Else c.Razao_Social 
                  End,
       c.Cgc_Cpf,
       c.Cgf,
       c.Razao_Social,
       Endereco = Case
                    When (IsNull(c.Numero,'') <> '') and (IsNull(c.Complemento,'') <> '') then
                      Rtrim(Ltrim(c.Endereco))+', '+Rtrim(Ltrim(c.Numero))+', '+Rtrim(Ltrim(c.Complemento))
                    When (IsNull(c.Numero,'') <> '') then
                      Rtrim(Ltrim(c.Endereco))+', '+Rtrim(Ltrim(c.Numero))
                    When (IsNull(c.Complemento,'') <> '') then
                      Rtrim(Ltrim(c.Endereco))+', '+Rtrim(Ltrim(c.Complemento))
                    Else Rtrim(Ltrim(c.Endereco))
                  End,
       c.Numero, 
       c.Complemento, 
       Des_Bairro = IsNull(b.Descricao,''),
       Des_Cidade = IsNull(d.Descricao,''),
       c.Cod_Estado,
       c.Cep,
       c.Cod_DDD_1,
       Telefone = IsNull(c.Fone1,''),
       c.Cod_CliPag,
       Licenca_Saude = IsNull(c.Licenca_Saude,''),    
       Val_LicSau = Case 
                      When Year(c.Val_LicSau) > 1910 Then Convert(VarChar,c.Val_LicSau,103) 
                      Else '' 
                    End,
       Num_AlvFun = IsNull(c.Num_AlvFun,''),
       Val_AlvFun = Case 
                      When Year(c.Val_AlvFun) > 1910 Then Convert(VarChar,c.Val_AlvFun,103) 
                      Else '' 
                    End,
       Num_CRF = IsNull(c.Num_CerReg,''),                    
       Val_NumCRF = Case 
                      When Year(c.Val_CerReg) > 1910 Then Convert(VarChar,c.Val_CerReg,103) 
                      Else '' 
                    End,
       Num_Anvisa = IsNull(c.Num_Anvisa,''),                     
       Val_Anvisa = Case 
                      When Year(c.Val_Anvisa) > 1910 Then Convert(VarChar,c.Val_Anvisa,103) 
                      Else '' 
                    End,                
--       c.Cod_RegTri,

     Id_PolCOm = IsNull(c.Id_PolCom,0),
     Flg_BloqPolCom = IsNull(c.Flg_BlqPrm,0),
       c.Cod_TabPrc,
     Email = Upper(Case When dbo.FN_ValidaEmail(email) = 1 Then Email Else '' End),
       cx.Cod_Vendedor,
       c.Cod_DDD_2, -- Integração Repifarma DMD-8229/8330
       Telefone2 = IsNull(c.Fone2,'') -- Integração Repifarma DMD-8229/8330
From CLIEN c 
     Inner Join (Select cl.Codigo, es.Cod_Vendedor
                 From CLIEN cl
                      Inner Join ENXES es on cl.Cgc_Cpf = es.Num_CgcCpf and cl.Codigo = es.Cod_Client
                      Inner Join VENDE ve on es.Cod_Vendedor = ve.Codigo
                 Where ve.Flg_Export = 1
                 Union 
                 Select cl2.Codigo, c2.Cod_Vended
                 From CLXVE c2 
                      Inner Join CLIEN cl2 ON (c2.Cod_Client = cl2.Codigo) 
                      Inner Join VENDE ve2 ON (c2.Cod_Vended = ve2.Codigo) 
                 Where ve2.Flg_Export = 1) cx on c.Codigo = cx.Codigo
     Left Join CIDAD d on ((c.Cod_Estado = d.Cod_Estado) And (c.Cod_Cidade = d.Codigo)) 
     Left Join BAIRR b On ((c.Cod_Estado = b.Cod_Estado) and (c.Cod_Cidade = b.Cod_Cidade) and (b.Codigo = c.Cod_Bairro))
GO


SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_GeraMensagensNF]
(
  @PCodEstabe int,
  @PNumNot int,
  @PSerNot varchar(3),
  @PTipNot char(1)
)

AS

SET NOCOUNT ON

if ((@PTipNot = 'E') and
    (not Exists(Select 1 From NFECB 
                 Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumNot))) or
   ((@PTipNot = 'S') and
    (not Exists(Select 1 From NFSCB 
                 Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot)))
  Return
else
BEGIN
BEGIN TRANSACTION

Declare @it_CodPrd int          
      , @it_CodLot varchar(20)
      , @it_SeqIte int
      , @rg_IdMensag int
      , @mg_FlgInfCpl bit = 0
      , @mg_FlgobsCont bit = 0
      , @mg_FlginfAdFisco bit = 0
      , @mg_FlgobsFisco bit = 0
      , @Chave int
      , @WNumSeqMensag int
      , @PObserv varchar(1600)

      , @NomFantas varchar(80) = ''
      , @TipNot varchar(1)
      , @ObsNf1 varchar(1600) = ''
      , @ObsNf2 varchar(200) = ''
      , @ObsNf3 varchar(200) = ''
      , @ListaTipPor344 varchar(100)

    Declare @TabObs Table(
      Chave Int Identity(1,1) PRIMARY KEY
    , Tip_Not varchar(1)
    , Des_Observ varchar(1600)
    , Flg_infCpl bit
    , Flg_obsCont bit
    , Flg_infAdFisco bit
    , Flg_obsFisco bit
    )


-- mensagens em NFSCB/NFECB
if @PTipNot = 'S'
  begin
    Delete
      From NSCOB 
     Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot

    Delete
      From NSIOB 
       Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot
  end
else
  begin
    Delete
      From NECOB 
     Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumNot

    Delete
      From NEIOB 
     Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumNot
  end

-- Nome Fantasia do destinatario da NF ----
Set @NomFantas = ''
Set @PObserv = ''
Set @mg_FlgInfCpl = 1
Set @mg_FlgobsCont = 0
Set @mg_FlginfAdFisco = 0
Set @mg_FlgobsFisco = 0

if @PTipNot = 'S' --SAIDAS
  begin
    Select @NomFantas = (Select dbo.FN_NomeFantasia(IsNull(Cod_Cliente,0), IsNull(Cod_Fornecedor,0), 0))
      From NFSCB
     Where Cod_Estabe = @PCodEstabe
       And Ser_Nota = @PSerNot
       And Num_Nota = @PNumNot

  if IsNull(@NomFantas,'') <> '' 
      Set @PObserv = 'FANTASIA DESTINATARIO: '+@NomFantas

    if (@PObserv <> '') and
       not exists(Select 1 From NSCOB 
                   Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot
                     And Des_Observ = @PObserv)
      begin
        Set @WNumSeqMensag = IsNull((Select max(Num_SeqMensag) 
                                       From NSCOB 
                                      Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot),0) + 1

        Insert Into NSCOB (Cod_Estabe, Ser_Nota, Num_Nota, Num_SeqMensag, Id_Mensag, Des_Observ
                        ,  Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
                   Values (@PCodEstabe, @PSerNot, @PNumNot, @WNumSeqMensag, 0, @PObserv
                        ,  @mg_FlgInfCpl, @mg_FlgobsCont, @mg_FlginfAdFisco, @mg_FlgobsFisco)
      end
  end
else
  begin
    Select @NomFantas = (Select dbo.FN_NomeFantasia(IsNull(Cod_EmiCliente,0), IsNull(Cod_EmiFornec,0), ISNull(Cod_EmiTransp,0)))
      From NFECB
     Where Cod_Estabe = @PCodEstabe
       And Protocolo = @PNumNot

  if IsNull(@NomFantas,'') <> '' 
      Set @PObserv = 'FANTASIA DESTINATARIO: '+@NomFantas

    if (@PObserv <> '') and
       not exists(Select 1 From NECOB 
                   Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumNot
                     And Des_Observ = @PObserv)
      begin
        Set @WNumSeqMensag = IsNull((Select max(Num_SeqMensag) 
                                       From NECOB 
                                      Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumNot),0) + 1

        Insert Into NECOB (Cod_Estabe, Protocolo, Num_SeqMensag, Id_Mensag, Des_Observ
                        ,  Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
                   Values (@PCodEstabe, @PNumNot, @WNumSeqMensag, 0, @PObserv
                        ,  @mg_FlgInfCpl, @mg_FlgobsCont, @mg_FlginfAdFisco, @mg_FlgobsFisco)
      end
  end
-----------------------------------------

-- Observações na UF
Set @ObsNf1 = ''
Set @ObsNf2 = ''
Set @ObsNf3 = ''
Set @mg_FlgInfCpl = 1
Set @mg_FlgobsCont = 0
Set @mg_FlginfAdFisco = 0
Set @mg_FlgobsFisco = 0

if Exists(Select 1
            From ESTAD uf
                 Inner Join ESTAB es on uf.Codigo = es.Des_Estado
           Where Cod_Estabe = @PCodEstabe
             And ( (IsNull(uf.ObservacaoNF,'') <> '') or
                   (IsNull(uf.Obs2_NF,'') <> '') or 
                   (IsNull(uf.Obs3_NF,'') <> '') ) )
  begin
    Select @ObsNf1 = IsNull(uf.ObservacaoNF,'')
         , @ObsNf2 = IsNull(uf.Obs2_NF,'')
         , @ObsNf3 = IsNull(uf.Obs3_NF,'')
      From ESTAD uf
           Inner Join ESTAB es on uf.Codigo = es.Des_Estado
    Where Cod_Estabe = @PCodEstabe

    if @PTipNot = 'S' --SAIDAS
      begin
        Set @PObserv = ''
        if IsNull(@ObsNf1,'') <> '' 
          Set @PObserv = @ObsNf1
        if (@PObserv <> '') and
           not exists(Select 1 From NSCOB 
                       Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot
                         And Des_Observ = @PObserv)
          begin
            Set @WNumSeqMensag = IsNull((Select max(Num_SeqMensag) 
                                           From NSCOB 
                                          Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot),0) + 1

            Insert Into NSCOB (Cod_Estabe, Ser_Nota, Num_Nota, Num_SeqMensag, Id_Mensag, Des_Observ
                            ,  Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
                       Values (@PCodEstabe, @PSerNot, @PNumNot, @WNumSeqMensag, 0, @PObserv
                            ,  @mg_FlgInfCpl, @mg_FlgobsCont, @mg_FlginfAdFisco, @mg_FlgobsFisco)
          end

        Set @PObserv = ''
        if IsNull(@ObsNf2,'') <> '' 
          Set @PObserv = @ObsNf2
        if (@PObserv <> '') and
           not exists(Select 1 From NSCOB 
                       Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot
                         And Des_Observ = @PObserv)
          begin
            Set @WNumSeqMensag = IsNull((Select max(Num_SeqMensag) 
                                           From NSCOB 
                                          Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot),0) + 1

            Insert Into NSCOB (Cod_Estabe, Ser_Nota, Num_Nota, Num_SeqMensag, Id_Mensag, Des_Observ
                            ,  Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
                       Values (@PCodEstabe, @PSerNot, @PNumNot, @WNumSeqMensag, 0, @PObserv
                            ,  @mg_FlgInfCpl, @mg_FlgobsCont, @mg_FlginfAdFisco, @mg_FlgobsFisco)
          end

        Set @PObserv = ''
        if IsNull(@ObsNf3,'') <> '' 
          Set @PObserv = @ObsNf3
        if (@PObserv <> '') and
           not exists(Select 1 From NSCOB 
                       Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot
                         And Des_Observ = @PObserv)
          begin
            Set @WNumSeqMensag = IsNull((Select max(Num_SeqMensag) 
                                           From NSCOB 
                                          Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot),0) + 1

            Insert Into NSCOB (Cod_Estabe, Ser_Nota, Num_Nota, Num_SeqMensag, Id_Mensag, Des_Observ
                            ,  Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
                       Values (@PCodEstabe, @PSerNot, @PNumNot, @WNumSeqMensag, 0, @PObserv
                            ,  @mg_FlgInfCpl, @mg_FlgobsCont, @mg_FlginfAdFisco, @mg_FlgobsFisco)
          end
      end -- if @PTipNot = 'S' --SAIDAS
    else -- entrada
      begin
        Set @PObserv = ''
        if IsNull(@ObsNf1,'') <> '' 
          Set @PObserv = @ObsNf1
        if (@PObserv <> '') and
           not exists(Select 1 From NECOB 
                       Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumNot
                         And Des_Observ = @PObserv)
          begin
            Set @WNumSeqMensag = IsNull((Select max(Num_SeqMensag) 
                                           From NECOB 
                                          Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumNot),0) + 1

            Insert Into NECOB (Cod_Estabe, Protocolo, Num_SeqMensag, Id_Mensag, Des_Observ
                            ,  Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
                       Values (@PCodEstabe, @PNumNot, @WNumSeqMensag, 0, @PObserv
                            ,  @mg_FlgInfCpl, @mg_FlgobsCont, @mg_FlginfAdFisco, @mg_FlgobsFisco)
          end

        Set @PObserv = ''
        if IsNull(@ObsNf2,'') <> '' 
          Set @PObserv = @ObsNf2
        if (@PObserv <> '') and
           not exists(Select 1 From NECOB 
                       Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumNot
                         And Des_Observ = @PObserv)
          begin
            Set @WNumSeqMensag = IsNull((Select max(Num_SeqMensag) 
                                           From NECOB 
                                          Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumNot),0) + 1

            Insert Into NECOB (Cod_Estabe, Protocolo, Num_SeqMensag, Id_Mensag, Des_Observ
                            ,  Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
                       Values (@PCodEstabe, @PNumNot, @WNumSeqMensag, 0, @PObserv
                            ,  @mg_FlgInfCpl, @mg_FlgobsCont, @mg_FlginfAdFisco, @mg_FlgobsFisco)
          end

        Set @PObserv = ''
        if IsNull(@ObsNf3,'') <> '' 
          Set @PObserv = @ObsNf3
        if (@PObserv <> '') and
           not exists(Select 1 From NECOB 
                       Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumNot
                         And Des_Observ = @PObserv)
          begin
            Set @WNumSeqMensag = IsNull((Select max(Num_SeqMensag) 
                                           From NECOB 
                                          Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumNot),0) + 1

            Insert Into NECOB (Cod_Estabe, Protocolo, Num_SeqMensag, Id_Mensag, Des_Observ
                            ,  Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
                       Values (@PCodEstabe, @PNumNot, @WNumSeqMensag, 0, @PObserv
                            ,  @mg_FlgInfCpl, @mg_FlgobsCont, @mg_FlginfAdFisco, @mg_FlgobsFisco)
          end
      end -- else if @PTipNot = 'S' --SAIDAS
  end  -- if Exists(Select 1
-----------------------------------------------------------------------------------------

-- observacao no Ag.Cobrador
Set @ObsNf1 = ''
Set @mg_FlgInfCpl = 1
Set @mg_FlgobsCont = 0
Set @mg_FlginfAdFisco = 0
Set @mg_FlgobsFisco = 0

if @PTipNot = 'S' --SAIDAS
  begin
    if Exists(Select 1
                From NFSCB cb
                     inner join AGCOB ag on cb.Cod_AGente = ag.Codigo
               Where Cod_Estabe = @PCodEstabe
                 And Ser_Nota = @PSerNot
                 And Num_Nota = @PNumNot
                 And IsNull(ag.Obs1_Nf,'') <> '')
      begin
        Select @ObsNf1 = Ltrim(Rtrim(IsNull(ag.Obs1_Nf,'')))
          From NFSCB cb
               inner join AGCOB ag on cb.Cod_AGente = ag.Codigo
         Where Cod_Estabe = @PCodEstabe
           And Ser_Nota = @PSerNot
           And Num_Nota = @PNumNot
           And IsNull(ag.Obs1_Nf,'') <> ''

        Set @PObserv = ''
        if IsNull(@ObsNf1,'') <> '' 
          Set @PObserv = @ObsNf1
        if (@PObserv <> '') and
           not exists(Select 1 From NSCOB 
                       Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot
                         And Des_Observ = @PObserv)
          begin
            Set @WNumSeqMensag = IsNull((Select max(Num_SeqMensag) 
                                           From NSCOB 
                                          Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot),0) + 1

            Insert Into NSCOB (Cod_Estabe, Ser_Nota, Num_Nota, Num_SeqMensag, Id_Mensag, Des_Observ
                            ,  Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
                       Values (@PCodEstabe, @PSerNot, @PNumNot, @WNumSeqMensag, 0, @PObserv
                            ,  @mg_FlgInfCpl, @mg_FlgobsCont, @mg_FlginfAdFisco, @mg_FlgobsFisco)
          end
      end  -- if Exists(Select 1
  end  -- if @PTipNot = 'S' --SAIDAS
-----------------------------------------------------------------------------------------

-- CNAE do cliente
Set @ObsNf1 = ''
Set @mg_FlgInfCpl = 1
Set @mg_FlgobsCont = 0
Set @mg_FlginfAdFisco = 0
Set @mg_FlgobsFisco = 0

if (@PTipNot = 'S') and
   Exists(Select 1
           From FS_PARAM 
          Where Cod_Estabe = @PCodEstabe
            And Cod_Param = 'NFE_CFG_DNF_IMPCNAE'
            And Val_Param ='1') And
   Exists( Select 1
             From NFSCB cb 
                  Inner Join CLIEN cl on cb.Cod_Cliente = cl.Codigo
            Where cb.Cod_Estabe = @PCodEstabe
              And cb.Ser_Nota = @PSerNot
              And cb.Num_Nota = @PNumNot
              And IsNull(cl.Cod_CNAE,'') <> '')
  begin
    Select @ObsNf1 = cl.Cod_CNAE
      From NFSCB cb 
           Inner Join CLIEN cl on cb.Cod_Cliente = cl.Codigo
     Where cb.Cod_Estabe = @PCodEstabe
       And cb.Ser_Nota = @PSerNot
       And cb.Num_Nota = @PNumNot
       And IsNull(cl.Cod_CNAE,'') <> ''

    Set @PObserv = ''
    if IsNull(@ObsNf1,'') <> '' 
      Set @PObserv = @ObsNf1
    if (@PObserv <> '') and
       not exists(Select 1 From NSCOB 
                   Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot
                     And Des_Observ = @PObserv)
      begin
        Set @WNumSeqMensag = IsNull((Select max(Num_SeqMensag) 
                                       From NSCOB 
                                      Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot),0) + 1

        Insert Into NSCOB (Cod_Estabe, Ser_Nota, Num_Nota, Num_SeqMensag, Id_Mensag, Des_Observ
                        ,  Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
                   Values (@PCodEstabe, @PSerNot, @PNumNot, @WNumSeqMensag, 0, @PObserv
                            ,  @mg_FlgInfCpl, @mg_FlgobsCont, @mg_FlginfAdFisco, @mg_FlgobsFisco)
      end
  end
--------------------------------------

-- CLTRI: classificação tributária
Set @ObsNf1 = ''
Set @mg_FlgInfCpl = 1
Set @mg_FlgobsCont = 0
Set @mg_FlginfAdFisco = 0
Set @mg_FlgobsFisco = 0

if Exists(Select 1
            From NFSIT it 
                 Inner Join NFSCB cb on (it.Cod_Estabe = cb.Cod_Estabe And it.Ser_Nota = cb.Ser_Nota And it.Num_Nota = cb.Num_Nota) 
                 Inner Join CLTRI ct on (it.Cod_ClaTri = ct.Cod_ClaTri)
           Where it.Cod_Estabe = @PCodEstabe
             And it.Ser_Nota = @PSerNot
             And it.Num_Nota = @PNumNot
             And IsNull(ct.Obs_FiscalSai,'') <> '' )
  begin
    Delete From @TabObs

    Insert Into @TabObs (Tip_Not, Des_Observ, Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
      Select Distinct @PTipNot, (IsNull(ct.Obs_FiscalSai,'')), 1, 0, 0, 0
        From NFSIT it 
             Inner Join NFSCB cb on (it.Cod_Estabe = cb.Cod_Estabe And it.Ser_Nota = cb.Ser_Nota And it.Num_Nota = cb.Num_Nota) 
             Inner Join CLTRI ct on (it.Cod_ClaTri = ct.Cod_ClaTri)
       Where it.Cod_Estabe = @PCodEstabe
         And it.Ser_Nota = @PSerNot
         And it.Num_Nota = @PNumNot
         And IsNull(ct.Obs_FiscalSai,'') <> '' 

    While Exists(Select 1 From @TabObs)
      begin
        Select top 1
               @Chave = Chave
             , @ObsNf1 = Des_Observ
             , @mg_FlgInfCpl = Flg_InfCpl
             , @mg_FlgobsCont = Flg_obsCont
             , @mg_FlgInfAdFisco = Flg_InfAdFisco
             , @mg_FlgobsFisco = Flg_obsFisco
          From @TabObs
         Order by Chave

        Set @PObserv = ''
        if IsNull(@ObsNf1,'') <> '' 
          Set @PObserv = @ObsNf1
        if (@PObserv <> '') and
           not exists(Select 1 From NSCOB 
                       Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot
                         And Des_Observ = @PObserv)
          begin
            Set @WNumSeqMensag = IsNull((Select max(Num_SeqMensag) 
                                           From NSCOB 
                                          Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot),0) + 1

            Insert Into NSCOB (Cod_Estabe, Ser_Nota, Num_Nota, Num_SeqMensag, Id_Mensag, Des_Observ
                            ,  Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
                       Values (@PCodEstabe, @PSerNot, @PNumNot, @WNumSeqMensag, 0, @PObserv
                            ,  @mg_FlgInfCpl, @mg_FlgobsCont, @mg_FlginfAdFisco, @mg_FlgobsFisco)
          end

        Delete From @TabObs Where Chave = @Chave
      end
  end
------------

-- RGTRI
if exists(Select 1
            From NFSCB cb
                 Inner Join RGTRI rg on cb.Cod_RegTri = rg.Cod_RegTri
           Where cb.Cod_Estabe = @PCodEstabe
             And Ser_Nota = @PSerNot
             And Num_Nota = @PNumNot
             And IsNull(rg.Id_MensagReg,0) > 0 )
  begin
    Select @rg_IdMensag = IsNull(rg.Id_MensagReg,0)
         , @mg_FlgInfCpl = IsNull(mg.Flg_InfCpl,0)
         , @mg_FlgobsCont = IsNull(mg.Flg_obsCont,0)
         , @mg_FlginfAdFisco = IsNull(mg.Flg_infAdFisco,0)
         , @mg_FlgobsFisco = IsNull(mg.Flg_obsFisco,0)

      From NFSCB cb
           Inner Join RGTRI rg on cb.Cod_RegTri = rg.Cod_RegTri
           inner join TBMSG mg on rg.Id_MensagReg = mg.Id_Mensag
     Where cb.Cod_Estabe = @PCodEstabe
       And cb.Ser_Nota = @PSerNot
       And cb.Num_Nota = @PNumNot
       And IsNull(rg.Id_MensagReg,0) > 0 

    if @rg_IdMensag > 0
      begin

        Exec PR_MontaMensagemNF 'S', @rg_IdMensag, @PCodEstabe, @PNumNot, @PSerNot, 0, '', 0, 'R', @PObserv output

    if (@PObserv <> '') and
           not exists(Select 1 From NSCOB 
                       Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot
                         And Id_Mensag = @rg_IdMensag)
          begin
            Set @WNumSeqMensag = IsNull((Select max(Num_SeqMensag) 
                                           From NSCOB 
                                          Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot),0) + 1
            Insert Into NSCOB (Cod_Estabe, Ser_Nota, Num_Nota, Num_SeqMensag, Id_Mensag, Des_Observ
                            ,  Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
              Values (@PCodEstabe, @PSerNot, @PNumNot, @WNumSeqMensag, @rg_IdMensag, @PObserv
                   ,  @mg_FlgInfCpl, @mg_FlgobsCont, @mg_FlginfAdFisco, @mg_FlgobsFisco)
          end
       end

  end  -- if exists(Select 1 NFSCB
---------------------------------------------------------------------------

-- qg Suframa
if Exists(Select 1 From NFSCB Where Cod_Estabe = @PCodEstabe
             And Ser_Nota =  @PSerNot And Num_Nota =  @PNumNot 
             And Vlr_DscCalSuframa > 0) and
   Exists(Select 1 From TBMSG Where CharIndex('SUFRAMA',Des_Mensag) > 0
             And Substring(Nom_TabPri,1,3) = 'NFS' And Flg_infCpl = 1)
  begin
    Set @rg_IdMensag = (Select top 1 Id_Mensag From TBMSG
                         Where CharIndex('SUFRAMA',Des_Mensag) > 0
                           And Substring(Nom_TabPri,1,3) = 'NFS'
