-- Total PMC
Set @ObsNf1 = 'Total PMC: R$'
if Exists(Select 1
            From FS_PARAM 
           Where Cod_Estabe = @PCodEstabe
             And Cod_Param = 'NFE_CFG_DNF_PMCNFE'
             And Val_Param ='1') and
   Exists(Select 1
            From FS_PARAM 
           Where Cod_Estabe = @PCodEstabe
             And Cod_Param = 'NFE_CFG_DNF_TOTPMC'
             And Val_Param ='1')
  begin
    if @PTipNot = 'S'
      begin
        if Exists(Select 1
                    From NFSIT it
                   Where it.Cod_Estabe = @PCodEstabe
                     And it.Ser_Nota = @PSerNot
                     And it.Num_Nota = @PNumNot
                     And IsNull(it.Prc_MaxCon,0) > 0)
          begin
            Select @ObsNf1 = dbo.FN_FormataValor(sum((it.Qtd_Produto+it.Qtd_Bonificacao)*IsNull(it.Prc_MaxCon,0)*IsNull(it.Fat_CnvImpFat,1)), '.', ',')
              From NFSIT it
             Where it.Cod_Estabe = @PCodEstabe
               And it.Ser_Nota = @PSerNot
               And it.Num_Nota = @PNumNot

            if IsNull(@ObsNf1,'') <> '' 
              Set @PObserv = 'Total PMC: R$' + @ObsNf1

            if not Exists(Select 1 From @TabObs Where Tip_Not = @PTipNot And Des_Observ = @PObserv)
              Insert Into @TabObs (Tip_Not, Des_Observ, Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
                           Values (@PTipNot, @PObserv, 1, 0, 0, 0)

          end  -- if Exists(Select 1
      end  -- if @PTipNot = 'S'
    else
      begin
        if Exists(Select 1
                    From NFEIT it
                   Where it.Cod_Estabe = @PCodEstabe
                     And it.Protocolo = @PNumNot
                     And IsNull(it.Prc_MaxCon,0) > 0)
          begin
            Select @ObsNf1 = dbo.FN_FormataValor(sum((it.Qtd_Pedido+it.Qtd_Bonificacao)*IsNull(it.Prc_MaxCon,0)*IsNull(it.Fator_Fat,1)), '.', ',')
              From NFEIT it
             Where it.Cod_Estabe = @PCodEstabe
               And it.Protocolo = @PNumNot

            if IsNull(@ObsNf1,'') <> '' 
              Set @PObserv = 'Total PMC: R$' + @ObsNf1

            if not Exists(Select 1 From @TabObs Where Tip_Not = @PTipNot And Des_Observ = @PObserv)
              Insert Into @TabObs (Tip_Not, Des_Observ, Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
                           Values (@PTipNot, @PObserv, 1, 0, 0, 0)

          end  -- if Exists(Select 1
      end  -- else if @PTipNot = 'S'
  end  -- if Exists(Select 1


