                 And x.Ser_Nota = i.Ser_Nota and x.Num_Nota = i.num_Nota 
                 And IsNull(x.Vlr_IcmParDes,0) > 0)

Select vBCUFDest = sum(IsNull(i.Vlr_BasIcmsNor,0))
  From NFEIT i
 Where i.Cod_Estabe = @PCodEstabe
   And i.Protocolo = @PNumNot
   And Exists(Select 1 From NFEIT x 
               Where x.Cod_Estabe = i.Cod_Estabe 
                 And x.Protocolo = i.Protocolo 
                 And IsNull(x.Vlr_IcmParDes,0) > 0)
*/
Set @ObsNf1 = 'Valor do BC do ICMS na UF de destino: '
if @PTipNot = 'S'
  begin
    if Exists(Select 1
                From NFSIT i
               Where i.Cod_Estabe = @PCodEstabe
                 And i.Ser_Nota = @PSerNot
                 And i.Num_Nota = @PNumNot
                 And Exists(Select 1 From NFSIT x 
                             Where x.Cod_Estabe = i.Cod_Estabe 
                               And x.Ser_Nota = i.Ser_Nota and x.Num_Nota = i.num_Nota 
                               And IsNull(x.Vlr_IcmParDes,0) > 0))
      begin
        Select @ObsNf1 = 'Valor do BC do ICMS na UF de destino: ' + 
               cast(cast(sum(IsNull(i.Vlr_BasIcmsNor,0)) as Decimal(18,2)) as varchar)
          From NFSIT i
         Where i.Cod_Estabe = @PCodEstabe
           And i.Ser_Nota = @PSerNot
           And i.Num_Nota = @PNumNot
           And Exists(Select 1 From NFSIT x 
                       Where x.Cod_Estabe = i.Cod_Estabe 
                         And x.Ser_Nota = i.Ser_Nota and x.Num_Nota = i.num_Nota 
                         And IsNull(x.Vlr_IcmParDes,0) > 0)
  
        if IsNull(@ObsNf1,'') <> '' 
