-- registra as observações em @TabObs 
While Exists(Select 1 From @TabObs)
  begin
    Select top 1
           @Chave = Chave
         , @TipNot = Tip_Not
         , @ObsNf1 = Des_Observ
         , @mg_FlgInfCpl = Flg_InfCpl
         , @mg_FlgobsCont = Flg_obsCont
         , @mg_FlgInfAdFisco = Flg_InfAdFisco
         , @mg_FlgobsFisco = Flg_obsFisco
      From @TabObs
     Order by Chave

    Set @PObserv = ''
    if IsNull(@ObsNf1,'') <> '' 
      Set @PObserv = @ObsNf1

    if (@PObserv <> '') 
      begin
        if (@TipNot = 'S') and
           not exists(Select 1 From NSCOB 
                       Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot
                         And Des_Observ = @PObserv)
          begin
            Set @WNumSeqMensag = IsNull((Select max(Num_SeqMensag) 
                                           From NSCOB 
                                          Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot),0) + 1

            Insert Into NSCOB (Cod_Estabe, Ser_Nota, Num_Nota, Num_SeqMensag, Id_Mensag, Des_Observ
                            ,  Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
                       Values (@PCodEstabe, @PSerNot, @PNumNot, @WNumSeqMensag, 0, @PObserv
                            ,  @mg_FlgInfCpl, @mg_FlgobsCont, @mg_FlginfAdFisco, @mg_FlgobsFisco)
          end
        else
        if not exists(Select 1 From NECOB 
                       Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumNot
                         And Des_Observ = @PObserv)
          begin
            Set @WNumSeqMensag = IsNull((Select max(Num_SeqMensag) 
                                           From NECOB 
                                          Where Cod_Estabe = @PCodEstabe And Protocolo = @PNumNot),0) + 1

            Insert Into NECOB (Cod_Estabe, Protocolo, Num_SeqMensag, Id_Mensag, Des_Observ
                            ,  Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
                       Values (@PCodEstabe, @PNumNot, @WNumSeqMensag, 0, @PObserv
                            ,  @mg_FlgInfCpl, @mg_FlgobsCont, @mg_FlginfAdFisco, @mg_FlgobsFisco)
          end
      end

    Delete From @TabObs Where Chave = @Chave
  end  -- while
------------------------------------------------------------------------------------------------------------------------------------






-- mensagens em obsCont
Set @PObserv = ''
Set @mg_FlgInfCpl = 0
Set @mg_FlgobsCont = 1
Set @mg_FlginfAdFisco = 0
Set @mg_FlgobsFisco = 0






------------------------------------------------------------------------------------------------------------------------------------
-- mensagens me NFSIT

-- RTXCT
if Exists(Select 1
            From NFSIT it
                 inner join NFSCB cb on it.Cod_Estabe = cb.Cod_Estabe and it.Ser_Nota = cb.Ser_Nota and it.Num_Nota = cb.Num_Nota
                 inner join RTXCT rx on cb.Cod_RegTri = rx.Cod_RegTri and it.Cod_ClaTri = rx.Cod_ClaTri
           Where it.Cod_Estabe = @PCodEstabe
             And it.Ser_Nota = @PSerNot
             And it.Num_Nota = @PNumNot
             And IsNull(rx.Id_MsgDesIcmLoc,0) > 0)
  begin
    Declare @TabIte Table(
      Chave Int Identity(1,1) PRIMARY KEY
    , Cod_Produt int
    , Cod_Lote varchar(20)
    , Num_SeqIte int
    , Id_Mensag int
    )

    Insert Into @TabIte (Cod_Produt, Cod_Lote, Num_SeqIte, Id_Mensag)
      Select it.Cod_Produto, it.Cod_Lote, it.Num_SeqIte, IsNull(rx.Id_MsgDesIcmLoc,0)
        From NFSIT it
             inner join NFSCB cb on it.Cod_Estabe = cb.Cod_Estabe and it.Ser_Nota = cb.Ser_Nota and it.Num_Nota = cb.Num_Nota
             inner join RTXCT rx on cb.Cod_RegTri = rx.Cod_RegTri and it.Cod_ClaTri = rx.Cod_ClaTri
       Where it.Cod_Estabe = @PCodEstabe
         And it.Ser_Nota = @PSerNot
         And it.Num_Nota = @PNumNot
         And IsNull(rx.Id_MsgDesIcmLoc,0) > 0

    While Exists(Select 1 From @TabIte)
      begin
        Select top 1
               @Chave = Chave
             , @it_CodPrd = Cod_Produt
             , @it_CodLot = Cod_Lote
             , @it_SeqIte = Num_SeqIte
             , @rg_IdMensag = Id_Mensag 
          From @TabIte
         Order by Num_SeqIte

        if @rg_IdMensag > 0
          begin
            Exec PR_MontaMensagemNF 'S', @rg_IdMensag, @PCodEstabe, @PNumNot, @PSerNot, @it_CodPrd, @it_CodLot, @it_SeqIte,
                                    'D', @PObserv output

            if (@PObserv <> '') and
               not exists(Select 1 From NSIOB 
                           Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot
                             And Cod_Produto = @it_CodPrd And Cod_Lote = @it_CodLot And Num_SeqIte = @it_SeqIte
                             And Id_Mensag = @rg_IdMensag And Des_Observ = @PObserv)
              begin
                Set @WNumSeqMensag = IsNull((Select max(Num_SeqMensag) 
                                               From NSIOB 
                                              Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot
                                                And Cod_Produto = @it_CodPrd And Cod_Lote = @it_CodLot And Num_SeqIte = @it_SeqIte),0) + 1
                Insert Into NSIOB (Cod_Estabe, Ser_Nota, Num_Nota, Cod_Produto, Cod_Lote, Num_SeqIte, 
                                   Num_SeqMensag, Id_Mensag, Des_Observ)
                  Values (@PCodEstabe, @PSerNot, @PNumNot, @it_CodPrd, @it_CodLot, @it_SeqIte
                       ,  @WNumSeqMensag, @rg_IdMensag, @PObserv)
              end
          end  -- if @rg_IdMensag > 0

        Delete From @TabIte Where Chave = @Chave
      end

  end  -- if exists(Select 1 NFSIT
  
if @PTipNot = 'S' /* DMD-8430 */
  begin
    if Exists(Select 1
        From NFSIT it 
           Inner Join NFSCB cb on (it.Cod_Estabe = cb.Cod_Estabe And it.Ser_Nota = cb.Ser_Nota And it.Num_Nota = cb.Num_Nota) 
           Inner Join RTXCT rt on (it.Cod_ClaTri = rt.Cod_ClaTri) And (cb.Cod_RegTri = rt.Cod_RegTri)
         Where it.Cod_Estabe = @PCodEstabe
         And it.Ser_Nota = @PSerNot
         And it.Num_Nota = @PNumNot
         And (rt.Obs_FiscalSai Is Not Null Or rt.Obs_FiscalSai <> '') )
    begin
    Delete From @TabObs

    Insert Into @TabObs (Tip_Not, Des_Observ, Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
      Select Distinct @PTipNot, (IsNull(rt.Obs_FiscalSai,'')), 1, 0, 0, 0
      From NFSIT it 
         Inner Join NFSCB cb on (it.Cod_Estabe = cb.Cod_Estabe And it.Ser_Nota = cb.Ser_Nota And it.Num_Nota = cb.Num_Nota) 
         Inner Join RTXCT rt on (it.Cod_ClaTri = rt.Cod_ClaTri) And (cb.Cod_RegTri = rt.Cod_RegTri)
       Where it.Cod_Estabe = @PCodEstabe
       And it.Ser_Nota = @PSerNot
       And it.Num_Nota = @PNumNot
       And (rt.Obs_FiscalSai Is Not Null Or rt.Obs_FiscalSai <> '') 

    While Exists(Select 1 From @TabObs)
      begin
      Select top 1
           @Chave = Chave
         , @ObsNf1 = Des_Observ
         , @mg_FlgInfCpl = Flg_InfCpl
         , @mg_FlgobsCont = Flg_obsCont
         , @mg_FlgInfAdFisco = Flg_InfAdFisco
         , @mg_FlgobsFisco = Flg_obsFisco
        From @TabObs
       Order by Chave

      Set @PObserv = ''
      if IsNull(@ObsNf1,'') <> '' 
        Set @PObserv = @ObsNf1
      if (@PObserv <> '') and
         not exists(Select 1 From NSCOB 
               Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot
               And Des_Observ = @PObserv)
        begin
        Set @WNumSeqMensag = IsNull((Select max(Num_SeqMensag) 
                         From NSCOB 
                        Where Cod_Estabe = @PCodEstabe And Ser_Nota = @PSerNot And Num_Nota = @PNumNot),0) + 1

        Insert Into NSCOB (Cod_Estabe, Ser_Nota, Num_Nota, Num_SeqMensag, Id_Mensag, Des_Observ
                ,  Flg_infCpl, Flg_obsCont, Flg_infAdFisco, Flg_obsFisco)
               Values (@PCodEstabe, @PSerNot, @PNumNot, @WNumSeqMensag, 0, @PObserv
                ,  @mg_FlgInfCpl, @mg_FlgobsCont, @mg_FlginfAdFisco, @mg_FlgobsFisco)
        end

      Delete From @TabObs Where Chave = @Chave
      end
    end
  end
if @@trancount > 0
  COMMIT TRANSACTION
END
GO

