SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [dbo].[PR_IncluiHSPRC]
@PCodEstabe int,
@PCodProdut int,
@PDatAlt smalldatetime,
@PNumSeqAlt int output    -- se = 0 : cria novo pedido

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd

Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now  = GetDate()
Set @Date = cast(GetDate() as date)

Begin Transaction

Declare @PNumSeqAnt int

Set @PNumSeqAlt = 0
Set @PNumSeqAnt = 0

if not Exists(Select 1 From HSPRC Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodProdut and Dat_Alteracao = @PDatAlt)
  begin

    Insert Into HSPRC (Cod_Estabe, Cod_Produto, Dat_Alteracao, Usuario, Transacao)
      Values (@PCodEstabe, @PCodProdut, @PDatAlt, Substring(dbo.FN_UsuarioInfarma(),1,15), @Now)

    Set @PNumSeqAlt = (Select max(Seq_Alteracao) From HSPRC 
                       Where Cod_Estabe = @PCodEstabe And Cod_Produto = @PCodProdut and Dat_Alteracao = @PDatAlt)

    Set @PNumSeqAnt = (Select top 1 Seq_ALteracao From HSPRC 
                       Where Cod_Estabe = @PCodEstabe And Cod_Produto = @PCodProdut 
                       /*And ( (Dat_Alteracao = @Date) and (Seq_Alteracao < @PNumSeqAlt) or (Dat_Alteracao < @Date) ) */
					   And ( (Dat_Alteracao = @Date) and (Seq_Alteracao < @PNumSeqAlt) or (Dat_Alteracao < @PDatAlt) ) /* DMD7878 */
                       Order by Cod_Estabe, Cod_Produto, Dat_Alteracao desc, Seq_ALteracao desc)

    Update h1
      Set h1.Vlr_PrcVen = IsNull(h2.Vlr_PrcVen,0),
          h1.Vlr_PrcFab = IsNull(h2.Vlr_PrcFab,0),
          h1.Vlr_PrcMaxCon = IsNull(h2.Vlr_PrcMaxCon,0),
          h1.Vlr_RefFpb = IsNull(h2.Vlr_RefFpb,0),
          h1.Vlr_CusLiqPra = IsNull(h2.Vlr_CusLiqPra,0),
          h1.Vlr_CusLiqDep = IsNull(h2.Vlr_CusLiqDep,0),
          h1.Vlr_CusMed = IsNull(h2.Vlr_CusMed,0),
          h1.Vlr_CusMedPra = IsNull(h2.Vlr_CusMedPra,0),
          h1.Vlr_CusMedDep = IsNull(h2.Vlr_CusMedDep,0),
          h1.Vlr_CusMedCom = IsNull(h2.Vlr_CusMedCom,0),
          h1.Vlr_PrcUltEntLiq = IsNull(h2.Vlr_PrcUltEntLiq,0),
          h1.Vlr_PrcUltEntLiqIpi = IsNull(h2.Vlr_PrcUltEntLiqIpi,0),
          h1.Vlr_BasCalSubTriEntMed = IsNull(h2.Vlr_BasCalSubTriEntMed,0),
          h1.Vlr_PrcFab12 = IsNull(h2.Vlr_PrcFab12,0),
          h1.Vlr_PrcFab17 = IsNull(h2.Vlr_PrcFab17,0),
          h1.Vlr_PrcFab175 = IsNull(h2.Vlr_PrcFab175,0),
          h1.Vlr_PrcFab18 = IsNull(h2.Vlr_PrcFab18,0),
          h1.Vlr_PrcFab19 = IsNull(h2.Vlr_PrcFab19,0),
          h1.Vlr_PrcFab195 = IsNull(h2.Vlr_PrcFab195,0),
          h1.Vlr_PrcFab20 = IsNull(h2.Vlr_PrcFab20,0),
          h1.Vlr_PrcFab205 = IsNull(h2.Vlr_PrcFab205,0),
          h1.Vlr_PrcMaxCon12 = IsNull(h2.Vlr_PrcMaxCon12,0),
          h1.Vlr_PrcMaxCon17 = IsNull(h2.Vlr_PrcMaxCon17,0),
          h1.Vlr_PrcMaxCon175 = IsNull(h2.Vlr_PrcMaxCon175,0),
          h1.Vlr_PrcMaxCon18 = IsNull(h2.Vlr_PrcMaxCon18,0),
          h1.Vlr_PrcMaxCon19 = IsNull(h2.Vlr_PrcMaxCon19,0),
          h1.Vlr_PrcMaxCon195 = IsNull(h2.Vlr_PrcMaxCon195,0),
          h1.Vlr_PrcMaxCon20 = IsNull(h2.Vlr_PrcMaxCon20,0),
          h1.Vlr_PrcMaxCon205 = IsNull(h2.Vlr_PrcMaxCon205,0)

    From HSPRC h1
         Inner Join HSPRC h2 on (h2.Cod_Estabe = h1.Cod_Estabe And h2.Cod_Produto = h1.Cod_Produto And h2.Seq_Alteracao = @PNumSeqAnt)
    Where h1.Cod_Estabe  = @PCodEstabe
    And h1.Cod_Produto   = @PCodProdut
    And h1.Dat_Alteracao = @PDatAlt
    And h1.Seq_Alteracao = @PNumSeqAlt

   end
else
  Set @PNumSeqAlt = (Select max(Seq_Alteracao) From HSPRC 
                     Where Cod_Estabe = @PCodEstabe And Cod_Produto = @PCodProdut and Dat_Alteracao = @PDatAlt)

Commit Transaction
GO


