   Where pr.Prc_MaxCon <> case 
                            when Round(IsNull(es.Per_AlqIcm,0),2) = 20.00 then p.Prc_MaxCon20
                            else pr.Prc_MaxCon
                          end

if Update(Prc_MaxCon205)
  Update pr
     Set pr.Prc_MaxCon = case 
                           when Round(IsNull(es.Per_AlqIcm,0),2) = 20.50 then p.Prc_MaxCon205
                           else pr.Prc_MaxCon
                         end
    From Inserted I
         inner join PRODU P  on P.Codigo = I.Codigo 
         inner join PRXES pr on P.Codigo = pr.Cod_Produt
         inner join ESTAB es on pr.Cod_Estabe = es.Cod_Estabe
   Where pr.Prc_MaxCon <> case 
                            when Round(IsNull(es.Per_AlqIcm,0),2) = 20.50 then p.Prc_MaxCon205
                            else pr.Prc_MaxCon
                          end

if Update(Prc_MaxCon21)
  Update pr
     Set pr.Prc_MaxCon = case 
                           when Round(IsNull(es.Per_AlqIcm,0),2) = 21.00 then p.Prc_MaxCon21
                           else pr.Prc_MaxCon
                         end
    From Inserted I 
         inner join PRODU P  on P.Codigo = I.Codigo
         inner join PRXES pr on P.Codigo = pr.Cod_Produt
         inner join ESTAB es on pr.Cod_Estabe = es.Cod_Estabe
   Where pr.Prc_MaxCon <> case 
                            when Round(IsNull(es.Per_AlqIcm,0),2) = 21.00 then p.Prc_MaxCon21
                            else pr.Prc_MaxCon
                          end

if Update(Prc_MaxCon22)
  Update pr
     Set pr.Prc_MaxCon = case 
                           when Round(IsNull(es.Per_AlqIcm,0),2) = 22.00 then p.Prc_MaxCon22
                           else pr.Prc_MaxCon
                         end
    From Inserted I
         inner join PRODU P  on P.Codigo = I.Codigo
         inner join PRXES pr on P.Codigo = pr.Cod_Produt
         inner join ESTAB es on pr.Cod_Estabe = es.Cod_Estabe
   Where pr.Prc_MaxCon <> case 
                            when Round(IsNull(es.Per_AlqIcm,0),2) = 22.00 then p.Prc_MaxCon22
                            else pr.Prc_MaxCon
                          end

-- atualiza historico de preços
--if Update(Prc_UltEntLiq) or Update(Prc_UltEntLiqIpi) or 
if Update(Prc_RefFpb) or
   Update(Prc_Fabric12) or Update(Prc_MaxCon12) or 
   Update(Prc_Fabric17) or Update(Prc_MaxCon17) or 
   Update(Prc_Fabric175) or Update(Prc_MaxCon175) or 
   Update(Prc_Fabric18) or Update(Prc_MaxCon18) or 
   Update(Prc_Fabric19) or Update(Prc_MaxCon19) or 
   Update(Prc_Fabric195) or Update(Prc_MaxCon195) or 
   Update(Prc_Fabric20) or Update(Prc_MaxCon20) or 
   Update(Prc_Fabric205) or Update(Prc_MaxCon205) or 
   Update(Prc_Fabric21) or Update(Prc_MaxCon21) or 
   Update(Prc_Fabric22) or Update(Prc_MaxCon22) 
  begin
    Declare @CodEstabe int, 
            @CodProdut int, 
            @DatAltera smalldatetime,
            @NumSequen int

    DECLARE Table_Cr CURSOR Local Fast_Forward For 
      
	  /*Select es.Cod_Estabe, px.Codigo, @Date */
	  Select es.Cod_Estabe, px.Codigo, px.Transacao			 			 
        From ESTAB es 
		     Cross Join (Select I.Codigo,  
								Transacao = Case When I.Transacao > @Date Then I.Transacao /* DMD-7878 */
												 Else @Date 
											End 
                           From	Inserted I 
                                Inner Join Deleted D on I.Codigo = D.Codigo
                          --Where ( (IsNull(I.Prc_UltEntLiq,0)    <> IsNull(D.Prc_UltEntLiq,0)) or
                          --        (IsNull(I.Prc_UltEntLiqIpi,0) <> IsNull(D.Prc_UltEntLiqIpi,0)) or
                          Where ( (IsNull(I.Prc_RefFpb,0)       <> IsNull(D.Prc_RefFpb,0)) or
                                  (IsNull(I.Prc_Fabric12,0)     <> IsNull(D.Prc_Fabric12,0)) or
                                  (IsNull(I.Prc_MaxCon12,0)     <> IsNull(D.Prc_MaxCon12,0)) or 
                                  (IsNull(I.Prc_Fabric17,0)     <> IsNull(D.Prc_Fabric17,0)) or
                                  (IsNull(I.Prc_MaxCon17,0)     <> IsNull(D.Prc_MaxCon17,0)) or 
                                  (IsNull(I.Prc_Fabric175,0)    <> IsNull(D.Prc_Fabric175,0)) or
                                  (IsNull(I.Prc_MaxCon175,0)    <> IsNull(D.Prc_MaxCon175,0)) or
                                  (IsNull(I.Prc_Fabric18,0)     <> IsNull(D.Prc_Fabric18,0)) or
                                  (IsNull(I.Prc_MaxCon18,0)     <> IsNull(D.Prc_MaxCon18,0)) or
                                  (IsNull(I.Prc_Fabric19,0)     <> IsNull(D.Prc_Fabric19,0)) or
                                  (IsNull(I.Prc_MaxCon19,0)     <> IsNull(D.Prc_MaxCon19,0)) or
                                  (IsNull(I.Prc_Fabric195,0)    <> IsNull(D.Prc_Fabric195,0)) or
                                  (IsNull(I.Prc_MaxCon195,0)    <> IsNull(D.Prc_MaxCon195,0)) or
                                  (IsNull(I.Prc_Fabric20,0)     <> IsNull(D.Prc_Fabric20,0)) or
                                  (IsNull(I.Prc_MaxCon20,0)     <> IsNull(D.Prc_MaxCon20,0)) or
                                  (IsNull(I.Prc_Fabric205,0)    <> IsNull(D.Prc_Fabric205,0)) or
                                  (IsNull(I.Prc_MaxCon205,0)    <> IsNull(D.Prc_MaxCon205,0)) or
                                  (IsNull(I.Prc_Fabric21,0)     <> IsNull(D.Prc_Fabric21,0)) or
                                  (IsNull(I.Prc_MaxCon21,0)     <> IsNull(D.Prc_MaxCon21,0)) or
                                  (IsNull(I.Prc_Fabric22,0)     <> IsNull(D.Prc_Fabric22,0)) or
                                  (IsNull(I.Prc_MaxCon22,0)     <> IsNull(D.Prc_MaxCon22,0)) 
                                ) ) px 
    OPEN Table_Cr
    FETCH NEXT FROM Table_Cr INTO @CodEstabe, @CodProdut, @DatAltera
    WHILE @@FETCH_STATUS = 0
    BEGIN

      Exec PR_IncluiHSPRC @CodEstabe, @CodProdut, @DatAltera, @NumSequen output   

      Update H
        Set H.Vlr_RefFpb = I.Prc_RefFpb,
            --H.Vlr_PrcUltEntLiq = I.Prc_UltEntLiq,
            --H.Vlr_PrcUltEntLiqIpi = I.Prc_UltEntLiqIpi,
            H.Vlr_PrcFab12 = I.Prc_Fabric12,
            H.Vlr_PrcMaxCon12 = I.Prc_MaxCon12,
            H.Vlr_PrcFab17 = I.Prc_Fabric17,
            H.Vlr_PrcMaxCon17 = I.Prc_MaxCon17,
            H.Vlr_PrcFab175 = I.Prc_Fabric175,
            H.Vlr_PrcMaxCon175 = I.Prc_MaxCon175,
            H.Vlr_PrcFab18 = I.Prc_Fabric18,
            H.Vlr_PrcMaxCon18 = I.Prc_MaxCon18,
            H.Vlr_PrcFab19 = I.Prc_Fabric19,
            H.Vlr_PrcMaxCon19 = I.Prc_MaxCon19,
            H.Vlr_PrcFab195 = I.Prc_Fabric195,
            H.Vlr_PrcMaxCon195 = I.Prc_MaxCon195,
            H.Vlr_PrcFab20 = I.Prc_Fabric20,
            H.Vlr_PrcMaxCon20 = I.Prc_MaxCon20,
            H.Vlr_PrcFab205 = I.Prc_Fabric205,
            H.Vlr_PrcMaxCon205 = I.Prc_MaxCon205,
            H.Vlr_PrcFab21 = I.Prc_Fabric21,
            H.Vlr_PrcMaxCon21 = I.Prc_MaxCon21,
            H.Vlr_PrcFab22 = I.Prc_Fabric22,
            H.Vlr_PrcMaxCon22 = I.Prc_MaxCon22,
            H.Usuario = Substring(dbo.FN_UsuarioInfarma(),1,15)
      From HSPRC H 
		   inner Join Inserted I on H.Cod_Produto = I.Codigo
      Where H.Cod_Estabe  = @CodEstabe
      and H.Cod_Produto   = @CodProdut 
      and H.Dat_Alteracao = @DatAltera
      and H.Seq_Alteracao = @NumSequen

      FETCH NEXT FROM Table_Cr INTO @CodEstabe, @CodProdut, @DatAltera
    END
    CLOSE Table_Cr
    DEALLOCATE Table_Cr
  end

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_RegistraEmailXml]
@PCodEstabe int,
@PSerNot varchar(3),
@PNumNot int

AS

SET NOCOUNT ON

Begin Transaction

Declare @pm_FlgEnviaXml bit,
        @vr_DesEmailTo varchar(200),
        @vr_DesEmailTr varchar(200),
        @vr_DesAssunto varchar(100),
        @vr_DesNomArq  varchar(100),
        @vr_DesTexto   varchar(MAX),
        @vr_CodCli     int,
		@vr_IsnUsu     int

Select @pm_FlgEnviaXml = Case When Val_Param = 'SIM' then
						   Cast(1 as bit)
                         Else 			
                           Cast(0 as bit)
                         End						   
From FS_PARAM
Where Cod_Estabe = @PCodEstabe
And Cod_Param = 'NFE_XML_ATIVO'

if @@ROWCOUNT > 0 and @pm_FlgEnviaXml = 1 
  begin

	Select @vr_DesEmailTo = Case When LTrim(IsNull(a.Email,''))<>'' and LTrim(IsNull(b.Email,''))<>'' and a.Email<>b.Email then lower(a.Email+','+b.Email) 
								 When LTrim(IsNull(a.Email,''))<>'' then lower(LTrim(a.Email))
								 When LTrim(IsNull(b.Email,''))<>'' then lower(LTrim(b.Email))
								 Else ''
							End,
		  @vr_DesNomArq  = n.Chv_Acesso,
		  @vr_CodCli     = a.Codigo,
		  @vr_DesEmailTr = IsNull(t.EMail,'')
	From NFSCB n
	Inner Join CLIEN a On n.Cod_Cliente = a.Codigo
	Left Join CLIEN b On a.Cod_CliPag = b.Codigo
	Left Join TRANS t On n.Cod_Transportadora = t.Codigo
	Where n.Cod_Estabe = @PCodEstabe
    And n.Ser_Nota = @PSerNot
    And n.Num_Nota = @PNumNot	
	
	Select @vr_IsnUsu = ua.Isn 
	From NFSCB nf
	Inner Join USUAR ua On ua.Nome_Login = nf.Usuario 
	Where nf.Cod_Estabe = @PCodEstabe
    And nf.Ser_Nota = @PSerNot
    And nf.Num_Nota = @PNumNot
    
	-- Texto padrao configurado para Assunto e Corpo do email
	Select @vr_DesAssunto = Val_Param 
	From FS_PARAM Where Cod_Estabe = @PCodEstabe And Cod_Param = 'NFE_XML_ASSUNTO'

	Select @vr_DesTexto = Val_Param 
	From FS_PARAM Where Cod_Estabe = @PCodEstabe And Cod_Param = 'NFE_XML_TEXTO'

	-- Substituindo MACROS pelos valores no texto -- ASSUNTO
	Select Top 1 @vr_DesAssunto = Replace(@vr_DesAssunto,'[RAZAO_SOCIAL_EMPRESA]',Des_RazSoc)
	From ESTAB Where Cod_Estabe = @PCodEstabe

	Select Top 1 @vr_DesAssunto = Replace(@vr_DesAssunto,'[CNPJ_EMPRESA]',Num_Cnpj)
	From ESTAB Where Cod_Estabe = @PCodEstabe

	Select Top 1 @vr_DesAssunto = Replace(@vr_DesAssunto,'[CNPJ_CPF_CLIENTE]',Cgc_Cpf)
	From CLIEN Where Codigo = @vr_CodCli

	Select Top 1 @vr_DesAssunto = Replace(@vr_DesAssunto,'[RAZAO_SOCIAL_CLIENTE]',Razao_Social)
	From CLIEN Where Codigo = @vr_CodCli

	Select Top 1 @vr_DesAssunto = Replace(@vr_DesAssunto,'[SERIE_NUMERO_NOTA]',@PSerNot+'/'+Convert(varchar(10),@PNumNot))

	Select Top 1 @vr_DesAssunto = Replace(@vr_DesAssunto,'[CHAVE_NFE]',@vr_DesNomArq)

	-- Substituindo MACROS pelos valores no texto -- CORPO
	Select Top 1 @vr_DesTexto = Replace(@vr_DesTexto,'[RAZAO_SOCIAL_EMPRESA]',Des_RazSoc)
	From ESTAB Where Cod_Estabe = @PCodEstabe

	Select Top 1 @vr_DesTexto = Replace(@vr_DesTexto,'[CNPJ_EMPRESA]',Num_Cnpj)
	From ESTAB Where Cod_Estabe = @PCodEstabe

	Select Top 1 @vr_DesTexto = Replace(@vr_DesTexto,'[CNPJ_CPF_CLIENTE]',Cgc_Cpf)
	From CLIEN Where Codigo = @vr_CodCli

	Select Top 1 @vr_DesTexto = Replace(@vr_DesTexto,'[RAZAO_SOCIAL_CLIENTE]',Razao_Social)
	From CLIEN Where Codigo = @vr_CodCli

	Select Top 1 @vr_DesTexto = Replace(@vr_DesTexto,'[SERIE_NUMERO_NOTA]',@PSerNot+'/'+Convert(varchar(10),@PNumNot))

	Select Top 1 @vr_DesTexto = Replace(@vr_DesTexto,'[CHAVE_NFE]',@vr_DesNomArq)

	-----------------
	-- Caso não haja texto configurado

	if IsNull(@vr_DesAssunto,'')=''
	  Set @vr_DesAssunto = 'Envio XML NFe '+@PSerNot+'/'+Convert(varchar(10),@PNumNot)

	if IsNull(@vr_DesTexto,'')=''
	  Set @vr_DesTexto = 'XML NFe '+@PSerNot+'/'+Convert(varchar(10),@PNumNot)+' anexada - Chave Nfe ['+@vr_DesNomArq+']'

	Set @vr_DesNomArq = 'NFe'+@vr_DesNomArq+'.xml'

	While (CharIndex(',,',@vr_DesEmailTo) <> 0) or (CharIndex(' ',@vr_DesEmailTo) <> 0)
	  begin
		  Set @vr_DesEmailTo = Replace(@vr_DesEmailTo,' ','')
		  Set @vr_DesEmailTo = Replace(@vr_DesEmailTo,',,','')
	  end
	
	if IsNull(@vr_DesEmailTo,'') <> ''
		Insert Into FS_EMAIL(Cod_Estabe, Ser_Nota, Num_Nota, Tip_NF, 
							 Des_EmailTo, Des_Assunto, Des_Texto, Des_NomArq,
							 AnexoB64, Isn_Usuario )
		Select x.Cod_Estabe,
			   x.Ser_Nota,
			   x.Num_Nota,
			   'X' as Tipo,
			   Substring(e.Item,1,200) as Email,
			   @vr_DesAssunto as Assunto,
			   @vr_DesTexto   as Texto,
			   @vr_DesNomArq  as Nome,
			   dbo.FN_StrToBase64(x.Xml_Nfeproc) as Anexo, 
			   @vr_IsnUsu as IdUsuario 
		From FS_NFXML x
		Cross Join FN_Split(@vr_DesEmailTo,',') e
		Where Cod_Estabe = @PCodEstabe
		And Ser_Nota = @PSerNot
		And Num_Nota = @PNumNot	
		And Xml_Nfe is not null

	--Transportador separado devido ao tipo de remetente
	if IsNull(@vr_DesEmailTr,'') <> ''
		Insert Into FS_EMAIL(Cod_Estabe, Ser_Nota, Num_Nota, Tip_NF, 
							 Des_EmailTo, Des_Assunto, Des_Texto, Des_NomArq,
							 AnexoB64, Isn_Usuario, Tip_Rem )
		Select x.Cod_Estabe,
			   x.Ser_Nota,
			   x.Num_Nota,
			   'X' as Tipo,
			   @vr_DesEmailTr,
			   @vr_DesAssunto as Assunto,
			   @vr_DesTexto   as Texto,
			   @vr_DesNomArq  as Nome,
			   dbo.FN_StrToBase64(x.Xml_Nfeproc) as Anexo, 
			   @vr_IsnUsu as IdUsuario,
			   'TR' as Tip_Rem
		From FS_NFXML x
		Where Cod_Estabe = @PCodEstabe
		And Ser_Nota = @PSerNot
		And Num_Nota = @PNumNot	
		And Xml_Nfe is not null
  end

Commit Transaction
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_SolicitaLoteProduto]
@PCodEstabe int,
@PCodPed int,
@PFlgLotEsp bit,
@PCodPrd int,
@PCodLot varchar(20),
@PTipSai varchar(1),
@PCodPrm int,
@PCodKitPrm int,
@PQtdPed int,
@PQtdBon int,
@PFatCnvImpFat int,
@PFlgLotNaoFra bit

AS

SET NOCOUNT ON

Set DateFormat ymd

Begin Transaction

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime

Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)

if @PQtdPed is null 
  Set @PQtdPed = 0
if @PQtdBon is null 
  Set @PQtdBon = 0
if IsNull(@PFatCnvImpFat,0) = 0
  Set @PFatCnvImpFat = 1
  
-- corrige saldos negativos
if Exists(Select Cod_Produt
            From PRLOT 
           Where Cod_Estabe = @PCodEstabe
             And Cod_Produt = @PCodPrd
             And ((Qtd_SolPra < 0) or (Qtd_SolDep < 0)))
  begin
    Update PRLOT
       Set Qtd_SolPra = 0
     Where Cod_Estabe = @PCodEstabe
       And Cod_Produt = @PCodPrd
       And Qtd_SolPra < 0
    
    Update PRLOT
       Set Qtd_SolDep = 0
     Where Cod_Estabe = @PCodEstabe
       And Cod_Produt = @PCodPrd
       And Qtd_SolDep < 0
  end

if Exists(Select Cod_Produt
            From PRLOT 
           Where Cod_Estabe = @PCodEstabe
             And Cod_Produt = @PCodPrd
             And ((Qtd_Saldo < 0) or (Qtd_Fisico < 0) or (Qtd_SldPra < 0) or (Qtd_FisPra < 0) or (Qtd_SldDep < 0) or (Qtd_FisDep < 0)))
  begin
    Update PRLOT
       Set Qtd_FisPra = Qtd_FisPra + Abs(Qtd_SldPra)
     Where Cod_Estabe = @PCodEstabe
       And Cod_Produt = @PCodPrd
       And Qtd_SldPra < 0
    
    Update PRLOT
       Set Qtd_FisDep = Qtd_FisDep + Abs(Qtd_SldDep)
     Where Cod_Estabe = @PCodEstabe
       And Cod_Produt = @PCodPrd
       And Qtd_SldDep < 0
  end
  
-- garante bloqueio do registro
Update PRXES
   Set Qtd_Solici = 0
 Where Cod_Estabe = @PCodEstabe 
   And Cod_Produt = @PCodPrd
   And Qtd_Solici < 0

Update PRXES
   Set Qtd_PrmSolici = 0
 Where Cod_Estabe = @PCodEstabe   
   And Cod_Produt = @PCodPrd
   And Qtd_PrmSolici < 0
  
Update PRXES
   Set Qtd_Solici = Qtd_Solici + 0
 Where Cod_Estabe = @PCodEstabe
   And Cod_Produt = @PCodPrd

Declare @CodDep smallint,
        @QtdPedAju int,
        @QtdBonAju int,
        @FatBon numeric(18,8),
        @PedSol int,
        @BonSol int,
        @CodLotPri varchar(20),  -- primeiro lote solicitado
        @CodLotEsp varchar(20),  -- lote especifico
        @lt_LocEst varchar(1),
        @lt_DatVct smalldatetime,
        @lt_CodLot varchar(20),
        @lt_SldLot int,
        @AccQtdAte int,
        @AccBonAte int,
        @QtdDsp int,
		@QtdLotDsp int,
        @QtdDspPrd int,
        @QtdDspLot int,
        @QtdDspPrm int,
        @QtdEmbFec int,
        @FlgPrdForLin bit,
        @PerQtp numeric(18,4),
        @PerQtpAcu numeric(18,4),
        @pm_FlgPerCmpEst bit,
        @to_CodCfoNorInt int,
		@cl_CodCliPag int,
		@cl_QtdMesMinPrzVctLot int,
        @CodMtvRej varchar(3),
        @QtdSolPrdIni int,
        @WAccQtdTot int,
        @WQtdPra int,
        @WQtdDep int
        
-- sem WMS: deposito unico
Set @CodDep = IsNull((Select min(Cod_Dep) 
                        From TBDEP 
                       Where Cod_Estabe = @PCodEstabe),1)

-- coloca campos de tabela na memoria
Select @pm_FlgPerCmpEst = Isnull(FlgPerCmpEst,0)
  From PARAM
 Where Cod_Estabe = @PCodEstabe
  
Select @to_CodCfoNorInt = t.Cod_CfoNorInt
  From TPOPE t 
       Inner Join PDVCB p on (t.Cod_Ope = p.Tip_Faturamento)
 Where p.Cod_Estabe = @PCodEstabe
   And p.Numero = @PCodPed

Select @cl_CodClipag = IsNull(cl.Cod_CliPag,0),
       @cl_QtdMesMinPrzVctLot = IsNull(Qtd_MesMinPrzVctLot,0)
 From PDVCB cb
      Left Outer Join CLIEN cl on (cb.Cod_Cliente = cl.Codigo)
 Where cb.Cod_Estabe = @PCodEstabe
   And cb.Numero = @PCodPed

-- variaveis para salvar valores iniciais do pedido para serem usados qdo incluir uma nova linha (lote)
Declare @it_LocFis varchar(15), 
        @it_CodFab int, 
        @it_PerDsc numeric(18,4), 
        @it_PrcUni numeric(18,8), 
        @it_PrcTab numeric(18,4), 
        @it_PrcTabBru numeric(18,4), 
        @it_FlgPrcUniDsc bit, 
        @it_PrzMax int, 
        @it_DscPrz numeric(18,4), 
        @it_DscVis numeric(18,4),
        @it_QtdSol int,
        @it_PrcMaxCon numeric(18,4), 
        @it_PrcFab numeric(18,4), 
        @it_NumSeqDig int,
        @it_NomUsuDbq varchar(15),
        @it_DesUnvImpFat char(3),
        @it_DesAprImpFat varchar(12),
        @it_IdPolCom int,
        @it_FlgVerba bit, 
        @it_PrcPolCom numeric(18,8), 
        @it_PerDscPolCom numeric(18,4), 
        @it_PerDscVisPolCom numeric(18,4),
        @it_QtdPrzPolCom int,
        @it_FlgPolPrm bit,
        @it_PrcUniLiqPer numeric(18,4),
        @it_PrcLiqUltEnt numeric(18,4),
        @it_PrcRefFpb numeric(18,4),
        @it_PrcUniPde numeric(18,4), 
        @it_PerDscPde numeric(18,4), 
        @it_CodPrjPde varchar(12),
        @it_NumSeqPdc varchar(6),
        @it_PerVrbPar numeric(18,4), 
        @it_PerVrbBon numeric(18,4), 
        @it_VlrBonificacao numeric(18,4),
        @it_VlrDscBonRat numeric(18,4),
        @it_PrcCusMinComMarkup numeric(18,4),
        @it_VlrBasVerba numeric(18,4),
        @IdPolLot int   -- politica com lote especifico

Select @it_LocFis = it.Loc_Fisica,
       @it_CodFab = it.Cod_Fabricante,
       @it_QtdSol = IsNull(it.Qtd_Solicitado,0),
       @it_PerDsc = it.Per_Desconto,
       @it_PrcUni = it.Prc_Unitario,
       @it_PrcTab = it.Prc_Tabela,
       @it_PrcTabBru = it.Prc_TabBru,
       @it_FlgPrcUniDsc = it.Flg_PrcUniDsc,
       @it_PrzMax = it.Qtd_PrzMax,
       @it_DscPrz = it.Per_Descon,
       @it_DscVis = it.Per_DscVis,
       @it_PrcMaxCon = it.Prc_MaxCon,
       @it_PrcFab = it.Prc_Fabric,
       @it_NumSeqDig = it.Num_SeqDig,
       @it_NomUsuDbq = it.Nom_UsuDesbloq,
       @it_DesUnvImpFat = it.Des_UnvImpFat,
       @it_DesAprImpFat = it.Des_AprImpFat,
       @it_IdPolCom = it.Id_PolCom,
       @IdPolLot = Case
                     When Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = it.Cod_Estabe and pl.Id_PolCom = it.Id_PolCom and pl.Cod_Produt = it.Cod_Produto) then it.Id_PolCom
                     Else 0
                   End,
       @it_FlgVerba = IsNull(it.Flg_Verba,0), 
       @it_PrcPolCom = it.Prc_PolCom, 
       @it_PerDscPolCom = it.Per_DscPolCom, 
       @it_PerDscVisPolCom = it.Per_DscVisPolCom,
       @it_QtdPrzPolCom = it.Qtd_PrzPolCom,
       @it_FlgPolPrm = ISNULL(it.Flg_PolPrm,0),
       @it_PrcUniLiqPer = it.Prc_UniLiqPer,
       @it_PrcLiqUltEnt = it.Prc_LiqUltEnt,
       @it_PrcRefFpb = it.Prc_RefFpb,
       @it_CodPrjPde = it.Cod_PrjPde,
       @it_PerDscPde = it.Per_DscPde,
       @it_PrcUniPde = it.Prc_UniPde,
       @it_NumSeqPdc = it.Num_SeqPdc,
       @it_PerVrbPar = IsNull(it.Per_VrbPar,0), 
       @it_PerVrbBon = IsNull(it.Per_VrbBon,0), 
       @it_VlrBonificacao = ISNULL(it.Vlr_Bonificacao,0),
       @it_VlrDscBonRat = ISNULL(it.Vlr_DscBonRat,0),
       @it_PrcCusMinComMarkup = ISNULL(it.Prc_CusMinComMarkup,0),
       @it_VlrBasVerba = ISNULL(it.Vlr_BasVerba,0)
  From PDVIT it
 Where it.Cod_Estabe = @PCodEstabe 
   And it.Cod_Pedido = @PCodPed 
   And it.Cod_Produto = @PCodPrd 
   And it.Cod_Lote = @PCodLot
   And it.Tip_Sai = @PTipSai

if @it_QtdSol = 0
  Set @it_QtdSol = @PQtdPed + @PQtdBon

-- exclui o regitro de origem
Delete From PDVIT
 Where Cod_Estabe = @PCodEstabe 
   And Cod_Pedido = @PCodPed 
   And Cod_Produto = @PCodPrd 
   And Cod_Lote = @PCodLot
   And Tip_Sai = @PTipSai

Set @AccQtdAte = 0
Set @AccBonAte = 0

Set @QtdDspLot = (Select sum(IsNull(Qtd_Saldo,0)) From PRLOT Where Cod_Estabe = @PCodEstabe And Qtd_Saldo > 0 And Cod_Produt = @PCodPrd)

Select @FlgPrdForLin = Case 
                         When Flag_ImprClassif1 = 'N' then 1 
                         Else 0 
                       End, 
       @QtdEmbFec = IsNull(Qtd_Embalagem,1)
  From PRODU 
 Where Codigo = @PCodPrd

if @QtdEmbFec = 0
  Set @QtdEmbFec = 1

Select @QtdDspPrd = dbo.FN_EstoqueDisponivelPrd(Cod_Estabe,Cod_Produt),
       @QtdSolPrdIni = ISNULL(Qtd_Solici,0),
       @QtdDspPrm = IsNull(Qtd_PrmDispon,0)
  From PRXES 
 Where Cod_Estabe = @PCodEstabe 
   And Cod_Produt = @PCodPrd

if IsNull(@QtdDspLot,0) < IsNull(@QtdDspPrd,0)
  Set @QtdDsp = IsNull(@QtdDspLot,0)
else
  Set @QtdDsp = IsNull(@QtdDspPrd,0)
  
-- verifica estoque disponivel para promocao
if (@PCodPrm > 0) and 
   (Charindex((Select Substring(Cod_OrigemPdv,1,1) From PDVCB Where Cod_Estabe = @PCodEstabe And Numero = @PCodPed),';M;T;W;') > 0) 
  if IsNull((Select Flg_BlqCtrQtdPrm From PRMCB Where Codigo = @PCodPrm),0) = 0
    begin
      if @QtdDspPrm < 0 
        Set @QtdDspPrm = 0 
      if @QtdDspPrm < @QtdDsp
        Set @QtdDsp = @QtdDspPrm
    end
  
Set @CodLotPri = ''     -- primeiro lote solicitado
Set @CodMtvRej = ''

Set @QtdLotDsp = dbo.FN_QtdLoteDisponivel (@PCodEstabe, @cl_CodCliPag, @PCodPrd, @Date, @cl_QtdMesMinPrzVctLot, @IdPolLot)

-- verifica se existe lote para atendimento
if (@QtdDsp > 0) and (@QtdLotDsp = 0)
  begin
    Set @QtdDsp = 0
    Set @CodMtvRej = 'LT-'
  end

if @QtdLotDsp < @QtdDsp 
  Set @QtdDsp = @QtdLotDsp

if ((@QtdDsp/@PFatCnvImpFat)*@PFatCnvImpFat) > 0
  begin
    -- acumulador total de solicitacoes do produto
    Set @WAccQtdTot = 0

    if @PQtdPed+@PQtdBon > 0 
      Set @PerQtp = @PQtdPed*100/(@PQtdPed+@PQtdBon)
    else
      Set @PerQtp = 0

    -- ajusta quantidades conforme estoque disponivel
    Set @QtdPedAju = @PQtdPed
    Set @QtdBonAju = @PQtdBon
    if @QtdDsp < (@PQtdPed+@PQtdBon)
      begin
        if @PQtdBon > 0
          begin
            Set @FatBon = @PQtdBon*1.0/@PQtdPed*1.0
            Set @QtdBonAju = @FatBon*@QtdDsp/(1+@FatBon) + 0.05
            Set @QtdPedAju = @QtdBonAju/@FatBon
			if (@QtdPedAju+@QtdBonAju) > @QtdDsp
              Set @QtdPedAju = @QtdDsp-@QtdBonAju
          end
        else
          Set @QtdPedAju = @QtdDsp
      end

    -- inclui novo(s) registro(s) conforme disponibilidade dos lotes
    -- solicita lote especifico ou pelo vencimento
	if @PFlgLotEsp = 1
	  Set @CodLotEsp = @PCodLot
	else
	  Set @CodLotEsp = ''

    -- solicita lote por vencimento
    if @to_CodCfoNorInt > 0
      begin
        -- venda FAT
		if @pm_FlgPerCmpEst = 0  
          begin
            Declare PRLOT_Cr Cursor Local Fast_Forward For
              Select '1' as CodLocEst, lt.Dat_Vencim, lt.Cod_Lote, 
                     SldLot = Case 
                                When @PFlgLotNaoFra = 1 Then lt.Qtd_SldPra/@QtdEmbFec*@QtdEmbFec
                                Else lt.Qtd_SldPra 
                              End  
                From PRLOT lt Inner Join
                     PRODU pr on pr.Codigo = lt.Cod_Produt Left Outer Join
                     CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                     CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
               Where lt.Cod_Estabe = @PCodEstabe
                 And lt.Cod_Dep = @CodDep
                 And lt.Cod_Produt = @PCodPrd 
                 And ( ((@PFlgLotEsp = 1) and (lt.Cod_Lote  = @CodLotEsp)) or 
                       ((@PFlgLotEsp = 0) and (lt.Cod_Lote <> @CodLotEsp)) )
                 And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                             (lt.Dat_Vencim >= Case
                                                                 When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                 When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                 Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                               End))) or
                       ((@IdPolLot > 0) and 
                        Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                 And lt.Qtd_Saldo > 0 
                 And lt.Qtd_SldPra > 0
               Order by CodLocEst, lt.Dat_Vencim
          end
        else
          begin
            -- compartilha estoque
            Declare PRLOT_Cr Cursor Local Fast_Forward For 
              Select lt.CodLocEst, lt.Dat_Vencim, lt.Cod_Lote, lt.SldLot
                From ( Select '1' as CodLocEst, l1.Cod_Estabe, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote,
                              SldLot = Case 
                                         When @PFlgLotNaoFra = 1 Then l1.Qtd_SldPra/@QtdEmbFec*@QtdEmbFec
                                         Else l1.Qtd_SldPra 
                                       End  
                         From PRLOT l1 
                        Where l1.Cod_Estabe = @PCodEstabe
                          And l1.Cod_Dep = @CodDep
                          And l1.Cod_Produt = @PCodPrd 
                          And l1.Qtd_Saldo > 0 
                          And l1.Qtd_SldPra > 0
                       Union
                       Select '2' as CodLocEst, l2.Cod_Estabe, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote, 
                              SldLot = Case 
                                         When @PFlgLotNaoFra = 1 Then l2.Qtd_SldDep/@QtdEmbFec*@QtdEmbFec
                                         Else l2.Qtd_SldDep 
                                       End  
                         From PRLOT l2 
                        Where l2.Cod_Estabe = @PCodEstabe
                          And l2.Cod_Dep = @CodDep
                          And l2.Cod_Produt = @PCodPrd 
                          And l2.Qtd_Saldo > 0 
                          And l2.Qtd_SldDep > 0 ) lt Inner Join
                     PRODU pr on pr.Codigo = lt.Cod_Produt Left Outer Join
                     CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                     CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
               Where 1 = 1
                 And ( ((@PFlgLotEsp = 1) and (lt.Cod_Lote  = @CodLotEsp)) or 
                       ((@PFlgLotEsp = 0) and (lt.Cod_Lote <> @CodLotEsp)) )
                 And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                             (lt.Dat_Vencim >= Case
                                                                 When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                 When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                 Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                               End))) or
                       ((@IdPolLot > 0) and 
                        Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
               Order by lt.CodLocEst, lt.Dat_Vencim
          end
      end
    else
      begin
        -- venda ORC
        if @pm_FlgPerCmpEst = 0
          begin
            Declare PRLOT_Cr Cursor Local Fast_Forward For
              Select '2' as CodLocEst, lt.Dat_Vencim, lt.Cod_Lote,
                     SldLot = Case 
                                When @PFlgLotNaoFra = 1 Then Qtd_SldDep/@QtdEmbFec*@QtdEmbFec
                                Else lt.Qtd_SldDep 
                              End  
                From PRLOT lt Inner Join
                     PRODU pr on pr.Codigo = lt.Cod_Produt Left Outer Join
                     CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                     CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
               Where lt.Cod_Estabe = @PCodEstabe
                 And lt.Cod_Dep = @CodDep
                 And lt.Cod_Produt = @PCodPrd 
                 And ( ((@PFlgLotEsp = 1) and (lt.Cod_Lote  = @CodLotEsp)) or 
                       ((@PFlgLotEsp = 0) and (lt.Cod_Lote <> @CodLotEsp)) )
                 And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                             (lt.Dat_Vencim >= Case
                                                                 When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                 When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                 Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                               End))) or
                       ((@IdPolLot > 0) and 
                        Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                 And lt.Qtd_Saldo > 0 
                 And lt.Qtd_SldDep > 0
               Order by CodLocEst, lt.Dat_Vencim
          end
        else
          begin
            -- compartilha estoque
            Declare PRLOT_Cr Cursor Local Fast_Forward For
              Select lt.CodLocEst, lt.Dat_Vencim, lt.Cod_Lote, lt.SldLot
                From ( Select '2' as CodLocEst, l2.Cod_Estabe, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote,
                              SldLot = Case 
                                         When @PFlgLotNaoFra = 1 Then l2.Qtd_SldDep/@QtdEmbFec*@QtdEmbFec
                                         Else l2.Qtd_SldDep 
                                       End  
                         From PRLOT l2
                        Where l2.Cod_Estabe = @PCodEstabe
                          And l2.Cod_Dep = @CodDep
                          And l2.Cod_Produt = @PCodPrd 
                          And l2.Qtd_Saldo > 0 
                          And l2.Qtd_SldDep > 0
                       Union
                       Select '1' as CodLocEst, l1.Cod_Estabe, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote,
                              SldLot = Case 
                                         When @PFlgLotNaoFra = 1 Then l1.Qtd_SldPra/@QtdEmbFec*@QtdEmbFec
                                         Else l1.Qtd_SldPra 
                                       End  
                         From PRLOT l1 
                        Where l1.Cod_Estabe = @PCodEstabe
                          And l1.Cod_Dep = @CodDep
                          And l1.Cod_Produt = @PCodPrd 
                          And l1.Qtd_Saldo > 0 
                          And l1.Qtd_SldPra > 0 ) lt Inner Join
                     PRODU pr on pr.Codigo = lt.Cod_Produt Left Outer Join
                     CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                     CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
               Where 1 = 1
                 And ( ((@PFlgLotEsp = 1) and (lt.Cod_Lote  = @CodLotEsp)) or 
                       ((@PFlgLotEsp = 0) and (lt.Cod_Lote <> @CodLotEsp)) )
                 And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                             (lt.Dat_Vencim >= Case
                                                                 When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                 When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                 Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                               End))) or
                       ((@IdPolLot > 0) and 
                        Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
               Order by lt.CodLocEst desc, lt.Dat_Vencim
          end
      end

    Open PRLOT_Cr
    Fetch Next From PRLOT_Cr Into @lt_LocEst, @lt_DatVct, @lt_CodLot, @lt_SldLot 

    While @@FETCH_STATUS = 0
	  begin
        -- ajusta saldo do lote : proporcional a fator de conversão DMD-7954: 30/03/2023
        Set @lt_SldLot = (@lt_SldLot/@PFatCnvImpFat) * @PFatCnvImpFat

        While (@AccQtdAte+@AccBonAte < @QtdPedAju+@QtdBonAju) and 
              (@lt_SldLot > 0) and (@@FETCH_STATUS = 0)
          begin
            Set @PedSol = @QtdPedAju - @AccQtdAte
            Set @BonSol = @QtdBonAju - @AccBonAte
      
            -- se o saldo do lote nao atender a qtd.solicitada refazer a solicitacao proporcionalmente
            if @PedSol+@BonSol > @lt_SldLot
              begin
                Set @PedSol = Round(@lt_SldLot*@PerQtp/100,0)
                Set @BonSol = @lt_SldLot-@PedSol
              end
      
            -- garante as quantidades solicitadas
            if (@PedSol = 0) or ((@AccQtdAte+@PedSol) > @QtdPedAju) or ((@AccBonAte+@BonSol) > @QtdBonAju)
              Break
      
            -- Atualiza saldo do lote
            Set @WQtdPra = 0
            Set @WQtdDep = 0
            
            if @CodLotPri = ''
              Set @CodLotPri = @lt_CodLot

            if @lt_LocEst = '1'
              begin
                Update PRLOT
                   Set Qtd_SolPra = Qtd_SolPra + @PedSol + @BonSol
                 Where Cod_Estabe = @PCodEstabe
                   And Cod_Dep = @CodDep
                   And Cod_Produt = @PCodPrd
                   And Cod_Lote = @lt_CodLot
      
                Set @WQtdPra = @PedSol + @BonSol
                Set @WAccQtdTot = @WAccQtdTot + @WQtdPra
              end
            else
              begin
                Update PRLOT
                   Set Qtd_SolDep = Qtd_SolDep + @PedSol + @BonSol
                 Where Cod_Estabe = @PCodEstabe
                   And Cod_Dep = @CodDep
                   And Cod_Produt = @PCodPrd
                   And Cod_Lote = @lt_CodLot
      
                Set @WQtdDep = @PedSol + @BonSol
                Set @WAccQtdTot = @WAccQtdTot + @WQtdDep
              end
           
            -- incrementa saldo solicitado em PRXES
            Update PRXES 
               Set Qtd_Solici = Qtd_Solici + @PedSol + @BonSol,
                   Qtd_PrmSolici = Case 
                                     When IsNull(@PCodPrm,0) > 0 then Qtd_PrmSolici + @PedSol + @BonSol
                                     Else Qtd_PrmSolici 
                                   End
             Where Cod_Estabe = @PCodEstabe
               And Cod_Produt = @PCodPrd
          
            Set @AccQtdAte = @AccQtdAte + @PedSol
            Set @AccBonAte = @AccBonAte + @BonSol
      
            -- atualiza qtd atendida e o lote ativo
            if Exists(Select Cod_Produto From PDVIT 
                       Where Cod_Estabe = @PCodEstabe
                         And Cod_Pedido = @PCodPed 
                         and Cod_Produto = @PCodPrd 
                         and Cod_Lote = @lt_CodLot
                         and Tip_Sai = @PTipSai)
              begin
                Update PDVIT
                   Set Qtd_Pedido = Qtd_Pedido + @PedSol,
                       Qtd_Bonificacao = Qtd_Bonificacao + @BonSol,
                       Qtd_Solicitado = Qtd_Solicitado + @PedSol + @BonSol,
                       Qtd_Pra = Qtd_Pra + @WQtdPra,
                       Qtd_Dep = Qtd_Dep + @WQtdDep   
                 Where Cod_Estabe = @PCodEstabe
                   and Cod_Pedido = @PCodPed 
                   and Cod_Produto = @PCodPrd 
                   and Cod_Lote = @lt_CodLot
                   and Tip_Sai = @PTipSai
              end
            else
              begin
                Insert into PDVIT (Cod_Estabe, Cod_Pedido, Cod_Produto, Cod_Lote, Tip_Sai, 
      		                   Qtd_Pedido, Qtd_Bonificacao, Prc_Unitario, Per_Desconto, Per_Descon, Per_DscVis)  
                           Values (@PCodEstabe, @PCodPed, @PCodPrd, @lt_CodLot, @PTipSai, 
      				           @PedSol, @BonSol, @it_PrcUni, @it_PerDsc, @it_DscPrz, @it_DscVis)
                if @@error <> 0
                    begin
                      Rollback Transaction
                      Return
                    end
      
                Update PDVIT
                   Set Fat_CnvImpFat = @PFatCnvImpFat,
                       Qtd_PrzMax = @it_PrzMax, 
                       Loc_Fisica = @it_LocFis, 
                       Cod_Fabricante = @it_CodFab,
                       Cod_Promocao = @PCodPrm, 
                       Cod_KitPrm = @PCodKitPrm, 
                       Qtd_Solicitado = @PedSol+@BonSol, 
                       Flg_PrcUniDsc = @it_FlgPrcUniDsc, 
                       Prc_Tabela = @it_PrcTab,  
                       Prc_TabBru = @it_PrcTabBru, 
                       Qtd_Pra = @WQtdPra, 
                       Qtd_Dep = @WQtdDep, 
                       Prc_MaxCon = @it_PrcMaxCon,
                       Prc_Fabric = @it_PrcFab,  
                       Num_SeqDig = @it_NumSeqDig,  
                       Nom_UsuDesbloq = @it_NomUsuDbq,  
                       Des_UnvImpFat = @it_DesUnvImpFat, 
                       Des_AprImpFat = @it_DesAprImpFat,
                       Id_PolCom = @it_IdPolCom, 
                       Flg_Verba = @it_FlgVerba, 
                       Prc_PolCom = @it_PrcPolCom,  
                       Per_DscPolCom = @it_PerDscPolCom, 
                       Per_DscVisPolCom = @it_PerDscVisPolCom,
                       Qtd_PrzPolCom = @it_QtdPrzPolCom, 
                       Flg_PolPrm = @it_FlgPolPrm,
                       Prc_UniLiqPer = @it_PrcUniLiqPer, 
                       Prc_LiqUltEnt = @it_PrcLiqUltEnt,
                       Prc_RefFpb = @it_PrcRefFpb,
                       Cod_PrjPde = @it_CodPrjPde,
                       Prc_UniPde = @it_PrcUniPde, 
                       Per_DscPde = @it_PerDscPde,
                       Num_SeqPdc = @it_NumSeqPdc,
                       Per_VrbPar = @it_PerVrbPar,
                       Per_VrbBon = @it_PerVrbBon,
                       Vlr_Bonificacao = @it_VlrBonificacao, 
                       Vlr_DscBonRat = @it_VlrDscBonRat, 
                       Prc_CusMinComMarkup = @it_PrcCusMinComMarkup,
                       Vlr_BasVerba = @it_VlrBasVerba
                 Where Cod_Estabe = @PCodEstabe
                   and Cod_Pedido = @PCodPed 
                   and Cod_Produto = @PCodPrd 
                   and Cod_Lote = @lt_CodLot
                   and Tip_Sai = @PTipSai
              end
      
            -- decrementa quantidade solicitada inicial
            Set @it_QtdSol = @it_QtdSol - @PedSol - @BonSol
      
            -- calcula tributos      
            EXEC PR_CalcTributPdvit @PCodEstabe, @PCodPed, @PCodPrd, @lt_CodLot, @PTipSai
            if @@error <> 0
              begin
                Rollback Transaction
                Return
              end
      
            Fetch Next From PRLOT_Cr Into @lt_LocEst, @lt_DatVct, @lt_CodLot, @lt_SldLot 
          end  -- While (@AccQtdAte+@AccBonAte < @QtdPedAju+@QtdBonAju)

        Fetch Next From PRLOT_Cr Into @lt_LocEst, @lt_DatVct, @lt_CodLot, @lt_SldLot
      end  -- While @@FETCH_STATUS 

    Close PRLOT_Cr
    Deallocate PRLOT_Cr

    -- verifica bonificacao
    if @PQtdBon > 0
      begin
        if @AccQtdAte + @AccBonAte > 0 
          Set @PerQtpAcu = @AccQtdAte*100/(@AccQtdAte+@AccBonAte)
        else
          Set @PerQtpAcu = 0
        if Round(@PerQtpAcu*100,0) <> Round(@PerQtp*100,0)
          begin
            Set @AccQtdAte = 0
            Set @AccBonAte = 0
--            Rollback Transaction A 
            Rollback Transaction 
            Return
          end
      end

/*    
    -- incrementa saldo solicitado
    Update PRXES 
      Set Qtd_Solici = Qtd_Solici + @AccQtdAte + @AccBonAte
    Where Cod_Estabe = @PCodEstabe
    And Cod_Produt = @PCodPrd
      
    Update PRXES
      Set Qtd_PrmSolici = Qtd_PrmSolici + @AccQtdAte + @AccBonAte
    Where Cod_Estabe = @PCodEstabe
    And Cod_Produt = @PCodPrd 
    And IsNull(@PCodPrm,0) > 0
*/
  end

-- registra faltas em @CodLotPri: primeiro lote solicitado
if @CodLotPri = ''
  Set @CodLotPri = '*'

if @AccQtdAte+@AccBonAte < @PQtdPed+@PQtdBon
  begin
    if @CodMtvRej = ''
      if @QtdDsp > 0
        Set @CodMtvRej = 'ES-'   -- estoque insuficiente
      else
      if @FlgPrdForLin = 1
        Set @CodMtvRej = 'PR-'   -- produto descontinuado
      else
        Set @CodMtvRej = 'ES0'   -- estoque zero
    
    if Exists(Select Cod_Produto From PDVIT 
               Where Cod_Estabe = @PCodEstabe and Cod_Pedido = @PCodPed 
                 and Cod_Produto = @PCodPrd and Cod_Lote = @CodLotPri and Tip_Sai = @PTipSai)
      begin
        Update PDVIT
           Set Qtd_Solicitado = Qtd_Solicitado + @PQtdPed + @PQtdBon - @AccQtdAte - @AccBonAte,
               Cod_MtvRej = @CodMtvRej
         Where Cod_Estabe = @PCodEstabe
           and Cod_Pedido = @PCodPed 
           and Cod_Produto = @PCodPrd 
           and Cod_Lote = @CodLotPri
           and Tip_Sai = @PTipSai
      end
    else
      begin
        Insert into PDVIT (Cod_Estabe, Cod_Pedido, Cod_Produto, Cod_Lote, Tip_Sai, 
                           Qtd_Pedido, Qtd_Bonificacao, Prc_Unitario, Per_Desconto, Per_Descon, Per_DscVis)
                   Values (@PCodEstabe, @PCodPed, @PCodPrd, @CodLotPri, @PTipSai, 
				           0, 0, @it_PrcUni, @it_PerDsc, @it_DscPrz, @it_DscVis)
        if @@error <> 0
          begin
            Rollback Transaction
            Return
          end

        Update PDVIT
           Set Fat_CnvImpFat = @PFatCnvImpFat,
               Qtd_PrzMax = @it_PrzMax,
               Loc_Fisica = @it_LocFis,
               Cod_Fabricante = @it_CodFab,
               Cod_Promocao = @PCodPrm,
               Cod_KitPrm =  @PCodKitPrm,  
               Qtd_Solicitado = @PQtdPed+@PQtdBon-@AccQtdAte-@AccBonAte,
               Flg_PrcUniDsc = @it_FlgPrcUniDsc,
               Prc_Tabela =  @it_PrcTab,
               Prc_TabBru = @it_PrcTabBru, 
               Qtd_Pra = 0,
               Qtd_Dep = 0,
               Prc_MaxCon = @it_PrcMaxCon,
               Prc_Fabric = @it_PrcFab,
               Num_SeqDig = @it_NumSeqDig,
               Nom_UsuDesbloq = @it_NomUsuDbq,
               Des_UnvImpFat = @it_DesUnvImpFat,
               Des_AprImpFat = @it_DesAprImpFat,
               Id_PolCom = @it_IdPolCom,
               Flg_Verba = @it_FlgVerba, 
               Prc_PolCom = @it_PrcPolCom,
               Per_DscPolCom = @it_PerDscPolCom,
               Per_DscVisPolCom = @it_PerDscVisPolCom,
               Cod_MtvRej = @CodMtvRej, 
               Qtd_PrzPolCom = @it_QtdPrzPolCom,
               Flg_PolPrm = @it_FlgPolPrm, 
               Prc_UniLiqPer = @it_PrcUniLiqPer,
               Prc_LiqUltEnt = @it_PrcLiqUltEnt,
               Prc_RefFpb = @it_PrcRefFpb,
               Cod_PrjPde = @it_CodPrjPde,
               Prc_UniPde = @it_PrcUniPde,
               Per_DscPde = @it_PerDscPde,
               Num_SeqPdc = @it_NumSeqPdc,
               Per_VrbPar = @it_PerVrbPar,
               Per_VrbBon = @it_PerVrbBon, 
               Vlr_Bonificacao = @it_VlrBonificacao,
               Vlr_DscBonRat = @it_VlrDscBonRat,
               Prc_CusMinComMarkup = @it_PrcCusMinComMarkup,
               Vlr_BasVerba = @it_VlrBasVerba
         Where Cod_Estabe = @PCodEstabe
           and Cod_Pedido = @PCodPed 
           and Cod_Produto = @PCodPrd 
           and Cod_Lote = @CodLotPri
           and Tip_Sai = @PTipSai
      end

    -- decrementa quantidade solicitada inicial
    Set @it_QtdSol = @it_QtdSol - @PQtdPed - @PQtdBon + @AccQtdAte + @AccBonAte

    -- calcula tributos      
    EXEC PR_CalcTributPdvit @PCodEstabe, @PCodPed, @PCodPrd, @CodLotPri, Tip_Sai
    if @@error <> 0
      begin
        Rollback Transaction
        Return
      end

  end  -- if ((@QtdDsp/@PFatCnvImpFat)*@PFatCnvImpFat) > 0

-- ajusta quantidade solicitada
if @it_QtdSol < 0
  Set @it_QtdSol = 0
if @it_QtdSol > 0 
  begin
    Update PDVIT
       Set Qtd_Solicitado = Qtd_Solicitado + @it_QtdSol
     Where Cod_Estabe = @PCodEstabe
       and Cod_Pedido = @PCodPed 
       And Cod_Produto = @PCodPrd 
       And Cod_Lote = @CodLotPri
       And Tip_Sai = @PTipSai
  end  

if (@QtdSolPrdIni + @WAccQtdTot) <>
   IsNull((Select IsNull(Qtd_Solici,0) From PRXES Where Cod_Estabe = @PCodEstabe And Cod_Produt = @PCodPrd),0) 
  begin
    RAISERROR('Erro na solicitação do Produto',16,1)
    Rollback Transaction
	Return
  end 

-- corrige quantidades solicitades de lotes não multiplos de fator de conversão do item
Exec dbo.PR_CorrigeQtdLoteProduto @PCodEstabe, @PCodPed, @PCodPrd
if @@error <> 0
  begin
    Rollback Transaction
    Return
  end
else
  Commit Transaction
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_RetornaItensNF]
@PCodEstabe int,
@PNumNota int,
@PSerNota varchar(3),
@PTipNota char(1)

AS

SET NOCOUNT ON 

Set dateformat ymd

IF OBJECT_ID('tempdb..#TMP_Itens') IS NOT NULL
  DROP TABLE #TMP_Itens
  
CREATE TABLE #TMP_Itens
(
    Chave int identity,
    Cod_Produto int,
    Num_SeqIte int,
    Num_SeqPdc varchar(6),
    Cod_EAN varchar(14),
    Tip_Sai varchar(1),
    Cod_NCM varchar(8),
    Cod_GrpPrc varchar(1),
    Cod_Cfo int,
    Tip_Por344 varchar(2),
    Tip_LisPis varchar(3),
    Des_Produto varchar(120),
    Obs_Produto varchar(500), 
    Und_Com varchar(12),
    Qtd_Com numeric(18,8),
    Prc_UniCom numeric(18,8),
    Vlr_TotBruIte numeric(18,8),
    Vlr_TotIte numeric(18,8),
    Per_Desconto numeric(18,8),
    Vlr_BasRepIcm numeric(18,8),
    Per_RepIcm numeric(7,4),
    Vlr_RepIcm numeric(18,8),
    Tip_Consumidor varchar(1),
    Vlr_DscTri numeric(18,8),
    Per_DscTri numeric(18,2),
    Vlr_DscRat numeric(18,8),
    Vlr_DscBonRat numeric(18,8),
    Vlr_DscTotIte numeric(18,8),
    Vlr_BasSbtRes numeric(18,8),
    Vlr_SbtRes numeric(18,8), 
    Vlr_BasSbtEmb numeric(18,8),
    Vlr_SbtEmb numeric(18,8), 
    Cod_Lote varchar(20), 
    Cod_LoteOri varchar(20), 
    Dat_Vencim datetime,
    Dat_Fabric datetime,
    Qtd_MesValid integer,
    Vlr_Frete numeric(18,8),
    Vlr_Seguro numeric(18,8),
    Vlr_DspRat numeric(18,8),
    Vlr_DspExt numeric(18,8), 
    Vlr_TotDsp numeric(18,8), 
    Und_Tri varchar(12),
    Qtd_Tri int,
    Prc_UniTri numeric(18,8),
    Cod_OriPrd varchar(1),
    Cod_CstIcm varchar(2),
    Cod_CsosnIcm varchar(3),
    Cod_ModBasCalIcm varchar(1),
    Per_RedBasCalIcm numeric(8,4),
    Vlr_BasIcm numeric(18,8),
    Alq_Icm numeric(8,4),
    Vlr_Icm numeric(18,8), 
    Dif_VlrIcm numeric(18,8), 
    Vlr_BasIcmPro numeric(18,8),
    Vlr_IcmPro numeric(18,8), 
    Per_IcmDiferi numeric(8,4),
    Vlr_IcmDiferi numeric(18,8), 
    Vlr_DscCalSuframa numeric(18,8),
    Vlr_IcmDesone numeric(18,8), 
    Cod_MtvIcmDesone varchar(1),
    Vlr_BasIcmSbtRet numeric(18,8), 
    Vlr_IcmSbtRet numeric(18,8),
    Cod_ModBasCalIcmSbt varchar(1),
    Alq_AgrSbt numeric(8,4), 
    Per_RedBasCalIcmSbt numeric(8,4),
    Vlr_BasIcmSbt numeric(18,8), 
    Alq_IcmSbt numeric(8,4),
    Vlr_IcmSbt numeric(18,8),
    CST_Ipi varchar(2), 
    Cod_EnqIpi varchar(3),
    Vlr_BasIpi numeric(18,8),
    Alq_Ipi numeric(8,4),
    Vlr_Ipi numeric(18,8),
    Vlr_BasDevIpi numeric(18,8),
    Per_DevIpi numeric(8,4),
    Vlr_DevIpi numeric(18,8), 
    CST_Pis varchar(2), 
    Vlr_BasPis numeric(18,8), 
    Alq_Pis numeric(8,4),
    Vlr_Pis numeric(18,8),
    Dif_VlrPis numeric(18,8),
    CST_Cofins varchar(2), 
    Vlr_BasCofins numeric(18,8), 
    Alq_Cofins numeric(8,4), 
    Vlr_Cofins numeric(18,8),
    Dif_VlrCofins numeric(18,8),
    Prc_MaxCon numeric(18,8),
    Prc_Fabric numeric(18,8),
    Des_Fabric varchar(25),
    Flg_DscItePdv bit,
    Prc_UniPdv numeric(18,8),
    Per_DscPdv numeric(8,4),
    Cod_CEST varchar(7),    
    Vlr_BasIcmDes numeric(18,8),
    Per_AcrAlqIntFcp numeric(8,4),
    Alq_IntDes numeric(8,4),
    Alq_Interesta numeric(8,4),
    Per_PrvParIcm numeric(8,4),
    Vlr_IcmFcpDes numeric(18,8),
    Vlr_IcmParDes numeric(18,8),
    Vlr_IcmParRem numeric(18,8),
    Cod_PedCmpCli varchar(20),
    Str_VolEmb varchar(50),
    Obs_IteNf varchar(200),
    Reg_MS varchar(20),
    Des_MtvIseRegMS varchar(255),

    Alq_FcpIcm numeric(8,4),
    Vlr_FcpIcm numeric(18,8),
    Alq_FcpSbt numeric(8,4), 
    Vlr_FcpSbt numeric(18,8), 
    Alq_FcpSbtRet numeric(8,4),
    Vlr_FcpSbtRet numeric(18,8),

    vBCSTRet numeric(18,8),
    pST numeric(8,4),
    vICMSSubstituto numeric(18,8),
    vICMSSTRet numeric(18,8),
    vBCFCPSTRet numeric(18,8),
    pFCPSTRet numeric(8,4), 
    vFCPSTRet numeric(18,8),
    pRedBCEfet numeric(8,4),
    vBCEfet numeric(18,8),
    pICMSEfet numeric(8,4),
    vICMSEfet numeric(18,8),

    cBenef varchar(10),
	
	nFCI varchar(36),
	pFCI numeric(18,8)
) 


Declare @Tab Table(
  ChaveTab Int Identity(1,1) PRIMARY KEY
, Obs_Fiscal varchar(800)
)

Declare @NumPdv int,
        @Chave int,
        @ChaveTab int,
        @CodPrd int,
        @SeqIte int,
        @CodLot varchar(20),
        @DatVct datetime,
        @DatFab datetime,
        @QtdMesVld integer,
        @WCodLotOri varchar(20),
        @WValDif numeric(18,8),
        @ParDif numeric(4,2),
        @WValLimDif numeric(18,8),

        @WStatusCab varchar(1),
        @WTipNotCab varchar(1),
        @WValCabRetCStat smallint,
        @WCodTipCon varchar(1),
        @WDatEmiCab datetime,
        @WValCabCodRegTri int,
        @WValCabTipConsumidor varchar(1),
        @WValCabUFEmi varchar(2),
        @WValCabUFDes varchar(2),
        @WValCabBasIcm numeric(18,8),
        @WValCabIcm numeric(18,8),
        @WValCabIcmPro numeric(18,8),
        @WValCabDscCom numeric(18,8),
        @WValCabDscBon numeric(18,8),
        @WValCabRepIcm numeric(18,8),
        @WValCabDscTri numeric(18,8),
        @WValCabBasIcmSbt numeric(18,8),
        @WValCabIcmSbt numeric(18,8),
        @WValCabBasSbtRes numeric(18,8),
        @WValCabSbtRes numeric(18,8),
        @WValCabSbtEmb numeric(18,8),
        @WValCabIpi numeric(18,8),
        @WValCabDevIpi numeric(18,8),
        @WValCabPis numeric(18,8),
        @WValCabCof numeric(18,8),
        @WValCabIcmParDes numeric(18,8), 
        @WValCabIcmParRem numeric(18,8),
        @WValCabCodCmpCli varchar(20),
        @WValCabIcmFcpDes numeric(18,8), 
        @WValCabFcpIcm numeric(18,8), 
        @WValCabFcpSbt numeric(18,8), 
        @WValCabFcpSbtRet numeric(18,8), 
        @WValCabDscSufram numeric(18,8), 
        @WCabObsRodape varchar(max),
        @WCabInsSufram varchar(9),

        @WDesProduto varchar(120),
        @WDesCplProduto varchar(max),
        @WTipLisPis varchar(3),
        @WVlrTotBruIte numeric(18,8),
        @WVlrTotLiqIte numeric(18,8),
        @WVlrDscTotIte numeric(18,8),
        @WVlrBasRepIcm numeric(18,8),
        @WPerRepIcm numeric(7,4),
        @WVlrRepIcm numeric(18,8),
        @WFlgDscItePdv bit,
        @WPrcUniPdv numeric(18,8),
        @WPerDscPdv numeric(8,4),
        @WPerDsc    numeric(8,4),
        @WVlrBasSbtRes numeric(18,8),
        @WVlrBasSbtEmb numeric(18,8),
        @WVlrSbtRes numeric(18,8), 
        @WVlrSbtEmb numeric(18,8),
        @WTipCon varchar(1),
        @WVlrDscTri numeric(18,8),
        @WPerDscTri numeric(18,2),
        @WPerDscIte numeric(18,2),
        @WDesFabric varchar(25),
        @WTipPor344 varchar(2),
        @WTipSai varchar(1),
        @WStrVolEmb varchar(50),
        @WObsIteNf varchar(800),
        @WPrcFabric numeric(18,8),
        @WPerParIcmDef numeric(8,4),
        @WPerAlqInterestaDef numeric(8,4),
        @WAlqIcm numeric(8,4),
        @WObsAux varchar(max),
        @WObsFis varchar(800)


-- normaliza PRODU
Update PRODU
   Set Reg_MS = IsNull(Reg_MS,'')
 Where Reg_MS <> Ltrim(Rtrim(Reg_MS))

-- preencher com zeros à esquerda até 13 posições
Update PRODU
Set Reg_MS = Substring('0000000000000',1,13-Len(Reg_MS))+Reg_MS
Where IsNull(Reg_MS,'') <> ''
And Len(IsNull(Reg_MS,'')) < 13 
And ISNULL(Reg_MS, '') <> 'ISENTO' 

-- parametros na memoria
Declare @pm_FlgImpDscEmbNot bit,
        @pm_CtrImpIteNotFis varchar(1),
        @pm_CodImpPrcFab varchar(1),
        @pm_CodImpDscFab varchar(1),
        @pm_CodImpPMC varchar(1),
        @pm_VerNfe varchar(20),
        @WSelect varchar(max)

Select @pm_FlgImpDscEmbNot = IsNull(FlgImpDscEmbNot,0),
       @pm_CtrImpIteNotFis = IsNull(Ctr_ImpIteNotFis,'') 
From PARAM 
Where Cod_Estabe = @PCodEstabe

Set @pm_CodImpPrcFab = Substring((Select LTrim(Val_Param) From FS_PARAM Where Cod_Estabe = @PCodEstabe and Cod_Param = 'NFE_CFG_DNF_PFABNFE'),1,1)
Set @pm_CodImpDscFab = Substring((Select LTrim(Val_Param) From FS_PARAM Where Cod_Estabe = @PCodEstabe and Cod_Param = 'NFE_CFG_DNF_IMPFBNFE'),1,1)
Set @pm_CodImpPMC = Substring((Select LTrim(Val_Param) From FS_PARAM Where Cod_Estabe = @PCodEstabe and Cod_Param = 'NFE_CFG_DNF_PMCNFE'),1,1)
-- versão da NF-e
Set @pm_VerNfe = Substring((Select Ltrim(Rtrim(Val_Param)) From FS_PARAM Where Cod_Estabe = @PCodEstabe and Cod_PARAM = 'NFE_CFG_VER'),1,20)
if (@pm_VerNfe <> '') and (charIndex('.',@pm_VerNfe) = 0)
  Set @pm_VerNfe = @pm_VerNfe + '.0'

-------------------------------------------------------------------------------------------------------------------------
if @PTipNota = 'S'
  begin

    -- atualiza IE cabecalho
    Update cb 
       Set cb.Cgf = cl.Cgf
     From NFSCB cb 
          Inner Join CLIEN cl on cb.Cod_Cliente = cl.Codigo
    Where cb.Cod_Estabe = @PCodEstabe 
      and cb.Ser_Nota = @PSerNota 
      and cb.Num_Nota = @PNumNota
      and cb.Cod_Cliente > 0
      And IsNull(cl.Cgf,'') <> ''
      And cb.Cgf <> cl.Cgf

    Update cb 
       Set cb.Inscricao_Suframa = cl.Inscricao_Suframa
      From NFSCB cb 
           Inner Join CLIEN cl on cb.Cod_Cliente = cl.Codigo
     Where cb.Cod_Estabe = @PCodEstabe 
       and cb.Ser_Nota = @PSerNota 
       and cb.Num_Nota = @PNumNota
       and cb.Cod_Cliente > 0
       And IsNull(cl.Inscricao_Suframa,'') <> ''
       And cb.Inscricao_Suframa <> cl.Inscricao_Suframa

    Update cb 
       Set cb.Cgf = fo.Cgf_Rg
      From NFSCB cb 
           Inner Join FORNE fo on cb.Cod_Fornecedor = fo.Codigo
     Where cb.Cod_Estabe = @PCodEstabe 
       and cb.Ser_Nota = @PSerNota 
       and cb.Num_Nota = @PNumNota
       and cb.Cod_Fornecedor > 0
       and IsNull(fo.Cgf_Rg,'') <> ''
       and cb.Cgf <> fo.Cgf_Rg

    Exec PR_CalcTributSTRetAntNFSCB @PCodEstabe, @PSerNota, @PNumNota

    -- monta mensagens NFS em NSCOB e NSIOB
    Exec PR_GeraMensagensNF @PCodEstabe, @PNumNota, @PSerNota, @PTipNota

    Select @NumPdv = IsNull(cb.Cod_Pedido,0), 
           @WStatusCab = IsNull(cb.Status,''),
           @WValCabRetCStat = IsNull(cb.Ret_CStat,0),
           @WTipNotCab = cb.Tip_Saida, 
           @WCodTipCon = dbo.FN_CodTipConsum (cb.Tip_Consumidor, '', cb.Cgc, cb.Cgf, cb.Estado),
           @WDatEmiCab = cb.Dat_Emissao,
           @WValCabCodRegTri = IsNull(cb.Cod_RegTri,0),
           @WValCabTipConsumidor = IsNull(cb.Tip_Consumidor,''),
           @WValCabUFEmi = IsNull(es.Des_Estado,''),
           @WValCabUFDes = IsNull(cb.Estado,''),
           @WValCabBasIcm = Round(IsNull(cb.Vlr_BasIcmsTri,0),2),
           @WValCabIcm = Round(IsNull(cb.Vlr_IcmsTri,0),2),
           @WValCabIcmPro = Round(IsNull(cb.Vlr_IcmsNor,0),2),
           @WValCabDscCom = Round(IsNull(cb.Vlr_DescontoCom,0),2),
           @WValCabDscBon = Round(IsNull(cb.Vlr_DscBon,0),2),
           @WValCabRepIcm = Round(IsNull(cb.Vlr_RepIcms,0),2),
           @WValCabDscTri = Round(IsNull(cb.Vlr_DscTri,0),2),
           @WValCabBasIcmSbt = Round(IsNull(cb.Vlr_BasSubsTrib,0),2),
           @WValCabIcmSbt = Round(IsNull(cb.Vlr_SubsTrib,0),2),
           @WValCabBasSbtRes = Round(IsNull(cb.Vlr_BasSbtRes,0),2),
           @WValCabSbtRes = Round(IsNull(cb.Vlr_SbtRes,0),2),
           @WValCabSbtEmb = Round(IsNull(oc.Vlr_SubsTrib,0),2),  -- aqui pode ser Vlr_SbtRes, recalcular este valor
           @WValCabIpi = Case When (cb.Tip_Saida = 'D') and (IsNull(cb.Vlr_Ipi,0) > 0) then 0 Else Round(IsNull(cb.Vlr_Ipi,0),2) End, 
           @WValCabDevIpi = Case When (cb.Tip_Saida = 'D') and (IsNull(cb.Vlr_Ipi,0) > 0) then Round(IsNull(cb.Vlr_Ipi,0),2) Else 0 End, 
           @WValCabPis = Round(IsNull(cb.Vlr_Pis,0),2),
           @WValCabCof = Round(IsNull(cb.Vlr_Cofins,0),2),
           @WValCabIcmParDes = Round(IsNull(cb.Vlr_IcmParDes,0),2), 
           @WValCabIcmParRem = Round(IsNull(cb.Vlr_IcmParRem,0),2),
           @WValCabCodCmpCli = IsNull(cb.Ide_PedCmp,''),
           @WValCabIcmFcpDes = Round(IsNull(cb.Vlr_IcmFcpDes,0),2), 
           @WValCabFcpIcm = Round(IsNull(cb.Vlr_FcpIcm,0),2), 
           @WValCabFcpSbt = Round(IsNull(cb.Vlr_FcpSbt,0),2), 
           @WValCabFcpSbtRet = Round(IsNull(cb.Vlr_FcpSbtRet,0),2),
           @WValCabDscSufram = Round(IsNull(cb.Vlr_DscCalSuframa,0),2),
           @WCabObsRodape = IsNull(cb.Obs_Rodape,''),
           @WCabInsSufram = IsNull(cb.Inscricao_Suframa,'?')
      From NFSCB cb 
           Inner Join ESTAB es on cb.Cod_Estabe = es.Cod_Estabe
           left join NSOCB oc on ((cb.Cod_Estabe = oc.Cod_Estabe) and (cb.Ser_Nota = oc.Ser_Nota) and (cb.Num_Nota = oc.Num_Nota))       
     Where cb.Cod_Estabe = @PCodEstabe 
       and cb.Ser_Nota = @PSerNota 
       and cb.Num_Nota = @PNumNota

/* aqui registros em NSCOB montados em uFiscal

    -- Observacao cabeçalho
    Set @WObsAux = Ltrim(Rtrim(@WCabObsRodape))

    Delete From @Tab


    Insert Into @Tab (Obs_Fiscal)
      Select Des_Observ From NSCOB
       Where Cod_Estabe = @PCodEstabe 
         and Ser_Nota = @PSerNota 
         and Num_Nota = @PNumNota

    While Exists(Select 1 From @Tab)
      begin
        Select top 1
               @ChaveTab = ChaveTab
             , @WObsFis = Obs_Fiscal
          From @Tab
         Order by ChaveTab

        if PatIndex(@WObsFis+'%', @WObsAux) = 0
          begin
            if (Len(@WObsAux) > 0) and
               (Substring(@WObsAux,1,Len(@WObsAux)) <> ';')
              Set @WObsAUx = @WObsAux + ';  '

            Set @WObsAux = @WObsAux + @WObsFis
          end

        Delete From @Tab Where ChaveTab = @ChaveTab
      end

    -- FECOP Icms
    if (@WValCabFcpIcm > 0) and  -- NFSCB: Vlr_FcpIcm, Vlr_BasIcmsNor
       (PatIndex('%B.Calculo Fecop%', @WObsAux) = 0)
      begin
        if (Len(@WObsAux) > 0) and
           (Substring(@WObsAux,1,Len(@WObsAux)) <> ';')
          Set @WObsAUx = @WObsAux + ';  '

        Set @WObsAux = @WObsAux + 
                               'B.Calculo Fecop: '+cast(cast(Round(@WValCabIcmPro,2) as money) as varchar)+' '+
                       'Vlr.Fecop: '+cast(cast(Round(@WValCabFcpIcm,2) as money) as varchar) -- +char(13)+char(10)
      end

    -- FECOP ST
    if (@WValCabFcpSbt > 0) and  -- NFSCB.Vlr_FcpSbt
       (PatIndex('%B.Calc.Fecop ST%', @WObsAux) = 0)
      begin
        if (Len(@WObsAux) > 0) and
           (Substring(@WObsAux,1,Len(@WObsAux)) <> ';')
          Set @WObsAUx = @WObsAux + ';  '

        Set @WObsAux = @WObsAux + 
                               'B.Calc.Fecop ST: '+cast(cast(Round(@WValCabBasIcmSbt,2) as money) as varchar)+' '+
                       'Vlr.Fecop ST: '+cast(cast(Round(@WValCabFcpSbt,2) as money) as varchar) -- +char(13)+char(10)
      end

    -- SUFRAMA
        -- Conforme ICM (65/88) e Lei 10.966/2004 Art 2º desconto de R$ 99,99 aplicado ref. isenção ICMS - 12% Suframa destinatário XXXXXXXXX
    if (@WValCabDscSufram > 0) and
       (PatIndex('%Lei 10.966/2004%', @WObsAux) = 0)
      begin
        Set @WAlqIcm = 0

        -- pegar alq de um item suframa....  
        Select Top 1 @WAlqIcm = Case When (@WTipNotCab <> 'D') then Isnull(rx.Alq_IcmExtLoc,0) Else Isnull(rx.Alq_IcmExtReg,0) End
          From NFSIT it
               inner Join RTXCT rx on rx.Cod_RegTri = @WValCabCodRegTri and rx.Cod_ClaTri = it.Cod_ClaTri
         Where IsNull(it.Vlr_DscCalSuframa,0) > 0 

        if (Len(@WObsAux) > 0) and
           (Substring(@WObsAux,1,Len(@WObsAux)) <> ';')
          Set @WObsAUx = @WObsAux + ';  '

        Select @WObsAux = @WObsAux +
                          'Conforme ICM (65/88) e Lei 10.966/2004 Art 2º '+
                          'desconto de '+cast(cast(Round(@WValCabDscSufram,2) as money) as varchar)+' '+
                          'aplicado ref. isenção ICMS - '+cast(cast(Round(@WAlqIcm,2) as money) as varchar)+'% '+
                          'destinatario '+cl.Razao_Social  -- +char(13)+char(10)
             From NFSCB cb 
                  Inner Join CLIEN cl on cb.Cod_CLiente = cl.Codigo
             Where cb.Cod_Estabe = @PCodEstabe
             And cb.Ser_Nota = @PSerNota
             And cb.Num_Nota = @PNumNota
      end

    if @WObsAux <> ''
      Update NFSCB
        Set Obs_Rodape = @WObsAux
      Where Cod_Estabe = @PCodEstabe
      And Ser_Nota = @PSerNota
      And Num_Nota = @PNumNota

*/

    if Exists(Select 1 From NFSIT it Inner Join PRODU pr on pr.Codigo = it.Cod_Produto
               Where it.Cod_Estabe = @PCodEstabe
                 And it.Num_Nota = @PNumNota
                 And it.Ser_Nota = @PSerNota
                 And IsNull(it.Cod_NCM,'') <> cast(Substring(IsNull(pr.Cod_ClaFis,''),1,8) as varchar))
      begin
        Exec PR_RecalculaPisCofins @PCodEstabe, @PNumNota, @PSerNota, @PTipNota
        if @@error <> 0
          begin
            Rollback Transaction
            Return
          end
      end

    Update it
       Set it.Cod_NCM = cast(Substring(IsNull(pr.Cod_ClaFis,''),1,8) as varchar)
      From NFSIT it
           Inner Join PRODU pr on pr.Codigo = it.Cod_Produto
     Where it.Cod_Estabe = @PCodEstabe
       And it.Num_Nota = @PNumNota
       And it.Ser_Nota = @PSerNota
       And IsNull(it.Cod_NCM,'') <> cast(Substring(IsNull(pr.Cod_ClaFis,''),1,8) as varchar)
       And ((@WValCabRetCStat <> 100) and (@WValCabRetCStat <> 101) and (@WValCabRetCStat <> 102))
       And @WStatusCab <> 'C'

    Update it
       Set it.Cod_CEST = cast(Substring(IsNull(pr.Cod_CEST,''),1,7) as varchar)
      From NFSIT it
           Inner Join PRODU pr on pr.Codigo = it.Cod_Produto
     Where it.Cod_Estabe = @PCodEstabe
       And it.Num_Nota = @PNumNota
       And it.Ser_Nota = @PSerNota
       And IsNull(it.Cod_CEST,'') <> cast(Substring(IsNull(pr.Cod_CEST,''),1,7) as varchar)
       And ((@WValCabRetCStat <> 100) and (@WValCabRetCStat <> 101) and (@WValCabRetCStat <> 102))
       And @WStatusCab <> 'C'

    Update it
       Set it.Cod_GrpPrc = IsNull(pr.Cod_GrpPrc,'')
      From NFSIT it
           Inner Join PRODU pr on pr.Codigo = it.Cod_Produto
     Where it.Cod_Estabe = @PCodEstabe
       And it.Num_Nota = @PNumNota
       And it.Ser_Nota = @PSerNota
--       And IsNull(it.Cod_GrpPrc,'') = ''
       And it.Cod_GrpPrc <> IsNull(pr.Cod_GrpPrc,'')
       And ((@WValCabRetCStat <> 100) and (@WValCabRetCStat <> 101) and (@WValCabRetCStat <> 102))
       And @WStatusCab <> 'C'

    Update it
       Set it.Cod_OriMer = IsNull(pr.Cod_OriMer,'0')
      From NFSIT it
           Inner Join PRXES pr on pr.Cod_Estabe = it.Cod_Estabe and pr.Cod_Produt = it.Cod_Produto
     Where it.Cod_Estabe = @PCodEstabe
       And it.Num_Nota = @PNumNota
       And it.Ser_Nota = @PSerNota
--       And IsNull(it.Cod_OriMer,'') = ''
       And it.Cod_OriMer <> IsNull(pr.Cod_OriMer,'0')
       And ((@WValCabRetCStat <> 100) and (@WValCabRetCStat <> 101) and (@WValCabRetCStat <> 102))
       And @WStatusCab <> 'C'


    -- atualiza dados faturamento por peso/volume
    Update it
      Set it.Des_UnvPesVolImpFat = ap.Des_UndPesVolApr,
          it.Qtd_PesVolImpFat = (it.Qtd_Produto+it.Qtd_Bonificacao)/it.Fat_CnvImpFat*ap.Qtd_PesVolApr,
          it.Prc_UniPesVolImpFat = it.Prc_Unitario*it.Fat_CnvImpFat/ap.Qtd_PesVolApr
    From NFSIT it 
         Inner Join PARAM pm on it.Cod_Estabe = pm.Cod_Estabe
         Inner Join PRXAP ap on it.Cod_Produto = ap.Cod_Produt and it.Fat_CnvImpFat = ap.Fat_CnvApr
    Where it.Cod_Estabe = @PCodEstabe
    And it.Num_Nota = @PNumNota
    And it.Ser_Nota = @PSerNota
    And it.Fat_CnvImpFat > 0
    And IsNull(it.Des_UnvImpFat,'') = IsNull(ap.Des_UnvApr,'')
    And IsNull(pm.FlgAltUnvItePdv,0) = 1
    And ((IsNull(ap.Flg_FatPes,0) = 1) or (IsNull(ap.Flg_FatVol,0) = 1))
    And IsNull(ap.Qtd_PesVolApr,0) > 0


    -- % FCP default
    Set @WPerParIcmDef = IsNull((Select max(Per_PrvParIcm)
                                 From NFSIT
                                 Where Cod_Estabe = @PCodEstabe
                                 And Num_Nota = @PNumNota
                                 And Ser_Nota = @PSerNota),0)
      
    -- 7%  UF Emissao: Sul e SE exceto ES:  ';MG;RJ;SP;PR;SC;RS;'
    --        Destino: N, NE e ES
    if (Charindex(@WValCabUFEmi,';MG;RJ;SP;PR;SC;RS;') > 0) and   -- S, SE, exceto ES
           (Charindex(@WValCabUFDes,';MG;RJ;SP;PR;SC;RS;') = 0)       -- N, NE e ES
      Set @WPerAlqInterestaDef = 7.00
    else
      Set @WPerAlqInterestaDef = 12.00


    -- atualiza cBenef NFSIT: UF Emitente
    -- Exige o código de benefício fiscal (cBenef) quando se utiliza um CST de benefício fiscal (20, 30, 40, 41, 50, 51, 60 ou 90).
        -- verifica beneficio por NCM
        -- devolucao ?????
/*
    Update it
      Set it.cBenef = ''
    From NFSIT it
    Where it.Cod_Estabe = @PCodEstabe
    And it.Num_Nota = @PNumNota
    And it.Ser_Nota = @PSerNota

    Update it
      Set it.cBenef = IsNull(un.Cod_Benefe,'')
    From NFSIT it
         Inner JOIN UFNCM un on (un.Cod_UF = @WValCabUFEmi) and (un.Cod_NCM = Substring(it.Cod_NCM,1,Len(IsNull(un.Cod_NCM,''))))
    Where it.Cod_Estabe = @PCodEstabe
    And it.Num_Nota = @PNumNota
    And it.Ser_Nota = @PSerNota
    And IsNull(un.Cod_Benefe,'') <> ''
--    And Charindex(it.Ctrl_Tributacao,';20;30;40;41;50;51;60;90;') > 0
    And Charindex(it.Ctrl_Tributacao,dbo.FN_ListaCSTBeneficio(un.Cod_Benefe)) > 0
    And Len(IsNull(un.Cod_NCM,'')) < 8

    Update it
      Set it.cBenef = IsNull(un.Cod_Benefe,'')
    From NFSIT it
         Inner JOIN UFNCM un on un.Cod_UF = @WValCabUFEmi and un.Cod_NCM = it.Cod_NCM
    Where it.Cod_Estabe = @PCodEstabe
    And it.Num_Nota = @PNumNota
    And it.Ser_Nota = @PSerNota
    And IsNull(un.Cod_Benefe,'') <> ''
    And Charindex(it.Ctrl_Tributacao,dbo.FN_ListaCSTBeneficio(un.Cod_Benefe)) > 0

        -- verifica beneficio por Produto
    Update it
      Set it.cBenef = IsNull(up.Cod_Benefe,'')
    From NFSIT it
         Inner JOIN UFXPR up on up.Cod_UF = @WValCabUFEmi and up.Cod_Produt = it.Cod_Produto
    Where it.Cod_Estabe = @PCodEstabe
    And it.Num_Nota = @PNumNota
    And it.Ser_Nota = @PSerNota
    And IsNull(up.Cod_Benefe,'') <> ''
    And Charindex(it.Ctrl_Tributacao,dbo.FN_ListaCSTBeneficio(up.Cod_Benefe)) > 0
*/

    Update it
       Set it.cBenef = dbo.FN_RetornaCBenef(@WValCabUFEmi, it.Ctrl_Tributacao, it.Cod_NCM, it.Cod_Produto, @WDatEmiCab)
     From NFSIT it
    Where it.Cod_Estabe = @PCodEstabe
      And it.Num_Nota = @PNumNota
      And it.Ser_Nota = @PSerNota

   -- paleativo: corrige CST 90 para não contribuintes
    Update it
       Set it.Ctrl_Tributacao = '41'
      From NFSIT it
     Where it.Cod_Estabe = @PCodEstabe
       And it.Num_Nota = @PNumNota
       And it.Ser_Nota = @PSerNota
       And @WCodTipCon = 'N'
       And it.Ctrl_Tributacao = '90'

   -- paleativo: corrige % Repasse enquanto este % não for determinado pela procedure PR_CalTributItem....
    Update it
       Set it.Per_RepIcms = Case
                              When it.Vlr_RepIcms = 0 then 0
                              When (IsNull(rx.Cod_RegTri,0) > 0) and (@WTipNotCab <> 'D') then Round(rx.C_PerRepIcmLoc,2)
                              When (IsNull(rx.Cod_RegTri,0) > 0) and (@WTipNotCab  = 'D') then Round(rx.C_PerRepIcmReg,2)
                              -- Diego: Forçando o valor para a Neosul (Clamed) Temporário, rever com o Cládio
                              When (IsNull(it.Vlr_BasRepIcms,0) > 0) and (Round(it.Vlr_RepIcms*100/it.Vlr_BasRepIcms,2) > 14) then 14.58
                              When (IsNull(it.Vlr_BasRepIcms,0) > 0) and (Round(it.Vlr_RepIcms*100/it.Vlr_BasRepIcms,2) >  6) then  6.82
                              When IsNull(it.Vlr_BasRepIcms,0) > 0 then Round(it.Vlr_RepIcms*100/it.Vlr_BasRepIcms,2)
                              Else 0
                            End
      From NFSIT it
           left Join RTXCT rx on rx.Cod_RegTri = @WValCabCodRegTri and rx.Cod_ClaTri = it.Cod_ClaTri
     Where it.Cod_Estabe = @PCodEstabe
       And it.Num_Nota = @PNumNota
       And it.Ser_Nota = @PSerNota
       And IsNull(it.Per_RepICms,0) = 0

    Insert Into #TMP_Itens
      Select it.Cod_Produto, it.Num_SeqIte,
             Num_SeqPdc = Case 
                            When IsNull(it.Num_SeqPdc,'') <> '' then Substring(IsNull(it.Num_SeqPDc,''),1,6)
                            Else Substring(Cast(it.Num_SeqIte as varchar),1,6)
                          End,
             Cod_EAN = Case 
                         When (IsNull(pr.Cod_Ean, '') = '') and Exists(Select 1 From PREAN pe Where pr.Codigo = pe.Cod_Produt And pe.Tip_Cod = '3') Then
                             (Select top 1 IsNull(pe.Cod_Ean, '') 
                                From PREAN pe 
                               Where pr.Codigo = pe.Cod_Produt 
                                 And pe.Tip_Cod = '3'
                                 And len(pe.Cod_Ean) > 1 
                               Order by len(pe.Cod_Ean) Desc)
                         When (IsNull(pr.Cod_Ean, '') = '') and Exists(Select 1 From PREAN pe  Where pr.Codigo = pe.Cod_Produt And pe.Tip_Cod = '4') Then
                             (Select top 1 IsNull(pe.Cod_Ean, '') 
                                From PREAN pe 
                               Where pr.Codigo = pe.Cod_Produt 
                                 And pe.Tip_Cod = '4'
                                 And len(pe.Cod_Ean) > 1 
                               Order by len(pe.Cod_Ean) Desc)
                         Else IsNull(pr.Cod_Ean,'')
                       End,
             Tip_Sai = IsNull(it.Tip_Sai,''),
             Cod_NCM = IsNull(it.Cod_NCM,''),
             Cod_GrpPrc = IsNull(it.Cod_GrpPrc,''),
             it.Cod_Cfo, 
             Tip_Por344 = IsNull(pr.Tip_Por344,''),
             Tip_LisPis = ISNull(it.Tip_Aux,''),
             Des_Produto = Case 
                             When ix.Cod_Produt > 0 then Substring(ix.Des_PrdDet,1,120) 
                             When IsNull(it.Des_AprImpFat,'') <> '' then rtrim(pr.Descri)+' '+it.Des_AprImpFat
                             Else pr.Descricao
                           End,
             Obs_Produto = '', 

             Und_Com = Case
                         When IsNull(it.Qtd_PesVolImpfat,0) > 0 then it.Des_UnvPesVolImpFat
                             When (IsNull(it.Qtd_ImpFat,0) > 0) and (IsNull(it.Prc_UniImpFat,0) > 0) and (IsNull(it.Des_UnvImpFat,'') <> '') and
                              (not Exists(Select 1 From NFSIT 
                                           Where Cod_Estabe = it.Cod_Estabe 
                                             And Ser_Nota = it.Ser_Nota And Num_Nota = it.Num_Nota
                                             And Cod_Produto = it.Cod_Produto
                                             And Qtd_ImpFat-cast(Qtd_ImpFat as integer) <> 0)) then it.Des_UnvImpFat
                         When ((ix.Cod_Produt > 0) and (IsNull(ix.Des_UndVen,'') <> '')) then ix.Des_UndVen
                         Else pr.Unidade_Venda
                       End,
             Qtd_Com = Case 
                         When IsNull(it.Qtd_PesVolImpfat,0) > 0 then it.Qtd_PesVolImpfat
                             When (IsNull(it.Qtd_ImpFat,0) > 0) and (IsNull(it.Prc_UniImpFat,0) > 0) and
                              (not Exists(Select 1 From NFSIT 
                                           Where Cod_Estabe = it.Cod_Estabe 
                                             And Ser_Nota = it.Ser_Nota And Num_Nota = it.Num_Nota
                                             And Cod_Produto = it.Cod_Produto
                                             And Qtd_ImpFat-cast(Qtd_ImpFat as integer) <> 0)) then Qtd_ImpFat
                         Else IsNull(it.Qtd_Produto,0)+IsNull(it.Qtd_Bonificacao,0)
                       end,

             Prc_UniCom = Case 
                            When IsNull(it.Qtd_PesVolImpfat,0) > 0 then it.Prc_UniPesVolImpFat
                                When (IsNull(it.Qtd_ImpFat,0) > 0) and (IsNull(it.Prc_UniImpFat,0) > 0) and
                                 (not Exists(Select 1 From NFSIT 
                                              Where Cod_Estabe = it.Cod_Estabe 
                                                And Ser_Nota = it.Ser_Nota And Num_Nota = it.Num_Nota
                                                And Cod_Produto = it.Cod_Produto
                                                And Qtd_ImpFat-cast(Qtd_ImpFat as integer) <> 0)) then it.Prc_UniImpFat
                            Else IsNull(it.Prc_Unitario,0)
                          end,

             Vlr_TotBruIte = Round(IsNull(it.Prc_Unitario,0)*(IsNull(it.Qtd_Produto,0)+IsNull(it.Qtd_Bonificacao,0)),2),
--             Vlr_TotIte = Round(IsNull(it.Qtd_Produto,0)*(IsNull(it.Prc_Unitar,0)*(1-IsNull(it.Per_Desconto,0)/100)),2),
--             Vlr_TotIte = Round(IsNull(it.Vlr_TotItem,0),2),
             Vlr_TotIte = Case
                            When Round(IsNull(it.Vlr_TotItem,0),2) <= Round(IsNull(it.Prc_Unitario,0)*(IsNull(it.Qtd_Produto,0)+IsNull(it.Qtd_Bonificacao,0)),2)
                                 Then Round(IsNull(it.Vlr_TotItem,0),2) 
                            Else Round(IsNull(it.Prc_Unitario,0)*(IsNull(it.Qtd_Produto,0)+IsNull(it.Qtd_Bonificacao,0)),2)
                          End,
             Per_Desconto = IsNull(it.Per_Desconto,0),
             Vlr_BasRepIcm = IsNull(it.Vlr_BasRepIcms,0),
             Per_RepIcm = IsNull(it.Per_RepIcms,0),
             Vlr_RepIcm = Round(IsNull(it.Vlr_RepIcms,0),2),
             Tip_Consumidor = @WValCabTipConsumidor,
             Vlr_DscTri = Round(IsNull(it.Vlr_DscTri,0),2),
                         Per_DscTri = IsNull(it.Per_DscTri,0),
             Vlr_DscRat = Round(IsNull(it.Vlr_DescRateado,0),2),
             Vlr_DscBonRat = Round(IsNull(it.Vlr_DscBonRat,0),2),
             Vlr_DscTotIte = 0,
             Vlr_BasSbtRes = Round(IsNull(it.Vlr_BasSbtRes,0),2),        
             Vlr_SbtRes = Round(IsNull(it.Vlr_SbtRes,0),2), 
             Vlr_BasSbtEmb = Round(IsNull(oi.Vlr_BasSubsTrib,0),2),
             Vlr_SbtEmb = Round(IsNull(oi.Vlr_SubsTrib,0),2),
             it.Cod_Lote, 
             it.Cod_Lote, 
             IsNull(lt.Dat_Vencim,0),
             IsNull(lt.Dat_Fabric,0),
             IsNull(pr.Validade,0),
             Vlr_Frete  = Round(IsNull(it.Vlr_Frete,0),2),
             Vlr_Seguro = Round(IsNull(it.Vlr_Seguro,0),2),
             Vlr_DspRat = Round(IsNull(it.Vlr_DespRateada,0),2),
             Vlr_DspExt = Round(IsNull(it.Vlr_DspExt,0),2),
             Vlr_TotDsp = 0,
             Und_Tri = pr.Unidade_Venda,
             Qtd_Tri = IsNull(it.Qtd_Produto,0)+IsNull(it.Qtd_Bonificacao,0),
             Prc_UniTri = IsNull(it.Prc_Unitario,0),          
             Cod_OriPrd = IsNull(it.Cod_OriMer,'0'),
             Cod_CstIcm = IsNull(it.Ctrl_Tributacao,''),
             Cod_CsosnIcm = IsNull(it.Cod_CSOSN,''),
             Cod_ModBasCalIcm = IsNull(it.Cod_ModBasCalIcm,''),
             Per_RedBasCalIcm = IsNull(it.Per_RedBasCalIcm,0),
             Vlr_BasIcm = Round(IsNull(it.Vlr_BasIcmsTri,0),2),
             Alq_Icm = IsNull(it.Alq_Icms,0),
             Vlr_Icm = Round(IsNull(it.Vlr_IcmsTri,0),2),
             Dif_VlrIcm = Round(IsNull(it.Vlr_IcmsTri,0),2) - IsNull(it.Vlr_IcmsTri,0),
             Vlr_BasIcmPro = Round(IsNull(it.Vlr_BasIcmsNor,0),2),
             Vlr_IcmPro = Round(IsNull(it.Vlr_IcmsNor,0),2),
             Per_IcmDiferi = IsNull(it.Per_IcmDiferi,0),
             Vlr_IcmDiferi = Round(IsNull(it.Vlr_IcmDiferi,0),2),
             Vlr_DscCalSuframa = Round(IsNull(it.Vlr_DscCalSuframa,0),2),
             Vlr_IcmDesone = IsNull(it.Vlr_IcmsDeson,0), 
             Cod_MtvIcmDesone = IsNull(it.Cod_MtvIcmsDeson,''),
             Vlr_BasIcmSbtRet = 0,
             Vlr_IcmSbtRet = 0,  --IsNull(oi.Vlr_SubsTrib,0),
             Cod_ModBasCalIcmSbt = IsNull(it.Cod_ModBasCalIcmSbt,''),
             Alq_AgrSbt = IsNull(it.Alq_AgrSbt,0), 
             Per_RedBasCalIcmSbt = IsNull(it.Per_RedBasCalIcmSbt,0),
             Vlr_BasIcmSbt = Round(IsNull(it.Vlr_BasSubsTrib,0),2),
             Alq_IcmSbt = IsNull(it.Alq_IcmSbt,0),
             Vlr_IcmSbt = Round(IsNull(it.Vlr_SubsTrib,0),2),

             CST_Ipi    = Case When IsNull(CST_Ipi,'') = '' then '99' Else CST_Ipi End, -- outras
                         Cod_EnqIpi = Case When IsNull(Cod_EnqIpi,'') = '' then '999' Else Cod_EnqIpi End,
                         Vlr_BasIpi = Case When (@WTipNotCab = 'D') and (IsNull(it.Vlr_BasIpi,0) > 0) then 0 Else Round(IsNull(it.Vlr_BasIpi,0),2) End,
             Alq_Ipi    = Case When (@WTipNotCab = 'D') and (IsNull(it.Vlr_Ipi,0) > 0) then 0 
                               Else Case When it.Vlr_TotItem > 0 then (it.Vlr_Ipi * 100 / it.Vlr_TotItem) Else 0 End End, 
             Vlr_Ipi    = Case When (@WTipNotCab = 'D') and (IsNull(it.Vlr_Ipi,0) > 0) then 0 Else IsNull(it.Vlr_Ipi,0) End, 
                         Vlr_BasDevIpi = Case When (@WTipNotCab = 'D') and (IsNull(it.Vlr_BasIpi,0) > 0) then Round(IsNull(it.Vlr_BasIpi,0),2) Else 0 End,
             Per_DevIpi = Case When (@WTipNotCab = 'D') and (IsNull(it.Vlr_Ipi,0) > 0) then 100.00 Else 0 End,
             Vlr_DevIpi = Case When (@WTipNotCab = 'D') and (IsNull(it.Vlr_Ipi,0) > 0) then it.Vlr_Ipi Else 0 End,

             it.CST_Pis, it.Vlr_BasPis, it.Alq_Pis, Vlr_Pis = Round(IsNull(it.Vlr_Pis,0),2), 
             Dif_VlrPis = Round(IsNull(it.Vlr_Pis,0),2)-IsNull(it.Vlr_Pis,0), 
             it.CST_Cofins, it.Vlr_BasCofins, it.Alq_Cofins, Vlr_Cofins = Round(IsNull(it.Vlr_Cofins,0),2),
             Dif_VlrCofins = Round(IsNull(it.Vlr_Cofins,0),2)-IsNull(it.Vlr_Cofins,0),
             Prc_MaxCon = Case
                            When @pm_CodImpPMC = '1' then IsNull(it.Prc_MaxCon,0)*IsNull(it.Fat_CnvImpFat,1)
                            Else 0
                          End, 
             Prc_Fabric = IsNull(it.Prc_Fabric,0)*IsNull(it.Fat_CnvImpFat,1), 
             Des_Fabric = Case 
                             When (ix.Cod_Produt > 0) and (IsNull(ix.Des_Fabric,'') <> '') then Substring(ix.Des_Fabric,1,25) 
                             Else Substring(fb.Fantasia,1,25)
                           End,
             Flg_DscItePdv = IsNull(it.Flg_DscItePdv,0),
             Prc_UniPdv = ISNULL(it.Prc_UniPdv,0),
             Per_DscPdv = ISNULL(it.Per_DscPdv,0),
             Cod_CEST = ISNULL(it.Cod_CEST,''),
  
             Vlr_BasIcmDes = Case 
                               When (@WPerParIcmDef > 0) or (IsNull(it.Vlr_IcmFcpDes,0) > 0) then Round(IsNull(it.Vlr_BasIcmsNor,0),2) 
                               Else 0
                             End,
             Per_AcrAlqIntFcp = Case
                                  When (ISNULL(it.Per_PrvParIcm,0) > 0) and (IsNull(it.Vlr_IcmFcpDes,0) > 0) then ISNULL(it.Per_AcrAlqIntFcp,0) 
                                  Else 0
                                End,
             Alq_IntDes = Case 
                            When (@WPerParIcmDef > 0) then ISNULL(it.Alq_IntIcmDes,0)
                            Else 0
                          End,
             Alq_Interesta = Case
                               When (@WPerParIcmDef > 0) and (it.Cod_OriMer IN ('1', '2', '3', '8')) then 4.0 /* DMD-8037: Regra NA09-20 */
							   When (@WPerParIcmDef > 0) and (ISNULL(it.Alq_Icms,0) > 0) then ISNULL(it.Alq_Icms,0)
                               When (@WPerParIcmDef > 0) and (ISNULL(it.Alq_Icms,0) = 0) then @WPerAlqInterestaDef							   
                               Else 0
                             End,
             Per_PrvParIcm = Case 
                               When (@WPerParIcmDef > 0) or (IsNull(it.Vlr_IcmFcpDes,0) > 0) then @WPerParIcmDef 
                               Else 0 
                             End, 
             Vlr_IcmFcpDes = Round(IsNull(it.Vlr_IcmFcpDes,0),2), 
             Vlr_IcmParDes = Round(IsNull(it.Vlr_IcmParDes,0),2), 
             Vlr_IcmParRem = Round(IsNull(it.Vlr_IcmParRem,0),2),
             Cod_PedCmpCli = @WValCabCodCmpCli,
             Str_VolEmb = IsNull(it.Str_VolEmb,''),
             Obs_IteNf = IsNull(it.Obs_Nf,''),
             Reg_MS = IsNull(pr.Reg_MS,''),
             Des_MtvIseRegMS = Substring(IsNull(pr.Des_MtvIseRegMS,''),1,255),

             Alq_FcpIcm = IsNull(it.Alq_FcpIcm,0),
             Vlr_FcpIcm = Round(IsNull(it.Vlr_FcpIcm,0),2),
             Alq_FcpSbt = IsNull(it.Alq_FcpSbt,0),
             Vlr_FcpSbt = Round(IsNull(it.Vlr_FcpSbt,0),2),
             Alq_FcpSbtRet = IsNull(it.Alq_FcpSbtRet,0),
             Vlr_FcpSbtRet = Round(IsNull(it.Vlr_FcpSbtRet,0),2),

             vBCSTRet = IsNull(it.vBCSTRet,0),
             pST = IsNull(it.pST,0),
             vICMSSubstituto = IsNull(it.vICMSSubstituto,0),
             vICMSSTRet = IsNull(it.vICMSSTRet,0),
             vBCFCPSTRet = IsNull(it.vBCFCPSTRet,0),
             pFCPSTRet = IsNull(it.pFCPSTRet,0), 
             vFCPSTRet = Round(IsNull(it.vFCPSTRet,0),2),

             pRedBCEfet = Case When @WValCabTipConsumidor = 'F' then IsNull(it.pRedBCEfet,0) Else 0 End,  -- somente para consumidor final: @WValCabTipConsumidor
             vBCEfet    = Case When @WValCabTipConsumidor = 'F' then IsNull(it.vBCEfet,0)    Else 0 End,
             pICMSEfet  = Case When @WValCabTipConsumidor = 'F' then IsNull(it.pICMSEfet,0)  Else 0 End,
             vICMSEfet  = Case When @WValCabTipConsumidor = 'F' then IsNull(it.vICMSEfet,0)  Else 0 End,

             cBenef = IsNull(it.cBenef,''),
			 
			 nFCI = IsNull(pr.Cod_FCI,''),
			 pFCI = IsNull(pr.Per_FCI,0) 

      From NFSIT it
           Inner Join PRODU pr on pr.Codigo = it.Cod_Produto
           Inner Join FABRI fb on fb.Codigo = pr.Cod_Fabricante
           left  join NSOIT oi on ((it.Cod_Estabe = oi.Cod_Estabe) and (it.Ser_Nota = oi.Ser_Nota) and (it.Num_Nota = oi.Num_Nota)       
                              and (it.Cod_Produto = oi.Cod_Produto) and (it.Cod_Lote = oi.Cod_Lote) and (it.Num_SeqIte = oi.Num_SeqIte)) 
           left  join ITDES ix on ((it.Cod_Estabe = ix.Cod_Estabe) and (ix.Num_Pedido = @NumPdv) and (it.Cod_Produto = ix.Cod_Produt)) 
           left  Join (Select Cod_Estabe, Cod_Produt, Cod_Lote,
                              Dat_Vencim = MIN(Dat_Vencim), Dat_Fabric = MIN(Dat_Fabric) 
                        From PRLOT 
                       Where Cod_Estabe = @PCodEstabe
                       Group by Cod_Estabe, Cod_Produt, Cod_Lote) lt on ((it.Cod_Estabe = lt.Cod_Estabe) and (it.Cod_Produto = lt.Cod_Produt) and (it.Cod_Lote = lt.Cod_Lote))
      Where it.Cod_Estabe = @PCodEstabe
        And it.Num_Nota = @PNumNota
        And it.Ser_Nota = @PSerNota
      Order by it.Cod_Produto

  end  -- if @PTipNota = 'S'
else
  begin

    -- se for devolucao
    if @WTipNotCab = 'D'
      Exec PR_CalcTributSTRetAntNFECB @PCodEstabe, @PNumNota

    -- normaliza itens da NF
    Update it
       Set it.Cod_NCM = cast(Substring(IsNull(pr.Cod_ClaFis,''),1,8) as varchar)
      From NFEIT it
           Inner Join PRODU pr on pr.Codigo = it.Cod_Produto
     Where it.Cod_Estabe = @PCodEstabe
       And it.Protocolo = @PNumNota
       And IsNull(it.Cod_NCM,'') <> cast(Substring(IsNull(pr.Cod_ClaFis,''),1,8) as varchar)
       And ((@WValCabRetCStat <> 100) and (@WValCabRetCStat <> 101) and (@WValCabRetCStat <> 102))
       And @WStatusCab <> 'C'

    Update it
       Set it.Cod_CEST = cast(Substring(IsNull(pr.Cod_CEST,''),1,7) as varchar)
      From NFEIT it
           Inner Join PRODU pr on pr.Codigo = it.Cod_Produto
     Where it.Cod_Estabe = @PCodEstabe
       And it.Protocolo = @PNumNota
       And IsNull(it.Cod_CEST,'') <> cast(Substring(IsNull(pr.Cod_CEST,''),1,7) as varchar)
       And ((@WValCabRetCStat <> 100) and (@WValCabRetCStat <> 101) and (@WValCabRetCStat <> 102))
       And @WStatusCab <> 'C'

    Update it
       Set it.Cod_OriMer = IsNull(pr.Cod_OriMer,'0')
      From NFEIT it
           Inner Join PRXES pr on pr.Cod_Estabe = it.Cod_Estabe and pr.Cod_Produt = it.Cod_Produto
     Where it.Cod_Estabe = @PCodEstabe
       And it.Protocolo = @PNumNota
--       And IsNull(it.Cod_OriMer,'') = ''
       And it.Cod_OriMer <> IsNull(pr.Cod_OriMer,'0')
       And ((@WValCabRetCStat <> 100) and (@WValCabRetCStat <> 101) and (@WValCabRetCStat <> 102))
       And @WStatusCab <> 'C'

    -- atualiza IE cabecalho
    Update cb 
       Set cb.Cgf_Rg = fo.Cgf_Rg
      From NFECB cb 
           Inner Join FORNE fo on cb.Cod_EmiFornec = fo.Codigo
     Where cb.Cod_Estabe = @PCodEstabe 
       and cb.Protocolo = @PNumNota
       and cb.Cod_EmiFornec > 0
       And IsNull(fo.Cgf_Rg,'') <> ''
       And cb.Cgf_Rg <> fo.Cgf_Rg

    Update cb 
       Set cb.Cgf_Rg = cl.Cgf
      From NFECB cb 
           Inner Join CLIEN cl on cb.Cod_EmiCliente = cl.Codigo
     Where cb.Cod_Estabe = @PCodEstabe 
       and cb.Protocolo = @PNumNota
       and cb.Cod_EmiCliente > 0
       And IsNull(cl.Cgf,'') <> ''
       And cb.Cgf_Rg <> cl.Cgf

    Update cb 
       Set cb.Cgf_Rg = tr.Cgf_Rg
      From NFECB cb 
           Inner Join TRANS tr on cb.Cod_EmiTransp = tr.Codigo
     Where cb.Cod_Estabe = @PCodEstabe 
       and cb.Protocolo = @PNumNota
       and cb.Cod_EmiTransp > 0
       And IsNull(tr.Cgf_Rg,'') <> ''
       And cb.Cgf_Rg <> tr.Cgf_Rg


    -- monta mensagens NFS em NECOB e NEIOB
    Exec PR_GeraMensagensNF @PCodEstabe, @PNumNota, @PSerNota, @PTipNota

    Select @NumPdv = cb.Cod_Pedido, 
           @WStatusCab = IsNull(cb.Status,''),
           @WValCabRetCStat = IsNull(cb.Ret_CStat,0),
           @WTipNotCab = cb.Tip_NF,
           @WCodTipCon = dbo.FN_CodTipConsum (cb.Tip_Consumidor, '', cb.Cgc_Cpf, cb.Cgf_Rg, cb.Cod_UfOrigem),
           @WDatEmiCab = cb.Dat_Emissao,
           @WValCabCodRegTri = IsNull(cb.Cod_RegTri,0),
           @WValCabTipConsumidor = IsNull(cb.Tip_Consumidor,''),
           @WValCabUFEmi = IsNull(cb.Cod_UFOrigem,''),
           @WValCabUFDes = IsNull(es.Des_Estado,''),
           @WValCabBasIcm = Round(IsNull(cb.Vlr_BasIcmsTri,0),2),
           @WValCabIcm = Round(IsNull(cb.Vlr_IcmsTri,0),2),
           @WValCabIcmPro = Round(IsNull(cb.Vlr_IcmsNor,0),2),
           @WValCabDscCom = Round(IsNull(cb.Vlr_Desconto,0),2),
           @WValCabDscBon = 0,
           @WValCabRepIcm = Round(IsNull(cb.Vlr_RepIcms,0),2),
           @WValCabDscTri = Round(IsNull(cb.Vlr_DscTri,0),2),
           @WValCabBasIcmSbt = Round(IsNull(cb.Vlr_BasIstFon,0),2),
           @WValCabIcmSbt = Round(IsNull(cb.Vlr_IstFon,0),2),
           @WValCabBasSbtRes = Round(IsNull(cb.Vlr_BasSbtRes,0),2),
           @WValCabSbtRes = Round(IsNull(cb.Vlr_SbtRes,0),2),
           @WValCabIpi = Round(IsNull(cb.Vlr_Ipi,0),2),
           @WValCabDevIpi = 0,
           @WValCabPis =  Round(IsNull(cb.Vlr_Pis,0),2),
           @WValCabCof =  Round(IsNull(cb.Vlr_Cofins,0),2),
           @WValCabIcmParDes = Round(IsNull(cb.Vlr_IcmParDes,0),2), 
           @WValCabIcmParRem = Round(IsNull(cb.Vlr_IcmParRem,0),2),
           @WValCabCodCmpCli = '',
           @WValCabIcmFcpDes = Round(IsNull(cb.Vlr_IcmFcpDes,0),2), 
           @WValCabFcpIcm = Round(IsNull(cb.Vlr_FcpIcm,0),2), 
           @WValCabFcpSbt = Round(IsNull(cb.Vlr_FcpSbt,0),2), 
           @WValCabFcpSbtRet = Round(IsNull(cb.Vlr_FcpSbtRet,0),2)
      From NFECB cb 
           Inner Join ESTAB es on cb.Cod_Estabe = es.Cod_Estabe
     Where cb.Cod_Estabe = @PCodEstabe 
       and cb.Protocolo = @PNumNota

    Set @WPerParIcmDef = IsNull((Select max(Per_PrvParIcm)
                                   From NFEIT
                                  Where Cod_Estabe = @PCodEstabe
                                    And Protocolo = @PNumNota),0)
    -- 7%  UF Emissao: Sul e SE exceto ES:  ';MG;RJ;SP;PR;SC;RS;'
    --        Destino: N, NE e ES
    if (Charindex(@WValCabUFEmi,';MG;RJ;SP;PR;SC;RS;') > 0) and   -- S, SE, exceto ES
           (Charindex(@WValCabUFDes,';MG;RJ;SP;PR;SC;RS;') = 0)       -- N, NE e ES
      Set @WPerAlqInterestaDef = 7.00
    else
      Set @WPerAlqInterestaDef = 12.00
    
    -- atualiza cBenef NFEIT: UF Emitente
    -- Exige o código de benefício fiscal (cBenef) quando se utiliza um CST de benefício fiscal (20, 30, 40, 41, 50, 51, 60 ou 90).
        -- verifica beneficio por NCM
        -- cBenef em devolução é calculado em PR_CalculaTributosEntradasDevlucao
    Exec PR_CalculaBeneficiosEntrada @PCodEstabe, @PNumNota

    Insert Into #TMP_Itens
      Select it.Cod_Produto, it.Num_SeqIte,
             Num_SeqPdc = Substring(Cast(it.Num_SeqIte as varchar),1,6),
             Cod_EAN = Case 
                         When (IsNull(pr.Cod_Ean, '') = '') and Exists(Select 1 From PREAN pe Where pr.Codigo = pe.Cod_Produt And pe.Tip_Cod = '3') Then
                             (Select top 1 IsNull(pe.Cod_Ean, '') 
                                From PREAN pe 
                               Where pr.Codigo = pe.Cod_Produt 
                                 And pe.Tip_Cod = '3'
                                 And len(pe.Cod_Ean) > 1 
                               Order by len(pe.Cod_Ean) Desc)
                         When (IsNull(pr.Cod_Ean, '') = '') and Exists(Select 1 From PREAN pe  Where pr.Codigo = pe.Cod_Produt And pe.Tip_Cod = '4') Then
                             (Select top 1 IsNull(pe.Cod_Ean, '') 
                                From PREAN pe 
                               Where pr.Codigo = pe.Cod_Produt 
                                 And pe.Tip_Cod = '4'
                                 And len(pe.Cod_Ean) > 1 
                               Order by len(pe.Cod_Ean) Desc)
                         Else IsNull(pr.Cod_Ean,'')
                       End,
             Tip_Sai = '',
             Cod_NCM = ISNULL(it.Cod_NCM,''),
             Cod_GrpPrc = IsNull(pr.Cod_GrpPrc,''),
             it.Cod_Cfo, 
             Tip_Por344 = IsNull(pr.Tip_Por344,''),
             Tip_LisPis = ISNull(it.Tip_LisPis,''),
             Des_Produto = pr.Descricao,
             Obs_Produto = '',
             Und_Com = pr.Unidade_Venda,
             Qtd_Com = IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0),
             Prc_UniCom = IsNull(it.Prc_Unitario,0),
             Vlr_TotBruIte = Round(IsNull(it.Prc_Unitario,0)*(IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)),2),
--             Vlr_TotIte = Round(IsNull(it.Qtd_Pedido,0)*(IsNull(it.Prc_Unitario,0)*(1-IsNull(it.Per_DescItem,0)/100)),2),
--             Vlr_TotIte = Round(IsNull(it.Vlr_TotItem,0),2),
             Vlr_TotIte = Case
                            When Round(IsNull(it.Vlr_TotItem,0),2) <= Round(IsNull(it.Prc_Unitario,0)*(IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)),2)
                            Then Round(IsNull(it.Vlr_TotItem,0),2) 
                            Else Round(IsNull(it.Prc_Unitario,0)*(IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)),2)
                          End,
             Per_Desconto = IsNull(it.Per_DescItem,0),
             Vlr_BasRepIcm = IsNull(it.Vlr_BasRepIcm,0),
             Per_RepIcm = IsNull(it.Per_RepIcm,0),
             Vlr_RepIcm = Round(IsNull(it.Vlr_RepIcm,0),2),
             Tip_Consumidor = @WValCabTipConsumidor,
             Vlr_DscTri = Round(IsNull(it.Vlr_DscTri,0),2),
             Per_DscTri = 0,
             Vlr_DscRat = Round(IsNull(it.Vlr_DescRateado,0),2),
             Vlr_DscBonRat = 0,
             Vlr_DscTotIte = 0,
             Vlr_BasSbtRes = Round(IsNull(it.Vlr_BasSbtRes,0),2),        
             Vlr_SbtRes = Round(IsNull(it.Vlr_SbtRes,0),2), 
             Vlr_BasSbtEmb = 0,
             Vlr_SbtEmb = 0, 
             it.Cod_Lote,
             it.Cod_Lote, 
             IsNull(lt.Dat_Vencim,0),
             IsNull(lt.Dat_Fabric,0),
             IsNull(pr.Validade,0),
             Vlr_Frete = Round(IsNull(it.Vlr_Frete,0),2),
             Vlr_Seguro = Round(IsNull(it.Vlr_Seguro,0),2),
             Vlr_DspRat = Round(IsNull(it.Vlr_DespRateada,0),2),
             Vlr_DspExt = Round(IsNull(it.Vlr_DspExt,0),2),
             Vlr_TotDsp = 0,
             Und_Tri = pr.Unidade_Venda,
             Qtd_Tri = IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0),
             Prc_UniTri = IsNull(it.Prc_Unitario,0),          
             Cod_OriPrd = IsNull(it.Cod_OriMer,'0'),
             Cod_CstIcm = IsNull(it.Ctrl_Tributacao,''),
             Cod_CsosnIcm = IsNull(it.Cod_CSOSN,''),
             Cod_ModBasCalIcm = IsNull(it.Cod_ModBasCalIcm,''),
             Per_RedBasCalIcm = IsNull(it.Per_RedBasCalIcm,0),
             Vlr_BasIcm = Round(IsNull(it.Vlr_BasIcmsTrib,0),2),
             Alq_Icm = IsNull(it.Alq_Icms,0),
             Vlr_Icm = Round(IsNull(it.Vlr_IcmsTrib,0),2),
             Dif_VlrIcm = Round(IsNull(it.Vlr_IcmsTrib,0),2) - IsNull(it.Vlr_IcmsTrib,0),
             Vlr_BasIcmPro = Round(IsNull(it.Vlr_BasIcmsNor,0),2),
             Vlr_IcmPro = Round(IsNull(it.Vlr_IcmsNor,0),2),
             Per_IcmDiferi = IsNull(it.Per_IcmDiferi,0),
             Vlr_IcmDiferi = Round(IsNull(it.Vlr_IcmDiferi,0),2),
             Vlr_DscCalSuframa = Round(IsNull(it.Vlr_DscCalSuframa,0),2),
             Vlr_IcmDesone = IsNull(it.Vlr_IcmsDeson,0), 
             Cod_MtvIcmDesone = IsNull(it.Cod_MtvIcmsDeson,''),
             Vlr_BasIcmSbtRet = 0,
             Vlr_IcmSbtRet = 0,
             Cod_ModBasCalIcmSbt = IsNull(it.Cod_ModBasCalIcmSbt,''),
             Alq_AgrSbt = IsNull(it.Alq_AgrDeb,0), 
             Per_RedBasCalIcmSbt = IsNull(it.Per_RedBasCalIcmSbt,0),
             Vlr_BasIcmSbt = Round(IsNull(it.Vlr_BasSubsTrib,0),2),
             Alq_IcmSbt = Case When IsNull(it.Alq_IcmSbt,0) > 0 then it.Alq_IcmSbt Else IsNull(it.Alq_IcmDeb,0) End,  -- ????
             Vlr_IcmSbt = Round(IsNull(it.Vlr_SubsTrib,0),2),
             CST_Ipi    = Case When IsNull(CST_Ipi,'') = '' then '49' Else CST_Ipi End, -- outras
             Cod_EnqIpi = Case When IsNull(Cod_EnqIpi,'') = '' then '999' Else Cod_EnqIpi End,
             Vlr_BasIpi = IsNull(it.Vlr_BasIpi,0),
             Alq_Ipi = Case 
                         When it.Vlr_TotItem > 0 then (it.Vlr_Ipi * 100 / it.Vlr_TotItem) 
                         Else 0
                       End, 
             Vlr_Ipi = it.Vlr_Ipi, 
             Vlr_BasDevIpi = 0,
             Per_DevIpi = 0,
             Vlr_DevIpi = 0,
             it.CST_Pis, it.Vlr_BasPis, it.Alq_Pis, Vlr_Pis = Round(IsNull(it.Vlr_Pis,0),2), 
             Dif_VlrPis = Round(IsNull(it.Vlr_Pis,0),2)-IsNull(it.Vlr_Pis,0), 
             it.CST_Cofins, it.Vlr_BasCofins, it.Alq_Cofins, Vlr_Cofins = Round(IsNull(it.Vlr_Cofins,0),2),
             Dif_VlrCofins = Round(IsNull(it.Vlr_Cofins,0),2)-IsNull(it.Vlr_Cofins,0),
             Prc_MaxCon = Case
                            When @pm_CodImpPMC = '1' then IsNull(it.Prc_MaxCon,0)*IsNull(it.Fator_Fat,1)
                            Else 0
                          End, 
             Prc_Fabric = IsNull(it.Prc_Fabric,0)*IsNull(it.Fator_Fat,1), 
             Des_Fabric = Substring(fb.Fantasia,1,25),
             Flg_DscItePdv = 0,
             Prc_UniPdv = 0,
             Per_DscPdv = 0,
             Cod_CEST = ISNULL(it.Cod_CEST,''),
             
             Vlr_BasIcmDes = Case 
                               When (@WPerParIcmDef > 0) and (IsNull(it.Vlr_IcmFcpDes,0) > 0)  then Round(IsNull(it.Vlr_BasIcmsNor,0),2) 
                               Else 0
                             End,
             Per_AcrAlqIntFcp = Case
                                  When (ISNULL(it.Per_PrvParIcm,0) > 0) and (IsNull(it.Vlr_IcmFcpDes,0) > 0) then ISNULL(it.Per_AcrAlqIntFcp,0)
                                  Else 0
                                End,
             Alq_IntDes = Case 
                            When (@WPerParIcmDef > 0) then ISNULL(it.Alq_IntIcmDes,0)
                            Else 0
                          End,
             Alq_Interesta = Case
                               When (@WPerParIcmDef > 0) and (it.Cod_OriMer IN ('1', '2', '3', '8')) then 4.0 /* DMD-8037: Regra NA09-20 */
							   When (@WPerParIcmDef > 0) and (ISNULL(it.Alq_Icms,0) > 0) then ISNULL(it.Alq_Icms,0)
                               When (@WPerParIcmDef > 0) and (ISNULL(it.Alq_Icms,0) = 0) then @WPerAlqInterestaDef							   
                               Else 0
                             End,
             Per_PrvParIcm = Case 
                               When (@WPerParIcmDef > 0) and (IsNull(it.Vlr_IcmFcpDes,0) > 0) then @WPerParIcmDef 
                               Else 0 
                             End, 

             Vlr_IcmFcpDes = Round(IsNull(it.Vlr_IcmFcpDes,0),2), 
             Vlr_IcmParDes = Round(IsNull(it.Vlr_IcmParDes,0),2),
             Vlr_IcmParRem = Round(IsNull(it.Vlr_IcmParRem,0),2), 
             Cod_PedCmpCli = @WValCabCodCmpCli,
             Str_VolEmb = '',
             Obs_IteNf = '',
             Reg_MS = IsNull(pr.Reg_MS,''),
             Des_MtvIseRegMS = Substring(IsNull(pr.Des_MtvIseRegMS,''),1,255),

             Alq_FcpIcm = IsNull(it.Alq_FcpIcm,0),
             Vlr_FcpIcm = Round(IsNull(it.Vlr_FcpIcm,0),2),
             Alq_FcpSbt = IsNull(it.Alq_FcpSbt,0),
             Vlr_FcpSbt = Round(IsNull(it.Vlr_FcpSbt,0),2),
             Alq_FcpSbtRet = IsNull(it.Alq_FcpSbtRet,0),
             Vlr_FcpSbtRet = Round(IsNull(it.Vlr_FcpSbtRet,0),2),

             vBCSTRet = IsNull(it.Xml_vBCSTRet,0),
             pST = IsNull(it.Xml_pST,0),
             vICMSSubstituto = IsNull(it.Xml_vICMSSubstituto,0),
             vICMSSTRet = IsNull(it.Xml_vICMSSTRet,0),
             vBCFCPSTRet = IsNull(it.Xml_vBCFCPSTRet,0),
             pFCPSTRet = IsNull(it.Xml_pFCPSTRet,0),
             vFCPSTRet = IsNull(it.Xml_vFCPSTRet,0),

             pRedBCEfet = Case When @WValCabTipConsumidor = 'F' then IsNull(it.Xml_pRedBCEfet,0) Else 0 End,
             vBCEfet    = Case When @WValCabTipConsumidor = 'F' then IsNull(it.Xml_vBCEfet,0)    Else 0 End,
             pICMSEfet  = Case When @WValCabTipConsumidor = 'F' then IsNull(it.Xml_pICMSEfet,0)  Else 0 End,
             vICMSEfet  = Case When @WValCabTipConsumidor = 'F' then IsNull(it.Xml_vICMSEfet,0)  Else 0 End,

             cBenef = IsNull(it.cBenef,''),
			 
			 nFCI = IsNull(pr.Cod_FCI,''),
			 pFCI = IsNull(pr.Per_FCI,0) 

      From NFEIT it
           Inner Join NFECB cb on cb.Protocolo = it.Protocolo
           Inner Join PRODU pr on pr.Codigo = it.Cod_Produto
           Inner Join FABRI fb on fb.Codigo = pr.Cod_Fabricante
           left outer Join (Select Cod_Estabe, Cod_Produt, Cod_Lote,
                            Dat_Vencim = MIN(Dat_Vencim), Dat_Fabric = MIN(Dat_Fabric) 
                            From PRLOT 
                            Where Cod_Estabe = @PCodEstabe
                            Group by Cod_Estabe, Cod_Produt, Cod_Lote) lt on ((it.Cod_Estabe = lt.Cod_Estabe) and (it.Cod_Produto = lt.Cod_Produt) and (it.Cod_Lote = lt.Cod_Lote))
           
      Where it.Cod_Estabe = @PCodEstabe
      And it.Protocolo = @PNumNota
      Order by it.Cod_Produto
  end  
  
--normaliza lote ------------------------------------------------------------------------------------------------
DECLARE ITENS_Cr Cursor Local Fast_Forward For
  Select Chave, Cod_Lote, Dat_Vencim, Dat_Fabric, Qtd_MesValid
  From #TMP_Itens
  Where ((Dat_Vencim < 10) or (Dat_Fabric < 10))
        
OPEN ITENS_Cr
FETCH NEXT FROM ITENS_Cr INTO @Chave, @CodLot, @DatVct, @DatFab, @QtdMesVld 
WHILE @@FETCH_STATUS = 0
BEGIN
  if @DatVct < 10
    begin
      Set @CodLot = ''
      Set @DatVct = null
      Set @DatFab = null 
    end      
  else  
  if @DatFab < 10
    begin
      if @QtdMesVld <= 0
        Set @QtdMesVld = 24
      if @QtdMesVld > 1000
        Set @QtdMesVld = 60   
      Set @DatFab = DATEADD(mm,-@QtdMesVld,@DatVct)
          if @DatFab > @WDatEmiCab
        Set @DatFab = @WDatEmiCab
    end  

  Update #TMP_Itens
    Set Cod_Lote = @CodLot,
        Dat_Vencim = @DatVct,
        Dat_Fabric = @DatFab  
  Where Chave = @Chave

  FETCH NEXT FROM ITENS_Cr INTO @Chave, @CodLot, @DatVct, @DatFab, @QtdMesVld
END

CLOSE ITENS_Cr
DEALLOCATE ITENS_Cr  

-- Normaliza desconto Comercial ----------------------------------------------------------------------------------------------
Set @WValDif = Round(@WValCabDscCom - (Select SUM(Vlr_DscRat) From #TMP_Itens),2) 
if @WValDif < 0
  Set @ParDif = -0.01  
else  
  Set @ParDif = 0.01  
  
while (@WValDif <> 0) and (Abs(@WValDif) < @WValCabDscCom)
  begin
    if @ParDif > 0
      DECLARE ITENS_Cr Cursor Local Fast_Forward For
        Select Chave
        From #TMP_Itens
        Where Vlr_DscRat > 0
        Order by Vlr_TotIte desc, Chave
    else
      DECLARE ITENS_Cr Cursor Local Fast_Forward For
        Select Chave
        From #TMP_Itens
        Where Vlr_DscRat > 0
        Order by Vlr_TotIte desc, Chave 
        
    OPEN ITENS_Cr
    FETCH NEXT FROM ITENS_Cr INTO @Chave 
    WHILE @@FETCH_STATUS = 0
    BEGIN
      if @WValDif <> 0
         begin
           Update #TMP_Itens
             Set Vlr_DscRat = Vlr_DscRat + @ParDif   
           Where Chave = @Chave
           And Vlr_DscRat > 0
                      
           Set @WValDif = @WValDif - @ParDif
         end
       else
         Break  
      FETCH NEXT FROM ITENS_Cr INTO @Chave
    END

    CLOSE ITENS_Cr
    DEALLOCATE ITENS_Cr     
          
  end  -- while @WValDif <> 0
