--  Base de calculo x aliquota icms
Update #TMP_Itens
  Set Vlr_Icm = Round(Vlr_BasIcm*Alq_Icm/100,2)
Where Round(Vlr_BasIcm*Alq_Icm/100,2) <> Vlr_Icm
And ((Vlr_IcmDiferi = 0) or ((Vlr_IcmDiferi > 0) and (Vlr_DscCalSuframa > 0)))

Update #TMP_Itens
  Set Vlr_Icm = Round((Vlr_BasIcm*Alq_Icm/100)-Vlr_IcmDiferi,2)
Where Round(Vlr_BasIcm*Alq_Icm/100,2)-Vlr_IcmDiferi <> Vlr_Icm
And Vlr_IcmDiferi > 0
And Vlr_DscCalSuframa = 0


-- ----- Normaliza ICMS: B.Calculo x Aliquota = Vlr_Icms  -----------------------------------------------------------
if Round(@WValCabIcm,2) <> Round( (Select SUM(Vlr_Icm) From #TMP_Itens),2) 
  begin
    Set @WValDif = Round(@WValCabIcm - (Select SUM(Vlr_Icm) From #TMP_Itens),2) 
    if ABS(@WValDif) > 0 
      begin
        -- atualiza valor na tabela de origem (alterando valor original ????)
        Set @WValCabIcm = Round((Select sum(Vlr_Icm) From #TMP_Itens),2)
        if @PTipNota = 'S'
          begin
            Update NFSCB
              Set Vlr_IcmsTri = @WValCabIcm
            Where Cod_Estabe = @PCodEstabe 
            and Ser_Nota = @PSerNota 
            and Num_Nota = @PNumNota
          end
        else
          begin
            Update NFECB
              Set Vlr_IcmsTri = @WValCabIcm
            From NFECB 
            Where Cod_Estabe = @PCodEstabe 
            and Protocolo = @PNumNota
          end
      end
  end  


