           Set @WValDif = @WValDif - @ParDif
         end
       else
         Break  
      FETCH NEXT FROM ITENS_Cr INTO @Chave
    END

    CLOSE ITENS_Cr
    DEALLOCATE ITENS_Cr     
          
  end  -- while @WValDif <> 0

