else  
  Set @ParDif = 0.01  
  
while (@WValDif <> 0) and (Abs(@WValDif) < @WValCabPis)
  begin
    if @ParDif > 0 
      DECLARE ITENS_Cr Cursor Local Fast_Forward For
        Select Chave
        From #TMP_Itens
        Where Vlr_Pis > 0
        Order by Vlr_TotIte desc, Chave 
    else
      DECLARE ITENS_Cr Cursor Local Fast_Forward For
        Select Chave
        From #TMP_Itens
        Where Vlr_Pis > 0
        Order by Vlr_TotIte desc, Chave 
        
    OPEN ITENS_Cr
    FETCH NEXT FROM ITENS_Cr INTO @Chave 
    WHILE @@FETCH_STATUS = 0
    BEGIN
      if @WValDif <> 0
         begin
           Update #TMP_Itens
             Set Vlr_Pis = Vlr_Pis + @ParDif   
           Where Chave = @Chave
           And Vlr_Pis > 0
                      
           Set @WValDif = @WValDif - @ParDif
         end
       else
         Break  
      FETCH NEXT FROM ITENS_Cr INTO @Chave
