------- Normaliza FCP: B.Calculo x Aliquota = Vlr_IcmFcp  -----------------------------------------------------------
--  está alterando NFSCB.Vlr_IcmFcpDes ????
if Round(@WValCabIcmFcpDes,2) = Round((Select SUM(Vlr_IcmFcpDes) From #TMP_Itens),2) 
  begin
    Set @WValDif = Round(@WValCabIcmFcpDes - (Select sum(Round(Vlr_BasIcmDes*Per_AcrAlqIntFcp/100,2)) From #TMP_Itens),2) 
    if ABS(@WValDif) > 0 
      begin
        Update #TMP_Itens
          Set Vlr_IcmFcpDes = Round(Vlr_BasIcmDes*Per_AcrAlqIntFcp/100,2)
          Where Round(Vlr_BasIcmDes*Per_AcrAlqIntFcp/100,2) <> Vlr_IcmFcpDes
          
        -- atualiza valor na tabela de origem (alterando valor original ????)
        Set @WValCabIcmFcpDes = Round((Select sum(Vlr_IcmFcpDes) From #TMP_Itens),2)
        if @PTipNota = 'S'
          begin
            Update NFSCB
              Set Vlr_IcmFcpDes = @WValCabIcmFcpDes
            Where Cod_Estabe = @PCodEstabe 
            and Ser_Nota = @PSerNota 
            and Num_Nota = @PNumNota
          end
        else
          begin
            Update NFECB
              Set Vlr_IcmFcpDes = @WValCabIcmFcpDes
            From NFECB 
            Where Cod_Estabe = @PCodEstabe 
            and Protocolo = @PNumNota
          end
      end
  end  

---------------------------------------------------------------------------------------------------------------

-- normaliza EAN (a partir da versão 4.0)
Update #TMP_Itens
  Set Cod_EAN = 'SEM GTIN'
Where IsNull(Cod_EAN,'') = ''
And Cast(Substring(@pm_VerNfe,1,CharIndex('.',@pm_VerNfe)-1) as int) > 3

------------------------------------------------------------------------------------------------------------------
-- recalcula campos
Update #TMP_Itens
  Set Vlr_DscTotIte = Vlr_TotBruIte - Vlr_TotIte + Vlr_DscRat + Vlr_DscBonRat + Vlr_DscTri, -- desc. sem repasse
      Vlr_TotDsp = Vlr_DspRat + Vlr_DspExt + Vlr_SbtRes,
      Vlr_BasIcmSbtRet = Vlr_BasSbtRes + Vlr_BasSbtEmb,
      Vlr_IcmSbtRet = Vlr_SbtRes + Vlr_SbtEmb
      
-- monta observacao 
DECLARE ITENS_Cr Cursor Local Fast_Forward For
  Select Chave, Cod_Produto, Num_SeqIte, Cod_Lote, Cod_LoteOri, Tip_LisPis, Vlr_TotBruIte, Vlr_DscTotIte,
         Flg_DscItePdv, Prc_UniPdv, Per_DscPdv, Prc_Fabric,
         Vlr_BasSbtRes, Vlr_SbtRes, Vlr_BasSbtEmb, Vlr_SbtEmb, Tip_Consumidor,
         Vlr_DscTri, Per_DscTri, Des_Produto, Des_Fabric, Tip_Por344, Tip_Sai, 
         Str_VolEmb, Obs_IteNf, Vlr_BasRepIcm, Per_RepIcm, Vlr_RepIcm,
         Per_Desconto = Case When (Vlr_DscRat + Vlr_DscBonRat) > 0 then 0 Else Per_Desconto End,
         Vlr_TotIte
  From #TMP_Itens
  Order by Chave 
OPEN ITENS_Cr
FETCH NEXT FROM ITENS_Cr INTO @Chave, @CodPrd, @SeqIte, @CodLot, @WCodLotOri, @WTipLisPis, @WVlrTotBruIte, @WVlrDscTotIte,
                              @WFlgDscItePdv, @WPrcUniPdv, @WPerDscPdv, @WPrcFabric,
                              @WVlrBasSbtRes, @WVlrSbtRes, @WVlrBasSbtEmb, @WVlrSbtEmb, @WTipCon,
                              @WVlrDscTri, @WPerDscTri, @WDesProduto, @WDesFabric, @WTipPor344, @WTipSai, 
                              @WStrVolEmb, @WObsIteNf, @WVlrBasRepIcm, @WPerRepIcm, @WVlrRepIcm, @WPerDscIte, @WVlrTotLiqIte
WHILE @@FETCH_STATUS = 0
  BEGIN
    -- monta observacao cancatenada infAdProd
    Set @WDesCplProduto = ''

    Delete From @Tab

    if @PTipNota = 'S'
      Insert Into @Tab (Obs_Fiscal)
        Select Des_Observ From NSIOB
         Where Cod_Estabe = @PCodEstabe 
           and Ser_Nota = @PSerNota 
           and Num_Nota = @PNumNota
           and Cod_Produto = @CodPrd
           and Cod_Lote = @CodLot
           and Num_SeqIte = @SeqIte
    else
      Insert Into @Tab (Obs_Fiscal)
        Select Des_Observ From NEIOB
         Where Cod_Estabe = @PCodEstabe 
           and Protocolo = @PNumNota
           and Cod_Produto = @CodPrd
           and Cod_Lote = @CodLot
           and Num_SeqIte = @SeqIte

    While Exists(Select 1 From @Tab)
      begin
        Select top 1
               @ChaveTab = ChaveTab
             , @WObsFis = Obs_Fiscal
          From @Tab
         Order by ChaveTab

        if PatIndex(@WObsFis+'%', @WDesCplProduto) = 0
          begin
            if (Len(@WDesCplProduto) > 0) and
               (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
              Set @WDesCplProduto = @WDesCplProduto + ';  '
            Set @WDesCplProduto = @WDesCplProduto + @WObsFis
          end

        Delete From @Tab Where ChaveTab = @ChaveTab
      end


    if (@pm_CodImpDscFab = '1') and (@WDesFabric <> '')
      Set @WDesProduto = @WDesProduto+' ('+Substring(@WDesFabric,1,5)+')'
    if @WTipPor344 <> ''
      Set @WDesProduto = @WDesProduto+' ('+@WTipPor344+')'  
    if @WTipSai = 'B'                     
      Set @WDesProduto = @WDesProduto+' **Bonific.**'

    if (@CodLot = '') and (@WCodLotOri <> '')
      begin
        if (Len(@WDesCplProduto) > 0) and
           (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
          Set @WDesCplProduto = @WDesCplProduto + ';  '
        Set @WDesCplProduto = @WDesCplProduto + 'Lote: '+@WCodLotOri
      end
    
    if (@pm_CodImpPrcFab = '1') and (@WPrcFabric > 0)
      begin
        if (Len(@WDesCplProduto) > 0) and
           (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
          Set @WDesCplProduto = @WDesCplProduto + ';  '
        Set @WDesCplProduto = @WDesCplProduto + 'PF: '+CAST(cast(@WPrcFabric as numeric(12,2)) as varchar)
      end


    Set @WTipLisPis = Case              
                        When @WTipLisPis = 'P' then '(+)'
                        When @WTipLisPis = 'N' then '(-)'
                        When @WTipLisPis = 'X' then '(n)'
                        When @WTipLisPis = 'O' then '(o)'
                      End
    if (Len(@WDesCplProduto) > 0) and
       (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
      Set @WDesCplProduto = @WDesCplProduto + ';  '
    Set @WDesCplProduto = @WDesCplProduto+'Lista '+@WTipLisPis

    -- desconto repasse
    if (@WPerRepIcm > 0) and (@WVlrRepIcm > 0)
      begin
        if (Len(@WDesCplProduto) > 0) and
           (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
          Set @WDesCplProduto = @WDesCplProduto + ';  '
        Set @WDesCplProduto = @WDesCplProduto + 'Repasse '+CAST(cast(@WPerRepIcm as numeric(8,2)) as varchar)+'%'
      end

    -- desconto total (-repasse)
    Set @WPerDsc = 0
    if (@WVlrDscTotIte > 0) and (@WVlrTotBruIte > 0) 
      begin
        if @WPerDscIte > 0 
          Set @WPerDsc = @WPerDscIte
        else
          Set @WPerDsc = Round(@WVlrDscTotIte*100/@WVlrTotBruIte,2)
        if @WPerDsc > 0
          Set @WDesCplProduto = @WDesCplProduto + 'Desc.'+CAST(cast(@WPerDsc as numeric(8,2)) as varchar)+'%  '
      end

    if (@pm_FlgImpDscEmbNot = 1) and (@WFlgDscItePdv = 1) and (@WPerDscPdv > 0) 
      begin
        if (Len(@WDesCplProduto) > 0) and
           (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
          Set @WDesCplProduto = @WDesCplProduto + ';  '
        Set @WDesCplProduto = @WDesCplProduto + 'Desc.Emb.'+CAST(cast(@WPerDscPdv as numeric(8,2)) as varchar)+'%'
      end
    
    if ((@WVlrBasSbtRes+@WVlrBasSbtEmb) > 0) and
       ((@WVlrSbtRes+@WVlrSbtEmb) > 0)
      begin
        if (Len(@WDesCplProduto) > 0) and
           (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
          Set @WDesCplProduto = @WDesCplProduto + ';  '
        Set @WDesCplProduto = @WDesCplProduto + 'BCRE: '+CAST(cast((@WVlrBasSbtRes+@WVlrBasSbtEmb) as numeric(12,2)) as varchar)
        Set @WDesCplProduto = @WDesCplProduto + '  VRE: '+CAST(cast((@WVlrSbtRes+@WVlrSbtEmb) as numeric(12,2)) as varchar)
      end   
  
/*    
    if @WVlrDscTri > 0
      if Charindex(@WTipCon,';P;E;M;') > 0  -- consumidor final
        Set @WDesCplProduto = @WDesCplProduto + 'ICMS abatido no valor de '+CAST(cast(@WVlrDscTri as numeric(12,2)) as varchar)+'  '
          else
      if @WPerDscTri > 0
        Set @WDesCplProduto = @WDesCplProduto + 'Desc.Repasse '+ CAST(cast(@WVlrDscTri as numeric(12,2)) as varchar) +'/'+CAST(@WPerDscTri as varchar)+'%  '
*/

    if @WStrVolEmb <> ''
      begin
        if (Len(@WDesCplProduto) > 0) and
           (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
          Set @WDesCplProduto = @WDesCplProduto + ';  '
        Set @WDesCplProduto = @WDesCplProduto + @WStrVolEmb
      end

    if @WObsIteNf <> ''
      begin
        if (Len(@WDesCplProduto) > 0) and
           (Substring(@WDesCplProduto,1,Len(@WDesCplProduto)) <> ';')
          Set @WDesCplProduto = @WDesCplProduto + ';  '
        Set @WDesCplProduto = @WDesCplProduto + @WObsIteNf
      end
---------------------------------------------------------------------------------------------------

    Update #TMP_Itens
      Set Des_Produto = @WDesProduto,
          Obs_Produto = Substring(@WDesCplProduto,1,500)
    Where Chave = @Chave

  FETCH NEXT FROM ITENS_Cr INTO @Chave, @CodPrd, @SeqIte, @CodLot, @WCodLotOri, @WTipLisPis, @WVlrTotBruIte, @WVlrDscTotIte,
                                @WFlgDscItePdv, @WPrcUniPdv, @WPerDscPdv, @WPrcFabric,
                                @WVlrBasSbtRes, @WVlrSbtRes, @WVlrBasSbtEmb, @WVlrSbtEmb, @WTipCon,
                                @WVlrDscTri, @WPerDscTri, @WDesProduto, @WDesFabric, @WTipPor344, @WTipSai, 
                                @WStrVolEmb, @WObsIteNf, @WVlrBasRepIcm, @WPerRepIcm, @WVlrRepIcm, @WPerDscIte, @WVlrTotLiqIte
END

CLOSE ITENS_Cr
DEALLOCATE ITENS_Cr     
      
----------------------------------------------------------------------------------------------------------

Set @WSelect = 'Select cProd = Cod_Produto, 
       cEAN = Cod_EAN, 
       NCM = Cod_NCM, 
       nItem = Num_SeqIte,
       nItemPed = Num_SeqPdc,
       Cod_GrpPrc = Cod_GrpPrc,
       CFOP = Cod_Cfo, 
       Tip_Por344,
       xProd = Des_Produto,
       cProdANVISA = Reg_MS, 
       xMotivoIsencao = Des_MtvIseRegMS,

       infAdProd = Obs_Produto,
       uCom = Und_Com,
       qCom = Qtd_Com,
       vUnCom = Prc_UniCom,
       vProd = Vlr_TotBruIte,
       vDesc = Vlr_DscTotIte + Vlr_RepIcm,
       Vlr_LiqMer = Vlr_TotIte,
       Vlr_BasSbtRes, Vlr_SbtRes, 
       nLote = Cod_Lote, 
       dVal = Dat_Vencim,
       dFab = Dat_Fabric,
       vFrete = Vlr_Frete,
       vSeg = Vlr_Seguro,
       vOutro = Vlr_TotDsp,
       uTrib = Und_Tri,
       qTrib = Qtd_Tri,
       vUnTrib = Prc_UniTri,

       orig = Cod_OriPrd,
       CST_Icm = Cod_CstIcm,
       CSOSN_Icm = Cod_CsosnIcm,
       modBC = Cod_ModBasCalIcm,
       pRedBC = Per_RedBasCalIcm, 
       vBC = Vlr_BasIcm, 
       pICMS = Alq_Icm - Alq_FcpIcm, 
           
       vICMSOp = Vlr_IcmPro,
       pDif = Per_IcmDiferi,
       vIcmsDif = Case 
                    When Vlr_IcmDiferi > 0 then 
                      Case 
                        When Vlr_IcmDiferi = (Vlr_IcmPro - (Vlr_Icm - Vlr_FcpIcm)) then Vlr_IcmDiferi 
                        Else (Vlr_IcmPro - (Vlr_Icm - Vlr_FcpIcm)) 
                      End
                    Else 0
                  End,
       vICMS = Vlr_Icm - Vlr_FcpIcm, 
       vICMSDeson = Vlr_IcmDesone, 
       motDesICMS = Cod_MtvIcmDesone,

       modBCST = Cod_ModBasCalIcmSbt,
       pMVAST = Alq_AgrSbt, 
       pRedBCST = Per_RedBasCalIcmSbt,
       vBCST = Vlr_BasIcmSbt, 
       pICMSST = Alq_IcmSbt - Alq_FcpSbt, 
       vICMSST = Vlr_IcmSbt - Vlr_FcpSbt,
       
       CST_Ipi, cEnq = Cod_EnqIpi,
       vBCIPI = Vlr_BasIpi+Vlr_BasDevIpi, 
       pIPI = Alq_Ipi, vIPI = Vlr_Ipi,
       pDevol = Per_DevIpi, vIPIDevol = Vlr_DevIpi,

       CST_Pis, Vlr_BasPis, Alq_Pis, Vlr_Pis,
       CST_Cofins, Vlr_BasCofins, Alq_Cofins, Vlr_Cofins, 
       vPMC = Prc_MaxCon, 
       Prc_Fabric,
  
       CEST = Cod_CEST,

       vBCUFDest = Vlr_BasIcmDes,
       vBCFCPUFDest = Vlr_BasIcmDes,
       pFCPUFDest = Per_AcrAlqIntFcp, 
       pICMSUFDest = Alq_IntDes,    
       pICMSInter = Alq_Interesta,
       pICMSInterPart = Per_PrvParIcm,

       vFCPUFDest = Vlr_IcmFcpDes,
       vICMSUFDest = Vlr_IcmParDes,    
       vICMSUFRemet = Vlr_IcmParRem,

       vBCFCP = Vlr_BasIcm,
       pFCP = Alq_FcpIcm,         
       vFCP = Vlr_FcpIcm,         

       vBCFCPST = Vlr_BasIcmSbt,
       pFCPST = Alq_FcpSbt,       
       vFCPST = Vlr_FcpSbt,       

       vBCSTRet, 
       pST,
       vICMSSubstituto,
       vICMSSTRet,

       vBCFCPSTRet,
       pFCPSTRet, 
       vFCPSTRet, 

       pRedBCEfet,
       vBCEfet,
       pICMSEfet,
       vICMSEfet,
           
       cBenef, 
       xPed = Cod_PedCmpCli,
	   nFCI,
	   pFCI
       
From #TMP_Itens '

if @pm_CtrImpIteNotFis = 'A'
  Set @WSelect = @WSelect +'Order by xProd'
else  
  Set @WSelect = @WSelect +'Order by cProd'

Exec (@WSelect)

DROP TABLE #TMP_Itens

RETURN;

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_AbastecePicking]
@PCodEstabe int,
@PCodAbaste int,
@PCodProdut int   -- 0 (todos os produtos)

WITH RECOMPILE
AS

SET NOCOUNT ON

BEGIN TRANSACTION

DECLARE @CodPrd int,
        @CodLot varchar(20),
        @CodDep smallint,
        @NumRuaDe smallint,
        @NumColDe smallint,
        @NumNivDe smallint,
        @NumAptDe smallint,
        @NumRuaPara smallint,
        @NumColPara smallint,
        @NumNivPara smallint,
        @NumAptPara smallint,
        @QtdMov integer,
        @QtdSldPra integer,
        @QtdSldDep integer,
        @QtdEmbFec integer,
        @QtdTrfPra integer,
        @QtdTrfDep integer,
        @QtdTrfTot integer,
        @CodOri varchar(10),
        @StrCodOri varchar(20),
        @DesUsu varchar(35),
        @FlgAchou bit,
        @TipAba varchar(1)

--Usuario do sistema que processa/executa (auditoria)
Set @DesUsu = dbo.FN_UsuarioInfarma()

Set @FlgAchou = 0
Set @CodOri = 'ABA_EST'

-- identifica tipo de abastecimento (A)-Fracionados, (T)-Pre-Picking
Select @TipAba = IsNull(Cod_Pro,'A') 
  From ABACB
 Where Cod_Estabe = @PCodEstabe
   And Cod_Abaste = @PCodAbaste

if @TipAba = 'T'
  begin
    Set @CodOri = 'ABA_PRE' 
    -- pre-picking (transferência no depósito)
    DECLARE Abait_Cr CURSOR Local Fast_Forward For 
      SELECT it.Cod_Produt, it.Cod_Lote, cb.Cod_Dep, it.Num_Rua, it.Num_Col, it.Num_Niv, IsNull(it.Num_Apt,0), it.Qtd_Mov,
             IsNull(Num_RuaDes,0), IsNull(Num_ColDes,0), IsNull(Num_NivDes,0), IsNull(Num_AptDes,0), cb.Usuario
        FROM ABAIT it Inner Join 
             ABACB cb on cb.Cod_Estabe = it.Cod_Estabe and cb.Cod_Abaste = it.Cod_Abaste
       WHERE it.Cod_Estabe = @PCodEstabe
         AND it.Cod_Abaste = @PCodAbaste
         AND ((cb.Cod_Sta = 'A') or (cb.Cod_Sta = 'C'))
         AND ((@PCodProdut = 0) or (it.Cod_Produt = @PCodProdut))
         AND IsNull(it.Flg_Proces,0) = 0
  end
else
  begin
    Set @CodOri = 'ABA_FRA' 
    -- fracionados (picking)
    DECLARE Abait_Cr CURSOR Local Fast_Forward For 
      SELECT it.Cod_Produt, it.Cod_Lote, cb.Cod_Dep, it.Num_Rua, it.Num_Col, it.Num_Niv, IsNull(it.Num_Apt,0), it.Qtd_Mov,
             IsNull(pr.Num_Rua,0), IsNull(pr.Num_Col,0), IsNull(pr.Num_Niv,0), IsNull(pr.Num_Apt,0), cb.Usuario
        FROM ABAIT it Inner Join 
             ABACB cb on cb.Cod_Estabe = it.Cod_Estabe and cb.Cod_Abaste = it.Cod_Abaste Inner Join
             DPXPR pr on cb.Cod_Estabe = pr.Cod_Estabe and cb.Cod_Dep = pr.Cod_Dep and it.Cod_Produt = pr.Cod_Produt
       WHERE it.Cod_Estabe = @PCodEstabe
         AND it.Cod_Abaste = @PCodAbaste
         AND ((cb.Cod_Sta = 'A') or (cb.Cod_Sta = 'C'))
         AND ((@PCodProdut = 0) or (it.Cod_Produt = @PCodProdut))
         AND IsNull(it.Flg_Proces,0) = 0
  end

OPEN Abait_Cr
FETCH NEXT FROM Abait_Cr INTO @CodPrd, @CodLot, @CodDep, @NumRuaDe, @NumColDe, @NumNivDe, @NumAptDe, @QtdMov,
                              @NumRuaPara, @NumColPara, @NumNivPara, @NumAptPara, @DesUsu
WHILE @@FETCH_STATUS = 0
BEGIN
  Select @QtdSldPra = IsNull(Qtd_SldPra,0),
         @QtdSldDep = IsNull(Qtd_SldDep,0),
         @QtdEmbFec = IsNull(Qtd_EmbFec,0)
    From PRLTL
   Where Cod_Estabe = @PCodEstabe 
     And Cod_Dep = @CodDep
     And Cod_Produt = @CodPrd
     And Cod_Lote = @CodLot
     And Num_Rua = @NumRuaDe
     And Num_Col = @NumColDe
     And Num_Niv = @NumNivDe
     And Num_Apt = @NumAptDe

  if (@QtdSldPra+@QtdSldDep) >= @QtdMov
    begin
      Set @FlgAchou = 1
      Set @QtdTrfPra = 0
      Set @QtdTrfDep = 0
      if @QtdSldPra > 0
        begin
          if @QtdSldPra > @QtdMov
            Set @QtdTrfPra = (@QtdMov/@QtdEmbFec)*@QtdEmbFec
          else
            Set @QtdTrfPra = @QtdSldPra
          Set @QtdMov = @QtdMov - @QtdSldPra
        end
      if (@QtdMov > 0) and (@QtdSldDep > 0)
        begin
          if @QtdSldDep > @QtdMov
            Set @QtdTrfDep = (@QtdMov/@QtdEmbFec)*@QtdEmbFec
          else
            Set @QtdTrfDep = @QtdSldPra
          Set @QtdMov = @QtdMov - @QtdSldDep
        end

     -- retira do endereço de origem
     Update PRLTL
        Set Qtd_FisPra = Qtd_FisPra - @QtdTrfPra,
            Qtd_FisDep = Qtd_FisDep - @QtdTrfDep
      Where Cod_Estabe = @PCodEstabe 
        And Cod_Dep = @CodDep
        And Cod_Produt = @CodPrd 
        And Cod_Lote = @CodLot
        And Num_Rua = @NumRuaDe
        And Num_Col = @NumColDe
        And Num_Niv = @NumNivDe
        And Num_Apt = @NumAptDe
        And Qtd_FisPra >= @QtdTrfPra
        And Qtd_FisDep >= @QtdTrfDep
      if @@rowcount > 0
        begin
          -- registra log saida
          Set @QtdTrfTot = (@QtdTrfPra + @QtdTrfDep) * (-1) 
      Set @StrCodOri = @CodOri + ' SAI'
          Exec PR_InserePRLOG @PCodEstabe, @CodPrd, @CodLot, @CodDep, 
                              @NumRuaDe, @NumColDe, @NumNivDe, @NumAptDe, 
                              @QtdTrfTot, @StrCodOri, '', @PCodAbaste, '', '', @DesUsu
          if @@error <> 0 
            begin 
              Rollback Transaction
              Return 
            end 
          
          if not Exists(Select 1 From PRLOT Where Cod_Estabe = @PCodEstabe And Cod_Dep = @CodDep And Cod_Produt = @CodPrd and Cod_Lote = @CodLot)
            Insert Into PRLOT (Cod_Estabe, Cod_Dep, Cod_Produt, Cod_Lote, Dat_Vencim, Dat_Fabric, Qtd_FisPra, Qtd_FisDep)
                        Select Cod_Estabe, Cod_Dep, Cod_Produt, Cod_Lote, Dat_Vencim, Dat_Fabric, 0, 0
                          From PRLTL
                         Where Cod_Estabe = @PCodEstabe 
                           And Cod_Dep = @CodDep
                           And Cod_Produt = @CodPrd
                           And Cod_Lote = @CodLot
                           And Num_Rua = @NumRuaDe
                           And Num_Col = @NumColDe
                           And Num_Niv = @NumNivDe
                           And Num_Apt = @NumAptDe

          -- abastece fracionados  
          if @TipAba = 'A'
            begin
              Update PRLOT
                 Set Qtd_FisPra = Qtd_FisPra + @QtdTrfPra,
                     Qtd_FisDep = Qtd_FisDep + @QtdTrfDep
               Where Cod_Estabe = @PCodEstabe 
                 And Cod_Dep = @CodDep
                 And Cod_Produt = @CodPrd
                 And Cod_Lote = @CodLot

              -- atualiza enderço de destino (picking) em ABAIT
              Update ABAIT
             Set Num_RuaDes = @NumRuaPara,
                     Num_ColDes = @NumColPara,
                     Num_NivDes = @NumNivPara,
                     Num_AptDes = @NumAptPara
               Where Cod_Estabe = @PCodEstabe
                 And Cod_Abaste = @PCodAbaste
                 And Cod_Produt = @CodPrd 
                 And Cod_Lote = @CodLot
                 And Cod_Dep = @CodDep
                 And Num_Rua = @NumRuaDe
                 And Num_Col = @NumColDe
                 And Num_Niv = @NumNivDe
                 And Num_Apt = @NumAptDe
             And ((IsNull(Num_RuaDes,0) <> @NumRuaPara) or 
                (IsNull(Num_ColDes,0) <> @NumColPara) or 
                (IsNull(Num_NivDes,0) <> @NumNivPara))
            end                  
          else
            begin
              -- abastece endereço pré-picking
              if not Exists(Select 1 From PRLTL Where Cod_Estabe = @PCodEstabe And Cod_Dep = @CodDep
                                                  And Cod_Produt = @CodPrd And Cod_Lote = @CodLot
                                                  And Num_Rua = @NumRuaPara And Num_Col = @NumColPara
                                                  And Num_Niv = @NumNivPara And Num_Apt = @NumAptPara)
                Insert Into PRLTL (Cod_Estabe, Cod_Dep, Cod_Produt, Cod_Lote, Num_Rua, Num_Col, Num_Niv, Num_Apt, Qtd_FisPra, Qtd_FisDep)
                           Values (@PCodEstabe, @CodDep, @CodPrd, @CodLot, @NumRuaPara, @NumColPara, @NumNivPara, @NumAptPara, 0, 0)

              Update d
                 Set d.Qtd_FisPra = d.Qtd_FisPra + @QtdTrfPra,
                     d.Qtd_FisDep = d.Qtd_FisDep + @QtdTrfDep,
                     d.Qtd_EmbFec = o.Qtd_EmbFec,
                     d.Dat_Vencim = o.Dat_Vencim, 
                     d.Dat_Fabric = o.Dat_Fabric, 
                     d.Dat_Entrada = o.Dat_Entrada
                From PRLTL d , PRLTL o
                Where d.Cod_Estabe = o.Cod_Estabe
                 And d.Cod_Dep = o.Cod_Dep
                 And d.Cod_Produt = o.Cod_Produt
                 And d.Cod_Lote = o.Cod_Lote
                 And d.Cod_Estabe = @PCodEstabe 
                 And d.Cod_Dep = @CodDep
                 And d.Cod_Produt = @CodPrd 
                 And d.Cod_Lote = @CodLot
                 And d.Num_Rua = @NumRuaPara
                 And d.Num_Col = @NumColPara
                 And d.Num_Niv = @NumNivPara
                 And d.Num_Apt = @NumAptPara
                 And o.Num_Rua = @NumRuaDe
                 And o.Num_Col = @NumColDe
                 And o.Num_Niv = @NumNivDe
                 And o.Num_Apt = @NumAptDe
            end
 
          -- registra log entrada
          Set @QtdTrfTot = @QtdTrfPra + @QtdTrfDep
      Set @StrCodOri = @CodOri + ' ENT'
          Exec PR_InserePRLOG @PCodEstabe, @CodPrd, @CodLot, @CodDep, 
                              @NumRuaPara, @NumColPara, @NumNivPara, @NumAptPara, 
                              @QtdTrfTot, @StrCodOri, '', @PCodAbaste, '', '', @DesUsu
          if @@error <> 0 
            begin 
              Rollback Transaction
              Return 
            end 

          -- atualiza flag item processado
          Update ABAIT
             Set Flg_Proces = 1
           Where Cod_Estabe = @PCodEstabe
             And Cod_Abaste = @PCodAbaste
             And Cod_Produt = @CodPrd 
             And Cod_Lote = @CodLot
             And Cod_Dep = @CodDep
             And Num_Rua = @NumRuaDe
             And Num_Col = @NumColDe
             And Num_Niv = @NumNivDe
             And Num_Apt = @NumAptDe

        end  -- if @@rowcount > 0

    end  -- if (@QtdSldPra+@QtdSldDep) >= @QtdMov
  else
    begin
      -- Elimina item em ABAIT
      Delete From ABAIT
       Where Cod_Estabe = @PCodEstabe
         And Cod_Abaste = @PCodAbaste
         And Cod_Produt = @CodPrd 
         And Cod_Lote = @CodLot
         And Cod_Dep = @CodDep
         And Num_Rua = @NumRuaDe
         And Num_Col = @NumColDe
         And Num_Niv = @NumNivDe
         And Num_Apt = @NumAptDe
    end

  FETCH NEXT FROM Abait_Cr INTO @CodPrd, @CodLot, @CodDep, @NumRuaDe, @NumColDe, @NumNivDe, @NumAptDe, @QtdMov,
                                @NumRuaPara, @NumColPara, @NumNivPara, @NumAptPara, @DesUsu
END
CLOSE Abait_Cr
DEALLOCATE Abait_Cr

if ((@FlgAchou = 0) and (@PCodProdut = 0))
  begin
    -- Elimina abastecimento  
    if Exists(Select 1 From ABACB 
               Where Cod_Estabe = @PCodEstabe And Cod_Abaste = @PCodAbaste 
	             And ((Cod_Sta = 'A') or (Cod_Sta = 'C')))
      begin
        Delete From ABAIT
         Where Cod_Estabe = @PCodEstabe
           And Cod_Abaste = @PCodAbaste
        
        Delete From ABACB
         Where Cod_Estabe = @PCodEstabe
           And Cod_Abaste = @PCodAbaste
      end 
  end
if ((@FlgAchou = 0) and (@PCodProdut > 0))
  begin
    -- Elimina apenas produto do abastecimento quando for passado por produto(Coletor)
    if Exists(Select 1 From ABACB 
               Where Cod_Estabe = @PCodEstabe And Cod_Abaste = @PCodAbaste 
	             And ((Cod_Sta = 'A') or (Cod_Sta = 'C')))
      begin
        Delete From ABAIT
         Where Cod_Estabe = @PCodEstabe
           And Cod_Abaste = @PCodAbaste
		   And Cod_Produt = @PCodProdut
      end 
  end
  --  Fechar abastecimento apenas aqui, pois pode acontecer de apenas o ultimo produto não ser atendido
Update ABACB
   Set Cod_Sta = 'F'
 Where Cod_Estabe = @PCodEstabe
   And Cod_Abaste = @PCodAbaste
   And ((Cod_Sta = 'A') or (Cod_Sta = 'C'))
   And not Exists(Select 1 From ABAIT Where Cod_Estabe = @PCodEstabe And Cod_Abaste = @PCodAbaste and IsNull(Flg_Proces,0) = 0) 
   
COMMIT TRANSACTION
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].PR_GeraAbastecimentoPrePicking
@PCodEstabe int,
@PCodDep int,
@PCodFab int,
@PCodPrd int,
@PNumRuaOriIni int,
@PNumRuaOriFim int,
@PNumRuaDesIni int,
@PNumRuaDesFim int

AS

BEGIN

SET NOCOUNT ON 

SET ANSI_WARNINGS OFF
--SET ANSI_NULLS OFF

-- verifica se existe endereço disponivel pre-picking
if not Exists(Select 1 From V_ENDDP Where IsNull(Flg_PrePck,0) = 1 And IsNull(Vol_Dispon,0) > 1.0)
  begin
    RAISERROR('Não existe endereço pré-picking disponível',16,1)
	Return
  end
else
-- verifica se há integração com WMS externo
if (Select IsNull(FlgIntegrWmsExt,0) From PMEST Where Cod_Estabe = @PCodEstabe) = 0
BEGIN
BEGIN TRANSACTION

-- Pegar a data atual com a hora 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)

Declare @CodPrd int,
        @FabIni int,
        @FabFim int,
        @StaAbc varchar(1),
        @QtdAba int,
        @QtdMov int,
        @CodAba int,

        @CodLot varchar(20),
        @DatVct smalldatetime,
        @QtdLotEnd int,
        @QtdEmbFec int,
        @QtdEmbFecCal int,
        @AccQtd int,
        @QtdFraArm int,

        @NumRuaDe smallint,
        @NumColDe smallint,
        @NumNivDe smallint,
        @NumAptDe smallint,
		@NumRuaPara smallint,
        @NumColPara smallint,
        @NumNivPara smallint,
        @NumAptPara smallint,

        @VolDis numeric(18,4),
        @VolUniEmbFec numeric(18,4),
        @VolTotArm numeric(18,4),
        @Cont smallint,
        @FlgAchou bit,
        @FlgCriouAba bit,
        @FlgLoteAnteriorAtendido bit

-- fabricante
Set @FabIni = @PCodFab
if @PCodFab > 0
  Set @FabFim = @PCodFab
else
  Set @FabFim = (Select max(Cod_Fabricante) From PRODU)

-- rua de origem final
if @PNumRuaOriFim = 0
  Set @PNumRuaOriFim = (Select max(Num_Rua) From ENDDP Where Cod_Estabe = @PCodEstabe And Cod_Dep = @PCodDep And IsNull(Flg_PrePck,0) = 0)

-- rua de destino final
if @PNumRuaDesFim = 0
  Set @PNumRuaDesFim = (Select max(Num_Rua) From ENDDP Where Cod_Estabe = @PCodEstabe And Cod_Dep = @PCodDep And IsNull(Flg_PrePck,0) = 1)

-- sinaliza que criou registro em ABACB
Set @FlgCriouAba = 0

-- produtos pre-picking que que necessitam abastecimento
Declare DPXPR_Cr Cursor Local Fast_Forward For 

  Select dp.Cod_Produt, pr.Sta_AbcAcesso, 
	     QtdAbaste = dp.Qtd_MaxPrePck - IsNull(lp.QtdSldPrePck,0)
  From DPXPR dp Inner Join
       PRODU pr on dp.Cod_Produt = pr.Codigo Left Join

	   -- qtd armazenada em endereços de pré-picking
       (Select l1.Cod_Produt, QtdSldPrePck=sum(l1.Qtd_Saldo) 
	    From PRLTL l1 Inner Join
             ENDDP e1 on (l1.Cod_Estabe = e1.Cod_Estabe and l1.Cod_Dep = e1.Cod_Dep and l1.Num_Rua = e1.Num_Rua and
                          l1.Num_Col = e1.Num_Col and l1.Num_Niv = e1.Num_Niv and l1.Num_Apt = e1.Num_Apt and
						  IsNull(e1.Flg_PrePck,0) = 1)
        Where l1.Cod_Estabe = @PCodEstabe
        And l1.Cod_Dep = @PCodDep
		And l1.Qtd_Saldo > 0
		And dbo.FN_TipLocEnd(l1.Cod_Estabe,l1.Cod_Dep,l1.Num_Rua) = 'D'
		Group by l1.Cod_Produt) lp on (dp.Cod_Produt = lp.Cod_Produt) Left Join

		-- qtd armazenada em endereços não pre-picking
       (Select l2.Cod_Produt, QtdSldPulmao = sum(l2.Qtd_Saldo)
        From PRLTL l2 Inner Join
             ENDDP e2 on (l2.Cod_Estabe = e2.Cod_Estabe and l2.Cod_Dep = e2.Cod_Dep and l2.Num_Rua = e2.Num_Rua and
                          l2.Num_Col = e2.Num_Col and l2.Num_Niv = e2.Num_Niv and l2.Num_Apt = e2.Num_Apt And +
					      IsNull(e2.Flg_PrePck,0) = 0 )
         Where l2.Cod_Estabe = @PCodEstabe   
         And l2.Cod_Dep = @PCodDep
         And dbo.FN_TipLocEnd(l2.Cod_Estabe,l2.Cod_Dep,l2.Num_Rua) = 'D'
         And l2.Qtd_Saldo > 0 
         Group by l2.Cod_Produt) lt on (dp.Cod_Produt = lt.Cod_Produt)

  Where dp.Cod_Estabe = @PCodEstabe
  And dp.Cod_Dep = @PCodDep
  And IsNull(dp.Flg_PrePck,0) = 1                         -- produtos destinados para pré-picking
  And dp.Qtd_MaxPrePck > 0                                -- existe configuração de armazenagem
  And not Exists (Select 1 From ABACB c Inner Join 
                                ABAIT i on c.Cod_Estabe = i.Cod_Estabe and c.Cod_Abaste = i.Cod_Abaste 
                  Where c.Cod_Estabe = @PCodEstabe and c.Cod_Pro = 'T' and c.Cod_Sta = 'A' and i.Cod_Produt = dp.Cod_Produt) 
  And pr.Cod_Fabricante between @FabIni and @FabFim
  And pr.Codigo > 0
  And IsNull(lt.QtdSldPulmao,0) > 0                       -- existe saldo deposito endereços não pre-picking
  And (dp.Qtd_MaxPrePck - IsNull(lp.QtdSldPrePck,0)) > 0  -- necessita abastecimento
  Order by pr.Sta_AbcAcesso, dp.Cod_Produt                -- ordenar por classificação acesso

Open DPXPR_Cr
Fetch Next From DPXPR_Cr Into @CodPrd, @StaAbc, @QtdAba
While @@FETCH_STATUS = 0 -- 1 (produtos pre-picking que necessitam reabastecimento)
  begin
    -- acumulador de qtd a abastecer: @CodPrd, @QtdAba
    Set @AccQtd = @QtdAba
    Set @FlgLoteAnteriorAtendido = 1

    -- selciona lotes endereços não pre-picking disponiveis por vencimento/end. mais distante
    DECLARE LOTES_Cr CURSOR Local Fast_Forward For 

        Select l.Cod_Lote, l.Dat_Vencim, l.Num_Rua, l.Num_Col, l.Num_Niv, l.Num_Apt, 
		       l.Qtd_EmbFec, l.C_QtdEmbFec, l.Qtd_Saldo
        From PRLTL l Inner Join
             ENDDP e on (l.Cod_Estabe = e.Cod_Estabe and l.Cod_Dep = e.Cod_Dep and l.Num_Rua = e.Num_Rua and
                          l.Num_Col = e.Num_Col and l.Num_Niv = e.Num_Niv and l.Num_Apt = e.Num_Apt And 
					      IsNull(e.Flg_PrePck,0) = 0 ) 
         Where l.Cod_Estabe = @PCodEstabe   
         And l.Cod_Dep = @PCodDep
         And dbo.FN_TipLocEnd(l.Cod_Estabe,l.Cod_Dep,l.Num_Rua) = 'D'
		 And l.Cod_Produt = @CodPrd
         And l.Qtd_Saldo > 0 
		 And l.Qtd_EmbFec > 0
         And l.Num_Rua between @PNumRuaOriIni and @PNumRuaOriFim
         Order by l.Dat_Vencim, l.Num_Rua desc, l.Num_Niv desc, l.Num_Apt desc, l.Num_Col desc

    OPEN LOTES_Cr
    FETCH NEXT FROM LOTES_Cr INTO @CodLot, @DatVct, @NumRuaDe, @NumColDe, @NumNivDe, @NumAptDe, 
	                              @QtdEmbFec, @QtdEmbFecCal, @QtdLotEnd

    WHILE (@@FETCH_STATUS = 0) and (@AccQtd > 0) and (@FlgLoteAnteriorAtendido = 1)  -- 2 (lotes disponiveis nao pre-picking)
    BEGIN
      -- inicializar contador de procura de endereços do lote
      Set @Cont = 1
      Set @FlgLoteAnteriorAtendido = 0

	  -- calcula volume da caixa fechada do lote
      Select @VolUniEmbFec = Case
                               When IsNull(e1.Vol_Emb,0) > 0 then e1.Vol_Emb
                               When (pr.Qtd_Embalagem = @QtdEmbFec) and (IsNull(pr.Alt_EmbCmp,0)) > 0 then pr.Alt_EmbCmp*pr.Lrg_EmbCmp*pr.Prf_EmbCmp
                               When IsNull(e2.Vol_Emb,0) > 0 then @QtdEmbFec*e2.Vol_Emb
                               When IsNull(pr.Alt_Emb,0) > 0 then @QtdEmbFec*pr.Alt_Emb*pr.Lrg_Emb*pr.Prf_Emb
                               Else 0
                             End
        From PRODU pr Left Join
             PREAN e1 on (pr.Codigo = e1.Cod_Produt and @QtdEmbFec = e1.Qtd_UndEmb and e1.Tip_Cod = '4' and e1.Vol_Emb > 0) Left Join
             PREAN e2 on (pr.Codigo = e2.Cod_Produt and e2.Tip_Cod = '3' and e2.Vol_Emb > 0)
        Where pr.Codigo = @CodPrd

      -- qtd do lote a movimentar - multiplo de cxa.fechada
      if @AccQtd >= @QtdLotEnd
        Set @QtdFraArm = @QtdLotEnd
      else
        Set @QtdFraArm = @AccQtd

      -- normaliza quantidade e volume a armazenar
      Set @QtdFraArm = (@QtdFraArm/@QtdEmbFecCal) * @QtdEmbFecCal
      Set @VolTotArm = (@QtdFraArm/@QtdEmbFecCal) * @VolUniEmbFec 

      -- devido a limitacao da chave em ABAIT so posso incluir um registro de PRLTL (Produto/lote/End.Armazenagem de origem)
      Set @FlgAchou = 0  -- sinaliza se a consulta relacionada com o contador obteve sucesso

	  -- procura endereços pre-picking disponiveis
      while (@QtdFraArm > 0) and (@Cont <= 4) and (@FlgAchou = 0)
        begin
           -- 1: seleciona somente endereços pre-picking com mesmo produto/lote 
          if @Cont = 1
            begin
              DECLARE ENDDP_Cr CURSOR Local Fast_Forward For 
                Select en.Num_Rua, en.Num_Col, en.Num_Niv, en.Num_Apt, en.Vol_Dispon
                  From V_ENDDP en
                Where en.Cod_Estabe = @PCodEstabe                             
                And en.Cod_Dep = @PCodDep                             
                And IsNull(en.Flg_DepFec,0) = 1 
                And IsNull(en.Flg_Bloqueado,0) = 0 
                And IsNull(en.Flg_PrePck,0) = 1 
                And en.Num_Rua between @PNumRuaDesIni and @PNumRuaDesFim
                And en.Vol_Dispon >= @VolTotArm --@VolUniEmbFec 
                And Exists(Select 1 From PRLTL lt Where lt.Cod_Estabe = en.Cod_Estabe and lt.Cod_Dep = en.Cod_Dep and 
                                                        lt.Num_Rua = en.Num_Rua and lt.Num_Col = en.Num_Col and
                                                        lt.Num_Niv = en.Num_Niv and lt.Num_Apt = en.Num_Apt and
														lt.Cod_Produt = @CodPrd and lt.Cod_Lote = @CodLot)
                Order by en.Num_Rua, en.Num_Col, en.Num_Niv
            end
          else  
           -- 2: seleciona somente endereços que atendem a quantidade e à curva (ou a mais proxima acima)
          if @Cont = 2
            begin
              DECLARE ENDDP_Cr CURSOR Local Fast_Forward For 
                Select en.Num_Rua, en.Num_Col, en.Num_Niv, en.Num_Apt, en.Vol_Dispon
                  From V_ENDDP en 
                Where en.Cod_Estabe = @PCodEstabe                             
                And en.Cod_Dep = @PCodDep                             
                And IsNull(en.Flg_DepFec,0) = 1 
                And IsNull(en.Flg_Bloqueado,0) = 0 
                And IsNull(en.Flg_PrePck,0) = 1 
                And en.Num_Rua between @PNumRuaDesIni and @PNumRuaDesFim
                And en.Vol_Dispon >= @VolTotArm  --@VolUniEmbFec 
                And Substring(IsNull(en.Str_AbcAcesso,''),1,1) >= @StaAbc
                And not Exists(Select 1 From PRLTL lt Where lt.Cod_Estabe = en.Cod_Estabe and lt.Cod_Dep = en.Cod_Dep and 
                                                            lt.Num_Rua = en.Num_Rua and lt.Num_Col = en.Num_Col and
                                                            lt.Num_Niv = en.Num_Niv and lt.Num_Apt = en.Num_Apt and
                                                            lt.Cod_Produt = @CodPrd)
                Order by Substring(IsNull(en.Str_AbcAcesso,''),1,1), en.Num_Rua, en.Num_Col, en.Num_Niv
            end
          else  
           -- 3: seleciona somente endereços que atendem a quantidade e sem curva definida
          if @Cont = 3
            begin
              DECLARE ENDDP_Cr CURSOR Local Fast_Forward For 
                Select en.Num_Rua, en.Num_Col, en.Num_Niv, en.Num_Apt, en.Vol_Dispon
                  From V_ENDDP en 
                Where en.Cod_Estabe = @PCodEstabe                             
                And en.Cod_Dep = @PCodDep                             
                And IsNull(en.Flg_DepFec,0) = 1 
                And IsNull(en.Flg_Bloqueado,0) = 0 
                And IsNull(en.Flg_PrePck,0) = 1 
                And en.Num_Rua between @PNumRuaDesIni and @PNumRuaDesFim
                And en.Vol_Dispon >= @VolTotArm 
                And Substring(IsNull(en.Str_AbcAcesso,''),1,1) = ''
                And not Exists(Select 1 From PRLTL lt Where lt.Cod_Estabe = en.Cod_Estabe and lt.Cod_Dep = en.Cod_Dep and 
                                                            lt.Num_Rua = en.Num_Rua and lt.Num_Col = en.Num_Col and
                                                            lt.Num_Niv = en.Num_Niv and lt.Num_Apt = en.Num_Apt and
                                                            lt.Cod_Produt = @CodPrd)
                Order by Substring(IsNull(en.Str_AbcAcesso,''),1,1), en.Num_Rua, en.Num_Col, en.Num_Niv
            end
          else  
           -- 4: seleciona somente endereços que atendem a quantidade e com curva inferior
          if @Cont = 4
            begin
              DECLARE ENDDP_Cr CURSOR Local Fast_Forward For 
                Select en.Num_Rua, en.Num_Col, en.Num_Niv, en.Num_Apt, en.Vol_Dispon
                  From V_ENDDP en 
                Where en.Cod_Estabe = @PCodEstabe                             
                And en.Cod_Dep = @PCodDep                             
                And IsNull(en.Flg_DepFec,0) = 1 
                And IsNull(en.Flg_Bloqueado,0) = 0 
                And IsNull(en.Flg_PrePck,0) = 1 
                And en.Num_Rua between @PNumRuaDesIni and @PNumRuaDesFim
                And en.Vol_Dispon >= @VolTotArm 
                And Substring(IsNull(en.Str_AbcAcesso,''),1,1) < @StaAbc
                And not Exists(Select 1 From PRLTL lt Where lt.Cod_Estabe = en.Cod_Estabe and lt.Cod_Dep = en.Cod_Dep and 
                                                            lt.Num_Rua = en.Num_Rua and lt.Num_Col = en.Num_Col and
                                                            lt.Num_Niv = en.Num_Niv and lt.Num_Apt = en.Num_Apt and
                                                            lt.Cod_Produt = @CodPrd)
                Order by Substring(IsNull(en.Str_AbcAcesso,''),1,1) desc, en.Num_Rua, en.Num_Col, en.Num_Niv
            end
            
          OPEN ENDDP_Cr
          FETCH NEXT FROM ENDDP_Cr INTO @NumRuaPara, @NumColPara, @NumNivPara, @NumAptPara, @VolDis
          WHILE (@@FETCH_STATUS = 0) and (@FlgAchou = 0)
          BEGIN
            Set @QtdMov = 0

            -- recalcula quantidade a movimentar
            if @VolUniEmbFec > 0
              begin
                if @VolTotArm > @VolDis
                  Set @QtdMov = (@VolDis/@VolUniEmbFec) * @QtdEmbFecCal
                else
                  Set @QtdMov = @QtdFraArm 
              end

            if @QtdMov > @QtdFraArm
              Set @QtdMov = @QtdFraArm 

            -- gera registro de abastecimento (pre-picking)
            if @QtdMov > 0
              begin
                -- cria registro cabeçalho em ABACB
                if @FlgCriouAba = 0
                  begin
                    Select @CodAba = IsNull((Select Max(Cod_Abaste) From ABACB Where Cod_Estabe = @PCodEstabe),0) + 1 
                    Insert Into ABACB (Cod_Estabe, Cod_Abaste, Des_Abaste, Cod_Dep, Cod_Pro, Cod_Sta, Usuario)
                               Values (@PcodEstabe, @CodAba, 'PRE-PICKING', @PCodDep, 'T', 'A', 'SISTEMA')
                    if @@error <> 0
                      begin
                        Rollback Transaction
                        Return
                      end

                    Set @FlgCriouAba = 1
                  end					   

                -- inclui registro ABAIT
                if not Exists(Select Cod_Produt 
                              From ABAIT
                              Where Cod_Estabe = @PCodEstabe
                              And Cod_Abaste = @CodAba         
                              And Cod_Produt = @CodPrd And Cod_Lote = @CodLot  
                              And Cod_Dep = @PCodDep
                              And Num_Rua = @NumRuaDe And Num_Col = @NumColDe
                              And Num_Niv = @NumNivDe And Num_Apt = @NumAptDe)
                  begin
                    Insert Into ABAIT (Cod_Estabe, Cod_Abaste, Cod_Produt, Cod_Lote, 
                                       Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Qtd_Mov,
                                       Num_RuaDes, Num_ColDes, Num_NivDes, Num_AptDes, Flg_Proces)
                               Values (@PCodEstabe, @CodAba, @CodPrd, @CodLot,
                                       @PCodDep, @NumRuaDe, @NumColDe, @NumNivDe, @NumAptDe, @QtdMov,
                                       @NumRuaPara, @NumColPara, @NumNivPara, @NumAptPara, 0)
                    if @@error <> 0
                      begin
                        Rollback Transaction
                        Return
                      end

                    Set @FlgLoteAnteriorAtendido = 1
                    Set @QtdFraArm = @QtdFraArm - @QtdMov      
                    Set @AccQtd = @AccQtd - @QtdMov

                    -- sinaliza que achou
                    Set @FlgAchou = 1
                  end
                      
              end
            
            FETCH NEXT FROM ENDDP_Cr INTO @NumRuaPara, @NumColPara, @NumNivPara, @NumAptPara, @VolDis
          END  --WHILE (@@FETCH_STATUS = 0) and (@FlgAchou = 0)
          
          CLOSE ENDDP_Cr
          DEALLOCATE ENDDP_Cr    

          -- incrementa contador 
          Set @Cont = @Cont + 1

        end -- while (@QtdFraArm > 0) and (@Cont <= 4)

      FETCH NEXT FROM LOTES_Cr INTO @CodLot, @DatVct, @NumRuaDe, @NumColDe, @NumNivDe, @NumAptDe, 
	                                @QtdEmbFec, @QtdEmbFecCal, @QtdLotEnd
    END    -- WHILE (@@FETCH_STATUS = 0) and (@AccQtd > 0) and (@FlgLoteAnteriorAtendido = 1)  -- 2 (lotes disponiveis nao pre-picking)

    CLOSE LOTES_Cr
    DEALLOCATE LOTES_Cr    

    Fetch Next From DPXPR_Cr Into @CodPrd, @StaAbc, @QtdAba
  end  -- While @@FETCH_STATUS = 0 -- 1 (produtos pre-picking que necessitam reabastecimento)

Close DPXPR_Cr
Deallocate DPXPR_Cr

COMMIT TRANSACTION
END
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_RetornaAbstecimentoPedidosPendentes]
@PCodEstabe int,
@PNumPdvIni int,
@PNumPdvFim int,
@PCodRot int,
@PStrOriPdv varchar(30),
@PNumRuaIni int,
@PNumRuaFim int

WITH RECOMPILE 
AS

BEGIN

SET NOCOUNT ON 

BEGIN TRANSACTION

-- Pegar a data atual com a hora 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)

Declare @CodPrd int,
        @CodGrpCli int,
        @DatVctMin smalldatetime, 
        @QtdPdv int,
        @ChavePdv int,
        @ChaveLot int,
        @ChaveLtl int,
        @DatVct smalldatetime, 
        @QtdSld int,
        @QtdEmbFec int,
        @QtdAteDep int,
        @QtdMov int,
        @CodDep smallint,
        @CodDepAnt smallint,
        @CodAba int,
        @DesAba varchar(50),
        @CodLot varchar(20),
        @NumRua smallint,
        @NumCol smallint,
        @NumNiv smallint,
        @NumApt smallint,
        @PCodRotIni int,
        @PCodRotFim int,
		@Usuario varchar(15)
        
Set @Usuario = dbo.FN_UsuarioInfarma()

Set @DesAba = ''
Set @PCodRotIni = 0
Set @PCodRotFim = 0

if @PCodRot > 0
  begin
    Set @DesAba = 'ROTA '+cast(@PCodRot as varchar)
    Set @PCodRotIni = @PCodRot
    Set @PCodRotFim = @PCodRot
  end
else
  begin
    Set @PCodRotIni = IsNull((Select Min(IsNull(Cod_Rota,0)) From PDVCB Where Cod_Estabe = @PCodEstabe),0)
    Set @PCodRotFim = IsNull((Select Max(IsNull(Cod_Rota,0)) From PDVCB Where Cod_Estabe = @PCodEstabe),0)
  end

if @PStrOriPdv <> ''
  begin
    if @DesAba <> ''
	  Set @DesAba = @DesAba + ' - ' 
    Set @DesAba = @DesAba + 'ORIGEM ('+@PStrOriPdv+')'
  end

if @PNumPdvIni > 0
  begin
    if @DesAba <> ''
	  Set @DesAba = @DesAba + ' - ' 
    if @PNumPdvFim > @PNumPdvIni 
      Set @DesAba = @DesAba + 'P.'+cast(@PNumPdvIni as varchar)+'_'+Cast(@PNumPdvFim as varchar)
    else
      Set @DesAba = @DesAba + 'PED.'+cast(@PNumPdvIni as varchar)
  end

if IsNull(@DesAba,'') = ''
  Set @DesAba = 'PED.'+ CONVERT(VARCHAR, @Date, 103);

if @PNumPdvFim = 0
  Set @PNumPdvFim = (Select MAX(Numero) From PDVCB Where Cod_Estabe = @PCodEstabe)

if @PNumRuaFim = 0
  Set @PNumRuaFim = (Select MAX(Num_Rua) From PRLTL Where Cod_Estabe = @PCodEstabe)
  
-- normaliza ABACB
Update ABACB
  Set Cod_Pro = 'A'  -- fracionados 'T' - pre-picking
Where IsNull(Rtrim(Ltrim(Cod_Pro)),'') = ''   

-- cria arq. de lotes q poderão ser necessários
IF OBJECT_ID('tempdb..#ARQ_PDVIT') IS NOT NULL
  DROP TABLE #ARQ_PDVIT

IF OBJECT_ID('tempdb..#ARQ_PRLTL') IS NOT NULL
  DROP TABLE #ARQ_PRLTL

IF OBJECT_ID('tempdb..#ARQ_PRLOT') IS NOT NULL
  DROP TABLE #ARQ_PRLOT

IF OBJECT_ID('tempdb..#ARQ_ABAST') IS NOT NULL
  DROP TABLE #ARQ_ABAST


CREATE TABLE #ARQ_PDVIT
(
    Chave int identity,
    Cod_Pedido int,
    Cod_GrpCli int,
    Cod_Produto int,
    Dat_VctMin smalldatetime,
    Qtd_Pdv int
) 

CREATE TABLE #ARQ_PRLTL
(
    Chave int identity,
    Cod_Dep smallint,
    Cod_Produto int,
    Dat_Vencim smalldatetime,
    Qtd_EmbFec int,
    Qtd_Saldo int
) 

CREATE TABLE #ARQ_PRLOT
(
    Chave int identity,
    Cod_Dep smallint,
    Cod_Produto int,
    Dat_Vencim smalldatetime,
    Qtd_Saldo int
) 

CREATE TABLE #ARQ_ABAST
(
    Cod_Dep smallint,
    Cod_Produto int,
    Dat_Vencim smalldatetime,
    Qtd_Lote int
) 


/* <Índices> */
CREATE UNIQUE CLUSTERED INDEX IX_CL_ARQ_PDVIT ON #ARQ_PDVIT (Chave);
CREATE NONCLUSTERED INDEX IX_ARQ_PDVIT_Cod_Produto ON #ARQ_PDVIT (Cod_Produto);
CREATE NONCLUSTERED INDEX IX_ARQ_PDVIT_Cod_GrpCli ON #ARQ_PDVIT (Cod_GrpCli);

CREATE UNIQUE CLUSTERED INDEX IX_CL_ARQ_PRLTL ON #ARQ_PRLTL (Chave);
CREATE NONCLUSTERED INDEX IX_CL_ARQ_PRLTL_Cod_Dep_Cod_Produto_Dat_Vencim ON #ARQ_PRLTL (Cod_Dep, Cod_Produto, Dat_Vencim);

CREATE UNIQUE CLUSTERED INDEX IX_CL_ARQ_PRLOT ON #ARQ_PRLOT (Chave);
CREATE NONCLUSTERED INDEX IX_CL_ARQ_PRLOT_Cod_Dep_Cod_Produto_Dat_Vencim ON #ARQ_PRLOT (Cod_Dep, Cod_Produto, Dat_Vencim);

CREATE CLUSTERED INDEX IX_CL_ARQ_ABAST ON #ARQ_ABAST (Cod_Dep, Cod_Produto, Dat_Vencim);
/* </Índices> */


-- cria arq. de pedidos
Insert Into #ARQ_PDVIT (Cod_Pedido, Cod_GrpCli, Cod_Produto, Dat_VctMin, Qtd_Pdv)
  Select a.Cod_Pedido, a.Cod_GrpCli, a.Cod_Produto, a.DatVctMin, a.QtdPdv
    From (Select it.Cod_Pedido, Cod_GrpCli=IsNull(cl.Cod_GrpCli,0), it.Cod_Produto, 
                 DatVctMin = Case 
                               When IsNull(vp.Cod_Produt,0) > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0)) 
                               When IsNull(vf.Cod_Fabric,0) > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0)) 
                               Else dbo.FN_DataVenctoMinimo(@Date,IsNull(cl.Qtd_MesMinPrzVctLot,0)) 
                             End, 
                 sum(it.Qtd_Pedido+it.Qtd_Bonificacao) as QtdPdv 
            From PDVCB cb Left Outer Join 
                 CLIEN cl on (cb.Cod_Cliente = cl.Codigo) Inner Join 
                 PDVIT it ON (cb.Cod_Estabe = it.Cod_Estabe and cb.Numero = it.Cod_Pedido) Inner Join 
                 PRODU pr on (it.Cod_Produto = pr.Codigo) Left Outer Join 
                 CLPRV vp on ((vp.Cod_CliPag = Case When IsNull(cl.Cod_CliPag,0) > 0 Then cl.Cod_CliPag Else cl.Codigo End) and 
                              (vp.Cod_Produt = pr.Codigo)) Left Outer Join 
                 CLFBV vf on ((vf.Cod_CliPag = Case When IsNull(cl.Cod_CliPag,0) > 0 Then cl.Cod_CliPag Else cl.Codigo End) and 
                              (vf.Cod_Fabric = pr.Cod_Fabricante)) 
          Where cb.Cod_Estabe = @PCodEstabe
          and cb.Status1 = 'P' and cb.Status2 = 'F'
          and cb.Tip_Pedido = 'P'
          and IsNull(cb.Flg_WMS,0) = 1 
          and IsNull(cb.Sta_IntWMS,'') = ''
          and IsNull(cb.Bloqueio,'') = ''
          and IsNull(cb.Cod_BlqRnt,'') <> 'B'
          and IsNull(cb.Cod_BlqLic,'') <> 'B'
          and it.Qtd_Pedido > 0
          and not Exists (Select 1 From PDVLT Where Cod_Estabe = cb.Cod_Estabe and Cod_Pedido = cb.Numero)
          and cb.Numero between @PNumPdvIni and @PNumPdvFim
          and IsNull(cb.Cod_Rota,0) between @PCodRotIni and @PCodRotFim
          and ((IsNull(@PStrOriPdv,'') = '') or (CharIndex(Substring(Cod_OrigemPdv,1,1),@PStrOriPdv) > 0))
          Group by it.Cod_Estabe, it.Cod_Pedido, IsNull(cl.Cod_GrpCli,0), it.Cod_Produto, cl.Qtd_MesMinPrzVctLot, 
                   vp.Cod_Produt, vp.Qtd_MesMinPrzVctLot, 
                   vf.Cod_Fabric, vf.Qtd_MesMinPrzVctLot) a
  Where not Exists (Select 1 From ABACB c Inner Join 
                                  ABAIT i on c.Cod_Estabe = i.Cod_Estabe and c.Cod_Abaste = i.Cod_Abaste 
                    Where c.Cod_Estabe = @PCodEstabe and c.Cod_Pro = 'A' and c.Cod_Sta <> 'F' and i.Cod_Produt = a.Cod_Produto) 

-- cria arq. de lotes PRLTL
Insert Into #ARQ_PRLTL (Cod_Dep, Cod_Produto, Dat_Vencim, Qtd_EmbFec, Qtd_Saldo)
  Select lt.Cod_Dep, lt.Cod_Produt, IsNull(lt.Dat_Vencim,0), lt.C_QtdEmbFec, sum(lt.Qtd_saldo)
  From PRLTL lt Inner Join 
       (Select distinct Cod_Produto
        From #ARQ_PDVIT) pv on lt.Cod_Produt = pv.Cod_Produto       
  Where lt.Cod_Estabe = @PCodEstabe
  And lt.Qtd_Saldo > 0
  And dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua) = 'D'
  And lt.Qtd_Saldo >= lt.C_QtdEmbFec
  And lt.C_QtdEmbFec > 0 
  And lt.Num_Rua between @PNumRuaIni and @PNumRuaFim 
  Group by lt.Cod_Dep, lt.Cod_Produt, lt.Dat_Vencim, lt.C_QtdEmbFec 

-- cria arq. de lotes PRLOT
Insert Into #ARQ_PRLOT (Cod_Dep, Cod_Produto, Dat_Vencim, Qtd_Saldo)
  Select lt.Cod_Dep, lt.Cod_Produt, IsNull(lt.Dat_Vencim,0), sum(lt.Qtd_saldo)
  From PRLOT lt Inner Join
       (Select distinct Cod_Produto
        From #ARQ_PDVIT) pv on lt.Cod_Produt = pv.Cod_Produto       
  Where lt.Cod_Estabe = @PCodEstabe
  And lt.Qtd_Saldo > 0
  Group by lt.Cod_Dep, lt.Cod_Produt, lt.Dat_Vencim 

--------------------------------------------------------------------------------------------------------------------------------

-- seleciona itens de pedidos de depositos exclusivos
Declare PDVIT_Cr Cursor Local Fast_Forward For 
  Select a.Chave, a.Cod_GrpCli, a.Cod_Produto, a.Dat_VctMin, a.Qtd_Pdv
  From #ARQ_PDVIT a
   -- filtra grupos de clientes com depositos exclusivos
  Where Exists (Select 1 From DPXGC Where Cod_Estabe = @PCodEstabe and Cod_GrpCli = a.Cod_GrpCli)
  Order by Cod_Produto, Dat_VctMin 
Open PDVIT_Cr
Fetch Next From PDVIT_Cr Into @ChavePdv, @CodGrpCli, @CodPrd, @DatVctMin, @QtdPdv
While @@FETCH_STATUS = 0
  begin
    -- verifica se existe itens que podem ser atendidos pelo deposito exclusivo
    while Exists(Select 1
                   From #ARQ_PRLTL a
                 Where Cod_Produto = @CodPrd
                 And ((IsNull(a.Dat_Vencim,0) = 0) or (IsNull(a.Dat_Vencim,0) >= IsNull(@DatVctMin,0)))
                 And @QtdPdv >= a.Qtd_EmbFec
                 And a.Qtd_Saldo >= a.Qtd_EmbFec
                 And a.Qtd_EmbFec > 0
                 And Exists (Select 1 From DPXGC Where Cod_Estabe = @PCodEstabe and Cod_GrpCli = @CodGrpCli and Cod_Dep = a.Cod_Dep))
      begin
        Select top 1 @ChaveLtl = a.Chave, 
                     @DatVct = a.Dat_Vencim, 
                     @QtdSld = a.Qtd_Saldo, 
                     @QtdEmbFec = IsNull(a.Qtd_EmbFec,0) 
        From #ARQ_PRLTL a   
        Where a.Cod_Produto = @CodPrd
        And ((IsNull(a.Dat_Vencim,0) = 0) or (IsNull(a.Dat_Vencim,0) >= IsNull(@DatVctMin,0)))
        And @QtdPdv >= a.Qtd_EmbFec
        And a.Qtd_Saldo >= a.Qtd_EmbFec
        And a.Qtd_EmbFec > 0
        -- filtra depositos exclusivos
        And Exists (Select 1 From DPXGC Where Cod_Estabe = @PCodEstabe and Cod_GrpCli = @CodGrpCli and Cod_Dep = a.Cod_Dep)
        Order by Dat_Vencim, Cod_Dep

        Set @QtdAteDep = @QtdPdv/@QtdEmbFec*@QtdEmbFec

        -- simular atendimento do pulmão: dar baixa em PRLTL e PDVIT
        Update #ARQ_PRLTL
          Set Qtd_Saldo = Qtd_Saldo - @QtdAteDep
        Where Chave = @ChaveLtl
        
        Update #ARQ_PDVIT
          Set Qtd_Pdv = Qtd_Pdv - @QtdAteDep
        Where Chave = @ChavePdv
          
       Set @QtdPdv = @QtdPdv - @QtdAteDep    
       
      end

    Fetch Next From PDVIT_Cr Into @ChavePdv, @CodGrpCli, @CodPrd, @DatVctMin, @QtdPdv
  end
Close PDVIT_Cr
Deallocate PDVIT_Cr

-- seleciona itens de pedidos de depositos EXCLUSIVOS para atendimento pelo picking
Declare PDVIT_Cr Cursor Local Fast_Forward For 

  Select a.Chave, a.Cod_GrpCli, a.Cod_Produto, a.Dat_VctMin, a.Qtd_Pdv
  From #ARQ_PDVIT a
   -- filtra grupos de clientes com depositos exclusivos
  Where Exists (Select 1 From DPXGC Where Cod_Estabe = @PCodEstabe and Cod_GrpCli = a.Cod_GrpCli)
  Order by Cod_Produto, Dat_VctMin 
  
Open PDVIT_Cr
Fetch Next From PDVIT_Cr Into @ChavePdv, @CodGrpCli, @CodPrd, @DatVctMin, @QtdPdv
While @@FETCH_STATUS = 0
  begin
    -- verifica se existe itens que podem ser transferidos para picking
    while (IsNull((Select sum(a.Qtd_Saldo)
                   From #ARQ_PRLOT a
                   Where a.Cod_Produto = @CodPrd
                   And ((IsNull(a.Dat_Vencim,0) = 0) or (IsNull(a.Dat_Vencim,0) >= IsNull(@DatVctMin,0)))
                   And a.Qtd_Saldo > 0
                   -- filtra depositos exclusivos
                   And Exists (Select 1 From DPXGC Where Cod_Estabe = @PCodEstabe and Cod_Dep = a.Cod_Dep)),0) < @QtdPdv) and
          Exists(Select sum(a.Qtd_Saldo)
                 From #ARQ_PRLTL a
                 Where a.Cod_Produto = @CodPrd
                 And ((IsNull(a.Dat_Vencim,0) = 0) or (IsNull(a.Dat_Vencim,0) >= IsNull(@DatVctMin,0)))
                 And a.Qtd_Saldo > 0
                 And a.Qtd_EmbFec > 0
                 -- filtra depositos exclusivos
                 And Exists (Select 1 From DPXGC Where Cod_Estabe = @PCodEstabe and Cod_Dep = a.Cod_Dep)
                 Having SUM(Qtd_Saldo) > 0)
      begin
        Set @ChaveLtl = 0
        
        Select top 1 @ChaveLtl = a.Chave, 
                     @CodDep = a.Cod_Dep,
                     @DatVct = a.Dat_Vencim, 
                     @QtdSld = a.Qtd_Saldo,
                     @QtdEmbFec = IsNull(a.Qtd_EmbFec,0) 
        From #ARQ_PRLTL a 
        Where a.Cod_Produto = @CodPrd
        And ((IsNull(a.Dat_Vencim,0) = 0) or (IsNull(a.Dat_Vencim,0) >= IsNull(@DatVctMin,0)))
        And a.Qtd_Saldo > 0
        And a.Qtd_EmbFec > 0
        -- filtra depositos exclusivos
        And Exists (Select 1 From DPXGC Where Cod_Estabe = @PCodEstabe and Cod_Dep = a.Cod_Dep)
        Order by Dat_Vencim, Cod_Dep
        
        if not Exists(Select 1 From #ARQ_ABAST
                      Where Cod_Dep = @CodDep
                      And Cod_Produto = @CodPrd
                      And Dat_Vencim = @DatVct)     
            Insert Into #ARQ_ABAST (Cod_Dep, Cod_Produto, Dat_Vencim, Qtd_Lote)
              Values (@CodDep, @CodPrd, @DatVct, 0)
            
        Update #ARQ_ABAST
          Set Qtd_Lote = Qtd_Lote + @QtdEmbFec
        Where Cod_Dep = @CodDep
        And Cod_Produto = @CodPrd
        And Dat_Vencim = @DatVct
                          
        -- simular atendimento do picking: transferir de PRLTL, dar baixa em PRLOT e PDVIT
        Update #ARQ_PRLTL
          Set Qtd_Saldo = Qtd_Saldo - @QtdEmbFec
        Where Chave = @ChaveLtl

        if not Exists(Select Chave
                      From #ARQ_PRLOT
                      Where Cod_Dep = @CodDep
                      And Cod_Produto = @CodPrd
                      And Dat_Vencim = @DatVct)
          Insert Into #ARQ_PRLOT (Cod_Dep, Cod_Produto, Dat_Vencim, Qtd_Saldo)
            Values (@CodDep, @CodPrd, @DatVct, 0)

        Set @ChaveLot = 0
            
        Select top 1 @ChaveLot = Chave
        From #ARQ_PRLOT
        Where Cod_Dep = @CodDep
        And Cod_Produto = @CodPrd
        And Dat_Vencim = @DatVct

        Update #ARQ_PRLOT
          Set Qtd_Saldo = Qtd_Saldo + @QtdEmbFec
        Where Chave = @ChaveLot
  
/*        
        if @QtdEmbFec > @QtdPdv
          Set @QtdMov = @QtdPdv
        else  
          Set @QtdMov = @QtdEmbFec
        
        Update #ARQ_PDVIT
          Set Qtd_Pdv = Qtd_Pdv - @QtdMov
        Where Chave = @ChavePdv

        Update #ARQ_PRLOT
          Set Qtd_Saldo = Qtd_Saldo - @QtdMov
        Where Chave = @ChaveLot

        Set @QtdPdv = @QtdPdv - @QtdMov
*/            
      end
      
    -- dar baixa em PRLOT e PDVIT
    while (IsNull((Select sum(a.Qtd_Saldo)
                   From #ARQ_PRLOT a
                   Where a.Cod_Produto = @CodPrd
                   And ((IsNull(a.Dat_Vencim,0) = 0) or (IsNull(a.Dat_Vencim,0) >= IsNull(@DatVctMin,0)))
                   And a.Qtd_Saldo > 0
                   -- filtra depositos exclusivos
                   And Exists (Select 1 From DPXGC Where Cod_Estabe = @PCodEstabe And Cod_Dep = a.Cod_Dep)),0) > 0) and (@QtdPdv > 0)
      begin
        Set @QtdMov = 0

        Select top 1 @ChaveLot = a.Chave, 
                     @CodDep = a.Cod_Dep,
                     @DatVct = a.Dat_Vencim, 
                     @QtdSld = a.Qtd_Saldo
        From #ARQ_PRLOT a 
        Where a.Cod_Produto = @CodPrd
        And ((IsNull(a.Dat_Vencim,0) = 0) or (IsNull(a.Dat_Vencim,0) >= IsNull(@DatVctMin,0)))
        And a.Qtd_Saldo > 0
        -- filtra depositos exclusivos
        And Exists (Select 1 From DPXGC Where Cod_Estabe = @PCodEstabe and Cod_Dep = a.Cod_Dep)
        Order by Dat_Vencim, Cod_Dep

        if @QtdSld > @QtdPdv
          Set @QtdMov = @QtdPdv
        else  
          Set @QtdMov = @QtdSld

        Update #ARQ_PDVIT
          Set Qtd_Pdv = Qtd_Pdv - @QtdMov
        Where Chave = @ChavePdv

        Update #ARQ_PRLOT
          Set Qtd_Saldo = Qtd_Saldo - @QtdMov
        Where Chave = @ChaveLot

        Set @QtdPdv = @QtdPdv - @QtdMov
      end               
    
    Fetch Next From PDVIT_Cr Into @ChavePdv, @CodGrpCli, @CodPrd, @DatVctMin, @QtdPdv
  end
Close PDVIT_Cr
Deallocate PDVIT_Cr

