IF OBJECT_ID('tempdb..#ARQ_PRLTL') IS NOT NULL
  DROP TABLE #ARQ_PRLTL

IF OBJECT_ID('tempdb..#ARQ_PRLOT') IS NOT NULL
  DROP TABLE #ARQ_PRLOT

IF OBJECT_ID('tempdb..#ARQ_PDVIT') IS NOT NULL
  DROP TABLE #ARQ_PDVIT
-------------------------------------------------------------------------------------


CREATE TABLE #AUX_PRLTL
(
    Cod_Dep smallint,
	Flg_PrePck bit,
    Num_Rua smallint, 
    Num_Col smallint, 
    Num_Niv smallint, 
    Num_Apt smallint, 
    Cod_Produto int,
    Cod_Lote varchar(20),
    Dat_Vencim smalldatetime,
    Dat_Entrada smalldatetime,
    Qtd_EmbFec int,
    Qtd_Saldo int
) 

Insert Into #AUX_PRLTL (Cod_Dep, Flg_PrePck, Num_Rua, Num_Col, Num_Niv, Num_Apt, 
                        Cod_Produto, Cod_Lote, Dat_Vencim, Dat_Entrada, Qtd_EmbFec, Qtd_Saldo)
  Select lt.Cod_Dep, en.Flg_PrePck, lt.Num_Rua, lt.Num_Col, lt.Num_Niv, lt.Num_Apt, 
         lt.Cod_Produt, lt.Cod_Lote, lt.Dat_Vencim, lt.Dat_Entrada, lt.C_QtdEmbFec, lt.Qtd_saldo
  From PRLTL lt Inner Join 
       (Select distinct Cod_Dep, Cod_Produto
        From #ARQ_ABAST) ab on (lt.Cod_Dep = ab.Cod_Dep and lt.Cod_Produt = ab.Cod_Produto) Left Join
       ENDDP en on (lt.Cod_Estabe = en.Cod_Estabe and lt.Cod_Dep = en.Cod_Dep and lt.Num_Rua = en.Num_Rua and
                    lt.Num_Col = en.Num_Col and lt.Num_Niv = en.Num_Niv and lt.Num_Apt = en.Num_Apt)
  Where lt.Cod_Estabe = @PCodEstabe
  And lt.Qtd_Saldo > 0
  And dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua) = 'D'
  And lt.Qtd_Saldo >= lt.C_QtdEmbFec


-- seleciona itens a abastecer
Declare PDVIT_Cr Cursor Local Fast_Forward For 

  Select Cod_Dep, Cod_Produto, Dat_Vencim, Qtd_Lote  
  From #ARQ_ABAST
  Order by Cod_Dep
  
Open PDVIT_Cr
Fetch Next From PDVIT_Cr Into @CodDep, @CodPrd, @DatVct, @QtdPdv
While @@FETCH_STATUS = 0
  begin
    -- elimina cabecalho aberto sem itens
    Delete cb
    From ABACB cb
    Where cb.Cod_Estabe = @PCodEstabe
    And cb.Cod_Pro = 'A'   -- fracionados 'T' - pre-picking
    And cb.Cod_Sta <> 'F'
    And not Exists(Select 1 From ABAIT it 
                   Where it.Cod_Estabe = cb.Cod_Estabe 
                   And it.Cod_Abaste = cb.Cod_Abaste)

    -- cria cabecalho ABACB: @CodDep
    Set @CodDepAnt = @CodDep

/*
    if Exists(Select 1 From ABACB
              Where Cod_Estabe = @PCodEstabe
              And Cod_Dep = @CodDep
              And Cod_Sta <> 'F')
      begin
        RAISERROR('Já existe Abastecimento Pendente. Procedimento Cancelado',16,1)
        Rollback Transaction
        Return
      end          
*/

    Select @CodAba = IsNull((Select Max(Cod_Abaste) From ABACB Where Cod_Estabe = @PCodEstabe),0) + 1 
	Set @DesAba = Substring(@DesAba, 1, 50)
      
    Insert Into ABACB (Cod_Estabe, Cod_Abaste, Des_Abaste, Cod_Dep, Cod_Pro, Cod_Sta, Usuario)
               Values (@PcodEstabe, @CodAba, @DesAba, @CodDep, 'A', 'A', @Usuario)
          
    -- elimina lixo pendente      
    Delete 
    From ABAIT 
    Where Cod_Estabe = @PCodEstabe
    And Cod_Abaste = @CodAba
          
    While (@CodDepAnt = @CodDep) and (@@FETCH_STATUS = 0)
      begin
        while @QtdPdv > 0
          begin
            Set @QtdSld = 0
            Select top 1 @CodLot = lt.Cod_Lote, 
                         @CodDep = lt.Cod_Dep, 
                         @NumRua = lt.Num_Rua, 
                         @NumCol = lt.Num_Col, 
                         @NumNiv = lt.Num_Niv, 
                         @NumApt = lt.Num_Apt,
                         @QtdEmbFec = lt.Qtd_EmbFec,
                         @QtdSld = lt.Qtd_Saldo
            From #AUX_PRLTL lt
            Where lt.Cod_Dep = @CodDep
            And lt.Cod_Produto = @CodPrd
            And ((IsNull(lt.Dat_Vencim,0) = 0) or (IsNull(lt.Dat_Vencim,0) >= IsNull(@DatVct,0)))
            And lt.Qtd_Saldo > 0
            And lt.Qtd_Saldo >= Qtd_EmbFec
--            Order by lt.Dat_Vencim, Dat_Entrada
            Order by lt.Flg_PrePck desc, lt.Dat_Vencim, lt.Num_Rua, lt.Num_Niv, lt.Num_Apt, lt.Num_Col, lt.Cod_Lote, lt.Dat_Entrada
        
            if @QtdSld > 0 
              begin
                -- calcular quantidade a movimentar
                Set @QtdMov = 0
                while (@QtdSld >= @QtdEmbFec) and (@QtdPdv > 0)
                  begin
                    Set @QtdMov = @QtdMov + @QtdEmbFec
                    Set @QtdSld = @QtdSld - @QtdEmbFec
                    Set @QtdPdv = @QtdPdv - @QtdEmbFec
                  end
              
                if @QtdMov > 0
                  begin
                    -- inclui registro ABAIT
                    if not Exists(Select Cod_Produt 
                                  From ABAIT
                                  Where Cod_Estabe = @PCodEstabe
                                  And Cod_Abaste = @CodAba         
                                  And Cod_Produt = @CodPrd And Cod_Lote = @CodLot  
                                  And Cod_Dep = @CodDep
                                  And Num_Rua = @NumRua And Num_Col = @NumCol
                                  And Num_Niv = @NumNiv And Num_Apt = @NumApt)
                      Insert Into ABAIT (Cod_Estabe, Cod_Abaste, Cod_Produt, Cod_Lote, 
                                         Cod_Dep, Num_Rua, Num_Col, Num_Niv, Num_Apt, Qtd_Mov, Flg_Proces)
                                 Values (@PCodEstabe, @CodAba, @CodPrd, @CodLot,
                                         @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, 0, 0)
                      
                    Update ABAIT
                      Set Qtd_Mov = Qtd_Mov + @QtdMov
                    Where Cod_Estabe = @PCodEstabe
                    And Cod_Abaste = @CodAba         
                    And Cod_Produt = @CodPrd
                    And Cod_Lote = @CodLot  
                    And Cod_Dep = @CodDep
                    And Num_Rua = @NumRua 
                    And Num_Col = @NumCol
                    And Num_Niv = @NumNiv
                    And Num_Apt = @NumApt
                    
                    -- dar baixa em #AUX_PRLTL      
                    Update #AUX_PRLTL
                      Set Qtd_Saldo = Qtd_Saldo - @QtdMov
                    Where Cod_Produto = @CodPrd
                    And Cod_Lote = @CodLot  
                    And Cod_Dep = @CodDep
                    And Num_Rua = @NumRua 
                    And Num_Col = @NumCol
                    And Num_Niv = @NumNiv
                    And Num_Apt = @NumApt
                  end
                else
                  begin
                    Set @QtdPdv = 0  
                    RAISERROR('Erro na geração de abastecimento.',16,1)
                    if @@trancount > 0
                      Rollback Transaction
                    Return
                  end          
                  
              end  -- if @QtdSld > 0 
            else
              Set @QtdPdv = 0  
              
          end  -- While @QtdPdv > 0
          
        Fetch Next From PDVIT_Cr Into @CodDep, @CodPrd, @DatVct, @QtdPdv
      end
  end
  
Close PDVIT_Cr
Deallocate PDVIT_Cr

IF OBJECT_ID('tempdb..#ARQ_ABAST') IS NOT NULL
  DROP TABLE #ARQ_ABAST

IF OBJECT_ID('tempdb..#AUX_PRLTL') IS NOT NULL
  DROP TABLE #AUX_PRLTL

if @@trancount > 0
  COMMIT TRANSACTION
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CalculaComisNFS]
@PCodEstabe int,        -- cod. estabelecimento
@PSerNot varchar(3),    -- serie da nota fiscal
@PNumNot int            -- num.da nota fiscal

AS

SET NOCOUNT ON 

-- notas de venda, fechada, e fechamento de comissao em aberto
if ((Select Tip_Saida From NFSCB Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot) = 'V') and
   ((Select Status From NFSCB Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot) = 'F') and
   ((Select ISNULL(Dat_FecCom,0) From NFSCB Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot) = 0)
  begin
    Begin Transaction

    -- variaveis de trabalho
    Declare @WCodTabComOpe int,
            @WCodTabComVdr int,
            @WCodPrm int, 
            @WCVlrTotNot numeric(18,4),
            @WVlrComVnd numeric(18,4),
            @WVlrComOpe numeric(18,4),
            @WVlrComSup numeric(18,4),
            @WVlrComGer numeric(18,4),
            @WVlrComSupOpe numeric(18,4),
            @WVlrComGerOpe numeric(18,4),
            @WVlrBasFre numeric(18,4),
            @WVlrLiqNot numeric(18,4),
            @WFlgNotRecSbt bit,
            @WPerRetBon numeric(18,4),
            @WTipSai varchar(1)

    -- campos para cabecalho da nota
    Declare @cb_CodCli int,
            @cb_CodPed int,
            @cb_DatEmi smalldatetime,
            @cb_PerDscCom numeric(18,4),
            @cb_PerDscFin numeric(18,4),
            @cb_QtdPrzMed numeric(18,4),
            @cb_PerComOpe numeric(18,4),
            @cb_PerComVnd numeric(18,4),
            @cb_PerComSup numeric(18,4),
            @cb_PerComGer numeric(18,4),
            @cb_PerComSupOpe numeric(18,4),
            @cb_PerComGerOpe numeric(18,4),
            @cb_CodOpe int,
            @cb_CodVdr int,
            @cb_CodSup int,
            @cb_CodGer int,
            @cb_CodSupOpe int,
            @cb_CodGerOpe int,
            @cb_TipVct varchar(1),
            @cb_TipRetImp varchar(1),
            @cb_VlrDscTri numeric(18,4),
            @cb_VlrSubTri numeric(18,4),
            @cb_VlrRecSbt numeric(18,4),
            @cb_VlrTotNot numeric(18,4),
            @cb_CodTra int,
            @cb_CodUF varchar(2),
            @sf_SerNot varchar(3),
            @sf_NumNot int,
            @cr_VlrDoc numeric(18,4)
                 
    -- campos para transportadora
    Declare @tr_Pessoa varchar(1),
            @tr_PerFrete numeric(18,4),
            @tr_VlrMin numeric(18,4),
            @tr_FlgCalFreVerMer bit

    -- campos para atualizar em NFSCB
    Declare @PFlgComNor bit,
            @PVlrComVnd numeric(18,4),
            @PVlrComOpe numeric(18,4),
            @PVlrComSup numeric(18,4),
            @PVlrComGer numeric(18,4),
            @PVlrComSupOpe numeric(18,4),
            @PVlrComGerOpe numeric(18,4),
            @PVlrComTra numeric(18,4)

    -- Campos para itens da nota
    Declare @it_CodPrd int,
            @it_CodLot varchar(20),
            @it_NumSeqIte int, 
            @it_TipSai varchar(1),
            @it_CodCfo int,
            @it_PerDsc numeric(18,4),
            @it_PerDesconto numeric (18,8),
            @it_CodPrm int, 
            @it_FlgPolPrm int, 
            @it_FlgDscIte bit,
            @it_FlgBlqInfPar bit,
            @it_PrcUni numeric (18,8),
            @it_PrcTab numeric (18,4),
            @it_VlrBasCom numeric(18,4),
            @it_IdPolCom int,
            @it_PerVrbPar numeric (18,4),
            @it_PerVrbBon numeric (18,4),
            @it_PerLucBru numeric (18,4)

    -- variaveis a atualizar em NFSIT
    Declare @P_FlgComNor bit,
            @P_PerComVnd numeric(18,4),
            @P_VlrComVnd numeric(18,4),
            @P_PerComOpe numeric(18,4),
            @P_VlrComOpe numeric(18,4),
            @P_PerComSup numeric(18,4),
            @P_VlrComSup numeric(18,4),
            @P_PerComGer numeric(18,4),
            @P_VlrComGer numeric(18,4),
            @P_PerComSupOpe numeric(18,4),
            @P_VlrComSupOpe numeric(18,4),
            @P_PerComGerOpe numeric(18,4),
            @P_VlrComGerOpe numeric(18,4),
            @P_PerComTra numeric(18,4),
            @P_VlrComTra numeric(18,4)

    -- normaliza campos NFSCB
    Update cb 
       Set cb.Cod_Supervisor = ve.Cod_Supervisor 
      From NFSCB cb Inner Join VENDE ve on cb.Cod_Vendedor = ve.Codigo
     Where cb.Cod_Estabe = @PCodEstabe 
       and cb.Ser_Nota = @PSerNot and cb.Num_Nota = @PNumNot       
       And ISNULL(cb.Cod_Supervisor,0) = 0
      
    Update cb 
       Set cb.Cod_Gerencia = su.Cod_Gerencia
      From NFSCB cb Inner Join VENDE ve on cb.Cod_Vendedor = ve.Codigo
                    Inner Join SUPER su on ve.Cod_Supervisor = su.Codigo
     Where cb.Cod_Estabe = @PCodEstabe 
       and cb.Ser_Nota = @PSerNot and cb.Num_Nota = @PNumNot       
       And ISNULL(cb.Cod_Gerencia,0) = 0

    Update cb 
       Set cb.Cod_SupOpe = ve.Cod_Supervisor 
      From NFSCB cb Inner Join VENDE ve on cb.Cod_VendTlmkt = ve.Codigo
     Where cb.Cod_Estabe = @PCodEstabe 
       and cb.Ser_Nota = @PSerNot and cb.Num_Nota = @PNumNot       
       And ISNULL(cb.Cod_SupOpe,0) = 0
      
    Update cb 
       Set cb.Cod_GerOpe = su.Cod_Gerencia
      From NFSCB cb Inner Join VENDE ve on cb.Cod_VendTlmkt = ve.Codigo
                    Inner Join SUPER su on ve.Cod_Supervisor = su.Codigo
     Where cb.Cod_Estabe = @PCodEstabe 
       and cb.Ser_Nota = @PSerNot and cb.Num_Nota = @PNumNot       
       And ISNULL(cb.Cod_GerOpe,0) = 0

    -- coloca campos de NFSCB na memoria
    Select @cb_CodCli = Cod_Cliente, 
           @cb_CodVdr = Cod_Vendedor, 
           @cb_CodOpe = Cod_VendTlmkt, 
           @cb_CodSup = Cod_Supervisor, 
           @cb_CodGer = Cod_Gerencia, 
           @cb_CodSupOpe = Cod_SupOpe, 
           @cb_CodGerOpe = Cod_GerOpe, 
           @cb_CodPed = Cod_Pedido,
           @cb_DatEmi = Dat_Emissao,
           @cb_PerDscCom = IsNull(Per_DescontoCom,0), 
           @cb_PerDscFin = IsNull(Per_DescontoFin,0), 
           @cb_TipVct = Tip_Vencimento, 
           @cb_QtdPrzMed = Qtd_PrzMed, 
           @cb_PerComOpe = IsNull(Per_ComOpe,0),
           @cb_PerComVnd = IsNull(Per_ComVnd,0),
           @cb_PerComSup = IsNull(Per_ComSup,0),
           @cb_PerComGer = IsNull(Per_ComGer,0),
           @cb_PerComSupOpe = IsNull(Per_ComSupOpe,0),
           @cb_PerComGerOpe = IsNull(Per_ComGerOpe,0),
           @cb_TipRetImp = Tip_RetImp, 
           @cb_CodTra = Cod_Transportadora,
		   @cb_CodUF = IsNull(Estado,''),
           @sf_SerNot = IsNull(Ser_NotSubFat,''),
           @sf_NumNot = Isnull(Num_NotSubFat,0)
      From NFSCB
     Where Cod_Estabe = @PCodEstabe 
       and Ser_Nota = @PSerNot and Num_Nota = @PNumNot       

    -- coloca campos de NFSCB/NSOCB na memoria especificos p/ calculo da comissao
    Set @WFlgNotRecSbt = 0   -- indica se a nf for recalculada por inclusao do sbt no preco
    if Exists(Select 1 From  NSOCB Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot)
      begin
        Set @WFlgNotRecSbt = 1
        Select @cb_VlrDscTri = IsNull(Vlr_DscTri,0), 
               @cb_VlrSubTri = IsNull(Vlr_SubsTrib,0)+IsNull(Vlr_SbtRes,0), 
               @cb_VlrRecSbt = IsNull(Vlr_RecSbt,0),
               @cb_VlrTotNot = IsNull(Vlr_TotalNota,0),
               @WVlrLiqNot   = IsNull(Vlr_LiqItens,0) - IsNull(Vlr_DescontoCom,0) - IsNull(Vlr_DscBon,0) - IsNull(Vlr_RepIcms,0) - IsNull(Vlr_DscTri,0)
          From NSOCB
         Where Cod_Estabe = @PCodEstabe 
           and Ser_Nota = @PSerNot and Num_Nota = @PNumNot       
      end
    else
      begin
        Set @WFlgNotRecSbt = 0
        Select @cb_VlrDscTri = IsNull(Vlr_DscTri,0), 
               @cb_VlrSubTri = IsNull(Vlr_SubsTrib,0)+IsNull(Vlr_SbtRes,0), 
               @cb_VlrRecSbt = IsNull(Vlr_RecSbt,0),
               @cb_VlrTotNot = IsNull(Vlr_TotalNota,0),
               @WVlrLiqNot   = dbo.FN_ValLiqNFS(Cod_Estabe,Ser_Nota,Num_Nota)
          From NFSCB
         Where Cod_Estabe = @PCodEstabe 
           and Ser_Nota = @PSerNot and Num_Nota = @PNumNot       
      end

    -- coloca campos da transportadora na memoria
    Select @tr_Pessoa = tr.Pessoa,
           @tr_PerFrete = Case 
                            When tx.Cod_Transp is null then IsNull(tr.Per_Frete,0) 
                            Else IsNull(tx.Per_Frete,0) 
                          End,
           @tr_VlrMin = Case 
                            When tx.Cod_Transp is null then IsNull(tr.Vlr_Minimo,0) 
                            Else IsNull(tx.Vlr_Minimo,0) 
                          End,
           @tr_FlgCalFreVerMer = Case 
                                   When tx.Cod_Transp is null then IsNull(tr.Flg_CalFreVlrMer,0) 
                                   Else IsNull(tx.Flg_CalFreVlrMer,0) 
                                 End
      From TRANS tr
           Left Join TRXUF tx on tr.Codigo = tx.Cod_Transp and tx.Cod_UF COLLATE DATABASE_DEFAULT = @cb_CodUF COLLATE DATABASE_DEFAULT 
     Where tr.Codigo = @cb_CodTra

    -- inicializa acumuladores  p/  cabecalho
    Set @PVlrComVnd = 0
    Set @PVlrComOpe = 0
    Set @PVlrComSup = 0
    Set @PVlrComGer = 0
    Set @PVlrComSupOpe = 0
    Set @PVlrComGerOpe = 0
    Set @PVlrComTra = 0   -- ???? recalcula para nf com sbt incluida no preco ????
    Set @PFlgComNor = 1

    -- pega tabela de comissao do vendedor e operador
    Set @WCodTabComOpe = (Select Cod_TabCom From VEXES Where Cod_Estabe = @PCodEstabe And Cod_Vended = @cb_CodOpe)
    Set @WCodTabComVdr = (Select Cod_TabCom From VEXES Where Cod_Estabe = @PCodEstabe And Cod_Vended = @cb_CodVdr)

    -- comissao de supervisor/gerencia do vendedor    
    Set @cb_PerComSup = (Select IsNull(Per_ComNor,0) From SUPER Where Codigo = @cb_CodSup)
    Set @cb_PerComGer = (Select IsNull(Per_ComNor,0) From GEREN Where Codigo = @cb_CodGer)

    -- comissao de supervisor/gerencia do operador
    Set @cb_PerComSupOpe = (Select IsNull(Per_ComNor,0) From SUPER Where Codigo = @cb_CodSupOpe)
    Set @cb_PerComGerOpe = (Select IsNull(Per_ComNor,0) From GEREN Where Codigo = @cb_CodGerOpe)

    -- calcula comissao dos itens
    Declare NFSIT_Cr Cursor Local Fast_Forward For 
      Select Cod_Produto, Cod_Lote, Num_SeqIte, ISNULL(Tip_Sai,''), ISNULL(Cod_Cfo,0),
			 IsNull(Vlr_TotItem,0)-IsNull(Vlr_RepIcms,0)-IsNull(Vlr_DescRateado,0)-IsNull(Vlr_DscBonRat,0)-IsNull(Vlr_DscTri,0), IsNull(Prc_Unitario,0), 
             IsNull(Prc_Tabela,0), IsNull(Flg_DscItePdv,0), IsNull(Flg_BlqInfPar,0), IsNull(Cod_Promocao,0), IsNull(Flg_PolPrm,0),
             IsNull(Per_Descon,0), IsNull(Per_Desconto,0), IsNull(Id_PolCom,0), IsNull(Per_VrbPar,0), IsNull(Per_VrbBon,0),
             IsNull(Per_LucBru,0)
        From NFSIT Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot
    Open NFSIT_Cr
    Fetch Next From NFSIT_Cr Into @it_CodPrd, @it_CodLot, @it_NumSeqIte, @it_TipSai, @it_CodCfo, @it_VlrBasCom, @it_PrcUni, 
                                  @it_PrcTab, @it_FlgDscIte, @it_FlgBlqInfPar, @it_CodPrm, @it_FlgPolPrm,
                                  @it_PerDsc, @it_PerDesconto, @it_IdPolCom, @it_PerVrbPar, @it_PerVrbBon,
                                  @it_PerLucBru

    While @@FETCH_STATUS = 0
      begin
        -- verifica se a nf foi recalculada (sbt incluida no preco)
        if @WFlgNotRecSbt = 1
          begin
            Select @it_VlrBasCom = IsNull(Vlr_LiqItem,0)-IsNull(Vlr_SubsTrib,0)-IsNull(Vlr_RecSbt,0),   -- -Vlr_SbtRes  -Vlr_Ipi -Vlr_DespRateada +VlrBonRat
                   @it_PrcUni = IsNull(Prc_Unitario,0), 
                   @it_PerDesconto = IsNull(Per_Desconto,0)              
              From NSOIT
             Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot       
               And Cod_Produto = @it_CodPrd and Cod_Lote = @it_CodLot and Num_SeqIte = @it_NumSeqIte
          end

        Set @WPerRetBon = @it_PerVrbPar + @it_PerVrbBon 
        if (@it_TipSai = 'B') or (@it_CodCfo = 5910) or (@it_CodCfo = 6910)  
          Set @WTipSai = 'B'
        else  
          Set @WTipSai = ''

-- Set Vlr_LiqItem = Vlr_TotItem - Vlr_RepIcms - Vlr_DescRateado  - Vlr_DscTri 
--                   - Vlr_DscBonRat + Vlr_SubsTrib + Vlr_SbtRes + Vlr_RecSbt + Vlr_Ipi + Vlr_DespRateada
        
        Set @WCodPrm = IsNull(@it_CodPrm,0) + IsNull(@it_FlgPolPrm,0)
        EXEC PR_CalcComisItemSaida @PCodEstabe, @cb_CodPed, @it_CodPrd, @WTipSai, @cb_CodCli, @cb_DatEmi, @it_VlrBasCom,
                                   @it_PrcUni, @it_PrcTab, @it_FlgDscIte, @it_FlgBlqInfPar, @WCodPrm, @it_PerDsc, @it_PerDesconto, 
                                   @cb_PerDscCom, @cb_PerDscFin, @cb_TipVct, @cb_QtdPrzMed, @cb_PerComVnd, @WCodTabComVdr, @cb_PerComOpe, @WCodTabComOpe, 
                                   @cb_PerComSup, @cb_PerComGer, @cb_PerComSupOpe, @cb_PerComGerOpe, @it_IdPolCom, @WPerRetBon, @it_PerLucBru, @P_FlgComNor output, 
                                   @P_PerComOpe output, @P_PerComVnd output, @P_PerComSup output, @P_PerComGer output, @P_PerComSupOpe output, @P_PerComGerOpe output, 
                                   @P_VlrComOpe output, @P_VlrComVnd output, @P_VlrComSup output, @P_VlrComGer output, @P_VlrComSupOpe output, @P_VlrComGerOpe output

        -- calcula comissao de entrega  -- ???? recalcula para nf com sbt incluida no preco ????
        Set @P_PerComTra = 0
        Set @P_VlrComTra = 0
        if @tr_Pessoa = 'F'
          begin
            Select @P_PerComTra = Isnull(Per_ComEnt,0) From PRXES Where Cod_Estabe = @PCodEstabe and Cod_Produt = @it_CodPrd
            Set @P_VlrComTra = @it_VlrBasCom * @P_PerComTra/100
          end

        -- atualiza item da nota
        Update NFSIT
           Set Flg_ComisNormal = @P_FlgComNor,
               Per_Comissao = @P_PerComVnd,
               Per_ComTlmkt = @P_PerComOpe,
               Per_ComSup = @P_PerComSup,
               Per_ComGer = @P_PerComGer,
               Per_ComSupOpe = @P_PerComSupOpe,
               Per_ComGerOpe = @P_PerComGerOpe,
               Vlr_Comissao = @P_VlrComVnd,
               Vlr_ComTlmkt = @P_VlrComOpe,
               Vlr_ComSup = @P_VlrComSup,
               Vlr_ComGer = @P_VlrComGer,
               Vlr_ComSupOpe = @P_VlrComSupOpe,
               Vlr_ComGerOpe = @P_VlrComGerOpe,
               Per_ComTra = @P_PerComTra,
               Val_ComTra = @P_VlrComTra
         Where Cod_Estabe = @PCodEstabe 
           and Ser_Nota = @PSerNot and Num_Nota = @PNumNot
           and Cod_Produto = @it_CodPrd and Cod_Lote = @it_CodLot and Num_SeqIte = @it_NumSeqIte

        -- atualiza tip_sai do item
        Update NFSIT
           Set Tip_Sai = @WTipSai
         Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota = @PNumNot
           and Cod_Produto = @it_CodPrd and Cod_Lote = @it_CodLot and Num_SeqIte = @it_NumSeqIte
           And IsNull(Tip_Sai,'') <> @WTipSai   

        -- acumula valores p/  cabecalho
        Set @PVlrComVnd = @PVlrComVnd + @P_VlrComVnd
        Set @PVlrComOpe = @PVlrComOpe + @P_VlrComOpe
        Set @PVlrComSup = @PVlrComSup + @P_VlrComSup
        Set @PVlrComGer = @PVlrComGer + @P_VlrComGer
        Set @PVlrComSupOpe = @PVlrComSupOpe + @P_VlrComSupOpe
        Set @PVlrComGerOpe = @PVlrComGerOpe + @P_VlrComGerOpe
        Set @PVlrComTra = @PVlrComTra + @P_VlrComTra
        if @P_FlgComNor = 0
          Set @PFlgComNor = 0

        Fetch Next From NFSIT_Cr Into @it_CodPrd, @it_CodLot, @it_NumSeqIte, @it_TipSai, @it_CodCfo, @it_VlrBasCom, @it_PrcUni, 
                                      @it_PrcTab, @it_FlgDscIte, @it_FlgBlqInfPar, @it_CodPrm, @it_FlgPolPrm,
                                      @it_PerDsc, @it_PerDesconto, @it_IdPolCom, @it_PerVrbPar, @it_PerVrbBon,
                                      @it_PerLucBru									   
      end
    Close NFSIT_Cr 
    Deallocate NFSIT_Cr

    -- calcula frete p/ pessoa juridica (somente se nao foi recalculada por sbt no preco)
    if @tr_Pessoa <> 'F'
      begin
        if @tr_FlgCalFreVerMer = 1
          Set @WVlrBasFre = @WVlrLiqNot
        else
          Set @WVlrBasFre = @cb_VlrTotNot

        Set @PVlrComTra = Round(@WVlrBasFre*@tr_PerFrete/100,2)
        if Round(@PVlrComTra*100,2) < Round(@tr_VlrMin*100,2)
          Set @PVlrComTra = @tr_VlrMin
      end

    -- Atualiza acumuladores em NFSCB
    Update NFSCB
       Set Vlr_Comissao = Round(@PVlrComVnd,2),
           Vlr_ComTlmkt = Round(@PVlrComOpe,2),
           Vlr_ComSup = Round(@PVlrComSup,2),          
           Vlr_ComGer = Round(@PVlrComGer,2),          
           Vlr_ComSupOpe = Round(@PVlrComSupOpe,2),          
           Vlr_ComGerOpe = Round(@PVlrComGerOpe,2),          
           Val_ComTra = Case
                          When @tr_Pessoa = 'F' Then Round(@PVlrComTra,2)
                          Else Val_ComTra 
                        End,
           Flg_ComisNormal = @PFlgComNor
     Where Cod_Estabe = @PCodEstabe 
       and Ser_Nota = @PSerNot and Num_Nota = @PNumNot

    -- atualiza contas a receber  
    -- campo calculado: valor real da nota
    if @cb_TipRetImp = 'R'
      Set @WCVlrTotNot = @cb_VlrTotNot + @cb_VlrSubTri - @cb_VlrDscTri + @cb_VlrRecSbt
    else
      Set @WCVlrTotNot = @cb_VlrTotNot

    Set @WVlrComVnd = Round(@PVlrComVnd,2)
    Set @WVlrComOpe = Round(@PVlrComOpe,2)
    Set @WVlrComSup = Round(@PVlrComSup,2)
    Set @WVlrComGer = Round(@PVlrComGer,2)
    Set @WVlrComSupOpe = Round(@PVlrComSupOpe,2)
    Set @WVlrComGerOpe = Round(@PVlrComGerOpe,2)
    
    -- qg somente para garantir divisao por 0
    if @WCVlrTotNot = 0
      begin
        Set @WCVlrTotNot = 1
        Set @WVlrComVnd = 0
        Set @WVlrComOpe = 0
        Set @WVlrComSup = 0
        Set @WVlrComGer = 0
        Set @WVlrComSupOpe = 0
        Set @WVlrComGerOpe = 0
      end

    -- atualiza titulos relacionados
    Update CTREC
       Set Cod_Vendedor = @cb_CodVdr,
           Cod_VendTlmkt = @cb_CodOpe,
           Cod_Supervisor = @cb_CodSup,
           Cod_Gerencia = @cb_CodGer,
           Cod_SupOpe = @cb_CodSupOpe,
           Cod_GerOpe = @cb_CodGerOpe,
           Vlr_Comissao = Vlr_Documento * @WVlrComVnd / @WCVlrTotNot,
           Vlr_ComTlmkt = Vlr_Documento * @WVlrComOpe / @WCVlrTotNot,
           Vlr_ComSup = Vlr_Documento * @WVlrComSup / @WCVlrTotNot,
           Vlr_ComGer = Vlr_Documento * @WVlrComGer / @WCVlrTotNot,
           Vlr_ComSupOpe = Vlr_Documento * @WVlrComSupOpe / @WCVlrTotNot,
           Vlr_ComGerOpe = Vlr_Documento * @WVlrComGerOpe / @WCVlrTotNot
     Where Cod_Estabe = @PCodEstabe 
       And Ser_NfOrigem = @PSerNot and Num_NfOrigem = @PNumNot

    -- atualiza titulos do sfaturamento
    if (@PSerNot = 'ORC') and (@sf_NumNot > 0)
      begin
        if @sf_SerNot = ''
          Set @sf_SerNot = (Select ModeloNotaFiscal From PARAM Where Cod_Estabe = @PCodEstabe)
        if Exists(Select Num_Nota From NFSCB Where Cod_Estabe = @PCodEstabe and Ser_Nota = @sf_SerNot and Num_Nota = @sf_NumNot)
          begin
            -- atualza NFSCB sfat
            Update NFSCB
               Set Cod_Vendedor = @cb_CodVdr,
                   Cod_VendTlmkt = @cb_CodOpe,
                   Cod_Supervisor = @cb_CodSup,
                   Cod_Gerencia = @cb_CodGer,
                   Cod_SupOpe = @cb_CodSupOpe,
                   Cod_GerOpe = @cb_CodGerOpe
             Where Cod_Estabe = @PCodEstabe 
               and Ser_Nota = @sf_SerNot and Num_Nota = @sf_NumNot       
            -- atualiza CTREC sfat
            Update CTREC
               Set Cod_Vendedor = @cb_CodVdr,
                   Cod_VendTlmkt = @cb_CodOpe,
                   Cod_Supervisor = @cb_CodSup,
                   Cod_Gerencia = @cb_CodGer,
                   Cod_SupOpe = @cb_CodSupOpe,
                   Cod_GerOpe = @cb_CodGerOpe,
                   Vlr_Comissao = Vlr_Documento * @WVlrComVnd / @WCVlrTotNot,
                   Vlr_ComTlmkt = Vlr_Documento * @WVlrComOpe / @WCVlrTotNot,
                   Vlr_ComSup = Vlr_Documento * @WVlrComSup / @WCVlrTotNot,
                   Vlr_ComGer = Vlr_Documento * @WVlrComGer / @WCVlrTotNot,
                   Vlr_ComSupOpe = Vlr_Documento * @WVlrComSupOpe / @WCVlrTotNot,
                   Vlr_ComGerOpe = Vlr_Documento * @WVlrComGerOpe / @WCVlrTotNot
             Where Cod_Estabe = @PCodEstabe 
               And Ser_NfOrigem = @sf_SerNot and Num_NfOrigem = @sf_NumNot
          end    -- Exists
      end  
  
    Commit Transaction
  end
GO


SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_FechaPDC]
@CodEstabe int,
@NumPed Int,
@NumPrt Int

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime

Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)

-- testa se o pedido ja esta fechado
Declare @Sta varchar(1)
Set @Sta = (Select Status From dbo.PDCCB Where Cod_Estabe = @CodEstabe And Numero = @NumPed)
if @Sta = 'F'
  RAISERROR('Rotina de Fechamento já executada para o pedido informado',16,1)
else
  begin
    Begin Transaction

      -- atualiza registros em NEIPC (ites de entrada relacionados ao pedido de compra)
      if not Exists (Select 1 From dbo.NEIPC Where Cod_Estabe = @CodEstabe And Num_PedCom = @NumPed)
        begin
          Exec dbo.PR_AtualizaNEIPC @CodEstabe, @NumPed
          if @@error <> 0
            begin
              if @@trancount > 0
                Rollback Transaction
              Return
            end    
        end

      -- seta status do cabecalho do pedido como "Fechado"
      Update dbo.PDCCB
         Set Status = 'F'
       Where Cod_Estabe = @CodEstabe 
         And Numero = @NumPed

    -- coloca qtde faturada em PDCIT
/*    
      Update itp
        Set itp.Qtd_Fatura = Isnull(itp.Qtd_Fatura,0) + 
                             Isnull((Select sum(i.Qtd_Pedido+i.Qtd_Bonificacao)
                                       From NFEIT i Inner join 
                                            NFECB c on c.Cod_Estabe = i.Cod_Estabe and c.Protocolo = i.Protocolo Inner Join 
                                            PDCCB p on c.Cod_Estabe = i.Cod_Estabe and c.Cod_Pedido = p.Numero
                                       Where p.Cod_Estabe = @CodEstabe
                                       And p.Numero = @NumPed
                                       and i.Cod_Produto = itp.Cod_Produto
                                       and c.Status = 'F'
                                       group by i.Cod_Produto),0)
      From PDCIT itp 
           Inner Join NFECB cbn on cbn.Cod_Estabe = itp.Cod_Estabe and cbn.Cod_Pedido = itp.Numero
      Where cbn.Status = 'F' 
      and itp.Cod_Estabe = @CodEstabe
      and itp.Numero = @NumPed
*/

    if @NumPrt = 0
      begin
        Update ic
           Set ic.Qtd_Fatura = IsNull(n.QtdComRel,0)
          From dbo.PDCIT ic 
               Inner Join (Select i.Cod_Produto, QtdComRel = sum(i.Qtd_PedCom) 
                             From dbo.NEIPC i  
                                  Inner Join dbo.NFECB c on i.Cod_Estabe = c.Cod_Estabe And i.Protocolo = c.Protocolo                   
                            Where c.Cod_Estabe = @CodEstabe
                              And ((c.Status = 'F') or (c.Status = 'C'))
                              And i.Num_PedCom = @NumPed
                            Group by i.Cod_Produto) n on ic.Cod_Produto = n.Cod_Produto
         Where ic.Cod_Estabe = @CodEstabe
           and ic.Numero = @NumPed
      end
    else
      begin
        Update ic
           Set ic.Qtd_Fatura = IsNull(ic.Qtd_Fatura,0) + IsNull(n.QtdComRel,0)
          From dbo.PDCIT ic 
               Inner Join (Select i.Cod_Produto, QtdComRel = sum(i.Qtd_PedCom) 
                             From dbo.NEIPC i  
                                  Inner Join dbo.NFECB c on i.Cod_Estabe = c.Cod_Estabe And i.Protocolo = c.Protocolo                   
                            Where c.Cod_Estabe = @CodEstabe
                              And c.Protocolo = @NumPrt
                              And ((c.Status = 'F') or (c.Status = 'C'))
                              And i.Num_PedCom = @NumPed
                            Group by i.Cod_Produto) n on ic.Cod_Produto = n.Cod_Produto
         Where ic.Cod_Estabe = @CodEstabe
           and ic.Numero = @NumPed
      end  

    -- coloca qtde em transito no produto
    Update pr
       Set pr.Qtd_Transi = Isnull(pr.Qtd_Transi,0) + Isnull(it.Qtd_Pendente,0) 
      From dbo.PDCIT it 
           Inner Join dbo.PRXES pr on pr.Cod_Estabe = it.Cod_Estabe and pr.Cod_Produt = it.Cod_Produto
     Where pr.Cod_Estabe = @CodEstabe
       And it.Numero = @NumPed

    -- verifica se ficou alguma pendencia
    Update cb
       Set cb.Status = 'P'
      From dbo.PDCIT it 
           Inner Join dbo.PDCCB cb on cb.Cod_Estabe = it.Cod_Estabe and cb.Numero = it.Numero
     Where cb.Cod_Estabe = @CodEstabe
       And cb.Numero = @NumPed 
       and ((Isnull(it.Qtd_Pedido,0) + Isnull(it.Qtd_Bonificacao,0)) - (Isnull(it.Qtd_Falta,0) + Isnull(it.Qtd_Fatura,0))) > 0

    -- Força calculo correto dos itens do pedido de compra DMD-8266
    -- Exec dbo.PR_ProIni_EliminaPendenciasPdc @CodEstabe,@NumPed
  
    -- GERA PREVISAO DE PAGAMENTOS 
    Exec dbo.PR_GeraPrevisaoPAGCT @CodEstabe, @NumPed
    if @@error <> 0
      begin
        if @@trancount > 0
          Rollback Transaction
        Return
      end

    if @@trancount > 0
      Commit Transaction
  end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CN_Atualiza_Historico] 
@CodEstabe int, 
@MesesHistorico int = 0


AS

SET NOCOUNT ON

Declare @DataAtual varchar(6),
    @CodProdut int,
    @QtdFatura int,
    @QtdDispon int,
    @QtdTransAut int,
    @QtdTransMan int,
    @QtdFaltas int,
    @QtdEmbala int,
    @WVMedDia  int,
    @AnoIni    int,
    @AnoFim    int,
    @MesIni    int,
    @MesFim    int,
    @PrcVenda  numeric(18,2),
    @PrcFabri  numeric(18,2),
    @PrcCompra numeric(18,2), 
    @PrcCusto  numeric(18,2),
    @CodEstabePed int,
    @AbcVal    varchar(1),
    @AbcQtd    varchar(1),
    @AbcAce    varchar(1),
    @WorkDate datetime,
    @PerNivServico numeric(18,2),
    @QtdDsvPad numeric(18,4),
    @NumMesesAtualiza int

If not Exists( Select Top 1 1 From ESTAB
               Where Cod_Estabe = @CodEstabe And IsNull(Flg_Inativ,0) = 0 )
  begin
    RAISERROR (15600,-1,-1, 'ESTABELECIMENTO INATIVO OU NÃO CADASTRADO')
    Return
  end

-- Antes poderia gerar o historico de um estabelecimento para outro 
Set dateformat ymd
Set @CodEstabePed = @CodEstabe
Set @WorkDate = GetDate()

While (@MesesHistorico > -1)
  begin
  Set @WorkDate = Cast( DateAdd(MONTH,( @MesesHistorico * (-1) ),GetDate()) as Date )

    Declare cr_prod Cursor local Fast_Forward for
  Select DataAtual = Substring(CONVERT(VARCHAR(10), @WorkDate, 103),7,4)+Substring(CONVERT(VARCHAR(10), @WorkDate, 103),4,2),
       CodProdut = pr.Codigo, 
           QtdDispon = dbo.FN_EstoqueDisponivelPrd(xe.Cod_Estabe,xe.Cod_Produt),
       QtdTransi = IsNull(xe.Qtd_Transi,0),
       QtdFaltas = IsNull(0,0),
           PrcCompra = Case 
                          When (IsNull(xe.Prc_UltEntDep,0) = 0) or 
                              ((IsNull(xe.Prc_UltEnt,0) > 0) and (xe.Dat_UltCompra >= xe.Dat_UltEntDep) and 
                               (IsNull(xe.Prc_UltEntDep,0) > 0)) Then xe.Prc_UltEnt 
                          Else xe.Prc_UltEntDep 
                        End,
       PrcVenda  = IsNull(xe.Prc_Venda,0),
       PrcFabri  = IsNull(xe.Prc_Fabric,0),
       PrcCusto  = IsNull(xe.Prc_CusMed,0),
       QtdEmbala = pr.Qtd_Embalagem,
           pr.Sta_AbcValFat,
       pr.Sta_AbcUniVen,
       pr.Sta_AbcAcesso,
       QtdTransiMan = IsNull(xe.Qtd_EstTraMan,0)
    From dbo.PRODU pr 
     Inner Join dbo.PRXES xe On (xe.Cod_Produt = pr.Codigo)
     Inner Join dbo.FABRI fb ON (pr.Cod_Fabricante = fb.Codigo)
  Where xe.Cod_Estabe = @CodEstabe
  and ((IsNull(xe.Qtd_Dispon,0) >= 0) or (IsNull(xe.Qtd_Reserv,0) >= 0) or (IsNull(xe.Qtd_Avaria,0) >= 0) or (IsNull(xe.Qtd_Solici,0) >= 0))
  Order By pr.Codigo
  
  Open cr_prod
  Fetch cr_prod into @DataAtual, @CodProdut, @QtdDispon, @QtdTransAut, @QtdFaltas, @PrcCompra, 
                     @PrcVenda, @PrcFabri, @PrcCusto, @QtdEmbala, @AbcVal, @AbcQtd, @AbcAce, @QtdTransMan

  while @@FETCH_STATUS = 0 
   begin

    Set @AnoFim = Convert( int, Substring(@DataAtual,1,4) )
    Set @AnoIni = @AnoFim
    Set @MesFim = Convert( int, Substring(@DataAtual,5,2) )
    Set @MesIni = @MesFim-3
    Set @WVMedDia = 0
    Set @QtdFatura = 0

    if @MesIni<=0 
     begin
       Set @MesIni = 12 + @MesIni
       Set @AnoIni = @AnoIni-1
     end

    -- Media mes e dividindo por 30
    Select @WVMedDia = Sum(IsNull(Qtd_UniVen,0)) From dbo.ACPRD
    Where Cod_Estabe = @CodEstabe 
    And Cod_Produto  = @CodProdut
    And  Ano_Movimento = @AnoFim
    And  Mes_Movimento = @MesFim
    
    if (IsNull(@WVMedDia,0) > 0)
      Select @WVMedDia = Case When @MesesHistorico = 0 Then
                           @WVMedDia / Day( GetDate() ) 
                 Else
                           @WVMedDia / 30
               End
    else
      Set @WVMedDia = 0
    
    Set @NumMesesAtualiza = 3
    if (@MesesHistorico = 7)
      begin
        Set @NumMesesAtualiza = 6       
      end

        -- Desvio padrão da data de referencia a três ou seis meses anteriores
        Set @QtdDsvPad = dbo.FN_CN_DesvioPadrao(@CodEstabe ,@CodProdut,@WorkDate, @NumMesesAtualiza)
    
    -- Faturamento do Mes atual
    Select @QtdFatura = IsNull(Qtd_UniVen,0) From dbo.ACPRD
    Where Cod_Estabe = @CodEstabe
    And Cod_Produto  = @CodProdut
    And  Ano_Movimento = @AnoFim
    And  Mes_Movimento = @MesFim

    If Exists(Select 1 From dbo.CN_HSPRD Where Cod_Estabe = @CodEstabePed And Cod_Produt = Convert(varchar(20),@CodProdut) And Ref_AnoMes = convert(int,@DataAtual) )
      Begin
      --Update
      Update dbo.CN_HSPRD
      Set Prc_UniCom  = @PrcCompra,
        Prc_UniVen  = @PrcVenda,
        Prc_UniFab  = @PrcFabri,
        Prc_UniCus  = @PrcCusto,
        Qtd_Dispon  = @QtdDispon,
        Qtd_Transi  = @QtdTransAut,
        Qtd_EstTraMan = @QtdTransMan,
        Qtd_EmbFec  = @QtdEmbala,
        Sta_AbcVal  = @AbcVal,
        Sta_AbcUni  = @AbcQtd,
        Sta_AbcAce  = @AbcAce,
        Qtd_MedVen  = @WVMedDia,
        Qtd_FatMes  = @QtdFatura,
        Qtd_DsvPad  = @QtdDsvPad,
        Dat_Atuali  = Convert(date, getdate(), 103) -- Data atualização sem hora
      Where Cod_Estabe= @CodEstabePed 
      And Cod_Produt =  @CodProdut
      And Ref_AnoMes =  Convert( int, @DataAtual )

      End
    Else
      Begin
      --Insert
      Insert Into dbo.CN_HSPRD
             (Ref_AnoMes
             ,Cod_Estabe
             ,Cod_Produt
             ,Prc_UniCom
             ,Prc_UniVen
             ,Prc_UniFab
             ,Prc_UniCus
             ,Qtd_FatMes
             ,Qtd_MedVen
             ,Qtd_Dispon
             ,Qtd_Transi
             ,Qtd_EstTraMan
             ,Qtd_EmbFec
             ,Qtd_Faltas
             ,Sta_AbcVal
             ,Sta_AbcUni
             ,Sta_AbcAce
             ,Qtd_DsvPad
             ,Dat_Atuali)
         VALUES
             (@DataAtual
             ,@CodEstabePed
             ,@CodProdut
             ,@PrcCompra
             ,@PrcVenda
             ,@PrcFabri
             ,@PrcCusto
             ,@QtdFatura
             ,@WVMedDia
             ,@QtdDispon
             ,@QtdTransAut
             ,@QtdTransMan
             ,@QtdEmbala
             ,@QtdFaltas
             ,@AbcVal
             ,@AbcQtd
             ,@AbcAce
             ,@QtdDsvPad
             ,Convert(date, getdate(), 103) ) -- Data atualização sem hora
      End

    Fetch cr_prod into @DataAtual, @CodProdut, @QtdDispon, @QtdTransAut, @QtdFaltas, @PrcCompra, 
                         @PrcVenda, @PrcFabri, @PrcCusto, @QtdEmbala, @AbcVal, @AbcQtd, @AbcAce, @QtdTransMan

   end

  Close cr_prod
    Deallocate cr_prod

  --Atualiza Faltas e nível de serviço
  Set @DataAtual = Substring(CONVERT(VARCHAR(10), @WorkDate, 103),7,4)+Substring(CONVERT(VARCHAR(10), @WorkDate, 103),4,2)
  
    Declare cr_fal Cursor local Fast_Forward for
  Select it.Cod_Produto, 
        Sum(it.Qtd_Solicitado-it.Qtd_Pedido) as Qtd_Fal,
              Case When SUM(IsNull(it.Qtd_Solicitado,0)) > 0 THEN 
                Convert(numeric(18,4),(SUM(IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)) * 100.00) / SUM(IsNull(it.Qtd_Solicitado,0))) 
              Else 0 
        End as Per_NivServico
  From  dbo.PDVCB cb 
  Inner Join dbo.PDVIT it On cb.Cod_Estabe = it.Cod_Estabe and cb.Numero = it.Cod_Pedido 
  Where cb.Cod_Estabe = @CodEstabe
  and it.Cod_Produto > 0 
  and ((cb.Status1 = 'P') or (cb.Status1 = 'D')) 
  and (cb.Tip_Pedido = 'P')
  and DateDiff(Month,cb.Dat_Pedido, @WorkDate ) = 0 -- Somente o mês de referencia
  Group By it.Cod_Produto

  Open cr_fal
  Fetch cr_fal Into @CodProdut, @QtdFaltas, @PerNivServico

  while @@FETCH_STATUS = 0 
   begin

    Update dbo.CN_HSPRD
    Set Qtd_Faltas = IsNull(@QtdFaltas,0),
        Per_NivSerPdv = isNull(@PerNivServico,0),
      Dat_Atuali = Convert(date, getdate(), 103)
    Where Cod_Estabe=@CodEstabePed 
    And Cod_Produt = @CodProdut
    And Ref_AnoMes = Convert( int ,@DataAtual)

    Fetch cr_fal Into @CodProdut, @QtdFaltas, @PerNivServico

   end

  Close cr_fal
  Deallocate cr_fal
  ---
  Set @MesesHistorico = @MesesHistorico - 1
  end

GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- @ParCompra = G Geral / C Por Classe / E(X) Classe Específica
-- Parametros do filtro e geração de sugestão
CREATE PROCEDURE [dbo].[PR_CN_GeraPedido]
          @IsnPedido int OUT, --Retorno Codigo do Pedido
          @PCodFabricante int = -1,
      @PCodFornecedor int = -1,
          @PLstProduto varchar(8000) = '0',
        @PListaEstab varchar(512) = '',
        @PFlgApenasEstoqueZero bit = 0,
        @PDiasRep int = 15, 
        @PDiasSupClasseA int = -1, 
        @PDiasSupClasseB int = -1,  
        @PDiasSupClasseC int = -1,
        @PFlgEstoqueSeguranca bit = 0,   -- utiliza estoque segurança
      @PFlgUsaEstTraMan bit = 0,       -- usa Transito Manual
        @PLstEstoque varchar(512) = '',
      @PTitulo varchar(255) = '',
      @PUsuario varchar(35) = '',
      @PTipoPreco int = -1,  -- 0-Prc_Fabrica, 1-Prc_Compra
      @PTipoCurvaABC int = 0, -- 0 = Produto / 1 = Fabricante
      @PPorCurva int = 0,
          @PIndexCurva int = 0,           
          @PUsaEstZero bit = 0,                     
          @PUsaCurvaAbcFabric bit = 0 
        
AS

Set NOCOUNT ON
Set Dateformat YMD


Declare @DataRef SmallDateTime,
        @DataAux SmallDateTime,
        @RefAnoMes int,
        @AnoMes0 int,
    @AnoMes1 int,
    @AnoMes2 int,
    @AnoMes3 int,
    @AnoMes4 int,
    @AnoMes5 int,
    @AnoMes6 int,   
    @Gera bit

-- Variaveis Itens
Declare @it_CodEstabe int,
        @it_CodProdut int,
        @it_StaAbcUniPrd varchar(1),
    @it_StaAbcValPrd varchar(1),
        @it_StaAbcUniFab varchar(1),
    @it_StaAbcValFab varchar(1),
        @it_PrcUniCom numeric(18,4),
        @it_PrcUniVen numeric(18,4),
        @it_PrcUniFab numeric(18,4),
        @it_PrcUniCus numeric(18,4),
        @it_PrcUniAna numeric(18,4),
        @it_QtdDispon int,
        @it_QtdTransi int,
        @it_QtdEmbFec int,
        @it_QtdFaltas int,
        @it_QtdEstTraMan int,
        @it_QtdDiaSupPrd int,
        
        @FatSeg numeric(18,4),
        @NivSrv numeric(18,4),
        @QtdDsvPad numeric(18,4),
        @QtdMedVen numeric(18,4),
        @QtdEstSeg int,
        @QtdEstMin int,
        @QtdEstMax int,
        @QtdRessup int,
        @QtdSugest int,
        @QtdSugDia int,
        @CodPedido int,
        @QtdPedido int,
        @DatPedido datetime,
        @PerDescon numeric(18,4),
    @PerRepasse numeric(18,4),
    @QtdFatMes int,
        @QtdFatMes0 int,
        @QtdFatMes1 int,
        @QtdFatMes2 int,
        @QtdFatMes3 int,
    @QtdFatMes4 int,
        @QtdFatMes5 int,
        @QtdFatMes6 int,    
        @DiasSup int,
    @TxParam nvarchar(max),
    @TxPcFor nvarchar(max),
    @TxCodEst int,
    @TxCodFor int,
    @TxIdPcFor int,
        @CalcVar1 numeric(18,4),
        @CalcVar2 numeric(18,4),
    @PerMinCxa numeric(18,4)

Declare @WStaAbcValFat varchar(1),
        @WStaAbcUniVen varchar(1),
    @WStrPrzCmp varchar(100),
        @WQtdDiaSupPrd int,
    @WCodEst int,
    @NumMesesAtualiza int

-- Validar dias de suprimento por classe
if @PDiasSupClasseA =-1
  Set @PDiasSupClasseA = 0

if @PDiasSupClasseC =-1
  Set @PDiasSupClasseC = @PDiasSupClasseA

if @PDiasSupClasseB = -1
  Set @PDiasSupClasseB = @PDiasSupClasseA

-- Data de Referência
Set @DataRef = GetDate()

-- Validar histórico atualizado
Set @NumMesesAtualiza = 4 -- pega-se as vendas do mês atual e dos 3 últimos meses

If @PListaEstab = ''
  begin
   Select @PListaEstab = @PListaEstab + Convert(varchar(3), Cod_Estabe)+' ' From ESTAB
  end


If (Select Count(1) From FN_ListaCodigos( @PLstEstoque )) > 0 and
   (Select Count(1) From FN_ListaCodigos( @PListaEstab )) <> 1
  begin
  RAISERROR (15600,-1,-1, 'ATENÇÃO: É permitido usar opção "considerar estoque" apenas para um estabelecimento.'); 
  Return
  end


if OBJECT_ID('tempdb..#listaestabcarga') Is Not Null
  Drop Table #listaestabcarga

Select es.Numero  
Into #listaestabcarga
From FN_ListaCodigos( @PListaEstab ) es
Select Top 1 @WCodEst = Numero From #listaestabcarga

while @@ROWCOUNT > 0
  begin
    Select @NumMesesAtualiza = CASE WHEN IsNull(QtdMesCalcSugCompra, 0) = 0 
                THEN 4 ELSE 7
               END 
        FROM PARAM where Cod_Estabe = @WCodEst 
  Exec PR_CN_Atualiza_Historico @WCodEst, @NumMesesAtualiza 
  Delete From #listaestabcarga Where Numero = @WCodEst
  Select Top 1 @WCodEst = Numero From #listaestabcarga
  end
Drop Table #listaestabcarga

if OBJECT_ID('tempdb..#listaProdu') Is Not Null
  Drop Table #listaProdu

Select pr.Numero
Into #listaProdu
From FN_ListaCodigos(@PLstProduto) pr

-- Mês atual
Set @DataAux = @DataRef
Select @AnoMes0 = Year(@DataAux) * 100 + Month(@DataAux)
-- 1 Mes anterior
Set @DataAux = DateAdd(MONTH,-1,@DataAux);
Select @AnoMes1 = Year(@DataAux) * 100 + Month(@DataAux)
-- 2 Meses anteriores
Set @DataAux = DateAdd(MONTH,-1,@DataAux);
Select @AnoMes2 = Year(@DataAux) * 100 + Month(@DataAux)
-- 3 Meses anteriores
Set @DataAux = DateAdd(MONTH,-1,@DataAux);
Select @AnoMes3 = Year(@DataAux) * 100 + Month(@DataAux)

-- 4 Meses anteriores
Set @DataAux = DateAdd(MONTH,-1,@DataAux);
Select @AnoMes4 = Year(@DataAux) * 100 + Month(@DataAux)
-- 5 Meses anteriores
Set @DataAux = DateAdd(MONTH,-1,@DataAux);
Select @AnoMes5 = Year(@DataAux) * 100 + Month(@DataAux)
-- 6 Meses anteriores
Set @DataAux = DateAdd(MONTH,-1,@DataAux);
Select @AnoMes6 = Year(@DataAux) * 100 + Month(@DataAux)


Begin Transaction

Set @IsnPedido = 0

Declare Cr_Itens CURSOR LOCAL FAST_FORWARD FOR 

  Select hs.Cod_Estabe, hs.Ref_AnoMes, hs.Cod_Produt, px.Sta_AbcUniVen, px.Sta_AbcValFat,
         px.Sta_AbcUniVenFab, px.Sta_AbcValFatFab,
         hs.Prc_UniCom, hs.Prc_UniVen, hs.Prc_UniFab, hs.Prc_UniCus,
         Case 
       When (@PTipoPreco = 0) and (hs.Prc_UniFab > 0) then hs.Prc_UniFab 
       When (@PTipoPreco = 0) and (hs.Prc_UniFab = 0) then hs.Prc_UniCom 
       When @PTipoPreco = 1 then hs.Prc_UniCom
       else 0
         end as Prc_UniAna,
         hs.Qtd_Dispon, hs.Qtd_Transi, hs.Qtd_EmbFec, hs.Qtd_Faltas, hs.Qtd_EstTraMan, px.Qtd_DiaSupPrd,
     IsNull(pm.PerMinRndCxaFecInfSugCmp,100) as PerMinCxa
  From CN_HSPRD hs
       Inner Join PRODU pr On pr.Codigo = hs.Cod_Produt 
       Inner Join FN_ListaCodigos( @PListaEstab ) es On hs.Cod_Estabe = es.Numero
       Inner Join PRXES px On px.Cod_Estabe = hs.Cod_Estabe And px.Cod_Produt = hs.Cod_Produt   
       Inner Join PARAM pm On pm.Cod_Estabe = hs.Cod_Estabe
       Left Join FORNE fo on fo.Codigo = @PCodFornecedor
       Left Join FRXFB fx on fx.Cod_Fabric = pr.Cod_Fabricante and fx.Cod_fornec = fo.Codigo
  Where 1 = 1
  And ( ((@PCodFabricante = -1) and (IsNull(fo.Tipo,'') = 'F') and (IsNull(fx.Cod_Fabric,0) > 0)) or 
        ((@PCodFabricante = -1) and (IsNull(fo.Tipo,'') <> 'F')) or 
        (pr.Cod_Fabricante = @PCodFabricante) )
  And ( (@PLstProduto = '0') or (hs.Cod_Produt in (select Numero from #listaProdu)))
  And ( hs.Ref_AnoMes = @AnoMes0 ) 
  --Bloqueio de compras
  And pr.Flag_ImprClassif1 <> 'N' 
  And IsNull(px.Flg_BlqCmp,0) = 0 

  Order by hs.Cod_Estabe, hs.Cod_Produt, hs.Ref_AnoMes Desc
  
Open Cr_Itens
Fetch Next From Cr_Itens Into @it_CodEstabe, @RefAnoMes, @it_CodProdut,@it_StaAbcUniPrd,@it_StaAbcValPrd,
                              @it_StaAbcUniFab, @it_StaAbcValFab, @it_PrcUniCom, @it_PrcUniVen, 
                @it_PrcUniFab, @it_PrcUniCus, @it_PrcUniAna, @it_QtdDispon, @it_QtdTransi, 
                @it_QtdEmbFec, @it_QtdFaltas, @it_QtdEstTraMan, @it_QtdDiaSupPrd, @PerMinCxa
 While @@Fetch_Status = 0 
 Begin
   if @IsnPedido = 0
     begin
     set @TxPcFor = ''
     if OBJECT_ID('tempdb..##CN_PCFOR') Is Not Null and ((select 1 from dbo.##CN_PCFOR) > 0)
       begin
       set @TxPcFor = '"PCFOR": ['
         Declare Cr_Pcfor CURSOR LOCAL FAST_FORWARD FOR 
             select Cod_Fornec, Cod_Estabe, Id_PCFOR from dbo.##CN_PCFOR
         Open  Cr_Pcfor 
             Fetch Next From Cr_Pcfor Into @TxCodEst, @TxCodFor, @TxIdPcFor 
             While @@Fetch_Status = 0 
         begin
           set @TxPcFor = @TxPcFor + ' { "Estabe":'+Convert(varchar(6),@TxCodEst)+', '+
                                 '  "Fornec":'+Convert(varchar(6),@TxCodFor)+', '+
                                   '  "IdPcFor":'+Convert(varchar(6),@TxIdPcFor)+
                           ' } '
               Fetch Next From Cr_Pcfor Into @TxCodEst, @TxCodFor, @TxIdPcFor 
         if @@FETCH_STATUS!=0 
           set @TxPcFor = @TxPcFor + ', '
         end
       set @TxPcFor = Substring(@TxPcFor, 1, (len(@TxPcFor) - 1))+ ' ] '
         Close Cr_Pcfor
             Deallocate Cr_Pcfor       
       end 

     Set @DataAux = Convert( Date, GetDate() , 103)      -- pegar data sem a hora
     Set @DataAux = DateAdd( day , @PDiasRep, @DataAux ) -- adicionar os dias de reposição para a entrega

       Execute dbo.PR_ProxNumero 'Cn_Isn_Pedido', @IsnPedido OUTPUT

     If @PTitulo = ''
       begin
       Set @PTitulo = 'Análise : '+Convert(varchar(10),@IsnPedido)+' (Dias de Rep.: '+Convert(varchar(6),@PDiasRep)+') Gerado por: '+dbo.FN_UsuarioInfarma()
     end

     Set @TxParam = '{'+ 
                    '"Mes1": '+Convert(varchar(6),@AnoMes6)+', '+
                    '"Mes2": '+Convert(varchar(6),@AnoMes5)+', '+
                    '"Mes3": '+Convert(varchar(6),@AnoMes4)+', '+
                    '"Mes4": '+Convert(varchar(6),@AnoMes3)+', '+
          '"Mes5": '+Convert(varchar(6),@AnoMes2)+', '+
                    '"Mes6": '+Convert(varchar(6),@AnoMes1)+', '+
                    '"Mes7": '+Convert(varchar(6),@AnoMes0)+', '+                    
                    '"Fabricante": '+Convert(varchar(6),@PCodFabricante)+', '+
                    '"Fornecedor": '+Convert(varchar(6),@PCodFornecedor)+', '+
          '"Produto": "'+@PLstProduto+'", '+
                    '"Estab": "'+@PListaEstab+'",'+
                    '"DiasRep": '+Convert(varchar(6),@PDiasRep)+','+
                    '"DiasSupA": '+Convert(varchar(6),@PDiasSupClasseA)+','+
                    '"DiasSupB": '+Convert(varchar(6),@PDiasSupClasseB)+','+
                    '"DiasSupC": '+Convert(varchar(6),@PDiasSupClasseC)+', '+
                    '"UsaEstSegura": '+Convert(varchar(1),@PFlgEstoqueSeguranca)+','+
                    '"UsaEstTraMan": '+Convert(varchar(1),@PFlgUsaEstTraMan)+','+
                    '"EstabListEst": "'+@PLstEstoque+'", '+
          '"Titulo": "'+@PTitulo+'", '+
                    '"TipoPreco": '+Convert(varchar(1),@PTipoPreco)+', '+
                    '"PorCurva": '+Convert(varchar(1),@PPorCurva)+', '+
                    '"IndexCurva": '+Convert(varchar(1),@PIndexCurva)+', '+
                    '"UsaEstZero": '+Convert(varchar(1),@PUsaEstZero)+','+
                    '"UsaCurvaAbcFabric": '+Convert(varchar(1),@PUsaCurvaAbcFabric)

       if @TxPcFor <> '' 
         set @TxParam = @TxParam + ' , '+ @TxPcFor + ' } '
       else 
         set @TxParam = @TxParam + ' } '

       Select Top 1 @WStrPrzCmp = StrPrzCmp From FORNE Where Codigo = @PCodFornecedor
     
       Insert Into dbo.CN_PEDCB (Isn_Pedido, Val_TotPed, Qtd_UniPed, Qtd_DiasRep,
                               Des_ParPed, Des_ObsPed, Dat_Criacao, Dat_Refere, 
                 Dat_Entrega, Cod_Fornec, Des_Titulo, Usuario, 
                 Str_PrzCmp)
                         Values (@IsnPedido, 0.00, 0, @PDiasRep, @TxParam, '', 
                     GetDate(), @DataRef, @DataAux, @PCodFornecedor, 
                 @PTitulo, @PUsuario, @WStrPrzCmp )
     end
 
    if @IsnPedido <= 0 Break
    Set @Gera = 1

  if ( @PFlgApenasEstoqueZero = 1 and (@it_QtdDispon > 0) ) -- Flg Ativa Gera apenas se estoque = 0
    Set @Gera = 0
 
  if @Gera = 1
    begin
      -- Pegar Faturamento 0 mes atual
    Set @QtdFatMes0 = dbo.FN_CN_QtdFatPrd(@it_CodEstabe,@it_CodProdut,@AnoMes0)

      -- Pegar Faturamento 1 mes anterior
    Set @QtdFatMes1 = dbo.FN_CN_QtdFatPrd(@it_CodEstabe,@it_CodProdut,@AnoMes1)
    
      -- Pegar Faturamento 2 meses atras
    Set @QtdFatMes2 = dbo.FN_CN_QtdFatPrd(@it_CodEstabe,@it_CodProdut,@AnoMes2)
    
      -- Pegar Faturamento 3 meses atras
    Set @QtdFatMes3 = dbo.FN_CN_QtdFatPrd(@it_CodEstabe,@it_CodProdut,@AnoMes3)
    
    -- Pegar Faturamento 4 meses atras
    Set @QtdFatMes4 = dbo.FN_CN_QtdFatPrd(@it_CodEstabe,@it_CodProdut,@AnoMes4)
    
      -- Pegar Faturamento 5 meses atras
    Set @QtdFatMes5 = dbo.FN_CN_QtdFatPrd(@it_CodEstabe,@it_CodProdut,@AnoMes5)
    
      -- Pegar Faturamento 6 meses atras
    Set @QtdFatMes6 = dbo.FN_CN_QtdFatPrd(@it_CodEstabe,@it_CodProdut,@AnoMes6)
    
    Select @NumMesesAtualiza = CASE WHEN IsNull(QtdMesCalcSugCompra, 0) = 0 
                THEN 3 ELSE 6
               END 
        FROM PARAM where Cod_Estabe = @it_CodEstabe 

    -- calcular venda media diaria
        Set @QtdMedVen = dbo.FN_CN_QtdVenMedDia(@it_CodEstabe,@it_CodProdut,@DataRef,@NumMesesAtualiza)
    
    -- Estoque segurança
    Set @QtdEstSeg = 0
        Set @QtdDsvPad = dbo.FN_CN_DesvioPadrao(@it_CodEstabe,@it_CodProdut,@DataRef,@NumMesesAtualiza)
    if @PFlgEstoqueSeguranca = 1
      begin
        Set @NivSrv = 95.00 -- nivel.serviço 95%
        Set @FatSeg = dbo.FN_CN_FatorSeguranca(@NivSrv)   
        Set @QtdEstSeg = Round(@FatSeg*@QtdDsvPad*SQRT(@PDiasRep),0) 
      end
    
    -- estoque minimo
        Set @QtdEstMin = Round(@QtdMedVen*@PDiasRep,0) + @QtdEstSeg   
        
    -- estoque maximo
    Set @QtdEstMax = Round((@QtdEstSeg+@QtdMedVen)*@PDiasRep,0)
        
    -- estoque suprimento
    if @PTipoCurvaABC = 0
      begin
        Set @DiasSup = Case
                       When @it_StaAbcUniPrd = 'A' Then @PDiasSupClasseA
                       When @it_StaAbcUniPrd = 'B' Then @PDiasSupClasseB
                       Else @PDiasSupClasseC
                       End  
          end
    else
      begin
        Set @DiasSup = Case
                       When @it_StaAbcUniPrd = 'A' Then @PDiasSupClasseA -- Feito aqui para deixar o do produto caso do Fabricante em branco
                       When @it_StaAbcUniPrd = 'B' Then @PDiasSupClasseB -- Feito aqui para deixar o do produto caso do Fabricante em branco
               When (IsNull(@it_StaAbcUniFab, '') <> '') and @it_StaAbcUniFab = 'A' Then @PDiasSupClasseA
                       When (IsNull(@it_StaAbcUniFab, '') <> '') and @it_StaAbcUniFab = 'B' Then @PDiasSupClasseB
                       Else @PDiasSupClasseC
                       End  
      end
    If @it_QtdDiaSupPrd > 0 
      Set @DiasSup = @it_QtdDiaSupPrd

    Set @QtdRessup = Round(@QtdMedVen*@DiasSup,0)  
    
    -- calcular sugestao de compra
    Set @QtdSugest = dbo.FN_CN_QtdSugCmp(@it_CodEstabe,@it_CodProdut,@DataRef,@PDiasRep,@DiasSup,@PFlgEstoqueSeguranca,@PFlgUsaEstTraMan,@PLstEstoque)
    
    Set @CodPedido = 0
    Set @DatPedido = null
    Set @QtdSugDia = @DiasSup
    Set @CalcVar1  = Cast(@QtdSugest as numeric(18,4));
    Set @CalcVar2  = Cast(@it_QtdEmbFec as numeric(18,4));    
    Set @CalcVar1  = @CalcVar1 / @CalcVar2
    Set @CalcVar1  = CEILING( @CalcVar1 )
    Set @QtdPedido = Convert( int , @it_QtdEmbFec * @CalcVar1 )

    -----------------------------------------
    -- Se sugestão for menor que embalagem de compra não sugere nada consideran parametro de % cxfec
    -----------------------------------------
    if (@QtdPedido > 0) and (@QtdPedido < @it_QtdEmbFec)
          begin
        if @PerMinCxa = 0
        Set @PerMinCxa = 100
      if round((@QtdPedido/@it_QtdEmbFec)*100,0) < @PerMinCxa
          Set @QtdPedido = 0
      end
    -----------------------------------------

--      Set @PerDescon = 0
--      Pega o desconto da tabela independente do fornecedor
--    Select Top 1
--      @PerDescon = dbo.FN_CN_DescontoFornecedor(Per_Dsc1,Per_Dsc2,Per_Dsc3,Per_Dsc4,Per_Dsc5),
--      @PerRepasse =  IsNull(Per_Repasse,0)
--    From FRXPR
--    Where Cod_Produt = @it_CodProdut
--    And (-1 = @PCodFornecedor or Cod_Fornec = @PCodFornecedor)

    
    if OBJECT_ID('tempdb..##CN_PCFOR') Is Not Null
      begin
      Select Top 1
        @PerDescon = dbo.FN_CN_DescontoFornecedor(pr.Per_Dsc1,pr.Per_Dsc2,pr.Per_Dsc3,pr.Per_Dsc4,pr.Per_Dsc5),
        @PerRepasse =  IsNull(pr.Per_Repasse,0)
      From dbo.PCFPR pr
      Inner Join dbo.##CN_PCFOR fr On pr.Id_PCFOR = fr.Id_PCFOR
      Where pr.Cod_Produt = @it_CodProdut
      And (fr.Cod_Fornec = @PCodFornecedor)
      And (fr.Cod_Estabe = @it_CodEstabe)
      end
    Set @PerDescon = Coalesce(@PerDescon,0)

    /*Select @WStaAbcValFat = Sta_AbcValFat, 
           @WStaAbcUniVen = Sta_AbcUniVen, 
         @WQtdDiaSupPrd = Qtd_DiaSupPrd 
    From PRXES
    Where Cod_Estabe = @it_CodEstabe
    And Cod_Produt = @it_CodProdut
    If @@ROWCOUNT = 0*/
      Begin
        if @PTipoCurvaABC = 0
        Begin
          Set @WStaAbcValFat = @it_StaAbcValPrd
          Set @WStaAbcUniVen = @it_StaAbcUniPrd
              end
      else
        begin
          if IsNull(@it_StaAbcValFab, '') = ''
          Set @WStaAbcValFat = @it_StaAbcValPrd
                else
            Set @WStaAbcValFat = @it_StaAbcValFab
        if IsNull(@it_StaAbcUniFab, '') = ''
          Set @WStaAbcUniVen = @it_StaAbcUniPrd
        else    
            Set @WStaAbcUniVen = @it_StaAbcUniFab
        end   
      Set @WQtdDiaSupPrd = @QtdRessup
      End

    Insert Into CN_PEDIT (Isn_Pedido, Cod_Estabe, Cod_Produt, Cod_Pedido, Sta_AbcUni, Sta_AbcVal,
                              Prc_UniCom, Prc_UniVen, Prc_UniFab, Prc_UniCus, Prc_UniAna, Qtd_MedVen, Qtd_Dispon,
                              Qtd_Transi, Qtd_EmbFec, Qtd_EstMin, Qtd_EstMax, Qtd_Ressup,
                              Qtd_Sugest, Qtd_SugDia, Qtd_Faltas, Qtd_Pedido, Dat_Pedido,
                              Per_Descon, Qtd_FatMes0, Qtd_FatMes1, Qtd_FatMes2, Qtd_FatMes3,
                              Qtd_DsvPad, Qtd_EstSeg, Per_Repasse, Qtd_EstTraMan, 
                Sta_AbcUniPrd, Sta_AbcValPrd, Sta_AbcUniFab, Sta_AbcValFab,
                Qtd_FatMes4, Qtd_FatMes5, Qtd_FatMes6)
          Values (@IsnPedido, @it_CodEstabe, @it_CodProdut, @CodPedido, @WStaAbcUniVen, @WStaAbcValFat,
                  @it_PrcUniCom, @it_PrcUniVen, @it_PrcUniFab, @it_PrcUniCus, @it_PrcUniAna, @QtdMedVen, @it_QtdDispon, 
              @it_QtdTransi, @it_QtdEmbFec, @QtdEstMin, @QtdEstMax, @WQtdDiaSupPrd,
              @QtdSugest, @QtdSugDia, @it_QtdFaltas, @QtdPedido, @DatPedido,  
              @PerDescon, @QtdFatMes0, @QtdFatMes1, @QtdFatMes2, @QtdFatMes3,
              @QtdDsvPad, @QtdEstSeg, @PerRepasse, @it_QtdEstTraMan,
          @it_StaAbcUniPrd, @it_StaAbcValPrd, @it_StaAbcUniFab, @it_StaAbcValFab,
          @QtdFatMes4, @QtdFatMes5, @QtdFatMes6)
    end

  Fetch Next From Cr_Itens Into @it_CodEstabe, @RefAnoMes, @it_CodProdut,@it_StaAbcUniPrd, @it_StaAbcValPrd,
                                @it_StaAbcUniFab, @it_StaAbcValFab,
                                @it_PrcUniCom, @it_PrcUniVen, @it_PrcUniFab, @it_PrcUniCus, @it_PrcUniAna,
                                @it_QtdDispon, @it_QtdTransi, @it_QtdEmbFec, @it_QtdFaltas, @it_QtdEstTraMan,
                                @it_QtdDiaSupPrd,
                @PerMinCxa
 End

 Close Cr_Itens
 Deallocate Cr_Itens

 -- Para atualizar os preços caso haja algum problema no histórico
 Update it Set 
       it.Prc_UniCom = Case 
                           When (IsNull(xe.Prc_UltEntDep,0) = 0) or 
                               ((IsNull(xe.Prc_UltEnt,0) > 0) and (xe.Dat_UltCompra >= xe.Dat_UltEntDep) and 
                                (IsNull(xe.Prc_UltEntDep,0) > 0)) Then xe.Prc_UltEnt 
                           Else xe.Prc_UltEntDep 
                           End,
       it.Prc_UniVen = IsNull(xe.Prc_Venda,0),
     it.Prc_UniFab = IsNull(xe.Prc_Fabric,0),
       it.Prc_UniCus = IsNull(xe.Prc_CusMed,0)
    From dbo.CN_PEDIT it 
    Inner Join dbo.PRXES xe On (xe.Cod_Estabe = it.Cod_Estabe) And (xe.Cod_Produt = it.Cod_Produt)
 Where it.Isn_Pedido = @IsnPedido

if OBJECT_ID('tempdb..#listaProdu') Is Not Null
  Drop Table #listaProdu

Commit Transaction
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-----------------------------------------------------------------------------------------------------------
----  Rotina para reprocessar custos custos em (PRXES, HSPRC, NFEIT, NFSIT)  de                        ----
----  NF Entradas a partir da data base definida                                                       ----
----  PRXES: Prc_CusLiqEnt, Prc_CusLiqEntDep, Prc_CusMed, Prc_CusMedCom, Prc_CusMedPra, Prc_CusMedDep  ----
----  HSPRC: Vlr_CusLiqPra, Vlr_CusLiqDep,    Vlr_CusMed, Vlr_CusMedCom, Vlr_CusMedPra, Vlr_CusMedDep  ----
----  NFEIT: Prc_CusMedAnt, Prc_CustoMedio                                                             ----  
----  NFSIT: Vlr_CusIte                                                                                ----
-----------------------------------------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[PR_ReprocessaCustosEntrada]
@PCodEstabe int,
@PMesMov smallint,        -- mes inicial
@PAnoMov smallint,        -- ano inicial
@PCodPrd int,             -- 0 = todos os produtos
@PFlgBlqAltUltPrcCMC Bit  -- 1 = Bloqueia alteração do ultimo custo comercial do produto

AS

SET NOCOUNT ON

SET DATEFORMAT ymd

BEGIN

  Declare @DatRef smalldatetime,  -- data inicial
          @DatBas smalldatetime,
          @CodPrdIni int,
          @CodPrdFin int,
          @CodPrd int,
          @NumSeq int,
          @DatMov smalldatetime,
          @DatMovAnt smalldatetime,
          @DatUltEnt smalldatetime,
          @DatUltEntPra smalldatetime,
          @DatUltEntDep smalldatetime,
          @QtdSldPraAnt int,
          @QtdSldDepAnt int,
          @QtdSldDiaAnt int,
          @NumPrt int, 
          @PrcVenPrd numeric (18,4),
          @VlrPrcVenHis numeric (18,4),
          @QtdEnt int,
          @VlrBasCalSubTriUni numeric(18,4),
          @CusLiqPraAnt numeric (18,4), 
          @CusLiqDepAnt numeric (18,4), 
          @CusMedGerAnt numeric (18,4),
          @CusMedComAnt numeric (18,4),
          @CusMedPraAnt numeric (18,4),
          @CusMedDepAnt numeric (18,4),
          @VlrBasCalSubTriEntMedAnt numeric(18,4),
          @CusLiqPraNew numeric (18,4), 
          @CusLiqDepNew numeric (18,4), 
          @CusMedGerNew numeric (18,4),
          @CusMedComNew numeric (18,4),
          @CusMedPraNew numeric (18,4),
          @CusMedDepNew numeric (18,4),
          @VlrBasCalSubTriEntMedNew numeric(18,4),
          @CodCfoCab int, 
          @CodCfoIte int, 
          @CusLiqUni numeric (18,4),
          @CusLiqComUni numeric (18,4),
          @PrcUniMed numeric (18,4),
          @DscUniMed numeric (8,4)

  -- CFOp bonificacao
  Declare @KCfoBonEntInt int = 1910,
          @KCfoBonEntExt int = 2910		         

  Set @DatRef = Cast(Cast(@PAnoMov as varchar)+'-'+Cast(@PMesMov as varchar)+'-01 00:00:00' as smalldatetime)

  BEGIN TRY
    BEGIN TRANSACTION

    -- desabilita triggers de PRODU que atualiza historico de precos
    --ALTER TABLE PRODU DISABLE TRIGGER ALL
    --ALTER TABLE PRXES DISABLE TRIGGER ALL

    -----------------------------------------------------------------------
    -- seleciona itens de nota de entrada a partir da data de movimento  --
    -----------------------------------------------------------------------
    Set @CodPrdIni = 0
    Set @CodPrdFin = 999999999
	if @PCodPrd > 0
      begin
        Set @CodPrdIni = @PCodPrd
        Set @CodPrdFin = @PCodPrd
      end


    Declare HSPRC_Cr Cursor Local For 
    
      Select distinct it.Cod_Produto, pr.Dat_UltCompra, pr.Dat_UltEntDep, pr.Prc_Venda
        From NFECB cb 
             Inner Join NFEIT it on cb.Cod_Estabe = it.Cod_Estabe and cb.Protocolo = it.Protocolo
             Inner Join PRXES pr on it.Cod_Estabe = pr.Cod_Estabe and it.Cod_Produto = pr.Cod_Produt
       Where cb.Cod_Estabe = @PCodEstabe
         and cb.Status = 'F'
         and cb.Flg_MovEst = 1 
         and cb.Flg_AtuPrcCus = 1 
         and IsNull(cb.Dat_Movimento,0) > 0
         and cb.Dat_Movimento >= @DatRef
         and it.Cod_Produto between @CodPrdIni and @CodPrdFin
       Order by it.Cod_Produto
    
    Open HSPRC_Cr
    Fetch Next From HSPRC_Cr Into @CodPrd, @DatUltEntPra, @DatUltEntDep, @PrcVenPrd
    While @@FETCH_STATUS = 0
      begin
        Set @DatMov = null

        -- Normaliza registros em NFEIT
        Update it
           Set it.Dat_Movimento = cb.Dat_Movimento
          From NFECB cb 
               Inner Join NFEIT it on cb.Cod_Estabe = it.Cod_Estabe and cb.Protocolo = it.Protocolo
         Where cb.Cod_Estabe = @PCodEstabe     
           and cb.Status = 'F'
           and cb.Flg_MovEst = 1 
           and cb.Flg_AtuPrcCus = 1 
           and cb.Dat_Movimento >= @DatRef
           and it.Cod_Produto = @CodPrd
           and IsNull(it.Dat_Movimento,0) <> cb.Dat_Movimento

        -- ultima entrada do produto
        Select top 1 @DatMov = it.Dat_Movimento,
                     @CodCfoCab = cb.Cod_Cfo
          From NFECB cb 
               Inner Join NFEIT it on cb.Cod_Estabe = it.Cod_Estabe and cb.Protocolo = it.Protocolo
         Where cb.Cod_Estabe = @PCodEstabe     
           and cb.Status = 'F'
           and cb.Flg_MovEst = 1 
           and cb.Flg_AtuPrcCus = 1 
           and it.Cod_Produto = @CodPrd
         Order by cb.Dat_Movimento desc

        -- normaliza registros em NFEIT        
        if @DatMov is not null
          begin
            if @CodCfoCab > 0 
              Set @DatUltEnt = @DatUltEntPra 
            else
              Set @DatUltEnt = @DatUltEntDep
    
            -- verifica data minima inicial processamento
            if @DatMov > @DatRef
              begin
                Select top 1 @DatMov = it.Dat_Movimento
                  From NFECB cb 
                       Inner Join NFEIT it on cb.Cod_Estabe = it.Cod_Estabe and cb.Protocolo = it.Protocolo
                 Where cb.Cod_Estabe = @PCodEstabe     
                   and cb.Status = 'F'
                   and cb.Flg_MovEst = 1 
                   and cb.Flg_AtuPrcCus = 1 
                   and cb.Dat_Movimento >= @DatRef
                   and it.Cod_Produto = @CodPrd
                 Order by it.Dat_Movimento
              end
              
            Set @DatBas = @DatMov   

            -- seleciona itens de nota de entrada a partir da data base ordenadaos pela data
            Declare TABLE_Cr Cursor Local For 
           
              Select cb.Cod_Cfo, it.Dat_Movimento, it.Protocolo, it.Cod_Cfo,
                     sum(it.Qtd_Pedido+IsNull(it.Qtd_Bonificacao,0)),
                     sum(it.Cus_LiqUni*it.Qtd_Pedido)/sum(it.Qtd_Pedido+IsNull(it.Qtd_Bonificacao,0)),
                     case 
                       When IsNull(it.Vlr_DscIte2,0) > 0 then sum(it.Cus_LiqUni*it.Qtd_Pedido+it.Vlr_DscIte2)/sum(it.Qtd_Pedido+IsNull(it.Qtd_Bonificacao,0))
                       Else sum(it.Cus_LiqUni*it.Qtd_Pedido)/sum(it.Qtd_Pedido+IsNull(it.Qtd_Bonificacao,0))
                     end,
                     sum(it.Prc_Unitario*(it.Qtd_Pedido+IsNull(it.Qtd_Bonificacao,0)))/sum(it.Qtd_Pedido+IsNull(it.Qtd_Bonificacao,0)),
                     sum(it.Per_DescItem*it.Prc_Unitario*(it.Qtd_Pedido+IsNull(it.Qtd_Bonificacao,0)))/sum(it.Prc_Unitario*(it.Qtd_Pedido+IsNull(it.Qtd_Bonificacao,0))),
                     case
                       When ((cb.Tip_NF = 'C') or (cb.Tip_NF = 'T') or (cb.Cod_Cfo = @KCfoBonEntExt) or (cb.Cod_Cfo = @KCfoBonEntInt)) 
                         then sum(it.Vlr_BasSubsTrib)/sum(it.Qtd_Pedido+IsNull(it.Qtd_Bonificacao,0))
                       Else 0
                     end
                From NFEIT it 
                     Inner Join NFECB cb on it.Cod_Estabe = cb.Cod_Estabe and it.Protocolo = cb.Protocolo
               Where cb.Cod_Estabe = @PCodEstabe     
                 and cb.Status = 'F'
                 and cb.Flg_MovEst = 1 
                 and cb.Flg_AtuPrcCus = 1 
                 and cb.Dat_Movimento >= @DatBas
                 and it.Cod_Produto = @CodPrd
               Group by cb.Cod_Cfo, it.Dat_Movimento, it.Protocolo, it.Cod_Cfo, cb.Tip_NF, it.Vlr_DscIte2
               Order by it.Dat_Movimento, it.Protocolo
           
            Open TABLE_Cr
            Fetch Next From TABLE_Cr Into @CodCfoCab, @DatMov, @NumPrt, @CodCfoIte, 
                                          @QtdEnt, @CusLiqUni, @CusLiqComUni, @PrcUniMed, @DscUniMed, @VlrBasCalSubTriUni
            While @@FETCH_STATUS = 0
              begin
           
                Set @DatMovAnt = @DatMov

                -- saldos anteriores mais proximos à data da entrada
                Set @QtdSldPraAnt = 0 
                Set @QtdSldDepAnt = 0
                Set @QtdSldDiaAnt = 0

                if Exists(Select 1 
                            From PRSLD
                           Where Cod_Estabe = @PCodEstabe 
                             And Cod_Produt = @CodPrd
                             And Dat_Movime < @DatMov)
                  Select Top 1 @QtdSldPraAnt = IsNull(Qtd_SldPra,0), 
                               @QtdSldDepAnt = IsNull(Qtd_SldDep,0), 
                               @QtdSldDiaAnt = IsNull(Qtd_SldAtu,0)
                    From PRSLD
                   Where Cod_Estabe = @PCodEstabe 
                     And Cod_Produt = @CodPrd
                     And Dat_Movime < @DatMov
                   Order by Dat_Movime desc
           
                if @QtdSldPraAnt < 0 Set @QtdSldPraAnt = 0
                if @QtdSldDepAnt < 0 Set @QtdSldDepAnt = 0
                if @QtdSldDiaAnt < 0 Set @QtdSldDiaAnt = 0

                -- inclui HSPRC
                if not Exists(Select 1 From HSPRC Where Cod_Estabe = @PCodEstabe and Cod_Produto = @CodPrd and Dat_Alteracao = @DatMov)
                  Exec PR_IncluiHSPRC @PCodEstabe, @CodPrd, @DatMov, @NumSeq output   

                -- custos medios imediatamente anteriores a data do movimennto
                Set @CusLiqPraAnt = 0
                Set @CusLiqDepAnt = 0
                Set @CusMedGerAnt = 0
                Set @CusMedComAnt = 0
                Set @CusMedPraAnt = 0
                Set @CusMedDepAnt = 0
                Set @VlrBasCalSubTriEntMedAnt = 0

                if Exists(Select 1
                            From HSPRC
                           Where Cod_Estabe = @PCodEstabe     
                             And Cod_Produto = @CodPrd
                             And Dat_Alteracao < @DatMov)
                  Select Top 1 @CusLiqPraAnt = IsNull(Vlr_CusLiqPra,0), 
                               @CusLiqDepAnt = IsNull(Vlr_CusLiqDep,0), 
                               @CusMedGerAnt = IsNull(Vlr_CusMed,0),
                               @CusMedComAnt = IsNull(Vlr_CusMedCom,0),
                               @CusMedPraAnt = IsNull(Vlr_CusMedPra,0), 
                               @CusMedDepAnt = IsNull(Vlr_CusMedDep,0),
                               @VlrBasCalSubTriEntMedAnt = IsNull(Vlr_BasCalSubTriEntMed,0)
                    From HSPRC
                   Where Cod_Estabe = @PCodEstabe     
                     And Cod_Produto = @CodPrd
                     And Dat_Alteracao < @DatMov
                   Order by Dat_Alteracao desc, Seq_Alteracao desc
           
                if @CusLiqPraAnt < 0 Set @CusLiqPraAnt = 0
                if @CusLiqDepAnt < 0 Set @CusLiqDepAnt = 0
                if @CusMedGerAnt < 0 Set @CusMedGerAnt = 0
                if @CusMedComAnt < 0 Set @CusMedComAnt = 0
                if @CusMedPraAnt < 0 Set @CusMedPraAnt = 0
                if @CusMedDepAnt < 0 Set @CusMedDepAnt = 0
                if @VlrBasCalSubTriEntMedAnt < 0 Set @VlrBasCalSubTriEntMedAnt = 0
           
                While (@DatMovAnt = @DatMov) and (@@FETCH_STATUS = 0)
                  begin
                    if @CodCfoCab > 0
                      Update pr
                         Set pr.Prc_CusLiqEnt = @CusLiqUni,
                             pr.Prc_EntAnt    = pr.Prc_UltEnt,
                             pr.Per_DscEntAnt = pr.Per_DscUltEnt,
                             pr.Qtd_EntAnt    = pr.Qtd_UltEnt,
                             pr.Dat_EntAnt    = pr.Dat_UltCompra,
                             pr.Prc_UltEnt    = @PrcUniMed,
                             pr.Per_DscUltEnt = @DscUniMed,
                             pr.Qtd_UltEnt    = @QtdEnt,
                             pr.Dat_UltCompra = @DatMov
                        From PRXES pr
                       Where pr.Cod_Estabe = @PCodEstabe And pr.Cod_Produt = @CodPrd
                    else
                      Update pr
                         Set pr.Prc_CusLiqEntDep = @CusLiqUni,
                             pr.Prc_EntAntDep    = pr.Prc_UltEntDep,
                             pr.Per_DscEntAntDep = pr.Per_DscUltEntDep,
                             pr.Qtd_EntAntDep    = pr.Qtd_UltEntDep,
                             pr.Dat_EntAntDep    = pr.Dat_UltEntDep,
                             pr.Prc_UltEntDep    = @PrcUniMed,
                             pr.Per_DscUltEntDep = @DscUniMed,
                             pr.Qtd_UltEntDep    = @QtdEnt,
                             pr.Dat_UltEntDep    = @DatMov
                        From PRXES pr
                       Where pr.Cod_Estabe = @PCodEstabe And pr.Cod_Produt = @CodPrd

                    -- atualiza registro de entrada
                    Update NFEIT
                       Set Qtd_FisAnt = @QtdSldDiaAnt,
--                           Vlr_BasCalSubTriEntMedAnt = @VlrBasCalSubTriEntMedAnt,
                           Prc_CusMedAnt = @CusMedGerAnt
                     Where Cod_Estabe = @PCodEstabe
                       And Protocolo = @NumPrt
                       And Cod_Produto = @CodPrd
                       And ((Qtd_FisAnt <> @QtdSldDiaAnt) or (Prc_CusMedAnt <> @CusMedGerAnt))
                
                    Update HSPRC
                       Set Vlr_CusLiqPra = @CusLiqPraAnt,
                           Vlr_CusLiqDep = @CusLiqDepAnt,
                           Vlr_CusMed    = @CusMedGerAnt,
                           Vlr_CusMedCom = Case 
                                             When @PFlgBlqAltUltPrcCMC = 0 then @CusMedComAnt 
                                             Else Vlr_CusMedCom 
                                           End,
                           Vlr_CusMedPra = @CusMedPraAnt,
                           Vlr_CusMedDep = @CusMedDepAnt
--                           Vlr_BasCalSubTriEntMed = @VlrBasCalSubTriEntMedAnt
                     Where Cod_Estabe = @PCodEstabe
                       and Cod_Produto = @CodPrd 
                       and Dat_Alteracao >= @DatMov
                       And ((Vlr_CusMed <> @CusMedGerAnt) or (Vlr_CusMedCom <> @CusMedComAnt) or 
                            (Vlr_CusMedPra <> @CusMedPraAnt) or (Vlr_CusMedDep <> @CusMedDepAnt))

                
                     -- zera saldo se o custo anterior estiver zerado
                    if @CusMedGerAnt = 0
                      Set @QtdSldDiaAnt = 0
                    if @CusMedPraAnt = 0
                      Set @QtdSldPraAnt = 0
                    if @CusMedDepAnt = 0
                      Set @QtdSldDepAnt = 0
                
                    -- custos a calcular
                    Set @CusLiqPraNew = 0
                    Set @CusLiqDepNew = 0
                    Set @CusMedGerNew = 0
                    Set @CusMedComNew = 0
                    Set @CusMedPraNew = 0
                    Set @CusMedDepNew = 0
                
/*               
                    Set @VlrBasCalSubTriEntMedNew = 0

                   -- base de calculo media ST
                    if @VlrBasCalSubTriUni > 0
                      begin
                        Set @VlrBasCalSubTriEntMedNew = (@VlrBasCalSubTriEntMedAnt*@QtdSldDiaAnt + @VlrBasCalSubTriUni*@QtdEnt)/(@QtdSldDiaAnt+@QtdEnt)

                        Update PRXES
                          Set Vlr_BasCalSubTriEntMed = @VlrBasCalSubTriEntMedNew
                        Where Cod_Estabe = @PCodEstabe
                        And Cod_Produt = @CodPrd
                        And @VlrBasCalSubTriEntMedNew > 0
                        And Vlr_BasCalSubTriEntMed <> @VlrBasCalSubTriEntMedNew

                        Update HSPRC
                          Set Vlr_BasCalSubTriEntMed = @VlrBasCalSubTriEntMedNew
                        Where Cod_Estabe = @PCodEstabe
                        And Cod_Produto = @CodPrd 
                        And Dat_Alteracao >= @DatMov
                        And @VlrBasCalSubTriEntMedNew > 0
                        And Vlr_BasCalSubTriEntMed <> @VlrBasCalSubTriEntMedNew
                      end 
*/

                    -- custo medio gerencial
                    -- verifica tipo de bonificacao
                    if ((@CodCfoCab <> @KCfoBonEntInt) and (@CodCfoCab <> @KCfoBonEntExt)) and  -- nao eh nf de bonificacao
                       ((@CodCfoIte = @KCfoBonEntInt) or (@CodCfoIte = @KCfoBonEntExt)) 
                      begin
                        Set @CusMedGerNew = (@CusMedGerAnt*@QtdSldDiaAnt)/(@QtdSldDiaAnt+@QtdEnt)
                        Set @CusMedComNew = (@CusMedComAnt*@QtdSldDiaAnt)/(@QtdSldDiaAnt+@QtdEnt)
                      end
                    else
                      begin
                        Set @CusMedGerNew = (@CusMedGerAnt*@QtdSldDiaAnt+@CusLiqUni*@QtdEnt)/(@QtdSldDiaAnt+@QtdEnt)
                        Set @CusMedComNew = (@CusMedComAnt*@QtdSldDiaAnt+@CusLiqComUni*@QtdEnt)/(@QtdSldDiaAnt+@QtdEnt)
                      end

                    Update PRXES
                       Set Prc_CusMed = @CusMedGerNew
                     Where Cod_Estabe = @PCodEstabe
                       And Cod_Produt = @CodPrd
                       And @CusMedGerNew > 0
                       And Prc_CusMed <> @CusMedGerNew
                
                    
		            if @PFlgBlqAltUltPrcCMC = 0
                      Update PRXES
                         Set Prc_CusMedCom = @CusMedComNew
                       Where Cod_Estabe = @PCodEstabe
                         And Cod_Produt = @CodPrd
                         And @CusMedComNew > 0
                         And Prc_CusMedCom <> @CusMedComNew

                    Update it
                       Set it.Vlr_CusIte = @CusMedGerNew
                      From NFSIT it 
                           Inner Join NFSCB cb on it.Cod_Estabe = cb.Cod_Estabe and it.Ser_Nota = cb.Ser_Nota and it.Num_Nota = cb.Num_Nota
                     Where it.Cod_Estabe = @PCodEstabe
                       And it.Cod_Produto = @CodPrd
                       And cb.Dat_Emissao >= @DatMov
                       And it.Vlr_CusIte <> @CusMedGerNew
                
                    Update HSPRC
                       Set Vlr_CusMed = @CusMedGerNew
                     Where Cod_Estabe = @PCodEstabe
                       And Cod_Produto = @CodPrd 
                       And Dat_Alteracao >= @DatMov
                       And @CusMedGerNew > 0
                       And Vlr_CusMed <> @CusMedGerNew

		            if @PFlgBlqAltUltPrcCMC = 0
                      Update HSPRC
                         Set Vlr_CusMedCom = @CusMedComNew 
                       Where Cod_Estabe = @PCodEstabe
                         And Cod_Produto = @CodPrd 
                         And Dat_Alteracao >= @DatMov
                         And @CusMedComNew > 0
                         And Vlr_CusMedCom <> @CusMedComNew
                
                    -- custo medio 1
                    if @CodCfoCab > 0
                      begin
                        Update PRXES
                           Set Prc_CusLiqEnt = @CusLiqUni,
                               Dat_UltCompra = @DatMov,
                               Qtd_UltEnt = @QtdEnt
                         Where Cod_Estabe = @PCodEstabe
                           And Cod_Produt = @CodPrd
                
                        -- verifica tipo de bonificacao
                        if ((@CodCfoCab <> @KCfoBonEntInt) and (@CodCfoCab <> @KCfoBonEntExt)) and  -- nao eh nf de bonificacao
                           ((@CodCfoIte = @KCfoBonEntInt) or (@CodCfoIte = @KCfoBonEntExt)) 
                          begin
                            Set @CusLiqPraNew = (@CusLiqPraAnt*@QtdSldPraAnt)/(@QtdSldPraAnt+@QtdEnt)
                            Set @CusMedPraNew = (@CusMedPraAnt*@QtdSldPraAnt)/(@QtdSldPraAnt+@QtdEnt)
                          end
                        else
                          begin
                            Set @CusLiqPraNew = (@CusLiqPraAnt*@QtdSldPraAnt+@CusLiqUni*@QtdEnt)/(@QtdSldPraAnt+@QtdEnt)
                            Set @CusMedPraNew = (@CusMedPraAnt*@QtdSldPraAnt+@CusLiqUni*@QtdEnt)/(@QtdSldPraAnt+@QtdEnt)
                          end
                
                        Update PRXES
                           Set Prc_CusMedPra = @CusMedPraNew
                         Where Cod_Estabe = @PCodEstabe
                           And Cod_Produt = @CodPrd
                           And @CusMedPraNew > 0
                           And Prc_CusMedPra <> @CusMedPraNew
                
                        Update HSPRC
                           Set Vlr_CusMedPra = @CusMedPraNew,
                               Vlr_CusLiqPra = @CusLiqUni
                         Where Cod_Estabe = @PCodEstabe
                           And Cod_Produto = @CodPrd 
                           And Dat_Alteracao >= @DatMov
                           And @CusMedPraNew > 0
                           And ((Vlr_CusMedPra <> @CusMedPraNew) or (Vlr_CusLiqPra <> @CusLiqUni))
                      end

                    else              
                    -- custo medio 2
                      begin
                        Update PRXES
                           Set Prc_CusLiqEntDep = @CusLiqUni,
                               Dat_UltEntDep = @DatMov,
                               Qtd_UltEntDep = @QtdEnt
                         Where Cod_Estabe = @PCodEstabe
                           And Cod_Produt = @CodPrd
                        
                        Set @CusLiqDepNew = (@CusLiqDepAnt*@QtdSldDepAnt+@CusLiqUni*@QtdEnt)/(@QtdSldDepAnt+@QtdEnt)
                        Set @CusMedDepNew = (@CusMedDepAnt*@QtdSldDepAnt+@CusLiqUni*@QtdEnt)/(@QtdSldDepAnt+@QtdEnt)

                        Update PRXES
                           Set Prc_CusMedDep = @CusMedDepNew
                         Where Cod_Estabe = @PCodEstabe
                           And Cod_Produt = @CodPrd
                           And @CusMedDepNew > 0
                           And Prc_CusMedDep <> @CusMedDepNew
          
                        Update HSPRC
                           Set Vlr_CusMedDep = @CusMedDepNew,
                               Vlr_CusLiqDep = @CusLiqUni
                         Where Cod_Estabe = @PCodEstabe
                           And Cod_Produto = @CodPrd 
                           And Dat_Alteracao >= @DatMov
                           And @CusMedDepNew > 0
                           And ((Vlr_CusMedDep <> @CusMedDepNew) or (Vlr_CusLiqDep <> @CusLiqUni))
                      end

                    -- atualiza itens da nota   
                    Update it
                       Set it.Prc_CustoMedio = pr.Prc_CusMed
                      From NFEIT it 
                           Inner Join PRXES pr on it.Cod_Estabe = pr.Cod_Estabe and it.Cod_Produto = pr.Cod_Produt
                     Where it.Cod_Estabe = @PCodEstabe 
                       and it.Protocolo = @NumPrt
                       And it.Cod_Produto = @CodPrd

                    -- acumula p/ proxima entrada do dia
                    Set @QtdSldDiaAnt = @QtdSldDiaAnt + @QtdEnt 
                    if @CodCfoCab > 0
                      Set @QtdSldPraAnt = @QtdSldPraAnt + @QtdEnt
                    else
                      Set @QtdSldDepAnt = @QtdSldDepAnt + @QtdEnt   

                    Set @CusLiqPraAnt = @CusLiqPraNew
                    Set @CusLiqDepAnt = @CusLiqDepNew
                    Set @CusMedGerAnt = @CusMedGerNew
                    Set @CusMedComAnt = @CusMedComNew
                    Set @CusMedPraAnt = @CusMedPraNew
                    Set @CusMedDepAnt = @CusMedDepNew

                    Fetch Next From TABLE_Cr Into @CodCfoCab, @DatMov, @NumPrt, @CodCfoIte, 
                                                  @QtdEnt, @CusLiqUni, @CusLiqComUni, @PrcUniMed, @DscUniMed, @VlrBasCalSubTriUni

                  end  -- While (@DatMovAnt = @DatMov) and (@@FETCH_STATUS = 0)

              end -- While @@FETCH_STATUS = 0  
            Close TABLE_Cr
            Deallocate TABLE_Cr

          end  -- if @DatMov is not null
/*
        else
          begin
            Set @VlrPrcVenHis = null
            Select Top 1 @VlrPrcVenHis = Vlr_PrcVen
              From HSPRC
              Where Cod_Estabe = @PCodEstabe     
              And Cod_Produto = @CodPrd
              Order by Dat_Alteracao desc
            
            if IsNull(@VlrPrcVenHis,0) <> IsNull(@PrcVenPrd,0)
              begin
                PRINT '!!!!!!!!!!!!!!!!!!  D E L E T A R  !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!'
              end    
          end  
*/
        Fetch Next From HSPRC_Cr Into @CodPrd, @DatUltEntPra, @DatUltEntDep, @PrcVenPrd
      end
    
    Close HSPRC_Cr
    Deallocate HSPRC_Cr

    -- habilita triggers
    --ALTER TABLE PRODU ENABLE TRIGGER ALL
    --ALTER TABLE PRXES ENABLE TRIGGER ALL

    if @@trancount > 0
      COMMIT TRANSACTION
  END TRY
  BEGIN CATCH
    if @@trancount > 0
      ROLLBACK TRANSACTION
    -- habilita triggers
    --ALTER TABLE PRODU ENABLE TRIGGER ALL
    --ALTER TABLE PRXES ENABLE TRIGGER ALL
  END CATCH

END
GO


SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE TRIGGER [dbo].[TR_CTREC_InsUpd] ON [dbo].[CTREC] 
FOR INSERT, UPDATE
NOT FOR REPLICATION
AS

-- comando p/ corrigir erro delphi/ado: record was changed by another user
SET NOCOUNT ON 

IF trigger_nestlevel() > 1 
  RETURN 

Declare @Chave int
      , @CodEstabe int
      , @CodDocume int
      , @TipVencim varchar(1)
      , @DatVencim smalldatetime
      , @DatBasJur smalldatetime
      , @IdTransac int
      , @VlrParTit numeric(18,4)
      , @VlrOutAcr numeric(18,4)
      , @IsnFinDsc int
      , @VlrDescon numeric(18,4)
      , @pm_FlgCalCtb bit
      , @pm_TipCalCtb varchar(1)
      , @pm_IsnCtaFinDsc int
    , @CodDocDel int
      , @VlrParDel numeric(18,4)
      , @VlrAcrDel numeric(18,4)
      , @QtdAcr smallint
      , @FlgAtu bit


Declare @TabIns Table(
  Chave Int Identity(1,1) PRIMARY KEY
, Cod_Estabe int
, Cod_Docume int
, Tip_Vencim varchar(1)
, Dat_Vencim smalldatetime
, Dat_BasJur smalldatetime
, Id_Transac int
, Vlr_ParTit numeric(18,4)
, Vlr_OutAcr numeric(18,4)
, Isn_FinDsc int
, Vlr_Descon numeric(18,4)
, Flg_CalCtb bit
, Tip_CalCtb varchar(1)
, Isn_FinPagDsc int
, Cod_DocDel int
, Vlr_ParDel numeric(18,4)
, Vlr_AcrDel numeric(18,4)
)

Insert Into @TabIns (Cod_Estabe, Cod_Docume, Tip_Vencim, Dat_Vencim, Dat_BasJur
                   , Id_Transac, Vlr_ParTit, Vlr_OutAcr, Isn_FinDsc, Vlr_Descon
                   , Flg_CalCtb, Tip_CalCtb, Isn_FinPagDsc
                   , Cod_DocDel, Vlr_ParDel, Vlr_AcrDel)

  Select IsNull(i.Cod_Estabe,0), i.Cod_Documento, IsNull(i.Tip_Vencimento,''), i.Dat_Vencimento, i.Dat_BaseJuros
       , IsNull(i.Id_Transacao,0), IsNull(i.Vlr_ParTit,0), IsNull(i.Vlr_OutAcr,0), IsNull(i.Isn_CtaFinDsc,0), IsNull(i.Vlr_DescConced,0)
       , IsNull(p.FlgCalCtbCtr,0), IsNull(p.TipCalCtbCtr,''), IsNull(pf.IsnCtaFinPagDesc,0)
       , IsNull(d.Cod_Documento,0), IsNull(d.Vlr_ParTit,0), IsNull(d.Vlr_OutAcr,0)

    From Inserted i
         inner Join PARAM p   on i.Cod_Estabe = p.Cod_Estabe
         Left  Join Deleted d on i.Cod_Estabe = d.Cod_Estabe and i.Cod_Documento = d.Cod_Documento
         Left  Join PMFIN pf  on pf.IsnCtaFinPagDesc > 0

   Where ( (i.Cod_Documento        <> IsNull(d.Cod_Documento,0)) or   -- somente insert
           (IsNull(i.Vlr_ParTit,0) <> IsNull(d.Vlr_ParTit,0)) or      -- Update(Vlr_ParTit)
       (IsNull(i.Vlr_OutAcr,0) <> IsNull(d.Vlr_OutAcr,0)) or      -- Update(Vlr_OutAcr)
       ((IsNull(i.Vlr_DescConced,0) > 0) and 
        (IsNull(i.Isn_CtaFinDsc,0) <> IsNull(pf.IsnCtaFinPagDesc,0))) 
     )

   Order by i.Cod_Estabe, i.Cod_Documento

While Exists(Select 1 From @TabIns)
begin
  Select top 1 
         @Chave = Chave

       , @CodEstabe = Cod_Estabe
       , @CodDocume = Cod_Docume
       , @TipVencim = Tip_Vencim
       , @DatVencim = Dat_Vencim
       , @DatBasJur = Dat_BasJur
       
     , @IdTransac = Id_Transac
       , @VlrParTit = Vlr_ParTit
       , @VlrOutAcr = Vlr_OutAcr
       , @IsnFinDsc = Isn_FinDsc
       , @VlrDescon = Vlr_Descon

       , @pm_FlgCalCtb = Flg_CalCtb
       , @pm_TipCalCtb = Tip_CalCtb
       , @pm_IsnCtaFinDsc = Isn_FinPagDsc

       , @CodDocDel = Cod_DocDel
       , @VlrParDel = Vlr_ParDel
       , @VlrAcrDel = Vlr_AcrDel
    From @TabIns
   Order by Chave

  Set @FlgAtu = 0

  -- somente inclusão
  if @CodDocDel = 0
    begin
      if (@DatVencim > 0) and 
         ((Datepart(dw,@DatVencim) = 1) or (Datepart(dw,@DatVencim) = 7)) and 
         (@pm_FlgCalCtb = 1)
        begin
          if (@pm_TipCalCtb = 'A') or ((@pm_TipCalCtb = 'M') and (Datepart(dw,@DatVencim) = 7))
            Set @QtdAcr = -1
          else
            Set @QtdAcr = 1
          While (Datepart(dw,@DatVencim) = 1) or (Datepart(dw,@DatVencim) = 7)
            Set @DatVencim = DateAdd(day,@QtdAcr,@DatVencim)
    
          Set @FlgAtu = 1
        end
    
      if @IdTransac = 0     
        begin
          EXEC PR_ProxNumeroEstab @CodEstabe, 'Id_Transacao', @IdTransac output
          if @@error <> 0
            begin
              Rollback Transaction
              Return
            end
    
          Set @FlgAtu = 1
        end
    
      -- teoricamente não deveria permitir modificar registro em Inserted/Deleted para evitar recursividade
      if (@FlgAtu = 1) and
         Exists(Select 1 From CTREC
                 Where Cod_Estabe = @CodEstabe 
                   And Cod_Documento = @CodDocume
                   And ((Dat_Vencimento <> @DatVencim) or
                        (Dat_BaseJuros  <> @DatVencim) or
                        (Id_Transacao   <> @IdTransac)))
        begin
          Update R
             Set R.Dat_Vencimento = @DatVencim
               , R.Dat_BaseJuros = @DatVencim
               , R.Id_Transacao = @IdTransac
            From Inserted I 
                 inner Join CTREC R on R.Cod_Estabe = I.Cod_Estabe And R.Cod_Documento = I.Cod_Documento
           Where R.Cod_Estabe = @CodEstabe 
             And R.Cod_Documento = @CodDocume
        end

    end -- somente inclusao

  if (@CodDocDel = 0) or
     (@VlrParTit <> @VlrParDel) or 
     (@VlrOutAcr <> @VlrAcrDel )
    begin
      Update R
         Set R.Vlr_Documento = Case 
                                 when (IsNull(I.Vlr_ParTit,0) + IsNull(I.Vlr_OutAcr,0)) >  0 then IsNull(I.Vlr_ParTit,0) + IsNull(I.Vlr_OutAcr,0)
                                 else I.Vlr_Documento
                               end
        From Inserted I 
             inner Join CTREC R on R.Cod_Estabe = I.Cod_Estabe And R.Cod_Documento = I.Cod_Documento
    end


  -- atualiza conta desconto concedido
  if (@VlrDescon > 0) and 
     (@IsnFinDsc <> @pm_IsnCtaFinDsc)
    begin
      Update R
         Set R.Isn_CtaFinDsc = @pm_IsnCtaFinDsc
        From Inserted I 
             inner Join CTREC R on R.Cod_Estabe = I.Cod_Estabe And R.Cod_Documento = I.Cod_Documento
    end


  -- somente inclusão
  if @CodDocDel = 0
    Exec PR_BaixaTituloAVistaCTREC @CodEstabe, @CodDocume  -- inclui BXREC


  Delete From @TabIns Where Chave = @Chave
end
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_AtualizaPCMOV] 
@TipOpe varchar(1),
@CodEstabe int,
@IsnCtaFin int,
@DatMov smalldatetime,
@NomTab varchar(5),
@TipDoc varchar(3),
@SerDoc varchar(3),
@NumDoc int,
@CodLan int,
@IdTransacao int,
@ValMov numeric(18,4)


AS

SET NOCOUNT ON
Set DateFormat ymd

Begin Transaction 

if Exists(Select 1 From PCFIN Where Isn_CtaFin = @IsnCtaFin)
  begin

    Declare @WNumSeqDia bigint,
          @WValSldAnt numeric(18,4),
            @WValSldAtu numeric(18,4),
            @WValMovAtu numeric(18,4),
            @WDatMov smalldatetime,
            @WTipDoc varchar(3),
            @WValAux numeric(18,4),
            @WFlgRep bit,
            @WNumSeq int,
            @WNumSeqMov bigint,
            @WMaxSeq int,
            @WTipMov varchar(3)
  
    -- indica necessidade de reprocessamento
    Set @WFlgRep = 0
    Set @WValAux = 0

    -- pega o ultimo sequencial do dia
    Set @WNumSeqDia = IsNull((Select max(Num_SeqGer) From PCMOV
                                Where Isn_CtaFin = @IsnCtaFin And Dat_Movime = @DatMov),0)

    -- pega o saldo imediatamente anterior
    Set @WValSldAnt = IsNull((Select top 1 Val_Saldo
                                From PCMOV
                                Where Isn_CtaFin = @IsnCtaFin
                                and Dat_Movime <= @DatMov
                                and ((Dat_Movime = @DatMov and Num_SeqGer <= @WNumSeqDia) or
                                     (Dat_Movime < @DatMov))
                                Order by Isn_CtaFin, Dat_Movime desc, Num_Sequen desc),0)

    -- inclui/altera movimento contas analiticas
    if (@TipOpe <> 'D') and (YEAR(ISNULL(@DatMov,0)) > 1950) and
       ((Select Tip_CtaFin From PCFIN Where Isn_CtaFin = @IsnCtaFin) = 'A')
      begin
        Set @WValSldAtu = 0
        Set @WTipMov = ''

        -- se existir registro INI posterior necessita reprocessamento
        if Exists(Select 1 From PCMOV
                    Where Isn_CtaFin = @IsnCtaFin
                    and Tip_Docume = 'INI'
                    and Dat_Movime > @DatMov)
          Set @WFlgRep = 1           

        -- se reg.inicial elimina todos os reg. iniciais posteriores a data do atual
        if @TipDoc = 'INI'
          begin
            Delete From PCMOV
              Where Isn_CtaFin = @IsnCtaFin
              and Tip_Docume = 'INI'
              and Dat_Movime > @DatMov
          end

        -- cancelamento (estorno)
        if @TipOpe = 'C'
          begin
            Set @WTipMov = 'CAN'
          end

        -- se ainda não existe o registro com os dados informados, inclui
        if not Exists(Select Isn_CtaFin From PCMOV 
                        Where Isn_CtaFin = @IsnCtaFin 
                        and Dat_Movime = @DatMov 
                        and Nom_Tabela = @NomTab
                        and Tip_Docume = @TipDoc
                        and Cod_Estabe = @CodEstabe
                        and Ser_Docume = @SerDoc
                        and Num_Docume = @NumDoc
                        and Cod_Lancam = @CodLan
                        and Id_Transacao = @IdTransacao)
          begin
            -- pega o proximo sequencial
            --Set @WMaxSeq = ISNULL((Select MAX(Num_Sequen) From PCMOV Where Cod_Estabe = @CodEstabe),0)  -- por estabelecimento ????
            Set @WMaxSeq = ISNULL((Select MAX(Num_Sequen) From PCMOV),0)
        
            if Exists(Select Valor From NUMER Where Campo = 'Seq_Movime')
              begin
                Update NUMER
                  Set Valor = @WMaxSeq
                  Where Campo = 'Seq_Movime'
                  And Valor < @WMaxSeq
               end
        
            EXEC PR_ProxNumero 'Seq_Movime', @WNumSeq output
            if @@error <> 0
              begin
                Rollback Transaction
                Return
              end
          
            -- insere novo registro com saldo = saldo anterior
            Set @WValSldAtu = @WValSldAnt
            Insert into PCMOV (Isn_CtaFin, Dat_Movime, Num_Sequen, Cod_Estabe, Cod_Lancam, Nom_Tabela, Tip_Docume, Tip_Movime, Ser_Docume, Num_Docume, Id_Transacao, Val_Movime, Val_Saldo)
                        Values(@IsnCtaFin, @DatMov, @WNumSeq, @CodEstabe, @CodLan, @NomTab, @TipDoc, IsNull(@WTipMov,''), @SerDoc, @NumDoc, @IdTransacao, @ValMov, @WValSldAtu) 

            Set @WNumSeqDia = IsNull((Select Num_SeqGer From PCMOV
                                      Where Isn_CtaFin = @IsnCtaFin and Dat_Movime = @DatMov 
                                        and Nom_Tabela = @NomTab and Tip_Docume = @TipDoc
                                    and Cod_Estabe = @CodEstabe and Cod_Lancam = @CodLan 
                                        and Ser_Docume = @SerDoc and Num_Docume = @NumDoc 
                    and Id_Transacao = @IdTransacao),0)

            if @TipDoc = 'INI'
              begin
                Set @WValSldAtu = @WValSldAnt   -- novo        
                Set @WValSldAnt = 0           
              end
              
          end
        else
          begin
            -- registro ja existe
            Set @WNumSeqDia = IsNull((Select Num_SeqGer From PCMOV
                                      Where Isn_CtaFin = @IsnCtaFin and Dat_Movime = @DatMov 
                                        and Nom_Tabela = @NomTab and Tip_Docume = @TipDoc
                                    and Cod_Estabe = @CodEstabe and Cod_Lancam = @CodLan 
                                        and Ser_Docume = @SerDoc and Num_Docume = @NumDoc 
                    and Id_Transacao = @IdTransacao),0)

            --Set @WValSldAtu = IsNull((Select Val_Saldo  From PCMOV Where Num_SeqGer = @WNumSeqDia),0)
            --Set @WValMovAtu = IsNull((Select Val_Movime From PCMOV Where Num_SeqGer = @WNumSeqDia),0)
            --Set @WNumSeq    = IsNull((Select Num_Sequen From PCMOV Where Num_SeqGer = @WNumSeqDia),0)

            Select top 1 @WValSldAtu = IsNull(Val_Saldo,0),
                         @WValMovAtu = IsNull(Val_Movime,0),
                         @WNumSeq    = IsNull(Num_Sequen,0)
      From PCMOV 
      Where Isn_CtaFin = @IsnCtaFin
      And Num_SeqGer = @WNumSeqDia
            Order by Dat_Movime desc, Num_Sequen desc

            if @WNumSeq > 0
              begin
                -- se for o caso atualiza valor
                Update PCMOV
                  Set Val_Movime = @ValMov
                Where Isn_CtaFin = @IsnCtaFin
                and Dat_Movime = @DatMov
                and Num_Sequen = @WNumSeq
                and Val_Movime <> @ValMov

                if @TipDoc = 'INI'
                  begin
                    Set @WValSldAnt = @WValSldAtu - @WValMovAtu           
                  end

              end
          end      

        -- calcula valor p/ reprocessamento de saldos
        Set @WValAux = @WValSldAnt + @ValMov - @WValSldAtu
        
      end
    else
    -- exclui movimento
    if @TipOpe = 'D'
      begin
        Set @WNumSeq = IsNull((Select Num_Sequen 
                                 From PCMOV 
                                 Where Isn_CtaFin = @IsnCtaFin 
                                 and Dat_Movime = @DatMov
                                 and Nom_Tabela = @NomTab 
                                 and Tip_Docume = @TipDoc
                                 and Cod_Estabe = @CodEstabe
                                 and Ser_Docume = @SerDoc 
                                 and Num_Docume = @NumDoc 
                                 and Cod_Lancam = @CodLan
                                 and Id_Transacao = @IdTransacao),0)
    
        if @WNumSeq > 0
          begin
            Delete From PCMOV
              Where Isn_CtaFin = @IsnCtaFin
              and Dat_Movime = @DatMov 
              and Num_Sequen = @WNumSeq

            -- calcula valor p/ reprocessamento de saldos
            Set @WValAux = -@ValMov

            if @TipDoc = 'INI'
              Set @WFlgRep = 1
          end  
      end

    -- atualiza os saldos
    if (@WFlgRep = 0) and (@WValAux <> 0)
      begin
        Update PCMOV 
          Set  Val_Saldo = Val_Saldo + @WValAux
          Where Isn_CtaFin = @IsnCtaFin
          and ((Dat_Movime = @DatMov and Num_SeqGer >= @WNumSeqDia) or (Dat_Movime > @DatMov))
      end
    else
    -- reprocessa saldos
    if @WFlgRep = 1
      begin
        -- atualizar saldos a partir do registro de inicio atual
        Declare PCMOV_Cr Cursor Local For 

          Select Dat_Movime, Num_SeqGer, Tip_Docume, Val_Movime, Val_Saldo            
            From PCMOV
            Where Isn_CtaFin = @IsnCtaFin
            and ((Dat_Movime = @DatMov and Num_SeqGer >= @WNumSeqDia) or (Dat_Movime > @DatMov))
            Order by Dat_Movime, Num_SeqGer

        Open PCMOV_Cr

        Fetch Next From PCMOV_Cr Into @WDatMov, @WNumSeqMov, @WTipDoc, @WValMovAtu, @WValSldAtu
        While @@FETCH_STATUS = 0
          begin
            if @WTipDoc = 'INI'
              Set @WValSldAnt = 0
                  
            if @WValSldAtu <> (@WValMovAtu+@WValSldAnt)
              begin
                Update PCMOV
                  Set Val_Saldo = @WValMovAtu+@WValSldAnt
                  Where Isn_CtaFin = @IsnCtaFin
                  And Dat_Movime = @WDatMov
          And Num_SeqGer = @WNumSeqMov
                
                Set @WValSldAtu = @WValMovAtu+@WValSldAnt
              end
                  
            Set @WValSldAnt = @WValSldAtu
                
            Fetch Next From PCMOV_Cr Into @WDatMov, @WNumSeqMov, @WTipDoc, @WValMovAtu, @WValSldAtu
          end
              
        Close PCMOV_Cr
        Deallocate PCMOV_Cr
        
      end  -- if @WFlgRep = 1

  end

Commit Transaction
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[FN_PrecoTabelaProduto]
(
@PCodCli int,
@PCodEstabe int,
@PCodPrd int,
@PIdPolComIte int,      -- PDVIT.Id_PolCom
@PCodTabPrc int,        -- PDVCB.Cod_TabPrc
@PFlgOrc bit,           -- indica se for "orçamento" 
@PFlgBlqDscAutIte bit   -- bloqueia desconto automatico do item  (parametro Pedido eletronico)     
)

RETURNS numeric(18,8)

AS

BEGIN

Declare @PPrcTab numeric(18,8),
        @pr_PrcVen numeric(18,8),
        @pr_PerDscAut numeric(18,8),
        @pc_PerAcrAutPrc numeric(7,4),
        @pc_PerDscAutPrc numeric(7,4),
        @pm_QtdDecPrcItePdv smallint,
        @pm_FlgCotPrcPrd bit = 0


Set @PPrcTab = 0

Set @pr_PrcVen = 0
Set @pr_PerDscAut = 0
Set @pc_PerAcrAutPrc = 0
Set @pc_PerDscAutPrc = 0


Select @pm_QtdDecPrcItePdv = IsNull(QtdDecPrcItePdv,0),
       @pm_FlgCotPrcPrd    = IsNull(FlgCotPrcPrd,0)
  From PARAM
 Where Cod_Estabe = @PCodEstabe

Select @pr_PrcVen    = IsNull(pr.Prc_Venda,0),  
       @pr_PerDscAut = Case 
                         When IsNull(@PFlgBlqDscAutIte,0) = 1 then 0
                         When IsNull(@PFlgOrc,0) = 1 then IsNull(pr.Per_DscAutOrc,0)
                         Else IsNull(pr.Per_DscAut,0)
                       End
  From PRXES pr 
       Inner Join PRODU p on pr.Cod_Produt = p.Codigo 
 Where pr.Cod_Estabe = @PCodEstabe
   And pr.Cod_Produt = @PCodPrd

if @PIdPolComIte > 0
  begin
    if Exists(Select 1 From POCOM Where Id_PolCom = @PIdPolComIte)
      begin
        Select --@PCodTabPrc = Case 
               --                When (IsNull(pc.Flg_UsaTabPrcCadCli,0) = 1) and (IsNull(es.Cod_TabPrc,0) > 0) then IsNull(es.Cod_TabPrc,0)
               --                Else IsNull(pc.Cod_TabPrc,0)
               --              End,
               @pc_PerAcrAutPrc = IsNull(pc.Per_AcrAutPrc,0), 
               @pc_PerDscAutPrc = IsNull(pc.Per_DscAutPrc,0)
          From POCOM pc 
               Left Join CLIEN cl on cl.Codigo = @PCodCli
               Left Join ENXES es on es.Cod_Estabe = @PCodEstabe and es.Num_CgcCpf = cl.Cgc_Cpf and es.Cod_Client = cl.Codigo
          Where pc.Id_PolCom = @PIdPolComIte
      end 
  end  -- @PIdPolComIte > 0


-- Pr. Tabela
if (@PCodTabPrc > 0) and            
   Exists(Select 1 From TPXPR it 
                        Inner Join TBPRC cb on (it.Cod_Estabe = cb.Cod_Estabe and it.Cod_TabPrc = cb.Cod_TabPrc)
           Where it.Cod_TabPrc = @PCodTabPrc
             And it.Cod_Produt = @PCodPrd
             And ((cb.Cod_Estabe = @PCodEstabe) or (cb.Flg_AllEstabe = 1)))
  begin
    Select @PPrcTab = Round(it.Val_PrcVen,@pm_QtdDecPrcItePdv)
	                  --Case
                      --  When IsNull(cb.Flg_IniDsc,0) = 1 then Round(it.Val_PrcVen,@pm_QtdDecPrcItePdv)
                      --  Else Round(it.Val_PrcVen*(1-IsNull(it.Per_DscMax,0)/100),@pm_QtdDecPrcItePdv)
                      --End
      From TPXPR it 
           Inner Join TBPRC cb on (it.Cod_Estabe = cb.Cod_Estabe and it.Cod_TabPrc = cb.Cod_TabPrc)
     Where it.Cod_TabPrc = @PCodTabPrc
       And it.Cod_Produt = @PCodPrd
       And ((cb.Cod_Estabe = @PCodEstabe) or (cb.Flg_AllEstabe = 1))
  end

-- e preço da politica ?????

-- desconto automatico, somente se nao for preço de tabela de preços
if @PPrcTab = 0   
  begin
    if @pc_PerAcrAutPrc > 0 
      Set @PPrcTab = @pr_PrcVen*(1-@pr_PerDscAut/100)*(1+@pc_PerAcrAutPrc/100)
    else
    if @pc_PerDscAutPrc > 0 
      Set @PPrcTab = @pr_PrcVen*(1-@pr_PerDscAut/100)*(1-@pc_PerDscAutPrc/100)
    else
      Set @PPrcTab = @pr_PrcVen*(1-@pr_PerDscAut/100)  
  end

Set @PPrcTab = Round(@PPrcTab,@pm_QtdDecPrcItePdv) 

-- Retorna o resultado da function
RETURN @PPrcTab

END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_InfoDefaultPDVIT]
@PFlgPolCom bit,           -- indica se utiliza politica de comercialização
@PCodEstabe int,           -- estabelecimento
@PNumPdv int,              -- numero pedido
@PCodPrd int,              -- produto
@PQtdPed int,              -- qtd pedido
@PQtdBon int,              -- qtd bonificacao
@PIdPolComIte int output,  -- politica de comercializaçãodo item : passa também parametro
@PFlgBlqDscAutIte bit,     -- bloqueia desconto automatico (Layout PDE)  -- TBLPG.Flg_BlqDscAutIte
-------------------------------------------------------------------------------------------------------
@PFlgAchou bit output,
@PLocFis varchar(15) output,                  -- somente registra
@PCodFab int output,                          -- somente registra 
@PPrcFab numeric(18,8) output,                -- somente registra
@PPrcMaxCon numeric(18,8) output,             -- somente registra
@PPrcRefFpb numeric(18,8) output,             -- somente registra
@PPrcTab numeric(18,8) output,
@PPrcTabBru numeric(18,8) output,             -- somente registra

@PFatCnvImpFat smallint output,               -- somente registra
@PPrcUni numeric(18,8) output,

@PPrcCusMinComMarkup numeric(18,8) output,    -- usado somene na critica
@PPerDscPolCom numeric(7,4) output,
@PPerDscVisPolCom numeric(7,4) output,
@PPrcPolCom numeric(18,8) output,
@PQtdPrzPolCom int output,
@PFlgGerVrbIte bit output,           -- PDVIT.Flg_Verba: indica se gera verba p/ acumular, não gera e usa verba no pedido
@PFlgPolPrm bit output,
@PCodKitPrm int output,
@PCodPromoc int output,
@PFlgEmbDscPrc bit output,           -- PDVIT.Flg_PrcUniDsc: embute desconto no preço  NPOL (nao politica)  
@PQtdPrzMax int output,              -- PDVIT.Qtd_PrzMax
@PPerDscLin numeric(7,4) output,     -- PDVIT.Per_Desconto: desconto prazo "linear"
@PPerDscPrz numeric(7,4) output,     -- PDVIT.Per_Descon: desconto prazo "fabricante" prazo
@PPerDscVis numeric(7,4) output,     -- PDVIT.Per_DscVis: desconto prazo "fabricante" vista
@PPrcUniLiqPer numeric(18,8) output

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Date smalldatetime

Set @Date = cast(GetDate() as Date)

BEGIN TRANSACTION

  Declare @WFlgBlqDscExt bit = 0,     -- Bloqueia desconto extra
          @WQtdPrzIte int = 0,

          @PFlgPromoc bit,        
          @PDesPromoc varchar(30),
          @PFlgBlqCtrQtdPromoc bit,
          @PQtdEstPromoc int,
          @PQtdMinPromoc int,
          @PDatEncPromoc smalldatetime,   
          @PDatVctLotPromoc smalldatetime,
          @PQtdPrzPromoc int,
          @PPerDscPromoc decimal(7,4),
          @PPerBonPromoc decimal(7,4),
          @PPrcPromoc decimal(18,8)

  Declare @WPerDscMax numeric(7,4),
          @WPerDscAut numeric(7,4),
          @WPrcUni numeric(18,8),
          @WPrcTabAux numeric(18,8),
          @WPerDscPrzIte numeric(7,4),
          @WPerDscVisIte numeric(7,4),
          @WPerDscTabSug numeric(7,4),
          @WTipPrz varchar(1),
          @WPrcUniLiqPromoc numeric(18,8),
          @WPrcUniLiqPolCom numeric(18,8),
          @WPrcUniLiqPdv numeric(18,8),
          @WQtdMaxCfg int

  Declare @pr_PrcVenda numeric(18,8),
          @pr_PrcCustoMedio numeric(18,8),
          @pr_PrcCusMedCom numeric(18,8),
          @pr_PrcCusLiqEnt numeric(18,8),
          @pr_PrcUltEnt numeric(18,8),
          @pr_PerDscUltEnt numeric(7,4),
          @pr_FlgBlqDsc bit,
          @pr_CodCla varchar(7),
          @pr_PerBonAut numeric(7,4),
          @pr_PerDscAut numeric(7,4),
          @pr_PerDscAutOrc numeric(7,4),
          @pr_CodPromoc int,
          @pr_QtdDispon int,
          @pr_QtdPromocDispon int,

          @fb_PerDscMax numeric(7,4),

          @pv_DatPedido smalldatetime,
          @pv_TipPdv varchar(1),  
          @pv_CodOriPdv varchar(2),
          @pv_TipFat varchar(3),   
          @pv_CodCli int, 
          @pv_CodVdr int, 
          @pv_CodOpe int,
          @pv_IdPolCom int,

          @pv_TipRatBon varchar(1),
          @pv_FlgMarkupCusCom bit,
          @pv_CodTabPrc int,   
          @pv_QtdPrzPdv int,
          @pv_PerDscPrzPdv numeric(7,4),
          @pv_PerDscVisPdv numeric(7,4),
          @pv_TipGerVrb varchar(1),
          @pv_FlgMrkCusCom bit, 

          @op_TipPrc varchar(1),
          @op_FlgOrc bit = 0,
          @cl_CodUf varchar(2), 
          @cl_FlgConFin bit,   
          @cl_FlgBlqEmbDscItePrcUni bit,
          @cl_FlgBlqDscPrmExtVenVis bit,

          @pe_CodLayPde int,
          @pe_CodGrpPde int,

          --@pc_FlgBlqVerba bit,

          @pm_QtdDecPrcItePdv smallint,
          @pm_FlgTabPrcConFin bit,
          @pm_FlgEmbDscItePrcUni bit,
          @pm_FlgSugPrmPdv bit,
          @pm_FlgNaoSugDscItePdv bit,
          @pm_PerDscPrmExtVenVis numeric(7,4),
          @pm_FlgCtrDscIte bit,      
          @pm_PerMaxDscIte numeric(7,4)

  Set @PFlgAchou = 0
  Set @PLocFis = ''

  Set @PCodFab = 0
  Set @PQtdPrzMax = 0

  Set @PPrcFab = 0
  Set @PPrcMaxCon = 0
  Set @PPrcRefFpb = 0
  Set @PPrcTab = 0
  Set @PPrcTabBru = 0
  Set @PPrcUni = 0
  Set @PPrcUniLiqPer = 0
  Set @PPrcPolCom = 0
  Set @PPrcCusMinComMarkup = 0
  Set @PFatCnvImpFat = 1

  Set @PPerDscLin = 0
  Set @PPerDscPrz = 0
  Set @PPerDscVis = 0
  Set @PQtdPrzPolCom = 0
  Set @PPerDscPolCom = 0
  Set @PPerDscVisPolCom = 0

  Set @PCodKitPrm = 0
  Set @PCodPromoc = 0
  Set @PFlgGerVrbIte = 0
  Set @PFlgPolPrm = 0
  Set @PFlgPromoc = 0
  Set @PDesPromoc = 0
  Set @PFlgBlqCtrQtdPromoc = 0
  Set @PQtdEstPromoc = 0
  Set @PDatEncPromoc = 0
  Set @PDatVctLotPromoc = 0
  Set @PQtdMinPromoc = 0
  Set @PQtdPrzPromoc = 0
  Set @PPerDscPromoc = 0
  Set @PPerBonPromoc = 0
  Set @PPrcPromoc = 0
  Set @PFlgEmbDscPrc = 0

    -- Status1 = 'P'     -- Pendente
    -- Status2 = 'A','X' -- em aberto 

  if Exists(Select 1 From PDVCB Where Cod_Estabe = @PCodEstabe And Numero = @PNumPdv And ((Status2 = 'A') or (Status2 = 'X'))) and
     Exists(Select 1 From PRXES pr Inner Join PRODU p on pr.Cod_Produt = p.Codigo Where pr.Cod_Estabe = @PCodEstabe And pr.Cod_Produt = @PCodPrd)
    begin
      Select @PFlgAchou       = 1,
	         @PLocFis            = IsNull(d.Cod_LocFis,''),   
	         @pr_CodCla          = IsNull(p.Cod_Classif,''), 
			 @PCodFab            = IsNull(p.Cod_Fabricante,0),   
			 @PPrcFab            = IsNull(pr.Prc_Fabric,0),      
			 @PPrcMaxCon         = IsNull(pr.Prc_MaxCon,0),      
			 @PPrcRefFpb         = IsNull(p.Prc_RefFpb,0),       
			 @pr_PrcVenda        = IsNull(pr.Prc_Venda,0), 
			 @pr_FlgBlqDsc       = IsNull(pr.Flg_BlqDsc,0), 
			 @pr_PerBonAut       = IsNull(pr.Per_BonAut,0), 
			 @pr_PerDscAut       = IsNull(pr.Per_DscAut,0), 
			 @pr_PerDscAutOrc    = IsNull(pr.Per_DscAutOrc,0), 
             @pr_PrcCustoMedio   = IsNull(pr.Prc_CusMed,0),   
			 @pr_PrcCusMedCom    = IsNull(pr.Prc_CusMedCom,0), 
			 @pr_PrcCusLiqEnt    = IsNull(pr.Prc_CusLiqEnt,0), 
			 @pr_PrcUltEnt       = IsNull(pr.Prc_UltEnt,0), 
			 @pr_PerDscUltEnt    = IsNull(pr.Per_DscUltEnt,0),
             @pr_CodPromoc       = IsNull(pr.Cod_Promocao,0),
             @pr_QtdDispon       = dbo.FN_EstoqueDisponivelPrd(pr.Cod_Estabe,pr.Cod_Produt),
             @pr_QtdPromocDispon = IsNull(pr.Qtd_PrmDispon,0),
			 @fb_PerDscMax       = Case 
                                     When IsNull(fb.Per_DscMaxVis,0) > IsNull(fb.Per_DscMaxPrz,0) then IsNull(fb.Per_DscMaxVis,0)
                                     Else IsNull(fb.Per_DscMaxPrz,0) 
                                   End
        From PRXES pr 
             Inner Join PRODU p on pr.Cod_Produt = p.Codigo 
             Left Join FABRI fb on p.Cod_Fabricante = fb.Codigo
             Left Outer Join DPXPR d ON ((pr.Cod_Estabe = d.Cod_Estabe) and (pr.Cod_Produt = d.Cod_Produt) and 
                                          d.Cod_Dep = (Select Min(Cod_Dep) FROM DPXPR 
                                                       Where Cod_Estabe = @PCodEstabe
                                                       And Cod_Produt = pr.Cod_Produt)) 
        Where pr.Cod_Estabe = @PCodEstabe
        And pr.Cod_Produt = @PCodPrd


      -- parametros na memoria
      Select @pm_QtdDecPrcItePdv    = IsNull(QtdDecPrcItePdv,2),
             @pm_FlgTabPrcConFin    = IsNull(FlgTabPrcConFin,0),
             @pm_FlgEmbDscItePrcUni = IsNull(FlgEmbDscItePrcUni,0),
             @pm_FlgSugPrmPdv       = IsNull(FlgSugPrmPdv,0),
             @pm_FlgNaoSugDscItePdv = IsNull(FlgNaoSugDscItePdv,0),
             @pm_PerDscPrmExtVenVis = IsNull(PerDscPrmExtVenVis,0),
             @pm_FlgCtrDscIte       = IsNull(FlgCtrDscIte,0),
             @pm_PerMaxDscIte       = IsNull(PerMaxDscIte,0)
        From PARAM
        Where Cod_Estabe = @PCodEstabe

      -- coloca PDVCB na memoria
      Select @pv_DatPedido    = IsNull(cb.Dat_Pedido,@Date),
	         @pv_TipPdv       = IsNull(cb.Tip_Pedido,''),
             @pv_CodOriPdv    = IsNull(cb.Cod_OrigemPdv,''),
             @pv_TipFat       = IsNull(cb.Tip_Faturamento,''),
             @pv_CodCli       = IsNull(cb.Cod_Cliente,0),
			 @pv_IdPolCom     = IsNull(cb.Id_PolCom,0),

			 @pv_CodVdr       = IsNull(cb.Cod_Vendedor,0),
			 @pv_CodOpe       = IsNull(cb.Cod_VendTlmkt,0),

             @pv_TipRatBon    = IsNull(cb.Tip_RatBon,''),
             @pv_FlgMarkupCusCom = IsNull(cb.Flg_MarkupCusCom,0),
             @pv_CodTabPrc    = IsNull(cb.Cod_TabPrc,0),
--             @pv_QtdPrzPdv    = IsNull(cb.Qtd_Prz,0),
             @pv_QtdPrzPdv    = Cast(IsNull(cb.Qtd_PrzMed,0) as int),
             @pv_PerDscPrzPdv = IsNull(cb.Per_DscPrz,0),
             @pv_PerDscVisPdv = IsNull(cb.Per_DscVis,0),
             @pv_TipGerVrb    = IsNull(cb.Tip_GerVrb,'X'),
             @pv_FlgMrkCusCom = IsNull(cb.Flg_MarkupCusCom,0), 
             @op_TipPrc       = IsNull(op.Tip_Prc,''),
             @op_FlgOrc       = Case
                                  When IsNull(op.Cod_CfoNorInt,0) = 0 then 1
                                  Else 0
                                End,
             @cl_CodUf        = IsNull(cl.Cod_Estado,''),
             @cl_FlgConFin    = Case When (IsNull(cl.Tipo_Consumidor,'') = 'F') and (@pm_FlgTabPrcConFin = 1) then 1 Else 0 End,
             @cl_FlgBlqEmbDscItePrcUni = IsNull(en.Flg_BlqEmbDscItePrcUni,0),
             @cl_FlgBlqDscPrmExtVenVis = IsNull(Flg_BlqDscPrmExtVenVis,0),

             @pe_CodLayPde = IsNull(pe.Cod_Layout,0),
             @pe_CodGrpPde = IsNull(pe.Cod_GrpClp,0)

        From PDVCB cb
             Left Join TPOPE op on cb.Tip_Faturamento = op.Cod_Ope
             Left Join CLIEN cl on cb.Cod_Cliente = cl.Codigo
             Left Join ENXES en on cb.Cod_Estabe = en.Cod_Estabe and cl.Cgc_Cpf = en.Num_CgcCpf and cl.Codigo = en.Cod_Client
             Outer Apply (Select top 1 p.Cod_Layout, p.Cod_GrpClp 
                            From PDECB p 
                           Where p.Cod_Estabe = cb.Cod_Estabe
                             And p.Num_PedVen = cb.Numero
                           Order by p.Isn_Arquiv desc) pe
        Where cb.Cod_Estabe = @PCodEstabe
        And cb.NUmero = @PNumPdv


      -- guarda o tipo de prazo: (F)abricante, (L)inear
      Set @WTipPrz = Substring(@pv_CodOriPdv,2,1)            
      if Ltrim(Rtrim(@WTipPrz)) = '' Set @WTipPrz = 'L'      

      -- embute desconto no preço
      if (@pm_FlgEmbDscItePrcUni = 1) and (@cl_FlgBlqEmbDscItePrcUni = 0)  
        Set @PFlgEmbDscPrc = 1 

      Set @WFlgBlqDscExt = 0  --@cl_FlgBlqDscPrmExtVenVis
      Set @WPrcUniLiqPromoc = 0
      Set @WPrcUniLiqPolCom = 0

      -- pr.bruto
      Set @PPrcTabBru = @pr_PrcVenda    

      -- desconto automatico do produto (p/ preco do cadastro)
      Set @WPerDscAut = 0
      if @pr_PerBonAut = 0
        if Upper(LTrim(RTrim(@pv_TipFat))) = 'ORC'
          Set @WPerDscAut = @pr_PerDscAutOrc
        else
          Set @WPerDscAut = @pr_PerDscAut
      if IsNull(@PFlgBlqDscAutIte,0) = 1   -- PARAM ????
        Set @WPerDscAut = 0


      -- inicializa
      --Set @pc_FlgBlqVerba  = 0
      Set @PPrcCusMinComMarkup = 0

-------------------------------------------------------------------------------------------------------------------------
      if @PFlgPolCom = 1
        begin
          if @PIdPolComIte = 0 
            Set @PIdPolComIte = dbo.FN_SugerePoliticaProduto(Substring(@pv_CodOriPdv,1,1),
                                                             @PCodEstabe,
                                                             @pv_CodCli, @pv_CodVdr, @pv_CodOpe,
                                                             @pv_IdPolCom, @PCodPrd, @PQtdPed,
                                                             @pe_CodLayPde, @pe_CodGrpPde)

          -- nem sempre a politica do cabeçalho atende ao item
          if (@PIdPolComIte = 0) and
             (dbo.FN_PoliticaProdutoValida(@PCodEstabe, Substring(@pv_CodOriPdv,1,1), @pv_IdPolCom, @PCodPrd) = 1)		   
		    Set @PIdPolComIte = @pv_IdPolCom 

          --Set @pv_CodTabPrc = IsNull((Select Cod_TabPrc From POCOM Where Id_PolCom = @PIdPolComIte),0)

          if Exists(Select 1 From POCOM Where Id_PolCom = @PIdPolComIte)
            begin
             -- Select @pc_FlgBlqVerba = Case 
             --                            When (IsNull(pc.Flg_AcuVrbPos,0) = 0) and (IsNull(pc.Flg_AcuVrbNeg,0) = 0) then 1 
             --                            Else 0 
             --                          End,
              Select @PFlgGerVrbIte = Case 
                                       When (IsNull(pc.Flg_NegDsc,0) = 1) and (IsNull(pc.Flg_GerVrbPdv,0) = 0) and    -- negocia desconto e não gera e usa verba exclusivamente no pedido
                                            ((IsNull(pc.Flg_AcuVrbPos,0) = 1) or (IsNull(pc.Flg_AcuVrbNeg,0) = 1)) then 1 
                                       Else 0 
                                     End,
                     --@pc_FlgBlqVerba  = IsNull(pc.Flg_BlqVerba,0),
                     @PFlgPolPrm = IsNull(pc.Flg_BlqCli,0), 
                     @PPrcCusMinComMarkup = Case
                                              When (@pv_TipGerVrb <> 'P') and 
                                                   ( (IsNull(pc.Flg_MarkupCusCom,0) = 1) or (@pv_TipRatBon <> '') ) then dbo.FN_PrcMinCom(@PCodEstabe,@PCodPrd)
                                              Else 0
                                            End
                From POCOM pc 
               Where pc.Id_PolCom = @PIdPolComIte
       
            end  -- if Exists(Select 1 From POCOM Where Id_PolCom = @PIdPolComIte)
       
        end  -- if @PFlgPolCom = 1
-------------------------------------------------------------------------------------------------------------------------

      -- Pr. Tabela
      Set @PPrcTab = dbo.FN_PrecoTabelaProduto(@pv_CodCli, @PCodEstabe, @PCodPrd, @PIdPolComIte, @pv_CodTabPrc, @op_FlgOrc, @PFlgBlqDscAutIte)

      Set @PFatCnvImpFat = 1    
      Set @WPerDscMax = 0   -- desconto maximo permitido (para calculo Pr.Permitido) 
      Set @WPerDscTabSug = 0                                        

      Set @WPrcUni = @PPrcTab   -- aquix ?????  o preço de tabela pode estar com desconto embutido (TPXPR)
      Set @WPrcUniLiqPdv = 0          

      -- preço unitario
      if @cl_FlgConFin = 0 
        begin
          --if @PFlgPrcDif = 1
          --Set @WPrcUni = @PPrcTab
          --Set @WPrcUni = ProduCds.FieldByName('H_PrcVen').AsFloat
          --else             
          if @op_TipPrc = 'V' 
            begin
              Set @WPrcUni = @PPrcTab
            end
          else
          if @op_TipPrc = 'M'
            begin
              if @pr_PrcCusMedCom > 0 
                Set @WPrcUni = @pr_PrcCusMedCom  -- custo medio comercial
              else
                Set @WPrcUni = @pr_PrcCustoMedio
              Set @WPerDscMax = 0
            end
          else
          if @op_TipPrc = 'C'
            begin
              Set @WPrcUni = @pr_PrcCusLiqEnt
              Set @WPerDscMax = 0
             end
          else
          if @op_TipPrc = 'E'
            begin
              Set @WPrcUni = @pr_PrcUltEnt*(1-@pr_PerDscUltEnt/100)
              Set @WPerDscMax = 0
             end
        end
      else
        begin
          Set @WPrcUni = @PPrcTab
          Set @WPerDscMax = 0
        end
   
-------------------------------------------------------------------------------------------------------------------------
      if @PFlgPolCom = 0
        begin
          Set @PIdPolComIte = 0  

          -- promocao
          Exec PR_ProdutoEmPromocao @PCodEstabe, @pr_CodPromoc, @PCodPrd, @cl_CodUf,
                                    @PFlgPromoc output, @PDesPromoc output, @PDatEncPromoc output, @PDatVctLotPromoc output, @PQtdMinPromoc output,
                                    @PQtdPrzPromoc output, @PPerDscPromoc output, @PPerBonPromoc output, @PPrcPromoc output, @PFlgBlqCtrQtdPromoc output
          if @PFlgPromoc = 1
            begin
              if @PFlgBlqCtrQtdPromoc = 1
                Set @PQtdEstPromoc = @pr_QtdDispon
              else
                Set @PQtdEstPromoc = @pr_QtdPromocDispon
            end

          Set @WQtdPrzIte = @pv_QtdPrzPdv  

          if @WTipPrz = 'L'     -- prazo linear
            begin
              -- politica de comercializacao = 0
              Set @PQtdPrzMax = 0     --@pv_QtdPrzPdv ????
              Set @PPerDscPrz = 0
              Set @PPerDscVis = 0
        
              if @op_TipPrc = 'V' 
                begin
                  if @fb_PerDscMax > @WPerDscMax
                    Set @WPerDscMax = @fb_PerDscMax
                  if @pm_FlgCtrDscIte = 0
                    if @pm_PerMaxDscIte = 0 
                      Set @WPerDscMax = 99
                   else
                      if @pm_PerMaxDscIte > @WPerDscMax
                        Set @WPerDscMax = @pm_PerMaxDscIte
                 
                  -- sugere promocao automatica
                  if (@pm_FlgSugPrmPdv = 1) and
                     (@PFlgPromoc = 1) and (@op_TipPrc = 'V') and (@PQtdEstPromoc > 0) and
                     ((@pr_QtdPromocDispon > 0) or (@PFlgBlqCtrQtdPromoc = 1)) and
                     (@pr_FlgBlqDsc = 0) 
                    begin
                      if @PPerDscPromoc > 0
                        Set @PPerDscLin = @PPerDscPromoc
                      else
                      if @PPrcPromoc > 0 
                        Set @WPrcUni = @PPrcPromoc
                    end
                  else
                    begin
                      Set @WPerDscTabSug = 0

                      if (@pv_CodTabPrc > 0) and            
                         Exists(Select 1 From TPXPR it 
                                              Inner Join TBPRC cb on it.Cod_Estabe = cb.Cod_Estabe and it.Cod_TabPrc = cb.Cod_TabPrc 
                                 Where it.Cod_TabPrc = @pv_CodTabPrc
                                   And it.Cod_Produt = @PCodPrd
                                   And ((cb.Cod_Estabe = @PCodEstabe) or (cb.Flg_AllEstabe = 1)))
                        begin
                          Select @WPerDscTabSug = Case 
                                                    When IsNull(cb.Flg_IniDsc,0) = 1 then IsNull(it.Per_DscMax,0)
                                                    Else 0
                                                  End
                            From TPXPR it 
                                 Inner Join TBPRC cb on it.Cod_Estabe = cb.Cod_Estabe and it.Cod_TabPrc = cb.Cod_TabPrc 
                           Where it.Cod_TabPrc = @pv_CodTabPrc
                             And it.Cod_Produt = @PCodPrd
                             And ((cb.Cod_Estabe = @PCodEstabe) or (cb.Flg_AllEstabe = 1))
                        end
                      
                       -- sugere desconto da tabela de preços
                      if (@WPerDscTabSug > 0) and (@pr_FlgBlqDsc = 0) 
                        Set @PPerDscLin = @WPerDscTabSug
                    end
                 
                end  -- if @op_TipPrc = 'V'
        
              -- calcula @WPrcUniLiqPdv
              Set @WPrcUni = Round(@WPrcUni,@pm_QtdDecPrcItePdv)
              Set @WPrcUniLiqPdv = @WPrcUni*(1-@PPerDscLin/100)
        
            end -- if @WTipPrz = 'L'
          else
            begin  -- if @WTipPrz = 'F': prazo fabricante - quando alterar aqui ver rotina de reprocessamento de comercializacao de itens
              Set @PPerDscLin = 0

              if @op_TipPrc = 'V' 
                begin
                  -- cond. comercializacao padrao
                  Exec PR_PdvitConComDef @PCodEstabe, @PCodPrd, @pv_CodCli, @pv_QtdPrzPdv, @pv_PerDscPrzPdv, @pv_PerDscVisPdv,
                                          @WQtdPrzIte output, @WPerDscPrzIte output, @WPerDscVisIte output
                
                  Set @PQtdPrzMax = @WQtdPrzIte
                  Set @PPerDscPrz = @WPerDscPrzIte
                  Set @PPerDscVis = @WPerDscVisIte
                
                  -- sugere promocao automatica
                  if (@pm_FlgSugPrmPdv = 1) and
                     (@PFlgPromoc = 1) and (@op_TipPrc = 'V') and
                     ((@pr_QtdPromocDispon > 0) or (@PFlgBlqCtrQtdPromoc = 1)) and
                     (@pr_FlgBlqDsc = 0) 
                    begin
                      if @PQtdPrzPromoc > 0 
                        Set @PQtdPrzMax = @PQtdPrzPromoc
                      if @PPerDscPromoc > 0
                        begin
                          Set @PPerDscPrz = @PPerDscPromoc
                          Set @PPerDscVis = @PPerDscPromoc
                          -- desconto adicional em venda a vista se configurado nas opcoes do sistema
                          -- se existir uma condicao pre-existente na venda a vista
                          if (@pm_PerDscPrmExtVenVis > 0) and
                             (@WPerDscVisIte > 0) and (@WFlgBlqDscExt = 0) 
                            -- (D1+D2) - (D1*D2)/100
                          Set @PPerDscVis = Round((@PPerDscPromoc+@pm_PerDscPrmExtVenVis) - (@PPerDscPromoc*@pm_PerDscPrmExtVenVis)/100,2)
                        end
                      else
                      if @PPrcPromoc > 0 
                        begin
                          Set @WPrcUni = @PPrcPromoc
                
                          Set @PPerDscPrz = 0
                          Set @PPerDscVis = 0
                          -- desconto adicional em venda a vista se configurado nas opcoes do sistema
                          -- se existir uma condicao pre-existente na venda a vista
                          if (@pm_PerDscPrmExtVenVis > 0) and
                             (@WPerDscVisIte > 0) and (@WFlgBlqDscExt = 0) 
                            Set @PPerDscVis = Round(@pm_PerDscPrmExtVenVis,2)
                        end
                
                    end  -- if (@pm_FlgSugPrmPdv = 1) and

                end  -- if @op_TipPrc = 'V'

              -- calcula @WPrcUniLiqPdv
              Set @WPrcUni = Round(@WPrcUni,@pm_QtdDecPrcItePdv)
              Set @WPrcUniLiqPdv = @WPrcUni*(1-@PPerDscPrz/100)

            end  -- if @WTipPrz = 'F'     -- prazo fabricante

          -- calcula preco progressivo
          --CalculaPrcUnitarioPdvit(PIteDts,PPsqDts,@pv_TipFat,@op_TipPrc,PEstCli,@pv_CodTabPrc,
          --                         @WQtdPrzIte, @WQtdPrzIte,PdvcbCds.FieldByName('Flg_TabProgres').AsBoolean,@cl_FlgConFin,PFlgPrcDif,true);

         Set @PPrcUni = @WPrcUni

        end  -- if @PFlgPolCom = 0
------------------------------------------------------------------------------------------------------------------------------------------------

      if @PFlgPolCom = 1
        begin
          -- promocao
          Set @PCodKitPrm = dbo.FN_IdKitPromocao(@PIdPolComIte)

          -- calcula preco progressivo
          --CalculaPrcUnitarioPdvit(PPsqPrd,PPsqDts,PTipFat,PTipPrc,PEstCli,PCodTabPrc,
          --                        PQtdPrzMax,PQtdPrzMax,PdvcbCds.FieldByName('Flg_TabProgres').AsBoolean,false,false,true);

          -- condicoes da politica: define preço unitario/desconto conforme politica de comercializacao
          -- na digitacao do pedido o preço já é sugerido e pode ser alterado
		  -- o parametro em PR_PrcPrdPolitica pede preço de tabela
		  -- @WPrcUni já pode estar com % de desconto automatico do produto e da politica
		  -- @PPrcTab já está com desconto automatico do produto e da politica
          if (@cl_FlgConFin = 0) and (@op_TipPrc <> 'V')
		    Set @WPrcTabAux = @WPrcUni
          else
		    Set @WPrcTabAux = @pr_PrcVenda*(1-@WPerDscAut/100)  -- aqui deve ser preço do produto com seu desconto automatico....
          if @PQtdPed > 0
            Exec PR_PrcPrdPolitica @pv_CodCli, @PCodEstabe, @PCodPrd, @PIdPolComIte, @PQtdPed, @WPrcTabAux, @pv_DatPedido,
                                   @PPrcUni output, @PQtdPrzMax output, @PPerDscPrz output, @PPerDscVis output, @WQtdMaxCfg output

          -- calcula @WPrcUniLiqPdv
          if @PPrcUni = 0
            Set @PPrcUni = @WPrcUni
          Set @PPrcUni = Round(@PPrcUni,@pm_QtdDecPrcItePdv)
          Set @WPrcUniLiqPdv = @PPrcUni*(1-@PPerDscPrz/100)

--          if IsNull(@pc_FlgBlqVerba,0) = 0
--            Set @PFlgVerba = 1
--          else
--            Set @PFlgVerba = 0

          Set @PQtdPrzPolCom = IsNull(@PQtdPrzMax,0)
--          Set @PPrcPolCom = IsNull(@WPrcUni,0)  alterado em 23/07/2020
          Set @PPrcPolCom = IsNull(@PPrcUni,0)
          Set @PPerDscPolCom = IsNull(@PPerDscPrz,0)
          Set @PPerDscVisPolCom = IsNull(@PPerDscVis,0)
          if @pv_TipPdv = 'C'
            Set @PPerDscLin = IsNull(@PPerDscPrz,0)

          if @PPerDscVisPolCom < @PPerDscPolCom
            Set @PPerDscVisPolCom = @PPerDscPolCom

        end  -- if @PFlgPolCom = 1

      -- produto bloqueado para descontos
      if (@pr_FlgBlqDsc = 1) or (@pm_FlgNaoSugDscItePdv = 1) 
        begin
          Set @PPerDscLin    = 0     
          Set @PPerDscPrz    = 0     
          Set @PPerDscVis    = 0     

          --if @pv_FlgMrkCusCom = 0
          Set @PFlgGerVrbIte  = 0

          Set @PPrcPolCom    = 0
          Set @PPerDscPolCom = 0
          Set @PPerDscVisPolCom = 0
        end

      -- desconto a vista nao pode ser menor que desc. a prazo
      if @PPerDscVis < @PPerDscPrz      
        Set @PPerDscVis = @PPerDscPrz

      -- desconto maximo
      if @WPerDscTabSug > @WPerDscMax
        Set @WPerDscMax = @WPerDscTabSug

	  if @PPerDscLin > @WPerDscMax
        Set @WPerDscMax = @PPerDscLin
      if @PPerDscVis > @WPerDscMax
        Set @WPerDscMax = @PPerDscVis

      if @PPerDscPromoc > @WPerDscMax
        Set @WPerDscMax = @PPerDscPromoc

      -- preco minimo permitido ------
	  if (@PPrcUni > 0) and (@PPrcUni < @WPrcUni)
        Set @WPrcUni = @PPrcUni

      Set @PPrcUniLiqPer = @WPrcUni*(1-@WPerDscMax/100)

      -- calcula preco minimo politica liquido
      Set @WPrcUniLiqPolCom = @PPrcPolCom*(1-@PPerDscVisPolCom/100)
      if (@WPrcUniLiqPolCom > 0) and (@WPrcUniLiqPolCom < @PPrcUniLiqPer)
        Set @PPrcUniLiqPer = @WPrcUniLiqPolCom

      -- calcula preco minimo promocional liquido
      Set @WPrcUniLiqPromoc = @PPrcPromoc*(1-@PPerDscPromoc/100)
      if (@WPrcUniLiqPromoc > 0) and (@WPrcUniLiqPromoc < @PPrcUniLiqPer)
        Set @PPrcUniLiqPer = @WPrcUniLiqPromoc

      -- verifica se venda foi da promocao
      Set @PCodPromoc = 0
      if @PFlgPromoc = 1
        Set @PCodPromoc = @pr_CodPromoc  
/*
      if @PFlgPromoc = 1
        begin
          if @PQtdBon > 0 
            Set @PCodPromoc = @pr_CodPromoc  
          else
          if @WPrcUniLiqPromoc > 0 
            if (Round(@WPrcUniLiqPdv,4) >= Round(@WPrcUniLiqPromoc,4)) and
               (Round(@WPrcUniLiqPdv,4) < Round(@PPrcTab,4)) and
               (Round(@WPrcUniLiqPdv,4) <= Round(@PPrcUniLiqPer,4)) 
              Set @PCodPromoc = @pr_CodPromoc
        end
*/

    end   -- if @PCodPrd > 0

COMMIT TRANSACTION
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CalculaVencPDV]
@CodEstabe int,
@CodPed int

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = cast(GetDate() as date)

-- normaliza campos 
if (Select IsNull(op.Flg_LanFin,0)
      From PDVCB pv 
           Inner Join TPOPE op on (pv.Tip_Faturamento = op.Cod_Ope)
     Where pv.Cod_Estabe = @CodEstabe 
       And pv.Numero = @CodPed) = 0
  begin    
    Update PDVCB
       Set Tip_Vencimento = 'A'
     Where Cod_Estabe = @CodEstabe
       And Numero = @CodPed
    
    Delete From PDVDP
     Where Cod_Estabe = @CodEstabe
       And Cod_Pedido = @CodPed  
  end

Update PDVCB
   Set Flg_CnvDscIteDscGlb = Case
                               When Id_PolCom > 0 then 0
                               Else (Select IsNull(FlgCnvDscIteDscCom,0) From PARAM Where Cod_Estabe = @CodEstabe)  
                             End,
       Tip_DscPdv = Case 
	                  When Id_PolCom > 0 then 'C'
	 				 Else Tip_DscPdv
                    End
 Where Cod_Estabe = @CodEstabe
  And Numero = @CodPed

--Update PDVCB  
--  Set Flg_CnvDscIteDscGlb = (Select IsNull(FlgCnvDscIteDscCom,0) From PARAM Where Cod_Estabe = @CodEstabe)  
--Where Cod_Estabe = @CodEstabe
--And Numero = @CodPed  

Update PDVCB  
   Set Flg_CnvDscIteDscGlb = 1
 Where Cod_Estabe = @CodEstabe
   And Numero = @CodPed  
   And Tip_DscPdv = 'F'
   And IsNull(Flg_CnvDscIteDscGlb,0) = 0


Delete From PDVIT 
 Where Cod_Estabe = @CodEstabe 
   And Cod_Pedido = @CodPed 
   And Qtd_Pedido > 0 
   And Prc_Unitario = 0.00


-- valida tabela de prazos se for o caso
if ((Select Tip_Vencimento From PDVCB Where Cod_Estabe = @CodEstabe And Numero = @CodPed) = 'T') and
   (not Exists(Select pz.Cod_Prz 
                 From PRZCB pz Inner Join PDVCB cb on cb.Cod_Prz = pz.Cod_Prz 
                Where cb.Cod_Estabe = @CodEstabe
                  And cb.Numero = @CodPed
                  And pz.Qtd_PrzMed > 0))
  begin
    RAISERROR('Tabela de prazos inválida',16,1)
	Return
  end
else
BEGIN
Begin Transaction

-- bloqueia pedido
Update PDVCB
   Set Qtd_Itens = Qtd_Itens + 0,
       Flg_Calc = 1
 Where Cod_Estabe = @CodEstabe
   And Numero = @CodPed

if (Select IsNull(C_VlrPedido,0) From PDVCB Where Cod_Estabe = @CodEstabe And Numero = @CodPed) = 0
  Update PDVCB
     Set Vlr_Despes = Vlr_Despes + 0
   Where Cod_Estabe = @CodEstabe
     And Numero = @CodPed

-- variaveis de trabalho
Declare @WtipPrz varchar(1),
        @WValDup numeric(18,4),
        @WValSubTri numeric(18,4),
        @WValSbtRes numeric(18,4),
        @WValBasPed numeric(18,4),
        @WValAcc numeric(18,4),
        @WFlgApr bit,
        @WRecalcula bit,
        @WDatVct smalldatetime,
        @WDatVctAnt smalldatetime,
        @WQtdPrzAnt int,

        @cl_DiaSemVctTit tinyint,
        @cl_FlgBlqDupExtSbt bit,
        @cl_FlgBlqIncImpPriDup bit,

        @ag_VlrDspBolBan numeric(18,4),
        @ag_PerTaxAdm numeric(18,4),
        @ag_CodAplTaxAdm varchar(1),

        @cr_CodPrd int,
        @cr_CodLot varchar(20),
        @cr_TipSai varchar(1),
        @cr_CVlrLiq numeric(18,4),
        @cr_CPrcTot numeric(18,4),
        @cr_PerDscVis numeric(18,4),
        @cr_QtdPrzMax int,
        @cr_PerDscPrz numeric(18,4),
        @cr_FlgBlqDsc bit, 

        @cr_QtdPrz int,
        @cr_VlrItens numeric(18,4),
        @cr_VlrDscFin numeric(18,4),
        @cr_VlrDscCom numeric(18,4),

        @WSomat numeric(18,4),
        @WValLiqAcc numeric(18,4),
        @WValBruAcc numeric(18,4),
        @WValDscAcc numeric(18,4),
        @WValIte numeric(18,4),
        @WValBru numeric(18,4),
        @WValDscFin numeric(18,4),
        @WValDscCom numeric(18,4),
        @WValTotLiq numeric(18,4),
        @WValDespes numeric(18,4),
        @WValTotDspBolBan  numeric(18,4),
        @WQtdPrz int,
        @WPerDsc numeric(18,4),
        @WConPar tinyint,
        @WFlgIncDupSbt bit    -- indica se cria nova parcela p/ sbt

-- variaveis que serao gravadas em PDVCB
Declare @PQtdPar int,
        @PQtdInt int,
        @PQtdPrzMed numeric(18,4),
        @PFlgVlrFin bit ,
        @PPerDscCom numeric(18,4),
        @PPerDscFin numeric(18,4),
        @PTipDsc varchar(1),
		@PPerDscComMemo numeric(18,4)

-- variaveis para guardar campos de tabelas
Declare @cb_TipVct varchar(1),
        @cb_IdPolCom int,
        @cb_VlrLiqIte numeric(18,4),
        @cb_VlrRepIcm numeric(18,4),
        @cb_VlrSubTri numeric(18,4),
        @cb_VlrSbtRes numeric(18,4),
        @cb_VlrDespes numeric(18,4),
        @cb_VlrDscTri numeric(18,4),
        @cb_BasDscCom numeric(18,4),
        @cb_CVlrPed numeric(18,4),
        @cb_DatPed smalldatetime,
        @cb_CodPrz int,
        @cb_FlgCnvDscIteDscGlb bit,
        @op_FlgLanFin bit,
        @op_VlrMinDup numeric(18,4),
        @pm_FlgDebBlqBanVrbVdr bit,
        @pm_FlgImpPriDup bit,
        @pm_QtdPrzMaxImpSbt int,
        @pm_QtdDiaDupVis int,
        @pm_QtdDiaPrgDupApr int

Select @WTipPrz = Substring(cb.Cod_OrigemPdv,2,1),
       @cb_CVlrPed = Round(IsNull(cb.C_VlrPedido,0),2),
       @cb_TipVct = cb.Tip_Vencimento,
       @cb_IdPolCom = IsNull(cb.Id_PolCom,0),
       @cb_VlrLiqIte = IsNull(cb.Vlr_LiqItens,0),
       @cb_VlrRepIcm = IsNull(cb.Vlr_RepIcms,0),
       @cb_VlrSubTri = Round(IsNull(cb.Vlr_SubsTrib,0),2),
       @cb_VlrSbtRes = Round(IsNull(cb.Vlr_SbtRes,0),2),
       @cb_VlrDespes = IsNull(cb.Vlr_Despes,0),
       @cb_VlrDscTri = IsNull(cb.Vlr_DscTri,0),
       @cb_BasDscCom = IsNull(cb.Vlr_BasDscCom,0),
       @cb_DatPed = cb.Dat_Pedido,
       @cb_CodPrz = IsNull(cb.Cod_Prz,0),
       @cb_FlgCnvDscIteDscGlb = IsNull(Flg_CnvDscIteDscGlb,0),

       @PPerDscCom = isnull(cb.Per_DescontoCom,0),
       @PPerDscFin = isnull(cb.Per_DescontoFin,0),
       @PQtdPar = IsNull(cb.Qtd_Parcela,0),
       @PQtdInt = IsNull(cb.Qtd_Intervalo,0),
       @PQtdPrzMed = IsNull(cb.Qtd_PrzMed,0),
       @PTipDsc = cb.Tip_DscPdv,

       @cl_DiaSemVctTit = IsNull(cl.Dia_SemVctTitEsp,0),
       @cl_FlgBlqDupExtSbt = IsNull(cl.Flg_BlqDupExtSbt,0),
       @cl_FlgBlqIncImpPriDup = IsNull(en.Flg_BlqIncSbtPriDup,0),

       @ag_VlrDspBolBan = case 
                            When (Isnull(ag.Flg_CobDspBolBanNtf,0) = 1) and (Tipo = 'BC') and
                                 (IsNull(cl.Flg_BlqCobTxaBan,0) = 0) then Round(Isnull(ag.Vlr_DspBolBan,0),2)
                            else 0
                          end,
       @ag_PerTaxAdm = IsNull(ag.Per_TaxAdm,0),
       @ag_CodAplTaxAdm = IsNull(Cod_AplTaxAdm,''),

       @op_FlgLanFin = IsNull(Flg_LanFin,0),
       @op_VlrMinDup = IsNull(Vlr_MinDup,0)

  From PDVCB cb 
       Left Join CLIEN cl on cb.Cod_Cliente = cl.Codigo 
       Left Join ENXES en on cb.Cod_Estabe = en.Cod_Estabe and cl.Cgc_Cpf = en.Num_CgcCpf and cl.Codigo = en.Cod_Client
       Left Join AGCOB ag on cb.Cod_Agente = ag.Codigo
       Left Join TPOPE op on cb.Tip_Faturamento = op.Cod_Ope
 Where cb.Cod_Estabe = @CodEstabe
   And cb.Numero = @CodPed

Select @pm_FlgImpPriDup = IsNull(FlgIncImpPriDup,0),
       @pm_QtdPrzMaxImpSbt = Case
                               When (IsNull(FlgIncImpPriDup,0) = 1) and (@cl_FlgBlqDupExtSbt = 0) Then IsNull(QtdPrzMaxImpSbt,0)
                               Else 0
                             End,
       @pm_QtdDiaDupVis = IsNull(QtdDiaDupVis,0),
       @pm_QtdDiaPrgDupApr = Isnull(QtdDiaPrgDupApr,0),
       @pm_FlgDebBlqBanVrbVdr = IsNull(FlgDebBlqBanVrbVdr,0)
  From PARAM
 Where Cod_Estabe = @CodEstabe



if (@PQtdInt = 0) and 
   Exists(Select 1 From PDVDP Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed And Num_SeqPar = 1) and
   Exists(Select 1 From PDVDP Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed And Num_SeqPar = 2) 
  Select @PQtdInt = Cast(((Select Dat_Vencim From PDVDP Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed And Num_SeqPar = 2) -
                          (Select Dat_Vencim From PDVDP Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed And Num_SeqPar = 1)) as int)

if (@PQtdPar = 0) and 
   Exists(Select 1 From PDVDP Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed) 
  Select @PQtdPar = count(*) From PDVDP Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed

/*
  -- calcula despesa ref. taxa administrativa
  Set @WValDespes = 0.00     
  if @ag_PerTaxAdm > 0
    begin
      if @ag_CodAplTaxAdm = 'P' -- margem (participação)
        Set @WValDespes = Round(@cb_VlrLiqIte/(1-@ag_PerTaxAdm/100),2)-Round(@cb_VlrLiqIte,2)
      if @ag_CodAplTaxAdm = 'A'  -- mark-up (acrescimo)
        Set @WValDespes = Round(@cb_VlrLiqIte*@ag_PerTaxAdm/100,2)     
    end

  -- calcula despesa boleto bancario a cobrar na nota fiscal
  Set @WValTotDspBolBan = 0
  if @op_FlgLanFin = 1
    begin
      Set @WValTotDspBolBan = Round(Isnull(@ag_VlrDspBolBan,0) * @PQtdPar,2)
      Set @WValDespes = @WValDespes + @WValTotDspBolBan
    end

  -- debita taxa boleto para vendedor
  if @TipNfs = 'V'
    begin
      -- taxa boleto
      if @pm_FlgDebBlqBanVrbVdr = 1
        begin
          Set @WValDespes = @WValDespes - @WValTotDspBolBan    -- isenta cliente
        end
    end

*/




if (@pm_FlgImpPriDup = 1) and (@cl_FlgBlqIncImpPriDup = 1)
  Set @pm_FlgImpPriDup = 0


-- Manter Desconto Comercial caso tenha algum valor
if @PPerDscCom > 0
  Set  @PPerDscComMemo = @PPerDscCom

-- garante que nao ha desconto financeiro em operacoes que nao geram lancamentos financeiros
if @op_FlgLanFin = 0
  begin
    Set @PPerDscFin = 0
    Set @PTipDsc = 'C' 
  end

-- sinalizador para recalcular o pedido
Set @WRecalcula = 0

-- ver se inclui total imposto na 1a. duplic
Set @WValBasPed = @cb_CVlrPed
if @pm_FlgImpPriDup = 1
  Set @WValBasPed = @WValBasPed - @cb_VlrSubTri - @cb_VlrSbtRes

-- Prazo linear com conversao de desconto item p/ global
if (@WTipPrz = 'L') and (@cb_FlgCnvDscIteDscGlb = 1)  and (@cb_IdPolCom = 0) and
   (Exists(Select 1 From PDVIT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed and Qtd_Pedido > 0 and ((Per_Desconto > 0) or (Per_Descon > 0))))
  begin
    Set @PPerDscCom = 0
    if @cb_IdPolCom = 0
      Set @PPerDscFin = 0
    -- tipo de desconto financeiro ou comercial
    if @PTipDsc <> 'F'
      Set @PTipDsc  = 'C'

  -- zera desc. cabecalho se houve alteracoes devido a calc. anterior
    Update PDVCB
      Set Per_DescontoCom = 0,
          Per_DescontoFin = 0
      Where Cod_Estabe = @CodEstabe
      And Numero = @CodPed

  -- Normaliza descontos nos itens e recalcula tributos
    Update PDVIT
      Set Per_Descon = Per_Desconto,
          Per_Desconto = 0
      Where Cod_Estabe = @CodEstabe
      And Cod_Pedido = @CodPed 
      And Qtd_Pedido > 0
      And Per_Desconto > 0

    Declare PDVIT_Cr Cursor Local Fast_Forward For
      Select Cod_Produto, Cod_Lote, Tip_Sai
        From PDVIT 
        Where Cod_Estabe = @CodEstabe
        And Cod_Pedido = @CodPed 
        And Qtd_Pedido > 0  
        And Per_Descon > 0
        
    Open PDVIT_Cr
    Fetch Next From PDVIT_Cr Into @cr_CodPrd, @cr_CodLot, @cr_TipSai
    While @@FETCH_STATUS = 0
      begin
        EXEC PR_CalcTributPdvit @CodEstabe, @CodPed, @cr_CodPrd, @cr_CodLot, @cr_TipSai
        Fetch Next From PDVIT_Cr Into @cr_CodPrd, @cr_CodLot, @cr_TipSai
      end
    Close PDVIT_Cr
    Deallocate PDVIT_Cr

    Set @WRecalcula = 0

    -- Desconto Financeiro ou comercial
    Set @WValDscAcc = Round((Select sum(Round(C_PrcTotal,2)*Per_Descon/100) From PDVIT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed and Qtd_Pedido > 0 and Per_Descon > 0),2)
    if @WValDscAcc > 0
      begin
        -- tem que recalcular valor do pedido devido a alteracao no desconto
        Set @WRecalcula = 1
        if @PTipDsc = 'F'
          begin
--12/04/2011            Set @WValLiqAcc = (Select sum(Round(C_VlrLiquido,2)) From PDVIT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed and Qtd_Pedido > 0)
            Set @WValLiqAcc = (Select sum(Round(C_PrcTotal,2)) From PDVIT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed and Qtd_Pedido > 0 and Desconto = 0)
            if @cb_IdPolCom = 0
              Set @PPerDscFin = @WValDscAcc * 100 /@WValLiqAcc
          end
        else
          begin
            Set @WValBruAcc = (Select sum(Round(C_PrcTotal,2)) From PDVIT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed and Qtd_Pedido > 0 and Desconto = 0)
            Set @PPerDscCom = @WValDscAcc * 100 /@WValBruAcc
          end
      end
  end    -- Prazo linear com conversao de deconto item p/ global
else
  begin
    Set @WRecalcula = 1   -- recalcula tributos  p/ todas as outras situacoes
    if (@WTipPrz = 'L') and ((@cb_VlrSubTri+@cb_VlrSbtRes) > 0) and (@PPerDscFin > 0)
      begin
        Set @WValDscCom = 0
        if @PPerDscCom > 0
          Set @WValDscCom = Round((@cb_BasDscCom-@cb_VlrRepIcm)*@PPerDscCom/100,2)
        Set @WValTotLiq = @cb_VlrLiqIte - @WValDscCom - @cb_VlrRepIcm - @cb_VlrDscTri
         -- calcula novo desc fin
--12/04/2011        Set @PPerDscFin = Round(@WValTotLiq*@PPerDscFin/(@WValTotLiq+@cb_VlrSubTri+@cb_VlrSbtRes),4)
      end
  end

-- Tipo de prazo F-fabricante
if (@WTipPrz = 'F') or (@cb_IdPolCom > 0)
  begin
    if @cb_TipVct <> 'V'
      Set @PQtdPrzMed = 0
    Set @PFlgVlrFin = 0
    Set @PPerDscCom = 0
    if @cb_IdPolCom = 0
      Set @PPerDscFin = 0

    -- tipo de desconto financeiro ou comercial
    if @PTipDsc = 'F'
      Set @PFlgVlrFin = 1
    else
      begin
        Set @PTipDsc  = 'C'
        Set @PFlgVlrFin = 0
      end

-- PRINT comandos abaixo náo estavam comentados
  -- zera desc. cabecalho se houve alteracoes devido a calc. anterior
--    Update PDVCB
--      Set Per_DescontoCom = 0,
--          Per_DescontoFin = 0
--      Where Cod_Estabe = @CodEstabe
--      And Numero = @CodPed

    -- cria tabela temporaria local
    Create Table #PRZAX
     (Qtd_Prz int not null Primary Key,
      Vlr_Itens numeric(18,4) not null,
      Vlr_DscFin numeric(18,4) not null,
      Vlr_DscCom numeric(18,4) not null)

    -- Normaliza desconto dos itens antes de iniciar os calculos
    Update PDVIT
      Set Per_Desconto = Case
                           When @PTipDsc = 'C' and @cb_FlgCnvDscIteDscGlb = 0 and @cb_TipVct = 'V' then Isnull(Per_DscVis,0)
                           When @PTipDsc = 'C' and @cb_FlgCnvDscIteDscGlb = 0 and @cb_TipVct <> 'V' then Isnull(Per_Descon,0)
                           Else 0
                         End
      Where Cod_Estabe = @CodEstabe
      And Cod_Pedido = @CodPed and Qtd_Pedido > 0

    -- inicializa acumuladores
    Set @WSomat = 0
    Set @WValLiqAcc = 0
    Set @WValBruAcc = 0
    Set @WValDscAcc = 0

    Declare PDVIT_Cr Cursor Local Fast_Forward For
      Select Cod_Produto, Cod_Lote, Tip_Sai, 
	         Case 
			   When @pm_FlgImpPriDup = 1 then C_VlrLiquido-IsNull(Vlr_SubsTrib,0)-IsNull(Vlr_SbtRes,0)
			   Else C_VlrLiquido
             End, 
			 C_PrcTotal, Per_DscVis, Qtd_PrzMax, Per_Descon, Desconto
        From PDVIT 
        Where Cod_Estabe = @CodEstabe
        And Cod_Pedido = @CodPed 
        And Qtd_Pedido > 0
    Open PDVIT_Cr
    Fetch Next From PDVIT_Cr Into @cr_CodPrd, @cr_CodLot, @cr_TipSai, @cr_CVlrLiq, @cr_CPrcTot, @cr_PerDscVis, @cr_QtdPrzMax, @cr_PerDscPrz, @cr_FlgBlqDsc
    While @@FETCH_STATUS = 0
      begin
        -- valor liquido do item (+ imp, - desc...)
        Set @WValIte = Round(@cr_CVlrLiq,2)
        Set @WValBru = Round(@cr_CPrcTot,2)
        if @cb_TipVct = 'V'
          begin
            Set @WQtdPrz = cast(@PQtdPrzMed as int)
            if (@WQtdPrz = 0) or (@WQtdPrz > @pm_QtdDiaDupVis)
              Set @WQtdPrz = @pm_QtdDiaDupVis
            Set @WPerDsc = Isnull(@cr_PerDscVis,0)
           end
        else
           begin
             Set @WQtdPrz = @cr_QtdPrzMax
             Set @WPerDsc = Isnull(@cr_PerDscPrz,0)
           end
        Set @WValDscFin = 0
        Set @WValDscCom = 0

        if (@PTipDsc = 'C' and @cb_FlgCnvDscIteDscGlb = 0) or (@cb_TipVct = 'A')
          Set @WValDscCom = 0
        else
        if @PTipDsc = 'F'
          Set @WValDscFin = @WValBru*@WPerDsc/100
        else
          Set @WValDscCom = @WValBru*@WPerDsc/100

        -- acumular p/ calc. prazo ponderado
        Set @WSomat = @WSomat + (@WValIte *@WQtdPrz)
        Set @WValLiqAcc = @WValLiqAcc + @WValIte
        if IsNull(@cr_FlgBlqDsc,0) = 0
          Set @WValBruAcc = @WValBruAcc + @WValBru
        Set @WValDscAcc = @WValDscAcc + (@WValBru*@WPerDsc/100)

        if Exists(Select Qtd_Prz From #PRZAX Where Qtd_Prz = @WQtdPrz)
          Update #PRZAX
            Set Vlr_Itens = Vlr_Itens + @WValIte,
                Vlr_DscFin = Vlr_DscFin + @WValDscFin,
                Vlr_DscCom = Vlr_DscCom + @WValDscCom
            Where Qtd_Prz = @WQtdPrz
        else
          Insert into #PRZAX Values(@WQtdPrz,@WValIte,@WValDscFin,@WValDscCom)

        Fetch Next From PDVIT_Cr Into @cr_CodPrd, @cr_CodLot, @cr_TipSai, @cr_CVlrLiq, @cr_CPrcTot, @cr_PerDscVis, @cr_QtdPrzMax, @cr_PerDscPrz, @cr_FlgBlqDsc
      end
    Close PDVIT_Cr
    Deallocate PDVIT_Cr

    -- Prazo Medio Ponderado
    if @cb_TipVct = 'A'
      begin
        Set @PQtdPrzMed = 0
        Set @PFlgVlrFin = 0
        Set @PPerDscCom = 0
        if @cb_IdPolCom = 0
          Set @PPerDscFin = 0
        -- recalcula valor do pedido devido a alteracao no desconto
        Set @WRecalcula = 1
      end
    else
      begin
        if @WValLiqAcc > 0
          Set @PQtdPrzMed = Round(@WSomat/@WValLiqAcc,0)

        -- Desconto Financeiro ou comercial
        Set @WValDscAcc = Round(@WValDscAcc,2)
        if (@WValDscAcc > 0) or (@PPerDscComMemo > 0) 
          if (@PTipDsc = 'F') and (@cb_IdPolCom = 0)
--12/04/2011            Set @PPerDscFin = @WValDscAcc * 100 /@WValLiqAcc
            Set @PPerDscFin = @WValDscAcc * 100 /@WValBruAcc
          else
            begin
              if @cb_FlgCnvDscIteDscGlb = 1
                begin
                  Set @PPerDscCom = @WValDscAcc * 100 /@WValBruAcc
                  -- recalcula valor do pedido devido a alteracao no desconto
                  Set @WRecalcula = 1
                end
			  else
			    if @PPerDscComMemo > 0
				  begin
			        Set @PPerDscCom = @PPerDscComMemo
					Set @WRecalcula = 1
				  end
            end

        -- aqui  09/06/2016
		-- desdobra prazos por prazo/fabricante
        if @cb_TipVct = 'D' 
		  begin
            -- cria tabela temporaria local
            Create Table #PRZAX2
             (Qtd_Prz int not null Primary Key,
              Vlr_Itens numeric(18,4) not null,
              Vlr_DscFin numeric(18,4) not null,
              Vlr_DscCom numeric(18,4) not null)

            Declare @WQtdInt int,
                    @WQtdDesdob int,
				    @WValIteDesdob numeric(18,4),
				    @WValDscFinDesdob numeric(18,4),
				    @WValDscComDesdob numeric(18,4),
				    @WValIteAcc  numeric(18,4),
				    @WValDscFinAcc numeric(18,4),
				    @WValDscComAcc numeric(18,4)

            Set @WQtdInt = @PQtdInt

            Declare PRZAX_Cr Cursor Local For
              Select Qtd_Prz, Vlr_Itens, Vlr_DscFin, Vlr_DscCom
                From #PRZAX
             Open PRZAX_Cr
            Fetch Next From PRZAX_Cr Into @cr_QtdPrz, @cr_VlrItens, @cr_VlrDscFin, @cr_VlrDscCom
            While @@FETCH_STATUS = 0
              begin
		        -- define quantidade de desdobramentos por prazo
                Set @WQtdDesdob = @PQtdPar
				if @WQtdDesdob < 1
				  Set @WQtdDesdob = 1      

                -- calcula qtd minima de desdobramentos verificando o valor minimo (pode reduzir a qtd de parcelas)
                if @WQtdDesdob > 0 
			      begin
                    Set @WValIteDesdob = Round(@cr_VlrItens/@WQtdDesdob,2)
                    while (@WValIteDesdob < @op_VlrMinDup) and (@WQtdDesdob > 1)
                      begin
                        Set @WQtdDesdob = @WQtdDesdob - 1
                        Set @WValIteDesdob = Round(@cr_VlrItens/@WQtdDesdob,2)
                      end
                  end

			    while @WQtdDesdob > 1
			      begin
                    -- se parcela for par, intervalo tem que ser par...
                    if (@WQtdDesdob > 1) and (@WQtdDesdob % 2 = 0)
                      if @WQtdInt % 2  <> 0
                        Set @WQtdInt = @WQtdInt + 1

                    -- prazo do 1o. desdobramento
                    Set @WQtdPrzAnt = @cr_QtdPrz - floor((@WQtdDesdob - 1)*@WQtdInt*1.0/2)

	     			if @WQtdPrzAnt >= @pm_QtdDiaDupVis
		    		  break
                    else
                      Set @WQtdDesdob = @WQtdDesdob - 1
			      end  -- while @WQtdDesdob > 1

                if @WQtdDesdob > 1 
                  begin
                    Set @WValIteDesdob = Round(@cr_VlrItens/@WQtdDesdob,2)
                    Set @WValDscFinDesdob = Round(@cr_VlrDscFin/@WQtdDesdob,2)
                    Set @WValDscComDesdob = Round(@cr_VlrDscCom/@WQtdDesdob,2)
			      end
		        else
			      begin
			        Set @WQtdDesdob = 1
					Set @WQtdPrzAnt = @cr_QtdPrz
                    Set @WValIteDesdob = @cr_VlrItens
                    Set @WValDscFinDesdob = @cr_VlrDscFin
                    Set @WValDscComDesdob = @cr_VlrDscCom
			      end

                Set @WConPar = 0
                Set @WValIteAcc = @cr_VlrItens
                Set @WValDscFinAcc = @cr_VlrDscFin
                Set @WValDscComAcc = @cr_VlrDscCom

			    while @WConPar < @WQtdDesdob
			      begin
                    Set @WConPar = @WConPar + 1
    
     	            if @WConPar = @WQtdDesdob
	    			  begin
                        Set @WValIteDesdob = @WValIteAcc
			    		Set @WValDscFinDesdob = @WValDscFinAcc
				    	Set @WValDscComDesdob = @WValDscComAcc
				      end

                    if Exists(Select Qtd_Prz From #PRZAX2 Where Qtd_Prz = @WQtdPrzAnt)
                      Update #PRZAX2
                        Set Vlr_Itens = Vlr_Itens + @WValIteDesdob,
                            Vlr_DscFin = Vlr_DscFin + @WValDscFinDesdob,
                            Vlr_DscCom = Vlr_DscCom + @WValDscComDesdob
                        Where Qtd_Prz = @WQtdPrzAnt
                    else
                      Insert into #PRZAX2 Values(@WQtdPrzAnt,@WValIteDesdob,@WValDscFinDesdob,@WValDscComDesdob)

                    Set @WQtdPrzAnt = @WQtdPrzAnt + @WQtdInt
                    Set @WValIteAcc = @WValIteAcc - @WValIteDesdob
                    Set @WValDscFinAcc = @WValDscFinAcc - @WValDscFinDesdob
                    Set @WValDscComAcc = @WValDscComAcc - @WValDscComDesdob
			      end

                Fetch Next From PRZAX_Cr Into @cr_QtdPrz, @cr_VlrItens, @cr_VlrDscFin, @cr_VlrDscCom
              end
            Close PRZAX_Cr
            Deallocate PRZAX_Cr

			Delete From #PRZAX
			Insert #PRZAX
			  Select * From #PRZAX2
			Delete From #PRZAX2

		  end  -- if @cb_TipVct = 'D' 

      end
  end    -- prazo fabricante         if @WTipPrz = 'F'

-- atualiza PDVCB para recalcular valores calculados
if (@WTipPrz = 'F') or (@cb_IdPolCom > 0)
  Update PDVCB
    Set Qtd_Parcela = @PQtdPar,
        Qtd_Intervalo = @PQtdInt,
        Per_DescontoCom = @PPerDscCom,
        Per_DescontoFin = @PPerDscFin,
        Qtd_PrzMed = @PQtdPrzMed,
        Flg_VlrFinanc = @PFlgVlrFin,
        Tip_DscPdv = @PTipDsc
    Where Cod_Estabe = @CodEstabe
    And Numero = @CodPed
else
  Update PDVCB
    Set Qtd_Parcela = @PQtdPar,
        Qtd_Intervalo = @PQtdInt,
        Per_DescontoCom = @PPerDscCom,
        Per_DescontoFin = @PPerDscFin
    Where Cod_Estabe = @CodEstabe
    And Numero = @CodPed

-- ver se recalcula impostos de itens devido alteracao de desconto no cabecalho
if @WRecalcula = 1
  begin
    Declare PDVIT_Cr Cursor Local Fast_Forward For
      Select Cod_Produto, Cod_Lote, Tip_Sai
        From PDVIT 
        Where Cod_Estabe = @CodEstabe
        And Cod_Pedido = @CodPed 
        And Qtd_Pedido > 0
    Open PDVIT_Cr
    Fetch Next From PDVIT_Cr Into @cr_CodPrd, @cr_CodLot, @cr_TipSai
    While @@FETCH_STATUS = 0
      begin

        EXEC PR_CalcTributPdvit @CodEstabe, @CodPed, @cr_CodPrd, @cr_CodLot, @cr_TipSai

        Fetch Next From PDVIT_Cr Into @cr_CodPrd, @cr_CodLot, @cr_TipSai
      end
    Close PDVIT_Cr
    Deallocate PDVIT_Cr
  end

-- pega valores atualizados do cabecalho
Select @cb_CVlrPed = Round(IsNull(C_VlrPedido,0),2),
       @cb_VlrSubTri = Round(IsNull(Vlr_SubsTrib,0),2),
       @cb_VlrSbtRes = Round(IsNull(Vlr_SbtRes,0),2)
  From PDVCB
  Where Cod_Estabe = @CodEstabe
  And Numero = @CodPed

-- ver se inclui total imposto na 1a. duplic
Set @WValBasPed = @cb_CVlrPed
if @pm_FlgImpPriDup = 1
  Set @WValBasPed = @WValBasPed - @cb_VlrSubTri - @cb_VlrSbtRes

-- se for informado (I) ::DMD-8489
IF ((@cb_TipVct = 'I') AND (@PQtdPar > 0)) BEGIN
    DECLARE @Dat_Vencim datetime 
	DECLARE @Num_SeqPar int
	DECLARE @Vlr_Duplic numeric(18, 4)
    DECLARE @Vlr_TotDifDup numeric(18, 4) = NULL
    DECLARE @Vlr_TotDup	numeric(18, 4)
	DECLARE @Qtd_TotDup int

	SET @WValAcc = @WValBasPed

	-- calcula tudo em uma única operação atómica
	DECLARE PDVDP_cr CURSOR LOCAL FAST_FORWARD FOR
	SELECT 
		Dat_Vencim
		, Num_SeqPar
		, Vlr_Duplic
		, SUM(Vlr_Duplic) OVER (PARTITION BY Cod_Estabe, Cod_Pedido) AS Vlr_TotDup
		, COUNT(*) OVER (PARTITION BY Cod_Estabe, Cod_Pedido) AS Qtd_TotDup
	FROM PDVDP
	WHERE (
	    (Cod_Estabe = @CodEstabe) AND
	    (Cod_Pedido = @CodPed)
	)
	OPEN PDVDP_cr
	FETCH NEXT FROM PDVDP_cr INTO 
	    @Dat_Vencim
		, @Num_SeqPar
		, @Vlr_Duplic
		, @Vlr_TotDup
		, @Qtd_TotDup

	WHILE (@@FETCH_STATUS = 0) BEGIN
	    IF (@Vlr_TotDifDup IS NULL)
		    SET @Vlr_TotDifDup = @WValBasPed - @Vlr_TotDup

		IF (ABS(@Vlr_TotDifDup) > 0) BEGIN
			DECLARE @Per_Duplic numeric(18,4) = @Vlr_Duplic * 100 / @Vlr_TotDup
			DECLARE @Vlr_DifDup numeric(18,4) = ROUND(@Per_Duplic * @Vlr_TotDifDup / 100, 2)
			DECLARE @Vlr_DupNew numeric(18,4) = @Vlr_Duplic + @Vlr_DifDup

			-- resíduo vai para última parcela
			IF (@Num_SeqPar = @Qtd_TotDup)
			    SET @Vlr_DupNew = ROUND(@WValAcc, 2)

			UPDATE PDVDP SET Vlr_Duplic = @Vlr_DupNew
			WHERE (
				(Cod_Estabe = @CodEstabe) AND
				(Cod_Pedido = @CodPed) AND
				(Num_SeqPar = @Num_SeqPar)
			)

		    SET @WValAcc = @WValAcc - @Vlr_DupNew
		END

        FETCH NEXT FROM PDVDP_cr INTO 
			@Dat_Vencim
			, @Num_SeqPar
			, @Vlr_Duplic
			, @Vlr_TotDup
			, @Qtd_TotDup
	END  
-- se nao utiliza tabela de prazos
END else if @cb_TipVct <> 'T'
  begin         
    -- CALCULA VENCIMENTOS
    -- inicializa campos
    Delete From PDVDP
      Where Cod_Estabe = @CodEstabe
      And Cod_Pedido = @CodPed
    
    Set @WConPar = 0  -- contador de parcelas
    
    -- prazo fabricante nao ponderado
    if ((@WTipPrz = 'F') or (@cb_IdPolCom > 0)) and (@cb_TipVct <> 'P') 
      begin
        if @cb_TipVct = 'A'  -- apresentacao
          begin
            Set @WDatVct = dbo.FN_DataDaSemana(@Date+@pm_QtdDiaPrgDupApr,@cl_DiaSemVctTit)
            if not Exists(Select 1 From PDVDP 
                          Where Cod_Estabe = @CodEstabe
                          And Cod_Pedido = @CodPed 
                          And Dat_Vencim = @WDatVct 
                          And Flg_Apresentacao = 1)
              begin
                Set @WConPar = @WConPar + 1
                Insert Into PDVDP (Cod_Estabe, Cod_Pedido, Dat_Vencim, Num_SeqPar, Vlr_Duplic, Vlr_SbtEmb, Vlr_ResEmb, Flg_DupExt, Flg_Apresentacao)
                           Values (@CodEstabe, @CodPed, @WDatVct, @WConPar, 0, 0, 0, 0, 1)
              end
              
            Update PDVDP
			  Set Vlr_Duplic = Vlr_Duplic + @WValBasPed
            Where Cod_Estabe = @CodEstabe
            And Cod_Pedido = @CodPed 
            And Dat_Vencim = @WDatVct
            And Flg_Apresentacao = 1  
            
          end
        else
          begin
            Declare @WUltPar int 

            Set @WUltPar = (Select count(*) From #PRZAX)

			Set @WValAcc = @WValBasPed

            -- calcula vencimentos
            Declare PRZAX_Cr Cursor Local Fast_Forward For
              Select Qtd_Prz, Vlr_Itens, Vlr_DscFin, Vlr_DscCom
                From #PRZAX
            Open PRZAX_Cr
            Fetch Next From PRZAX_Cr Into @cr_QtdPrz, @cr_VlrItens, @cr_VlrDscFin, @cr_VlrDscCom
            While @@FETCH_STATUS = 0
              begin
                Set @WConPar = @WConPar + 1
        
                if @WConPar = @WUltPar
                  Set @WValDup = Round(@WValAcc,2)
                else
                  Set @WValDup = Round(@cr_VlrItens-@cr_VlrDscCom,2)
                      
                Set @WValDscFin = 0
                if @PTipDsc = 'F'
                  Set @WValDscFin = Round(@cr_VlrDscFin,4)
                   
                Set @WDatVct = dbo.FN_DataDaSemana(@cb_DatPed+@cr_QtdPrz,@cl_DiaSemVctTit)

                Insert Into PDVDP (Cod_Estabe, Cod_Pedido, Dat_Vencim, Num_SeqPar, Vlr_Duplic, Vlr_SbtEmb, Vlr_ResEmb, Vlr_DescFinanc, Flg_DupExt)
                           Values (@CodEstabe, @CodPed, @WDatVct, @WConPar, @WValDup, 0, 0, @WValDscFin, 0)
                           
                Set @WValAcc = @WValAcc - @WValDup

                 Fetch Next From PRZAX_Cr Into @cr_QtdPrz, @cr_VlrItens, @cr_VlrDscFin, @cr_VlrDscCom
              end
            Close PRZAX_Cr
            Deallocate PRZAX_Cr

            -- garante pelo menos uma duplicata
            if @WConPar = 0
              begin
                Set @WConPar = @WConPar + 1
                Set @WDatVct = dbo.FN_DataDaSemana(@cb_DatPed+cast(@PQtdPrzMed as int),@cl_DiaSemVctTit)

                Insert Into PDVDP (Cod_Estabe, Cod_Pedido, Dat_Vencim, Num_SeqPar, Vlr_Duplic, Vlr_SbtEmb, Vlr_ResEmb, Flg_DupExt)
                           Values (@CodEstabe, @CodPed, @WDatVct, @WConPar, @WValBasPed, 0, 0, 0) 
              end

           Set @PQtdPar = @WConPar
               
          end  -- else if @cb_TipVct = 'A'
      end  -- if ((@WTipPrz = 'F') or (@cb_IdPolCom > 0)) and (@cb_TipVct <> 'P') 

    -- CALCULA VENCIMENTOS
    -- prazo linear ou fabricante ponderado
    if (@WTipPrz <> 'F') or (((@WTipPrz = 'F') or (@cb_IdPolCom > 0)) and @cb_TipVct = 'P')
      begin
        Set @WFlgApr = 0
        if @cb_TipVct = 'A'
          Set @WFlgApr = 1
      
        -- calcula o valor de uma duplicata verificando o valor minimo (pode reduzir a qtd de parcelas)
        if @PQtdPar > 0 
          Set @WValDup = Round(@WValBasPed/@PQtdPar,2)
        else
          Set @WValDup = 0
        while (@WValDup < @op_VlrMinDup) and (@PQtdPar > 1)
          begin
            Set @PQtdPar = @PQtdPar - 1
            Set @WValDup = Round(@WValBasPed/@PQtdPar,2)
          end

        -- se parcela for par, intervalo tem que ser par...
--        if (@PQtdPar > 1) and (@PQtdPar % 2 = 0)
--          if @PQtdInt % 2  <> 0
--            Set @PQtdInt = @PQtdInt + 1

        -- aqui  09/06/2016
        while @PQtdPar > 1
		  begin
            -- se parcela for par, intervalo tem que ser par...
            if (@PQtdPar > 1) and (@PQtdPar % 2 = 0)
              if @PQtdInt % 2  <> 0
                Set @PQtdInt = @PQtdInt + 1

            -- prazo do 1o. desdobramento
            Set @WQtdPrzAnt = @PQtdPrzMed - floor((@PQtdPar - 1)*@PQtdInt*1.0/2)

            if @WQtdPrzAnt >= @pm_QtdDiaDupVis
		      break
            else
              Set @PQtdPar = @PQtdPar - 1
          end  -- while @PQtdPar > 1

        if @PQtdPar > 0 
          begin
            Delete From PDVDP
            Where Cod_Estabe = @CodEstabe
            And Cod_Pedido = @CodPed
          end

        Set @WConPar = 1
        Set @WDatVctAnt = @cb_DatPed + cast(@PQtdPrzMed as int) - floor((@PQtdPar - 1)*@PQtdInt*1.0/2)
        Set @WValAcc = 0 -- para calcular a primeira, que terá o residuo (acumulador das parcelas exceto a 1a.)
        while @WConPar <= @PQtdPar
          begin
            Set @WDatVct = dbo.FN_DataDaSemana(@WDatVctAnt,@cl_DiaSemVctTit)
            Insert Into PDVDP (Cod_Estabe, Cod_Pedido, Dat_Vencim, Num_SeqPar, Vlr_Duplic, Vlr_SbtEmb, Vlr_ResEmb, Flg_Apresentacao, Flg_DupExt)
                       Values (@CodEstabe, @CodPed, @WDatVct, @WConPar, @WValDup, 0, 0, @WFlgApr, 0)
            if @WConPar > 1           
              Set @WValAcc = @WValAcc + @WValDup
            Set @WDatVctAnt = @WDatVctAnt + @PQtdInt
            Set @WConPar = @WConPar + 1
          end
          
        -- calcula o valor da primeira que terá o residuo 
        if Exists(Select Num_SeqPar From PDVDP Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed And Num_SeqPar = 1)
          begin
            Update PDVDP
              Set Vlr_Duplic = Round(@WValBasPed-@WValAcc,2)
              Where Cod_Estabe = @CodEstabe
              And Cod_Pedido = @CodPed
              And Num_SeqPar = 1
          end
      end  -- se prazo linear ou fabricante ponderado
      
  end    --  if @cb_TipVct <> 'T'
else
  begin
    if Exists(Select Cod_Prz From PRZCB 
                Where Cod_Prz = @cb_CodPrz 
                And Qtd_PrzMed > 0)  
      begin
        Declare @pz_QtdParPrz tinyint,
                @pz_QtdPrzMed int,
                @cr_QtdPrzPar smallint, 
                @cr_Per_ParPar numeric(18,8)
                
        Select @pz_QtdParPrz = Qtd_ParPrz,
               @pz_QtdPrzMed = Qtd_PrzMed
          From PRZCB
          Where Cod_Prz = @cb_CodPrz

        Set @PQtdPrzMed = @pz_QtdPrzMed
        Set @PQtdPar = @pz_QtdParPrz

        Delete From PDVDP
          Where Cod_Estabe = @CodEstabe
          And Cod_Pedido = @CodPed

        -- calcula os valores dos titulos
        Set @WValAcc = 0
        Set @WConPar = @pz_QtdParPrz

        Declare PRZIT_Cr Cursor Local Fast_Forward For
          Select Qtd_PrzPar, Per_ParPar 
            From PRZIT 
            Where Cod_Prz = @cb_CodPrz
            Order by Qtd_PrzPar desc  -- residuo vai para o 1o vencimento
        Open PRZIT_Cr
        Fetch Next From PRZIT_Cr Into @cr_QtdPrzPar, @cr_Per_ParPar
        While @@FETCH_STATUS = 0
          begin
            if @WConPar > 0
              begin
                if @WConPar = 1
                  Set @WValDup = Round(@WValBasPed-@WValAcc,2)
                else
                  Set @WValDup = Round(@WValBasPed*@cr_Per_ParPar/100,2)
                Set @WDatVct = dbo.FN_DataDaSemana(@cb_DatPed+@cr_QtdPrzPar,@cl_DiaSemVctTit)

                Insert Into PDVDP (Cod_Estabe, Cod_Pedido, Dat_Vencim, Num_SeqPar, Vlr_Duplic, Vlr_SbtEmb, Vlr_ResEmb, Flg_DupExt)
                           Values (@CodEstabe, @CodPed, @WDatVct, @WConPar, @WValDup, 0, 0, 0)

                Set @WValAcc = @WValAcc + @WValDup
                Set @WConPar = @WConPar - 1
              end

            Fetch Next From PRZIT_Cr Into @cr_QtdPrzPar, @cr_Per_ParPar
          end

        Close PRZIT_Cr
        Deallocate PRZIT_Cr

        -- Normaliza prazos nos itens
        Update PDVIT
          Set Qtd_PrzMax = @PQtdPrzMed
          Where Cod_Estabe = @CodEstabe
          And Cod_Pedido = @CodPed and Qtd_Pedido > 0
      end
  end
--------------------------------------------------------------------------------------------------------------------

if (@WTipPrz = 'F') or (@cb_IdPolCom > 0)
  Update PDVCB
     Set Qtd_PrzMed = @PQtdPrzMed
     Where Cod_Estabe = @CodEstabe
     And Numero = @CodPed

Update PDVCB
  Set Qtd_Parcela = @PQtdPar,
      Qtd_Intervalo = @PQtdInt
   Where Cod_Estabe = @CodEstabe
   And Numero = @CodPed

-- inclui ST na 1a. duplicata
if (@pm_FlgImpPriDup = 1) and
((@cb_VlrSubTri + @cb_VlrSbtRes) > 0)
  begin
    Set @WFlgIncDupSbt = 0  -- indica se cria nova parcela para ST
    if @pm_QtdPrzMaxImpSbt > 0
      begin
        -- prazo maximo p/ ST
        Set @WDatVct = dbo.FN_DataDaSemana(@cb_DatPed+@pm_QtdPrzMaxImpSbt,@cl_DiaSemVctTit)
        
        -- prazo da 1a. parcela
        Select top 1 @WDatVctAnt = Dat_Vencim 
          From PDVDP 
          Where Cod_Estabe = @CodEstabe
          And Cod_Pedido = @CodPed 
          And Num_SeqPar = 1
          
        -- verifica se vencimento da 1a.parcela é maior que vencimento minimo p/ ST
        if (@WDatVctAnt > @WDatVct) and
           ((@cb_VlrSubTri + @cb_VlrSbtRes) >= @op_VlrMinDup)
          Set @WFlgIncDupSbt = 1  -- indica se cria nova parcela para sbt
          
      end
     
    -- cria nova 1a.parcela
    if @WFlgIncDupSbt = 1 
      begin
        if Exists(Select 1 From PDVDP Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed And Num_SeqPar = 1)
          begin
            Update PDVDP
              Set Num_SeqPar = Num_SeqPar + 1 
              Where Cod_Estabe = @CodEstabe
              And Cod_Pedido = @CodPed
      
            Update PDVCB
              Set Qtd_Parcela = Qtd_Parcela + 1
              Where Cod_Estabe = @CodEstabe
              And Numero = @CodPed
          end

        Insert Into PDVDP (Cod_Estabe, Cod_Pedido, Dat_Vencim, Num_SeqPar, Vlr_Duplic, Vlr_SbtEmb, Vlr_ResEmb, Flg_DupExt)
                   Values (@CodEstabe, @CodPed, @WDatVct, 1, 0, 0, 0, 0)
      end
     
    -- acrescenta ST à 1a. parcela  
    Update PDVDP
      Set Vlr_Duplic = Vlr_Duplic + @cb_VlrSubTri + @cb_VlrSbtRes,
          Vlr_SbtEmb = @cb_VlrSubTri,
          Vlr_ResEmb = @cb_VlrSbtRes
      Where Cod_Estabe = @CodEstabe
      And Cod_Pedido = @CodPed
      And Num_SeqPar = 1
   end

-- rateia subst.tribut e ressarcimento embutidos no valor
Set @WValSubTri = @cb_VlrSubTri - (Select SUM(Vlr_SbtEmb) From PDVDP Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed)
Set @WValSbtRes = @cb_VlrSbtRes - (Select SUM(Vlr_ResEmb) From PDVDP Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed)

if @WValSubTri < 0
  Set @WValSubTri = 0
if @WValSbtRes < 0
  Set @WValSbtRes = 0  

if @WValSubTri > 0
  begin
    -- rateia
    Update PDVDP
      Set Vlr_SbtEmb = Round(@WValSubTri*Vlr_Duplic/@cb_CVlrPed,2,1)
      Where Cod_Estabe = @CodEstabe
      And Cod_Pedido = @CodPed

    Set @WValAcc = ISNULL(ROUND((Select SUM(ISNULL(Vlr_SbtEmb,0)) From PDVDP Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed And Num_SeqPar > 1),2),0)
    
    -- calcula o valor da primeira que terá o residuo
    Update PDVDP
      Set Vlr_SbtEmb = Round(@cb_VlrSubTri-@WValAcc,2)
      Where Cod_Estabe = @CodEstabe
      And Cod_Pedido = @CodPed
      And Num_SeqPar = 1
  end

if @WValSbtRes > 0
  begin
    -- rateia
    Update PDVDP
      Set Vlr_ResEmb = Round(@WValSbtRes*Vlr_Duplic/@cb_CVlrPed,2,1)
      Where Cod_Estabe = @CodEstabe
      And Cod_Pedido = @CodPed

    Set @WValAcc = ISNULL(ROUND((Select SUM(ISNULL(Vlr_ResEmb,0)) From PDVDP Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed And Num_SeqPar > 1),2),0)

    -- calcula o valor da primeira que terá o residuo
    Update PDVDP
       Set Vlr_ResEmb = Round(@cb_VlrSbtRes-@WValAcc,2)
     Where Cod_Estabe = @CodEstabe
       And Cod_Pedido = @CodPed
       And Num_SeqPar = 1
  end

Set @WValDespes = 0.00     

if @op_FlgLanFin = 0
  begin
    Delete From PDVDP
     Where Cod_Estabe = @CodEstabe
       And Cod_Pedido = @CodPed
      
    Update PDVCB
       Set Qtd_Parcela = @PQtdPar,
           Qtd_Intervalo = @PQtdInt
     Where Cod_Estabe = @CodEstabe
       And Numero = @CodPed
  end
else
  begin
    -- calcula despesa ref. taxa administrativa
    if @ag_PerTaxAdm > 0
      begin
        if @ag_CodAplTaxAdm = 'P' -- margem (participação)
          Set @WValDespes = Round(@cb_VlrLiqIte/(1-@ag_PerTaxAdm/100),2)-Round(@cb_VlrLiqIte,2)
        if @ag_CodAplTaxAdm = 'A'  -- mark-up (acrescimo)
          Set @WValDespes = Round(@cb_VlrLiqIte*@ag_PerTaxAdm/100,2)     
      end

    -- calcula despesa boleto bancario a cobrar na nota fiscal
    Set @WValTotDspBolBan = 0
    if @op_FlgLanFin = 1
      begin
        Set @WValTotDspBolBan = Round(Isnull(@ag_VlrDspBolBan,0) * @PQtdPar,2)
        Set @WValDespes = @WValDespes + @WValTotDspBolBan
      end

    -- debita taxa boleto para vendedor
    if 1 = 1 --@TipNfs = 'V'
      begin
        -- taxa boleto
        if @pm_FlgDebBlqBanVrbVdr = 1
          begin
            Set @WValDespes = @WValDespes - @WValTotDspBolBan    -- isenta cliente
          end
      end
  end

/*
if @cb_VlrDespes <> @WValDespes
  begin
-- print 'Vou ratear despesas'
    Exec PR_RateiaDespesasPDV @CodEstabe, @CodPEd
  end
*/

-- libera pedido
Update PDVCB
   Set Flg_Calc = 0               
 Where Cod_Estabe = @CodEstabe
   And Numero = @CodPed

if @@trancount > 0
  Commit Transaction
END
GO


SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_AtualizaPVMCB]
@PIdPVMCB int     -- se = 0, atualiza todos registros em PVMCB
AS

SET NOCOUNT ON

Update cb

   Set cb.C_QtdItens    = IsNull(c.C_QtdItens,0)
     , cb.C_QtdUndIte   = IsNull(i.C_QtdUndIte,0)
     , cb.C_VlrBruto    = IsNull(i.C_VlrBruto,0)
     , cb.C_VlrDscIte   = IsNull(i.C_VlrBruto,0)-IsNull(c.C_VlrLiqItens,0)
     , cb.C_VlrLiqItens = IsNull(c.C_VlrLiqItens,0)
     , cb.C_VlrRepIcm   = IsNull(c.C_VlrRepIcm,0)
     , cb.C_VlrSubTri   = IsNull(c.C_VlrSubTri,0)
     , cb.C_VlrSbtRes   = IsNull(c.C_VlrSbtRes,0)
     , cb.C_VlrDscTri   = IsNull(c.C_VlrDscTri,0)
     , cb.C_VlrImposto  = IsNull(c.C_VlrImposto,0)
     , cb.C_VlrDespes   = IsNull(c.C_VlrDespes,0)
     , cb.C_VlrDesconto = IsNull(c.C_VlrDesconto,0)
     , cb.C_VlrDscBon   = IsNull(c.C_VlrDscBon,0)
     , cb.C_VlrIpi      = IsNull(c.C_VlrIpi,0)
     , cb.C_VlrPedido   = IsNull(c.C_VlrPedido,0)
     , cb.C_PerLuc      = IsNull(c.C_PerLuc,0)

  From dbo.PVMCB cb

       Left Join (Select Id_PVMCB
                       , C_QtdItens    = Sum(IsNull(Qtd_Itens,0))
                       , C_VlrLiqItens = Round(Sum(IsNull(Vlr_LiqItens,0)),2)
                       , C_VlrRepIcm   = Round(Sum(IsNull(Vlr_RepIcms,0)),2)
                       , C_VlrSubTri   = Round(Sum(IsNull(Vlr_SubsTrib,0)),2)
                       , C_VlrSbtRes   = Round(Sum(IsNull(Vlr_SbtRes,0)),2)
                       , C_VlrDscTri   = Round(Sum(IsNull(Vlr_DscTri,0)),2)
                       , C_VlrImposto  = Round(Sum(IsNull(Vlr_SubsTrib,0)+IsNull(Vlr_SbtRes,0)-IsNull(Vlr_DscTri,0)),2)
                       , C_VlrDespes   = Round(Sum(IsNull(Vlr_Despes,0)+IsNull(Vlr_DspExt,0)),2)
                       , C_VlrDesconto = Round(Sum(IsNull(C_VlrDesconto,0)),2)
                       , C_VlrDscBon   = Round(Sum(IsNull(Vlr_DscBon,0)),2)
                       , C_VlrIpi      = Round(Sum(IsNull(Vlr_Ipi,0)),2)
                       , C_VlrPedido   = Round(Sum(IsNull(C_VlrPedido,0)),2)
                       , C_PerLuc      = Case 
                                           When (Select sum(Vlr_LiqItens)) > 0 then (Select Sum(Per_Rnt*Vlr_LiqItens)/sum(Vlr_LiqItens))
                                           Else 0
                                         End
                    From dbo.PDVCB
                   Where IsNull(Id_PVMCB,0) > 0 
                     And ((@PIdPVMCB = 0) or (Id_PVMCB = @PIdPVMCB))
                     And ((Status1 = 'P') and (Status2 <> 'N') and (Status2 <> 'D'))
                   Group by Id_PVMCB) c on cb.Id_PVMCB = c.Id_PVMCB

       Left Join (Select cab.Id_PVMCB
                       , C_QtdUndIte = sum(ite.Qtd_Pedido+ite.Qtd_Bonificacao)
                       , C_VlrBruto = Round(Sum(IsNull(ite.Vlr_Bruto,0)),2)
                    From dbo.PDVIT ite
                         inner join dbo.PDVCB cab on ite.Cod_Estabe = cab.Cod_Estabe and 
                                                     ite.Cod_Pedido = cab.Numero
                   Where IsNull(cab.Id_PVMCB,0) > 0 
                     And ((@PIdPVMCB = 0) or (cab.Id_PVMCB = @PIdPVMCB))
                   Group by cab.Id_PVMCB) i on cb.Id_PVMCB = i.Id_PVMCB

 Where ((@PIdPVMCB = 0) or (cb.Id_PVMCB = @PIdPVMCB))

GO


SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CalculaSbtEmbCTREC]
@PCodEstabe int,
@PSerNot varchar(3),
@PNumNot int


AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = cast(GetDate() as date)

--if (Select Status From NFSCB Where Cod_Estabe = @PCodEstabe and Ser_Nota = @PSerNot and Num_Nota  = @PNumNot) = 'A'
--  RAISERROR('Nota Fiscal "em aberto"',16,1)
--else
  begin
    Begin Transaction
    
    Declare @CodDoc int,
            @WValTotDup numeric(18,4),
            @WValTotImpDup numeric(18,4),
            @WValTotAux numeric(18,4),
            @pm_FlgImpPriDup bit,
			@cl_FlgBlqIncImpPriDup bit,
            @cb_VlrSbtRes numeric(18,4),
            @cb_VlrSubTri numeric(18,4),
            @cb_VlrNot numeric(18,4)

    Select @cb_VlrSbtRes = Round(IsNull(cb.Vlr_SbtRes,0),2),
           @cb_VlrSubTri = Round(IsNull(cb.Vlr_SubsTrib,0),2),
           @cb_VlrNot = Round(IsNull(cb.Vlr_TotalNota,0),2),
      	   @cl_FlgBlqIncImpPriDup = IsNull(en.Flg_BlqIncSbtPriDup,0)
      From NFSCB cb 
           Left Join CLIEN cl on cb.Cod_Cliente = cl.Codigo 
           Left Join ENXES en on cb.Cod_Estabe = en.Cod_Estabe and cl.Cgc_Cpf = en.Num_CgcCpf and cl.Codigo = en.Cod_Client
     Where cb.Cod_Estabe = @PCodEstabe 
       And cb.Ser_Nota = @PSerNot and cb.Num_Nota = @PNumNot

    Select @pm_FlgImpPriDup = IsNull(FlgIncImpPriDup,0)
      From PARAM
     Where Cod_Estabe = @PCodEstabe 

    if (@pm_FlgImpPriDup = 1) and (@cl_FlgBlqIncImpPriDup = 1)
      Set @pm_FlgImpPriDup = 0

    -- verifica se ST nao foi embutida no preco  
    if @cb_VlrSubTri+@cb_VlrSbtRes = 0
      begin
        Select @cb_VlrSubTri = Round(IsNull(Vlr_SubsTrib,0),2),
               @cb_VlrSbtRes = Round(IsNull(Vlr_SbtRes,0),2)		
          From NSOCB
         Where Cod_Estabe = @PCodEstabe 
           And Ser_Nota = @PSerNot and Num_Nota = @PNumNot
      end
      
    if @cb_VlrSubTri+@cb_VlrSbtRes > 0
      begin
        -- normaliza campos
        Update CTREC
           Set Vlr_SbtEmb = 0
         Where Cod_Estabe = @PCodEstabe 
           And Ser_NfOrigem = @PSerNot and Num_NfOrigem = @PNumNot
           And Vlr_SbtEmb is null
          
        Update CTREC
           Set Vlr_ResEmb = 0
         Where Cod_Estabe = @PCodEstabe 
           And Ser_NfOrigem = @PSerNot and Num_NfOrigem = @PNumNot
           And Vlr_ResEmb is null
      
        -- verifica valor total dos titulos      
        Set @WValTotDup = IsNull(Round((Select Sum(Vlr_Documento) From CTREC Where Cod_Estabe = @PCodEstabe And Ser_NfOrigem = @PSerNot and Num_NfOrigem = @PNumNot),2),0)

        -- verifica valor total dos tributos      
        Set @WValTotImpDup = IsNull(Round((Select Sum(IsNull(Vlr_SbtEmb,0)+IsNull(Vlr_ResEmb,0)) From CTREC Where Cod_Estabe = @PCodEstabe And Ser_NfOrigem = @PSerNot and Num_NfOrigem = @PNumNot),2),0)

        if (@WValTotDup >= @cb_VlrNot) and
           (@cb_VlrSubTri+@cb_VlrSbtRes <> @WValTotImpDup)
          begin
            -- zera todos os valores embutidos se for o caso
            Update CTREC
              Set Vlr_SbtEmb = 0,
                  Vlr_ResEmb = 0
            Where Cod_Estabe = @PCodEstabe 
              And Ser_NfOrigem = @PSerNot and Num_NfOrigem = @PNumNot
           
            -- poe na memoria 1a. titulo a vencer que vai receber diferença de valores
            Set @CodDoc = IsNull((Select top 1 Cod_Documento From CTREC 
                                   Where Cod_Estabe = @PCodEstabe 
                                     And Ser_NfOrigem = @PSerNot and Num_NfOrigem = @PNumNot
                                   Order by Dat_Vencimento, Cod_Documento),0)
 
            -- subst. tribut.
            if (@cb_VlrSubTri > 0) and (@CodDoc > 0) and (@WValTotDup > 0)
              begin
                -- rateia se for o caso
                if @pm_FlgImpPriDup = 1
                  begin
                    Update CTREC
                       Set Vlr_SbtEmb = @cb_VlrSubTri
                     Where Cod_Estabe = @PCodEstabe 
                       And Ser_NfOrigem = @PSerNot and Num_NfOrigem = @PNumNot
                       And Cod_Documento = @CodDoc
                       And Vlr_Documento >= @cb_VlrSubTri
                    if @@ROWCOUNT = 0
                      Set @pm_FlgImpPriDup = 0
                  end
                
                if @pm_FlgImpPriDup = 0
                  begin
                    Update CTREC
                       Set Vlr_SbtEmb = Round(@cb_VlrSubTri*Vlr_Documento/@WValTotDup,2,1)
                     Where Cod_Estabe = @PCodEstabe 
                       And Ser_NfOrigem = @PSerNot and Num_NfOrigem = @PNumNot
                  end
              
                Set @WValTotAux = IsNull(Round((Select Sum(IsNull(Vlr_SbtEmb,0)) 
                                                  From CTREC Where Cod_Estabe = @PCodEstabe 
                                                   And Ser_NfOrigem = @PSerNot and Num_NfOrigem = @PNumNot
                                                   And Cod_Documento <> @CodDoc),2),0)

                -- calcula o valor da primeira que terá o residuo
                Update CTREC
                   Set Vlr_SbtEmb = Round(@cb_VlrSubTri-@WValTotAux,2)
                 Where Cod_Estabe = @PCodEstabe 
                   And Cod_Documento = @CodDoc
              end
              
            -- ressarcimento tribut.
            if (@cb_VlrSbtRes > 0) and (@CodDoc > 0) and (@WValTotDup > 0)
              begin
                -- rateia se for o caso
                if @pm_FlgImpPriDup = 1
                  begin
                    Update CTREC
                       Set Vlr_ResEmb = Round(@cb_VlrSbtRes*Vlr_Documento/@WValTotDup,2,1)
                     Where Cod_Estabe = @PCodEstabe 
                       And Ser_NfOrigem = @PSerNot and Num_NfOrigem = @PNumNot
                       And Cod_Documento = @CodDoc
                       And Vlr_Documento >= @cb_VlrSbtRes
                    if @@ROWCOUNT = 0
                      Set @pm_FlgImpPriDup = 0
                  end  
                                
                if @pm_FlgImpPriDup = 0
                  begin
                    Update CTREC
                       Set Vlr_ResEmb = Round(@cb_VlrSbtRes*Vlr_Documento/@WValTotDup,2,1)
                     Where Cod_Estabe = @PCodEstabe 
                       And Ser_NfOrigem = @PSerNot and Num_NfOrigem = @PNumNot
                  end
              
                Set @WValTotAux = IsNull(Round((Select Sum(IsNull(Vlr_ResEmb,0)) 
                                                  From CTREC Where Cod_Estabe = @PCodEstabe 
                                                   And Ser_NfOrigem = @PSerNot and Num_NfOrigem = @PNumNot
                                                   And Cod_Documento <> @CodDoc),2),0)

                -- calcula o valor da primeira que terá o residuo
                Update CTREC
                   Set Vlr_ResEmb = Round(@cb_VlrSbtRes-@WValTotAux,2)
                 Where Cod_Estabe = @PCodEstabe 
                   And Cod_Documento = @CodDoc
              end
              
          end
          
      end

    if @@trancount > 0
      Commit Transaction
  end

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[FN_RetornaPoliticasProduto]
(
 @PCodOri varchar(1),      -- Origem (A-Ativo, P-Receptivo, M-Móvel, T-Eletronico/EDI, W-Internet/WEB, H-Hospitalar, D-por Desdobramento, V-por Val)
 @PCodEstabe int,          -- OPCIONAL: cod.estabe: -1 
 @PCodCli int,             
 @PCodVdr int,             -- OPCIONAL: cod.vendedor: 0 
 @PCodOpe int,             -- OPCIONAL: cod.operador: 0 
 @PIdPolComCab int,     
 @PCodPrd int,
 @PDatRef smalldatetime,
 @PCodLayPde int,          -- OPCIONAL: layout pedido eletronico: 0
 @PCodGrpLay int           -- OPCIONAL: grupo do layout pedido eletronico: 0
)

RETURNS @retPoliticas TABLE 
  ( Cod_Estabe int, 
	Id_PolCom int,
    Cod_PolCom varchar(25),
	Dat_Cadastro smalldatetime,
	Flg_NegDsc bit,
    Flg_AcuVrbPos bit, 
    Flg_AcuVrbNeg bit, 
    Flg_MarkupCusCom bit, 
    Tip_RatBon varchar(1), 
    Tip_GerVrb varchar(1), 
    Flg_CtrPdvVrbVdr bit, 
    Flg_CtrPdvVrbOpe bit, 
    Controle_Saldo varchar(1), 
    Per_AcrAutPrc numeric(9,4), 
    Per_DscAutPrc numeric(9,4), 
    Prc_Promoc numeric(18,8), 
    Qtd_PrzMax smallint, 
    Per_Descon numeric(7,4), 
	Per_DscVis numeric(7,4), 
    Qtd_Minimo int, 
	Qtd_Maximo int, 
    Ordem smallint, 
    Nivel varchar(1),
    Val_PrcTab numeric(18,4),
    Per_DscMaxTab numeric(7,4),
    Prc_Unitar numeric(18,4)
  ) 

--Retorna todas politicas permitidas para o produto

AS

BEGIN

Declare @pr_CodCla varchar(2),
		@WTipPrz char(1),
		@WFlgExcClaPolComCab bit,
        @WQtdPrzPolComCab int,
        @WFlgPolCabBlqOutPolIte bit

Set @pr_CodCla = IsNull((Select Substring(Cod_Classif,1,2) From PRODU Where Codigo = @PCodPrd),'')

Set @WQtdPrzPolComCab = 0
Set @WFlgPolCabBlqOutPolIte = 0
Set @WTipPrz = 'F'
Set @WFlgExcClaPolComCab = 0

if Exists(Select 1 From POCOM Where Id_PolCom = @PIdPolComCab)
  Select @WQtdPrzPolComCab = IsNull(pc.Qtd_PrzMax,0),
         @WFlgPolCabBlqOutPolIte = IsNull(pc.Flg_BlqPolDifItePdv,0),
		 @WTipPrz = IsNull(pc.Cod_TipPrz,'F'),
         @WFlgExcClaPolComCab = IsNull(pc.Flg_ExcCla,0)
    From POCOM pc   
	     left join PCXCP cp on pc.Id_PolCom = cp.Id_PolCom
   Where pc.Id_PolCom = @PIdPolComCab

Delete From @retPoliticas

Insert Into @retPoliticas
  Select pe.Cod_Estabe, p.Id_PolCom, p.Cod_PolCom, p.Dat_Cadastro, Flg_NegDsc=IsNull(p.Flg_NegDsc,0), 
         Flg_AcuVrbPos=IsNull(p.Flg_AcuVrbPos,0), Flg_AcuVrbNeg=IsNull(p.Flg_AcuVrbNeg,0), 
	     Flg_MarkupCusCom=IsNull(p.Flg_MarkupCusCom,0), Tip_RatBon=IsNull(p.Tip_RatBon,''), 
         TipGerVrb = dbo.FN_TipGerVrbPdv(p.Id_PolCom), Flg_CtrPdvVrbVdr=IsNull(p.Flg_CtrPdvVrbVdr,0), Flg_CtrPdvVrbOpe=IsNull(p.Flg_CtrPdvVrbOpe,0), 
         Controle_Saldo=IsNull(p.Controle_Saldo,''), Per_AcrAutPrc=IsNull(p.Per_AcrAutPrc,0), Per_DscAutPrc=IsNull(p.Per_DscAutPrc,0), 
         s.Prc_Promoc, s.Qtd_PrzMax, s.Per_Descon, s.Per_DscVis, s.Qtd_Minimo, s.Qtd_Maximo, s.Ordem, s.Nivel, 
         Val_PrcTab = IsNull(tp.Val_PrcVen,0), Per_DscMaxTab = IsNull(tp.Per_DscMax,0),
         Prc_Uni = Case
                     When s.Prc_Promoc > 0 then s.Prc_Promoc
                     When IsNull(tp.Val_PrcVen,0) > 0 then tp.Val_PrcVen
                     When IsNull(p.Per_AcrAutPrc,0) > 0 then Round(IsNull(pr.Prc_Venda,0)*(1+p.Per_AcrAutPrc/100),IsNull(pm.QtdDecPrcItePdv,0))
                     When IsNull(p.Per_DscAutPrc,0) > 0 then Round(IsNull(pr.Prc_Venda,0)*(1-p.Per_DscAutPrc/100),IsNull(pm.QtdDecPrcItePdv,0))
                     Else Round(IsNull(pr.Prc_Venda,0)*(1-IsNull(pr.Per_DscAut,0)/100),IsNull(pm.QtdDecPrcItePdv,0))
                   End
    From POCOM p 
		 --Cross Apply dbo.FN_ViewPoliticaAtiva(p.Id_PolCom, @PDatRef) vw
--         Inner Join PCXES pe on ((p.Id_PolCom = pe.Id_PolCom) and (pe.Cod_Estabe = @PCodEstabe)) 
         Inner Join PCXES pe on ((p.Id_PolCom = pe.Id_PolCom) and ( ((@PCodEstabe > -1) and (pe.Cod_Estabe = @PCodEstabe)) or (@PCodEstabe < 0)) ) 
         Inner Join PARAM pm on pe.Cod_Estabe = pm.Cod_Estabe
         Inner Join PRXES pr on pe.Cod_Estabe = pr.Cod_Estabe and pr.Cod_Produt = @PCodPrd

         Inner Join CLIEN cl on cl.Codigo = @PCodCli
         Left  Join ENXES es on es.Cod_Estabe = @PCodEstabe and es.Num_CgcCpf = cl.Cgc_Cpf and es.Cod_Client = cl.Codigo
         Left  Join PCXCL pc on ((p.Id_PolCom = pc.Id_PolCom) and (pc.Cod_Client = cl.Codigo)) 
         Left  Join PCXGC pg on ((p.Id_PolCom = pg.Id_PolCom) and (pg.Cod_GrpCli = cl.Cod_GrpCli)) 
         Left  Join PCXUF pu on ((p.Id_PolCom = pu.Id_PolCom) and (pu.Cod_Uf = cl.Cod_Estado)) 
         Left  Join PCXVE pv on ((p.Id_PolCom = pv.Id_PolCom) and (pv.Cod_Vended = @PCodVdr)) 
         Left  Join PCXOP po on ((p.Id_PolCom = po.Id_PolCom) and (po.Cod_Vended = @PCodOpe)) 
         Left  Join TBPRC tb on ((tb.Cod_Estabe = @PCodEstabe) or (tb.Flg_AllEstabe = 1)) 
		                    and (tb.Cod_TabPrc = Case 
                                                   When (IsNull(p.Flg_UsaTabPrcCadCli,0) = 1) and (IsNull(es.Cod_TabPrc,0) > 0) 
                                                     then es.Cod_TabPrc 
                                                   Else p.Cod_TabPrc
                                                 End)
         Left  Join TPXPR tp on ((tb.Cod_Estabe = tp.Cod_Estabe) and (tb.Cod_TabPrc = tp.Cod_TabPrc) and (tp.Cod_Produt = @PCodPrd))
         Left  Join dbo.FN_ViewPoliticasProduto(@PIdPolComCab, @PCodPrd, @PDatRef) s on (p.Id_PolCom = s.Id_PolCom) 

         Left  Join LGXPC lp on (lp.Cod_Estabe = @PCodEstabe and lp.Cod_Layout = @PCodLayPde and lp.Cod_Grupo = @PCodGrpLay and lp.Id_PolCom = p.Id_PolCom)
         Left  Join TBLPG lg on (lg.Cod_Estabe = lp.Cod_Estabe and lg.Cod_Layout = lp.Cod_Layout and lg.Cod_Grupo = lp.Cod_Grupo)

 Where ( (pc.Cod_Client > 0) or (pg.Cod_GrpCli > 0) or (pu.Cod_Uf <> '') ) 
   And ( (@PCodVdr = 0) or ((@PCodVdr > 0) and (pv.Cod_Vended = @PCodVdr)) )
   And ( (@PCodOpe = 0) or ((@PCodOpe > 0) and (po.Cod_Vended = @PCodOpe)) )
   And IsNull(s.Ordem,0) > 0

   And p.Tip_PolCom <> 'KIT'
   And ( (p.Dat_Inicio Is Null  or (@PDatRef >= p.Dat_Inicio))  and
         (p.Dat_Termino Is Null or (@PDatRef <= p.Dat_Termino)) and
         (p.Bloqueado Is Null or p.Bloqueado = 0) ) 

   And (((@WTipPrz = 'L') and (s.Qtd_PrzMax >= @WQtdPrzPolComCab)) or 
        (@WTipPrz = 'F')) 
   And ((p.Flg_BlqCli = 0) or ((p.Flg_BlqCli = 1) and (IsNull(cl.Flg_BlqPrm,0) = 0)))

   And (((@PCodOri = 'M') and (p.Flg_Cfv = 1)) or
        ((@PCodOri = 'T') and (p.Flg_PedEle = 1)) or
        ((@PCodOri = 'W') and (p.Flg_Web = 1)) or
        ((Charindex(@PCodOri,';M;T;W;') = 0) and (p.Flg_Televendas = 1)))

   And @pr_CodCla = Case
                      When @WFlgExcClaPolComCab = 1 then 
                        Case
                          When Exists(Select Cod_Classi From PCXCP Where Id_PolCom = @PIdPolComCab And Cod_Classi = @pr_CodCla) then @pr_CodCla
                          Else '??'
                        End
                      Else @pr_CodCla
                    End

-- verifica se politica do cabecalho permite outrqas politica no item
   And p.Id_PolCom = Case
                       When @WFlgPolCabBlqOutPolIte = 1 then @PIdPolComCab
	                   Else p.Id_PolCom
                     End
-- verifica se há restrição de uso da politica do item
   And ((p.Flg_BlqPolDifCabPdv = 0) or (p.Id_PolCom = @PIdPolComCab))

-- verifica politicas vinculadas ao layout
   And ((IsNull(lg.Flg_UsaPolVnc,0) = 1) and (IsNull(lp.Id_PolCom,0) > 0) or (IsNull(lg.Flg_UsaPolVnc,0) = 0))

 Order by s.Nivel, pe.Cod_Estabe, p.Dat_Cadastro, s.Ordem, s.Id_PolCom 

RETURN
END
GO

