CREATE FUNCTION [dbo].[FN_CN_QtdSugCmp]
(
  @PCodEstabe int,
  @PCodPrd int,
  @PDatRef smalldatetime,
  @PDiaRep smallint,
  @PDiaSup smallint,
  @PFlgEstoqueSeguranca bit,     -- usa estoque seguranca
  @PFlgUsaEstTraMan bit = 0,     -- usa Transito Manual
  @PListaEst varchar(255) = ''   -- Considera estoque de outros estabelecimentos
)
RETURNS int


AS

BEGIN

  -- Declarar variável de retorno da function
  Declare @QtdSugCmp int,
          @cn_EstDis int,
          @cn_EstDisOut int,
          @cn_EstTra int,
      @cn_EstTraMan int,
          @WEstMin int,
          @WEstSup int,
          @WEstSeg int,
          @WAno smallint,
          @WMes smallint,
          @WVenMedDia numeric(18,4),
          @FatSeg numeric(18,4),
          @NivSrv numeric(18,4),
          @DsvPad numeric(18,4),
		  @QtdMesAtu int
          
  Set @QtdSugCmp = 0
  
  if ISNULL(@PDatRef,0) > 0
    begin
      Set @WAno = YEAR(@PDatRef)
      Set @WMes = MONTH(@PDatRef)
      
      -- estoque disponivel e transito mais recente      
      Set @cn_EstDis = 0
      Set @cn_EstTra = 0

      Select top 1 @cn_EstDis = Qtd_Dispon,
                   @cn_EstTra = Qtd_Transi,
           @cn_EstTraMan = Qtd_EstTraMan
      From CN_HSPRD
      Where Cod_Estabe = @PCodEstabe
      And Cod_Produt = @PCodPrd
      And Ref_AnoMes <= (@WAno*100+@WMes)
      Order by Ref_AnoMes desc

      Set @cn_EstDisOut = 0

    if @PListaEst <> ''
      begin
      With CTE(Cod_Estabe,Qtd_Dispon,Ref_AnoMes,Row)
      As
      (       Select hs.Cod_Estabe,
                     hs.Qtd_Dispon,
               hs.Ref_AnoMes, 
               ROW_NUMBER() OVER(PARTITION BY Cod_Estabe ORDER BY Cod_Estabe,Ref_AnoMes DESC) AS Row
          From CN_HSPRD hs
          Inner Join dbo.FN_ListaCodigos( @PListaEst ) es On es.Numero = hs.Cod_Estabe
          Where Cod_Produt = @PCodPrd
          And Ref_AnoMes <= (@WAno*100+@WMes)
      )
      Select @cn_EstDisOut = Sum(Qtd_Dispon) From CTE
      Where Row = 1
    end

      if @cn_EstDis is null Set @cn_EstDis = 0
      if @cn_EstTra is null Set @cn_EstTra = 0
    if @cn_EstTraMan is null Set @cn_EstTraMan = 0
    if @cn_EstDisOut is null Set @cn_EstDisOut = 0

    -- Usa transito do sistema ou transito manual
    if @PFlgUsaEstTraMan = 1
      Set @cn_EstTra = @cn_EstTraMan
	  
	Select @QtdMesAtu = CASE WHEN IsNull(QtdMesCalcSugCompra, 0) = 0 
								THEN 3 ELSE 6
						   END 
        FROM PARAM where Cod_Estabe = @PCodEstabe 

      -- Estoque segurança
      Set @WEstSeg = 0
      if @PFlgEstoqueSeguranca = 1
        begin
          Set @NivSrv = 95.00 -- nivel.serviço 95%
      Set @FatSeg = dbo.FN_CN_FatorSeguranca(@NivSrv)   
          Set @DsvPad = dbo.FN_CN_DesvioPadrao(@PCodEstabe,@PCodPrd,@PDatRef,@QtdMesAtu)
          Set @WEstSeg = Round(@FatSeg*@DsvPad*SQRT(@PDiaRep),0) 
        end

      -- venda media diaria dos ultimos 3 ou 6 meses
      Set @WVenMedDia = dbo.FN_CN_QtdVenMedDia(@PCodEstabe,@PCodPrd,@PDatRef,@QtdMesAtu)

      -- estoque mínimo e estoque para suprimento
      --Set @WEstMin = round(@WVenMedDia*@PDiaRep,0) + @WEstSeg   
      --Set @WEstSup = round(@WVenMedDia*@PDiaSup,0) 
      --pra bater com a planilha 
      Set @WEstMin = round((round(@WVenMedDia*30,0)/30)*@PDiaRep,0) + @WEstSeg   
      Set @WEstSup = round((round(@WVenMedDia*30,0)/30)*@PDiaSup,0) 

      if @PFlgEstoqueSeguranca = 1
        Set @QtdSugCmp = @WEstSup-@cn_EstDis-@cn_EstTra + @WEstMin
      else
        Set @QtdSugCmp = @WEstSup-@cn_EstDis-@cn_EstTra
        
      -- sugestao
      --if @cn_EstDis + @cn_EstTra >= @WEstMin 
      --  Set @QtdSugCmp = @WEstSup-@cn_EstDis-@cn_EstTraMan+@WEstMin
      --else
      --  Set @QtdSugCmp = @WEstSup+@WEstSeg
    
      --if @QtdSugCmp < 0
      --  Set @QtdSugCmp = 0  
    end
  
  -- Retorna o resultado da function
  RETURN @QtdSugCmp

END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE TRIGGER [dbo].[TR_ENDDP_AtualizaCampos_Depois] ON [dbo].[ENDDP] 
AFTER INSERT, UPDATE, DELETE 
NOT FOR REPLICATION
AS

-- comando p/ corrigir erro delphi/ado: record was changed by another user
SET NOCOUNT ON 

if Update(Vol_Util) or Update(Vol_Ocup)
  begin
    Update E
      Set E.Vol_Disp = Case 
                         When I.Vol_Util > I.Vol_Ocup Then I.Vol_Util-I.Vol_Ocup
                         Else 0
                       End  
      From Inserted I inner Join 
           ENDDP E on E.Cod_Estabe = I.Cod_Estabe and 
                      E.Cod_Dep = I.Cod_Dep and 
                      E.Num_Rua = I.Num_Rua and E.Num_Col = I.Num_Col and 
                      E.Num_NIv = I.Num_Niv and E.Num_Apt = I.Num_Apt
  end
  
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_SolicitaLotesPDV]
@CodEstabe int,
@CodPed int,       -- num. do pedido
@QtdMesVctMin int,  -- qtd meses vencimento minimo de lotes DESCARTAR  
@FlgErr bit output

AS

SET NOCOUNT ON 

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = Cast(GetDate() as date)

Declare @StrMsg varchar(400)

Set @FlgErr = 0
Set @StrMsg = ''

if Exists(Select 1
           From PDVCB
          Where Cod_Estabe = @CodEstabe
            And Numero = @CodPed
            And IsNull(Sta_SepLot,'') <> '')
  begin
    Set @FlgErr = 1
    Return
  end

Set @StrMsg = IsNull((Select MsgErr = Case
                                        When CharIndex(Status2,';N;D;') > 0 then 'Pedido já faturado'
                                        When (Status1 <> 'P') or (Status2 <> 'F') then 'Pedido não está pendente/fechado'
                                        When IsNull(Bloqueio,'') <> '' then 'Pedido está bloqueado'
                                        When IsNull(Flg_Wms,0) = 0 then 'Pedido não permite solicitar lotes'
                                        Else ''
                                      End
                        From PDVCB
                       Where Cod_Estabe = @CodEstabe
                         And Numero = @CodPed),'')
if @StrMsg <> ''
  Set @FlgErr = 1

/*
-- retirar esta critica quando o sistema permitir solicitação de lote específico parcial
if (@FlgErr = 0) and
   Exists(Select 1 From PDVLT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed)
  begin
    Set @FlgErr = 1
    Set @StrMsg = 'Pedido já solicitou lotes'
  end
*/

-- verifica se existe quantidades em PDVLT inválidas
if (@FlgErr = 0) and
   Exists(Select lt.Cod_Produt, lt.QtdLot, it.QtdIte 
             From (Select Cod_Produt, QtdLot = SUM(IsNull(Qtd_Lote,0)) 
                     From PDVLT 
                   Where Cod_Estabe = @CodEstabe
                     And Cod_Pedido = @CodPed
                     And IsNull(Qtd_Lote,0) > 0 
                   Group by Cod_Produt) lt 
                 Inner Join (Select Cod_Produto, QtdIte = SUM(IsNull(Qtd_Pedido,0)+Isnull(Qtd_Bonificacao,0)) 
                               From PDVIT 
                              Where Cod_Estabe = @CodEstabe
                                And Cod_Pedido = @CodPed
                                And (IsNull(Qtd_Pedido,0)+IsNull(Qtd_Bonificacao,0)) > 0 
                              Group by Cod_Produto) it on it.Cod_Produto = lt.Cod_Produt 

           Where IsNull(lt.QtdLot,0) > IsNull(it.QtdIte,0))
  begin
    Set @FlgErr = 1
    Set @StrMsg = 'Existem itens em PDVLT com quantidades superiores de PDVIT '
  end

if (@FlgErr = 0) and
   Exists(Select Cod_Produto, Tip_Sai, count(*) From PDVIT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed Group By Cod_Produto, Tip_Sai Having count(*) > 1)
  begin
    Set @FlgErr = 1
    Set @StrMsg = 'Existem produtos com mais de um lote'
  end

if (@FlgErr = 0) and
   Exists(Select z1.Cod_Zon, z2.Cod_Zon 
            From TBZON z1, TBZON z2
           Where z1.Cod_Estabe = z2.Cod_Estabe
             And z1.Cod_Dep = z2.Cod_Dep
             And z1.Cod_Estabe = @CodEstabe
             And z1.Cod_Zon > 0
             And z1.Cod_Zon <> z2.Cod_Zon 
             And ((z1.Num_RuaIni between z2.Num_RuaIni and z2.Num_RuaFim) or
                  (z1.Num_RuaFim between z2.Num_RuaIni and z2.Num_RuaFim)))
  begin
    Set @FlgErr = 1
    Select top 1 
           @StrMsg = 'Endereços conflitantes entre as Zonas '+CAST(z1.Cod_Zon as varchar)+' e '+CAST(z2.Cod_Zon as varchar)
      From TBZON z1, TBZON z2
     Where z1.Cod_Estabe = z2.Cod_Estabe
       And z1.Cod_Dep = z2.Cod_Dep
       And z1.Cod_Estabe = @CodEstabe
       And z1.Cod_Zon > 0
       And z1.Cod_Zon <> z2.Cod_Zon 
       And ((z1.Num_RuaIni between z2.Num_RuaIni and z2.Num_RuaFim) or
            (z1.Num_RuaFim between z2.Num_RuaIni and z2.Num_RuaFim))    
  end

-- critica cadastros, inconsistencias, embalagem padrao, apresentacao padrao, etc...
if @FlgErr = 0
  Exec PR_CriticaCadastrosVolumesWMS @CodEstabe, @CodPed, @FlgErr output, @StrMsg output

-- verifica reabastecimento do picking
if @FlgErr = 0
  Exec PR_VerificaAbastecimentoPedido @CodEstabe, @CodPed, @StrMsg output, @FlgErr output  


if @FlgErr = 1
  begin
    RAISERROR(@StrMsg,16,1)
    Return
  end
else
BEGIN
  Begin Transaction

--    Declare @DesLoc varchar(80) = '(ANTES) PR_SolicitaLotesPDV pedido: '+cast(@CodPed as varchar)
--    Exec PR_Verifica_Divergencia_PRXESxPRLOT_PRLTL @DesLoc, @CodEstabe, 0

    Declare @CodPrd int,
            @TipSai varchar(1),
            @IdPolLot int,
            @QtdPdv int,
            @QtdLot int,
            @QtdSld int,
			@FatCnvImpFat int,
            @QtdMov int,
            @FlgMov bit = 0,
            @CodLotTip varchar(20),
            @QtdTotTip int,
            @QtdPraTip int,
            @QtdDepTip int,
            @QtdFra int,
            @QtdEmbFec int,
            @QtdEmbFecCal int,
            @QtdCxaFec int,
            @QtdUndLot int,
            @QtdSldFiscal int,
            @QtdSolPulmao int,
            @cl_CodCliPag int,
            @cl_CodGrpCli int,
            @cl_QtdMesMinPrzVctLot int,
            @cl_FlgBlqLotVarPdv bit,
            @StrPrd varchar(100),
            @FlgIntWms bit = 0,
            @BlqEstFisNeg bit = 0,
            @FlgUndMin bit = 0,
            @StaIntWms varchar(1),
            @FlgTipVenFat bit = 0,
            @FlgPodeFechar bit = 0,
		    @Usuario varchar(15)

    Set @Usuario = dbo.FN_UsuarioInfarma()

    Select @FlgIntWms = IsNull(FlgIntegrWmsExt,0),
           @BlqEstFisNeg = IsNull(BlqEstFisNeg,0)   -- nao permite negativar estoque fiscal
      From PMEST 
     Where Cod_Estabe = @CodEstabe

    Select @FlgUndMin = IsNull(FlgAltUnvItePdv,0) 
      From PARAM 
     Where Cod_Estabe = @CodEstabe

    Select @StaIntWms = IsNull(cb.Sta_IntWms,''),
           @FlgTipVenFat = Case When ISNull(op.Cod_CfoNorInt,0) > 0 then 1 ELse 0 End
      From PDVCB cb
           Left Join TPOPE op on cb.Tip_Faturamento = op.Cod_Ope 
     Where cb.Cod_Estabe = @CodEstabe and cb.Numero = @CodPed

    Set @FlgPodeFechar = 0
    if @FlgIntWms = 0
      begin
        -- atualiza status PDVCB: 'X"- em processamento
        Update PDVCB
           Set Sta_SepLot = 'X'
         Where Cod_Estabe = @CodEstabe
           And Numero = @CodPed
           And IsNull(Sta_SepLot,'') = ''

        if Exists(Select 1
                    From PDVCB
                   Where Cod_Estabe = @CodEstabe
                     And Numero = @CodPed
                     And IsNull(Sta_SepLot,'') = 'X')
          Set @FlgPodeFechar = 1
      end
    else
      begin
        if @StaIntWms = ''
          Exec PR_WMSGerarXMLSaida @CodEstabe, @CodPed

        Update PDVCB
           Set Sta_IntWMS = '0'
         Where Cod_Estabe = @CodEstabe 
           And Numero = @CodPed
           And IsNull(Sta_IntWMS,'') = ''
      end


    Set @FlgErr = 0
    Set @StrMsg = ''

    if @FlgPodeFechar = 1
      begin 

        IF OBJECT_ID('tempdb..#ARQ_PDVIT') IS NOT NULL
          DROP TABLE #ARQ_PDVIT
        
        CREATE TABLE #ARQ_PDVIT
        (
            Chave int identity,
        	Cod_Produt int,
            Id_PolLot int,
            Fat_CnvImpFat int,
            Qtd_Pdv int
        ) 

        IF OBJECT_ID('tempdb..#ARQ_PRLTL') IS NOT NULL
          DROP TABLE #ARQ_PRLTL
        
        CREATE TABLE #ARQ_PRLTL
        (
            Chave int identity,
        	Cod_Estabe smallint,
            Cod_Dep smallint,
            Num_Rua smallint, 
        	Num_Col smallint, 
        	Num_Niv smallint, 
        	Num_Apt smallint,
        	Tip_LocEnd varchar(1),
            Cod_Produt int,
        	Cod_Lote varchar(20),
            Cod_Fabricante int,
            Dat_Vencim smalldatetime,
            Dat_Entrada smalldatetime,
            Qtd_EmbFec int,
            C_QtdEmbFec int,
            Qtd_Saldo int,
            Qtd_SldPra int,
            Qtd_SldDep int
        ) 
        
        CREATE UNIQUE CLUSTERED INDEX IX_ARQ_PRLTL ON #ARQ_PRLTL (Chave);
        CREATE NONCLUSTERED INDEX IX_ARQ_PRLTL_1 ON #ARQ_PRLTL (Cod_Estabe, Cod_Produt, Dat_Vencim);


        -- popula #ARQ_PDVIT --------------------------------------------------
        Insert into #ARQ_PDVIT
          Select it.Cod_Produto, 
                 IdPolLot = Case
                              When Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = it.Cod_Estabe and pl.Id_PolCom = it.Id_PolCom and pl.Cod_Produt = it.Cod_Produto) then it.Id_PolCom
                              Else 0
                            End, 
                 max(IsNull(it.Fat_CnvImpFat,1)) as FatCnvImpFat,
                 sum(IsNull(it.Qtd_Pedido,0)+IsNull(it.Qtd_Bonificacao,0)) as QtdPdv
            From PDVIT it 
           Where it.Cod_Estabe = @CodEstabe 
             And it.Cod_Pedido = @CodPed
             And IsNull(it.Qtd_Pedido,0) > 0
           Group by it.Cod_Estabe, it.Cod_Produto, it.Id_PolCom

        -- desconta PDVLT já solicitado ---131370
		Declare @cr_CodPrd int,
                @cr_IdPolLot int,
                @cr_QtdLot int

        -- lotes já solicitados
        Declare PDVLT_Cr Cursor Local Fast_Forward For 

          Select Cod_Produt, Id_PolCOm
               , Qtd_Lote = sum(Qtd_Lote)
            From PDVLT
           Where Cod_Estabe = @CodEstabe
             And Cod_Pedido = @CodPed
           Group by Cod_Produt, Id_PolCom
           Order by Cod_Produt, Id_PolCom Desc

        Open PDVLT_Cr  
        Fetch Next From PDVLT_Cr Into @cr_CodPrd, @cr_IdPolLot, @QtdSld
        While @@FETCH_STATUS = 0
          begin
            Set @CodPrd = @cr_CodPrd

            While (@CodPrd = @cr_CodPrd) and (@@FETCH_STATUS = 0)  
              begin

                -- desconta lote diferenciado se houver
                if Exists(Select 1 From #ARQ_PDVIT Where Cod_Produt = @CodPrd 
                             And Id_PolLot = @cr_IdPolLot 
                             And @cr_IdPolLot > 0 And Qtd_Pdv > 0)
                  begin
                    Select @cr_QtdLot = Qtd_Pdv 
                      From #ARQ_PDVIT 
                     Where Cod_Produt = @CodPrd
                       And Id_PolLot = @cr_IdPolLot
                       And Qtd_Pdv > 0

                    Set @QtdMov = Case 
                                    When @cr_QtdLot > @QtdSld then @QtdSld
                                    Else @cr_QtdLot
                                  End

                    Update #ARQ_PDVIT 
                       Set Qtd_Pdv = Qtd_Pdv - @QtdMov
                     Where Cod_Produt = @CodPrd
                       And Id_PolLot = @cr_IdPolLot
                       And @QtdMov >= Qtd_Pdv
                    if @@rowcount > 0
                      Set @QtdSld = @QtdSld - @QtdMov
                  end

                -- desconta restante
                if @QtdSld > 0
                  Set @FlgMov = 1
				   
                while (@QtdSld > 0) and (@FlgMov = 1) and
                      Exists(Select 1 From #ARQ_PDVIT Where Cod_Produt = @CodPrd And Qtd_Pdv > 0)
                  begin
                    Set @FlgMov = 0

                    Select top 1 
                           @cr_IdPolLot = Id_PolLot
                         , @cr_QtdLot = Qtd_Pdv 
                      From #ARQ_PDVIT 
                     Where Cod_Produt = @CodPrd
                       And Qtd_Pdv > 0
                     Order by Id_PolLot desc

                    Set @QtdMov = Case 
                                    When @cr_QtdLot > @QtdSld then @QtdSld
                                    Else @cr_QtdLot
                                  End

                    Update #ARQ_PDVIT 
                       Set Qtd_Pdv = Qtd_Pdv - @QtdMov
                     Where Cod_Produt = @CodPrd
                       And Id_PolLot = @cr_IdPolLot
                       And @QtdMov <= Qtd_Pdv
                    if @@rowcount > 0
                      begin
                        Set @FlgMov = 1
                        Set @QtdSld = @QtdSld - @QtdMov
                      end

                  end -- while (@QtdSld > 0) and (@FlgMov = 1) and

                Fetch Next From PDVLT_Cr Into @cr_CodPrd, @cr_IdPolLot, @QtdSld

              end  -- While (@CodPrd = @cr_CodPrd) and (@@FETCH_STATUS = 0)

            Delete From #ARQ_PDVIT 
             Where Cod_Produt = @CodPrd
               And Qtd_Pdv = 0

          end  -- While @@FETCH_STATUS = 0
          
        Close PDVLT_Cr
        Deallocate PDVLT_Cr
        -- fim popula #ARQ_PRLTL -------------------------------------------------------

        -- popula #ARQ_PRLTL descontando abastecimentos pendentes
        Insert into #ARQ_PRLTL
          Select lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua, lt.Num_Col, lt.Num_Niv, lt.Num_Apt,
                 dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua),
                 lt.Cod_Produt, lt.Cod_Lote, pr.Cod_Fabricante, lt.Dat_Vencim, lt.Dat_Entrada,
                 Qtd_EmbFec  = IsNull(lt.Qtd_EmbFec,0),
                 C_QtdEmbFec = IsNull(lt.C_QtdEmbFec,0),
                 Qtd_Saldo   = IsNull(lt.Qtd_Saldo,0)  - IsNull(ab.C_QtdMov,0),
                 Qtd_SldPra  = IsNull(lt.Qtd_SldPra,0) - IsNull(ab.C_QtdMov,0),
                 Qtd_SldDep  = IsNull(lt.Qtd_SldDep,0)
            From PRLTL lt Inner Join
                 PRODU pr on lt.Cod_Produt = pr.Codigo Left Join
                 ( Select it.Cod_Produt, it.Cod_Lote, it.Cod_Dep, it.Num_Rua, it.Num_Col, it.Num_Niv, it.Num_Apt,
                          C_QtdMov = sum(QTd_Mov)
                     From ABAIT it
                          Inner Join ABACB cb on it.Cod_Estabe = cb.Cod_Estabe and it.Cod_Abaste = cb.Cod_Abaste
                    Where cb.Cod_Estabe = @CodEstabe
                      And cb.Cod_STa = 'A'
                    Group by it.Cod_Produt, it.Cod_Lote, it.Cod_Dep, it.Num_Rua, it.Num_Col, it.Num_Niv, it.Num_Apt
                 ) ab on lt.Cod_Produt = ab.Cod_Produt and lt.Cod_Lote = ab.Cod_Lote and
                         lt.Cod_Dep = ab.Cod_Dep and lt.Num_Rua = ab.Num_Rua and lt.Num_Col = ab.Num_Col and lt.Num_Niv = ab.Num_Niv and lt.Num_Apt = ab.Num_Apt
           Where lt.Cod_Estabe = @CodEstabe
             And (IsNull(lt.Qtd_Saldo,0) - IsNull(ab.C_QtdMov,0)) > 0
             And IsNull(lt.Qtd_EmbFec,0) > 0

        -- normaliza #ARQ_PRLTL
        Update #ARQ_PRLTL
           Set Qtd_SldDep = Qtd_SldDep + Abs(Qtd_SldPra),
               Qtd_SldPra = 0
         Where Qtd_SldPra < 0
        
		-- TBZON
        Update TBZON
           Set Num_Esteira = 1
         Where Cod_Estabe = @CodEstabe
           And ISNULL(Num_Esteira,0) = 0

        Declare @NumVol int,
                @to_CodCfoNorInt int,
                @to_TipOpe varchar(1),
                @pm_FlgBlqCnfTrf bit, 
                @pm_CodOpeWmsDef int,
                @DatVct smalldatetime,
                @DatEnt smalldatetime,
                @CodLot varchar(20),
                @CodLotEsp varchar(20),  -- lote especifico
				@QtdLotSel int,
                @LocEst varchar(1),
                @OrdDep varchar(1),
				@FlgPrePck bit,
                @CodDep int, 
                @CodDepAnt int, 
                @NumEst smallint,
                @NumEstAnt smallint,
                @NumRua int, 
                @NumCol int, 
                @NumNiv int, 
                @NumApt int, 
                @SldLot int,
                @FatCnvAprEmbPad int,
                @QtdPraLot int,
                @QtdDepLot int,
                @QtdDif int,
                @FlgDesord bit,
                @dx_CodLocFis varchar(15),
                @pr_VolUniMin numeric(18,8),  -- @pr_VolEmb
                @cx_CodCxaPad int,
                @cx_VolCxaPad numeric(18,4),
                @cx_NewCodCxaPad int,
                @VolMaxCxa numeric(18,4),
                @VolTotIte numeric(18,4),
                @VolAcu numeric(18,4),
                @QtdAteAcu int,
                @QtdAte int,
                @Per numeric(18,8)

        Select @cl_CodCliPag = Case 
                                 When IsNull(cl.Cod_CliPag,0) > 0 then cl.Cod_CliPag
                                 Else cl.Codigo
                               End,
               @cl_QtdMesMinPrzVctLot = IsNull(cl.Qtd_MesMinPrzVctLot,0),
               @cl_CodGrpCli = cl.Cod_GrpCli,
			   @cl_FlgBlqLotVarPdv = IsNull(Flg_BlqLotVarPdv,0)
          From CLIEN cl Inner Join PDVCB cb on (cb.Cod_Cliente = cl.Codigo)
         Where cb.Cod_Estabe = @CodEstabe 
           And cb.Numero = @CodPed
          
        if @cl_CodCliPag is null Set @cl_CodCliPag = 0
        if @cl_QtdMesMinPrzVctLot is null Set @cl_QtdMesMinPrzVctLot = 0
        if @cl_CodGrpCli is null Set @cl_CodGrpCli = 0
                     
        Select @to_CodCfoNorInt = IsNull(t.Cod_CfoNorInt,0),
               @to_TipOpe = IsNull(t.Tip_Ope,'')
          From TPOPE t Inner Join PDVCB p on (t.Cod_Ope = p.Tip_Faturamento)
         Where p.Cod_Estabe = @CodEstabe 
           And p.Numero = @CodPed

        Select @pm_FlgBlqCnfTrf = IsNull(FlgBlqCnfTrf,0), 
               @pm_CodOpeWmsDef = IsNull(CodOpeWmsDef,0) 
          From PMEST
         Where Cod_Estabe = @CodEstabe  

        -- pega o último volume de caixa fechada, se já existir
        Set @NumVol = IsNull((Select max(Num_Vol)
                                From PDVLT 
                               Where Cod_Estabe = @CodEstabe 
                                 And Cod_Pedido = @CodPed
                                 And ((Cod_LocFis = 'PRLTL') And (Qtd_CxaFec > 0))),0)	

        -- negativa volumes fracionados pré-existentes
        Update PDVLT
           Set Num_Vol = -1
         Where Cod_Estabe = @CodEstabe 
           And Cod_Pedido = @CodPed
           And ((Cod_LocFis <> 'PRLTL') or (Qtd_CxaFec > 0))


        -- elimina registro de conferencia existentes
        Delete from CPVIT Where Cod_Estabe = @CodEstabe And Num_PedCnf = @CodPed

        Delete from CPVCB Where Cod_Estabe = @CodEstabe And Num_PedCnf = @CodPed
          
        -- **************************************************  solicita lotes (CAIXA FECHADA) por vencimento do DEPOSITO FECHADO  ******************************************************************
        Declare PDVIT_Cr Cursor Local Fast_Forward For 

          Select Cod_Produt, Id_PolLot, Fat_CnvImpFat, Qtd_Pdv
            From #ARQ_PDVIT

        Open PDVIT_Cr  
        Fetch Next From PDVIT_Cr Into @CodPrd, @IdPolLot, @FatCnvImpFat, @QtdPdv
        While @@FETCH_STATUS = 0  
          begin
            -- nao permite negativar estoque fiscal
            if (@BlqEstFisNeg = 1) and (@FlgTipVenFat = 1)
              begin
                Set @QtdSldFiscal = dbo.FN_SldFiscalDisponPrd(@CodEstabe,@CodPrd)
                if @QtdPdv > @QtdSldFiscal 
                  Set @QtdPdv = @QtdSldFiscal
              end

            if @FlgUndMin = 0
              begin
                Select @pr_VolUniMin = IsNull(Vol_Emb,0)
                  From PRODU
                 Where Codigo = @CodPrd
              end
            else
            -- volume da embalagem Unidade minima
              begin
                Select @pr_VolUniMin = IsNull(Vol_Emb/Fat_CnvApr,0)
                  From PRXAP
                 Where Cod_Produt = @CodPrd
				   And Flg_Padrao = 1
              end

            -- verifica atendimento lote especifico
			Set @QtdLotSel = 0

            Set @QtdFra = @QtdPdv  
            -------------------------------------------------------------------------------------------------------------------------------------------------------
            if @to_CodCfoNorInt > 0
              begin
                -- venda FAT estoque compartilhado
                Declare PRLTL_Cr Cursor Local Fast_Forward For 

                  Select '1' as CodLocEst, lt.OrdDep, lt.Dat_Vencim, lt.Flg_PrePck, lt.Dat_Entrada, lt.Cod_Lote, lt.Qtd_EmbFec, lt.Qtd_EmbFecCal, 
                         lt.Cod_Dep, lt.Num_Rua, lt.Num_Col, lt.Num_Niv, lt.Num_Apt, lt.Qtd_SldPra
                    From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Produt, l1.Cod_Fabricante, l1.Dat_Vencim, Flg_PrePck=IsNull(e1.Flg_PrePck,0), l1.Dat_Entrada, l1.Cod_Lote, Qtd_EmbFec=IsNull(l1.Qtd_EmbFec,0), Qtd_EmbFecCal=IsNull(l1.C_QtdEmbFec,0),
                                 l1.Cod_Dep, l1.Num_Rua, l1.Num_Col, l1.Num_Niv, l1.Num_Apt, Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldPra=IsNull(l1.Qtd_SldPra,0) 
                            From #ARQ_PRLTL l1 Inner Join 
                                 DPXGC de on (l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli) Left Join
							     ENDDP e1 on (l1.Cod_Estabe = e1.Cod_Estabe and l1.Cod_Dep = e1.Cod_Dep and l1.Num_Rua = e1.Num_Rua and
								              l1.Num_Col = e1.Num_Col and l1.Num_Niv = e1.Num_Niv and l1.Num_Apt = e1.Num_Apt)
                           Where l1.Cod_Estabe = @CodEstabe 
                             And IsNull(l1.Qtd_SldPra,0) >= IsNull(l1.C_QtdEmbFec,0)
                          UNION ALL
                          Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Produt, l2.Cod_Fabricante, l2.Dat_Vencim, Flg_PrePck=IsNull(e2.Flg_PrePck,0), l2.Dat_Entrada, l2.Cod_Lote, Qtd_EmbFec=IsNull(l2.Qtd_EmbFec,0), Qtd_EmbFecCal=IsNull(l2.C_QtdEmbFec,0), 
                                 l2.Cod_Dep, l2.Num_Rua, l2.Num_Col, l2.Num_Niv, l2.Num_Apt, Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldPra=IsNull(l2.Qtd_SldPra,0) 
                            From #ARQ_PRLTL l2 Left Join
							     ENDDP e2 on (l2.Cod_Estabe = e2.Cod_Estabe and l2.Cod_Dep = e2.Cod_Dep and l2.Num_Rua = e2.Num_Rua and
								              l2.Num_Col = e2.Num_Col and l2.Num_Niv = e2.Num_Niv and l2.Num_Apt = e2.Num_Apt)
                           Where l2.Cod_Estabe = @CodEstabe 
                             And IsNull(l2.Qtd_SldPra,0) >= IsNull(l2.C_QtdEmbFec,0)
						     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Left Join
                         CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = lt.Cod_Produt Left Join
                         CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = lt.Cod_Fabricante
                   Where lt.Cod_Estabe = @CodEstabe 
                     And lt.Cod_Produt = @CodPrd
                     And IsNull(lt.Qtd_EmbFecCal,0) > 0 
                     And IsNull(lt.Qtd_Saldo,0) >= IsNull(lt.Qtd_EmbFecCal,0) 
                     And dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua) = 'D'
                     And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                                 (lt.Dat_Vencim >= Case
                                                                     When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                     When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                     Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                                   End))) or
                           ((@IdPolLot > 0) and 
                            Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                     and IsNull(lt.Qtd_SldPra,0) > 0
                     and @QtdPdv >= IsNull(lt.Qtd_EmbFecCal,0) 
                  UNION ALL
                  Select '2' as CodLocEst, lt.OrdDep, lt.Dat_Vencim, lt.Flg_PrePck, lt.Dat_Entrada, lt.Cod_Lote, lt.Qtd_EmbFec, lt.Qtd_EmbFecCal,
                         lt.Cod_Dep, lt.Num_Rua, lt.Num_Col, lt.Num_Niv, lt.Num_Apt, IsNull(lt.Qtd_SldDep,0) 
                    From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Produt, l1.Cod_Fabricante, l1.Dat_Vencim, Flg_PrePck=IsNull(e1.Flg_PrePck,0), l1.Dat_Entrada, l1.Cod_Lote, Qtd_EmbFec=IsNull(l1.Qtd_EmbFec,0), Qtd_EmbFecCal=IsNull(l1.C_QtdEmbFec,0),
                                 l1.Cod_Dep, l1.Num_Rua, l1.Num_Col, l1.Num_Niv, l1.Num_Apt, Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldDep=IsNull(l1.Qtd_SldDep,0) 
                            From #ARQ_PRLTL l1 Inner Join 
                                 DPXGC de on (l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli) Left Join
							     ENDDP e1 on (l1.Cod_Estabe = e1.Cod_Estabe and l1.Cod_Dep = e1.Cod_Dep and l1.Num_Rua = e1.Num_Rua and
								              l1.Num_Col = e1.Num_Col and l1.Num_Niv = e1.Num_Niv and l1.Num_Apt = e1.Num_Apt)
                           Where l1.Cod_Estabe = @CodEstabe 
                             And IsNull(l1.Qtd_SldDep,0) >= IsNull(l1.C_QtdEmbFec,0) 
                          UNION ALL
                          Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Produt, l2.Cod_Fabricante, l2.Dat_Vencim, Flg_PrePck=IsNull(e2.Flg_PrePck,0), l2.Dat_Entrada, l2.Cod_Lote, Qtd_EmbFec=IsNull(l2.Qtd_EmbFec,0), Qtd_EmbFecCal=IsNull(l2.C_QtdEmbFec,0), 
                                 l2.Cod_Dep, l2.Num_Rua, l2.Num_Col, l2.Num_Niv, l2.Num_Apt, Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldDep=IsNull(l2.Qtd_SldDep,0) 
                            From #ARQ_PRLTL l2 Left Join
							     ENDDP e2 on (l2.Cod_Estabe = e2.Cod_Estabe and l2.Cod_Dep = e2.Cod_Dep and l2.Num_Rua = e2.Num_Rua and
								              l2.Num_Col = e2.Num_Col and l2.Num_Niv = e2.Num_Niv and l2.Num_Apt = e2.Num_Apt)
                           Where l2.Cod_Estabe = @CodEstabe 
                             And IsNull(l2.Qtd_SldDep,0) >= IsNull(l2.C_QtdEmbFec,0)  
						     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Left Join
                         CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = lt.Cod_Produt Left Join
                         CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = lt.Cod_Fabricante
                   Where lt.Cod_Estabe = @CodEstabe 
                     And lt.Cod_Produt = @CodPrd  
                     And IsNull(lt.Qtd_EmbFecCal,0) > 0 
                     And IsNull(lt.Qtd_Saldo,0) >= IsNull(lt.Qtd_EmbFecCal,0) 
                     And dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua) = 'D'
                     And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                                 (lt.Dat_Vencim >= Case
                                                                     When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                     When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                     Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                                   End))) or
                           ((@IdPolLot > 0) and 
                            Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                     And IsNull(lt.Qtd_SldDep,0) > 0
                     And @QtdPdv >= IsNull(lt.Qtd_EmbFecCal,0) 
                   Order by OrdDep, CodLocEst, Dat_Vencim, Flg_PrePck desc, Num_Rua, Num_Niv, Num_Apt, Num_Col, Cod_Lote, Dat_Entrada
				   --        1,2       1,2
              end
            else
              begin
                -- venda ORC estoque compartilhado
                Declare PRLTL_Cr Cursor Local Fast_Forward For 
                  Select '2' as CodLocEst, lt.OrdDep, lt.Dat_Vencim, lt.Flg_PrePck, lt.Dat_Entrada, lt.Cod_Lote, lt.Qtd_EmbFec, lt.Qtd_EmbFecCal,
                         lt.Cod_Dep, lt.Num_Rua, lt.Num_Col, lt.Num_Niv, lt.Num_Apt, lt.Qtd_SldDep
                    From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Produt, l1.Cod_Fabricante, l1.Dat_Vencim, Flg_PrePck=IsNull(e1.Flg_PrePck,0), l1.Dat_Entrada, l1.Cod_Lote, Qtd_EmbFec=IsNull(l1.Qtd_EmbFec,0), Qtd_EmbFecCal=IsNull(l1.C_QtdEmbFec,0), 
                                 l1.Cod_Dep, l1.Num_Rua, l1.Num_Col, l1.Num_Niv, l1.Num_Apt, Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldDep=IsNull(l1.Qtd_SldDep,0) 
                            From #ARQ_PRLTL l1 Inner Join 
                                 DPXGC de on (l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli) Left Join
							     ENDDP e1 on (l1.Cod_Estabe = e1.Cod_Estabe and l1.Cod_Dep = e1.Cod_Dep and l1.Num_Rua = e1.Num_Rua and
								              l1.Num_Col = e1.Num_Col and l1.Num_Niv = e1.Num_Niv and l1.Num_Apt = e1.Num_Apt)
                           Where l1.Cod_Estabe = @CodEstabe 
                             And IsNull(l1.Qtd_SldDep,0) >= IsNull(l1.C_QtdEmbFec,0)
                          UNION ALL
                          Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Produt, l2.Cod_Fabricante, l2.Dat_Vencim, Flg_PrePck=IsNull(e2.Flg_PrePck,0), l2.Dat_Entrada, l2.Cod_Lote, Qtd_EmbFec=IsNull(l2.Qtd_EmbFec,0), Qtd_EmbFecCal=IsNull(l2.C_QtdEmbFec,0),
                                 l2.Cod_Dep, l2.Num_Rua, l2.Num_Col, l2.Num_Niv, l2.Num_Apt, Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldDep=IsNull(l2.Qtd_SldDep,0) 
                            From #ARQ_PRLTL l2 Left Join
							     ENDDP e2 on (l2.Cod_Estabe = e2.Cod_Estabe and l2.Cod_Dep = e2.Cod_Dep and l2.Num_Rua = e2.Num_Rua and
								              l2.Num_Col = e2.Num_Col and l2.Num_Niv = e2.Num_Niv and l2.Num_Apt = e2.Num_Apt)
                           Where l2.Cod_Estabe = @CodEstabe 
                             And IsNull(l2.Qtd_SldDep,0) >= IsNull(l2.C_QtdEmbFec,0)
						     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Left Join
                         CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = lt.Cod_Produt Left Join
                         CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = lt.Cod_Fabricante
                   Where lt.Cod_Estabe = @CodEstabe 
                     And lt.Cod_Produt = @CodPrd
                     And IsNull(lt.Qtd_EmbFecCal,0) > 0 
                     And IsNull(lt.Qtd_Saldo,0) >= IsNull(lt.Qtd_EmbFecCal,0) 
                     And dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua) = 'D'
                     And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                                 (lt.Dat_Vencim >= Case
                                                                     When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                     When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                     Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                                   End))) or
                           ((@IdPolLot > 0) and 
                            Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                     And IsNull(lt.Qtd_SldDep,0) > 0
                     And @QtdPdv >= IsNull(lt.Qtd_EmbFecCal,0) 
                  UNION ALL
                  Select '1' as CodLocEst, lt.OrdDep, lt.Dat_Vencim, lt.Flg_PrePck, lt.Dat_Entrada, lt.Cod_Lote, lt.Qtd_EmbFec, lt.Qtd_EmbFecCal,
                         lt.Cod_Dep, lt.Num_Rua, lt.Num_Col, lt.Num_Niv, lt.Num_Apt, lt.Qtd_SldPra
                    From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Produt, l1.Cod_Fabricante, l1.Dat_Vencim, Flg_PrePck=IsNull(e1.Flg_PrePck,0), l1.Dat_Entrada, l1.Cod_Lote, Qtd_EmbFec=IsNull(l1.Qtd_EmbFec,0), Qtd_EmbFecCal=IsNull(l1.C_QtdEmbFec,0), 
                                 l1.Cod_Dep, l1.Num_Rua, l1.Num_Col, l1.Num_Niv, l1.Num_Apt, Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldPra=IsNull(l1.Qtd_SldPra,0) 
                            From #ARQ_PRLTL l1 Inner Join 
                                 DPXGC de on (l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli) Left Join
							     ENDDP e1 on (l1.Cod_Estabe = e1.Cod_Estabe and l1.Cod_Dep = e1.Cod_Dep and l1.Num_Rua = e1.Num_Rua and
								              l1.Num_Col = e1.Num_Col and l1.Num_Niv = e1.Num_Niv and l1.Num_Apt = e1.Num_Apt)
                           Where l1.Cod_Estabe = @CodEstabe 
                            And IsNull(l1.Qtd_SldPra,0) >= IsNull(l1.C_QtdEmbFec,0)
                          UNION ALL
                          Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Produt, l2.Cod_Fabricante, l2.Dat_Vencim, Flg_PrePck=IsNull(e2.Flg_PrePck,0), l2.Dat_Entrada, l2.Cod_Lote, Qtd_EmbFec=IsNull(l2.Qtd_EmbFec,0), Qtd_EmbFecCal=IsNull(l2.C_QtdEmbFec,0),
                                 l2.Cod_Dep, l2.Num_Rua, l2.Num_Col, l2.Num_Niv, l2.Num_Apt, Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldPra=IsNull(l2.Qtd_SldPra,0) 
                            From #ARQ_PRLTL l2 Left Join
							     ENDDP e2 on (l2.Cod_Estabe = e2.Cod_Estabe and l2.Cod_Dep = e2.Cod_Dep and l2.Num_Rua = e2.Num_Rua and
								              l2.Num_Col = e2.Num_Col and l2.Num_Niv = e2.Num_Niv and l2.Num_Apt = e2.Num_Apt)
                           Where l2.Cod_Estabe = @CodEstabe 
                             And IsNull(l2.Qtd_SldPra,0) >= IsNull(l2.C_QtdEmbFec,0)
						     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Left Join
                         CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = lt.Cod_Produt Left Join
                         CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = lt.Cod_Fabricante
                   Where lt.Cod_Estabe = @CodEstabe 
                     And lt.Cod_Produt = @CodPrd
                     And IsNull(lt.Qtd_EmbFecCal,0) > 0 
                     And IsNull(lt.Qtd_Saldo,0) >= IsNull(lt.Qtd_EmbFecCal,0) 
                     And dbo.FN_TipLocEnd(lt.Cod_Estabe, lt.Cod_Dep, lt.Num_Rua) = 'D'
                     And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                                 (lt.Dat_Vencim >= Case
                                                                     When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                     When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                     Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                                   End))) or
                           ((@IdPolLot > 0) and 
                            Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                     And IsNull(lt.Qtd_SldPra,0) > 0
                     And @QtdPdv >= IsNull(lt.Qtd_EmbFecCal,0) 
                   Order by OrdDep, CodLocEst desc, Dat_Vencim, Flg_PrePck desc, Num_Rua, Num_Niv, Num_Apt, Num_Col, Cod_Lote, Dat_Entrada
              end
            -------------------------------------------------------------------------------------------------------------------------------------------------------
            Open PRLTL_Cr
            Fetch Next From PRLTL_Cr Into @LocEst, @OrdDep, @DatVct, @FlgPrePck, @DatEnt, @CodLot, @QtdEmbFec, @QtdEmbFecCal,
                                          @CodDep, @NumRua, @NumCol, @NumNiv,@NumApt, @SldLot 

            While @@FETCH_STATUS = 0
              begin
                -- ajusta saldo do lote : proporcional a fator de conversão DMD-7954: 30/03/2023
                Set @SldLot = (@SldLot/@FatCnvImpFat) * @FatCnvImpFat

                -- verifica lote unico
                Set @QtdLotSel = @QtdLotSel + 1
                if (@cl_FlgBlqLotVarPdv = 1) and (@QtdLotSel > 1)
                  Break

                if (@QtdFra > 0) and (@QtdFra >= @QtdEmbFecCal) and (@SldLot >= @QtdEmbFecCal)
                  begin
                    Set @QtdCxaFec = Case 
                                       When @SldLot < @QtdFra Then @SldLot / @QtdEmbFecCal
                                       Else @QtdFra / @QtdEmbFecCal
                                     End

                    Set @QtdUndLot = @QtdCxaFec * @QtdEmbFecCal

                    -- decrementa saldo em PRLTL
                    Set @QtdPraLot = 0
                    Set @QtdDepLot = 0
                    if @LocEst = '1'
                      Set @QtdPraLot = @QtdUndLot
                    else
                      Set @QtdDepLot = @QtdUndLot

                    Update PRLTL
                       Set Qtd_SolPra = IsNull(Qtd_SolPra,0) + @QtdPraLot,
                           Qtd_SolDep = IsNull(Qtd_SolDep,0) + @QtdDepLot
                     Where Cod_Estabe = @CodEstabe 
                       And Cod_Produt = @CodPrd
                       And Cod_Lote = @CodLot
                       And Qtd_EmbFec = @QtdEmbFec 
                       And Cod_Dep =  @CodDep
                       And Num_Rua = @NumRua
                       And Num_Col = @NumCol
                       And Num_Niv = @NumNiv
                       And Num_Apt = @NumApt

                    Set @QtdFra = @QtdFra - @QtdUndLot
                    Set @SldLot = @SldLot - @QtdUndLot

                    -- grava registro em PDVLT 
                    Set @VolTotIte = @QtdUndLot*@pr_VolUniMin
                    Set @FlgDesord = 0

					if (@QtdPraLot+@QtdDepLot) > 0
                      begin
					    --Set @NumEst = IsNull((Select z.Num_Esteira From TBZON z Where z.Cod_Estabe = @CodEstabe and @NumRua between z.Num_RuaIni and z.Num_RuaFim),0)
						Set @NumEst = IsNull((Select z.Num_Esteira From TBZON z Where z.Cod_Estabe = @CodEstabe and Cod_Dep = @CodDep and @NumRua between z.Num_RuaIni and z.Num_RuaFim),0)

                        -- caixa fechada: sempre um novo volume
                        Set @NumVol = @NumVol + 1
                        if @NumVol = 0 Set @NumVol = 1

                        if Exists(Select 1 From PDVLT 
                                   Where Cod_Estabe = @CodEstabe 
                                     And Cod_Pedido = @CodPed And Num_Vol = @NumVol) 
                          Set @NumVol = @NumVol + 1

                        -- caixa fechada: PDVLT.Cod_LocFis = 'PRLTL',  PDVLT.Qtd_CxaFec > 0
                        Insert Into PDVLT (Cod_Estabe, Cod_Pedido, Num_Vol, Cod_Produt, Cod_Lote
                                        ,  Qtd_EmbFec, Fat_CnvAprEmbPad, Qtd_Lote, Qtd_CxaFec
                                        ,  Cod_Dep, Num_Esteira, Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_LocFis
                                        ,  Qtd_LotePra, Qtd_LoteDep, Vol_TotIte, Id_PolCom, Flg_Desord, Flg_Manual
                                        ,  Cod_FunSep, Transacao)
                                   Values (@CodEstabe, @CodPed, @NumVol, @CodPrd, @CodLot
                                        ,  @QtdEmbFec, @QtdEmbFecCal, @QtdUndLot, @QtdCxaFec
                                        ,  @CodDep, @NumEst, @NumRua, @NumCol, @NumNiv, @NumApt, 'PRLTL'
                                        ,  @QtdPraLot, @QtdDepLot, @VolTotIte, @IdPolLot, @FlgDesord, 0
                                        ,  0, @Now )
                        if @@error <> 0
                          begin
                            Rollback Transaction
                            Return
                          end
                      end

                  end -- if (@QtdFra > 0) and (@QtdFra >= @QtdEmbFec) and (@SldLot >= @QtdEmbFec) 

                Fetch Next From PRLTL_Cr Into @LocEst, @OrdDep, @DatVct, @FlgPrePck, @DatEnt, @CodLot, @QtdEmbFec, @QtdEmbFecCal,
                                              @CodDep, @NumRua, @NumCol, @NumNiv, @NumApt, @SldLot 
              end    -- While @@FETCH_STATUS = 0
              
            Close PRLTL_Cr
            Deallocate PRLTL_Cr

            Fetch Next From PDVIT_Cr Into @CodPrd, @IdPolLot, @FatCnvImpFat, @QtdPdv
          end  -- While @@FETCH_STATUS = 0
          
        Close PDVIT_Cr
        Deallocate PDVIT_Cr
        
--------  FIM SOLICITA CAIXA FECHADA PULMAO --------------------------------------------------------------------------------------------------------------


        -- **************************************************  solicita lotes fracionados por vencimento do PICKING  ******************************************************************
        -- unico volume para fracionados
        Set @NumVol = @NumVol + 1

        -- ajusta volumes fracionados pré-existentes negativados
        Update PDVLT
           Set Num_Vol = @NumVol
         Where Cod_Estabe = @CodEstabe 
           And Cod_Pedido = @CodPed
           And Num_Vol < 0

        if @FlgUndMin = 0
          begin
            Declare PDVIT_Cr Cursor Local Fast_Forward For 
              Select x.Cod_Produt, x.IdPolLot, pr.Qtd_Embalagem, IsNull(pr.Vol_Emb,0), x.QtdFra,
                     FatCnvImpFat = IsNull((Select max(IsNull(Fat_CnvImpFat,1)) From #ARQ_PDVIT Where Cod_Produt = x.Cod_Produt and Id_PolLot = x.IdPolLot),1)     
				From (Select it.Cod_Produt, it.IdPolLot, (it.QtdPdv-IsNull(d.QtdLot,0)) as QtdFra
                        From (Select a.Cod_Produt, 
                                     IdPolLot = Case
                                                  When Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = @CodEstabe and pl.Id_PolCom = a.Id_PolLot and pl.Cod_Produt = a.Cod_Produt) then a.Id_PolLot
                                                  Else 0
                                                End,
                                     sum(IsNull(a.Qtd_Pdv,0)) as QtdPdv
                                From #ARQ_PDVIT a
                               Where IsNull(a.Qtd_Pdv,0) > 0
                               Group by a.Cod_Produt, a.Id_PolLot) it Left Outer Join

                             (Select b.Cod_Produt, 
                                     IdPolLot = Case
                                                  When Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = b.Cod_Estabe and pl.Id_PolCom = b.Id_PolCom and pl.Cod_Produt = b.Cod_Produt) then b.Id_PolCom
                                                  Else 0
                                                End,
                                     sum(IsNull(b.Qtd_Lote,0)) as QtdLot
                                From PDVLT b
                               Where b.Cod_Estabe = @CodEstabe
                                 And b.Cod_Pedido = @CodPed
                                 And IsNull(b.Qtd_Lote,0) > 0 
                                 And IsNull(b.Qtd_CxaFec,0) > 0   
                               Group by b.Cod_Estabe, b.Cod_Produt, b.Id_PolCom) d on (it.Cod_Produt = d.Cod_Produt and it.IdPolLot = d.IdPolLot)
                            
                       Where (it.QtdPdv-IsNull(d.QtdLot,0)) > 0) x  

                     Inner Join PRODU pr on x.Cod_Produt = pr.Codigo
          end
        else
          begin
            -- trabalha com unidade minima
            Declare PDVIT_Cr Cursor Local Fast_Forward For 
              Select x.Cod_Produt, x.IdPolLot, pr.Qtd_Embalagem, IsNull(ap.Vol_Emb/ap.Fat_CnvApr,0), x.QtdFra,
                     FatCnvImpFat = IsNull((Select max(IsNull(Fat_CnvImpFat,1)) From #ARQ_PDVIT Where Cod_Produt = x.Cod_Produt and Id_PolLot = x.IdPolLot),1)     
                From (Select it.Cod_Produt, it.IdPolLot, (it.QtdPdv-IsNull(d.QtdLot,0)) as QtdFra  -- it.Cod_Estabe, 
                        From (Select a.Cod_Produt, 
                                     IdPolLot = Case
                                                  When Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = @CodEstabe and pl.Id_PolCom = a.Id_PolLot and pl.Cod_Produt = a.Cod_Produt) then a.Id_PolLot
                                                  Else 0
                                                End,
                                     sum(IsNull(a.Qtd_Pdv,0)) as QtdPdv
                                From #ARQ_PDVIT a
                               Where IsNull(a.Qtd_Pdv,0) > 0
                               Group by a.Cod_Produt, a.Id_PolLot) it Left Outer Join
                 
                             (Select b.Cod_Produt,
                                     IdPolLot = Case
                                                  When Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = b.Cod_Estabe and pl.Id_PolCom = b.Id_PolCom and pl.Cod_Produt = b.Cod_Produt) then b.Id_PolCom
                                                  Else 0
                                                End,
                                     sum(IsNull(b.Qtd_Lote,0)) as QtdLot
                                From PDVLT b
                               Where b.Cod_Estabe = @CodEstabe
                                 And b.Cod_Pedido = @CodPed
                                 And IsNull(b.Qtd_Lote,0) > 0 
                                 And IsNull(b.Qtd_CxaFec,0) > 0   
                               Group by b.Cod_Estabe, b.Cod_Produt, b.Id_PolCom) d on (it.Cod_Produt = d.Cod_Produt and it.IdPolLot = d.IdPolLot)

                       Where (it.QtdPdv-IsNull(d.QtdLot,0)) > 0) x  

                     Inner Join PRODU pr on x.Cod_Produt = pr.Codigo
					 Inner Join PRXAP ap on pr.Codigo = ap.Cod_Produt and ap.Flg_Padrao = 1
          end
                 
        Open PDVIT_Cr
        Fetch Next From PDVIT_Cr Into @CodPrd, @IdPolLot, @QtdEmbFec, @pr_VolUniMin, @QtdFra, @FatCnvImpFat
                           
        While @@FETCH_STATUS = 0
          begin
			if @FatCnvImpFat = 0 Set @FatCnvImpFat = 1

            -- nao permite negativar estoque fiscal
            if (@BlqEstFisNeg = 1) and (@FlgTipVenFat = 1)
              begin
                -- qtd solicitada anteriormente (cx fexhada)
                Set @QtdSolPulmao = IsNull((Select sum(Qtd_Lote) From PDVLT Where Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed 
                                               And Cod_Produt = @CodPrd And Cod_LocFis = 'PRLTL'),0)
                Set @QtdSldFiscal = dbo.FN_SldFiscalDisponPrd(@CodEstabe,@CodPrd) - @QtdSolPulmao
                if @QtdSldFiscal < 0 Set @QtdSldFiscal = 0
                if @QtdFra > @QtdSldFiscal 
                  Set @QtdFra = @QtdSldFiscal
              end
 
            Set @QtdAteAcu = 0    -- acumulador por produto
           
            -- verifica atendimento lote unico
            Set @CodLotEsp = ''
            Set @QtdLotSel = 0
			if (@cl_FlgBlqLotVarPdv = 1) and 
               Exists(Select 1 From PDVLT WHere Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed And Cod_Produt = @CodPrd) 
              Set @CodLotEsp = (Select top 1 Cod_Lote From PDVLT WHere Cod_Estabe = @CodEstabe And Cod_Pedido = @CodPed And Cod_Produt = @CodPrd)

            -- fracionados solicita somente pelo vencimento --
            if @to_CodCfoNorInt > 0
              begin
                Declare PRLOT_Cr Cursor Local Fast_Forward For   
                  Select '1' as CodLocEst, lt.OrdDep, lt.Cod_Dep, lt.Dat_Vencim, lt.Cod_Lote, lt.Qtd_SldPra, lt.Fat_CnvAprEmbPad
                    From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Dep, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote, 
                                 Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldPra=IsNull(l1.Qtd_SldPra,0), Fat_CnvAprEmbPad=IsNull(l1.Fat_CnvAprEmbPad,0) 
                            From PRLOT l1 Inner Join
                                 DPXGC de on l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli
                           Where l1.Cod_Estabe = @CodEstabe 
                             And IsNull(l1.Qtd_Saldo,0) > 0 
                             and IsNull(l1.Qtd_SldPra,0) > 0
                          UNION ALL
                          Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Dep, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote, 
                                 Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldPra=IsNull(l2.Qtd_SldPra,0), Fat_CnvAprEmbPad=IsNull(l2.Fat_CnvAprEmbPad,0)
                            From PRLOT l2 
                           Where l2.Cod_Estabe = @CodEstabe 
                             And IsNull(l2.Qtd_Saldo,0) > 0 
                             And IsNull(l2.Qtd_SldPra,0) > 0
                          --And Cod_Dep not in (Select distinct Cod_Dep From DPXGC Where Cod_Estabe = @CodEstabe)) lt Inner Join 
						     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Inner Join 
                         PRODU pr on lt.Cod_Produt = pr.Codigo Left Outer Join
                         CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                         CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
                   Where lt.Cod_Estabe = @CodEstabe 
                     And lt.Cod_Produt = @CodPrd
					 And ((@CodLotEsp = '') or 
                          ((@CodLotEsp <> '') and (lt.Cod_Lote = @CodLotEsp)))
                     And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                                 (lt.Dat_Vencim >= Case
                                                                     When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                     When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                     Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                                   End))) or
                           ((@IdPolLot > 0) and 
                            Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                     And IsNull(lt.Qtd_Saldo,0) > 0 
                     And IsNull(lt.Qtd_SldPra,0) > 0
                  UNION ALL
                  Select '2' as CodLocEst, lt.OrdDep, lt.Cod_Dep, lt.Dat_Vencim, lt.Cod_Lote, lt.Qtd_SldDep, lt.Fat_CnvAprEmbPad
                    From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Dep, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote, 
                                 Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldDep=IsNull(l1.Qtd_SldDep,0), Fat_CnvAprEmbPad=IsNull(l1.Fat_CnvAprEmbPad,0) 
                            From PRLOT l1 Inner Join
                                 DPXGC de on l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli
                           Where l1.Cod_Estabe = @CodEstabe 
                             And IsNull(l1.Qtd_Saldo,0) > 0 
                             And IsNull(l1.Qtd_SldDep,0) > 0
                          UNION ALL
                          Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Dep, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote, 
                                 Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldDep=IsNull(l2.Qtd_SldDep,0), Fat_CnvAprEmbPad=IsNull(l2.Fat_CnvAprEmbPad,0)
                            From PRLOT l2 
                           Where l2.Cod_Estabe = @CodEstabe 
                             And IsNull(l2.Qtd_Saldo,0) > 0 
                             And IsNull(l2.Qtd_SldDep,0) > 0
                          --And Cod_Dep not in (Select distinct Cod_Dep From DPXGC Where Cod_Estabe = @CodEstabe)) lt Inner Join 
						     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Inner Join 
                         PRODU pr on lt.Cod_Produt = pr.Codigo Left Outer Join
                         CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                         CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
                   Where lt.Cod_Estabe = @CodEstabe 
                     And lt.Cod_Produt = @CodPrd
					 And ((@CodLotEsp = '') or 
                          ((@CodLotEsp <> '') and (lt.Cod_Lote = @CodLotEsp)))
                     And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                                 (lt.Dat_Vencim >= Case
                                                                     When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                     When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                     Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                                   End))) or
                           ((@IdPolLot > 0) and 
                            Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                     And IsNull(lt.Qtd_Saldo,0) > 0 
                     And IsNull(lt.Qtd_SldDep,0) > 0
                   Order by OrdDep, Dat_Vencim, CodLocEst
              end
            else
              begin
                Declare PRLOT_Cr Cursor Local Fast_Forward For 
                  Select '1' as CodLocEst, lt.OrdDep, lt.Cod_Dep, lt.Dat_Vencim, lt.Cod_Lote, lt.Qtd_SldPra, lt.Fat_CnvAprEmbPad
                    From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Dep, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote, 
                                 Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldPra=IsNull(l1.Qtd_SldPra,0), Fat_CnvAprEmbPad=IsNull(l1.Fat_CnvAprEmbPad,0) 
                            From PRLOT l1 Inner Join
                                 DPXGC de on l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli
                           Where l1.Cod_Estabe = @CodEstabe 
                             And IsNull(l1.Qtd_Saldo,0) > 0 
                             And IsNull(l1.Qtd_SldPra,0) > 0
                          UNION ALL
                          Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Dep, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote, 
                                 Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldPra=IsNull(l2.Qtd_SldPra,0), Fat_CnvAprEmbPad=IsNull(l2.Fat_CnvAprEmbPad,0) 
                            From PRLOT l2 
                           Where l2.Cod_Estabe = @CodEstabe 
                             And IsNull(l2.Qtd_Saldo,0) > 0 
                             And IsNull(l2.Qtd_SldPra,0) > 0
                          --And Cod_Dep not in (Select distinct Cod_Dep From DPXGC Where Cod_Estabe = @CodEstabe)) lt Inner Join 
						     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Inner Join 
                         PRODU pr on lt.Cod_Produt = pr.Codigo Left Outer Join
                         CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                         CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
                   Where lt.Cod_Estabe = @CodEstabe 
                     And lt.Cod_Produt = @CodPrd
					 And ((@CodLotEsp = '') or 
                          ((@CodLotEsp <> '') and (lt.Cod_Lote = @CodLotEsp)))
                     And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                                 (lt.Dat_Vencim >= Case
                                                                     When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                     When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                     Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                                   End))) or
                           ((@IdPolLot > 0) and 
                            Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                     And IsNull(lt.Qtd_Saldo,0) > 0 
                     And IsNull(lt.Qtd_SldPra,0) > 0
                  UNION ALL
                  Select '2' as CodLocEst, lt.OrdDep, lt.Cod_Dep, lt.Dat_Vencim, lt.Cod_Lote, lt.Qtd_SldDep, lt.Fat_CnvAprEmbPad
                    From (Select '1' as OrdDep, l1.Cod_Estabe, l1.Cod_Dep, l1.Cod_Produt, l1.Dat_Vencim, l1.Cod_Lote, 
                                 Qtd_Saldo=IsNull(l1.Qtd_Saldo,0), Qtd_SldDep=IsNull(l1.Qtd_SldDep,0), Fat_CnvAprEmbPad=IsNull(l1.Fat_CnvAprEmbPad,0)
                            From PRLOT l1 Inner Join
                                 DPXGC de on l1.Cod_Estabe = de.Cod_Estabe and l1.Cod_Dep = de.Cod_Dep and de.Cod_GrpCli = @cl_CodGrpCli
                           Where l1.Cod_Estabe = @CodEstabe 
                             And IsNull(l1.Qtd_Saldo,0) > 0 
                             And IsNull(l1.Qtd_SldDep,0) > 0
                          UNION ALL
                          Select '2' as OrdDep, l2.Cod_Estabe, l2.Cod_Dep, l2.Cod_Produt, l2.Dat_Vencim, l2.Cod_Lote, 
                                 Qtd_Saldo=IsNull(l2.Qtd_Saldo,0), Qtd_SldDep=IsNull(l2.Qtd_SldDep,0), Fat_CnvAprEmbPad=IsNull(l2.Fat_CnvAprEmbPad,0)
                            From PRLOT l2
                           Where l2.Cod_Estabe = @CodEstabe 
                             And IsNull(l2.Qtd_Saldo,0) > 0 
                             And IsNull(l2.Qtd_SldDep,0) > 0
                             --And Cod_Dep not in (Select distinct Cod_Dep From DPXGC Where Cod_Estabe = @CodEstabe)) lt Inner Join 
						     And not Exists(Select 1 From DPXGC dc Where dc.Cod_Estabe = l2.Cod_Estabe And dc.Cod_Dep = l2.Cod_Dep)) lt Inner Join 
                         PRODU pr on lt.Cod_Produt = pr.Codigo Left Outer Join
                         CLPRV vp on vp.Cod_CliPag = @cl_CodCliPag and vp.Cod_Produt = pr.Codigo Left Outer Join
                         CLFBV vf on vf.Cod_CliPag = @cl_CodCliPag and vf.Cod_Fabric = pr.Cod_Fabricante
                   Where lt.Cod_Estabe = @CodEstabe 
                     And lt.Cod_Produt = @CodPrd
					 And ((@CodLotEsp = '') or 
                          ((@CodLotEsp <> '') and (lt.Cod_Lote = @CodLotEsp)))
                     And ( ((@IdPolLot = 0) and ((lt.Dat_Vencim is null) or 
                                                 (lt.Dat_Vencim >= Case
                                                                     When vp.Cod_Produt > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vp.Qtd_MesMinPrzVctLot,0))   
                                                                     When vf.Cod_Fabric > 0 Then dbo.FN_DataVenctoMinimo(@Date,IsNull(vf.Qtd_MesMinPrzVctLot,0))   
                                                                     Else dbo.FN_DataVenctoMinimo(@Date,IsNull(@cl_QtdMesMinPrzVctLot,0))
                                                                   End))) or
                           ((@IdPolLot > 0) and 
                            Exists(Select 1 From PCXPL pl Where pl.Cod_Estabe = lt.Cod_Estabe and pl.Id_PolCom = @IdPolLot and pl.Cod_Produt = lt.Cod_Produt and pl.Cod_Lote = lt.Cod_Lote)) ) 
                     And IsNull(lt.Qtd_Saldo,0) > 0 
                     And IsNull(lt.Qtd_SldDep,0) > 0
                   Order by OrdDep, Dat_Vencim, CodLocEst desc
              end
            -------------------------------------------------------------------------------------------------------------------------------------------------------
            Open PRLOT_Cr
            Fetch Next From PRLOT_Cr Into @LocEst, @OrdDep, @CodDep, @DatVct, @CodLot, @SldLot, @FatCnvAprEmbPad

            Set @QtdAteAcu = 0
            
            While @@FETCH_STATUS = 0
              begin
                -- ajusta saldo do lote : proporcional a fator de conversão DMD-7954: 30/03/2023
                Set @SldLot = (@SldLot/@FatCnvImpFat) * @FatCnvImpFat

                While (@QtdAteAcu < @QtdFra) and (@@FETCH_STATUS = 0)
                  begin
                    -- verifica lote unico
                    Set @QtdLotSel = @QtdLotSel + 1
                    if (@cl_FlgBlqLotVarPdv = 1) and (@QtdLotSel > 1)
                      Break
		    
                    Set @QtdAte = @QtdFra - @QtdAteAcu
                    -- se o saldo do lote nao atender a qtd.solicitada refazer a solicitacao proporcionalmente
                    if @QtdAte > @SldLot
                      begin
                        Set @QtdAte = @SldLot
                      end
                     -- Atualiza saldo do lote
                    Set @QtdPraLot = 0
                    Set @QtdDepLot = 0
                    if @LocEst = '1'
                      Set @QtdPraLot = @QtdAte
                    else
                      Set @QtdDepLot = @QtdAte
		    
                    Update PRLOT
                       Set Qtd_SolPra = Qtd_SolPra + @QtdPraLot,
                           Qtd_SolDep = Qtd_SolDep + @QtdDepLot
                     Where Cod_Estabe = @CodEstabe 
                       And Cod_Dep = @CodDep
                       And Cod_Produt = @CodPrd
                       And Cod_Lote = @CodLot
 		    
                    Set @QtdAteAcu = @QtdAteAcu + @QtdAte
		    
                    -- verifica se lote foi solicitado fora de ordem
                    Set @FlgDesord = 0
                    if (@DatVct is not Null) and (@cl_QtdMesMinPrzVctLot > 0) and 
                       (Exists(Select Cod_Lote From PRLOT Where Cod_Estabe = @CodEstabe And Cod_Dep = @CodDep And Cod_Produt = @CodPrd And Qtd_Saldo > 0 And Dat_Vencim < @DatVct))
                      Set @FlgDesord = 1
                               
                    -- pega endereço de picking do produto
                    Select @NumRua = dx.Num_Rua,
                           @NumCol = dx.Num_Col,   
                           @NumNiv = dx.Num_Niv,   
                           @NumApt = dx.Num_Apt,
                           @dx_CodLocFis = dx.Cod_LocFis,
                           @NumEst = ISNULL(z.Num_Esteira,0)   
                      From DPXPR dx Left Outer Join
                           TBZON z on (dx.Cod_Estabe = z.Cod_Estabe and dx.Num_Rua between z.Num_RuaIni and z.Num_RuaFim)
                     Where dx.Cod_Estabe = @CodEstabe
                       And dx.Cod_Dep = @CodDep
                       And dx.Cod_Produt = @CodPrd
                           
                    -- grava/regrava registro em PDVLT 
                    Set @VolTotIte = (@QtdPraLot+@QtdDepLot)*@pr_VolUniMin
		    
                     -- aqui ??? Id_PolCOm ????
                    if not Exists(Select 1 From PDVLT 
                                   Where Cod_Estabe = @CodEstabe 
                                     And Cod_Pedido = @CodPed And Num_Vol = @NumVol 
                                     And Cod_Produt = @CodPrd And Cod_Lote = @CodLot)
                      Insert Into PDVLT (Cod_Estabe, Cod_Pedido, Num_Vol, Cod_Produt, Cod_Lote
                                      ,  Qtd_EmbFec, Fat_CnvAprEmbPad, Qtd_Lote, Qtd_CxaFec
                                      ,  Cod_Dep, Num_Esteira, Num_Rua, Num_Col, Num_Niv, Num_Apt, Cod_LocFis
                                      ,  Qtd_LotePra, Qtd_LoteDep, Vol_TotIte, Id_PolCom, Flg_Desord, Flg_Manual
                                      ,  Cod_FunSep, Transacao)
                                 Values (@CodEstabe, @CodPed,    @NumVol, @CodPrd,    @CodLot
                                      ,  @QtdEmbFec, @FatCnvAprEmbPad, 0,        0
                                      ,  @CodDep, @NumEst,     @NumRua, @NumCol, @NumNiv, @NumApt, @dx_CodLocFis
                                      , 0,           0,           0,          0,         @FlgDesord,  0
                                      , 0,          @Now)
                                              
                    Update PDVLT
                       Set Qtd_Lote    = IsNull(Qtd_Lote,0)    + @QtdAte,
                           Vol_TotIte  = IsNull(Vol_TotIte,0)  + @VolTotIte,
                           Qtd_LotePra = IsNull(Qtd_LotePra,0) + @QtdPraLot,
                           Qtd_LoteDep = IsNull(Qtd_LoteDep,0) + @QtdDepLot
                     Where Cod_Estabe = @CodEstabe 
                       And Cod_Pedido = @CodPed 
                       And Num_Vol = @NumVol 
                       And Cod_Produt = @CodPrd 
                       And Cod_Lote = @CodLot

                    Fetch Next From PRLOT_Cr Into @LocEst, @OrdDep, @CodDep, @DatVct, @CodLot, @SldLot, @FatCnvAprEmbPad
		    
                  end  -- While (@QtdAteAcu < @QtdFra) and (@@FETCH_STATUS = 0)
				Fetch Next From PRLOT_Cr Into @LocEst, @OrdDep, @CodDep, @DatVct, @CodLot, @SldLot, @FatCnvAprEmbPad
              end  -- While @@FETCH_STATUS = 0

            Close PRLOT_Cr
            Deallocate PRLOT_Cr

            Fetch Next From PDVIT_Cr Into @CodPrd, @IdPolLot, @QtdEmbFec, @pr_VolUniMin, @QtdFra, @FatCnvImpFat
          end    -- While @@FETCH_STATUS = 0
          
        Close PDVIT_Cr
        Deallocate PDVIT_Cr

	    -- corrige quantidades solicitades de lotes não multiplos de fator de conversão do item
        Exec dbo.PR_CorrigeQtdLoteProduto @CodEstabe, @CodPed, @CodPrd
        if @@error <> 0
          begin
            Rollback Transaction
            Return
          end

        -- verifica se necessita corrigir quantidades do pedido em PDVIT
        Exec PR_Corrige_PDVITxPDVLT @CodEstabe, @CodPed
        if @@error <> 0
          begin
            Rollback Transaction
            Return
          end

        -- normaliza quantidades 1 e 2 entre PDVLT e PDVIT
        if @FlgErr = 0
          Exec PR_NormalizaPDVITxPDVLT @CodEstabe, @CodPed

        -- verifica resultado 
        if @FlgErr = 0
          Exec PR_DivergenciasPDVITxPDVLT @CodEstabe, @CodPed, @FlgErr output, @StrMsg output

        -- reorganiza volumes
        if @FlgErr = 0
          Exec PR_ReorganizaVolumesPDV @CodEstabe, @CodPed

        -- atualiza status PDVCB
        if @FlgErr = 0
          Update PDVCB
             Set Sta_SepLot = 'F'
           Where Cod_Estabe = @CodEstabe
             And Numero = @CodPed


        IF OBJECT_ID('tempdb..#ARQ_PRLOT') IS NOT NULL
          DROP TABLE #ARQ_PRLOT

        IF OBJECT_ID('tempdb..#ARQ_PRLTL') IS NOT NULL
          DROP TABLE #ARQ_PRLTL

        IF OBJECT_ID('tempdb..#ARQ_PDVIT') IS NOT NULL
          DROP TABLE #ARQ_PDVIT


        -- recalcula tributos PDV devido a SBt Ret Ant em PDVLT
        -- seria melhor criar uma flag em PDVCB?
        if Exists(Select 1
                    From PDVCB cb
                         inner join RGTRI rg on cb.Cod_RegTri = rg.Cod_RegTri
                   Where cb.Numero = @CodPed
                     And cb.Tip_Pedido = 'P'
                     And rg.Flg_DscSbtOrgPub = 1)
          Exec dbo.PR_CalcTributPDV @CodEstabe, @CodPed

      end  -- if @FlgPodeFechar = 1

    if @FlgErr = 1
      begin
        Update PDVCB
           Set Sta_SepLot = null
         Where Cod_Estabe = @CodEstabe
           And Numero = @CodPEd
        RAISERROR(@StrMsg,16,1)
        Rollback Transaction
        Return
      end
    else
      begin
--        Set @DesLoc = '(DEPOIS) PR_SolicitaLotesPDV pedido: '+cast(@CodPed as varchar)
--        Exec PR_Verifica_Divergencia_PRXESxPRLOT_PRLTL @DesLoc, @CodEstabe, 0

        Commit Transaction
      end
END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [dbo].[FN_ValImposto]
(
@PCodEstabe int,
@PCodOpe varchar(3),
@PTipNot char(1),
@PCodCli int,
@PCodPrd int,
@PPrcUniIte numeric(18,8),
@PPerDscIte numeric(18,4),
@PPerDscCom numeric(18,4)
)
RETURNS numeric(18,4)

AS

BEGIN

-- variaveis de trabalho
Declare @PVlrSub numeric(18,4),
        @PVlrRep numeric(18,4),

        @cl_CodRegTri int,
        @cl_CodEstado varchar(2),

        @WBasIcmNor numeric(18,4),
        @WBasRep numeric(18,4),
        @WVlrPrdSub numeric(18,4),
        @WBasSub numeric(18,4),
        @WVlrDscRat numeric(18,4),
        @WVlrRepBru numeric(18,4),
        @WVlrRepBruTab numeric(18,4),
        
        @WPerRepIcm numeric(18,4),
        @WPerRedBasCalIcmExt numeric(18,4),
        @WAlqIcmExt numeric(18,4),
        @WCtrBasCalDeb varchar(1),
        @WCtrBasCalCre varchar(1),
        @WTipPrcBasDebSbt varchar(1),
        @WTipPrcBasCreSbt varchar(1),
        @WAlqAgrDeb numeric(18,4),
        @WPerRedBasCalDeb numeric(18,4),
        @WPerLimMinIcmSbtSaiRedDeb numeric(18,4),
        @WTipPrcLimMinBasCalIcmSbtSai varchar(1),
        @WAlqAgrLimMinBasCalIcmSbtSai numeric(18,4),
        @WTipCreSbt varchar(1),
        @WAlqDebSbt numeric(18,4),
        @WFlgImpSbtFnt bit,
        @WPerRedBasCalIcmInt numeric(18,4),
        @WAlqIcmInt numeric(18,4),
        
        @WLiq numeric(18,4),
        @WCre numeric(18,4),
        @WDebSbt numeric(18,4),
        @WBru numeric(18,4),
        @WBruTab numeric(18,4),
        @WCreSbt numeric(18,4),
        @WVlrBasPrdSub numeric(18,4),
        @WVlrMinIcmSbtSaiRedDeb numeric(18,4),
        @WVlrBasCalMinSubTri numeric(18,4),
        @PVlrBasCalSubTriEntMed numeric(18,4)

Set @PVlrSub = 0
Set @PVlrRep = 0

-- coloca campos de CLIEN na memoria
Set @cl_CodRegTri = 0
Set @cl_CodEstado = ''

if Exists(Select Codigo From CLIEN Where Codigo = @PCodCli) 
  begin
    Select @cl_CodRegTri = IsNull(en.Cod_RegTri,0),
           @cl_CodEstado = cl.Cod_Estado
    From CLIEN cl
         Left Outer Join ENXES en on ((en.Cod_Estabe = @PCodEstabe) and (cl.Cgc_Cpf = en.Num_CgcCpf)) 
    Where cl.Codigo = @PCodCli 
  end

-- colococa campos de TPOPE na memoria
Declare @to_FlgCalIcmSbt bit,
        @to_FlgCalRepIcm bit

Set @to_FlgCalIcmSbt  = 0
Set @to_FlgCalRepIcm = 0

if Exists(Select Cod_Ope From TPOPE Where Cod_Ope = @PCodOpe)
  begin
    Select @to_FlgCalIcmSbt = case 
                                When @cl_CodEstado = (Select Des_Estado from ESTAB Where Cod_Estabe = @PCodEstabe) then Isnull(Flg_CalIcmSbt,0)
                                else Isnull(Flg_CalIcmSbtExt,0)
                              end,
           @to_FlgCalRepIcm = case 
                                When @cl_CodEstado = (Select Des_Estado from ESTAB Where Cod_Estabe = @PCodEstabe) then Isnull(Flg_CalRepIcmInt,0)
                                else Isnull(Flg_CalRepIcm,0)
                              end
      From TPOPE
      Where Cod_Ope = @PCodOpe
  end

-- coloca campo de PRODU na memoria
Declare @pr_CodClaTri varchar(4),
        @pr_CtrlPreco varchar(1),
        @pr_Desconto bit,
        @pr_PrcFab numeric(18,4),
        @pr_PrcVen numeric(18,4),
        @pr_PrcMax numeric(18,4),
        @pr_PrcRefFpb numeric(18,4),
        @pr_PrcUltEnt numeric(18,4),
        @pr_PerDscUltEnt numeric(18,4),
        @pr_VlrBasCalSubTriEntMed numeric(18,4)

Set @pr_CodClaTri = (Select Cod_ClaTri From PRXES Where Cod_Estabe = @PCodEstabe And Cod_Produt = @PCodPrd)

-- coloca campos de RTXCT na memoria
Declare @rt_Tip_PrcBasDebSbt varchar(1),
        @rt_Ctrl_BasCalDebSai varchar(1),
        @rt_Alq_AgrDebSai numeric(18,4),
        @rt_Per_RedBasCalDebSai numeric(18,4),
        @rt_Per_LimMinIcmSbtSaiRedDeb numeric(18,4),
        @rt_Tip_PrcLimMinBasCalIcmSbtSai varchar(1),
        @rt_Alq_AgrLimMinBasCalIcmSbtSai numeric(18,4),        
        @rt_Tip_CreSbtSai varchar(1),
        @rt_Alq_DebSbtSai numeric(18,4),
        @rt_Alq_IcmIntReg numeric(18,4),
        @rt_Per_RedBasCalIntReg numeric(18,4),
        @rt_Tip_PrcBasCreSbtSai varchar(1),
        @rt_Ctrl_BasCalCreSai varchar(1),
        @rt_Alq_IcmExtLoc numeric(18,4),
        @rt_Per_RedBasCalExtLoc numeric(18,4),
        @rt_C_PerRepIcmLoc numeric(18,4),

        @rt_Tip_PrcBasSbtEnt varchar(1),
        @rt_Ctrl_BasCalDebEnt varchar(1),
        @rt_Alq_AgrDebEnt numeric(18,4),
        @rt_Per_RedBasCalDebEnt numeric(18,4),
        @rt_Tip_CreSbtEnt varchar(1),
        @rt_Alq_DebSbtEnt numeric(18,4),
        @rt_Flg_ImpSbtFntEnt bit, 
        @rt_Alq_IcmIntLoc numeric(18,4),
        @rt_Per_RedBasCalIntLoc numeric(18,4),
        @rt_Tip_PrcBasCreSbtEnt varchar(1),
        @rt_Ctrl_BasCalCreEnt varchar(1),
        @rt_Alq_IcmExtReg numeric(18,4),
        @rt_Per_RedBasCalExtReg numeric(18,4),
        @rt_C_PerRepIcmReg numeric(18,4),
        @rt_CodImpNotEnt varchar(2)

Select @rt_CodImpNotEnt = rt.Cod_ImpNotEnt,
       @rt_Tip_PrcBasDebSbt = IsNull(rt.Tip_PrcBasDebSbt,''),
       @rt_Ctrl_BasCalDebSai = IsNull(rt.Ctrl_BasCalDebSai,''),
       @rt_Alq_AgrDebSai = Isnull(rt.Alq_AgrDebSai,0),
       @rt_Per_RedBasCalDebSai = Isnull(rt.Per_RedBasCalDebSai,0),
       @rt_Per_LimMinIcmSbtSaiRedDeb = IsNull(Per_LimMinIcmSbtSaiRedDeb,0),
	   @rt_Tip_PrcLimMinBasCalIcmSbtSai = IsNull(Tip_PrcLimMinBasCalIcmSbtSai,''),
	   @rt_Alq_AgrLimMinBasCalIcmSbtSai = IsNull(Alq_AgrLimMinBasCalIcmSbtSai,0),
       @rt_Tip_CreSbtSai = Isnull(rt.Tip_CreSbtSai,''),
       @rt_Alq_DebSbtSai = Isnull(rt.Alq_DebSbtSai,0),
       @rt_Alq_IcmIntReg = Isnull(rt.Alq_IcmIntReg,0),
       @rt_Per_RedBasCalIntReg = Isnull(rt.Per_RedBasCalIntReg,0),
       @rt_Tip_PrcBasCreSbtSai = IsNull(rt.Tip_PrcBasCreSbtSai,''),
       @rt_Ctrl_BasCalCreSai = IsNull(rt.Ctrl_BasCalCreSai,''),
       @rt_Alq_IcmExtLoc = Isnull(rt.Alq_IcmExtLoc,0),
       @rt_Per_RedBasCalExtLoc = Isnull(rt.Per_RedBasCalExtLoc,0),
       @rt_C_PerRepIcmLoc = Isnull(rt.C_PerRepIcmLoc,0),
       @rt_Tip_PrcBasSbtEnt = IsNull(rt.Tip_PrcBasSbtEnt,''),
       @rt_Ctrl_BasCalDebEnt  = IsNull(rt.Ctrl_BasCalDebEnt,''),
       @rt_Alq_AgrDebEnt = Isnull(rt.Alq_AgrDebEnt,0),
       @rt_Per_RedBasCalDebEnt = Isnull(Per_RedBasCalDebEnt,0),
       @rt_Tip_CreSbtEnt = IsNull(rt.Tip_CreSbtEnt,''),
       @rt_Alq_DebSbtEnt = Isnull(rt.Alq_DebSbtEnt,0),
       @rt_Flg_ImpSbtFntEnt = IsNull(Flg_ImpSbtFntEnt,0),
       @rt_Alq_IcmIntLoc = Isnull(rt.Alq_IcmIntLoc,0),
       @rt_Per_RedBasCalIntLoc = Isnull(rt.Per_RedBasCalIntLoc,0),
       @rt_Tip_PrcBasCreSbtEnt = IsNull(rt.Tip_PrcBasCreSbtEnt,''),
       @rt_Ctrl_BasCalCreEnt = IsNull(rt.Ctrl_BasCalCreEnt,''),
       @rt_Alq_IcmExtReg = Isnull(rt.Alq_IcmExtReg,0),
       @rt_Per_RedBasCalExtReg = Isnull(rt.Per_RedBasCalExtReg,0),
       @rt_C_PerRepIcmReg = Isnull(rt.C_PerRepIcmReg,0)
  from RTXCT rt Inner JOIN PRODU pr on (rt.Cod_RegTri = @cl_CodRegTri) and (rt.Cod_Clatri = @pr_CodClaTri)
  Where pr.Codigo = @PCodPrd

Select @pr_CtrlPreco = pr.Ctrl_Preco,
       @pr_Desconto = Isnull(p.Flg_BlqDsc,0),
       @pr_PrcRefFpb = ISNULL(pr.Prc_RefFpb,0),
       @pr_PrcUltEnt = Isnull(p.Prc_UltEnt,0),
       @pr_PerDscUltEnt = Isnull(p.Per_DscUltEnt,0),
	   @pr_VlrBasCalSubTriEntMed = IsNull(p.Vlr_BasCalSubTriEntMed,0),
       @pr_PrcFab = Case
                      When (Round(@WAlqIcmInt,2) = 12.00) and (IsNull(pr.Prc_Fabric12,0)  > 0) Then IsNull(pr.Prc_Fabric12,0)
                      When (Round(@WAlqIcmInt,2) = 17.00) and (IsNull(pr.Prc_Fabric17,0)  > 0) Then IsNull(pr.Prc_Fabric17,0)
                      When (Round(@WAlqIcmInt,2) = 17.50) and (IsNull(pr.Prc_Fabric175,0) > 0) Then IsNull(pr.Prc_Fabric175,0)
                      When (Round(@WAlqIcmInt,2) = 18.00) and (IsNull(pr.Prc_Fabric18,0)  > 0) Then IsNull(pr.Prc_Fabric18,0)
                      When (Round(@WAlqIcmInt,2) = 19.00) and (IsNull(pr.Prc_Fabric19,0)  > 0) Then IsNull(pr.Prc_Fabric19,0)
                      When (Round(@WAlqIcmInt,2) = 19.50) and (IsNull(pr.Prc_Fabric195,0) > 0) Then IsNull(pr.Prc_Fabric195,0)
                      When (Round(@WAlqIcmInt,2) = 20.00) and (IsNull(pr.Prc_Fabric20,0)  > 0) Then IsNull(pr.Prc_Fabric20,0)
                      When (Round(@WAlqIcmInt,2) = 20.50) and (IsNull(pr.Prc_Fabric205,0) > 0) Then IsNull(pr.Prc_Fabric205,0)
                      When (Round(@WAlqIcmInt,2) = 21.00) and (IsNull(pr.Prc_Fabric21,0)  > 0) Then IsNull(pr.Prc_Fabric21,0)
                      When (Round(@WAlqIcmInt,2) = 22.00) and (IsNull(pr.Prc_Fabric22,0)  > 0) Then IsNull(pr.Prc_Fabric22,0)
                      Else Isnull(p.Prc_Fabric,0)
                    End,
       @pr_PrcMax = Case
                      When (Round(@WAlqIcmInt,2) = 12.00) and (IsNull(pr.Prc_MaxCon12,0)  > 0) Then IsNull(pr.Prc_MaxCon12,0)
                      When (Round(@WAlqIcmInt,2) = 17.00) and (IsNull(pr.Prc_MaxCon17,0)  > 0) Then IsNull(pr.Prc_MaxCon17,0)
                      When (Round(@WAlqIcmInt,2) = 17.50) and (IsNull(pr.Prc_MaxCon175,0) > 0) Then IsNull(pr.Prc_MaxCon175,0)
                      When (Round(@WAlqIcmInt,2) = 18.00) and (IsNull(pr.Prc_MaxCon18,0)  > 0) Then IsNull(pr.Prc_MaxCon18,0)
                      When (Round(@WAlqIcmInt,2) = 19.00) and (IsNull(pr.Prc_MaxCon19,0)  > 0) Then IsNull(pr.Prc_MaxCon19,0)
                      When (Round(@WAlqIcmInt,2) = 19.50) and (IsNull(pr.Prc_MaxCon195,0) > 0) Then IsNull(pr.Prc_MaxCon195,0)
                      When (Round(@WAlqIcmInt,2) = 20.00) and (IsNull(pr.Prc_MaxCon20,0)  > 0) Then IsNull(pr.Prc_MaxCon20,0)
                      When (Round(@WAlqIcmInt,2) = 20.50) and (IsNull(pr.Prc_MaxCon205,0) > 0) Then IsNull(pr.Prc_MaxCon205,0)
                      When (Round(@WAlqIcmInt,2) = 21.00) and (IsNull(pr.Prc_MaxCon21,0)  > 0) Then IsNull(pr.Prc_MaxCon21,0)
                      When (Round(@WAlqIcmInt,2) = 22.00) and (IsNull(pr.Prc_MaxCon22,0)  > 0) Then IsNull(pr.Prc_MaxCon22,0)
                      Else Isnull(p.Prc_MaxCon,0)
                    End
  from PRXES p
       Inner Join PRODU pr on p.Cod_Produt = pr.Codigo
  Where p.Cod_Estabe = @PCodEstabe
  And p.Cod_Produt = @PCodPrd

Set @PVlrBasCalSubTriEntMed = @pr_VlrBasCalSubTriEntMed

-- coloca campos de NFSIT na memoria
Declare @it_Vlr_TotIte numeric(18,4),  -- por enquanto nao estou pegando da tabela
        @it_Vlr_BruIte numeric(18,4)   -- por enquanto nao estou pegando da tabela

-- calcula valores toais do item (Vlr_TotItem e Vlr_BruItem em NFSIT)
Set @it_Vlr_BruIte = Round(@PPrcUniIte,2)
Set @it_Vlr_TotIte = Round(@PPrcUniIte*(1-@PPerDscIte/100),2)

-- tipo da nota diferente de devolucao
if @PTipNot <> 'D'
  begin
    -- vendas, outras saidas
    Set @WTipPrcBasDebSbt = @rt_Tip_PrcBasDebSbt
    Set @WCtrBasCalDeb = @rt_Ctrl_BasCalDebSai
    Set @WAlqAgrDeb = @rt_Alq_AgrDebSai
    Set @WPerRedBasCalDeb = @rt_Per_RedBasCalDebSai
    Set @WPerLimMinIcmSbtSaiRedDeb = @rt_Per_LimMinIcmSbtSaiRedDeb
    Set @WTipPrcLimMinBasCalIcmSbtSai = @rt_Tip_PrcLimMinBasCalIcmSbtSai
    Set @WAlqAgrLimMinBasCalIcmSbtSai = @rt_Alq_AgrLimMinBasCalIcmSbtSai     
    Set @WTipCreSbt = @rt_Tip_CreSbtSai
    Set @WAlqDebSbt = @rt_Alq_DebSbtSai
    Set @WFlgImpSbtFnt = 1
    Set @WAlqIcmInt = @rt_Alq_IcmIntReg
    Set @WPerRedBasCalIcmInt = @rt_Per_RedBasCalIntReg
    Set @WTipPrcBasCreSbt = @rt_Tip_PrcBasCreSbtSai
    Set @WCtrBasCalCre = @rt_Ctrl_BasCalCreSai
    Set @WAlqIcmExt = @rt_Alq_IcmExtLoc
    Set @WPerRedBasCalIcmExt = @rt_Per_RedBasCalExtLoc
    Set @WPerRepIcm = @rt_C_PerRepIcmLoc
  end
else
  begin
    -- devolucao
    Set @WTipPrcBasDebSbt = @rt_Tip_PrcBasSbtEnt
    Set @WCtrBasCalDeb = @rt_Ctrl_BasCalDebEnt
    Set @WAlqAgrDeb = @rt_Alq_AgrDebEnt
    Set @WPerRedBasCalDeb = @rt_Per_RedBasCalDebEnt
    Set @WPerLimMinIcmSbtSaiRedDeb = 0
    Set @WTipPrcLimMinBasCalIcmSbtSai = ''
    Set @WAlqAgrLimMinBasCalIcmSbtSai = 0
    Set @WTipCreSbt = @rt_Tip_CreSbtEnt
    Set @WAlqDebSbt = @rt_Alq_DebSbtEnt
    Set @WFlgImpSbtFnt = @rt_Flg_ImpSbtFntEnt
    Set @WAlqIcmInt = @rt_Alq_IcmIntLoc
    Set @WPerRedBasCalIcmInt = @rt_Per_RedBasCalIntLoc
    Set @WTipPrcBasCreSbt = @rt_Tip_PrcBasCreSbtEnt
    Set @WCtrBasCalCre = @rt_Ctrl_BasCalCreEnt
    Set @WAlqIcmExt = @rt_Alq_IcmExtReg
    Set @WPerRedBasCalIcmExt = @rt_Per_RedBasCalExtReg
    Set @WPerRepIcm = @rt_C_PerRepIcmReg
  end

-- calcula repasse para futuros calculos
-- repasse de ICMS se houver diferenca de aliquotas
-- e somente cipados ou liberados c/ repasse
Set @WVlrRepBru = 0
Set @WVlrRepBruTab = 0
if @to_FlgCalIcmSbt = 1
  if (@to_FlgCalRepIcm = 1) and (@WPerRepIcm <> 0) and (@pr_CtrlPreco <> 'L')
    begin
      -- repasse liquido
      Set @WBasRep = Round(@it_Vlr_TotIte,2)
      Set @PVlrRep = @WBasRep * @WPerRepIcm / 100
      -- repasse bruto
      Set @WVlrRepBru = Round(@it_Vlr_BruIte * @WPerRepIcm / 100,2)
      Set @WVlrRepBruTab = Round(@pr_PrcVen * @WPerRepIcm / 100,2)
    end

-- valor liquido do item sem reducao da base de calculo p/ credito Icms
Set @WLiq = @it_Vlr_TotIte - @PVlrRep

Set @WVlrDscRat = 0
if @pr_Desconto = 0
  Set @WVlrDscRat = @WLiq * @PPerDscCom/100
Set @WLiq = Round(@WLiq-@WVlrDscRat,2)

-- registra icms proprio, icms tributavel da operacao se DEB/CRE ou SUB.TRIB.
Set @WBasIcmNor = Round(@WLiq * (1 - @WPerRedBasCalIcmExt/100),2)
Set @WCre = @WBasIcmNor * @WAlqIcmExt / 100

-- Calcula Substituicao Tributaria
if (@to_FlgCalIcmSbt = 1) and (@WTipPrcBasDebSbt <> 'X') and (@WTipPrcBasDebSbt <> 'O')
  begin
    -- valor bruto do item
    Set @WBru = @it_Vlr_BruIte - @WVlrRepBru
    Set @WBru = Round(@WBru,2)

    -- @rt_Tip_AgrDebSbt = 'F' or 'A'
    if @WCtrBasCalDeb = 'B'  -- pelo vlr. bruto
      begin
        if @WTipPrcBasDebSbt = 'M'           -- utiliza P.M.C. do cadastro
          Set @WVlrBasPrdSub = @pr_PrcMax 
        else
        if @WTipPrcBasDebSbt = 'F'            -- utiliza preco fabrica do cadastro
          Set @WVlrBasPrdSub = @pr_PrcFab 
        else
        if @WTipPrcBasDebSbt = 'P'            -- utiliza preco ref. fcia popular
          Set @WVlrBasPrdSub = @pr_PrcRefFpb 
        else
        if @WTipPrcBasDebSbt = 'V'            -- utiliza preco venda do cadastro
          Set @WVlrBasPrdSub = @pr_PrcVen - @WVlrRepBruTab
        else
        if @WTipPrcBasDebSbt = 'C'            -- utiliza preco compra do cadastro
          Set @WVlrBasPrdSub = @pr_PrcUltEnt*(1-@pr_PerDscUltEnt/100) 
        else
          Set @WVlrBasPrdSub = @WBru   --/ transacao
      end
    else
      Set @WVlrBasPrdSub = @WLiq
      
	-- redução da base de calculo original
	Set @WVlrBasPrdSub = @WVlrBasPrdSub * (1 - @WPerRedBasCalIcmInt/100)

    -- Valor base da ST: agregacao, reducao e aliquota 
    Set @WVlrPrdSub = @WVlrBasPrdSub * (1 - @WPerRedBasCalDeb/100)
    Set @WBasSub = @WVlrPrdSub * (1 + @WAlqAgrDeb/100)

    -- verifica limitador B.C.ST
    Set @WVlrBasCalMinSubTri = 0
    if @WTipPrcLimMinBasCalIcmSbtSai = 'E'
      begin
        -- média da B.C. de Entrada + Agreg.
        Set @WVlrBasCalMinSubTri = Round(@PVlrBasCalSubTriEntMed * (1 + @WAlqAgrLimMinBasCalIcmSbtSai/100),2)
      end
    if @WBasSub < @WVlrBasCalMinSubTri
      Set @WBasSub = @WVlrBasCalMinSubTri

    -- ver se utiliza no calculo da ST % fixo sobre preco do produto
    if @WTipCreSbt = 'F'
      begin
        Set @PVlrSub = @WVlrPrdSub * @WAlqDebSbt / 100
      end
    else
      -- calcula subst.tributaria com agregacao
      begin
        -- debito com red. base de calculo icms
        Set @WAlqDebSbt = @WAlqIcmInt
        Set @WDebSbt = @WBasSub * @WAlqDebSbt / 100   

        -- credito
        if @WCtrBasCalCre = 'B'         -- credito pelo vlr.bruto
          begin
            if @WTipPrcBasCreSbt = 'F'      -- utiliza preco fabrica do cadastro
              Set @WCreSbt = @pr_PrcFab  
            else
            if @WTipPrcBasCreSbt = 'V'     -- utiliza preco venda do cadastro
              Set @WCreSbt = @pr_PrcVen - @WVlrRepBruTab
            else
              Set @WCreSbt = @WBru              -- transacao
            -- credito com red.base de calculo
            Set @WCreSbt = @WCreSbt * (1 -@WPerRedBasCalIcmExt/100) * @WAlqIcmExt / 100
          end
        else
          Set @WCreSbt = @WCre

        -- calcula icm subst.
        Set @PVlrSub = @WDebSbt - @WCreSbt
        
      end  -- -- calcula subst.tributaria com agregacao
      
    -- verifica limitador ST
    Set @WVlrMinIcmSbtSaiRedDeb = 0
    if (@WPerRedBasCalDeb > 0) and (@WPerLimMinIcmSbtSaiRedDeb > 0) 
      Set @WVlrMinIcmSbtSaiRedDeb = @WBasSub*@WPerLimMinIcmSbtSaiRedDeb/100

    if (@WVlrMinIcmSbtSaiRedDeb > 0) and (@PVlrSub < @WVlrMinIcmSbtSaiRedDeb)
      begin
        -- desconsidera reducao na base de calculo
--        Set @WVlrPrdSub = @WVlrBasPrdSub
--        Set @WBasSub = @WVlrPrdSub * (1 + @WAlqAgrDeb/100)
--        Set @WDebSbt = @WBasSub * @WAlqDebSbt / 100   
--        Set @PVlrSub = @WDebSbt - @WCreSbt
        Set @PVlrSub = @WVlrMinIcmSbtSaiRedDeb
      end
        
    if @PVlrSub <= 0
      Set @PVlrSub = 0
      
  end  -- if (@to_FlgCalIcmSbt = 1) and (@WTipPrcBasDebSbt <> 'X') and (@WTipPrcBasDebSbt <> 'O')


-- se a ST nao for retida na fonte
if (@WFlgImpSbtFnt = 0) and (@PVlrSub > 0)
  Set @PVlrSub = 0

-- Retorna o resultado da function
RETURN @PVlrSub-@PVlrRep

END
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_ConfiguraESTAB]
@CodEstabe int,
@Usuario Varchar(15),
@Opcao smallint,
@CodEstabePai int,
@IdSessao int

-- Parametros
-- @CodEstabe - Estabelecimento para configurar, se informar -1 atualiza todos
-- @Usuario - Login do sistema
-- @Opcao - Item a ser criado/atualizado
--          1 - PARAM
--          2 - PMEST
--          3 - FS_PARAM
--          4 - MIXPRODUTOS
--          5 - MIXENTIDADES
--          0 - TODAS AS OPÇÕES ANTERIORES
-- @CodEstabPai - Esabelecimento a ser usado como modelo se informar -1 procura automatico


AS

SET NOCOUNT ON

Declare @CodDep smallint,
		@RowCount int,
		@ErroMsg varchar(500),
		@TotalCount int
		
        
Declare Table_Cr Cursor Local FAST_FORWARD For
  Select Cod_Estabe From ESTAB
  Where ( Cod_Estabe = @CodEstabe )
  Or ( @CodEstabe = -1 ) -- Configura/Atualiza todos os estabelecimentos

Set @TotalCount = 0

-- Procura o estabelecimento para ser usado como modelo
if @CodEstabePai = -1
	Select Top 1 @CodEstabePai = EstabPai.Cod  
	From (
		Select Cod_EstabPai as Cod From ESTAB Where Cod_EstabPai is Not Null
		Union All
		Select Cod_Estabe as Cod   From ESTAB Where Cod_EstabPai is Null
		) EstabPai 
	Inner Join ESTAB e On e.Cod_Estabe = EstabPai.Cod
	Order By Cod

-- Se não foi informado e também não localizar o estabelecimento exibe erro
if (@CodEstabePai = -1) or (@CodEstabe <= 0)
 begin
   RAISERROR (15600,-1,-1, 'PR_ConfiguraESTAB'); --Foi especificado um parâmetro ou uma opção inválida para o procedimento '%1!'.
   RETURN 0
 end
 
--valida login para auditoria
if (@Usuario='' or @Usuario='SISTEMA')
  set @Usuario = dbo.FN_UsuarioInfarma()
 
OPEN Table_Cr

FETCH NEXT FROM Table_Cr INTO @CodEstabe

While @@FETCH_STATUS = 0
Begin
	Begin Try
		Begin Transaction

	    -- Configurar o estabelecimento PAI
		Update ESTAB
		 Set Cod_EstabPai = @CodEstabePai
		 Where Cod_Estabe = @CodEstabe 

		-- Auditoria
		--Insert Into AUDIT (Cod_Estabe,Cod_Ope,Nom_Tabela,Chave1,Chave2,Nom_Campo,Des_Campo,
		--            Observ,
		--            Usuario,Transacao)
		--Values(@CodEstabe,'A','ESTAB',@CodEstabe,@IdSessao,'Cod_Estabe','PR_ConfiguraESTAB',
		--            'Iniciando Configuração do Estabelecimento', @Usuario,GetDate() )

		-- Criar PARAM se não existir -- copia do estabelecimento pai
		If (@Opcao = 0 or @Opcao = 1) And Not Exists(Select 1 From PARAM Where Cod_Estabe = @CodEstabe)
		  Begin
			Insert Into PARAM (Cod_Estabe,UltDatAcesso,DatHorArqRot,VlrObjEmp,VlrLimComFun,PerComVdrAtoVen,
				               PerMinAcrComGer,PerMaxAcrComGer,CodAgeCobCar,FlgImpPedBlq,FlgImpPedDbq,FlgImpCupFun,
				               FlgImpCupCon,Des_Versao,DesImpPedBlq,DesImpPedLib,DesImpVale,DesImpNotFis,DesImpOrcame,
				               DesImpCupom,DesImpBloquete,DesImpDuplic,DesImpEtqVol,SerieSeloFiscal,ModeloNotaFiscal,
				               NumItePagNfs,CodCfoVenInt,CodCfoVenExt,CodCfoTrfInt,CodCfoTrfExt,CodCfoVenIntConFin,
				               CodCfoVenExtConFin,PerTaxJurDia,PerDesOpe,PerDesFre,PerDesCom,PerDesPis,PerDesCof,
				               PerDesIrpj,PerDesConSoc,QtdDiaDefDup,QtdDiaMaxDup,QtdDiaDupApr,QtdDiaPrgDupApr,
				               PrzMedMaxDup,PrzMaxPdvDscIte,PrzMaxPdvDscCom,PrzMaxPdvDscFin,QtdParMaxDup,VlrMinDup,
				               PerDscComMax,PerDscComMaxVis,PerDscFinMax,StrCodFabPrzDif,QtdDiaPrzDif,PerDscMaxPrzDif,
				               DatEspIni,DatEspFim,PerEspDscComMaxVis,VlrEspMinPdvVis,PrzEspMaxPdvDscCom,PerEspMaxPdvDscCom,
				               VlrEspMinPdvDscCom,PrzInfEspPdvDscFin,PerInfEspPdvDscFin,VlrInfEspPdvDscFin,PrzMedEspPdvDscFin,
				               PerMedEspPdvDscFin,VlrMedEspPdvDscFin,PrzSupEspPdvDscFin,PerSupEspPdvDscFin,VlrSupEspPdvDscFin,
				               PrzEspMaxPdvSdc,VlrEspMinPdvSdc,NumLotFecReq,QtdMesTmpCom,CodAgcChqVct,QtdDiaChqVct,PerPrcMaxCon,
				               DesMsgBlo1,PerMsgBlo1,DesMsgBlo2,PerMsgBlo2,DesMsgBlo3,PerMsgBlo3,QtdMesVenMed,CodVdrPdvFun,
				               CodVdrPdvCon,CodOpePdvFun,CodOpePdvCon,CodCidadeEmpLoc,CodMacRegEmpLoc,CodMicRegEmpLoc,
				               PerTaxJurMerc,PerCorPrcVen,PrzRefPrcVen,PrzPrc1,PrzPrc2,PrzPrc3,PrzPrc4,
				               FlgCtrLot,QtdDiaDupVis,TipPreNot,MrgErrAdmNfe,FlgFecFisNfe,FlgImpCliPreNot,FlgDespachMercad,
				               FlgIncImpPriDup,FlgImpSelFisNotFis,FlgImpHorSaiNotFis,FlgCtrDscIte,PerMaxDscIte,FlgCtrSelFis,
				               FlgIncImpOrc,FlgIncImpFun,FlgIncImpCon,FlgComRedIteDsc,PerMaxComNorIteDsc,FlgComRedNotDsc,
				               PerMaxComNorNotDsc,FlgComRedCliEsp,FlgOrcAgeCobCar,FlgDscFinIstOutEst,FlgBlqAltVndPdv,
				               FlgImpDscIteNfs,Ctr_ImpItePreNot,Ctr_ImpIteNotFis,FlgComVndCmpOpe,PerDscAtcCtr,QtdPrzDscAtcCtr,
				               QtdPrzMinDscAtcCtr,FlgPrcEspHospit,CodRamAtvHospit,CodRamAtvOrgPub,CodRamAtvAtacad,FlgAlerta,
				               FlgIstRecDup,FlgBlqCriPrcVen,FlgEmbDscItePrcUni,QtdConBal,FlgImpIstOrc,DiaVctDupExtIst,FlgIntCtb,
				               FlgIntFis,FlgPdvPrzFab,FlgLimComMaxFab,FlgComRedItePrm,FlgExcImpOrcItePrm,FlgCmpAutChqVct,FlgEmiDup,
				               FlgIstOrcCli,VlrDebVndCtr,TipNotFis,FlgComPrpDsc,FlgCnvDscIteDscCom,FlgCnvPdvVal,FlgCalComDscFin,
				               FlgConferPed,FlgZerLimCre,PerMulAtrPag,QtdDiaProtes,PerMkpPrdCipNeg,PerMkpPrdCipPos,PerMkpPrdCipNeu,
				               FlgCalendContab,FlgImpItePrpNfs,DesArqAbcFar,FlgGerRecSubFat,FlgCtrSubFat,
				               FlgComPrdPrpDsc,FlgComPrdPrpDscPrm,FlgImpResFinPreNot,QtdDiaPerPdv,QtdDiaCanNtf,TipOrcame,
				               QtdDiaPrzEntChqVct,QtdDiaAtrMedCtr,QtdMesPagCtrAtr,FlgBlqPdvAtrCtr,StrCodAgcChqVct,FlgCtlLotSai,
				               FlgImpCtrPreNot,FlgComTabDsc,FlgTabPrcConFin,
				               FlgNaoRepIcmVen,FlgTabPrzVenLin,QtdDecPrcItePdv,TipCalCtbCtp,FlgCalCtbCtr,TipCalCtbCtr,TipCalCusPrd,
				               FlgAtuPrvEnt,FlgBasPrvConFin,FlgContribSubstituto,FlgPrzLinConFin,FlgImpDscEmbNot,FlgResPrdVen,
