				               PerTaxJurMerc,PerCorPrcVen,PrzRefPrcVen,PrzPrc1,PrzPrc2,PrzPrc3,PrzPrc4,
				               FlgCtrLot,QtdDiaDupVis,TipPreNot,MrgErrAdmNfe,FlgFecFisNfe,FlgImpCliPreNot,FlgDespachMercad,
				               FlgIncImpPriDup,FlgImpSelFisNotFis,FlgImpHorSaiNotFis,FlgCtrDscIte,PerMaxDscIte,FlgCtrSelFis,
				               FlgIncImpOrc,FlgIncImpFun,FlgIncImpCon,FlgComRedIteDsc,PerMaxComNorIteDsc,FlgComRedNotDsc,
				               PerMaxComNorNotDsc,FlgComRedCliEsp,FlgOrcAgeCobCar,FlgDscFinIstOutEst,FlgBlqAltVndPdv,
				               FlgImpDscIteNfs,Ctr_ImpItePreNot,Ctr_ImpIteNotFis,FlgComVndCmpOpe,PerDscAtcCtr,QtdPrzDscAtcCtr,
				               QtdPrzMinDscAtcCtr,FlgPrcEspHospit,CodRamAtvHospit,CodRamAtvOrgPub,CodRamAtvAtacad,FlgAlerta,
				               FlgIstRecDup,FlgBlqCriPrcVen,FlgEmbDscItePrcUni,QtdConBal,FlgImpIstOrc,DiaVctDupExtIst,FlgIntCtb,
				               FlgIntFis,FlgPdvPrzFab,FlgLimComMaxFab,FlgComRedItePrm,FlgExcImpOrcItePrm,FlgCmpAutChqVct,FlgEmiDup,
				               FlgIstOrcCli,VlrDebVndCtr,TipNotFis,FlgComPrpDsc,FlgCnvDscIteDscCom,FlgCnvPdvVal,FlgCalComDscFin,
				               FlgConferPed,FlgZerLimCre,PerMulAtrPag,QtdDiaProtes,PerMkpPrdCipNeg,PerMkpPrdCipPos,PerMkpPrdCipNeu,
				               FlgCalendContab,FlgImpItePrpNfs,DesArqAbcFar,FlgGerRecSubFat,FlgCtrSubFat,
				               FlgComPrdPrpDsc,FlgComPrdPrpDscPrm,FlgImpResFinPreNot,QtdDiaPerPdv,QtdDiaCanNtf,TipOrcame,
				               QtdDiaPrzEntChqVct,QtdDiaAtrMedCtr,QtdMesPagCtrAtr,FlgBlqPdvAtrCtr,StrCodAgcChqVct,FlgCtlLotSai,
				               FlgImpCtrPreNot,FlgComTabDsc,FlgTabPrcConFin,
				               FlgNaoRepIcmVen,FlgTabPrzVenLin,QtdDecPrcItePdv,TipCalCtbCtp,FlgCalCtbCtr,TipCalCtbCtr,TipCalCusPrd,
				               FlgAtuPrvEnt,FlgBasPrvConFin,FlgContribSubstituto,FlgPrzLinConFin,FlgImpDscEmbNot,FlgResPrdVen,
				               QtdDiaResPrdVen,FlgImpDesPrdCli,FlgNaoSugDscItePdv,FlgRegDscCliItePdv,PerRntMinPdv,FlgPerCmpEst,
				               FlgSubTriCusPrd,FlgIcmTriCusPrd,ValDspBolBan,FlgCobDspBanNtf,FlgRedComCliPar,FlgCtrEntNfs,
				               FlgSugPrmPdv,PerDscPrmExtVenVis,FlgPreEntNfe,PerDedVlrChqDvl,QtdDiaRecChqDvl,UltDatFecComVnd,
				               UltDatFecComEnt,PerMinRndCxaFecInfSugCmp,FlgCorAutFalPdvFecCnf,Dat_UltRemSerasa,FlgNaoObgSelFisOpeExt,
				               FlgComPrpDscTabRed,FlgComPrpDscTabFix,FlgGerComOpeAtv,PerRedComCliPar,CodOpeSemCom,FlgAltConComPdv,
				               FlgRegPrzPdvExcConCom,FlgDispenPwdPedRea,FlgTabPrzPrcVenLin,FlgFatAutPdvDiv,Str1EstCliGerRom,
				               CodCli1GerRom,CodOpe1GerRom,FlgAltUnvItePdv,FlgSugUnvPadPdv,FlgEncParAut,FlgCriPrcMinCusLiq,
				               FlgCriPrcMinPmz,FlgOmiEstNegCadPro,PerAcrCriPrcMinCusLiq,Flg_BlqAltQtdCnf,Flg_DivPdvVol,
				               FlgCanNotForaPerFis,FlgAtuPrcCusCadPro,Des_VersaoMin,FlgPisCofCusPrd,DesImpPckLst,
				               CodCtrImpAprPreNot,FlgBlqSugPrmQtdMin,FlgCalComPdv,FlgImpEmpVal,FlgCtrBlqPdvLicCli,
				               FlgNfe,FlgSolCrmPdv,FlgIncSbtPrcOpeInt,FlgInfFrePdv,FlgUsaPolComPdv,FlgImpRotBlq,
				               FlgUsaPsqPar,FlgManutencao,FlgDscAutPrxFatCli,FlgSugPolComIdeal,FlgAltDscPrdBlqDsc,
				               FlgCriIteFecPdv,FlgBlqMsgFecPdv,FlgUsaPrcBruEnt,FlgIncDscPrcOpeIntSbtEmb,FlgInfPrvFrePdv,
				               FlgBlqIcmTriCalRntPrdSbtFnt,FlgFecVlrPdvNfsSbtEmb,FlgGerAutPdvBon,CodTpvBon,FlgGerBonVlrCli,
				               CodEstabeCon,FlgBlqCnfLotPrd,PrzVctLot1,CorVctLot1,PrzVctLot2,CorVctLot2,PrzVctLot3,CorVctLot3,
				               FlgImpSldEstBal,FlgUsaEstornoNfe,FlgBlqIncPdvCliAtr,FlgBlqFecNfeDivPrc,PerDesPisLucRea,
				               PerDesPisLucPre,PerDesCofLucRea,PerDesCofLucPre,FlgIncIpiCalPis,FlgCalcRentPdvOnLine,
				               FlgArredondaPisCofins,FlgCriPrcMinCusMedCom,FlgNfeIntArtNew,FlgUsaCusMedComCalRnt,TipEmiNfe,
				               FlgBlqBonPdv,FlgNfeWebSer,FlgSugPolComMenDsc,FlgPerResExtEnt,FlgUsaColExp,FlgUsaColRec,QtdPrzMaxImpSbt,FlgUsaPbmSpv,
                               QtdDiaPerAud,QtdDiaPerMaiNfs,QtdDiaPerXmlNfs,FlgCotPrcPrd,FlgUsaDirGerCac,FlgExiPolSelPrdPedVen,FlgBlqCtrDocClaPrd,
							   FlgAtuTabPrcEnt,FlgExiGrpPrdPdv,DatUltAtuModExt,FlgManImpPckLst,FlgExbEstPrcAprPrd
			From PARAM
			Where Cod_Estabe = @CodEstabePai
			And Not Exists(Select 1 From PARAM Where Cod_Estabe = @CodEstabe)

			-- AUDITORIA
			Set @RowCount = @@ROWCOUNT
			Set @TotalCount = @TotalCount+@RowCount;
			If @RowCount > 0
				Insert Into AUDIT (Cod_Estabe,Cod_Ope,Nom_Tabela,Chave1,Chave2,Nom_Campo,Des_Campo,
				            Observ,
				            Usuario,Transacao)
	            Values(@CodEstabe, 'I','PARAM',@CodEstabe,@IdSessao,'Cod_Estabe','PR_ConfiguraESTAB',
				            'Inclusão de '+Convert(varchar(20),@RowCount)+' Registros em PARAM',
					       @Usuario,GetDate() )

			If @RowCount = 0
				Insert Into AUDIT (Cod_Estabe,Cod_Ope,Nom_Tabela,Chave1,Chave2,Nom_Campo,Des_Campo,
				            Observ,
				            Usuario,Transacao)
	            Values(@CodEstabe, 'I','PARAM',@CodEstabe,@IdSessao,'Cod_Estabe','PR_ConfiguraESTAB',
				            'Atenção: Não foram inseridos registros em PARAM',
					       @Usuario,GetDate() )


	   	  End
	   	-- FINAL CRIAR PARAM

		-- Criar PMEST senão existir
		If (@Opcao = 0 or @Opcao = 2) And Not Exists(Select 1 From PMEST Where Cod_Estabe = @CodEstabe)
		  Begin
			Insert Into PMEST (Cod_Estabe ,
					CodClaAbc1 ,PerClaAbcVal1 ,PerClaAbcVol1 ,QtdDiaSeg1 ,CodClaAbc2 ,PerClaAbcVal2 ,PerClaAbcVol2 ,
					QtdDiaSeg2 ,CodClaAbc3 ,PerClaAbcVal3 ,PerClaAbcVol3 ,QtdDiaSeg3 ,CodClaAbc4 ,PerClaAbcVal4 ,PerClaAbcVol4 ,QtdDiaSeg4 ,CodClaAbc5 ,
					PerClaAbcVal5 ,PerClaAbcVol5 ,QtdDiaSeg5 ,CodClaAbc6 ,PerClaAbcVal6 ,PerClaAbcVol6 ,QtdDiaSeg6 ,Usuario ,Transacao ,CodZonDev ,
					CodZonCan ,CodZonDiv ,QtdNivEndPck ,QtdNivEndDep ,WmsFlgBlqImpEtqVol ,WmsFlgBlqImpCodBarPckLst ,WmsFlgBlqRotFecEmbPdv ,FlgCnfIUM ,
					WmsFlgImpFabPckLst ,BalImpIniCodBar ,BalImpTamCodBar ,BalImpIniQtdPrd ,BalImpTamQtdPrd ,BalExpIniCodBar ,BalExpTamCodBar ,BalExpIniDesPrd ,
					BalExpTamDesPrd ,BalExpIniQtdPrd ,BalExpTamQtdPrd ,BalExpFlgCodPrd ,DesMscEndPrd ,CodOpeNfsBal ,CodOpeNfeBal ,CodCliNotBal ,CodZonDivBal ,
					FlgBlqCnfTrf ,CodOpeWmsDef ,BlqEstFisNeg,FlgIntegrWmsExt,DesSisIntWms,FlgIgnQtdMenDvgPdc,FlgIgnPrcMenDvgPdc,WmsFlgBlqImpEtqVolPul)
			Select @CodEstabe ,
					CodClaAbc1 ,PerClaAbcVal1 ,PerClaAbcVol1 ,QtdDiaSeg1 ,CodClaAbc2 ,PerClaAbcVal2 ,PerClaAbcVol2 ,
					QtdDiaSeg2 ,CodClaAbc3 ,PerClaAbcVal3 ,PerClaAbcVol3 ,QtdDiaSeg3 ,CodClaAbc4 ,PerClaAbcVal4 ,PerClaAbcVol4 ,QtdDiaSeg4 ,CodClaAbc5 ,
					PerClaAbcVal5 ,PerClaAbcVol5 ,QtdDiaSeg5 ,CodClaAbc6 ,PerClaAbcVal6 ,PerClaAbcVol6 ,QtdDiaSeg6 ,Usuario ,Transacao ,CodZonDev ,
					CodZonCan ,CodZonDiv ,QtdNivEndPck ,QtdNivEndDep ,WmsFlgBlqImpEtqVol ,WmsFlgBlqImpCodBarPckLst ,WmsFlgBlqRotFecEmbPdv ,FlgCnfIUM ,
					WmsFlgImpFabPckLst ,BalImpIniCodBar ,BalImpTamCodBar ,BalImpIniQtdPrd ,BalImpTamQtdPrd ,BalExpIniCodBar ,BalExpTamCodBar ,BalExpIniDesPrd ,
					BalExpTamDesPrd ,BalExpIniQtdPrd ,BalExpTamQtdPrd ,BalExpFlgCodPrd ,DesMscEndPrd ,CodOpeNfsBal ,CodOpeNfeBal ,CodCliNotBal ,CodZonDivBal ,
					FlgBlqCnfTrf ,CodOpeWmsDef ,BlqEstFisNeg,FlgIntegrWmsExt,DesSisIntWms,FlgIgnQtdMenDvgPdc,FlgIgnPrcMenDvgPdc,WmsFlgBlqImpEtqVolPul
			From PMEST
			Where Cod_Estabe = @CodEstabePai
			And Not Exists(Select 1 From PMEST Where Cod_Estabe = @CodEstabe)

			-- AUDITORIA
			Set @RowCount = @@ROWCOUNT
			Set @TotalCount = @TotalCount+@RowCount;
			If @RowCount > 0
				Insert Into AUDIT (Cod_Estabe,Cod_Ope,Nom_Tabela,Chave1,Chave2,Nom_Campo,Des_Campo,
				            Observ,
				            Usuario,Transacao)
	            Values(@CodEstabe, 'I','PMEST',@CodEstabe,@IdSessao,'Cod_Estabe','PR_ConfiguraESTAB',
				            'Inclusão de '+Convert(varchar(20),@RowCount)+' Registros em PMEST',
					       @Usuario,GetDate() )

			If @RowCount = 0
				Insert Into AUDIT (Cod_Estabe,Cod_Ope,Nom_Tabela,Chave1,Chave2,Nom_Campo,Des_Campo,
				            Observ,
				            Usuario,Transacao)
	            Values(@CodEstabe, 'I','PMEST',@CodEstabe,@IdSessao,'Cod_Estabe','PR_ConfiguraESTAB',
				            'Atenção: Não foram inseridos registros em PMEST',
					       @Usuario,GetDate() )

	      End

		-- Criar FS_PARAM Se não existir nenhum parametro--
		If (@Opcao = 0 or @Opcao = 3) And Not Exists(Select 1 From FS_PARAM Where Cod_Estabe = @CodEstabe)
	      Begin
			Insert Into FS_PARAM
	           (Cod_Estabe ,Cod_Param
	           ,Tip_Param  ,Val_Param
	           ,Dsc_Param  
	           ,Grp_Param  ,Msk_Param)
	        Select @CodEstabe   ,fs.Cod_Param
	           ,fs.Tip_Param    ,fs.Val_Param
	           ,fs.Dsc_Param    
	           ,fs.Grp_Param    ,fs.Msk_Param
			From FS_PARAM fs
			Where fs.Cod_Estabe = @CodEstabePai
			And Not Exists(Select 1 From FS_PARAM 
				           Where Cod_Estabe = @CodEstabe
				           And Cod_Param = fs.Cod_Param)
			-- AUDITORIA
			Set @RowCount = @@ROWCOUNT
			Set @TotalCount = @TotalCount+@RowCount;
			If @RowCount > 0
				Insert Into AUDIT (Cod_Estabe,Cod_Ope,Nom_Tabela,Chave1,Chave2,Nom_Campo,Des_Campo,
				            Observ,
				            Usuario,Transacao)
	            Values(@CodEstabe, 'I','FS_PARAM',@CodEstabe,@IdSessao,'Cod_Estabe','PR_ConfiguraESTAB',
				            'Inclusão de '+Convert(varchar(20),@RowCount)+' Registros em FS_PARAM',
					       @Usuario,GetDate() )

			If @RowCount = 0
				Insert Into AUDIT (Cod_Estabe,Cod_Ope,Nom_Tabela,Chave1,Chave2,Nom_Campo,Des_Campo,
				            Observ,
				            Usuario,Transacao)
	            Values(@CodEstabe, 'I','FS_PARAM',@CodEstabe,@IdSessao,'Cod_Estabe','PR_ConfiguraESTAB',
				            'Atenção: Não foram inseridos registros em FS_PARAM',
					       @Usuario,GetDate() )
	      End


	    -- Criar MIX de PRODUTOS
	    If (@Opcao = 0 or @Opcao = 4)
	      Begin
			--Depósito PADRÃO

			--Verifica se nao existe cria
		    Select Top 1 @CodDep = Cod_Dep 
			From TBDEP 
			Where Cod_Estabe = @CodEstabe
			Order By Cod_Dep
		    
			If @@ROWCOUNT = 0 
			Begin
				Set @CodDep = IsNull(@CodDep,0) + 1
				Insert Into TBDEP(Cod_Dep,Des_Dep,Cod_Estabe)
				Values (@CodDep,'DEPOSITO PADRÃO',@CodEstabe)
				-- AUDITORIA
				Set @RowCount = @@ROWCOUNT
				Set @TotalCount = @TotalCount+@RowCount;
				If @RowCount > 0
					Insert Into AUDIT (Cod_Estabe,Cod_Ope,Nom_Tabela,Chave1,Chave2,Nom_Campo,Des_Campo,
								Observ,
								Usuario,Transacao)
					Values(@CodEstabe, 'I','TBDEP',@CodEstabe,@CodDep,'Cod_Estabe','PR_ConfiguraESTAB',
								'Inclusão de '+Convert(varchar(20),@RowCount)+' Registros em TBDEP',
							    @Usuario,GetDate() )

				If @RowCount = 0
					Insert Into AUDIT (Cod_Estabe,Cod_Ope,Nom_Tabela,Chave1,Chave2,Nom_Campo,Des_Campo,
								Observ,
								Usuario,Transacao)
					Values(@CodEstabe, 'I','TBDEP',@CodEstabe,@IdSessao,'Cod_Estabe','PR_ConfiguraESTAB',
								'Atenção: Não foram inseridos registros em TBDEP',
							   @Usuario,GetDate() )

			End

			--Criando MIX do estabelecimento novo
			--Copiar do estabelecimento pai - se existir
			IF Exists(Select 1 From PRXES Where Cod_Estabe = @CodEstabePai)
				Insert Into dbo.PRXES
							(Cod_Estabe, Cod_Produt	,Qtd_Transi, Qtd_Fisico				
							,Qtd_Solici, Qtd_Avaria	,Qtd_Reserv, Qtd_Dispon				
							,Qtd_Quaren, Qtd_CrossDock
							,Prc_Venda , Prc_Fabric ,Prc_MaxCon
							,Prc_Pmz   , Prc_Tabela ,Flg_BlqCfv, Flg_BlqCmp
							,Flg_BlqCot, Flg_BlqDsc ,Flg_BlqInfPar, Flg_BlqInfVen
							,Flg_BlqPrp, Flg_BlqVen ,Flg_CesBas, Flg_PlaFatPrcLiq
							,Flg_RegSbtEsp, Flg_UsoExcHsp ,Usuario , Transacao
							,Dat_PrcAtual, Dat_PrcFab, Cod_ClaTri, Cod_OriMer)
				Select       @CodEstabe,p.Codigo    ,0         ,0         
							,0         ,0           ,0         ,0         
							,0         ,0         
							,Prc_Venda =    case when es.Per_AlqIcm=12   then p.Prc_Fabric12
												 when es.Per_AlqIcm=17   then p.Prc_Fabric17
												 when es.Per_AlqIcm=17.5 then p.Prc_Fabric175
												 when es.Per_AlqIcm=18   then p.Prc_Fabric18
												 when es.Per_AlqIcm=19   then p.Prc_Fabric19
												 when es.Per_AlqIcm=19.5 then p.Prc_Fabric195
												 when es.Per_AlqIcm=20   then p.Prc_Fabric20
												 when es.Per_AlqIcm=20.5 then p.Prc_Fabric205
												 when es.Per_AlqIcm=21   then p.Prc_Fabric21
												 when es.Per_AlqIcm=22   then p.Prc_Fabric22
												 else e.Prc_Venda
											end
							,Prc_Fabric =   case when es.Per_AlqIcm=12   then p.Prc_Fabric12
												 when es.Per_AlqIcm=17   then p.Prc_Fabric17
												 when es.Per_AlqIcm=17.5 then p.Prc_Fabric175
												 when es.Per_AlqIcm=18   then p.Prc_Fabric18
												 when es.Per_AlqIcm=19   then p.Prc_Fabric19
												 when es.Per_AlqIcm=19.5 then p.Prc_Fabric195
												 when es.Per_AlqIcm=20   then p.Prc_Fabric20
												 when es.Per_AlqIcm=20.5 then p.Prc_Fabric205
												 when es.Per_AlqIcm=21   then p.Prc_Fabric21
												 when es.Per_AlqIcm=22   then p.Prc_Fabric22
												 else e.Prc_Fabric
											end
							,Prc_MaxCon =   case when es.Per_AlqIcm=12   then p.Prc_MaxCon12
												 when es.Per_AlqIcm=17   then p.Prc_MaxCon17
												 when es.Per_AlqIcm=17.5 then p.Prc_MaxCon175
												 when es.Per_AlqIcm=18   then p.Prc_MaxCon18
												 when es.Per_AlqIcm=19   then p.Prc_MaxCon19
												 when es.Per_AlqIcm=19.5 then p.Prc_MaxCon195
												 when es.Per_AlqIcm=20   then p.Prc_MaxCon20
												 when es.Per_AlqIcm=20.5 then p.Prc_MaxCon205
												 when es.Per_AlqIcm=21   then p.Prc_MaxCon21
												 when es.Per_AlqIcm=22   then p.Prc_MaxCon22
												 else e.Prc_MaxCon
											end

							,e.Prc_Pmz ,e.Prc_Tabela,e.Flg_BlqCfv,e.Flg_BlqCmp
							,e.Flg_BlqCot,e.Flg_BlqDsc,e.Flg_BlqInfPar,e.Flg_BlqInfVen
							,e.Flg_BlqPrp,e.Flg_BlqVen,e.Flg_CesBas,e.Flg_PlaFatPrcLiq
							,e.Flg_RegSbtEsp,e.Flg_UsoExcHsp, @Usuario ,GetDate()
							,cast( GetDate() as Date ),cast( GetDate() as Date), e.Cod_ClaTri, e.Cod_OriMer
				From PRODU p
				Inner Join PRXES e On e.Cod_Estabe = @CodEstabePai and p.Codigo = e.Cod_Produt
				Inner Join ESTAB es On es.Cod_Estabe = @CodEstabe -- Configuração do novo estabelecimento
				Where p.Codigo not in (Select x.Cod_Produt 
					                   From PRXES x 
									   Where x.Cod_Estabe = @CodEstabe
									   And x.Cod_Produt = p.Codigo)

			/*
			Após conversa com Meire, ficou esclarecido que se não for encontrado o produto no estabelecimento 
			sugerido(Pai) não é para ser importado, principalmente por conta da falta da classificação 
			tributaria, que irá impactarem questões fiscais.
			ELSE
				Insert Into dbo.PRXES
							(Cod_Estabe, Cod_Produt				
							,Qtd_Transi, Qtd_Fisico				
							,Qtd_Solici, Qtd_Avaria				
							,Qtd_Reserv, Qtd_Dispon				
							,Qtd_Quaren, Qtd_CrossDock 
							, Prc_Venda
                            ,Prc_Fabric, Prc_MaxCon							
							,Usuario   , Transacao
							,Dat_PrcAtual, Dat_PrcFab)
				Select       @CodEstabe,p.Codigo  
							,0         ,0         
							,0         ,0         
							,0         ,0         
							,0         ,0
							,Prc_Venda =    case when es.Per_AlqIcm=12   then p.Prc_Fabric12
												 when es.Per_AlqIcm=17   then p.Prc_Fabric17
												 when es.Per_AlqIcm=17.5 then p.Prc_Fabric175
												 when es.Per_AlqIcm=18   then p.Prc_Fabric18
												 when es.Per_AlqIcm=19   then p.Prc_Fabric19
												 else 0
											end
							,Prc_Fabric =   case when es.Per_AlqIcm=12   then p.Prc_Fabric12
												 when es.Per_AlqIcm=17   then p.Prc_Fabric17
												 when es.Per_AlqIcm=17.5 then p.Prc_Fabric175
												 when es.Per_AlqIcm=18   then p.Prc_Fabric18
												 when es.Per_AlqIcm=19   then p.Prc_Fabric19
												 else 0
											end
							,Prc_MaxCon =   case when es.Per_AlqIcm=12   then p.Prc_MaxCon12
												 when es.Per_AlqIcm=17   then p.Prc_MaxCon17
												 when es.Per_AlqIcm=17.5 then p.Prc_MaxCon175
												 when es.Per_AlqIcm=18   then p.Prc_MaxCon18
												 when es.Per_AlqIcm=19   then p.Prc_MaxCon19
												 else 0
											end
							,@Usuario  ,GetDate()
							,cast( GetDate() as Date ),cast( GetDate() as Date )
				From PRODU p
				Inner Join ESTAB es On es.Cod_Estabe = @CodEstabe -- Configuração do novo estabelecimento
				Where p.Codigo not in (Select Distinct x.Cod_Produt 
					                   From PRXES x 
						               Where x.Cod_Estabe = @CodEstabe 
									   And x.Cod_Produt = p.Codigo)
									   
			*/

			-- AUDITORIA
			Set @RowCount = @@ROWCOUNT
			Set @TotalCount = @TotalCount+@RowCount;
			If @RowCount > 0
				Insert Into AUDIT (Cod_Estabe,Cod_Ope,Nom_Tabela,Chave1,Chave2,Nom_Campo,Des_Campo,
				            Observ,
				            Usuario,Transacao)
	            Values(@CodEstabe, 'I','PRXES',@CodEstabe,@IdSessao,'Cod_Estabe','PR_ConfiguraESTAB',
				            'Inclusão de '+Convert(varchar(20),@RowCount)+' Registros em PRXES',
					       @Usuario,GetDate() )
			If @RowCount = 0
				Insert Into AUDIT (Cod_Estabe,Cod_Ope,Nom_Tabela,Chave1,Chave2,Nom_Campo,Des_Campo,
							Observ,
							Usuario,Transacao)
				Values(@CodEstabe, 'I','PRXES',@CodEstabe,@IdSessao,'Cod_Estabe','PR_ConfiguraESTAB',
							'Atenção: Não foram inseridos registros em PRXES',
						   @Usuario,GetDate() )

	      End

		-- Cria/Copia ENXES do estabelecimento pai se não existir --
		If (@Opcao = 0 or @Opcao = 5)
		  Begin
			Insert Into ENXES ( Cod_Estabe,       Num_CgcCpf,       Cod_Client,        Cod_RegTri,    Cod_AgeCob,         Cod_Transp,      Cod_Rota, Cod_EstEnt,
								Cod_EstabeEntida, Cod_IdeEntida,    Des_LayoutPdc,     Des_DirPedPdc, Des_DirPrePdc,      Des_DirNotPdc,
								Des_PrgComPdc,    Des_UltArqPdc,    Dat_UltArqPdc,     Num_SeqArqPdc, Des_EnderecoFtpPdc ,Des_UsuarioFtpPdc,
								Des_SenhaFtpPdc,  Vlr_UltimaFatura, Data_UltimaFatura, Usuario ,      Transacao,          Cod_DisTra,      UF_PlaVei,
								Cod_PlaVei,       Cod_AgePag,       Cod_Vendedor,      Cod_Operador,  Des_FtpUrlPdc,      Des_FtpUsrPdc,   Des_FtpSnhPdc, 
								Flg_BlqEmbDscItePrcUni,             Flg_BlqIncSbtPrc,  Flg_BlqIncSbtPriDup,               Flg_BlqFecVlrPdvNfsSbtEmb,        
								Flg_ImpSbtEmbPrc, Flg_InfXmlSbtEmbPrc,                 Cod_TabPrc,       Cod_TabPrz,       Qtd_PrzMax) 
			Select @CodEstabe,  a.Num_CgcCpf,     a.Cod_Client, a.Cod_RegTri,    a.Cod_AgeCob,       a.Cod_Transp,    a.Cod_Rota,           a.Cod_EstEnt,
								a.Cod_EstabeEntida,a.Cod_IdeEntida,   a.Des_LayoutPdc,    a.Des_DirPedPdc, a.Des_DirPrePdc,      a.Des_DirNotPdc,
								a.Des_PrgComPdc,   a.Des_UltArqPdc,   a.Dat_UltArqPdc,    a.Num_SeqArqPdc, a.Des_EnderecoFtpPdc, a.Des_UsuarioFtpPdc,
								a.Des_SenhaFtpPdc, a.Vlr_UltimaFatura,a.Data_UltimaFatura, @Usuario     , GetDate(),
								a.Cod_DisTra,a.UF_PlaVei, a.Cod_PlaVei,a.Cod_AgePag,a.Cod_Vendedor,
								a.Cod_Operador,a.Des_FtpUrlPdc,a.Des_FtpUsrPdc,a.Des_FtpSnhPdc,a.Flg_BlqEmbDscItePrcUni,a.Flg_BlqIncSbtPrc,
								a.Flg_BlqIncSbtPriDup,a.Flg_BlqFecVlrPdvNfsSbtEmb,a.Flg_ImpSbtEmbPrc,a.Flg_InfXmlSbtEmbPrc,a.Cod_TabPrc,
								a.Cod_TabPrz,a.Qtd_PrzMax
			From ENXES a
			Where Cod_Estabe = @CodEstabePai
					And isnull(a.Num_CgcCpf, '') <> '' -- Evitar erro de violação de chave primaria
					And Not Exists(Select 1 From ENXES b
				           Where b.Cod_Estabe = @CodEstabe
				           And b.Num_CgcCpf = a.Num_CgcCpf
						   And b.Cod_Client = a.Cod_Client)

			-- Campos complementares Clientes
			Update e
              Set e.Cod_Client = c.Codigo
            From ENXES e
			Inner join CLIEN c On c.Cgc_Cpf = E.Num_CgcCpf
			Where e.Cod_Estabe = @CodEstabe
			And Not Exists( Select 1 From ENXES x Where 
			                    x.Cod_Estabe = @CodEstabe
			                And x.Num_CgcCpf = c.Cgc_Cpf
			                And x.Cod_Client = c.Codigo)

			-- Campos complementares Fornecedores
			Update e
			 Set e.Cod_CadFor = f.Codigo
            From ENXES e
			Inner join FORNE f On f.Cgc_Cpf = E.Num_CgcCpf
			Where e.Cod_Estabe = @CodEstabe
			-- Campos complementares Transportadoras
			Update e
			 Set e.Cod_CadTra = t.Codigo
            From ENXES e
			Inner join TRANS t On t.Cgc_Cpf = E.Num_CgcCpf
			Where e.Cod_Estabe = @CodEstabe

			-- AUDITORIA
			Set @RowCount = @@ROWCOUNT
			Set @TotalCount = @TotalCount+@RowCount;
			If @RowCount > 0
				Insert Into AUDIT (Cod_Estabe,Cod_Ope,Nom_Tabela,Chave1,Chave2,Nom_Campo,Des_Campo,
				            Observ,
				            Usuario,Transacao)
	            Values(@CodEstabe,'I','ENXES',@CodEstabe,@IdSessao,'Cod_Estabe','PR_ConfiguraESTAB',
				            'Inclusão de '+Convert(varchar(20),@RowCount)+' Registros em ENXES',
					       @Usuario,GetDate() )
			If @RowCount = 0
				Insert Into AUDIT (Cod_Estabe,Cod_Ope,Nom_Tabela,Chave1,Chave2,Nom_Campo,Des_Campo,
							Observ,
							Usuario,Transacao)
				Values(@CodEstabe, 'I','ENXES',@CodEstabe,@IdSessao,'Cod_Estabe','PR_ConfiguraESTAB',
							'Atenção: Não foram inseridos registros em ENXES',
						   @Usuario,GetDate() )
	      End


		Commit Transaction		
	End Try
	Begin Catch
	    Select @ErroMsg = ERROR_MESSAGE()
	    Rollback
		RAISERROR (@ErroMsg,1, 1) 
	End Catch
    

  	FETCH NEXT FROM Table_Cr INTO @CodEstabe
END

CLOSE Table_Cr
DEALLOCATE Table_Cr    
RETURN @TotalCount

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_AtualizaPrecoProduto] 
@CodEstabe int

AS

SET NOCOUNT ON

-- Pegar a data atual com a hora zerada 
Set DateFormat ymd
Declare @Now smalldatetime,
        @Date smalldatetime
Set @Now = GetDate()
Set @Date = cast(GetDate() as date)

Begin Transaction

Declare @em_UF varchar(2),
        @em_AlqIcm numeric(18,4)
        
Select @em_UF = Des_Estado, 
       @em_AlqIcm = Per_AlqIcm
  From ESTAB
Where Cod_Estabe = @CodEstabe  

-- atualiza cadastro de produtos: preco de venda
Update pr
  Set pr.Prc_VenAnt = case 
                        When @Date > pr.Dat_PrcAtual then pr.Prc_Venda
                        else pr.Prc_VenAnt
                      end,
      pr.Dat_PrcAnt = case 
                        When @Date > pr.Dat_PrcAtual then pr.Dat_PrcAtual
                        else pr.Dat_PrcAnt
                      end,
      pr.Prc_Venda = ap.Prc_Venda,
      pr.Dat_PrcAtual = @Date,
      pr.Usuario = ap.Usuario,
      pr.Transacao = GetDate()
From ALTPR ap 
     Inner Join PRXES pr on pr.Cod_Estabe = ap.Cod_Estabe And pr.Cod_Produt = ap.Cod_Produto
Where ap.Dat_Vigencia <= @Date
and ap.Prc_Venda <> IsNull(pr.Prc_Venda,0)
And ap.Cod_Estabe = @CodEstabe

Update pr
  Set pr.Prc_Fabric12 = ap.Prc_Fabric12,
	  pr.Prc_MaxCon12 = ap.Prc_MaxCon12,
	  pr.Prc_Fabric17 = ap.Prc_Fabric17,
	  pr.Prc_MaxCon17 = ap.Prc_MaxCon17,
	  pr.Prc_Fabric175 = ap.Prc_Fabric175,
	  pr.Prc_MaxCon175 = ap.Prc_MaxCon175,
	  pr.Prc_Fabric18 = ap.Prc_Fabric18,
	  pr.Prc_MaxCon18 = ap.Prc_MaxCon18,
	  pr.Prc_Fabric19 = ap.Prc_Fabric19,
	  pr.Prc_MaxCon19 = ap.Prc_MaxCon19,
	  pr.Prc_Fabric195 = ap.Prc_Fabric195,
	  pr.Prc_MaxCon195 = ap.Prc_MaxCon195,
	  pr.Prc_Fabric20 = ap.Prc_Fabric20,
	  pr.Prc_MaxCon20 = ap.Prc_MaxCon20,
	  pr.Prc_Fabric205 = ap.Prc_Fabric205,
	  pr.Prc_MaxCon205 = ap.Prc_MaxCon205,
	  pr.Prc_Fabric21 = ap.Prc_Fabric21,
	  pr.Prc_MaxCon21 = ap.Prc_MaxCon21,
	  pr.Prc_Fabric22 = ap.Prc_Fabric22,
	  pr.Prc_MaxCon22 = ap.Prc_MaxCon22,
--      pr.Dat_PrcFab = @Date,
      pr.Usuario = ap.Usuario,
      pr.Transacao = GetDate()
From ALTPR ap 
     Inner Join PRODU pr on pr.Codigo = ap.Cod_Produto
Where ap.Dat_Vigencia <= @Date
And ap.Cod_Estabe = @CodEstabe
and ( (ap.Prc_Fabric12 <> IsNull(pr.Prc_Fabric12,0)) or 
      (ap.Prc_MaxCon12 <> IsNull(pr.Prc_MaxCon12,0)) or 
      (ap.Prc_Fabric17 <> IsNull(pr.Prc_Fabric17,0)) or 
      (ap.Prc_MaxCon17 <> IsNull(pr.Prc_MaxCon17,0)) or 
      (ap.Prc_Fabric175 <> IsNull(pr.Prc_Fabric175,0)) or 
      (ap.Prc_MaxCon175 <> IsNull(pr.Prc_MaxCon175,0)) or 
      (ap.Prc_Fabric18 <> IsNull(pr.Prc_Fabric18,0)) or 
      (ap.Prc_MaxCon18 <> IsNull(pr.Prc_MaxCon18,0)) or 
      (ap.Prc_Fabric19 <> IsNull(pr.Prc_Fabric19,0)) or 
      (ap.Prc_MaxCon19 <> IsNull(pr.Prc_MaxCon19,0)) or 
      (ap.Prc_Fabric195 <> IsNull(pr.Prc_Fabric195,0)) or 
      (ap.Prc_MaxCon195 <> IsNull(pr.Prc_MaxCon195,0)) or 
      (ap.Prc_Fabric20 <> IsNull(pr.Prc_Fabric20,0)) or 
      (ap.Prc_MaxCon20 <> IsNull(pr.Prc_MaxCon20,0)) or
      (ap.Prc_Fabric205 <> IsNull(pr.Prc_Fabric205,0)) or 
      (ap.Prc_MaxCon205 <> IsNull(pr.Prc_MaxCon205,0)) or
      (ap.Prc_Fabric21 <> IsNull(pr.Prc_Fabric21,0)) or 
      (ap.Prc_MaxCon21 <> IsNull(pr.Prc_MaxCon21,0)) or 
      (ap.Prc_Fabric22 <> IsNull(pr.Prc_Fabric22,0)) or 
      (ap.Prc_MaxCon22 <> IsNull(pr.Prc_MaxCon22,0)) )

-- atualiza cadastro de produtos: preco referencia farmacia popular
Update pr
  Set pr.Prc_RefFpbAnt = case 
                           When @Date > pr.Dat_PrcRefFpb then pr.Prc_RefFpb
                           else pr.Prc_RefFpbAnt
                         end,
      pr.Dat_PrcRefFpbAnt = case 
                              When @Date > pr.Dat_PrcRefFpb then pr.Dat_PrcRefFpb
                              else pr.Dat_PrcRefFpbAnt
                            end,
      pr.Prc_RefFpb = ap.Prc_RefFpb,
      pr.Dat_PrcRefFpb = @Date,
      pr.Usuario = ap.Usuario,
      pr.Transacao = GetDate()
From ALTPR ap 
     Inner Join PRODU pr on pr.Codigo = ap.Cod_Produto
Where ap.Dat_Vigencia <= @Date
And ap.Cod_Estabe = @CodEstabe
and ap.Prc_RefFpb <> IsNull(pr.Prc_RefFpb,0)

-- atualiza cadastro de produtos (dados da planilha) p/ produtos liberado
Update pr
  Set pr.Prc_Tabela = null, pr.Prc_CusLiqPla = null, pr.Prc_Pmz = null,
      pr.Per_PlaRepIcm = null, pr.Per_PlaCreIcm = null, pr.Per_PlaDebIcm  =null,
      pr.Per_PlaRebate = null, pr.Per_PlaAgrega = null, pr.Per_PlaDesc1 = null,
      pr.Per_PlaDesc2 = null, pr.Per_PlaBonific = null, pr.Per_PlaIpi = null,
      pr.Per_PlaDesFin = null, pr.Per_PlaCusFre = null, pr.Per_PlaDesOpe = null,
      pr.Per_PlaDesFre = null, pr.Per_PlaDesCom = null, pr.Per_PlaDesPis = null,
      pr.Per_PlaDesCof = null, pr.Per_PlaDesIrpj = null, pr.Per_PlaDesConSoc = null,
      pr.Per_PlaDesIcms = null, pr.Per_PlaMarRes = null, pr.Per_PlaMarOpe = null,
      pr.Taxa_PlaFinanc = null, pr.Per_PlaMarFin = null, pr.Dias_PlaFinanc = null
From ALTPR ap 
     Inner Join PRODU pr on pr.Codigo = ap.Cod_Produto
Where ap.Dat_Vigencia <= @Date and pr.Ctrl_Preco <> 'C'
And ap.Cod_Estabe = @CodEstabe

Update pr
  Set pr.Prc_Tabela = null, pr.Prc_CusLiqPla = null, pr.Prc_Pmz = null,
      pr.Per_PlaRepIcm = null, pr.Per_PlaCreIcm = null, pr.Per_PlaDebIcm  =null,
      pr.Per_PlaRebate = null, pr.Per_PlaAgrega = null, pr.Per_PlaDesc1 = null,
      pr.Per_PlaDesc2 = null, pr.Per_PlaBonific = null, pr.Per_PlaIpi = null,
      pr.Per_PlaDesFin = null, pr.Per_PlaCusFre = null, pr.Per_PlaDesOpe = null,
      pr.Per_PlaDesFre = null, pr.Per_PlaDesCom = null, pr.Per_PlaDesPis = null,
      pr.Per_PlaDesCof = null, pr.Per_PlaDesIrpj = null, pr.Per_PlaDesConSoc = null,
      pr.Per_PlaDesIcms = null, pr.Per_PlaMarRes = null, pr.Per_PlaMarOpe = null,
      pr.Taxa_PlaFinanc = null, pr.Per_PlaMarFin = null, pr.Dias_PlaFinanc = null
From ALTPR ap
     Inner Join PRXES pr on pr.Cod_Estabe = @CodEstabe And pr.Cod_Produt = ap.Cod_Produto
     Inner Join PRODU p on pr.Cod_Produt = p.Codigo
Where ap.Dat_Vigencia <= @Date and p.Ctrl_Preco <> 'C'
And ap.Cod_Estabe = @CodEstabe

-- elimina registros da ALTPR que foram atualizados
Delete from ALTPR
  Where Dat_Vigencia <= @Date
  And Cod_Estabe = @CodEstabe

Commit Transaction

GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CalcTributItemEntrada]
@PCodEstabe int,
@PDatMov smalldatetime,
@PDatEmi smalldatetime,
@PTipNot char(1),
@PCfoCab smallint,
@PCodRegTri int,

@PFlgCalIcmSbt bit,       
@PFlgCalIcmPro bit,       
@PFlgCalRepIcm bit,       
@PFlgCalPisCof bit,       
@PFlgCalIpi bit,
@PFlgDscIcmDesone bit,                  -- icms desonerado eh abatido no valor da nf
@PFlgIncIpiBasIcmTrib bit,              -- adiciona valor ipi ICMS tributável para notas de devolução de uso e consumo

@PClaTri varchar(4),                    -- classificacao tributaria do produto ja existente/importado/devolucao
@PTipLisPis varchar(1),
@PFlgSbtEmbPrc bit,                     -- indica ST embutida no preço

@PCodPrd int,
@PQtdPed int,
@PQtdBon int,
@PPrcUniIte numeric(18,8),
@PPerDscIte numeric(18,8),

@PVlrDscRat numeric(18,4),          
@PVlrDspTot numeric(18,4),              -- despesas totais: frete, seguro, ....
@PVlrDspSbt numeric(18,4), 
@PVlrIpi numeric(18,4),    
@PVlrBasSuf numeric(18,4),
@PVlrTaxSuf numeric(18,4),

@PArqPrcFab numeric(18,4),              -- Pr.Fabrica em PDVIT os NFSIT
@PArqPrcVen numeric(18,4),              -- Pr.Venda
@PArqPrcMax numeric(18,4),              -- Pr.Max.Consumidor
@PArqPrcRefFpb numeric(18,4),           -- Pr.Ref.Farmacia Popular
@PArqPrcPon numeric(18,4),              -- Pr.Medio Ponderado Consumidor Final

@PPrcFab numeric(18,4) output,          -- Pr.Fabrica
@PPrcVen numeric(18,4) output,          -- Pr.Venda
@PPrcMax numeric(18,4) output,          -- Pr.Max.Consumidor
@PPrcRefFpb numeric(18,4) output,       -- Pr.Ref.Farmacia Popular
@PPrcPonFin numeric(18,4) output,       -- Pr.Medio Ponderado Consumidor Final

@PCodModBasCalIcm char(1) output,
@PCodModBasCalIcmSbt char(1) output,
@PCodSt varchar(2) output,
@PCodCsosn varchar(3) output,
@PCstIpi varchar(2) output,
@PCstPis varchar(2) output,
@PCstCof varchar(2) output,
@PTipPrcBasDebSbt varchar(1) output,
@PTipPrcBasCreSbt varchar(1) output,
@PBasTri numeric(18,4) output,          -- valor base tributação
@PAlqIcm numeric(18,4) output,
@PBasIcmPro numeric(18,4) output,       -- Base ICMS proprio
@PIcmPro numeric(18,4) output,          -- ICMS proprio
@PVlrPrdSub numeric(18,4) output,
@PBasSubFnt numeric(18,4) output,
@PVlrSubFnt numeric(18,4) output,
@PBasSbtRes numeric(18,4) output,
@PVlrSbtRes numeric(18,4) output,
@PBasSubRec numeric(18,4) output,
@PVlrSubRec numeric(18,4) output,
@PBasIcm numeric(18,4) output,          -- base icms tributavel
@PVlrIcm numeric(18,4) output,          -- icms tributavel
@PBasIpi numeric(18,4) output,
@PVlrIse numeric(18,4) output,
@PVlrPrdAnt numeric(18,4) output,
@PBasAnt numeric(18,4) output,
@PVlrAnt numeric(18,4) output,
@PVlrOut numeric(18,4) output,
@PPerRedBasCalIcmDeb numeric(18,4) output,
@PAlqAgrDeb numeric(18,4) output,
@PPerRedBasCalDeb numeric(18,4) output,
@PAlqIcmDeb numeric(18,4) output,
@PVlrDebIcm numeric(18,4) output,
@PPerRedBasCalIcmCre numeric(18,4) output,
@PPerLimBasCalCreSbt numeric(18,4) output,
@PVlrLimCreIcm numeric(18,4) output,
@PVlrDspSubCusCreIcm numeric(18,4) output,
@PVlrBasPis numeric(18,4) output,
@PAlqPis numeric(18,4) output,
@PVlrPis numeric(18,4) output,
@PVlrBasCof numeric(18,4) output,
@PAlqCof numeric(18,4) output,
@PVlrCof numeric(18,4) output,
@PVlrSuf numeric(18,4) output,
@PVlrDsp numeric(18,4) output,
@PFlgUsaCreIcmSbt bit output,

@PAlqIpi numeric(18,4) output,
@PCodNcm varchar(8) output,

@PFlgUsaCrePresum bit output,
@PAlqCrePresum numeric(18,4) output,

@PDatRefPrdCip datetime output,

-- novos em 15/01/2019
@PAlqIcmFcp numeric(18,4) output,
@PVlrIcmFcp numeric(18,4) output,       -- icms tributavel FCP: embutido em @PVlrIcm
@PAlqIcmSbtFcp numeric(18,4) output,
@PVlrSubFcp numeric(18,4) output,
@PAlqIcmSbtFcpRet numeric(18,4) output,
@PVlrSubFcpRet numeric(18,4) output,
@PAlqIcmSbtFcpRec numeric(18,4) output,
@PVlrSubFcpRec numeric(18,4) output,
@PAlqIcmSbtFcpAnt numeric(18,4) output,
@PVlrSubFcpAnt numeric(18,4) output,

--novos em 11/06/2019
@PPerIcmDiferi numeric(18,4) output,
@PVlrIcmDiferi numeric(18,4) output,

-- novo em 19/11/2019
@PVlrIcmDesone numeric(18,4) output,      -- icms desonerado
@PMtvIcmDesone varchar(1) output,         -- cod.motivo icms desonerado
@PVlrDst numeric(18,4) output             -- icms desonerado concedido como desconto (desconto de tributacao)

AS

SET NOCOUNT ON 

Begin Transaction

-- variaveis de trabalho
Declare @WQtdLoop tinyint, 
        @WClaTriExt varchar(4),
        @WQtdDecRndTrb tinyint,
        @PObsNf varchar(200),
        @WLiq numeric(18,4),
        @WVlrIte numeric(18,4),
        @WCre numeric(18,4),
        @WCreFcp numeric(18,4),
		@WIcmProFcp numeric(18,4),
        @WCreSbt numeric(18,4),
        @WCreSbtFcp numeric(18,4),
        @WVlrPrdSbt numeric(18,4),
        @WVlrImpSbt numeric(18,4),
        @WVlrPrdSbtLim numeric(18,4),
        @WVlrMinSbt numeric(18,4),
        @WVlrMinBasCalSbt numeric(18,4),
        @WVlrBasSbt numeric(18,4),
        @WVlrBasLimCreSbt numeric(18,4),

        @WVlrPrdSbtOpc numeric(18,4),
        @WVlrImpSbtOpc numeric(18,4),
        @WVlrDebIcmOpc numeric(18,4),

        @WPrcAux numeric(18,4),
        @it_Vlr_TotIte numeric(18,4),
        @it_Vlr_BruIte numeric(18,4)
        
-- variaveis de trabalho extra
Declare @WPerRepIcm numeric(18,4),
        @WPerDspSubCusCreIcm numeric(18,4),
        @WAlqIcmExt numeric(18,4),
        @WAlqIcmExtFcp numeric(18,4),
        @WCtrBasCalDeb varchar(1),
        @WCtrBasCalCre varchar(1),
        @WAlqAgrDeb numeric(18,4),
        @WFatSubTriDeb numeric(18,4),
        @WPerRedBasCalDeb numeric(18,4),
		@WTipPrcLimMinIcmSbt varchar(1),
        @WPerLimMinIcmSbt numeric(18,4),
        @WPerRedBasCalDebOpc numeric(18,4),
        @WTipPrcLimMinBasCalIcmSbt varchar(1),
        @WPerLimMinBasCalIcmSbt numeric(18,4),
        @WAlqAgrLimMinBasCalIcmSbt numeric(18,4),
        @WPerResExt numeric(18,4),
        @WTipCreSbt varchar(1),
        @WAlqDebSbt numeric(18,4),
        @WFlgImpSbtFnt bit,
        @WPerRedBasCalIcmInt numeric(18,4),
        @WAlqIcmInt numeric(18,4),
        @WAlqIcmIntFcp numeric(18,4),
        @WVlrBasPisCof numeric(18,4),
        @WFlgUsaCrePresum bit,
        @WFlgDatEmiPrdCip bit,
        @WFlgDatAntUltAtuPrdCip bit,
        @WAlqCrePresum numeric(18,4),
        @WDatAntUltAlt smalldatetime,
        @WVlrBasResExt numeric(18,4),
        @PVlrBasCalSubTriEntMed numeric(18,4),
        @WDebSbtFcp numeric(18,4),
        @WPerIcmDesRedBasCal numeric(18,4),
        @WPerIcmDesone numeric(18,4),
        @WCodMtvDesone varchar(2),
        @WFlgDscDesIcm bit,
        @WFlgIcmIsento bit

Declare @em_CodTipLuc varchar(2),
        @em_DesEstado varchar(2),
        @pm_FlgExcIcmCalPis bit = 0,
        @pm_FlgIncIpiCalPis bit

Declare @pr_PrcFab numeric(18,4),
        @pr_PrcVen numeric(18,4),
        @pr_PrcMax numeric(18,4),
        @pr_PrcRefFpb numeric(18,4),
        @pr_VlrBasCalSubTriEntMed numeric(18,4)

Declare @rt_ClaTriExt varchar(4),
        @rt_Cod_ImpNotSai varchar(2),
        @rt_Cod_CSOSNSai varchar(3),
        @rt_Tip_PrcBasDebSbt char(1),
        @rt_Ctrl_BasCalDebSai char(1),
        @rt_Alq_AgrDebSai numeric(18,4),
        @rt_Per_RedBasCalDebSai numeric(18,4),
        @rt_Per_LimMinIcmSbtSaiRedDeb numeric(18,4),        
        @rt_Tip_PrcLimMinBasCalIcmSbtSai varchar(1),    -- em 08/01/2019
        @rt_Alq_AgrLimMinBasCalIcmSbtSai numeric(18,4), -- em 08/01/2019       
        @rt_Per_ResExtSai numeric(18,4),        
        @rt_Tip_CreSbtSai char(1),
        @rt_Alq_DebSbtSai numeric(18,4),
        @rt_Alq_IcmIntReg numeric(18,4),
        @rt_Per_AcrAlqIntFcpReg numeric(18,4),
        @rt_Per_RedBasCalIntReg numeric(18,4),
        @rt_Tip_PrcBasCreSbtSai char(1),
        @rt_Ctrl_BasCalCreSai char(1),
        @rt_Alq_IcmExtLoc numeric(18,4),
        @rt_Per_AcrAlqExtFcpLoc numeric(18,4),
        @rt_Per_RedBasCalExtLoc numeric(18,4),
        @rt_Per_IcmDiferiExtLoc numeric(18,4),
        @rt_Per_IcmDesoneExtLoc numeric(18,4),
        @rt_Cod_MtvDesIcmLoc varchar(2),
        @rt_Flg_DscDesIcmLoc bit,
        @rt_C_PerRepIcmLoc numeric(18,4),
        
        @rt_Cod_ImpNotEnt varchar(2),
        @rt_Cod_CSOSNEnt varchar(3),
        @rt_Tip_PrcBasSbtEnt varchar(1),
        @rt_Ctrl_BasCalDebEnt varchar(1),
        @rt_Alq_AgrDebEnt numeric(18,4),
        @rt_Per_RedBasCalDebEnt numeric(18,4),
        @rt_Tip_PrcLimMinBasCalIcmSbtEnt varchar(1),
        @rt_Per_LimMinBasCalIcmSbtEnt numeric(18,4), 
        @rt_Per_ResExtEnt numeric(18,4),        
        @rt_Tip_CreSbtEnt varchar(1),
        @rt_Alq_DebSbtEnt numeric(18,4),
        @rt_Flg_ImpSbtFntEnt bit, 
        @rt_Alq_IcmIntLoc numeric(18,4),
        @rt_Per_AcrAlqIntFcpLoc numeric(18,4),
        @rt_Per_RedBasCalIntLoc numeric(18,4),
        @rt_Tip_PrcBasCreSbtEnt varchar(1),
        @rt_Ctrl_BasCalCreEnt varchar(1),
        @rt_Per_LimBasCalCreSbtEnt numeric(18,4),
        @rt_Alq_IcmExtReg numeric(18,4),
        @rt_Per_AcrAlqExtFcpReg numeric(18,4),
        @rt_Per_RedBasCalExtReg numeric(18,4),
        @rt_Per_IcmDiferiExtReg numeric(18,4),
        @rt_Per_IcmDesoneExtReg numeric(18,4),
        @rt_Cod_MtvDesIcmReg varchar(2),
        @rt_Flg_DscDesIcmReg bit,
        @rt_C_PerRepIcmReg numeric(18,4),
		@rt_Tip_PrcLimMinIcmSbtEnt varchar(1),
        @rt_Per_LimMinIcmSbtEnt numeric(18,4),
        @rt_Per_RedBasCalDebEntOpc numeric(18,4),
		@rt_PerDspCusEnt  numeric(18,4),

		@rt_Alq_CrePresum numeric(18,4),
        @rg_Flg_UsaCrePresum bit,
        @rg_Flg_DatEmiPrdCip bit,
		@rg_Flg_DatAntUltAtuPrdCip bit,
        @ct_FlgSujAntIcm bit

-- coloca campos de tabelas na memoria
-- ESTAB / PARAM
Select @em_CodTipLuc = IsNull(Cod_TipLucro,''),
       @em_DesEstado = IsNull(Des_Estado,'')
  From ESTAB
Where Cod_Estabe = @PCodEstabe  

Select @pm_FlgIncIpiCalPis = IsNull(FlgIncIpiCalPis,0),
       @pm_FlgExcIcmCalPis = IsNull(FlgExcIcmCalPis,0)
  From PARAM
Where Cod_Estabe = @PCodEstabe  


-- qtd casa decimais para arredondamento de tributos
-- as bases de calculo sempre 2 casas
Set @WQtdDecRndTrb = 2

Set @WQtdLoop = 1

LOOP_INICIO:

Set @PBasTri    = 0
Set @PBasIcmPro = 0
Set @PAlqIcm    = 0
Set @PIcmPro    = 0
Set @PBasIcm    = 0
Set @PVlrIcm    = 0
Set @PVlrIse    = 0
Set @PVlrOut    = 0

Set @PVlrPrdSub = 0
Set @PBasSubFnt = 0
Set @PVlrSubFnt = 0
Set @PBasSbtRes = 0
Set @PVlrSbtRes = 0
Set @PBasSubRec = 0
Set @PVlrSubRec = 0
Set @PVlrPrdAnt = 0
Set @PBasAnt    = 0
Set @PVlrAnt    = 0

Set @PBasIpi    = 0
Set @PVlrSuf    = 0
Set @PVlrDsp    = 0

Set @PPerRedBasCalIcmDeb = 0
Set @PAlqAgrDeb = 0
Set @PPerRedBasCalDeb = 0
Set @PAlqIcmDeb = 0
Set @PVlrDebIcm = 0
Set @PPerRedBasCalIcmCre = 0
Set @PPerLimBasCalCreSbt = 0
Set @PVlrLimCreIcm = 0
Set @PVlrDspSubCusCreIcm = 0
Set @PCodModBasCalIcm = ''
Set @PCodModBasCalIcmSbt = ''
Set @PFlgUsaCreIcmSbt = 0
Set @PAlqIpi = 0
Set @PCodNcm = ''
Set @PFlgUsaCrePresum = 0
Set @PAlqCrePresum = 0
Set @PObsNf = ''

Set @PAlqIcmFcp = 0
Set @PVlrIcmFcp = 0
Set @PAlqIcmSbtFcp = 0
Set @PVlrSubFcp = 0
Set @PAlqIcmSbtFcpRet = 0
Set @PVlrSubFcpRet = 0
Set @PAlqIcmSbtFcpRec = 0
Set @PVlrSubFcpRec = 0
Set @PAlqIcmSbtFcpAnt = 0
Set @PVlrSubFcpAnt = 0

Set @PPerIcmDiferi = 0
Set @PVlrIcmDiferi = 0

Set @PVlrIcmDesone = 0
Set @PMtvIcmDesone = ''
Set @PVlrDst = 0

Set @WVlrBasResExt = 0
Set @WIcmProFcp = 0
Set @WDebSbtFcp = 0

-- coloca campos de RTXCT na memoria
Select @rt_Cod_ImpNotSai  = IsNull(rx.Cod_ImpNotSai,''),
       @rt_Cod_CSOSNSai = IsNull(rx.Cod_CSOSNSai,''),
       @rt_ClaTriExt = IsNull(rx.Cod_ClaTriExt,''),
       @rt_Tip_PrcBasDebSbt = IsNull(rx.Tip_PrcBasDebSbt,''),
       @rt_Ctrl_BasCalDebSai = IsNull(rx.Ctrl_BasCalDebSai,''),
       @rt_Alq_AgrDebSai = Isnull(rx.Alq_AgrDebSai,0),
       @rt_Per_RedBasCalDebSai = Isnull(rx.Per_RedBasCalDebSai,0),
       @rt_Per_LimMinIcmSbtSaiRedDeb = IsNull(rx.Per_LimMinIcmSbtSaiRedDeb,0),

	   @rt_Tip_PrcLimMinBasCalIcmSbtSai = IsNull(rx.Tip_PrcLimMinBasCalIcmSbtSai,''),
	   @rt_Alq_AgrLimMinBasCalIcmSbtSai = IsNull(rx.Alq_AgrLimMinBasCalIcmSbtSai,0),

       @rt_Per_ResExtSai = IsNull(rx.Per_ResExtSai,0),
       @rt_Tip_CreSbtSai = Isnull(rx.Tip_CreSbtSai,''),
       @rt_Alq_DebSbtSai = Isnull(rx.Alq_DebSbtSai,0),
       @rt_Alq_IcmIntReg = Isnull(rx.Alq_IcmIntReg,0),
       @rt_Per_AcrAlqIntFcpReg = Isnull(rx.Per_AcrAlqIntFcpReg,0),
       @rt_Per_RedBasCalIntReg = Isnull(rx.Per_RedBasCalIntReg,0),
       @rt_Tip_PrcBasCreSbtSai = IsNull(rx.Tip_PrcBasCreSbtSai,''),
       @rt_Ctrl_BasCalCreSai = IsNull(rx.Ctrl_BasCalCreSai,''),
       @rt_Alq_IcmExtLoc = Isnull(rx.Alq_IcmExtLoc,0),
       @rt_Per_AcrAlqExtFcpLoc = Isnull(rx.Per_AcrAlqExtFcpLoc,0),
       @rt_Per_RedBasCalExtLoc = Isnull(rx.Per_RedBasCalExtLoc,0),
       @rt_Per_IcmDiferiExtLoc = Isnull(rx.Per_IcmDiferiExtLoc,0),
       @rt_Per_IcmDesoneExtLoc = Isnull(rx.Per_IcmDesoneExtLoc,0),
       @rt_Cod_MtvDesIcmLoc = Isnull(rx.Cod_MtvDesIcmLoc,'9'),
       @rt_C_PerRepIcmLoc = Isnull(rx.C_PerRepIcmLoc,0),
       @rt_Cod_ImpNotEnt  = IsNull(rx.Cod_ImpNotEnt,''),
       @rt_Cod_CSOSNEnt = IsNull(rx.Cod_CSOSNEnt,''),
       @rt_Tip_PrcBasSbtEnt = IsNull(rx.Tip_PrcBasSbtEnt,''),
       @rt_Ctrl_BasCalDebEnt  = IsNull(rx.Ctrl_BasCalDebEnt,''),
       @rt_Alq_AgrDebEnt = Isnull(rx.Alq_AgrDebEnt,0),
       @rt_Per_RedBasCalDebEnt = Isnull(rx.Per_RedBasCalDebEnt,0),
       @rt_Tip_PrcLimMinBasCalIcmSbtEnt = IsNull(Tip_PrcLimMinBasCalIcmSbtEnt,''),
       @rt_Per_LimMinBasCalIcmSbtEnt = IsNull(Per_LimMinBasCalIcmSbtEnt,0),
       @rt_Per_ResExtEnt = IsNull(rx.Per_ResExtEnt,0),
       @rt_Tip_CreSbtEnt = IsNull(rx.Tip_CreSbtEnt,''),
       @rt_Alq_DebSbtEnt = Isnull(rx.Alq_DebSbtEnt,0),
       @rt_Flg_ImpSbtFntEnt = IsNull(rx.Flg_ImpSbtFntEnt,0),
       @rt_Alq_IcmIntLoc = Isnull(rx.Alq_IcmIntLoc,0),
       @rt_Per_AcrAlqIntFcpLoc = IsNull(rx.Per_AcrAlqIntFcpLoc,0),
       @rt_Per_RedBasCalIntLoc = Isnull(rx.Per_RedBasCalIntLoc,0),
       @rt_Tip_PrcBasCreSbtEnt = IsNull(rx.Tip_PrcBasCreSbtEnt,''),
       @rt_Ctrl_BasCalCreEnt = IsNull(rx.Ctrl_BasCalCreEnt,''),
       @rt_Per_LimBasCalCreSbtEnt = IsNull(rx.Per_LimBasCalCreSbtEnt,0),
       @rt_Alq_IcmExtReg = Isnull(rx.Alq_IcmExtReg,0),
       @rt_Per_AcrAlqExtFcpReg = Isnull(rx.Per_AcrAlqExtFcpReg,0),
       @rt_Per_RedBasCalExtReg = Isnull(rx.Per_RedBasCalExtReg,0),
       @rt_C_PerRepIcmReg = Isnull(rx.C_PerRepIcmReg,0),
       @rt_Per_IcmDiferiExtReg = Isnull(rx.Per_IcmDiferiExtReg,0),
       @rt_Per_IcmDesoneExtReg = Isnull(rx.Per_IcmDesoneExtReg,0),
       @rt_Cod_MtvDesIcmReg = Isnull(rx.Cod_MtvDesIcmReg,'9'),
	   @rt_Tip_PrcLimMinIcmSbtEnt = IsNull(rx.Tip_PrcLimMinIcmSbtEnt,''),
       @rt_Per_LimMinIcmSbtEnt = IsNull(rx.Per_LimMinIcmSbtEnt,0),
       @rt_Per_RedBasCalDebEntOpc = IsNull(rx.Per_RedBasCalDebEntOpc,0),
	   @rt_PerDspCusEnt = IsNull(rx.Per_DspCusEnt,0),
       @rg_Flg_UsaCrePresum = IsNull(rg.Flg_UsaCrePresum,0),
       @rg_Flg_DatEmiPrdCip = IsNull(rg.Flg_DatEmiPrdCip,0),
       @rg_Flg_DatAntUltAtuPrdCip = IsNull(rg.Flg_DatAntUltAtuPrdCip,0),
       @rt_Alq_CrePresum = Case 
	                         When IsNull(rg.Flg_UsaCrePresum,0) = 1 then IsNull(rx.Alq_IcmPresumReg,0) 
							 Else 0 
                           End    
  From RTXCT rx
       Inner Join RGTRI rg on rx.Cod_RegTri = rg.Cod_RegTri
Where rx.Cod_RegTri = @PCodRegTri
and rx.Cod_ClaTri = @PClaTri

Select @ct_FlgSujAntIcm = IsNull(Flg_SujAntIcm,0) 
  From CLTRI
Where Cod_ClaTri = @PClaTri

if @PTipNot <> 'D'  -- tipo da nota diferente de devolucao
  begin
    -- compras, outras entradas
	Set @WClaTriExt             = @rt_ClaTriExt
    Set @PCodSt                 = @rt_Cod_ImpNotEnt
    Set @PCodCsosn              = @rt_Cod_CSOSNEnt
    Set @PTipPrcBasDebSbt       = @rt_Tip_PrcBasSbtEnt
    Set @WCtrBasCalDeb          = @rt_Ctrl_BasCalDebEnt
          
    Set @PAlqAgrDeb             = @rt_Alq_AgrDebEnt
    Set @WFatSubTriDeb          = 1 + @rt_Alq_AgrDebEnt/100
    Set @PPerRedBasCalDeb       = @rt_Per_RedBasCalDebEnt
          
    Set @WTipPrcLimMinBasCalIcmSbt = @rt_Tip_PrcLimMinBasCalIcmSbtEnt
    Set @WPerLimMinBasCalIcmSbt    = @rt_Per_LimMinBasCalIcmSbtEnt
    Set @WAlqAgrLimMinBasCalIcmSbt = 0

    Set @WPerResExt             = @rt_Per_ResExtEnt
    Set @WTipCreSbt             = @rt_Tip_CreSbtEnt
    Set @WAlqDebSbt             = @rt_Alq_DebSbtEnt
	Set @WTipPrcLimMinIcmSbt    = @rt_Tip_PrcLimMinIcmSbtEnt
    Set @WPerLimMinIcmSbt       = @rt_Per_LimMinIcmSbtEnt
    Set @WAlqIcmInt             = @rt_Alq_IcmIntLoc
    Set @WAlqIcmIntFcp          = @rt_Per_AcrAlqIntFcpLoc
    Set @PPerRedBasCalIcmDeb    = @rt_Per_RedBasCalIntLoc
    Set @WPerRedBasCalDebOpc    = @rt_Per_RedBasCalDebEntOpc
    Set @WFlgImpSbtFnt          = @rt_Flg_ImpSbtFntEnt

    Set @PTipPrcBasCreSbt       = @rt_Tip_PrcBasCreSbtEnt
    Set @WCtrBasCalCre          = @rt_Ctrl_BasCalCreEnt
    Set @PPerLimBasCalCreSbt    = @rt_Per_LimBasCalCreSbtEnt
    Set @WAlqIcmExt             = @rt_Alq_IcmExtReg
    Set @WAlqIcmExtFcp          = @rt_Per_AcrAlqExtFcpReg
    Set @PPerRedBasCalIcmCre    = @rt_Per_RedBasCalExtReg
	Set @PPerIcmDiferi          = @rt_Per_IcmDiferiExtReg
	Set @WPerIcmDesone          = @rt_Per_IcmDesoneExtReg
    Set @WCodMtvDesone          = @rt_Cod_MtvDesIcmReg
    Set @WFlgDscDesIcm          = @rt_Flg_DscDesIcmReg
    Set @WPerRepIcm             = @rt_C_PerRepIcmReg
  	Set @WPerDspSubCusCreIcm    = @rt_PerDspCusEnt
    Set @WFlgUsaCrePresum       = @rg_Flg_UsaCrePresum
    Set @WAlqCrePresum          = @rt_Alq_CrePresum
	Set @WFlgDatEmiPrdCip       = @rg_Flg_DatEmiPrdCip
	Set @WFlgDatAntUltAtuPrdCip = @rg_Flg_DatAntUltAtuPrdCip
  end
else
  begin
    -- devolucao
	Set @WClaTriExt             = ''
    Set @PCodSt                 = @rt_Cod_ImpNotSai
    Set @PCodCsosn              = @rt_Cod_CSOSNSai
    Set @PTipPrcBasDebSbt       = @rt_Tip_PrcBasDebSbt
    Set @WCtrBasCalDeb          = @rt_Ctrl_BasCalDebSai
    
    Set @PAlqAgrDeb             = @rt_Alq_AgrDebSai
    Set @WFatSubTriDeb          = 1 + @rt_Alq_AgrDebSai/100
    Set @PPerRedBasCalDeb       = @rt_Per_RedBasCalDebSai
    
    Set @WTipPrcLimMinBasCalIcmSbt = @rt_Tip_PrcLimMinBasCalIcmSbtSai
    Set @WPerLimMinBasCalIcmSbt    = 0
    Set @WAlqAgrLimMinBasCalIcmSbt = @rt_Alq_AgrLimMinBasCalIcmSbtSai     

    Set @WPerResExt             = @rt_Per_ResExtSai
    Set @WTipCreSbt             = @rt_Tip_CreSbtSai
    Set @WAlqDebSbt             = @rt_Alq_DebSbtSai
	Set @WTipPrcLimMinIcmSbt    = ''
    Set @WPerLimMinIcmSbt       = 0
    Set @WAlqIcmInt             = @rt_Alq_IcmIntReg
    Set @WAlqIcmIntFcp          = @rt_Per_AcrAlqIntFcpReg
    Set @PPerRedBasCalIcmDeb    = @rt_Per_RedBasCalIntReg
    Set @WPerRedBasCalDebOpc    = 0
    Set @WFlgImpSbtFnt          = 1

    Set @PTipPrcBasCreSbt       = @rt_Tip_PrcBasCreSbtSai
    Set @WCtrBasCalCre          = @rt_Ctrl_BasCalCreSai
    Set @PPerLimBasCalCreSbt    = 0
    Set @WAlqIcmExt             = @rt_Alq_IcmExtLoc
    Set @WAlqIcmExtFcp          = @rt_Per_AcrAlqExtFcpLoc
    Set @PPerRedBasCalIcmCre    = @rt_Per_RedBasCalExtLoc
    Set @PPerIcmDiferi          = @rt_Per_IcmDiferiExtLoc
    Set @WPerIcmDesone          = @rt_Per_IcmDesoneExtLoc
    Set @WCodMtvDesone          = @rt_Cod_MtvDesIcmLoc
    Set @WFlgDscDesIcm          = @rt_Flg_DscDesIcmLoc
    Set @WPerRepIcm             = @rt_C_PerRepIcmLoc
    Set @WPerDspSubCusCreIcm    = 0
    Set @WFlgUsaCrePresum       = 0
    Set @WAlqCrePresum          = 0
	Set @WFlgDatEmiPrdCip       = 0
	Set @WFlgDatAntUltAtuPrdCip = 0

end

-- coloca campo de PRODU na memoria
Select @PTipLisPis = pr.Tip_LisPis,
       @PCodNcm = Substring(Ltrim(Rtrim(pr.Cod_ClaFis)),1,8),
       @PAlqIpi = IsNull(pr.Per_Ipi,0),
       @pr_PrcVen = Isnull(p.Prc_Venda,0),
       @pr_PrcRefFpb = Isnull(pr.Prc_RefFpb,0),
       @pr_PrcFab = Case
                      When (Round(@WAlqIcmInt,2) = 12.00) and (IsNull(pr.Prc_Fabric12,0)  > 0) Then IsNull(pr.Prc_Fabric12,0)
                      When (Round(@WAlqIcmInt,2) = 17.00) and (IsNull(pr.Prc_Fabric17,0)  > 0) Then IsNull(pr.Prc_Fabric17,0)
                      When (Round(@WAlqIcmInt,2) = 17.50) and (IsNull(pr.Prc_Fabric175,0) > 0) Then IsNull(pr.Prc_Fabric175,0)
                      When (Round(@WAlqIcmInt,2) = 18.00) and (IsNull(pr.Prc_Fabric18,0)  > 0) Then IsNull(pr.Prc_Fabric18,0)
                      When (Round(@WAlqIcmInt,2) = 19.00) and (IsNull(pr.Prc_Fabric19,0)  > 0) Then IsNull(pr.Prc_Fabric19,0)
                      When (Round(@WAlqIcmInt,2) = 19.50) and (IsNull(pr.Prc_Fabric195,0) > 0) Then IsNull(pr.Prc_Fabric195,0)
                      When (Round(@WAlqIcmInt,2) = 20.00) and (IsNull(pr.Prc_Fabric20,0)  > 0) Then IsNull(pr.Prc_Fabric20,0)
                      When (Round(@WAlqIcmInt,2) = 20.50) and (IsNull(pr.Prc_Fabric205,0) > 0) Then IsNull(pr.Prc_Fabric205,0)
                      When (Round(@WAlqIcmInt,2) = 21.00) and (IsNull(pr.Prc_Fabric21,0)  > 0) Then IsNull(pr.Prc_Fabric21,0)
                      When (Round(@WAlqIcmInt,2) = 22.00) and (IsNull(pr.Prc_Fabric22,0)  > 0) Then IsNull(pr.Prc_Fabric22,0)
                      Else Isnull(p.Prc_Fabric,0)
                    End,
       @pr_PrcMax = Case
                      When (Round(@WAlqIcmInt,2) = 12.00) and (IsNull(pr.Prc_MaxCon12,0)  > 0) Then IsNull(pr.Prc_MaxCon12,0)
                      When (Round(@WAlqIcmInt,2) = 17.00) and (IsNull(pr.Prc_MaxCon17,0)  > 0) Then IsNull(pr.Prc_MaxCon17,0)
                      When (Round(@WAlqIcmInt,2) = 17.50) and (IsNull(pr.Prc_MaxCon175,0) > 0) Then IsNull(pr.Prc_MaxCon175,0)
                      When (Round(@WAlqIcmInt,2) = 18.00) and (IsNull(pr.Prc_MaxCon18,0)  > 0) Then IsNull(pr.Prc_MaxCon18,0)
                      When (Round(@WAlqIcmInt,2) = 19.00) and (IsNull(pr.Prc_MaxCon19,0)  > 0) Then IsNull(pr.Prc_MaxCon19,0)
                      When (Round(@WAlqIcmInt,2) = 19.50) and (IsNull(pr.Prc_MaxCon195,0) > 0) Then IsNull(pr.Prc_MaxCon195,0)
                      When (Round(@WAlqIcmInt,2) = 20.00) and (IsNull(pr.Prc_MaxCon20,0)  > 0) Then IsNull(pr.Prc_MaxCon20,0)
                      When (Round(@WAlqIcmInt,2) = 20.50) and (IsNull(pr.Prc_MaxCon205,0) > 0) Then IsNull(pr.Prc_MaxCon205,0)
                      When (Round(@WAlqIcmInt,2) = 21.00) and (IsNull(pr.Prc_MaxCon21,0)  > 0) Then IsNull(pr.Prc_MaxCon21,0)
                      When (Round(@WAlqIcmInt,2) = 22.00) and (IsNull(pr.Prc_MaxCon22,0)  > 0) Then IsNull(pr.Prc_MaxCon22,0)
                      Else Isnull(p.Prc_MaxCon,0)
                    End,
	   @pr_VlrBasCalSubTriEntMed = IsNull(p.Vlr_BasCalSubTriEntMed,0)
  From PRXES p Inner Join PRODU pr on p.Cod_Produt = pr.Codigo
Where p.Cod_Estabe = @PCodEstabe 
And p.Cod_Produt = @PCodPrd

Set @PPrcVen = ISNULL(@PArqPrcVen,0)

if @PTipNot = 'D'  -- tipo da nota devolucao
  begin
    Set @PPrcFab = IsNull(@PArqPrcFab,0)
    Set @PPrcMax = IsNull(@PArqPrcMax,0)
	Set @PPrcRefFpb = IsNull(@PArqPrcRefFpb,0)
  end
else
  begin
    Set @PPrcFab = 0
    Set @PPrcMax = 0
	Set @PPrcRefFpb = 0
  end

-- data anterior á ult. atualização de preço
if Exists(Select 1
          From HSPRC
          Where Cod_Estabe = @PCodEstabe
          And Cod_Produto = @PCodPrd
          And Dat_Alteracao <= @PDatMov)
  Select top 1 @WDatAntUltAlt = Dat_Alteracao - 1
  From HSPRC
  Where Cod_Estabe = @PCodEstabe
  And Cod_Produto = @PCodPrd
  And Dat_Alteracao <= @PDatMov
  Order by Dat_Alteracao desc
else
  Set @WDatAntUltAlt = @PDatMov

-- data referencia para preços "monitorados"
Set @PDatRefPrdCip = Case 
                       When @WFlgDatEmiPrdCip = 1 then @PDatEmi
                       When @WFlgDatAntUltAtuPrdCip = 1 then @WDatAntUltAlt
                       Else @PDatMov
                     End

if @PPrcVen = 0
  begin
    Set @WPrcAux = IsNull((Select TOP 1 Vlr_PrcVen
                             From HSPRC
                           Where Cod_Estabe = @PCodEstabe 
                           and Cod_Produto = @PCodPrd
                           And Dat_Alteracao <= @PDatMov
                           Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
    if @WPrcAux > 0
      Set @PPrcVen = @WPrcAux
    else           
      Set @PPrcVen = @pr_PrcVen
  end

if @PPrcRefFpb = 0
  begin
    Set @WPrcAux = IsNull((Select TOP 1 Vlr_RefFpb
                           From HSPRC
                           Where Cod_Estabe = @PCodEstabe 
                           and Cod_Produto = @PCodPrd
                           and Dat_Alteracao <= @PDatRefPrdCip 
                           Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
    if @WPrcAux > 0
      Set @PPrcRefFpb = @WPrcAux
    else           
      Set @PPrcRefFpb = @pr_PrcRefFpb
  end

if @PPrcFab = 0
  begin
    Set @WPrcAux = Case
                     When Round(@WAlqIcmInt,2) = 12.00 Then IsNull((Select TOP 1 Vlr_PrcFab12 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip 
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     When Round(@WAlqIcmInt,2) = 17.00 Then IsNull((Select TOP 1 Vlr_PrcFab17 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip 
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     When Round(@WAlqIcmInt,2) = 17.50 Then IsNull((Select TOP 1 Vlr_PrcFab175 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     When Round(@WAlqIcmInt,2) = 18.00 Then IsNull((Select TOP 1 Vlr_PrcFab18 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     When Round(@WAlqIcmInt,2) = 19.00 Then IsNull((Select TOP 1 Vlr_PrcFab19 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     When Round(@WAlqIcmInt,2) = 19.50 Then IsNull((Select TOP 1 Vlr_PrcFab195 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     When Round(@WAlqIcmInt,2) = 20.00 Then IsNull((Select TOP 1 Vlr_PrcFab20 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     When Round(@WAlqIcmInt,2) = 20.50 Then IsNull((Select TOP 1 Vlr_PrcFab205 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     When Round(@WAlqIcmInt,2) = 21.00 Then IsNull((Select TOP 1 Vlr_PrcFab21 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     When Round(@WAlqIcmInt,2) = 22.00 Then IsNull((Select TOP 1 Vlr_PrcFab22 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     Else IsNull((Select TOP 1 Vlr_PrcFab From HSPRC
                                  Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                  And Dat_Alteracao <= @PDatRefPrdCip
                                  Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                   End                       
                           
    if @WPrcAux > 0
      Set @PPrcFab = @WPrcAux
    else           
      Set @PPrcFab = @pr_PrcFab
  end
      
if @PPrcMax = 0
  begin
    Set @WPrcAux = Case
                     When Round(@WAlqIcmInt,2) = 12.00 Then IsNull((Select TOP 1 Vlr_PrcMaxCon12 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     When Round(@WAlqIcmInt,2) = 17.00 Then IsNull((Select TOP 1 Vlr_PrcMaxCon17 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     When Round(@WAlqIcmInt,2) = 17.50 Then IsNull((Select TOP 1 Vlr_PrcMaxCon175 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     When Round(@WAlqIcmInt,2) = 18.00 Then IsNull((Select TOP 1 Vlr_PrcMaxCon18 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     When Round(@WAlqIcmInt,2) = 19.00 Then IsNull((Select TOP 1 Vlr_PrcMaxCon19 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     When Round(@WAlqIcmInt,2) = 19.50 Then IsNull((Select TOP 1 Vlr_PrcMaxCon195 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     When Round(@WAlqIcmInt,2) = 20.00 Then IsNull((Select TOP 1 Vlr_PrcMaxCon20 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     When Round(@WAlqIcmInt,2) = 20.50 Then IsNull((Select TOP 1 Vlr_PrcMaxCon205 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     When Round(@WAlqIcmInt,2) = 21.00 Then IsNull((Select TOP 1 Vlr_PrcMaxCon21 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     When Round(@WAlqIcmInt,2) = 22.00 Then IsNull((Select TOP 1 Vlr_PrcMaxCon22 From HSPRC
                                                                    Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                                                    And Dat_Alteracao <= @PDatRefPrdCip
                                                                    Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                     Else IsNull((Select TOP 1 Vlr_PrcMaxCon
                                  From HSPRC
                                  Where Cod_Estabe = @PCodEstabe and Cod_Produto = @PCodPrd
                                  And Dat_Alteracao <= @PDatRefPrdCip
                                  Order by Dat_Alteracao desc, Seq_Alteracao desc),0)
                   End
                   
    if @WPrcAux > 0
      Set @PPrcMax = @WPrcAux
    else           
      Set @PPrcMax = @pr_PrcMax
  end

-- PMPF - Preco Medio Ponderado ao Consumidor Final
if @PPrcPonFin = 0
  Set @PPrcPonFin = (Select dbo.FN_PrcMedPonFin (@em_DesEstado,@PCodPrd,@PDatEmi))

Set @PVlrBasCalSubTriEntMed = @pr_VlrBasCalSubTriEntMed  -- 08/01/2019

-- verifica se utiliza classificação tributária extra (uma unica vez)
--if (@PFlgCalIcmSbt = 1) and
if ( ((@PTipPrcBasDebSbt <> 'X') and (@PTipPrcBasDebSbt <> 'O')) or (@ct_FlgSujAntIcm = 1) ) and (@PFlgSbtEmbPrc = 0) and  -- produto suj.subst.trib. ou antecip.
   (((@PTipPrcBasDebSbt = 'D') and (@PPrcPonFin = 0)) or
    ((@PTipPrcBasDebSbt = 'M') and (@PPrcMax = 0))) and
   (@WClaTriExt <> '') and
   (@PClaTri <> @WClaTriExt) and
   (@WQtdLoop = 1)
  begin
    Set @WQtdLoop = @WQtdLoop + 1
    Set @PClaTri = @WClaTriExt
    GOTO LOOP_INICIO
  end

-- valor bruto/total do item
Set @it_Vlr_BruIte = Round((@PPrcUniIte * (@PQtdPed+@PQtdBon)),2)
Set @it_Vlr_TotIte = Round(@PQtdPed * @PPrcUniIte * (1-@PPerDscIte/100),2)

-- calcula despesa tributaria 
  if @WPerResExt > 0
    begin
      Set @WVlrBasResExt = @it_Vlr_TotIte
      Set @PVlrDsp = Round(@WVlrBasResExt * @WPerResExt/100,2)
    end

-- valor liquido do item
Set @WVlrIte = @it_Vlr_TotIte - @PVlrDscRat


-----------  DESONERAÇÃO ICMS  -----------------------------------------------------------------------------
-- desoneração somente sobre valor item (sem frete / despesas)
-- ou existe redução, ou desoneração ou suframa
Set @WFlgIcmIsento = 0
Set @WPerIcmDesRedBasCal = 0 -- desoneração de icms por redução de base de cálculo

if @PFlgCalIcmPro = 1
  begin
    if @WAlqIcmExt = @WPerIcmDesone
      Set @WFlgIcmIsento = 1
    
    -- desoneração por redução de base de cálculo
    if @PPerRedBasCalIcmCre > 0
      Set @WPerIcmDesRedBasCal = Round(@WAlqIcmExt*@PPerRedBasCalIcmCre/100,4)
-- desoneração não é obrigatória:
--    if @WPerIcmDesone = 0
--      Set @WPerIcmDesone = @WPerIcmDesRedBasCal
    
    if @WPerIcmDesone > 0
      begin
        Set @PMtvIcmDesone = @WCodMtvDesone
        Set @PVlrIcmDesone = Round(Round(@WVlrIte,2)*@WPerIcmDesone/100,@WQtdDecRndTrb)
    
    	-- se for desoneracao por redução de base de calculo não abate valor na NF -- 
        if ((@WFlgDscDesIcm = 1) or @PFlgDscIcmDesone = 1) and 
    	   (@PPerRedBasCalIcmCre = 0)  
          Set @PVlrDst = @PVlrIcmDesone
      end
  end  -- if @PFlgCalIcmPro = 1
----------- FIM DESONERAÇÃO ICMS  -----------------------------------------------------------------------------

Set @WLiq = Round(@WVlrIte,2) - @PVlrDst

-- valor liquido do item sem reducao da base de calculo p/ credito Icms
Set @WLiq = Round(@WLiq + @PVlrDspTot + @PVlrDsp,2)

-- registra icms proprio, icms tributavel da operacao se DEB/CRE ou SUB.TRIB.
Set @WCre = 0
Set @PAlqIcm = @WAlqIcmExt

Set @WCreFcp = 0
Set @PAlqIcmFcp = @WAlqIcmExtFcp  

/*
if @PAlqIcm > 0
  Set @PBasTri = @WLiq   -- valor base p/ tributos
else  
  Set @PBasTri = Round(@it_Vlr_TotIte - @PVlrDscRat,2)  -- valor base sem despesas
*/

Set @PBasTri = @WLiq

Set @PBasIcmPro = Round(@PBasTri*(1-@PPerRedBasCalIcmCre/100),2)
Set @PIcmPro = Round(@PBasIcmPro * @PAlqIcm/100, @WQtdDecRndTrb)
if @PIcmPro = 0
  Set @PBasIcmPro = 0

Set @WIcmProFcp = Round(@PBasIcmPro * @PAlqIcmFcp/100, @WQtdDecRndTrb)
Set @PVlrIcmDiferi = Round(@PIcmPro * @PPerIcmDiferi/100, @WQtdDecRndTrb)

-- calcula valor de custo substituto do credito de icms
if (@WPerDspSubCusCreIcm > 0) and (@PAlqIcm > 0)
  Set @PVlrDspSubCusCreIcm = @PBasTri * @WPerDspSubCusCreIcm/100

-- credito com reducao da base de calculo p/ credito Icms
--if Charindex(@PCodSt,';00;10;20;30;60;70;90;51;') > 0 
if (@PFlgCalIcmPro = 1) or (@PFlgCalIcmSbt = 1)
  begin
    Set @WCre = @PIcmPro
    Set @WCreFcp = @WIcmProFcp
    if @WCre > 0
      Set @PCodModBasCalIcm = '3'
  end

-- calcula icms tributavel (debito/credito)  aqui novo
if (@PFlgCalIcmPro = 1) and (@PTipPrcBasDebSbt = 'X')   -- nao eh subst.tributaria
  begin
    Set @PBasIcm = @PBasIcmPro
    if @WPerIcmDesRedBasCal > 0
      Set @PVlrIcm = @PIcmPro - @PVlrIcmDiferi  -- @PIcmPro já está com redução de B.C.
    else
      Set @PVlrIcm = @PIcmPro - @PVlrIcmDesone - @PVlrIcmDiferi
    Set @PVlrIcmFcp = @WIcmProFcp
    if @WFlgIcmIsento = 1
      begin
        Set @PBasIcm = 0
        Set @PVlrIcm = 0
        Set @PVlrIcmFcp = 0
      end

    Set @PFlgUsaCrePresum = @WFlgUsaCrePresum
    Set @PAlqCrePresum = @WAlqCrePresum
  end

-- Calcula Base de Cálculo do IPI (valor bruto)
Set @PCstIpi = ''
if @PVlrIpi > 0
  begin
    Set @PCstIpi = '49'   -- outras entradas
    Set @PBasIpi = @it_Vlr_TotIte
  end

-- ver se eh ST sem retencao
if @PTipPrcBasDebSbt = 'O' 
  begin
    Set @PVlrPrdSub = 0
    Set @PAlqIcmDeb = 0
    Set @PAlqAgrDeb = 0
    Set @PPerRedBasCalDeb = 0
    Set @PBasSubFnt = 0
    Set @PVlrSubFnt = 0
    Set @PBasSbtRes = 0
    Set @PVlrSbtRes = 0
    Set @PBasSubRec = 0
    Set @PVlrSubRec = 0
    Set @PVlrPrdAnt = 0
    Set @PBasAnt    = 0
    Set @PVlrAnt    = 0
--    Set @PBasIcmPro = 0
--    Set @PIcmPro    = 0
--    Set @WIcmProFcp = 0
    Set @PBasIcm    = 0
    Set @PVlrIcm    = 0
    Set @PVlrIcmFcp = 0
    Set @PVlrIse    = 0
    Set @PVlrOut    = @WLiq
    Set @PCodModBasCalIcm = ''
    Set @PCodModBasCalIcmSbt = ''
    Set @PFlgUsaCrePresum = @WFlgUsaCrePresum
    Set @PAlqCrePresum = @WAlqCrePresum
  end

-- Calcula Substituicao Tributaria ou Antecipacao de Icms
Set @WVlrPrdSbt = 0
Set @WVlrImpSbt = 0
Set @WVlrPrdSbtLim = 0   -- limitador p/ pr. transacao ou p.fábrica

if (@PFlgCalIcmSbt = 1) and
   ( ((@PTipPrcBasDebSbt <> 'X') and (@PTipPrcBasDebSbt <> 'O')) or
     (@ct_FlgSujAntIcm = 1) )  and  
   (@PFlgSbtEmbPrc = 0)  -- produto suj.subst.trib. ou antecip.
  begin
    -- credito presumido p/ uso no calculo de custo
    Set @PFlgUsaCrePresum = 0
    Set @PAlqCrePresum = 0

    if @WCtrBasCalDeb = 'B'    -- pelo vlr. bruto
      begin
        if @PTipPrcBasDebSbt = 'D'           -- utiliza PMPF do cadastro
          Set @WVlrPrdSbt = @PPrcPonFin * (@PQtdPed + @PQtdBon)
        else
        if @PTipPrcBasDebSbt = 'M'      -- utiliza P.M.C. do cadastro
          Set @WVlrPrdSbt = @PPrcMax * (@PQtdPed+@PQtdBon)
        else
        if @PTipPrcBasDebSbt = 'F'       -- utiliza preco fabrica do cadastro
          Set @WVlrPrdSbt = (@PPrcFab * (@PQtdPed+@PQtdBon)) + @PVlrIpi
        else
        if @PTipPrcBasDebSbt = 'P'      -- utiliza Preço Referencia Farmacia Popular do cadastro
          Set @WVlrPrdSbt = @PPrcRefFpb * (@PQtdPed+@PQtdBon)
        else
        if @PTipPrcBasDebSbt = 'V'       -- utiliza preco venda do cadastro
          Set @WVlrPrdSbt = (@PPrcVen * (@PQtdPed+@PQtdBon)) + @PVlrIpi
        else
          Set @WVlrPrdSbt = @it_Vlr_BruIte + @PVlrIpi + @PVlrDspSbt  + @PVlrDspTot + @PVlrDsp   -- transacao
      end
    else
      begin
        Set @WVlrPrdSbt = @PBasTri + @PVlrIpi + @PVlrDspSbt
      end

    Set @WVlrPrdSbt = @WVlrPrdSbt * (1-@PPerRedBasCalDeb/100)
    Set @WVlrBasSbt = @WVlrPrdSbt * @WFatSubTriDeb

    -- calcula valor minimo p/ B.Cálculo de ST
    Set @WVlrMinBasCalSbt = 0

	-- 08/01/2019 : compatibilizar com calculo da saida
    -- média da B.C. de Entrada + Agreg.
    if @WTipPrcLimMinBasCalIcmSbt = 'E'
      Set @WVlrMinBasCalSbt = Round(@PVlrBasCalSubTriEntMed * (1 + @WAlqAgrLimMinBasCalIcmSbt/100),2)

    if @WTipPrcLimMinBasCalIcmSbt = 'F' 
      Set @WVlrMinBasCalSbt = Round((@PPrcFab * (@PQtdPed+@PQtdBon)) * @WPerLimMinBasCalIcmSbt/100,4)

    if @WVlrBasSbt < @WVlrMinBasCalSbt
      Set @WVlrBasSbt = @WVlrMinBasCalSbt    

    Set @WVlrBasSbt = Round(@WVlrBasSbt,2)

    if @WTipCreSbt = 'F'    -- Valor da substituicao fixo
      begin
        Set @PFlgUsaCreIcmSbt = 0
        Set @WVlrImpSbt = @WVlrBasSbt * @WAlqDebSbt / 100
        Set @PAlqIcmDeb = @WAlqDebSbt
        Set @PVlrPrdSub = @WVlrPrdSbt

		Set @PAlqIcmSbtFcp = @WAlqIcmIntFcp
        Set @PVlrSubFcp = @WVlrBasSbt * @PAlqIcmSbtFcp / 100

        if @WFlgImpSbtFnt = 1 
          begin
            if @PAlqAgrDeb > 0
              Set @PCodModBasCalIcmSbt = '4'  -- Margem Valor Agregado (%)
            else
              Set @PCodModBasCalIcmSbt = '0'  -- preco tabela ou maximo sugerido
          end
        else
          Set @PCodModBasCalIcmSbt = ''
      end
    else
      begin
        -- substituicao com agregacao
        -- debito com red. base de calculo icms
        Set @PFlgUsaCreIcmSbt = 1
        Set @PAlqIcmDeb = @WAlqIcmInt
        Set @PVlrDebIcm = @WVlrBasSbt * @PAlqIcmDeb / 100

		Set @PAlqIcmSbtFcp = @WAlqIcmIntFcp
        Set @WDebSbtFcp = @WVlrBasSbt * @PAlqIcmSbtFcp / 100   

        Set @WVlrBasLimCreSbt = @WVlrBasSbt

        if @WCtrBasCalCre = 'B'       -- credito pelo vlr.bruto
          begin
            if @PTipPrcBasCreSbt = 'F'    -- utiliza preco fabrica do cadastro
              Set @WCreSbt = @PPrcFab * (@PQtdPed+@PQtdBon)
            else
            if @PTipPrcBasCreSbt = 'V'    -- utiliza preco venda do cadastro
              Set @WCreSbt = @PPrcVen * (@PQtdPed+@PQtdBon)
            else
              Set @WCreSbt = @it_Vlr_BruIte  -- transacao
            -- credito com red.base de calculo
            Set @WCreSbt = @WCreSbt * (1-@PPerRedBasCalIcmCre/100) * @WAlqIcmExt / 100
            Set @WCreSbtFcp = @WCreSbt * (1-@PPerRedBasCalIcmCre/100) * @WAlqIcmExtFcp / 100
          end
        else
          begin
            Set @WCreSbt = @WCre
            Set @WCreSbtFcp = @WCreFcp
          end

        -- valor limite de credito na substituicao tributaria
        Set @PVlrLimCreIcm = 0
        if @PPerLimBasCalCreSbt > 0
          Set @PVlrLimCreIcm = @WVlrBasLimCreSbt*@PPerLimBasCalCreSbt*@WAlqIcmExt/10000

        if (@PVlrLimCreIcm > 0) and (@WCreSbt > @PVlrLimCreIcm) 
          Set @WCreSbt = @PVlrLimCreIcm

        -- calcula icm subst.
        Set @WVlrImpSbt = @PVlrDebIcm - @WCreSbt
		Set @PVlrSubFcp = @WDebSbtFcp - @WCreSbtFcp

		if @PAlqAgrDeb > 0
          Set @PCodModBasCalIcmSbt = '4'  -- Margem Valor Agregado (%)
        else
          Set @PCodModBasCalIcmSbt = '0'  
      end

    -- verifica limitador de ST
    Set @WVlrMinSbt = 0
    if @WPerLimMinIcmSbt > 0 
      begin
        if @WTipPrcLimMinIcmSbt = 'L'
          Set @WVlrPrdSbtLim = @PBasTri + @PVlrIpi + @PVlrDspSbt
        else
        if @WTipPrcLimMinIcmSbt = 'F'
          Set @WVlrPrdSbtLim = (@PPrcFab * (@PQtdPed+@PQtdBon)) + @PVlrIpi
        Set @WVlrMinSbt = @WVlrPrdSbtLim*@WPerLimMinIcmSbt/100
      end

    if (@WVlrImpSbt < @WVlrMinSbt) and (Round(@WVlrMinSbt,2) > 0) 
      begin
        Set @WVlrPrdSbt = @WVlrPrdSbtLim
        Set @WVlrBasSbt = @WVlrPrdSbtLim
        Set @WVlrImpSbt = @WVlrMinSbt
        Set @PAlqIcmDeb = @WPerLimMinIcmSbt

		Set @PAlqIcmSbtFcp = @WAlqIcmIntFcp
        Set @PVlrSubFcp = @WVlrBasSbt * @PAlqIcmSbtFcp / 100

        if @WFlgImpSbtFnt = 1
          begin
            if @PAlqAgrDeb > 0
              Set @PCodModBasCalIcmSbt = '4'  -- Margem Valor Agregado (%)
            else
              Set @PCodModBasCalIcmSbt = '0'  -- preco tabela ou maximo sugerido
          end
       else
         Set @PCodModBasCalIcmSbt = ''
      end

    -- verifica S.T. opcional
    Set @WVlrImpSbtOpc = 0
    if @WPerRedBasCalDebOpc > 0
      begin
        Set @WVlrDebIcmOpc = 0
        Set @WVlrPrdSbtOpc = @PPrcMax * (@PQtdPed+@PQtdBon)
        Set @WVlrPrdSbtOpc = @WVlrPrdSbtOpc * (1-@WPerRedBasCalDebOpc/100)

        -- calcula S.T. opcional
        Set @WVlrDebIcmOpc = @WVlrPrdSbtOpc * @WAlqIcmInt/100
        Set @WVlrImpSbtOpc = @WVlrDebIcmOpc - @WCre

        if (@WVlrImpSbtOpc < @WVlrImpSbt) and (Round(@WVlrImpSbtOpc,2) > 0)
          begin
            Set @WVlrPrdSbt = @WVlrPrdSbtOpc
            Set @WVlrBasSbt = @WVlrPrdSbtOpc
            Set @WVlrImpSbt = @WVlrImpSbtOpc

            Set @PAlqIcmSbtFcp = @WAlqIcmIntFcp
            Set @PVlrSubFcp = @WVlrBasSbt * @PAlqIcmSbtFcp / 100   

            Set @PTipPrcBasDebSbt = 'M'   -- P.M.C.
            Set @PFlgUsaCreIcmSbt = 1
            Set @PAlqAgrDeb = 0
            Set @PPerRedBasCalDeb = @WPerRedBasCalDebOpc
            Set @PVlrDebIcm = @WVlrDebIcmOpc
            Set @PAlqIcmDeb = @WAlqIcmInt

            if @WFlgImpSbtFnt = 1
              begin
                if @PAlqAgrDeb > 0
                  Set @PCodModBasCalIcmSbt = '4'  -- Margem Valor Agregado (%)
                else
                  Set @PCodModBasCalIcmSbt = '0'  -- preco tabela ou maximo sugerido
              end
            else
              Set @PCodModBasCalIcmSbt = ''
          end
      end
    
    -- verifica valor ST
    if @WVlrImpSbt <= 0
      begin
        Set @WVlrImpSbt = 0
        Set @PVlrSubFcp = 0
        if @WVlrBasSbt = 0
          begin
            Set @PCodModBasCalIcmSbt = ''
            Set @WVlrPrdSbt = 0
            Set @PAlqIcmDeb = 0
            Set @PAlqAgrDeb = 0
            Set @PPerRedBasCalIcmDeb = 0
            Set @PAlqIcmSbtFcp = 0
          end
      end

    if @ct_FlgSujAntIcm = 0
      begin
        -- subst. tributaria
        Set @PVlrPrdSub = @WVlrPrdSbt
        if @WFlgImpSbtFnt = 1
          begin
            Set @PBasSubFnt = @WVlrBasSbt
            Set @PVlrSubFnt = @WVlrImpSbt
          end
        else
          begin
            Set @PBasSubRec = @WVlrBasSbt
            Set @PVlrSubRec = @WVlrImpSbt

            Set @PAlqIcmSbtFcpRec = @PAlqIcmSbtFcp
            Set @PVlrSubFcpRec = @PVlrSubFcp
            Set @PAlqIcmSbtFcp = 0
            Set @PVlrSubFcp = 0
          end
      end
    else
      begin
        -- antecip. tributaria
        Set @PVlrPrdAnt = @WVlrPrdSbt
        Set @PBasAnt    = @WVlrBasSbt
        Set @PVlrAnt    = @WVlrImpSbt

        Set @PAlqIcmSbtFcpAnt = @PAlqIcmSbtFcp
        Set @PVlrSubFcpAnt = @PVlrSubFcp
        Set @PAlqIcmSbtFcp = 0
        Set @PVlrSubFcp = 0

        -- Calcula Base Calc.ICMS deb/cre
        if @WAlqIcmExt > 0
          begin
            if @PFlgCalIcmPro = 1
               begin
                 Set @PBasIcm = @PBasIcmPro
                 if @WPerIcmDesRedBasCal > 0
                   Set @PVlrIcm = @PIcmPro - @PVlrIcmDiferi  -- @PIcmPro já está com redução de B.C.
                 else
                   Set @PVlrIcm = @PIcmPro - @PVlrIcmDesone - @PVlrIcmDiferi
                 Set @PVlrIcmFcp = @WIcmProFcp
               end
            if @WFlgIcmIsento = 1
              begin
                Set @PBasIcm = 0
                Set @PVlrIcm = 0
                Set @PVlrIcmFcp = 0
              end
          end
      end
  end  -- if (@PFlgCalIcmSbt = 1) and ... produto suj.subst.trib. ou antecip.

/*
else
  -- Calcula Base Calc.ICMS deb/cre
  begin
    Set @PFlgUsaCrePresum = @WFlgUsaCrePresum
    Set @PAlqCrePresum = @WAlqCrePresum
    if @WAlqIcmExt > 0 
      begin
        Set @PBasIcm = @PBasIcmPro
        if @WPerIcmDesRedBasCal > 0
          Set @PVlrIcm = @PIcmPro - @PVlrIcmDiferi  -- @PIcmPro já está com redução de B.C.
        else
          Set @PVlrIcm = @PIcmPro - @PVlrIcmDesone - @PVlrIcmDiferi
        Set @PVlrIcmFcp = @WIcmProFcp
        if @WFlgIcmIsento = 1
          begin
            Set @PBasIcm = 0
            Set @PVlrIcm = 0
            Set @PVlrIcmFcp = 0
          end
      end
    else
      -- Calcula Valor Isento (AQUI não funciona mais... alíquota nunca pode ser zero
      Set @PVlrIse = Round(@PBasTri,2)
  end
*/


-- nao houve tributacao qualquer
if (@PFlgCalIcmPro = 0) and (@PFlgCalIcmSbt = 0)
  begin
    Set @PVlrOut = @PBasIcmPro
    if Charindex(@PCodSt,';51;') = 0  -- if Charindex(@PCodSt,';51;90;') = 0
--      Set @PCodSt = '41'   -- para não contribuinte
      Set @PCodSt = '90'     -- para contribuinte 
  end

-- CST sujeitas a ST 10;30;70
if (@PFlgCalIcmSbt = 1) and (@WVlrImpSbt = 0) and (Charindex(@PCodSt,';10;30;60;70;') > 0) 
  if Charindex(@PCodSt,';10;70;') > 0 
    begin
      Set @PBasIcm = @PBasIcmPro
      if @WPerIcmDesRedBasCal > 0
        Set @PVlrIcm = @PIcmPro - @PVlrIcmDiferi  -- @PIcmPro já está com redução de B.C.
      else
        Set @PVlrIcm = @PIcmPro - @PVlrIcmDesone - @PVlrIcmDiferi
      Set @PVlrIcmFcp = @WIcmProFcp
      if @WFlgIcmIsento = 1
        begin
          Set @PBasIcm = 0
          Set @PVlrIcm = 0
          Set @PVlrIcmFcp = 0
        end
      if @WVlrBasSbt = 0
        if @PCodSt = '70'
          Set @PCodSt = '20' 
        else
          Set @PCodSt = '00' 
    end
  else
    begin
      Set @PVlrOut = @PBasIcmPro
      if @WVlrBasSbt > 0 
        if @PCodSt = '60'
          Set @WVlrBasSbt = 0
      if @WVlrBasSbt = 0
        if @PCodSt = '30'
          if @WFlgIcmIsento = 1
            Set @PCodSt = '40'
          else			 
            Set @PCodSt = '41' 
    end

-- exige tributacao icm
if (@PFlgCalIcmPro = 1) and
   (Charindex(@PCodSt,';00;10;20;51;70;90;') > 0)
  begin
    Set @PBasIcm = @PBasIcmPro
    if @WPerIcmDesRedBasCal > 0
      Set @PVlrIcm = @PIcmPro - @PVlrIcmDiferi  -- @PIcmPro já está com redução de B.C.
    else
      Set @PVlrIcm = @PIcmPro - @PVlrIcmDesone - @PVlrIcmDiferi
    Set @PVlrIcmFcp = @WIcmProFcp
    if @WFlgIcmIsento = 1
      begin
        Set @PBasIcm = 0
        Set @PVlrIcm = 0
        Set @PVlrIcmFcp = 0
      end
  end

-- ajusta cst de isento
if (@PVlrIcm = 0) and
   (Charindex(@PCodSt,';30;40;41;50;60;') = 0)   
  begin
    if Charindex(@PCodSt,';00;20;51;') > 0
      if @WFlgIcmIsento = 1
        Set @PCodSt = '40'
      else			 
        Set @PCodSt = '41' 

    if Charindex(@PCodSt,';10;;70;') > 0
      Set @PCodSt = '30'
    else
    if ((@PVlrSubFnt+@PVlrSbtRes) > 0)
      Set @PCodSt = '30'
    else
      if @WFlgIcmIsento = 1
        Set @PCodSt = '40'
      else			 
        Set @PCodSt = '41' 
  end

-- nao exige tributacao icm
if Charindex(@PCodSt,';30;40;41;50;60;') > 0 
  begin
    Set @PBasIcm = 0
    Set @PVlrIcm = 0
    Set @PVlrIcmFcp = 0
  end

if (@PCodSt = '90') and (@PTipPrcBasDebSbt = 'O')
  begin
    Set @PBasIcm = 0
    Set @PVlrIcm = 0
    Set @PVlrIcmFcp = 0
  end

if (@PVlrIse = 0) and (@PVlrOut = 0) and 
   (@PVlrSubFnt = 0) and (@PVlrSbtRes = 0) and (@PVlrSubRec = 0) and (@PVlrAnt = 0) and
   (@PVlrIcm = 0) 
  if (@PFlgCalIcmPro = 1) or (@PFlgCalIcmSbt = 1)
    Set @PVlrIse = @PBasTri
  else
    Set @PVlrOut = @PBasTri

-- AQUI não funciona mais... alíquota interna nunca pode ser zero
if @PVlrIse > 0 
  if @PAlqIcm = 0
    begin
      Set @PBasIcmPro = 0
      Set @PIcmPro = 0
      Set @WIcmProFcp = 0
      Set @PBasIcm = 0
      Set @PVlrIcm = 0
      Set @PVlrIcmFcp = 0
      Set @PVlrOut = 0
      if @WFlgIcmIsento = 1
        Set @PCodSt = '40'
      else			 
        Set @PCodSt = '41' 
    end

-- ICM presumido
if (@PVlrIcm > 0) and (@PFlgUsaCrePresum = 0)
  begin
    Set @PFlgUsaCrePresum = @WFlgUsaCrePresum
    Set @PAlqCrePresum = @WAlqCrePresum
  end

-- ajusta ressarcimento de ST
if @PCodSt = '60' 
  begin
    Set @PBasSbtRes = @PBasSubFnt
    Set @PVlrSbtRes = @PVlrSubFnt
    Set @PBasSubFnt = 0
    Set @PVlrSubFnt = 0

    Set @PAlqIcmSbtFcpRet = @PAlqIcmSbtFcp 
    Set @PVlrSubFcpRet = @PVlrSubFcp
    Set @PAlqIcmSbtFcp = 0
    Set @PVlrSubFcp = 0
  end

-- calcula outros valores de icms
Set @PVlrOut = Round((@WLiq - @PVlrIse - @PBasIcm),2)
if @PVlrOut < 0
  Set @PVlrOut = 0
if @PVlrOut > @WLiq
  Set @PVlrOut = Round(@WLiq,2)

-- ajusta Cod.Modalidade base de calculo icm sbt
if @PVlrSubFnt > 0
  if @PAlqAgrDeb > 0
    Set @PCodModBasCalIcmSbt = '4'  -- Margem Valor Agregado (%)
  else
     Set @PCodModBasCalIcmSbt = '0'  -- preco tabela ou maximo sugerido
else
  Set @PCodModBasCalIcmSbt = ''

if Charindex(@PCodSt,';30;40;41;50;60;') > 0
  Set @PCodModBasCalIcm = ''
if Charindex(@PCodSt,';00;20;40;41;50;51;60;') > 0
  Set @PCodModBasCalIcmSbt = ''

-- aqui TESTE em 24/03/2022: zerar ICMS proprio...
if Round(@PVlrIse,2) > 0
  begin
    Set @PAlqIcm = 0  -- ????? pode zerar ?????
    Set @PBasIcmPro = 0
    Set @PIcmPro = 0 
    Set @PBasIcm = 0
    Set @PVlrIcm = 0 
    Set @PVlrIcmFcp = 0
    Set @PVlrOut = 0
  end


-- adiciona valor ipi ao ICMS tributável para notas de devolução de uso e consumo
-- ?????? está adicionando ipi somente no final... não entra nocãuculo do valor do tributo?????
--if (@PBasIcm > 0) and (@PTipNot = 'D') and (@PFlgIncIpiBasIcmTrib = 1) 
--  Set @PBasIcm = @PBasIcm + @PVlrIpi


-- pis/cofins
Set @WVlrBasPisCof = Round(@WLiq,2)

--ressarcimento é despesa
Set @WVlrBasPisCof = Round(@WLiq+@PVlrSbtRes,2)  

-- ipi
if @pm_FlgIncIpiCalPis = 1
  Set @WVlrBasPisCof = @WVlrBasPisCof + @PVlrIpi

-- exclui icm destacado na devolução de venda
if @pm_FlgExcIcmCalPis = 1
  begin
    if @PTipNot = 'D'  -- devolução de venda
      Set @WVlrBasPisCof = @WVlrBasPisCof - @PVlrIcm
    else
      Set @WVlrBasPisCof = @WVlrBasPisCof - @PIcmPro
  end

Exec PR_CalculaPisCofins @PCodEstabe, @PFlgCalPisCof, 'E', @em_CodTipLuc, @PDatMov, @PCfoCab, 0, @PCodNcm, @PTipLisPis, @WVlrBasPisCof, 
                         @PCstPis output, @PVlrBasPis output, @PAlqPis output, @PVlrPis output,
                         @PCstCof output, @PVlrBasCof output, @PAlqCof output, @PVlrCof output, @PObsNf output

-- Suframa
if (@PAlqIpi > 0) and (@PVlrBasSuf > 0)
  Set @PVlrSuf = @it_Vlr_TotIte/@PVlrBasSuf*@PVlrTaxSuf

Commit Transaction
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- tem que saber se é contribuinte ou não???
-- calculo Irf: Base de calculo, Aliquota, Valor do Tributo
-- CFOp do item....

-- PR_CalcTrbParItemSai.sql
-- PR_CalcTrbSaiInventario.sql
-- PR_CalcTributNFSIT.sql
-- PR_CalcTributPDVIT.sql
-- PR_CalculaSubTriSai.sql
CREATE PROCEDURE [dbo].[PR_CalcTributItemSaida]
@PCodEstabe int,
@PDatEmi smalldatetime,
@PCodRegTri int,
@PPerDscCab numeric(7,4),              -- desconto comercial (cabecalho)
@PTipNot char(1),
@PCodCfo smallint,                      -- para calculo Pis/Cofins          
@PCodRamAtv int,                        -- para calculo Pis/Cofins
@PCodUfDst varchar(2), 

@PFlgValDscSuframa bit,                 -- calcula desconto Suframa (com Inscicao Suframa, produto com incentivo fiscal)      
@PFlgCalIcmSbt bit,       
@PFlgCalIcmPro bit,       
@PFlgCalRepIcm bit,       
@PFlgCalPisCof bit,       
@PFlgCalIpi bit,
@PFlgSbtEmbPrc bit,       

@PCodPrd int,
@PCodLot varchar(20),                   -- opcional (usado para calculo ST recolhido antecipadamente)
@PQtdPed int,
@PQtdBon int,
@PPrcUniIte numeric(18,8) output,       -- preço atual (pode estar com acrescimo de icm)
@PPerDscIte numeric(9,6),   
@PFlgPrcUniDsc bit,                     -- indica se embute desconto no preço initário

@PVlrCabDscBonRat numeric(18,4),        -- desconto bonificacao
@PVlrCabDscRat numeric(18,4),           -- desc.rateado do item
@PVlrDspRat numeric(18,8), 
 
@PArqPrcVen numeric(18,4),              -- Pr.Venda
@PArqPrcUltEnt numeric(18,4),           -- Pr.Liq.Ultima Entrada
@PArqPrcFab numeric(18,4),              -- Pr.Fabrica em PDVIT os NFSIT
@PArqPrcMax numeric(18,4),              -- Pr.Max.Consumidor
@PArqPrcRefFpb numeric(18,4),           -- Pr.Ref.Farmacia Popular
@PArqPrcPonFin numeric(18,4),           -- Pr.Médio Ponderado a Consumidor Final

@PArqCstIpi varchar(2),
@PArqVlrBasIpi numeric(18,4),
@PArqAlqIpi numeric(7,4),
@PArqVlrIpi numeric(18,4),
@PArqCodEnqIpi varchar(3),

@PFlgPrcUniAcrIcm numeric(18,8) output,     -- indica se há acréscimo no preço 
@PPrcUniSemAcrIcm numeric(18,8) output,     -- pr.unitario sem acrescimo ICMS 
@PPrcUniComAcrIcm numeric(18,8) output,     -- pr.unitario com acrescimo ICMS 

@PPrcVen numeric(18,4) output,          -- Pr.Venda
@PPrcUltEnt numeric(18,4) output,       -- Pr.Liq.Ultima Entrada
@PPrcFab numeric(18,4) output,          -- Pr.Fabrica
@PPrcMax numeric(18,4) output,          -- Pr.Max.Consumidor
@PPrcRefFpb numeric(18,4) output,       -- Pr.Ref.Farmacia Popular

@PVlrDscRat numeric(18,4) output,       -- novo desc.rateado do item
@PVlrBasTri numeric(18,4) output,       -- valor base tributação
@PCodSt varchar(2) output,
@PCodCsosn varchar(3) output,
@PClaTri varchar(4) output,
@PCodModBasCalIcm char(1) output,
@PAlqIcm numeric(7,4) output,
@PPerRedBasCalIcm numeric(7,4) output,
@PBasIcmPro numeric(18,4) output,       -- Base ICMS proprio
@PIcmPro numeric(18,4) output,          -- ICMS proprio
@PPerRep numeric(7,4) output,           -- % repasse
@PBasRep numeric(18,4) output,          -- Base Repasse
@PVlrRep numeric(18,4) output,          -- Vlr Repasse
@PVlrPrdSub numeric(18,4) output,
@PVlrBasCalSubTriEntMed numeric(18,4) output,
@PCodModBasCalIcmSbt char(1) output,
@PAlqIcmSbt numeric(7,4) output,
@PAlqAgrSbt numeric(7,4) output,
@PPerRedBasCalIcmSbt numeric(7,4) output,
@PBasSbt numeric(18,4) output,
@PVlrSbt numeric(18,4) output,
@PBasRes numeric(18,4) output,
@PVlrRes numeric(18,4) output,

@PBasDst numeric(18,4) output,          -- base desconto de tributacao   ?????  futuramente excluir PDVIT PDVCB NFSIT NFSCB
@PPerDst numeric(7,4) output,           -- % desconto de tributacao      ?????? futuramente excluir RTXCT PDVIT NFSIT
@PVlrDst numeric(18,4) output,          -- desconto de tributacao (reduz diretamente no valor da NF)

@PBasIcm numeric(18,4) output,          -- base icms tributavel 
@PVlrIcm numeric(18,4) output,          -- icms tributavel (Total: FCP embutido)
@PVlrIse numeric(18,4) output,
@PVlrOut numeric(18,4) output,

@PCstPis varchar(2) output,
@PVlrBasPis numeric(18,4) output,
@PAlqPis numeric(7,4) output,
@PVlrPis numeric(18,4) output,
@PCstCof varchar(2) output,
@PVlrBasCof numeric(18,4) output,
@PAlqCof numeric(7,4) output,
@PVlrCof numeric(18,4) output,

@PVlrDspTrb numeric(18,4) output,
@PAlqIntIcmUfDes numeric(7,4) output,
@PPerFcpUfDes numeric(7,4) output,
@PPerParIcmUfDes numeric(7,4) output,
@PVlrFcpUfDes numeric(18,4) output,     
@PVlrParIcmUfDes numeric(18,4) output,
@PVlrParIcmUfRem numeric(18,4) output,

@PVlrIcmDesone numeric(18,4) output,      -- icms desonerado
@PMtvIcmDesone varchar(1) output,         -- cod.motivo icms desonerado
--@PVlrIcmSTDesone numeric(18,4) output,    -- icms ST desonerado
--@PMtvIcmSTDesone varchar(1) output,       -- cod.motivo icms ST desonerado
@PFlgIncFis bit output,                   -- incentivo fiscal
@PVlrDscSuframa numeric(18,4) output,     -- desconto suframa

@PFlgUsaDebPresum bit output,
@PAlqDebPresum numeric(7,4) output,
@PObsNf varchar(200) output,

@PAlqIcmFcp numeric(7,4) output,
@PVlrIcmFcp numeric(18,4) output,          -- icms tributavel FCP: embutido em @PVlrIcm
@PAlqIcmSbtFcp numeric(7,4) output,
@PVlrSbtFcp numeric(18,4) output,
@PAlqIcmSbtFcpRet numeric(7,4) output,
@PVlrSbtFcpRet numeric(18,4) output,

@PPerIcmDiferi numeric(7,4) output,
@PVlrIcmDiferi numeric(18,4) output,

@PPrcPonFin numeric(18,4) output,
@PCodOriMer varchar(1) output,
@PCstIpi varchar(2) output,
@PVlrBasIpi numeric(18,4) output,
@PAlqIpi numeric(7,4) output,
@PVlrIpi numeric(18,4) output,
@PCodEnqIpi varchar(3) output,

@PCodPDVLT int,        -- num. do pedido de venda PDVLT/PDVCB
@PVlrSbtRetAnt numeric(18,4) output,
@PVlrBasIrf numeric(18,4) output,
@PAlqIrf numeric(7,4)  output,
@PVlrIrf numeric(18,4)  output


AS

SET NOCOUNT ON 

Begin Transaction

DECLARE @PVlrFcpSbtUfDes numeric(18,4),
        @PBasRecSbt numeric(18,4),
        @PVlrRecSbt numeric(18,4),

        @PVlrLiqIte numeric(18,4),
        @PCodCfoNor smallint,
        @PCodCfoSbt smallint,
        @PCodCfoIte smallint


-- variaveis de trabalho
Declare @WQtdLoop tinyint, 
        @WClaTriExt varchar(4),
        @WQtdDecRndTrb tinyint,
        @WVlrRepBru numeric(18,4),
        @WVlrRepBruTab numeric(18,4),
        @WLiq numeric(18,4),
