  end
else
  begin
    Set @PPrcFab = 0
    Set @PPrcMax = 0
    Set @PPrcRefFpb = 0
    Set @PPrcPonFin = 0
  end


-- coloca campo de PRODU na memoria
Select @PCodOriMer = p.Cod_OriMer,
       @pr_Ctrl_Preco = pr.Ctrl_Preco,
       @pr_Desconto = Isnull(p.Flg_BlqDsc,0),
       @pr_FlgIncFis = pr.Flg_IncFis,   -- produto com incentivo fiscal
       @pr_TipLisPis = pr.Tip_LisPis,
       @pr_CodClaFis = Substring(Ltrim(Rtrim(pr.Cod_ClaFis)),1,8),
       @pr_PrcVen = Isnull(p.Prc_Venda,0),
       @pr_PrcRefFpb = Isnull(pr.Prc_RefFpb,0),
       @pr_PrcUltEnt = Isnull(p.Prc_UltEnt,0),
       @pr_PerDscUltEnt = Isnull(p.Per_DscUltEnt,0),
       @pr_VlrBasCalSubTriEntMed = IsNull(p.Vlr_BasCalSubTriEntMed,0),
       @pr_PrcFab = Case
                      When (Round((@WAlqIcmInt-@WAlqIcmIntFcp),2) = 12.00) and (IsNull(pr.Prc_Fabric12,0)  > 0) Then IsNull(pr.Prc_Fabric12,0)
                      When (Round((@WAlqIcmInt-@WAlqIcmIntFcp),2) = 17.00) and (IsNull(pr.Prc_Fabric17,0)  > 0) Then IsNull(pr.Prc_Fabric17,0)
                      When (Round((@WAlqIcmInt-@WAlqIcmIntFcp),2) = 17.50) and (IsNull(pr.Prc_Fabric175,0) > 0) Then IsNull(pr.Prc_Fabric175,0)
                      When (Round((@WAlqIcmInt-@WAlqIcmIntFcp),2) = 18.00) and (IsNull(pr.Prc_Fabric18,0)  > 0) Then IsNull(pr.Prc_Fabric18,0)
                      When (Round((@WAlqIcmInt-@WAlqIcmIntFcp),2) = 19.00) and (IsNull(pr.Prc_Fabric19,0)  > 0) Then IsNull(pr.Prc_Fabric19,0)
                      When (Round((@WAlqIcmInt-@WAlqIcmIntFcp),2) = 19.50) and (IsNull(pr.Prc_Fabric195,0) > 0) Then IsNull(pr.Prc_Fabric195,0)
                      When (Round((@WAlqIcmInt-@WAlqIcmIntFcp),2) = 20.00) and (IsNull(pr.Prc_Fabric20,0)  > 0) Then IsNull(pr.Prc_Fabric20,0)
                      When (Round((@WAlqIcmInt-@WAlqIcmIntFcp),2) = 20.50) and (IsNull(pr.Prc_Fabric205,0) > 0) Then IsNull(pr.Prc_Fabric205,0)
                      When (Round((@WAlqIcmInt-@WAlqIcmIntFcp),2) = 21.00) and (IsNull(pr.Prc_Fabric21,0)  > 0) Then IsNull(pr.Prc_Fabric21,0)
                      When (Round((@WAlqIcmInt-@WAlqIcmIntFcp),2) = 22.00) and (IsNull(pr.Prc_Fabric22,0)  > 0) Then IsNull(pr.Prc_Fabric22,0)
                      Else Isnull(p.Prc_Fabric,0)
                    End,
       @pr_PrcMax = Case
                      When (Round((@WAlqIcmInt-@WAlqIcmIntFcp),2) = 12.00) and (IsNull(pr.Prc_MaxCon12,0)  > 0) Then IsNull(pr.Prc_MaxCon12,0)
                      When (Round((@WAlqIcmInt-@WAlqIcmIntFcp),2) = 17.00) and (IsNull(pr.Prc_MaxCon17,0)  > 0) Then IsNull(pr.Prc_MaxCon17,0)
                      When (Round((@WAlqIcmInt-@WAlqIcmIntFcp),2) = 17.50) and (IsNull(pr.Prc_MaxCon175,0) > 0) Then IsNull(pr.Prc_MaxCon175,0)
                      When (Round((@WAlqIcmInt-@WAlqIcmIntFcp),2) = 18.00) and (IsNull(pr.Prc_MaxCon18,0)  > 0) Then IsNull(pr.Prc_MaxCon18,0)
                      When (Round((@WAlqIcmInt-@WAlqIcmIntFcp),2) = 19.00) and (IsNull(pr.Prc_MaxCon19,0)  > 0) Then IsNull(pr.Prc_MaxCon19,0)
                      When (Round((@WAlqIcmInt-@WAlqIcmIntFcp),2) = 19.50) and (IsNull(pr.Prc_MaxCon195,0) > 0) Then IsNull(pr.Prc_MaxCon195,0)
                      When (Round((@WAlqIcmInt-@WAlqIcmIntFcp),2) = 20.00) and (IsNull(pr.Prc_MaxCon20,0)  > 0) Then IsNull(pr.Prc_MaxCon20,0)
                      When (Round((@WAlqIcmInt-@WAlqIcmIntFcp),2) = 20.50) and (IsNull(pr.Prc_MaxCon205,0) > 0) Then IsNull(pr.Prc_MaxCon205,0)
                      When (Round((@WAlqIcmInt-@WAlqIcmIntFcp),2) = 21.00) and (IsNull(pr.Prc_MaxCon21,0)  > 0) Then IsNull(pr.Prc_MaxCon21,0)
                      When (Round((@WAlqIcmInt-@WAlqIcmIntFcp),2) = 22.00) and (IsNull(pr.Prc_MaxCon22,0)  > 0) Then IsNull(pr.Prc_MaxCon22,0)
                      Else Isnull(p.Prc_MaxCon,0)
                    End
  From PRXES p 
       Inner Join PRODU pr on p.Cod_Produt = pr.Codigo
Where p.Cod_Estabe = @PCodEstabe 
And p.Cod_Produt = @PCodPrd

Set @PPrcUniComAcrIcm = 0

Set @PPrcVen = ISNULL(@PArqPrcVen,0)
Set @PPrcUltEnt = ISNULL(@PArqPrcUltEnt,0)

if @PPrcVen = 0
  Set @PPrcVen = @pr_PrcVen
if @PPrcUltEnt = 0
  Set @PPrcUltEnt = @pr_PrcUltEnt*(1-@pr_PerDscUltEnt/100)

if @PPrcFab = 0
  Set @PPrcFab = @pr_PrcFab
if @PPrcMax = 0
  Set @PPrcMax = @pr_PrcMax
if @PPrcRefFpb = 0
  Set @PPrcRefFpb = @pr_PrcRefFpb
-- PMPF - Preco Medio Ponderado ao Consumidor Final
if @PPrcPonFin = 0
  Set @PPrcPonFin = (Select dbo.FN_PrcMedPonFin (@PCodUfDst,@PCodPrd,@PDatEmi))

Set @PVlrBasCalSubTriEntMed = @pr_VlrBasCalSubTriEntMed

-- verifica se utiliza classificação tributária extra (uma unica vez)
if (@PFlgCalIcmSbt = 1) and 
   (((@WTipPrcBasDebSbt = 'D') and (@PPrcPonFin = 0)) or
    ((@WTipPrcBasDebSbt = 'M') and (@PPrcMax = 0))) and
   (@WClaTriExt <> '') and
   (@PClaTri <> @WClaTriExt) and
   (@WQtdLoop = 1)
  begin
    Set @WQtdLoop = @WQtdLoop + 1
    Set @PClaTri = @WClaTriExt
    GOTO LOOP_INICIO
  end


--------------------------------------------------------------------------------------------

-- op. interestadual
Set @WFlgOpeInteresta = 0
if @PCodUfDst <> @em_CodEst
  Set @WFlgOpeInteresta = 1

-- calcula %participacao DIfal UF Destino nem op.interestaduais
Set @WPerDifAlq = 0.00
if (@WFlgOpeInteresta = 1) and (@WPerParIcmUfDes > 0) and (@PFlgCalIcmPro = 1) and
   (@WAlqIcmExt < (@WAlqIcmInt-@WAlqIcmIntFcp))
  Set @WPerDifAlq = (@WAlqIcmInt - @WAlqIcmIntFcp - @WAlqIcmExt) * @WPerParIcmUfDes/100

-- retorno o preço sem acréscimo de ICM
if @PPrcUniSemAcrIcm > 0
  Set @WPrcUniIteOri = @PPrcUniSemAcrIcm
else
  Set @WPrcUniIteOri = @PPrcUniIte

Set @PPrcUniIte = @WPrcUniIteOri

-- acresce ICMS ao pr.Unitario se ICMS Deson for abatido do valor
Set @PFlgPrcUniAcrIcm = 0
if (@rt_Flg_DscIcmOrgPubAcr = 1) and (@WAlqIcmExt > 0) and  
   (@WFlgDscDesone = 1) and (@PFlgCalIcmPro = 1)
  begin
    Set @PFlgPrcUniAcrIcm = 1
    Set @PPrcUniSemAcrIcm = @WPrcUniIteOri

--antes
--    Set @PPrcUniComAcrIcm = Round((@WPrcUniIteOri/(1-(@WAlqIcmExt+@WPerDifAlq)/100)),@pm_QtdDecPrcItePdv)

    Set @WVlrAcrUniIcm = @WPrcUniIteOri * (@WAlqIcmExt+@WPerDifAlq) / (100-(@WAlqIcmExt+@WPerDifAlq))
    if @pm_FlgAltUnvItePdv = 0
      Set @WVlrAcrUniIcm = Round(@WVlrAcrUniIcm,@pm_QtdDecPrcItePdv)
    Set @PPrcUniComAcrIcm = @WPrcUniIteOri + @WVlrAcrUniIcm

    Set @PPrcUniIte       = @PPrcUniComAcrIcm
  end

-----------  DESONERAÇÃO 1 ICMS  -----------------------------------------------------------------------------
-- desoneração somente sobre valor item (sem frete / despesas)
-- ou existe redução, ou desoneração ou suframa
Set @WFlgIcmIsento = 0

-- produto suframado: concede icms tributavel como desconto nas operações inter-estaduais
-- somente para produtos nacionais/nacionalizados
if @PFlgValDscSuframa = 1
  if (@WFlgOpeInteresta = 1) and (@PCodOriMer = '0') and 
     (@PFlgCalIcmPro = 1) and (@WAlqIcmExt > 0) 
    begin
      if Charindex(@PCodSt,';00;10;20;70;') > 0    -- if Charindex(@PCodSt,';00;10;20;70;90;') > 0 
        Set @PFlgCalRepIcm  = 0    -- nao calcula repasse
      else
        Set @PFlgValDscSuframa = 0 
    end
  else
    Set @PFlgValDscSuframa = 0


Set @WFlgEmbutiuDscDesonePrcUnit = 0  -- indica se embutiu desoneração no pr.unitario

if @PFlgCalIcmPro = 1
  begin
    if ((@rt_Flg_DscIcmOrgPub = 1) or (@rt_Flg_DscIcmOrgPubAcr = 1)) and
       (@WFlgDscDesone = 1) and (@WPerIcmDesone <> @WAlqIcmExt)
      Set @WPerIcmDesone = @WAlqIcmExt

    if @WAlqIcmExt = @WPerIcmDesone
      Set @WFlgIcmIsento = 1

    -- desoneração por redução de base de cálculo
    Set @WPerIcmDesRedBasCal = 0
    if @WPerRedBasCalIcmExt > 0
      Set @WPerIcmDesRedBasCal = Round(@WAlqIcmExt*@WPerRedBasCalIcmExt/100,4)
--    if @WPerIcmDesone = 0
--      Set @WPerIcmDesone = @WPerIcmDesRedBasCal

    -- embute desc.desoneração no preço unitário
    if (@WPerIcmDesone > 0) and (@pm_FlgEmbDscDesoneItePrcUni = 1) and
       (@WFlgDscDesone = 1) and (@WPerRedBasCalIcmExt = 0) and
       (@PFlgValDscSuframa = 0)
      begin
        Set @WFlgEmbutiuDscDesonePrcUnit = 1
        Set @PPrcUniSemAcrIcm = @WPrcUniIteOri

        -- @PPrcUniIte pode estar com acréscimo ICMS
        -- valor da desoneracao unitario
        Set @WVlrDscUniIcm = @PPrcUniIte*(@WPerIcmDesone+@WPerDifAlq)/100
        if @pm_FlgAltUnvItePdv = 0
          Set @WVlrDscUniIcm = Round(@WVlrDscUniIcm,@pm_QtdDecPrcItePdv)

        -- abate desoneração do preço
        Set @PPrcUniIte = @PPrcUniIte - @WVlrDscUniIcm 

        -- calcula desoneração        
        Set @PMtvIcmDesone = @WCodMtvDesone
        Set @PVlrIcmDesone = Round(Round(@WVlrDscUniIcm*@PQtdPed,2),@WQtdDecRndTrb)

        Set @PBasDst = 0
        Set @PPerDst = 0
        Set @PVlrDst = 0

        Set @WFlgDscDesone = 0
      end
  end  -- if @PFlgCalIcmPro = 1

  -- desoneração ref. ST recolhido antecipadamente em op.Sem Retenção
  -- e não houve desoneração anterior
  if (@rt_Flg_DscSbtOrgPub = 1) and (@WTipPrcBasDebSbt = 'O') and
     (@WFlgDscDesone = 1) and (@PVlrIcmDesone = 0)
    begin
      Set @WPerIcmDesone = 0
      Set @PVlrIcmDesone = 0
      Set @WFlgSbtRetAnt = 0

      -- calcula desoneração ref SBT retido anteriormente        
      -- se está calculando tributos em PDVIT e existe calculo em PDVLT
      if @PCodPDVLT > 0  
        begin
          if Exists(Select 1
                      From PDVLT
                     Where Cod_Estabe = @PCodEstabe
                       And Cod_Pedido = @PCodPDVLT
                       And Cod_Produt = @PCodPrd
                    Having sum(Qtd_Lote) >= (@PQtdPed+@PQtdBon))
            begin
              Declare @lt_QtdLot int,
                      @lt_VlrSbtRetAnt numeric(18,4)

              Select @lt_QtdLot = sum(IsNull(Qtd_Lote,0)), 
                     @lt_VlrSbtRetAnt = sum(IsNull(Vlr_SbtRetAnt,0))
                From PDVLT
               Where Cod_Estabe = @PCodEstabe
                 And Cod_Pedido = @PCodPDVLT
                 And Cod_Produt = @PCodPrd
              Having sum(Qtd_Lote) >= (@PQtdPed+@PQtdBon)

              if @lt_QtdLot > 0
                begin
                  Set @PVlrIcmDesone = @lt_VlrSbtRetAnt* (@PQtdPed+@PQtdBon)/@lt_QtdLot 
                  Set @WFlgSbtRetAnt = 1
                end
            end  -- if Exists(Select 1
        end  -- if @PCodPDVLT > 0 

      if @WFlgSbtRetAnt = 0
        Set @PVlrIcmDesone = dbo.FN_ValSbtUltEnt(@PCodEstabe, @PCodPrd, @PCodLot, @PDatEmi, (@PQtdPed+@PQtdBon))

	  if @PVlrIcmDesone > 0
	    begin
          Set @PVlrSbtRetAnt = @PVlrIcmDesone
          Set @PMtvIcmDesone = @WCodMtvDesone
          Set @PBasDst = 0
          Set @PPerDst = 0
          Set @PVlrDst = @PVlrIcmDesone
	    end
      else
        Set @WFlgDscDesone = 0
    end

----------- FIM DESONERAÇÃO 1 ICMS  -----------------------------------------------------------------------------

-- calcula valores totais do item (Vlr_TotItem e Vlr_BruItem em NFSIT)
Set @it_Vlr_BruIte = Round(@PPrcUniIte * (@PQtdPed+@PQtdBon),2)

-- calcula repasse para futuros calculos
-- repasse de ICMS se houver diferenca de aliquotas
-- e somente cipados ou liberados c/ repasse
-- repasse bruto
Set @PPerRep = @WPerRepIcm
if (@PFlgCalRepIcm = 1) and (@PPerRep <> 0) and (@pr_Ctrl_Preco <> 'L')
  begin
    Set @WVlrRepBru    = Round(@PPrcUniIte * (@PQtdPed + @PQtdBon) * @PPerRep/100,2)
    Set @WVlrRepBruTab = Round(@PPrcVen * (@PQtdPed + @PQtdBon) * @PPerRep/100,2)
  end

-- embute desconto no preço
-- para garantir que calculos tributos PDVIT = NFSIT
if @PFlgPrcUniDsc = 1
  Set @it_Vlr_TotIte = Round(@PQtdPed * Round(@PPrcUniIte*(1-@PPerDscIte/100),@pm_QtdDecPrcItePdv),2)
else
  Set @it_Vlr_TotIte = Round(@PQtdPed * @PPrcUniIte * (1-@PPerDscIte/100),2)

-- calcula despesa tributaria 
--if (@PFlgCalIcmPro = 1) and (@WTipPrcBasDebSbt = 'X')   -- nao eh subst.tributaria
  if @WPerResExt > 0
    begin
      Set @WVlrBasResExt = @it_Vlr_TotIte
      Set @PVlrDspTrb = Round(@WVlrBasResExt * @WPerResExt/100,2)  -- @WQtdDecRndTrb
    end

-- valor bruto do item
Set @WBruIte = Round(@it_Vlr_BruIte - @WVlrRepBru + @PVlrDspRat + @PVlrDspTrb,2)

-- calcula IPI
Exec PR_CalculaIpi @PFlgCalIpi, @PCodEstabe, 'S', @PTipNot, @PCodRamAtv, @WBruIte, @PCodPrd,
                   @PCodOriMer output, @PCstIpi output, @PCodEnqIpi output,
                   @PVlrBasIpi output, @PAlqIpi output, @PVlrIpi output, @WDesEnqIpi output

/*
-- produto suframado: concede icms tributavel como desconto nas operações inter-estaduais
-- somente para produtos nacionais/nacionalizados
if @PFlgValDscSuframa = 1
  if (@WFlgOpeInteresta = 1) and (@PCodOriMer = '0') and 
     (@PFlgCalIcmPro = 1) and (@WAlqIcmExt > 0) 
    begin
      if Charindex(@PCodSt,';00;10;20;70;') > 0    -- if Charindex(@PCodSt,';00;10;20;70;90;') > 0 
        Set @PFlgCalRepIcm  = 0    -- nao calcula repasse
      else
        Set @PFlgValDscSuframa = 0 
    end
  else
    Set @PFlgValDscSuframa = 0
*/

if (@PFlgCalIcmPro = 1) or (@PFlgCalIcmSbt = 1)
  if @WVlrRepBru > 0
    begin
      -- repasse liquido
      Set @PBasRep = Round(@it_Vlr_TotIte + @PVlrDspRat + @PVlrDspTrb,2)
      Set @PVlrRep = Round(@PBasRep * @PPerRep/100,@WQtdDecRndTrb)
      if @PVlrRep = 0
        begin
          Set @PBasRep = 0
          Set @PPerRep = 0
        end
    end

-- calcula IR
if @WAlqIrf > 0
  begin
    Set @PAlqIrf = @WAlqIrf
    Set @PVlrBasIrf = @it_Vlr_TotIte
    Set @PVlrIrf = Round(@PVlrBasIrf * @PAlqIrf/100, @WQtdDecRndTrb)
  end

-- valor liquido do item
Set @WVlrIte = @it_Vlr_TotIte - @PVlrRep

-- desconto cabecalho
Set @PVlrDscRat = @PVlrCabDscRat
if (@PVlrDscRat = 0) and (@PPerDscCab > 0) and (@pr_Desconto = 0)
  Set @PVlrDscRat = Round(@WVlrIte * @PPerDscCab/100,2) 
  
Set @WVlrIte = Round(@WVlrIte - @PVlrDscRat - @PVlrCabDscBonRat,2)



-- resolver
-- @WVlrIte : está com repasse
-- @PVlrCabDscBonRat está sem repasse
IF @WVlrIte < 0
  Set @WVlrIte = 0 



if @PFlgCalIcmPro = 1
  begin
    -- produto suframado: concede icms tributavel como desconto
    if @PFlgValDscSuframa = 1
      begin
        Set @WPerRedBasCalIcmExt = 0
        Set @WPerIcmDesone = Round(@WAlqIcmExt*(1-@WPerRedBasCalIcmExt/100),4)
        Set @WFlgIcmIsento = 1
        Set @WCodMtvDesone = '7'
        Set @WFlgDscDesone = 1
      end

    if @WPerIcmDesone > 0
      begin
        if (@PVlrIcmDesone = 0) -- já calculou desoneração anteriormente
          begin
            Set @PMtvIcmDesone = @WCodMtvDesone
            Set @PVlrIcmDesone = Round(@WVlrIte*(@WPerIcmDesone+@WPerDifAlq)/100,@WQtdDecRndTrb)
          end

        -- se for desoneracao por redução de base de calculo não abate valor na NF -- 
        if (@WFlgEmbutiuDscDesonePrcUnit = 0) and
           (@WFlgDscDesone = 1) and (@WPerRedBasCalIcmExt = 0)
          begin
            Set @PBasDst = @WVlrIte
            Set @PPerDst = @WPerIcmDesone+@WPerDifAlq
            Set @PVlrDst = @PVlrIcmDesone
    
            if @PFlgValDscSuframa = 1 
              begin
                Set @PMtvIcmDesone =  '7'
                Set @PFlgIncFis = 1
                Set @PVlrDscSuframa = @PVlrIcmDesone
              end
          end
      end  -- if @WPerIcmDesone > 0
  end
----------- FIM DESONERAÇÃO 2 ICMS  -----------------------------------------------------------------------------

Set @WLiq = Round(@WVlrIte,2) - @PVlrDst

-- o calculo abaixo devera ser excluido com a despesa estiver realmente rateada no item
Set @WLiq = Round(@WLiq + @PVlrDspRat + @PVlrDspTrb,2)

-- registra icms proprio, icms tributavel da operacao se DEB/CRE ou SUB.TRIB.
Set @WCre = 0
Set @PPerRedBasCalIcm = @WPerRedBasCalIcmExt
Set @PAlqIcm = @WAlqIcmExt

Set @WCreFcp = 0
Set @PAlqIcmFcp = @WAlqIcmExtFcp

--Set @PVlrBasTri = @WLiq

-- icms próprio
Set @PBasIcmPro = Round(@WLiq * (1 - @PPerRedBasCalIcm/100),2)
Set @PIcmPro = Round(@PBasIcmPro * @PAlqIcm/100, @WQtdDecRndTrb)
if @PIcmPro = 0
  Set @PBasIcmPro = 0

Set @WIcmProFcp = Round(@PBasIcmPro * @PAlqIcmFcp/100, @WQtdDecRndTrb)
Set @PVlrIcmDiferi = Round(@PIcmPro * @PPerIcmDiferi/100, @WQtdDecRndTrb)

if (@PFlgCalIcmPro = 1) or (@PFlgCalIcmSbt = 1)
  begin
    -- credito com reducao da base de calculo
    Set @WCre = @PIcmPro
    Set @WCreFcp = @WIcmProFcp
    if @WCre > 0
      Set @PCodModBasCalIcm = '3'  -- ICMS sobre Valor da operação
  end

-- calcula icms tributavel (debito/credito)
if (@PFlgCalIcmPro = 1) and (@WTipPrcBasDebSbt = 'X')   -- nao eh subst.tributaria
  begin
    Set @PBasIcm = @PBasIcmPro
    if @WPerIcmDesRedBasCal > 0
      Set @PVlrIcm = @PIcmPro - @PVlrIcmDiferi  -- @PIcmPro já está com redução de B.C.
    else
      Set @PVlrIcm = @PIcmPro - @PVlrIcmDesone - @PVlrIcmDiferi
    Set @PVlrIcmFcp = @WIcmProFcp
    if @WFlgIcmIsento = 1
      begin
        Set @PBasIcm = 0
        Set @PVlrIcm = 0
        Set @PVlrIcmFcp = 0
      end

    Set @PFlgUsaDebPresum = @WFlgUsaDebPresum
    Set @PAlqDebPresum = @WAlqDebPresum
  end

-----------------------------------------------------------------------------------------------------------------------------------------

-- ver se eh ST sem retencao
if @WTipPrcBasDebSbt = 'O'
  begin
    Set @PVlrPrdSub = 0
    Set @PAlqIcmSbt = 0
    Set @PAlqIcmSbtFcp = 0
    Set @PAlqAgrSbt = 0
    Set @PPerRedBasCalIcmSbt = 0
    Set @PBasSbt = 0
    Set @PVlrSbt = 0
    Set @PVlrSbtFcp = 0
--    Set @PBasIcmPro = 0
--    Set @PIcmPro = 0 
    Set @PBasIcm = 0
    Set @PVlrIcm = 0 
    Set @PVlrIcmFcp = 0
    Set @PVlrIse = 0
    Set @PVlrOut = @WLiq
    Set @PCodModBasCalIcm = ''
    Set @PCodModBasCalIcmSbt = ''
    Set @PFlgUsaDebPresum = @WFlgUsaDebPresum
    Set @PAlqDebPresum = @WAlqDebPresum
  end

-- Calcula Substituicao Tributaria
if (@PFlgCalIcmSbt = 1) and (@WTipPrcBasDebSbt <> 'X') and (@WTipPrcBasDebSbt <> 'O')
  begin
    -- debito presumido p/ uso no calculo de rentabilidade
    Set @PFlgUsaDebPresum = 0
    Set @PAlqDebPresum = 0
  
    -- valor bruto do item
    Set @WBruIte = Round(@it_Vlr_BruIte - @WVlrRepBru + @PVlrDspRat + @PVlrDspTrb,2)
    
    if @WCtrBasCalDeb = 'B'  -- pelo vlr. bruto
      begin
        if @WTipPrcBasDebSbt = 'D'           -- utiliza PMPF do cadastro
          Set @WVlrBasPrdSub = @PPrcPonFin * (@PQtdPed + @PQtdBon)
        else
        if @WTipPrcBasDebSbt = 'M'           -- utiliza P.M.C. do cadastro
          Set @WVlrBasPrdSub = @PPrcMax * (@PQtdPed + @PQtdBon)
        else
        if @WTipPrcBasDebSbt = 'F'            -- utiliza preco fabrica do cadastro
          Set @WVlrBasPrdSub = (@PPrcFab * (@PQtdPed + @PQtdBon)) + @PVlrIpi
        else
        if @WTipPrcBasDebSbt = 'P'            -- utiliza preco ref fcia popular
          Set @WVlrBasPrdSub = @PPrcRefFpb * (@PQtdPed + @PQtdBon)
        else
        if @WTipPrcBasDebSbt = 'V'            -- utiliza preco venda do cadastro
          Set @WVlrBasPrdSub = (@PPrcVen * (@PQtdPed + @PQtdBon)) + @PVlrIpi - @WVlrRepBruTab
        else
        if @WTipPrcBasDebSbt = 'C'            -- utiliza preco compra do cadastro
          Set @WVlrBasPrdSub = @PPrcUltEnt * (@PQtdPed + @PQtdBon)
        else
        if @WTipPrcBasDebSbt = 'T'            -- utiliza preco transacao
          Set @WVlrBasPrdSub = @WBruIte + @PVlrIpi 
        else
          Set @WVlrBasPrdSub = @WBruIte + @PVlrIpi --/ transacao
      end
    else
      Set @WVlrBasPrdSub = @WLiq + @PVlrIpi
          
    -- redução da base de calculo original
    Set @WVlrBasPrdSub = @WVlrBasPrdSub * (1 - @WPerRedBasCalIcmInt/100) 

    -- Valor base da ST: agregacao, reducao e aliquota 
    Set @PAlqAgrSbt = @WAlqAgrDeb
    Set @PPerRedBasCalIcmSbt = @WPerRedBasCalDeb

    -- verifica limitador ST: SC (Santa Catarina)
    if @em_CodEst = 'SC'
      if (@PPerRedBasCalIcmSbt > 0) and (@WPerLimMinIcmSbtSaiRedDeb > 0) 
        if @WLiq >= Round(@WVlrBasPrdSub*@WPerLimMinIcmSbtSaiRedDeb/100,2)
          -- desconsidera reducao na base de calculo
          Set @PPerRedBasCalIcmSbt = 0

    Set @PVlrPrdSub = @WVlrBasPrdSub * (1 - @PPerRedBasCalIcmSbt/100) 
    Set @PBasSbt = @PVlrPrdSub * (1 + @PAlqAgrSbt/100)

    -- verifica limitador B.C.ST
    Set @WVlrBasCalMinSubTri = 0
    if @WTipPrcLimMinBasCalIcmSbtSai = 'E'
      begin
        -- média da B.C. de Entrada + Agreg.
        Set @WVlrBasCalMinSubTri = Round(@PVlrBasCalSubTriEntMed * (@PQtdPed + @PQtdBon) * (1 + @WAlqAgrLimMinBasCalIcmSbtSai/100),2)
      end
    if @PBasSbt < @WVlrBasCalMinSubTri
      Set @PBasSbt = @WVlrBasCalMinSubTri

    Set @PBasSbt = Round(@PBasSbt,2)

    -- ver se utiliza no calculo da ST % fixo sobre preco do produto
    if @WTipCreSbt = 'F'
      begin
        Set @PAlqIcmSbt = @WAlqDebSbt
        Set @PVlrSbt = Round(@PBasSbt * @PAlqIcmSbt/100, @WQtdDecRndTrb)
        Set @PAlqIcmSbtFcp = @WAlqIcmIntFcp 
        Set @PVlrSbtFcp = Round(@PBasSbt * @PAlqIcmSbtFcp/100, @WQtdDecRndTrb)
        if @PAlqAgrSbt = 0
          Set @PCodModBasCalIcmSbt = '0'  -- preco tabela ou maximo sugerido
        else
          Set @PCodModBasCalIcmSbt = '4'
      end
    else
      -- calcula subst.tributaria com agregacao      
      begin
        -- debito com red. base de calculo icms
        Set @PAlqIcmSbt = @WAlqIcmInt
        Set @WDebSbt = Round(@PBasSbt * @PAlqIcmSbt/100, @WQtdDecRndTrb)

        Set @PAlqIcmSbtFcp = @WAlqIcmIntFcp
        Set @WDebSbtFcp = Round(@PBasSbt * @PAlqIcmSbtFcp/100, @WQtdDecRndTrb)

        -- credito
        if @WCtrBasCalCre = 'B'         -- credito pelo vlr.bruto
          begin
            if @WTipPrcBasCreSbt = 'F'      -- utiliza preco fabrica do cadastro
              Set @WCreSbt = @PPrcFab * (@PQtdPed + @PQtdBon)
            else
            if @WTipPrcBasCreSbt = 'V'     -- utiliza preco venda do cadastro
              Set @WCreSbt = @PPrcVen * (@PQtdPed + @PQtdBon) - @WVlrRepBruTab
            else
            if @WTipPrcBasCreSbt = 'T'     -- utiliza preco da transacao
              Set @WCreSbt = @WBruIte          
            else
              Set @WCreSbt = @WBruIte              -- transacao

            -- credito com red.base de calculo
            Set @WValAux = @WCreSbt
            Set @WCreSbt = Round(@WValAux * (1 - @PPerRedBasCalIcm/100) * @PAlqIcm/100, @WQtdDecRndTrb)
            Set @WCreSbtFcp = Round(@WValAux * (1 - @PPerRedBasCalIcm/100) * @PAlqIcmFcp/100, @WQtdDecRndTrb)
          end
        else
          begin
            Set @WCreSbt = @WCre
            Set @WCreSbtFcp = @WCreFcp
          end

        -- calcula icm subst.
        Set @PVlrSbt = @WDebSbt - @WCreSbt
        Set @PVlrSbtFcp = @WDebSbtFcp - @WCreSbtFcp
        
--        if (@WTipPrcBasDebSbt = 'M') or (@WTipPrcBasDebSbt = 'P') or (@PAlqAgrSbt = 0)
        if @PAlqAgrSbt = 0
          Set @PCodModBasCalIcmSbt = '0'  -- preco tabela ou maximo sugerido
        else
          Set @PCodModBasCalIcmSbt = '4'  -- Margem Valor Agregado (%)
            
      end  -- calcula subst.tributaria com agregacao
          
    -- verifica limitador ST: PR (Parana)
    if @em_CodEst <> 'SC'
      begin
        Set @WVlrMinIcmSbtSaiRedDeb = 0
        if (@PPerRedBasCalIcmSbt > 0) and (@WPerLimMinIcmSbtSaiRedDeb > 0) 
          Set @WVlrMinIcmSbtSaiRedDeb = Round(@PBasSbt*@WPerLimMinIcmSbtSaiRedDeb/100, @WQtdDecRndTrb)

        if (@WVlrMinIcmSbtSaiRedDeb > 0) and (@PVlrSbt < @WVlrMinIcmSbtSaiRedDeb)
          begin
            -- desconsidera reducao na base de calculo
            Set @PPerRedBasCalIcmSbt = 0
            Set @PVlrSbt = @WVlrMinIcmSbtSaiRedDeb
          end
      end

    -- verifica limitador de ST: DMD-6109: implementado em 10/06/2021
    Set @WVlrMinSbt = 0
    Set @WVlrPrdSbtLim = 0
    if @WPerLimMinIcmSbt > 0 
      begin
        if @WTipPrcLimMinIcmSbt = 'M'
          Set @WVlrPrdSbtLim = @PPrcMax * (@PQtdPed+@PQtdBon)
        else
        if @WTipPrcLimMinIcmSbt = 'D'
          Set @WVlrPrdSbtLim = @PPrcPonFin * (@PQtdPed+@PQtdBon)
        Set @WVlrMinSbt = Round(@WVlrPrdSbtLim*@WPerLimMinIcmSbt/100, @WQtdDecRndTrb)
      end
    if (@PVlrSbt < @WVlrMinSbt) and (Round(@WVlrMinSbt,2) > 0) 
      begin
        Set @PVlrPrdSub = @WVlrPrdSbtLim 
        Set @PBasSbt = @WVlrPrdSbtLim
        Set @PVlrSbt = @WVlrMinSbt
        Set @PAlqIcmSbt = @WPerLimMinIcmSbt
        Set @PAlqIcmSbtFcp = @WAlqIcmIntFcp 
        Set @PVlrSbtFcp = Round(@PBasSbt * @PAlqIcmSbtFcp/100, @WQtdDecRndTrb)
        if @WFlgImpSbtFnt = 1
          begin
            if @PAlqIcmSbt > 0
              Set @PCodModBasCalIcmSbt = '4'  -- Margem Valor Agregado (%)
            else
              Set @PCodModBasCalIcmSbt = '0'  -- preco tabela ou maximo sugerido
          end
       else
         Set @PCodModBasCalIcmSbt = ''
      end

    if Round(@PVlrSbt,2) <= 0
      begin
        Set @PVlrSbt = 0
        Set @PVlrSbtFcp = 0
        if @PBasSbt = 0
          begin
            Set @PCodModBasCalIcmSbt = ''
            Set @PVlrPrdSub = 0
            Set @PAlqIcmSbt = 0
            Set @PAlqIcmSbtFcp = 0
            Set @PAlqAgrSbt = 0
            Set @PPerRedBasCalIcmSbt = 0
          end  
      end  -- if @PVlrSbt <= 0
          
  end  -- fim calculo substituicao tributaria
  
-- se a ST nao for retida na fonte
if (@WFlgImpSbtFnt = 0) and (@PVlrSbt > 0)
  begin
    Set @PAlqIcmSbt = 0
    Set @PAlqIcmSbtFcp = 0
    Set @PAlqAgrSbt = 0
    Set @PPerRedBasCalIcmSbt = 0
    Set @PBasSbt = 0
    Set @PVlrSbt = 0
    Set @PVlrSbtFcp = 0
    Set @PVlrPrdSub = 0

    if Charindex(@PCodSt,';51;') = 0   -- if Charindex(@PCodSt,';51;90;') = 0
      if @PPerRedBasCalIcm > 0 
        Set @PCodSt = '20' 
      else
        Set @PCodSt = '00' 

    Set @PBasIcm = @PBasIcmPro
    if @WPerIcmDesRedBasCal > 0
      Set @PVlrIcm = @PIcmPro - @PVlrIcmDiferi  -- @PIcmPro já está com redução de B.C.
    else
      Set @PVlrIcm = @PIcmPro - @PVlrIcmDesone - @PVlrIcmDiferi
    Set @PVlrIcmFcp = @WIcmProFcp
    if @WFlgIcmIsento = 1
      begin
        Set @PBasIcm = 0
        Set @PVlrIcm = 0
        Set @PVlrIcmFcp = 0
      end
  end

-- nao houve tributacao qualquer
if (@PFlgCalIcmPro = 0) and (@PFlgCalIcmSbt = 0)
  begin
    Set @PVlrOut = @PBasIcmPro
    if Charindex(@PCodSt,';51;') = 0  -- if Charindex(@PCodSt,';51;90;') = 0
--      Set @PCodSt = '41'   -- para não contribuinte
      Set @PCodSt = '90'     -- para contribuinte 
  end

-- CST sujeitas a ST 10;30;60;70;
if (@PFlgCalIcmSbt = 1) and (@PVlrSbt = 0) and (Charindex(@PCodSt,';10;30;60;70;') > 0) -- if (@PVlrSbt = 0) and (Charindex(@PCodSt,';10;30;60;70;') > 0)
  if Charindex(@PCodSt,';10;70;') > 0 
    begin
      Set @PBasIcm = @PBasIcmPro
      if @WPerIcmDesRedBasCal > 0
        Set @PVlrIcm = @PIcmPro - @PVlrIcmDiferi  -- @PIcmPro já está com redução de B.C.
      else
        Set @PVlrIcm = @PIcmPro - @PVlrIcmDesone - @PVlrIcmDiferi
      Set @PVlrIcmFcp = @WIcmProFcp
      if @WFlgIcmIsento = 1
        begin
          Set @PBasIcm = 0
          Set @PVlrIcm = 0
          Set @PVlrIcmFcp = 0
        end

      if @PBasSbt = 0
        if @PCodSt = '70'
          Set @PCodSt = '20' 
        else
          Set @PCodSt = '00' 
    end
  else
    begin
      Set @PVlrOut = @PBasIcmPro
      if @PBasSbt > 0 
        if @PCodSt = '60'
          Set @PBasSbt = 0

      if @PBasSbt = 0
        if @PCodSt = '30'
          Set @PCodSt = '40' 
    end

--ajusta ressarcimento ST
if (@PCodSt = '60') and (@PVlrSbt > 0)
  begin
    Set @PBasRes = @PBasSbt
    Set @PVlrRes = @PVlrSbt
    Set @PBasSbt = 0 
    Set @PVlrSbt = 0 

    Set @PAlqIcmSbtFcpRet = @PAlqIcmSbtFcp
    Set @PVlrSbtFcpRet = @PVlrSbtFcp
    Set @PAlqIcmSbtFcp = 0
    Set @PVlrSbtFcp = 0
  end

-- exige tributacao icm
if Charindex(@PCodSt,';00;10;20;51;70;') > 0  --if Charindex(@PCodSt,';00;10;20;51;70;90;') > 0
  begin
    Set @PBasIcm = @PBasIcmPro
    if @WPerIcmDesRedBasCal > 0
      Set @PVlrIcm = @PIcmPro - @PVlrIcmDiferi  -- @PIcmPro já está com redução de B.C.
    else
      Set @PVlrIcm = @PIcmPro - @PVlrIcmDesone - @PVlrIcmDiferi
    Set @PVlrIcmFcp = @WIcmProFcp
    if @WFlgIcmIsento = 1
      begin
        Set @PBasIcm = 0
        Set @PVlrIcm = 0
        Set @PVlrIcmFcp = 0
      end
  end

/* removi em 21/07/2022 : não consta na 19.05
-- ajusta cst de isento
if (@PVlrIcm = 0) and
   (Charindex(@PCodSt,';30;40;41;50;60;90;') = 0)  -- aqui inclui 90 em 14/06/2022
  begin
    if Charindex(@PCodSt,';00;20;51;') > 0
      Set @PCodSt = '40'
    if Charindex(@PCodSt,';10;;70;') > 0
      Set @PCodSt = '30'
    else
    if ((@PVlrSbt+@PVlrRes) > 0)
      Set @PCodSt = '30'
    else
      Set @PCodSt = '40'
  end
*/

-- nao exige tributacao icm
if Charindex(@PCodSt,';30;40;41;50;60;') > 0   
  begin
    Set @PBasIcm = 0
    Set @PVlrIcm = 0
    Set @PVlrIcmFcp = 0
  end

if (@PCodSt = '90') and (@WTipPrcBasDebSbt = 'O')
  begin
    Set @PBasIcm = 0
    Set @PVlrIcm = 0
    Set @PVlrIcmFcp = 0
  end

if (@PVlrIse = 0) and (@PVlrSbt = 0) and (@PVlrRes = 0) and (@PVlrIcm = 0) and (@PVlrOut = 0)
  if (@PFlgCalIcmPro = 1) or (@PFlgCalIcmSbt = 1)
    Set @PVlrIse = @WLiq
  else
    Set @PVlrOut = @WLiq

-- AQUI não funciona mais... alíquota interna nunca pode ser zero
if Round(@PVlrIse,2) > 0
  if @PAlqIcm = 0
    begin
      Set @PBasIcmPro = 0
      Set @PIcmPro = 0 
      Set @PBasIcm = 0
      Set @PVlrIcm = 0 
      Set @PVlrIcmFcp = 0
      Set @PVlrOut = 0
      Set @PCodSt = '40'
    end

-- ICM presumido
if (@PVlrIcm > 0) and (@PFlgUsaDebPresum = 0)
  begin
    Set @PFlgUsaDebPresum = @WFlgUsaDebPresum
    Set @PAlqDebPresum = @WAlqDebPresum
  end

Set @PVlrOut = Round(@WLiq - @PVlrIse - @PBasIcm,2)
if @PVlrOut < 0
  Set @PVlrOut = 0
if @PVlrOut > @WLiq
  Set @PVlrOut = @WLiq 

-- ajusta Cod.Modalidade base de calculo icm sbt
if @PVlrSbt > 0
  if @PAlqAgrSbt = 0
    Set @PCodModBasCalIcmSbt = '0'  -- preco tabela ou maximo sugerido
  else
    Set @PCodModBasCalIcmSbt = '4'
else
  Set @PCodModBasCalIcmSbt = ''

if Charindex(@PCodSt,';30;40;41;50;60;') > 0 
  Set @PCodModBasCalIcm = ''
if Charindex(@PCodSt,';00;20;40;41;50;51;60;') > 0 
  Set @PCodModBasCalIcmSbt = ''
  
Set @PVlrBasTri = @WLiq


-- Maranhão: concede valor ST (Cod.ST = 30) como desconto em operações internas
-- CST 30 = Isenta / não tributada e com cobrança do ICMS por substituição tributária
if (@em_FlgGerDscCanSbtOpeInt = 1) and (@WFlgOpeInteresta = 0) and
   (@PVlrSbt > 0) and (@PVlrDst = 0)
  begin
    if (@PCodSt = '30')  -- (@em_CodEst = 'MA')
      begin
        Set @PVlrDst = @PVlrSbt
      end
  end

-- FCP UF destino op. interestaduais
if @WFlgOpeInteresta = 1
  begin
    Set @PAlqIntIcmUfDes = @WAlqIcmInt-@WAlqIcmIntFcp
    Set @PPerFcpUfDes = @WAlqIcmIntFcp

    if @PBasSbt > 0 
      Set @PVlrFcpUfDes = Round(@PBasSbt * @PPerFcpUfDes/100, @WQtdDecRndTrb)
    else
      if @PVlrIcm > 0 
        Set @PVlrFcpUfDes = Round(@PBasIcm * @PPerFcpUfDes/100, @WQtdDecRndTrb)
      else
      if @PCodSt = '60'
        Set @PVlrFcpUfDes = Round(@PBasIcmPro * @PPerFcpUfDes/100, @WQtdDecRndTrb)

    -- novo
    if (@PBasSbt > 0) and
       (@PBasSbt > @PBasIcmPro)
      Set @PVlrFcpSbtUfDes = Round((@PBasSbt-@PBasIcmPro) * @PPerFcpUfDes/100, @WQtdDecRndTrb)

    -- DIFAL - Partilha ICMS operações interestaduais p/ consumidor final não contribuinte
    -- Convênio ICMS 153/2015 
    -- DIFAl só existe quando a aliquota de ICMS entre os dois estados envolvidos é menor que 
    -- a alíquota interna de comercialização (da UF destino)
    -- (diferença entre a alíquota interestadual(@WAlqIcmExt) e a alíquota interna (@WAlqIcmInt) da Unidade Federada de destino)
    if (@WPerParIcmUfDes > 0) and (@PFlgCalIcmPro = 1) --if (@WFlgOpeInteresta = 1) and (@WPerParIcmUfDes > 0) and (@PFlgCalIcmPro = 1)
      begin
        Set @PPerParIcmUfDes = @WPerParIcmUfDes
        Set @PAlqIntIcmUfDes = @WAlqIcmInt-@WAlqIcmIntFcp
        if @PAlqIcm < @PAlqIntIcmUfDes  -- @WAlqIcmExt < @WAlqIcmInt 
          begin
            if @PBasIcmPro > 0
              Set @WVlrBasDifal = @PBasIcmPro
            Set @WVlrIcmDifAlq = Round(@WVlrBasDifal * (@PAlqIntIcmUfDes-@PAlqIcm)/100, @WQtdDecRndTrb)
            Set @PVlrParIcmUfDes = Round(@WVlrIcmDifAlq * @PPerParIcmUfDes/100, @WQtdDecRndTrb)
            Set @PVlrParIcmUfRem = @WVlrIcmDifAlq - @PVlrParIcmUfDes
          end
      end

    -- se houver desoneração por isenção não há partilha
    if (@PVlrIcmDesone > 0) and (@PVlrIcm = 0)
      begin
        Set @PVlrParIcmUfDes = 0
        Set @PVlrParIcmUfRem = 0
      end
  end  -- if @WFlgOpeInteresta = 1

-- se desoneração não é abatida não informa....
if @WFlgDscDesone = 0
  begin
    Set @PMtvIcmDesone = ''
    Set @PVlrIcmDesone = 0
  end

-- aqui TESTE em 24/03/2022: zerar ICMS proprio...
if Round(@PVlrIse,2) > 0
  begin
    Set @PAlqIcm = 0
    Set @PBasIcmPro = 0
    Set @PIcmPro = 0 
    Set @PBasIcm = 0
    Set @PVlrIcm = 0 
    Set @PVlrIcmFcp = 0
    Set @PVlrOut = 0
  end


-- PIS/COFINS
Set @WVlrBasPisCof = @WLiq

-- ressarcimento é despesa
if (@PVlrRes > 0) and (@PFlgSbtEmbPrc = 0)
  Set @WVlrBasPisCof = Round(@WLiq+@PVlrRes,2)

-- ipi
if @pm_FlgIncIpiCalPis = 1  
  Set @WVlrBasPisCof = @WVlrBasPisCof + @PVlrIpi

-- exclui icm destacado
if @pm_FlgExcIcmCalPis = 1
  begin
    if @PTipNot = 'D' -- devolução de compra
      Set @WVlrBasPisCof = @WVlrBasPisCof - @PIcmPro
    else
      Set @WVlrBasPisCof = @WVlrBasPisCof - @PVlrIcm
  end
  
Exec PR_CalculaPisCofins @PCodEstabe, @PFlgCalPisCof, 'S', @em_CodTipLuc, @PDatEmi, @PCodCfo, @PCodRamAtv, @pr_CodClaFis, @pr_TipLisPis, @WVlrBasPisCof, 
                         @PCstPis output, @PVlrBasPis output, @PAlqPis output, @PVlrPis output,
                         @PCstCof output, @PVlrBasCof output, @PAlqCof output, @PVlrCof output, @PObsNf output
 
-- ICMS Deson reduz diretamente o valor total da nota fiscal
-- if @WPerIcmDesone = (@WAlqIcmExt-@WAlqIcmExtFcp) :  ISENTO ICMS: redução de BC = 100%  ?????

Commit Transaction
GO

SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PR_CalcTributItemSaidaECF]
@PCodEstab smallint,
@PSerNot varchar(3),
@PNumNot int,
@PCodPrd int,
@PCodLot varchar(20),
@PNumSeqIte smallint,
@PTipNot varchar(1),
@PDatEmi smalldatetime,
@PCodRegTri int,
@PTipLuc varchar(2),   
@PPerDst numeric(18,4),
@PCodOpe varchar(3),
@PPerDescontoCom numeric(18,8),
@PTipRetImp char(1),
@PFlgCalIcmSbt bit,
@PFlgCalIcmNor bit,
@PFlgCalRepIcm bit,
@PPrcUnitario numeric(18,4),
@PPrcVen numeric(18,4),
@PPrcFab numeric(18,4),
@PPrcMax numeric(18,4),
@PPrcRefFpb numeric(18,4),       -- Pr.Ref.Farmacia Popular
@PPrcUltEnt numeric(18,4),       -- Pr.Ult. Entrada 
@PQtdProduto int,
@PPerDesconto numeric(18,8),
@PVlrDscBonRat numeric(18,4),  -- deconto bonificado
@PVlrDspRat numeric(18,4),
@PVlrIpi numeric(18,4),
@PVlrDscRat numeric(18,4)

AS

SET NOCOUNT ON 

Begin Transaction

Declare @PPrcPon numeric(18,4) = 0

-- variaveis que serão gravadas na NFSIT
Declare @PVlrBasTri numeric(18,4),
        @PCodSt varchar(2),
        @PCodCsosn varchar(3),
        @PClaTri varchar(4),
        @PCodModBasCalIcm char(1),
        @PAlqIcm numeric(18,4),
        @PPerRedBasCalIcm numeric(7,4),
        @PBasIcmNor numeric(18,4),
        @PIcmNor numeric(18,4),
        @PBasRep numeric(18,4),
        @PPerRep numeric(7,4),
        @PVlrRep numeric(18,4),
        @PVlrPrdSub numeric(18,4),
        @PCodModBasCalIcmSbt char(1),
        @PAlqIcmSbt numeric(18,4),
        @PAlqAgrSbt numeric(18,4),
        @PPerRedBasCalIcmSbt numeric(7,4),
        @PBasSub numeric(18,4),
        @PVlrSub numeric(18,4),
        @PBasRes numeric(18,4),
        @PVlrRes numeric(18,4),
        @PVlrDst numeric(18,4),      -- desconto de tributacao (Pernambuco)
        @PBasRecSbt numeric(18,4),
        @PVlrRecSbt numeric(18,4),
        @PBasIcm numeric(18,4),      -- icms tributavel
        @PVlrIcm numeric(18,4),      -- icms tributavel
        @PVlrIse numeric(18,4),
        @PVlrOut numeric(18,4),
        @PBasIpi numeric(18,4),
        @PCstPis varchar(2),
        @PVlrBasPis numeric(18,4),
        @PAlqPis numeric(18,4),
        @PVlrPis numeric(18,4),
        @PCstCof varchar(2),
        @PVlrBasCof numeric(18,4),
        @PAlqCof numeric(18,4),
        @PVlrCof numeric(18,4),
        @PFlgBlqDsc bit,
        @PTipAux varchar(1),
        @PCodCfo smallint,
        @PVlrBasCalSubTriEntMed numeric(18,4),
        @PFlgUsaDebPresum bit,
        @PAlqDebPresum numeric(18,4),
        @PObsNf varchar(200)

-- variaveis de trabalho
Declare @WQtdLoop tinyint, 
        @WClaTriExt varchar(4),
        @WVlrTotIte numeric(18,4),  
        @WVlrRepBru numeric(18,4),
        @WVlrRepBruTab numeric(18,4),
        @WPerRepIcm numeric(7,4),
        @WVlrBasPrdSub numeric(18,4),
        @WVlrMinIcmSbtSaiRedDeb numeric(18,4),
        @WPerRedBasCalIcmExt numeric(7,4),
        @WAlqIcmExt numeric(18,4),
        @WCtrBasCalDeb varchar(1),
        @WCtrBasCalCre varchar(1),
        @WTipPrcBasDebSbt varchar(1),
        @WTipPrcBasCreSbt varchar(1),
        @WTipAgrDebSbt varchar(1),
        @WAlqAgrDeb numeric(18,4),
        @WPerRedBasCalDeb numeric(7,4),
        @WPerLimMinIcmSbtSaiRedDeb numeric(7,4),
        @WTipPrcLimMinBasCalIcmSbtSai varchar(1),
        @WAlqAgrLimMinBasCalIcmSbtSai numeric(18,4),
        @WTipCreSbt varchar(1),
        @WAlqDebSbt numeric(18,4),
        @WFlgImpSbtFnt bit,
        @WPerRedBasCalIcmInt numeric(7,4),
        @WAlqIcmInt numeric(18,4),
        @WLiq numeric(18,4),
        @WCre numeric(18,4),
        @WDebSbt numeric(18,4),
        @WBru numeric(18,4),
        @WBruTab numeric(18,4),
        @WCodCfoNor smallint,
        @WCodCfoSbt smallint,
        @WFlgCalPisCof bit,
		@WCreSbt numeric(18,4),
        @WVlrBasPisCof numeric(18,4),
        @WVlrBasCalMinSubTri numeric(18,4),
        @WFlgUsaDebPresum bit,
        @WAlqDebPresum numeric(18,4),
        @WUfDestin varchar(2)

Declare @pm_FlgIncIpiCalPis bit,
        @pm_FlgExcIcmCalPis bit,
		@em_FlgContriSubstituido bit,
        @em_DesEstado varchar(2)

Declare @pr_Ctrl_Origem varchar(1),
        @pr_Ctrl_Preco varchar(1),
        @pr_Desconto bit,
        @pr_FlgBlqInfPar bit,
        @pr_TipLisPis varchar(1),
        @pr_CodClaFis varchar(8),
        @pr_PrcFab numeric(18,4),
        @pr_PrcVen numeric(18,4),
        @pr_PrcMax numeric(18,4),
        @pr_PrcRefFpb numeric(18,4),
        @pr_PrcUltEnt numeric(18,4),
        @pr_PerDscUltEnt numeric(7,4),
        @pr_VlrBasCalSubTriEntMed numeric(18,4)
        
-- coloca campos de RTXCT na memoria
Declare @rt_ClaTriExt varchar(4),
        @rt_Tip_PrcBasDebSbt char(1),
        @rt_Ctrl_BasCalDebSai char(1),
        @rt_Alq_AgrDebSai numeric(18,4),
        @rt_Per_RedBasCalDebSai numeric(7,4),
        @rt_Per_LimMinIcmSbtSaiRedDeb numeric(7,4),        
        @rt_Tip_CreSbtSai char(1),
        @rt_Tip_PrcLimMinBasCalIcmSbtSai varchar(1),
        @rt_Alq_AgrLimMinBasCalIcmSbtSai numeric(18,4),        
        @rt_Alq_DebSbtSai numeric(18,4),
        @rt_Alq_IcmIntReg numeric(18,4),
        @rt_Per_RedBasCalIntReg numeric(7,4),
        @rt_Tip_PrcBasCreSbtSai char(1),
        @rt_Ctrl_BasCalCreSai char(1),
        @rt_Alq_IcmExtLoc numeric(18,4),
        @rt_Per_RedBasCalExtLoc numeric(7,4),
        @rt_C_PerRepIcmLoc numeric(7,4),
        
        @rt_Tip_PrcBasSbtEnt varchar(1),
        @rt_Ctrl_BasCalDebEnt varchar(1),
        @rt_Alq_AgrDebEnt numeric(18,4),
        @rt_Per_RedBasCalDebEnt numeric(7,4),
        @rt_Tip_CreSbtEnt varchar(1),
        @rt_Alq_DebSbtEnt numeric(18,4),
        @rt_Flg_ImpSbtFntEnt bit, 
        @rt_Alq_IcmIntLoc numeric(18,4),
        @rt_Per_RedBasCalIntLoc numeric(7,4),
        @rt_Tip_PrcBasCreSbtEnt varchar(1),
        @rt_Ctrl_BasCalCreEnt varchar(1),
        @rt_Alq_IcmExtReg numeric(18,4),
        @rt_Per_RedBasCalExtReg numeric(7,4),
        @rt_C_PerRepIcmReg numeric(7,4),
		@rt_Alq_DebPresum numeric(18,4),
        @rg_Flg_UsaDebPresum bit


-- coloca campos de tabelas na memoria
-- ESTAB
Select @em_FlgContriSubstituido = IsNull(Flg_ContriSubstituido,0),
       @em_DesEstado = Des_Estado
  From ESTAB
Where Cod_Estabe = @PCodEstab

-- PARAM
Select @pm_FlgIncIpiCalPis = IsNull(FlgIncIpiCalPis,0),
       @pm_FlgExcIcmCalPis = IsNull(FlgExcIcmCalPis,0)
  From PARAM
Where Cod_Estabe = @PCodEstab

Set @WUfDestin = IsNull((Select Estado 
                           From NFSCB
                          Where Cod_Estabe = @PCodEstab 
                            And Ser_Nota = @PSerNot 
                            And Num_Nota = @PNumNot),'')
if @WUfDestin = ''
  Set @WUfDestin = @em_DesEstado

Set @WQtdLoop = 1
Set @PClaTri = (Select Cod_ClaTri From PRXES Where Cod_Estabe = @PCodEstab And Cod_Produt = @PCodPrd)

LOOP_INICIO:

Set @PVlrBasTri = 0
Set @PCodSt = ''
Set @PCodCsosn = ''
Set @PCodModBasCalIcm = ''
Set @PAlqIcm = 0
Set @PPerRedBasCalIcm = 0
Set @PBasIcmNor = 0
Set @PIcmNor = 0
Set @PPerRep = 0
Set @PBasRep = 0
Set @PVlrRep = 0
Set @PVlrPrdSub = 0
Set @PCodModBasCalIcmSbt = ''
Set @PAlqIcmSbt = 0
Set @PAlqAgrSbt = 0
Set @PPerRedBasCalIcmSbt = 0
Set @PBasSub = 0
Set @PVlrSub = 0
Set @PBasRes = 0
Set @PVlrRes = 0
Set @PVlrDst = 0
Set @PBasRecSbt = 0
Set @PVlrRecSbt = 0
Set @PBasIcm = 0
Set @PVlrIcm = 0
Set @PVlrIse = 0
Set @PVlrOut = 0
Set @PBasIpi = 0
Set @PCstPis = ''
Set @PVlrBasPis = 0
Set @PAlqPis = 0
Set @PVlrPis = 0
Set @PCstCof = ''
Set @PVlrBasCof = 0
Set @PAlqCof = 0
Set @PVlrCof = 0
Set @PFlgUsaDebPresum = 0
Set @PAlqDebPresum = 0
Set @PObsNf = ''

Set @PFlgBlqDsc = 0
Set @PTipAux = null
Set @WVlrRepBru = 0
Set @WVlrRepBruTab = 0
Set @WVlrBasPrdSub = 0



Select @PCodSt = IsNull(rx.Cod_ImpNotSai,''),
       @PCodCsosn = IsNull(rx.Cod_CSOSNSai,''),
       @rt_ClaTriExt = IsNull(rx.Cod_ClaTriExt,''),
       @rt_Tip_PrcBasDebSbt = IsNull(rx.Tip_PrcBasDebSbt,''),
       @rt_Ctrl_BasCalDebSai = IsNull(rx.Ctrl_BasCalDebSai,''),
       @rt_Alq_AgrDebSai = Isnull(rx.Alq_AgrDebSai,0),
       @rt_Per_RedBasCalDebSai = Isnull(rx.Per_RedBasCalDebSai,0),
       @rt_Per_LimMinIcmSbtSaiRedDeb = IsNull(rx.Per_LimMinIcmSbtSaiRedDeb,0),
	   @rt_Tip_PrcLimMinBasCalIcmSbtSai = IsNull(Tip_PrcLimMinBasCalIcmSbtSai,''),
	   @rt_Alq_AgrLimMinBasCalIcmSbtSai = IsNull(Alq_AgrLimMinBasCalIcmSbtSai,0),
       @rt_Tip_CreSbtSai = Isnull(rx.Tip_CreSbtSai,''),
       @rt_Alq_DebSbtSai = Isnull(rx.Alq_DebSbtSai,0),
       @rt_Alq_IcmIntReg = Isnull(rx.Alq_IcmIntReg,0),
       @rt_Per_RedBasCalIntReg = Isnull(rx.Per_RedBasCalIntReg,0),
       @rt_Tip_PrcBasCreSbtSai = IsNull(rx.Tip_PrcBasCreSbtSai,''),
       @rt_Ctrl_BasCalCreSai = IsNull(rx.Ctrl_BasCalCreSai,''),
       @rt_Alq_IcmExtLoc = Isnull(rx.Alq_IcmExtLoc,0),
       @rt_Per_RedBasCalExtLoc = Isnull(rx.Per_RedBasCalExtLoc,0),
       @rt_C_PerRepIcmLoc = Isnull(rx.C_PerRepIcmLoc,0),
       
       @rt_Tip_PrcBasSbtEnt = IsNull(rx.Tip_PrcBasSbtEnt,''),
       @rt_Ctrl_BasCalDebEnt  = IsNull(rx.Ctrl_BasCalDebEnt,''),
       @rt_Alq_AgrDebEnt = Isnull(rx.Alq_AgrDebEnt,0),
       @rt_Per_RedBasCalDebEnt = Isnull(rx.Per_RedBasCalDebEnt,0),
       @rt_Tip_CreSbtEnt = IsNull(rx.Tip_CreSbtEnt,''),
       @rt_Alq_DebSbtEnt = Isnull(rx.Alq_DebSbtEnt,0),
       @rt_Flg_ImpSbtFntEnt = IsNull(rx.Flg_ImpSbtFntEnt,0),
       @rt_Alq_IcmIntLoc = Isnull(rx.Alq_IcmIntLoc,0),
       @rt_Per_RedBasCalIntLoc = Isnull(rx.Per_RedBasCalIntLoc,0),
       @rt_Tip_PrcBasCreSbtEnt = IsNull(rx.Tip_PrcBasCreSbtEnt,''),
       @rt_Ctrl_BasCalCreEnt = IsNull(rx.Ctrl_BasCalCreEnt,''),
       @rt_Alq_IcmExtReg = Isnull(rx.Alq_IcmExtReg,0),
       @rt_Per_RedBasCalExtReg = Isnull(rx.Per_RedBasCalExtReg,0),
       @rt_C_PerRepIcmReg = Isnull(rx.C_PerRepIcmReg,0),
       @rg_Flg_UsaDebPresum = IsNull(rg.Flg_UsaDebPresum,0),
       @rt_Alq_DebPresum = Case 
	                         When IsNull(rg.Flg_UsaDebPresum,0) = 1 then IsNull(rx.Alq_IcmPresumLoc,0) 
							 Else 0 
                           End    
  From RTXCT rx
       Inner Join RGTRI rg on rx.Cod_RegTri = rg.Cod_RegTri
Where rx.Cod_RegTri = @PCodRegTri
and  rx.Cod_ClaTri = @PClaTri

-- CFOP
Select @WCodCfoNor = Isnull(Cod_CfoNorInt,0),       
       @WCodCfoSbt = IsNull(Cod_CfoSbtInt,0),
       @WFlgCalPisCof = IsNull(Flg_CalPisCof,0)
  From TPOPE
Where Cod_Ope = @PCodOpe

-- tipo da nota diferente de devolucao
if @PTipNot <> 'D'
  begin
    -- vendas, outras saidas
	Set @WClaTriExt = @rt_ClaTriExt
    Set @WTipPrcBasDebSbt = @rt_Tip_PrcBasDebSbt
    Set @WCtrBasCalDeb = @rt_Ctrl_BasCalDebSai
    Set @WAlqAgrDeb = @rt_Alq_AgrDebSai
    Set @WPerRedBasCalDeb = @rt_Per_RedBasCalDebSai
    Set @WPerLimMinIcmSbtSaiRedDeb = @rt_Per_LimMinIcmSbtSaiRedDeb
    Set @WTipPrcLimMinBasCalIcmSbtSai = @rt_Tip_PrcLimMinBasCalIcmSbtSai
    Set @WAlqAgrLimMinBasCalIcmSbtSai = @rt_Alq_AgrLimMinBasCalIcmSbtSai     
    Set @WTipCreSbt = @rt_Tip_CreSbtSai
    Set @WAlqDebSbt = @rt_Alq_DebSbtSai
    Set @WFlgImpSbtFnt = 1
    Set @WAlqIcmInt = @rt_Alq_IcmIntReg
    Set @WPerRedBasCalIcmInt = @rt_Per_RedBasCalIntReg
    Set @WTipPrcBasCreSbt = @rt_Tip_PrcBasCreSbtSai
    Set @WCtrBasCalCre = @rt_Ctrl_BasCalCreSai
    Set @WAlqIcmExt = @rt_Alq_IcmExtLoc
    Set @WPerRedBasCalIcmExt = @rt_Per_RedBasCalExtLoc
    Set @WPerRepIcm = @rt_C_PerRepIcmLoc
    Set @WFlgUsaDebPresum = @rg_Flg_UsaDebPresum
    Set @WAlqDebPresum = @rt_Alq_DebPresum
  end
else
  begin
    -- devolucao
	Set @WClaTriExt = ''
    Set @WTipPrcBasDebSbt = @rt_Tip_PrcBasSbtEnt
    Set @WCtrBasCalDeb = @rt_Ctrl_BasCalDebEnt
    Set @WAlqAgrDeb = @rt_Alq_AgrDebEnt
    Set @WPerRedBasCalDeb = @rt_Per_RedBasCalDebEnt
    Set @WPerLimMinIcmSbtSaiRedDeb = 0
    Set @WTipPrcLimMinBasCalIcmSbtSai = ''
    Set @WAlqAgrLimMinBasCalIcmSbtSai = 0
    Set @WTipCreSbt = @rt_Tip_CreSbtEnt
    Set @WAlqDebSbt = @rt_Alq_DebSbtEnt
    Set @WFlgImpSbtFnt = @rt_Flg_ImpSbtFntEnt
    Set @WAlqIcmInt = @rt_Alq_IcmIntLoc
    Set @WPerRedBasCalIcmInt = @rt_Per_RedBasCalIntLoc
    Set @WTipPrcBasCreSbt = @rt_Tip_PrcBasCreSbtEnt
    Set @WCtrBasCalCre = @rt_Ctrl_BasCalCreEnt
    Set @WAlqIcmExt = @rt_Alq_IcmExtReg
    Set @WPerRedBasCalIcmExt = @rt_Per_RedBasCalExtReg
    Set @WPerRepIcm = @rt_C_PerRepIcmReg
    Set @WFlgUsaDebPresum = 0
    Set @WAlqDebPresum = 0
  end

-- coloca campo de PRODU na memoria
Select @pr_Ctrl_Origem = IsNull(p.Cod_OriMer,'0'),
       @pr_Ctrl_Preco = pr.Ctrl_Preco,
       @pr_Desconto = Isnull(p.Flg_BlqDsc,0),
       @pr_FlgBlqInfPar = Isnull(p.Flg_BlqInfPar,0),
       @pr_TipLisPis = pr.Tip_LisPis,
       @pr_CodClaFis = Substring(Ltrim(Rtrim(pr.Cod_ClaFis)),1,8),
       @pr_PrcVen = Isnull(p.Prc_Venda,0),
       @pr_PrcRefFpb = Isnull(pr.Prc_RefFpb,0),
       @pr_PrcUltEnt = Isnull(p.Prc_UltEnt,0),
       @pr_PerDscUltEnt = Isnull(p.Per_DscUltEnt,0),
	   @pr_VlrBasCalSubTriEntMed = IsNull(p.Vlr_BasCalSubTriEntMed,0),
       @pr_PrcFab = Case
                      When (Round(@WAlqIcmInt,2) = 12.00) and (IsNull(pr.Prc_Fabric12,0)  > 0) Then IsNull(pr.Prc_Fabric12,0)
                      When (Round(@WAlqIcmInt,2) = 17.00) and (IsNull(pr.Prc_Fabric17,0)  > 0) Then IsNull(pr.Prc_Fabric17,0)
                      When (Round(@WAlqIcmInt,2) = 17.50) and (IsNull(pr.Prc_Fabric175,0) > 0) Then IsNull(pr.Prc_Fabric175,0)
                      When (Round(@WAlqIcmInt,2) = 18.00) and (IsNull(pr.Prc_Fabric18,0)  > 0) Then IsNull(pr.Prc_Fabric18,0)
                      When (Round(@WAlqIcmInt,2) = 19.00) and (IsNull(pr.Prc_Fabric19,0)  > 0) Then IsNull(pr.Prc_Fabric19,0)
                      When (Round(@WAlqIcmInt,2) = 19.50) and (IsNull(pr.Prc_Fabric195,0) > 0) Then IsNull(pr.Prc_Fabric195,0)
                      When (Round(@WAlqIcmInt,2) = 20.00) and (IsNull(pr.Prc_Fabric20,0)  > 0) Then IsNull(pr.Prc_Fabric20,0)
                      When (Round(@WAlqIcmInt,2) = 20.50) and (IsNull(pr.Prc_Fabric205,0) > 0) Then IsNull(pr.Prc_Fabric205,0)
                      When (Round(@WAlqIcmInt,2) = 21.00) and (IsNull(pr.Prc_Fabric21,0)  > 0) Then IsNull(pr.Prc_Fabric21,0)
                      When (Round(@WAlqIcmInt,2) = 22.00) and (IsNull(pr.Prc_Fabric22,0)  > 0) Then IsNull(pr.Prc_Fabric22,0)
                      Else Isnull(p.Prc_Fabric,0)
                    End,
       @pr_PrcMax = Case
                      When (Round(@WAlqIcmInt,2) = 12.00) and (IsNull(pr.Prc_MaxCon12,0)  > 0) Then IsNull(pr.Prc_MaxCon12,0)
                      When (Round(@WAlqIcmInt,2) = 17.00) and (IsNull(pr.Prc_MaxCon17,0)  > 0) Then IsNull(pr.Prc_MaxCon17,0)
                      When (Round(@WAlqIcmInt,2) = 17.50) and (IsNull(pr.Prc_MaxCon175,0) > 0) Then IsNull(pr.Prc_MaxCon175,0)
                      When (Round(@WAlqIcmInt,2) = 18.00) and (IsNull(pr.Prc_MaxCon18,0)  > 0) Then IsNull(pr.Prc_MaxCon18,0)
                      When (Round(@WAlqIcmInt,2) = 19.00) and (IsNull(pr.Prc_MaxCon19,0)  > 0) Then IsNull(pr.Prc_MaxCon19,0)
                      When (Round(@WAlqIcmInt,2) = 19.50) and (IsNull(pr.Prc_MaxCon195,0) > 0) Then IsNull(pr.Prc_MaxCon195,0)
                      When (Round(@WAlqIcmInt,2) = 20.00) and (IsNull(pr.Prc_MaxCon20,0)  > 0) Then IsNull(pr.Prc_MaxCon20,0)
                      When (Round(@WAlqIcmInt,2) = 20.50) and (IsNull(pr.Prc_MaxCon205,0) > 0) Then IsNull(pr.Prc_MaxCon205,0)
                      When (Round(@WAlqIcmInt,2) = 21.00) and (IsNull(pr.Prc_MaxCon21,0)  > 0) Then IsNull(pr.Prc_MaxCon21,0)
                      When (Round(@WAlqIcmInt,2) = 22.00) and (IsNull(pr.Prc_MaxCon22,0)  > 0) Then IsNull(pr.Prc_MaxCon22,0)
                      Else Isnull(p.Prc_MaxCon,0)
                    End
  From PRXES p Inner Join PRODU pr on p.Cod_Produt = pr.Codigo
Where p.Cod_Estabe = @PCodEstab
And p.Cod_Produt = @PCodPrd

if @PPrcVen = 0
  Set @PPrcVen = @pr_PrcVen
if @PPrcRefFpb = 0
  Set @PPrcRefFpb = @pr_PrcRefFpb
if @PPrcFab = 0
  Set @PPrcFab = @pr_PrcFab
if @PPrcMax = 0
  Set @PPrcMax = @pr_PrcMax
  
if @PPrcFab <> @pr_PrcFab 
  Set @PPrcFab = @pr_PrcFab
if @PPrcMax <> @pr_PrcMax  
  Set @PPrcMax = @pr_PrcMax
  
Set @PVlrBasCalSubTriEntMed = @pr_VlrBasCalSubTriEntMed

if @PPrcPon = 0
  Set @PPrcPon = (Select dbo.FN_PrcMedPonFin (@WUfDestin,@PCodPrd,@PDatEmi))

-- verifica se utiliza classificação tributária extra (uma unica vez)
if (@PFlgCalIcmSbt = 1) and 
   (((@WTipPrcBasDebSbt = 'D') and (@PPrcPon = 0)) or
    ((@WTipPrcBasDebSbt = 'M') and (@PPrcMax = 0))) and
   (@WClaTriExt <> '') and
   (@PClaTri <> @WClaTriExt) and
   (@WQtdLoop = 1)
  begin
    Set @WQtdLoop = @WQtdLoop + 1
    Set @PClaTri = @WClaTriExt
    GOTO LOOP_INICIO
  end


-- calcula repasse para futuros calculos
-- repasse de ICMS se houver diferenca de aliquotas
-- e somente cipados ou liberados c/ repasse
Set @WVlrTotIte = Round(@PPrcUnitario * @PQtdProduto * (1-@PPerDesconto/100),2)

Set @PPerRep = @WPerRepIcm
 
if (@PFlgCalIcmNor = 1) or (@PFlgCalIcmSbt = 1)
  if (@PFlgCalRepIcm = 1) and (@PPerRep <> 0) and (@pr_Ctrl_Preco <> 'L')
    begin
      -- repasse liquido
      Set @PBasRep = @WVlrTotIte + @PVlrDspRat
      Set @PVlrRep = @PBasRep * @PPerRep / 100
      -- repasse bruto
      Set @WVlrRepBru = Round(@PPrcUnitario * @PQtdProduto * @PPerRep / 100,2)
      Set @WVlrRepBruTab = Round(@PPrcVen * @PQtdProduto * @PPerRep / 100,2)
      if @PVlrRep = 0
        Set @PBasRep = 0
    end

-- valor liquido do item
Set @WLiq = @WVlrTotIte - @PVlrRep
                        
-- desconto cabecalho
Set @PFlgBlqDsc = @pr_Desconto
                        
Set @WLiq =  @WLiq - @PVlrDscRat - @PVlrDscBonRat 
                        
-- o calculo abaixo devera ser excluido com a despesa estiver realmente rateada no item
Set @WLiq = Round(@WLiq + @PVlrDspRat,2)

if @PVlrIpi > 0
  Set @PBasIpi = @WLiq

-- registra icms proprio, icms tributavel da operacao se DEB/CRE ou SUB.TRIB.
Set @WCre = 0
Set @PPerRedBasCalIcm = @WPerRedBasCalIcmExt
Set @PBasIcmNor = Round(@WLiq * (1 - @PPerRedBasCalIcm/100),2)
Set @PAlqIcm = @WAlqIcmExt
Set @PIcmNor = @WLiq * (1 - @PPerRedBasCalIcm/100) * @PAlqIcm / 100
if @PIcmNor = 0
  Set @PBasIcmNor = 0
  
if (@PFlgCalIcmNor = 1) or (@PFlgCalIcmSbt = 1)
  begin
    -- credito com reducao da base de calculo
    Set @WCre = @PIcmNor
    if @WCre > 0
      Set @PCodModBasCalIcm = '3'  -- ICMS sobre Valor da operação
  end

-- calcula icms tributavel (debito/credito)
if (@PFlgCalIcmNor = 1) and (@WTipPrcBasDebSbt = 'X')   -- nao eh subst.tributaria
  begin
    Set @PBasIcm = @PBasIcmNor
    Set @PVlrIcm = @PIcmNor
    Set @PFlgUsaDebPresum = @WFlgUsaDebPresum
    Set @PAlqDebPresum = @WAlqDebPresum
  end

-- ver se eh ST sem retencao
if @WTipPrcBasDebSbt = 'O'
  begin
    Set @PVlrPrdSub = 0
    Set @PAlqIcmSbt = 0
    Set @PAlqAgrSbt = 0
    Set @PPerRedBasCalIcmSbt = 0
    Set @PBasSub = 0
    Set @PVlrSub = 0
--    Set @PBasIcmNor = 0
--    Set @PIcmNor = 0 
    Set @PBasIcm = 0
    Set @PVlrIcm = 0 
    Set @PVlrIse = 0
    Set @PVlrOut = @WLiq
    Set @PCodModBasCalIcm = ''
    Set @PCodModBasCalIcmSbt = ''
    Set @PFlgUsaDebPresum = @WFlgUsaDebPresum
    Set @PAlqDebPresum = @WAlqDebPresum
end
  
-- Calcula Substituicao Tributaria
if (@PFlgCalIcmSbt = 1) and (@WTipPrcBasDebSbt <> 'X') and (@WTipPrcBasDebSbt <> 'O')
  begin
    -- debito presumido p/ uso no calculo de rentabilidade
    Set @PFlgUsaDebPresum = 0
    Set @PAlqDebPresum = 0

    -- valor bruto do item
    Set @WBru = Round(@PPrcUnitario * @PQtdProduto - @WVlrRepBru + @PVlrDspRat,2)
    
    if @WCtrBasCalDeb = 'B'  -- pelo vlr. bruto
      begin
        if @WTipPrcBasDebSbt = 'D'           -- utiliza PMMF do cadastro
          Set @WVlrBasPrdSub = @PPrcPon * @PQtdProduto
        else
        if @WTipPrcBasDebSbt = 'M'           -- utiliza P.M.C. do cadastro
          Set @WVlrBasPrdSub = @PPrcMax * @PQtdProduto
        else
        if @WTipPrcBasDebSbt = 'F'            -- utiliza preco fabrica do cadastro
          Set @WVlrBasPrdSub = @PPrcFab * @PQtdProduto
        else
        if @WTipPrcBasDebSbt = 'P'            -- utiliza preco ref fcia popular
          Set @WVlrBasPrdSub = @PPrcRefFpb * @PQtdProduto
        else
        if @WTipPrcBasDebSbt = 'V'            -- utiliza preco venda do cadastro
          Set @WVlrBasPrdSub = @PPrcVen * @PQtdProduto - @WVlrRepBruTab
        else
        if @WTipPrcBasDebSbt = 'C'            -- utiliza preco compra do cadastro
          Set @WVlrBasPrdSub = @PPrcUltEnt * @PQtdProduto
        else
          Set @WVlrBasPrdSub = @WBru   --/ transacao
      end
    else
      Set @WVlrBasPrdSub = @WLiq
          
    -- Valor base da ST: agregacao, reducao e aliquota 
    Set @PAlqAgrSbt = @WAlqAgrDeb
    Set @PPerRedBasCalIcmSbt = @WPerRedBasCalDeb

    Set @PVlrPrdSub = @WVlrBasPrdSub * (1 - @PPerRedBasCalIcmSbt/100)
    Set @PBasSub = @PVlrPrdSub * (1 + @PAlqAgrSbt/100)

    -- verifica limitador B.C.ST
    Set @WVlrBasCalMinSubTri = 0
    if @WTipPrcLimMinBasCalIcmSbtSai = 'E'
      begin
        -- média da B.C. de Entrada + Agreg.
        Set @WVlrBasCalMinSubTri = Round(@PVlrBasCalSubTriEntMed * @PQtdProduto * (1 + @WAlqAgrLimMinBasCalIcmSbtSai/100),2)
      end
    if @PBasSub < @WVlrBasCalMinSubTri
      Set @PBasSub = @WVlrBasCalMinSubTri

    -- ver se utiliza no calculo da ST % fixo sobre preco do produto
    if @WTipCreSbt = 'F'
      begin
        Set @PAlqIcmSbt = @WAlqDebSbt
        Set @PVlrSub = @PBasSub * @PAlqIcmSbt / 100
        if @PAlqAgrSbt = 0
          Set @PCodModBasCalIcmSbt = '0'  -- preco tabela ou maximo sugerido
        else
          Set @PCodModBasCalIcmSbt = '4'
      end
    else
      -- calcula subst.tributaria com agregacao      
      begin
        -- debito com red. base de calculo icms
        Set @PAlqIcmSbt = @WAlqIcmInt
        Set @WDebSbt = @PBasSub * @PAlqIcmSbt / 100   

        -- desconto comercial concedido por subst.trib.
        if @PPerDst > 0
          begin
            Set @PVlrDst = @PVlrPrdSub * @PPerDst / 100
            Set @WLiq = Round(@WLiq - @PVlrDst,2)
            Set @WCre = @WLiq * (1 - @PPerRedBasCalIcm/100) * @PAlqIcm / 100
            Set @PBasIcmNor = Round(@WLiq * (1 - @PPerRedBasCalIcm/100),2)
            Set @PIcmNor = @WCre
            if @PIcmNor  = 0
              Set @PBasIcmNor = 0
            else
              Set @PCodModBasCalIcm = '3'  -- ICMS sobre Valor da operação
          end

        -- credito
        if @WCtrBasCalCre = 'B'         -- credito pelo vlr.bruto
          begin
            if @WTipPrcBasCreSbt = 'F'      -- utiliza preco fabrica do cadastro
              Set @WCreSbt = @PPrcFab * @PQtdProduto
            else
            if @WTipPrcBasCreSbt = 'V'     -- utiliza preco venda do cadastro
              Set @WCreSbt = @PPrcVen * @PQtdProduto - @WVlrRepBruTab
            else
              Set @WCreSbt = @WBru              -- transacao
                -- credito com red.base de calculo
             Set @WCreSbt = @WCreSbt * (1 - @PPerRedBasCalIcm/100) * @PAlqIcm / 100
          end
        else
          Set @WCreSbt = @WCre

        -- calcula icm subst.
        Set @PVlrSub = @WDebSbt - @WCreSbt

--        if (@WTipPrcBasDebSbt = 'M') or (@WTipPrcBasDebSbt = 'P')
        if @PAlqAgrSbt = 0
          Set @PCodModBasCalIcmSbt = '0'  -- preco tabela ou maximo sugerido
        else
          Set @PCodModBasCalIcmSbt = '4'  -- Margem Valor Agregado (%)
            
      end  -- calcula subst.tributaria com agregacao
          
    -- verifica limitador ST
    Set @WVlrMinIcmSbtSaiRedDeb = 0
    if (@PPerRedBasCalIcmSbt > 0) and (@WPerLimMinIcmSbtSaiRedDeb > 0) 
      Set @WVlrMinIcmSbtSaiRedDeb = @PBasSub*@WPerLimMinIcmSbtSaiRedDeb/100

    if (@PVlrSub > 0) and (@PVlrSub < @WVlrMinIcmSbtSaiRedDeb)
      begin
        -- desconsidera reducao na base de calculo
        Set @PPerRedBasCalIcmSbt = 0
        Set @PVlrPrdSub = @WVlrBasPrdSub
        Set @PBasSub = @PVlrPrdSub * (1 + @PAlqAgrSbt/100)
        Set @WDebSbt = @PBasSub * @PAlqIcmSbt / 100   
        Set @PVlrSub = @WDebSbt - @WCreSbt
      end
            
    if Round(@PVlrSub,2) <= 0
      begin
--        Set @PAlqIcmSbt = 0
--        Set @PAlqAgrSbt = 0
--        Set @PPerRedBasCalIcmSbt = 0
--        Set @PBasSub = 0
        Set @PVlrSub = 0
--        Set @PVlrPrdSub = 0
--        Set @PBasIcm = 0
--        Set @PVlrIcm = 0
--        Set @PVlrIse = 0
--        Set @PVlrOut = 0
--        Set @PCodModBasCalIcmSbt = ''

        -- CST sujeitas a ST 10;30;70;
        if Charindex(@PCodSt,';10;70;') > 0 
          begin
            Set @PBasIcm = @PBasIcmNor
            Set @PVlrIcm = @PIcmNor 
--            if @PCodSt = '70'
--              Set @PCodSt = '20' 
--            else
--              Set @PCodSt = '00' 
          end
        else
          begin
            Set @PVlrOut = @PBasIcmNor
--            if @PCodSt = '30'
--              Set @PCodSt = '40' 
          end
      end  -- if @PVlrSub <= 0
          
  end  -- fim Calculo Substituicao Tributaria
  
-- se a ST nao for retida na fonte
if (@WFlgImpSbtFnt = 0) and (@PVlrSub > 0)
  begin
    Set @PAlqIcmSbt = 0
    Set @PAlqAgrSbt = 0
    Set @PPerRedBasCalIcmSbt = 0
    Set @PBasSub = 0
    Set @PVlrSub = 0
    Set @PVlrPrdSub = 0

    if @PPerRedBasCalIcm > 0 
      Set @PCodSt = '20' 
    else
      Set @PCodSt = '00' 
    Set @PBasIcm = @PBasIcmNor
    Set @PVlrIcm = @PIcmNor 
  end

-- nao houve tributacao qualquer
-- if (@PFlgCalIcmNor = 0) and (@PFlgCalIcmSbt = 0)
--   begin
--     Set @PVlrOut = @PBasIcmNor
--     Set @PCodSt = '41'
--    end Albani Comentou: Para obedecer o que está na tributação do produto
  
-- CST sujeitas a ST 10;30;70;
if (@PVlrSub = 0) and (Charindex(@PCodSt,';10;30;70;') > 0) 
  if Charindex(@PCodSt,';10;70;') > 0 
    begin
      Set @PBasIcm = @PBasIcmNor
      Set @PVlrIcm = @PIcmNor 
      if @PBasSub = 0
        if @PCodSt = '70'
          Set @PCodSt = '20' 
        else
          Set @PCodSt = '00' 
    end
  else
    begin
      Set @PVlrOut = @PBasIcmNor
      if @PBasSub = 0
        if @PCodSt = '30'
          Set @PCodSt = '40' 
    end

--ajusta ressarcimento ST
if (@PCodSt = '60') and (@PVlrSub > 0)
  begin
    Set @PBasRes = @PBasSub
    Set @PVlrRes = @PVlrSub
    Set @PBasSub = 0 
    Set @PVlrSub = 0 
  end

-- exige tributacao icm
if Charindex(@PCodSt,';00;10;20;51;70;90;') > 0  -- if Charindex(@PCodSt,';00;10;20;70;90;') > 0 
  begin
    Set @PBasIcm = @PBasIcmNor
    Set @PVlrIcm = @PIcmNor 
  end
  
-- nao exige tributacao icm
if Charindex(@PCodSt,';30;40;41;50;60;') > 0   -- if Charindex(@PCodSt,';30;40;41;50;51;60;') > 0 
  begin
    Set @PBasIcm = 0
    Set @PVlrIcm = 0
  end
  
if (@PVlrIse = 0) and (@PVlrSub = 0) and (@PVlrRes = 0) and (@PVlrIcm = 0) and (@PVlrOut = 0)
  if (@PFlgCalIcmNor = 1) or (@PFlgCalIcmSbt = 1)
    Set @PVlrIse = @WLiq
  else
    Set @PVlrOut = @WLiq

if Round(@PVlrIse,2) > 0
  if @PAlqIcm = 0
    begin
      Set @PBasIcmNor = 0
      Set @PIcmNor = 0
      Set @PBasIcm = 0
      Set @PVlrIcm = 0 
      Set @PVlrOut = 0
      Set @PCodSt = '40'
    end

-- ICM presumido
if (@PVlrIcm > 0) and (@PFlgUsaDebPresum = 0)
  begin
    Set @PFlgUsaDebPresum = @WFlgUsaDebPresum
    Set @PAlqDebPresum = @WAlqDebPresum
  end

Set @PVlrOut = Round(@WLiq - @PVlrIse - @PBasIcm,2)
if @PVlrOut < 0
  Set @PVlrOut = 0
if @PVlrOut > @WLiq
  Set @PVlrOut = @WLiq 

-- ajusta Cod.Modalidade base de calculo icm sbt
if @PVlrSub > 0
  if @PAlqAgrSbt = 0
    Set @PCodModBasCalIcmSbt = '0'  -- preco tabela ou maximo sugerido
  else
    Set @PCodModBasCalIcmSbt = '4'
else
  Set @PCodModBasCalIcmSbt = ''

if Charindex(@PCodSt,';30;40;41;50;60;') > 0 
  Set @PCodModBasCalIcm = ''
if Charindex(@PCodSt,';00;20;40;41;50;51;60;') > 0 
  Set @PCodModBasCalIcmSbt = ''
  
Set @PVlrBasTri = @WLiq

if Charindex(@PCodSt,';00;40;41;') > 0
  Set @PCodCfo = @WCodCfoNor
else if Charindex(@PCodSt,';60;') > 0
  Set @PCodCfo = @WCodCfoSbt
else
  Set @PCodCfo = @WCodCfoNor
  
-- pis/cofins
Set @WVlrBasPisCof = @WLiq

-- ressarcimento
if @PVlrRes > 0
  Set @WVlrBasPisCof = Round(@WLiq+@PVlrRes,2)

-- ipi
if @pm_FlgIncIpiCalPis = 1  
  Set @WVlrBasPisCof = @WVlrBasPisCof + @PVlrIpi
  
-- exclui icm destacado
if @pm_FlgExcIcmCalPis = 1
  Set @WVlrBasPisCof = @WVlrBasPisCof - @PVlrIcm

Exec PR_CalculaPisCofins @PCodEstab, @WFlgCalPisCof, 'S', @PTipLuc, @PDatEmi, @PCodCfo, 0, @pr_CodClaFis, @pr_TipLisPis, @WVlrBasPisCof, 
                         @PCstPis output, @PVlrBasPis output, @PAlqPis output, @PVlrPis output,
                         @PCstCof output, @PVlrBasCof output, @PAlqCof output, @PVlrCof output, @PObsNf output

-- grava valores em NFSIT
Set @pr_FlgBlqInfPar = 0
Update NFSIT
   Set Tip_Aux = @pr_TipLisPis,
       Flg_BlqDsc = @PFlgBlqDsc,
       Flg_BlqInfPar = @pr_FlgBlqInfPar,
       Cod_Cfo = @PCodCfo,
       Ctrl_Tributacao = @PCodSt,
       Cod_CSOSN = @PCodCsosn,
       Cod_Tribut = @pr_Ctrl_Origem+@PCodSt,
       Cod_ClaTri = @PClaTri,

       Prc_TabBru = @PPrcVen,
       Prc_Fabric = @PPrcFab,
       Prc_PonFin = @PPrcPon,
       Prc_MaxCon = @PPrcMax,
       Prc_RefFpb = @PPrcRefFpb,
       Prc_LiqUltEnt = @PPrcUltEnt,
       Vlr_BasCalSubTriEntMed = @PVlrBasCalSubTriEntMed, 

       Vlr_BasTri = @PVlrBasTri,
       Cod_ModBasCalIcm = @PCodModBasCalIcm,

       Alq_Icms = @PAlqIcm,
       Per_RedBasCalIcm = @PPerRedBasCalIcm,
       Vlr_BasIcmsNor = Round(@PBasIcmNor,2),
       Vlr_IcmsNor = @PIcmNor,
       Flg_UsaDebPresum = @PFlgUsaDebPresum,
       Alq_IcmPresum = @PAlqDebPresum,

       Vlr_BasRepIcms = Round(@PBasRep,2),
       Per_RepIcms = @PPerRep,
       Vlr_RepIcms = @PVlrRep,

       Vlr_PrdSubTri = Round(@PVlrPrdSub,2),
       Cod_ModBasCalIcmSbt = @PCodModBasCalIcmSbt,
       Alq_IcmSbt = @PAlqIcmSbt,
       Alq_AgrSbt = @PAlqAgrSbt,
       Per_RedBasCalIcmSbt = @PPerRedBasCalIcmSbt,
       Vlr_BasSubsTrib = Round(@PBasSub,2),
       Vlr_SubsTrib = @PVlrSub,
       Vlr_BasSbtRes = Round(@PBasRes,2),
       Vlr_SbtRes = @PVlrRes,
       Vlr_DscTri = @PVlrDst,
       Vlr_BasRecSbt = Round(@PBasRecSbt,2),
       Vlr_RecSbt = @PVlrRecSbt,
       Vlr_BasIcmsTri = Round(@PBasIcm,2),
       Vlr_IcmsTri = @PVlrIcm,
       Vlr_Isento = Round(@PVlrIse,2),
       Vlr_Outros = Round(@PVlrOut,2),
       Vlr_BasIpi = Round(@PBasIpi,2),

       CST_Pis = @PCstPis, 
       Vlr_BasPis = @PVlrBasPis, 
       Alq_Pis = @PAlqPis, 
       Vlr_Pis = @PVlrPis, 
       CST_Cofins = @PCstCof, 
       Vlr_BasCofins = @PVlrBasCof, 
       Alq_Cofins = @PAlqCof, 
       Vlr_Cofins = @PVlrCof,
       Obs_Nf = @PObsNf

 Where Cod_Estabe = @PCodEstab 
   And Ser_Nota = @PSerNot 
   And Num_Nota = @PNumNot And Cod_Produto = @PCodPrd 
   And Cod_Lote = @PCodLot And Num_SeqIte = @PNumSeqIte

Update NFSIT
   Set Vlr_LiqVenIte = Round(Qtd_Produto * Prc_Unitario*(1-Per_Desconto/100),2) -- IsNull(Vlr_TotItem,0) 
                     - IsNull(Vlr_RepIcms,0) - Isnull(Vlr_DescRateado,0) - IsNull(Vlr_DscBonRat,0) - IsNull(Vlr_DscTri,0),

       Vlr_LiqItem = Round(Qtd_Produto * Prc_Unitario*(1-Per_Desconto/100),2) --IsNull(Vlr_TotItem,0) 
                   - IsNull(Vlr_RepIcms,0) - Isnull(Vlr_DescRateado,0) - IsNull(Vlr_DscBonRat,0) - IsNull(Vlr_DscTri,0)
                   + IsNull(Vlr_SubsTrib,0) + IsNull(Vlr_SbtRes,0) + IsNull(Vlr_RecSbt,0) + IsNull(Vlr_Ipi,0) + Isnull(Vlr_DespRateada,0)  + Isnull(Vlr_DspExt,0)
 Where Cod_Estabe = @PCodEstab 
   And Ser_Nota = @PSerNot 
   And Num_Nota = @PNumNot And Cod_Produto = @PCodPrd 
   And Cod_Lote = @PCodLot And Num_SeqIte = @PNumSeqIte

if (@PTipRetImp = 'R') and (@PVlrSub > 0)
  begin
    if Charindex(@PCodSt,';10;30;70;') > 0
      begin
        if @PVlrIcm > 0
          if @PPerRedBasCalIcm > 0
            Set @PCodSt = '20'    -- tributacao com reducao
          else
            Set @PCodSt = '00'    -- tributacao integral
        else
          Set @PCodSt = '41'    -- nao tributada
      end
    Set @PCodCfo = @WCodCfoNor
    Set @PBasRecSbt = @PBasSub
    Set @PVlrRecSbt = @PVlrSub - @PVlrDst
    Set @PBasSub = 0 
    Set @PVlrSub = 0
    Set @PVlrDst = 0

    Update NFSIT
       Set Cod_Cfo = Case 
                       When (Cod_Cfo = 5910) or (Cod_Cfo = 6910) Then Cod_Cfo
                       Else @PCodCfo
                     End,
           Vlr_BasSubsTrib = Round(@PBasSub,2),
           Vlr_SubsTrib = @PVlrSub,
           Vlr_BasSbtRes = Round(@PBasRes,2),
           Vlr_SbtRes = @PVlrRes,
           Vlr_DscTri = @PVlrDst,
           Vlr_BasRecSbt = Round(@PBasRecSbt,2),
           Vlr_RecSbt = @PVlrRecSbt
     Where Cod_Estabe = @PCodEstab 
       And Ser_Nota = @PSerNot 
       And Num_Nota = @PNumNot And Cod_Produto = @PCodPrd 
       And Cod_Lote = @PCodLot And Num_SeqIte = @PNumSeqIte
  end

Commit Transaction
GO



